pub const Error = error{
    UnsupportedTarget,
    UnsupportedProgram,
    SemanticFactsInvalid,
    MissingMain,
    InvalidMainSignature,
    IntegerOutOfRange,
    RegisterExhausted,
    UndefinedName,
    DuplicateSymbol,
    UnknownSymbol,
    BranchOutOfRange,
    /// Relocatable-object or dylib request on Linux/aarch64, mapping to
    /// DNB012. The direct ELF writer only produces static executables.
    UnsupportedObjectFormat,
    /// Undefined symbols remain after lowering a static executable request,
    /// mapping to DNB013. A static image has no linker to satisfy them.
    UnresolvedExternals,
    /// An undefined symbol on the Windows/PE32+ path names nothing in the
    /// known import set (msvcrt/kernel32), mapping to DNB014. The PE writer
    /// never guesses a DLL for a symbol it does not know.
    UnknownImportSymbol,
} || std.mem.Allocator.Error;

/// Mach-O / ELF labels cannot contain `.`; DNIR keeps logical `Type.method` names.
fn linkerSymbolName(alloc: std.mem.Allocator, name: []const u8) Error![]const u8 {
    if (std.mem.indexOfScalar(u8, name, '.') == null) return try alloc.dupe(u8, name);
    return std.mem.replaceOwned(u8, alloc, name, ".", "_");
}

/// Pass 11 WP-02: structured direct-backend diagnostic.
pub const DirectDiag = struct {
    code: []const u8,
    message: []const u8,
};

/// Bootstrap projection from one realized application to emitted bytes.
/// Every semantic field is an exact id owned by the output's resident graph.
pub const MachineLineage = struct {
    relation: semantic_graph.id,
    target: semantic_graph.id,
    application: semantic_graph.id,
    value: semantic_graph.id,
    subject: ?semantic_graph.id,
    descriptor: native_types.ResolvedType,
    caller: semantic_graph.id,
    instruction_start: u32,
    instruction_end: u32,
    text_start: u32,
    text_end: u32,
    object_start: u32 = 0,
    object_end: u32 = 0,
};

pub const ObjectWithLineage = struct {
    bytes: []u8,
    lineage: []MachineLineage,
    /// Borrowed physical context for the ids in `lineage`.
    graph: *const semantic_graph.SemanticGraph,
    /// Physical undefined linker names (no leading `_`). Owned. Not semantic
    /// identity — the link line consumes these to select bootstrap objects.
    need: [][]const u8 = &.{},

    pub fn deinit(self: *ObjectWithLineage, alloc: std.mem.Allocator) void {
        alloc.free(self.bytes);
        alloc.free(self.lineage);
        for (self.need) |name| alloc.free(name);
        alloc.free(self.need);
    }
};

pub const AssemblyWithLineage = struct {
    assembly: []u8,
    machine: []u8,
    lineage: []MachineLineage,
    /// Borrowed physical context for the ids in `lineage`.
    graph: *const semantic_graph.SemanticGraph,

    pub fn deinit(self: *AssemblyWithLineage, alloc: std.mem.Allocator) void {
        alloc.free(self.assembly);
        alloc.free(self.machine);
        alloc.free(self.lineage);
    }
};

/// Caller-owned physical evidence for one native attempt. Lowering and backend
/// refusal evidence travel together without allocation or ambient state.
pub const Diagnostic = struct {
    site: ?std.builtin.SourceLocation = null,
    note_buffer: [64]u8 = undefined,
    note_len: u8 = 0,
    /// Exact application id when the refusal is about one occurrence.
    /// Null is unknown — never a sentinel zero.
    application: ?semantic_graph.id = null,
    /// Diagnostic projection of the occurrence's relation/method face.
    /// Borrowed from the resident graph or AST; not a second identity.
    relation: ?[]const u8 = null,
    lowering: dnir_lower.Diagnostic = .{},

    pub fn reset(self: *Diagnostic) void {
        self.site = null;
        self.note_len = 0;
        self.application = null;
        self.relation = null;
        self.lowering.reset();
    }

    pub fn bindOccurrence(
        self: *Diagnostic,
        graph: *const semantic_graph.SemanticGraph,
        occurrence: semantic_graph.id,
    ) void {
        self.application = occurrence;
        self.relation = occurrenceFace(graph, occurrence);
    }

    /// Take the lowering's occurrence AND its relation face TOGETHER.
    ///
    /// The occurrence alone was promoted here, which left the backend wrapper
    /// naming the lowering's application beside the backend's own absent
    /// relation, and `formatDirectCause` then patched the hole from the
    /// lowering — a borrow across two causes that were never checked to be the
    /// same one. THE OCCURRENCE IS WHAT DECIDES. Same occurrence and the two
    /// sides are describing one refusal, so the face completes it; a different
    /// occurrence is a different cause and nothing crosses.
    pub fn adoptLoweringCause(self: *Diagnostic) void {
        if (self.application) |bound| {
            const lowered = self.lowering.application orelse return;
            if (bound != lowered) return;
            if (self.relation == null) self.relation = self.lowering.relation;
            return;
        }
        if (self.relation != null) return;
        self.application = self.lowering.application;
        self.relation = self.lowering.relation;
    }

    pub fn remember(self: *Diagnostic, detail: []const u8) void {
        self.record(@src(), detail);
    }

    pub fn note(self: *const Diagnostic) ?[]const u8 {
        if (self.note_len == 0) return null;
        return self.note_buffer[0..self.note_len];
    }

    fn record(self: *Diagnostic, site: std.builtin.SourceLocation, detail: ?[]const u8) void {
        self.site = site;
        const text = detail orelse {
            self.note_len = 0;
            return;
        };
        const len = @min(text.len, self.note_buffer.len);
        @memcpy(self.note_buffer[0..len], text[0..len]);
        self.note_len = @intCast(len);
    }
};

fn occurrenceFace(graph: *const semantic_graph.SemanticGraph, entity: semantic_graph.id) ?[]const u8 {
    const node = graph.get(entity) orelse return null;
    // THE GRAPH IS ASKED FIRST. This read the SPELLING out of `ast_ref` and
    // only consulted the relation when there was no AST pointer, which inverts
    // the one law this whole file is enforcing: the graph knows which relation
    // an occurrence denotes, and the syntax only knows what was typed. They
    // differ exactly where it matters — `tokenizer = rule` then
    // `tokenizer(source)` resolves to relation `token`, and the spelling says
    // `tokenizer`, which `ApplicationFact.applied` exists to keep apart. A
    // refusal that names the applied binding instead of the relation sends the
    // reader to the wrong declaration.
    //
    // The syntax face remains, below, for the occurrence the graph could NOT
    // resolve — which is most of what this projection is asked about, and the
    // only case where a spelling is the best answer available.
    if (graph.applicationRelation(entity)) |relation_id| {
        if (graph.get(relation_id)) |relation| {
            if (relation.name) |name| return name;
        }
    }
    if (node.ast_ref) |raw| {
        const expr: *const ast.Expr = @ptrCast(@alignCast(raw));
        return switch (expr.*) {
            .call => |c| switch (c.func.*) {
                .name => |n| n.ident,
                .field => |f| f.field,
                else => node.name,
            },
            .method_call => |mc| mc.method,
            else => node.name,
        };
    }
    return node.name;
}

fn recordRefusal(diagnostic: *Diagnostic, src: std.builtin.SourceLocation) Error {
    diagnostic.record(src, null);
    return error.UnsupportedProgram;
}

/// Same treatment for the OTHER refusal error. `UndefinedName` means a slot or
/// temp had no register, and which one is the entire finding — exactly as
/// `UnknownSymbol` turned out to be two different problems wearing one code
/// once the symbol was printed.
/// Same as `undefinedAt` but for the keyed maps (fp_locals, fp_stack_slots,
/// locals), where the KEY is the finding rather than a slot number.
fn recordUndefinedKey(diagnostic: *Diagnostic, src: std.builtin.SourceLocation, kind: []const u8, key: []const u8) Error {
    diagnostic.site = src;
    const w = std.fmt.bufPrint(&diagnostic.note_buffer, "{s} '{s}' has no register", .{ kind, key }) catch {
        diagnostic.note_len = 0;
        return error.UndefinedName;
    };
    diagnostic.note_len = @intCast(w.len);
    return error.UndefinedName;
}

fn recordUndefinedAt(diagnostic: *Diagnostic, src: std.builtin.SourceLocation, kind: []const u8, id: u32) Error {
    diagnostic.site = src;
    const w = std.fmt.bufPrint(&diagnostic.note_buffer, "{s} {d} has no register", .{ kind, id }) catch {
        diagnostic.note_len = 0;
        return error.UndefinedName;
    };
    diagnostic.note_len = @intCast(w.len);
    return error.UndefinedName;
}

fn recordRefusalWith(diagnostic: *Diagnostic, src: std.builtin.SourceLocation, note: []const u8) Error {
    diagnostic.record(src, note);
    return error.UnsupportedProgram;
}

fn invalidFactsWith(diagnostic: *Diagnostic, src: std.builtin.SourceLocation, note: []const u8) Error {
    diagnostic.record(src, note);
    return error.SemanticFactsInvalid;
}

pub fn directDiagnostic(err: Error, target: []const u8) DirectDiag {
    _ = target;
    return switch (err) {
        error.UnsupportedTarget => .{ .code = "DNB004", .message = "target object format or host is unsupported by the direct backend" },
        error.UnsupportedObjectFormat => .{ .code = "DNB012", .message = "direct ELF writer emits static executables only; relocatable objects and shared libraries are not supported" },
        error.UnresolvedExternals => .{ .code = "DNB013", .message = "static executable has undefined symbols no linker will satisfy" },
        error.UnknownImportSymbol => .{ .code = "DNB014", .message = "PE writer cannot import external symbol: outside the known CRT/kernel32 set" },
        error.UnsupportedProgram => .{ .code = "DNB001", .message = "program construct is outside the direct backend subset" },
        error.SemanticFactsInvalid => .{ .code = "DNB011", .message = "required graph facts or realization lineage are missing or inconsistent" },
        error.MissingMain => .{ .code = "DNB006", .message = "direct native module has no eligible functions" },
        error.InvalidMainSignature => .{ .code = "DNB002", .message = "function signature incompatible with direct ARM64 ABI" },
        error.RegisterExhausted => .{ .code = "DNB003", .message = "register pressure exceeds direct backend spill capacity" },
        error.UndefinedName, error.UnknownSymbol => .{ .code = "DNB007", .message = "undefined symbol in direct backend lowering" },
        error.DuplicateSymbol => .{ .code = "DNB008", .message = "duplicate symbol in direct backend output" },
        error.BranchOutOfRange => .{ .code = "DNB009", .message = "branch relocation out of range" },
        error.IntegerOutOfRange => .{ .code = "DNB010", .message = "integer literal out of range for direct backend" },
        else => .{ .code = "DNB000", .message = "direct backend internal error" },
    };
}

/// ONE refusal, ONE cause, ALL THREE of its fields.
///
/// A compile carries two diagnostics — the backend's own and `diag.lowering` —
/// and these were three independent `orelse` choices across them: `missing`
/// preferred the lowering while `application` and `relation` preferred the
/// backend. A compile that recorded something on each side emitted the
/// occurrence of one refusal beside the missing fact of another, in one
/// sentence that reads as a single finding. That is the defect
/// `scripts/native_census.id` opens with — "one program, three causes, one
/// line of output" — reached by splicing instead of by check order, and worse,
/// because the spliced line describes a refusal that never happened.
///
/// THE SIDE THAT RECORDED THE REFUSAL OWNS THE CAUSE, and the backend's own
/// record wins whenever it has one. `diag.lowering` can hold a note from an
/// attempt lowering RECOVERED from — a `bail` some `tryLower…` caught and fell
/// back past — so a rule that simply prefers the lowering note promotes a
/// cause that did not happen. Measured on `examples/call_shape_demo.id`: the
/// backend refuses with `application-realization-count` while a stale
/// `missing-application-id` still sits on the lowering.
///
/// ONE OCCURRENCE MAY BE DESCRIBED BY BOTH SIDES, and completing it is not
/// splicing. `dnir_lower.applicationTarget` refuses occurrence 4 having bound
/// its face, and the backend wraps that refusal having bound the same
/// occurrence 4 with no face; the two halves are one cause and the equality of
/// the occurrence is the proof. A face is borrowed ONLY across that equality —
/// never to fill a hole in a cause the other side is not talking about.
const Cause = struct {
    missing: ?[]const u8 = null,
    application: ?semantic_graph.id = null,
    relation: ?[]const u8 = null,
};

fn selectedCause(diagnostic: ?*const Diagnostic) Cause {
    const diag = diagnostic orelse return .{};
    var cause: Cause = if (diag.note() != null or diag.application != null) .{
        .missing = diag.note(),
        .application = diag.application,
        .relation = diag.relation,
    } else .{
        .missing = diag.lowering.note(),
        .application = diag.lowering.application,
        .relation = diag.lowering.relation,
    };
    if (cause.relation == null) {
        if (cause.application) |occurrence| {
            if (diag.relation != null and diag.application != null and diag.application.? == occurrence) {
                cause.relation = diag.relation;
            } else if (diag.lowering.application != null and diag.lowering.application.? == occurrence) {
                cause.relation = diag.lowering.relation;
            }
        }
    }
    return cause;
}

/// `law.crash.first`: DNB001/DNB011 name application, missing fact, consumer, producer.
/// Category prose is the fallback when the attempt recorded no cause.
pub fn formatDirectCause(
    err: Error,
    target: []const u8,
    buf: []u8,
    diagnostic: ?*const Diagnostic,
) []const u8 {
    const d = directDiagnostic(err, target);
    const causal = err == error.SemanticFactsInvalid or err == error.UnsupportedProgram;
    if (!causal) {
        return std.fmt.bufPrint(buf, "{s}: {s}", .{ d.code, d.message }) catch d.message;
    }
    const cause = selectedCause(diagnostic);
    const missing = cause.missing;
    const application = cause.application;
    const relation = cause.relation;
    const producer: []const u8 = if (err == error.SemanticFactsInvalid)
        "graph"
    else
        "dnir lower";
    const miss = missing orelse "unspecified";
    if (application) |id| {
        if (relation) |rel| {
            return std.fmt.bufPrint(
                buf,
                "{s} application: {d} relation: {s} missing: {s} consumer: native realization producer: {s}",
                .{ d.code, id, rel, miss, producer },
            ) catch d.message;
        }
        return std.fmt.bufPrint(
            buf,
            "{s} application: {d} missing: {s} consumer: native realization producer: {s}",
            .{ d.code, id, miss, producer },
        ) catch d.message;
    }
    if (relation) |rel| {
        return std.fmt.bufPrint(
            buf,
            "{s} application: unknown relation: {s} missing: {s} consumer: native realization producer: {s}",
            .{ d.code, rel, miss, producer },
        ) catch d.message;
    }
    return std.fmt.bufPrint(
        buf,
        "{s} application: unknown missing: {s} consumer: native realization producer: {s}",
        .{ d.code, miss, producer },
    ) catch d.message;
}

pub fn formatDirectError(err: Error, target: []const u8, buf: []u8) []const u8 {
    return formatDirectCause(err, target, buf, null);
}

pub fn describeError(err: anyerror, target: []const u8, buf: []u8) []const u8 {
    return describeCause(err, target, buf, null);
}

pub fn describeCause(
    err: anyerror,
    target: []const u8,
    buf: []u8,
    diagnostic: ?*const Diagnostic,
) []const u8 {
    switch (err) {
        error.UnsupportedTarget,
        error.UnsupportedProgram,
        error.SemanticFactsInvalid,
        error.MissingMain,
        error.InvalidMainSignature,
        error.IntegerOutOfRange,
        error.RegisterExhausted,
        error.UndefinedName,
        error.DuplicateSymbol,
        error.UnknownSymbol,
        error.BranchOutOfRange,
        => return formatDirectCause(@errorCast(err), target, buf, diagnostic),
        error.OutOfMemory => return "out of memory",
        else => return @errorName(err),
    }
}

pub fn isNativeMachineTarget(target: []const u8) bool {
    return std.mem.eql(u8, target, "native-object") or
        std.mem.eql(u8, target, "native-mach-o") or
        std.mem.eql(u8, target, "native-asm") or
        std.mem.eql(u8, target, "native-exe") or
        std.mem.eql(u8, target, "native-dylib");
}

pub fn isNativeObjectTarget(target: []const u8) bool {
    return std.mem.eql(u8, target, "native-object") or
        std.mem.eql(u8, target, "native-mach-o");
}

pub fn isNativeAsmTarget(target: []const u8) bool {
    return std.mem.eql(u8, target, "native-asm");
}

pub fn isNativeExecutableTarget(target: []const u8) bool {
    return std.mem.eql(u8, target, "native-exe");
}

pub fn isNativeSharedTarget(target: []const u8) bool {
    return std.mem.eql(u8, target, "native-dylib");
}

/// Emit a graph-aware object together with the byte ranges of every DNIR
/// instruction that retained application facts. The symbol table remains a
/// physical linker projection; semantic correspondence is queried through this
/// sidecar, never reconstructed from symbol spelling.
pub fn emitObjectWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    target: []const u8,
    graph: *const semantic_graph.SemanticGraph,
) Error!ObjectWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitObjectWithGraphLineageObserved(alloc, mod, target, graph, &diagnostic);
}

pub fn emitObjectWithGraphLineageObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    target: []const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!ObjectWithLineage {
    diagnostic.reset();
    if (!isNativeObjectTarget(target)) return error.UnsupportedTarget;
    return emitObjectModeWithGraphLineage(alloc, mod, null, graph, diagnostic);
}

/// When `entry` is set the named zero-arg function
/// gets `fcvtzs x0, d0` on f64 returns so native executables receive an i64 exit code.
/// Which host the direct backend is running on, for the object/executable
/// dispatch. macOS/aarch64 keeps the Mach-O object path; Linux/aarch64 emits
/// static ELF64 executables directly; Windows/aarch64 emits PE32+
/// executables directly; anything else is a genuine DNB004 (unsupported
/// host). The parameterized form exists so the dispatch is unit-testable
/// without a Linux or Windows machine.
const NativeHost = enum { macos, linux, windows, unsupported };

fn nativeHostKindFor(os: std.Target.Os.Tag, arch: std.Target.Cpu.Arch) NativeHost {
    if (os == .macos and arch == .aarch64) return .macos;
    if (os == .linux and arch == .aarch64) return .linux;
    if (os == .windows and arch == .aarch64) return .windows;
    return .unsupported;
}

/// IDOL_PE_TARGET=1 forces the Windows ARM64 / PE32+ target on any AArch64
/// host. The fleet has no Windows hardware, so without this hatch the PE
/// writer and its lowering arms could never be exercised end to end; on
/// real Windows ARM64 hardware the host gate selects PE by itself and the
/// variable is unnecessary. This is a verification hatch, not a second
/// production route: the emitted image is the same one Windows hardware
/// would get.
fn peTargetForced() bool {
    return builtin.cpu.arch == .aarch64 and std.c.getenv("IDOL_PE_TARGET") != null;
}

pub fn nativeHostKind() NativeHost {
    if (peTargetForced()) return .windows;
    return nativeHostKindFor(builtin.os.tag, builtin.cpu.arch);
}

/// DNB013 refusal: a static executable has no linker to satisfy undefined
/// symbols, so report the count and the first few names instead of emitting
/// an image with dangling relocations.
fn recordUnresolvedExternals(diagnostic: *Diagnostic, src: std.builtin.SourceLocation, symbols: []const Symbol) Error {
    var count: usize = 0;
    for (symbols) |sym| {
        if (!sym.defined) count += 1;
    }
    diagnostic.site = src;
    const w = std.fmt.bufPrint(&diagnostic.note_buffer, "{d} undefined:", .{count}) catch {
        diagnostic.note_len = 0;
        return error.UnresolvedExternals;
    };
    var len: usize = w.len;
    var shown: usize = 0;
    for (symbols) |sym| {
        if (sym.defined) continue;
        if (shown >= 5) break;
        const piece = std.fmt.bufPrint(diagnostic.note_buffer[len..], " {s}", .{sym.name}) catch break;
        len += piece.len;
        shown += 1;
    }
    diagnostic.note_len = @intCast(len);
    return error.UnresolvedExternals;
}

pub fn emitObjectForExecutableWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: []const u8,
    graph: *const semantic_graph.SemanticGraph,
) Error!ObjectWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitObjectForExecutableWithGraphLineageObserved(alloc, mod, entry, graph, &diagnostic);
}

pub fn emitObjectForExecutableWithGraphLineageObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: []const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!ObjectWithLineage {
    diagnostic.reset();
    // The host gate lives in emitObjectModeWithGraphLineage so the object,
    // dylib, and executable entries share one dispatch.
    return emitObjectModeWithGraphLineage(alloc, mod, entry, graph, diagnostic);
}

pub fn emitSharedObjectInputWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
) Error!ObjectWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitSharedObjectInputWithGraphLineageObserved(alloc, mod, graph, &diagnostic);
}

pub fn emitSharedObjectInputWithGraphLineageObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!ObjectWithLineage {
    diagnostic.reset();
    return emitObjectModeWithGraphLineage(alloc, mod, null, graph, diagnostic);
}

fn emitObjectModeWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: ?[]const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!ObjectWithLineage {
    // One host gate shared by the object, dylib, and executable entries:
    // macOS/aarch64 keeps the Mach-O object path; Linux/aarch64 emits a
    // static ELF64 executable directly; Windows/aarch64 emits a PE32+
    // executable directly (DNB012 refuses the object/dylib request up front
    // on both direct-executable paths). Any other host is a genuine DNB004.
    const host = nativeHostKind();
    if (host == .unsupported) return error.UnsupportedTarget;
    if (host == .linux and entry == null) return error.UnsupportedObjectFormat;

    var output = try emitArm64ModuleWithGraph(alloc, mod, entry, graph, diagnostic);
    defer output.deinit(alloc);
    if (output.graph != graph) return invalidFactsWith(diagnostic, @src(), "object-graph-context");

    if (host == .linux) {
        const exe_entry = entry orelse return error.UnsupportedObjectFormat;
        // DNB013: a static executable has no linker to satisfy undefined
        // symbols. Refuse with the count and names instead of emitting an
        // image with dangling relocations.
        for (output.symbols) |sym| {
            if (!sym.defined) return recordUnresolvedExternals(diagnostic, @src(), output.symbols);
        }
        const bytes = try emitElfArm64StaticExec(
            alloc,
            output.text,
            output.cstring,
            output.const_data,
            output.symbols,
            output.relocations,
            output.data_relocations,
            output.bss_size,
            output.global_data,
            exe_entry,
        );
        errdefer alloc.free(bytes);
        const lineage = try alloc.dupe(MachineLineage, output.lineage);
        errdefer alloc.free(lineage);
        for (lineage) |*row| {
            row.object_start = @intCast(elfTextFileOffset() + row.text_start);
            row.object_end = @intCast(elfTextFileOffset() + row.text_end);
        }
        return .{
            .bytes = bytes,
            .lineage = lineage,
            .graph = graph,
            .need = &.{},
        };
    }

    if (host == .windows) {
        // PE32+: undefined symbols become imports (msvcrt/kernel32) — the
        // OS loader is the linker. Only the unimportable are refused, as
        // DNB014 inside the writer. Object/dylib requests are refused
        // exactly like the ELF path's DNB012: the writer emits executables
        // only.
        const exe_entry = entry orelse return error.UnsupportedObjectFormat;
        const bytes = try emitPeArm64StaticExec(
            alloc,
            output.text,
            output.cstring,
            output.const_data,
            output.symbols,
            output.relocations,
            output.data_relocations,
            output.bss_size,
            output.global_data,
            exe_entry,
        );
        errdefer alloc.free(bytes);
        const lineage = try alloc.dupe(MachineLineage, output.lineage);
        errdefer alloc.free(lineage);
        for (lineage) |*row| {
            row.object_start = @intCast(peTextFileOffset() + row.text_start);
            row.object_end = @intCast(peTextFileOffset() + row.text_end);
        }
        return .{
            .bytes = bytes,
            .lineage = lineage,
            .graph = graph,
            .need = &.{},
        };
    }

    const bytes = try emitMachOArm64ObjectWithConst(
        alloc,
        output.text,
        output.cstring,
        output.const_data,
        output.symbols,
        output.relocations,
        output.data_relocations,
        output.bss_size,
        output.global_data,
        output.cstring_coalescable,
    );
    errdefer alloc.free(bytes);

    const text_offset = machOTextOffset(output.cstring.len, output.const_data.len, output.bss_size);
    const lineage = try alloc.dupe(MachineLineage, output.lineage);
    errdefer alloc.free(lineage);
    for (lineage) |*row| {
        row.object_start = @intCast(text_offset + row.text_start);
        row.object_end = @intCast(text_offset + row.text_end);
    }
    var need = try std.ArrayListUnmanaged([]const u8).initCapacity(alloc, output.symbols.len);
    errdefer {
        for (need.items) |name| alloc.free(name);
        need.deinit(alloc);
    }
    for (output.symbols) |sym| {
        if (sym.defined) continue;
        need.appendAssumeCapacity(try alloc.dupe(u8, sym.name));
    }
    return .{
        .bytes = bytes,
        .lineage = lineage,
        .graph = graph,
        .need = try need.toOwnedSlice(alloc),
    };
}

pub fn emitAssemblyWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    target: []const u8,
    graph: *const semantic_graph.SemanticGraph,
) Error!AssemblyWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitAssemblyWithGraphLineageObserved(alloc, mod, target, graph, &diagnostic);
}

pub fn emitAssemblyWithGraphLineageObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    target: []const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!AssemblyWithLineage {
    diagnostic.reset();
    if (!isNativeAsmTarget(target)) return error.UnsupportedTarget;
    return emitAssemblyModeWithGraphLineage(alloc, mod, null, graph, diagnostic);
}

pub fn emitAssemblyForExecutableWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: []const u8,
    graph: *const semantic_graph.SemanticGraph,
) Error!AssemblyWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitAssemblyForExecutableWithGraphLineageObserved(alloc, mod, entry, graph, &diagnostic);
}

pub fn emitAssemblyForExecutableWithGraphLineageObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: []const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!AssemblyWithLineage {
    diagnostic.reset();
    return emitAssemblyModeWithGraphLineage(alloc, mod, entry, graph, diagnostic);
}

fn emitAssemblyModeWithGraphLineage(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: ?[]const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!AssemblyWithLineage {
    // Assembly text is host-independent lowering; the object/executable
    // writers pick the format. Open on Linux/aarch64 so --emit asm works
    // everywhere the ELF writer runs.
    if (nativeHostKind() == .unsupported) {
        return error.UnsupportedTarget;
    }
    var output = try emitArm64ModuleWithGraph(alloc, mod, entry, graph, diagnostic);
    errdefer output.deinit(alloc);
    if (output.graph != graph) return invalidFactsWith(diagnostic, @src(), "assembly-graph-context");
    const artifact: AssemblyWithLineage = .{
        .assembly = output.asm_text,
        .machine = output.text,
        .lineage = output.lineage,
        .graph = graph,
    };
    output.deinitExceptAssemblyMachineAndLineage(alloc);
    return artifact;
}

const Symbol = struct {
    name: []const u8,
    offset: u32,
    defined: bool = true,
    // Section index, 1-based over the sections this object actually emits:
    // 1 = __TEXT,__text, then __TEXT,__cstring and __TEXT,__const in that order
    // when they are non-empty. A promoted table's index is therefore not a
    // constant — `finish` stamps it once it knows whether any string exists.
    section: u8 = 1,
    external: bool = true, // n_ext bit for nlist; local string symbols set this false
};

const RelocKind = enum(u3) {
    branch26,
    page21,
    pageoff12,
    /// Absolute 64-bit address of a local symbol, emitted into __DATA,__data.
    /// A string-literal global initializer is a link-time address, so finish
    /// records one per initialized word and the writer serializes it as
    /// ARM64_RELOC_UNSIGNED.
    abs64,
};

/// A global word whose load-time content is a string's address.
const GlobalStrFixup = struct {
    word: u32, // index into global_words
    str_sym: u32, // interned __cstring symbol
};

const Relocation = struct {
    offset: u32,
    symbol_index: u32,
    kind: RelocKind = .branch26,
};

/// Sealed record descriptor lowered as consecutive f64 ABI slots (Pass 4 M1).
const F64RecordDesc = struct {
    field_names: []const []const u8,
};

const F64RecordMap = std.StringHashMapUnmanaged(F64RecordDesc);

const ScalFieldKind = enum { i64, str, f64 };

/// Record lowered as consecutive x-reg ABI slots (i64 / const char*).
const ScalRecordDesc = struct {
    field_names: []const []const u8,
    field_kinds: []const ScalFieldKind,
};

fn scalRecordReturnsIndirect(record: ScalRecordDesc, foreign: bool) bool {
    return dnir_lower.recordReturnIsIndirectFields(record.field_names.len, foreign);
}

const ScalRecordMap = std.StringHashMapUnmanaged(ScalRecordDesc);

fn freeF64Records(alloc: std.mem.Allocator, map: *F64RecordMap) void {
    map.deinit(alloc);
}

fn freeScalRecords(alloc: std.mem.Allocator, map: *ScalRecordMap) void {
    var it = map.iterator();
    while (it.next()) |entry| {
        alloc.free(entry.value_ptr.field_kinds);
    }
    map.deinit(alloc);
}

fn scalRecordDesc(records: *const ScalRecordMap, name: []const u8) ?ScalRecordDesc {
    return records.get(name);
}

fn f64RecordDesc(records: *const F64RecordMap, name: []const u8) ?F64RecordDesc {
    return records.get(name);
}

const Condition = enum(u4) {
    eq = 0x0,
    ne = 0x1,
    // UNSIGNED. `hi`/`ls` are not spellings of `gt`/`le` — they read the carry
    // flag, not the sign, which is what makes ONE compare answer a two-sided
    // range test: `(i - 1) <=u (len - 1)` is false for every i below 1 as well
    // as every i above len, because 0 - 1 wraps to the largest unsigned value.
    // No DNIR binop maps to either; they exist for the index bounds check.
    hi = 0x8,
    ls = 0x9,
    ge = 0xa,
    lt = 0xb,
    gt = 0xc,
    le = 0xd,
};

const Arm64Output = struct {
    text: []u8,
    asm_text: []u8,
    cstring: []u8 = &.{},
    /// Whether the literal blob may be handed to the linker as
    /// `S_CSTRING_LITERALS`.
    ///
    /// THE BLOB CANNOT ANSWER THIS ITSELF, which is the whole defect. Written
    /// out, one literal `"a\0b"` and two literals `"a"`, `"b"` are the SAME
    /// FOUR BYTES `61 00 62 00`; the boundary between literals is a fact the
    /// emitter holds and the byte stream does not carry. `S_CSTRING_LITERALS`
    /// invites ld to re-derive that boundary by splitting at every NUL, so it
    /// answered "two literals" and `Lduo_str_N` came out pointing at `a\0`
    /// with somebody else's string behind it. MEASURED before this field
    /// existed, `s = "a\0b"`: `s:byte(3)` was 108 — the `l` of the adjacent
    /// `len=%lld` format — where the same program on Wasm, whose data segment
    /// is not resplit, answered 98.
    ///
    /// So the section type states the fact: literals are coalescable only when
    /// none of them contains an interior NUL, and a module that has one keeps
    /// its blob in a plain `S_REGULAR` section that ld copies whole.
    cstring_coalescable: bool = true,
    /// Bytes of `__TEXT,__const` — determined positional tables that became
    /// read-only data instead of being built word by word at run time.
    ///
    /// NOT `__cstring`, AND NOT `__text`. `__cstring` is `S_CSTRING_LITERALS`:
    /// the linker splits and dedups it at NUL bytes, and a table of i64 literals
    /// is full of them, so a blob put there would be silently corrupted. `__text`
    /// would make the data count as INSTRUCTIONS under `otool -tV`, corrupting
    /// every measurement on this surface — the collapse gate, the perf baseline,
    /// the frontier rows. `S_REGULAR` in its own section is the only placement
    /// that is neither.
    const_data: []u8 = &.{},
    symbols: []Symbol,
    relocations: []Relocation,
    /// Data-section relocations (RelocKind.abs64) for __DATA,__data.
    data_relocations: []Relocation = &.{},
    lineage: []MachineLineage = &.{},
    /// Borrowed physical context for the ids in `lineage`.
    graph: ?*const semantic_graph.SemanticGraph = null,
    /// Published applications with a KNOWN-ABSENT realization — the ones inside
    /// relations that were folded to their compile-time answer, so no machine
    /// text exists for them to be attributed to. Carried here because
    /// `validateMachineLineage` is handed this output and not the DNIR module
    /// the fold was recorded on, and it is computed by the SAME helper the DNIR
    /// check uses (`unrealizedApplicationCount`) so the two cannot disagree.
    unrealized: usize = 0,
    /// Bytes of the module-global arena. 0 means the section is not emitted at
    /// all, which is the pre-arena behavior verbatim.
    bss_size: u64 = 0,
    /// The arena's LOAD-TIME CONTENT, when any word of it is non-zero. Empty
    /// means every word is zero and the arena is realized as `__DATA,__bss`
    /// zerofill — no file bytes at all. Non-empty means `__DATA,__data` at the
    /// same address with these bytes, and `global_data.len == bss_size`.
    ///
    /// This is what makes `global G: i64 = 7` correct in a LIBRARY. The
    /// initializer used to be a store emitted into the entry prologue, and an
    /// object has no entry, so `--emit obj` and `--emit dylib` silently started
    /// every module global at zero.
    global_data: []u8 = &.{},
    cost: []CostEntry = &.{},

    fn deinit(self: *Arm64Output, alloc: std.mem.Allocator) void {
        alloc.free(self.text);
        alloc.free(self.asm_text);
        if (self.cstring.len > 0) alloc.free(self.cstring);
        if (self.const_data.len > 0) alloc.free(self.const_data);
        if (self.global_data.len > 0) alloc.free(self.global_data);
        for (self.symbols) |sym| alloc.free(sym.name);
        alloc.free(self.symbols);
        alloc.free(self.relocations);
        alloc.free(self.data_relocations);
        if (self.lineage.len > 0) alloc.free(self.lineage);
        for (self.cost) |entry| alloc.free(entry.reason);
        if (self.cost.len > 0) alloc.free(self.cost);
    }

    fn deinitExceptAssembly(self: *Arm64Output, alloc: std.mem.Allocator) void {
        alloc.free(self.text);
        if (self.cstring.len > 0) alloc.free(self.cstring);
        if (self.const_data.len > 0) alloc.free(self.const_data);
        if (self.global_data.len > 0) alloc.free(self.global_data);
        for (self.symbols) |sym| alloc.free(sym.name);
        alloc.free(self.symbols);
        alloc.free(self.relocations);
        if (self.lineage.len > 0) alloc.free(self.lineage);
    }

    fn deinitExceptAssemblyMachineAndLineage(self: *Arm64Output, alloc: std.mem.Allocator) void {
        if (self.cstring.len > 0) alloc.free(self.cstring);
        if (self.const_data.len > 0) alloc.free(self.const_data);
        for (self.symbols) |sym| alloc.free(sym.name);
        alloc.free(self.symbols);
        alloc.free(self.relocations);
    }
};

fn isFloatAnnotation(t: ast.TypeExpr) bool {
    return t.is_float(); // named == "f32" or "f64"
}

fn returnsFloat(t: ast.TypeExpr) bool {
    return isFloatAnnotation(t);
}

/// Zero-arg i64/void/f64 module function suitable as a native executable entry.
/// f64 entries coerce to i64 exit codes at link time via `fcvtzs x0, d0`.
///
/// ONE DEFINITION, in `ast.zig`, because the SAME predicate decides which
/// relation owns the bare process symbol (`Module.sourceProcessEntry`) and
/// which relation `--entry` may point a link line at. A second copy here is how
/// those two answers stop agreeing.
fn isZeroArgEntryFunction(fd: *const ast.FuncDecl) bool {
    return fd.processEntryEligible();
}

fn findModuleFunction(mod: *const ast.Module, name: []const u8) ?*const ast.FuncDecl {
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (fd.path.len == 1 and std.mem.eql(u8, fd.path[0], name)) return fd;
    }
    return null;
}

/// Semantic process-entry selection. The physical root and a source relation
/// named `main` are different identities even though older paths represented
/// both with the text `main`.
pub const ProcessEntry = union(enum) {
    /// The module program: file-scope execution and its tail result.
    root: semantic_graph.id,
    /// An ordinary source relation selected explicitly or by compatibility.
    relation: semantic_graph.id,
};

pub const ProcessEntryError = error{
    /// An explicit source spelling did not resolve to an eligible relation.
    InvalidProcessEntry,
    /// The source, root, or relation did not belong to this graph.
    SemanticFactsInvalid,
};

fn relationProcessEntry(
    graph: *const semantic_graph.SemanticGraph,
    declaration: *const ast.FuncDecl,
) ProcessEntryError!?ProcessEntry {
    const relation = graph.relationForDeclaration(declaration) orelse
        return error.SemanticFactsInvalid;
    const linkage = graph.callableLinkage(relation) orelse
        return error.SemanticFactsInvalid;
    if (linkage.exposure == .c_import) return null;
    return .{ .relation = relation };
}

/// Select the semantic process entry after graph lift.
///
/// An explicit request resolves to the exact relation id. Without one, a
/// module program is authoritative and wins over every compatibility relation,
/// including a source relation spelled `main`. Only a body-less module retains
/// the historical export / named-main / sole-zero-arg inference ladder.
pub fn selectProcessEntry(
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
    root: semantic_graph.id,
    want: ?[]const u8,
) ProcessEntryError!?ProcessEntry {
    const graph_root = graph.rootForModule(mod) orelse return error.SemanticFactsInvalid;
    if (root != graph_root) return error.SemanticFactsInvalid;
    if (want) |name| {
        const fd = findModuleFunction(mod, name) orelse return error.InvalidProcessEntry;
        if (!isZeroArgEntryFunction(fd)) return error.InvalidProcessEntry;
        return (try relationProcessEntry(graph, fd)) orelse error.InvalidProcessEntry;
    }
    if (mod.program()) return .{ .root = graph_root };

    var sole: ?ProcessEntry = null;
    var sole_count: usize = 0;
    var named_main: ?ProcessEntry = null;

    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (!isZeroArgEntryFunction(fd)) continue;

        const selected = (try relationProcessEntry(graph, fd)) orelse continue;
        if (std.mem.eql(u8, fd.path[0], "main")) named_main = selected;
        const linkage = graph.callableLinkage(selected.relation) orelse
            return error.SemanticFactsInvalid;
        if (linkage.exposure != .internal) return selected;
        sole = selected;
        sole_count += 1;
    }
    if (named_main) |selected| return selected;
    if (sole_count == 1) return sole.?;
    return null;
}

/// Physical linker symbol for one already-selected semantic entry. The root is
/// the ABI-owned `main`; an ordinary relation, even one named `main`, follows
/// the same home/linkage law as every other source relation.
pub fn processEntrySymbol(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    entry: ProcessEntry,
) Error![]const u8 {
    return switch (entry) {
        .root => |entity| blk: {
            if (!graph.isModuleRoot(entity)) return error.SemanticFactsInvalid;
            break :blk try alloc.dupe(u8, "main");
        },
        .relation => |entity| blk: {
            const linkage = graph.callableLinkage(entity) orelse
                return error.SemanticFactsInvalid;
            break :blk try alloc.dupe(u8, linkage.symbol);
        },
    };
}

pub const CostKind = enum {
    extern_call,
    string_intern_hash,
    spill,
    stack_local,
};

pub const CostEntry = struct {
    kind: CostKind,
    reason: []const u8,
};

pub const CostLedger = struct {
    entries: std.ArrayList(CostEntry) = .empty,

    pub fn deinit(self: *CostLedger, alloc: std.mem.Allocator) void {
        for (self.entries.items) |entry| alloc.free(entry.reason);
        self.entries.deinit(alloc);
    }

    pub fn record(self: *CostLedger, alloc: std.mem.Allocator, kind: CostKind, reason: []const u8) !void {
        try self.entries.append(alloc, .{
            .kind = kind,
            .reason = try alloc.dupe(u8, reason),
        });
    }
};

/// GP value registers the allocator may hand out: x9–x17 (nine — x18 is Apple's
/// reserved platform register) and x19–x28 (ten).
const gp_allocatable: u32 = 19;
/// Registers held back from long-lived homes so every instruction has somewhere
/// to compute. Five is what a record store-and-index sequence peaks at.
const gp_scratch_floor: u32 = 5;

const Arm64Compiler = struct {
    alloc: std.mem.Allocator,
    diagnostic: *Diagnostic,
    f64_records: *const F64RecordMap,
    scal_records: *const ScalRecordMap,
    record: []const dnir.RecordDesc = &.{},
    code: std.ArrayList(u8) = .empty,
    asm_text: std.ArrayList(u8) = .empty,
    symbols: std.ArrayList(Symbol) = .empty,
    extern_symbols: std.StringHashMapUnmanaged(u32) = .empty,
    relocations: std.ArrayList(Relocation) = .empty,
    lineage: std.ArrayList(MachineLineage) = .empty,
    call_patches: std.ArrayList(CallPatch) = .empty,
    used_regs: [29]bool = @splat(false),
    returned: bool = false,
    strings: std.ArrayList(StringSymbol) = .empty,
    string_map: std.StringHashMapUnmanaged(u32) = .empty,
    next_string: u32 = 0,
    /// What the SOURCE facts permit to become read-only data. Borrowed; empty
    /// when the caller had no source module in hand, and an empty licence
    /// promotes nothing, so every DNIR-only entry point keeps today's emission
    /// byte for byte.
    const_licence: ?*const const_table.Licence = null,
    /// True when this compilation targets Windows ARM64 (PE32+): set once
    /// from `nativeHostKind()` at construction. The trap, depth-fault, and
    /// depth-limit lowering arms read it. False on every existing path, so
    /// macOS and Linux emission are untouched by its presence.
    target_windows: bool = false,
    /// The resident graph this DNIR projection carries coordinates into, when
    /// it carries any. W8 (two-sided if-conversion) reads `ApplicationFact`
    /// from here rather than re-deriving effect from instruction shape; a null
    /// graph is "no fact published", which is a refusal and not a licence.
    graph: ?*const semantic_graph.SemanticGraph = null,
    /// Why the last two-sided if-conversion candidate was refused, for the
    /// census `IDOL_IFCONV_REPORT` prints. Purely diagnostic.
    ifconv_refusal: []const u8 = "",
    ifconv_admitted: u32 = 0,
    ifconv_refused_trap: u32 = 0,
    ifconv_refused_effect_unknown: u32 = 0,
    ifconv_refused_lineage: u32 = 0,
    ifconv_refused_diverge: u32 = 0,
    /// OF `ifconv_refused_diverge`, HOW MANY WERE ALREADY REFUSED ANYWAY.
    ///
    /// A missing fact only costs something when it is the LAST thing standing
    /// between a candidate and its transform. `no-termination-fact` fires
    /// before the lineage rule below, so the census cannot tell "termination is
    /// what blocks this" from "termination fires first and something else would
    /// have refused regardless". This counts the second case, and it is the
    /// number that decides whether publishing a termination fact would change a
    /// single decision. See `gate/speculation.sh`.
    ifconv_refused_diverge_masked: u32 = 0,
    /// UNDER `IDOL_TERMINATION_ASSUME=1` ONLY: arms that reached the END of the
    /// admission chain carrying an assumed-terminating call. This is the number
    /// a termination producer would be worth, and it is measured WITHOUT the
    /// compiler ever admitting one — see `terminationAssumed`.
    ifconv_termination_would_admit: u32 = 0,
    /// Per-arm: this chain contains a call that only got past the termination
    /// ground because the control assumed it away. Reset at the top of
    /// `ifConvArmChainAdmissible`; it makes the successful return REFUSE.
    ifconv_assumed_call: bool = false,
    ifconv_refused_cap: u32 = 0,
    ifconv_refused_latency: u32 = 0,
    ifconv_candidates: u32 = 0,
    ifconv_trace: bool = false,
    /// First value id past everything the function being compiled uses. W8's
    /// select needs a carrier id that belongs to no local and no temp; see
    /// `emitIfConvertedTwoSided`.
    synth_value_next: u32 = 0,
    /// Promoted tables of the function being compiled: `alloc_slots` result temp
    /// -> the `__TEXT,__const` symbol its base address relocates against.
    /// Cleared per function.
    const_bases: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    /// Graph aggregate identity -> immutable `__TEXT,__const` symbol. DNIR
    /// function plans project that semantic identity onto their local base
    /// temp; no source binding name or table AST is consulted here.
    graph_const_bases: std.AutoHashMapUnmanaged(semantic_graph.id, u32) = .empty,
    /// The module's `__TEXT,__const` payload, one i64 word per entry.
    const_words: std.ArrayList(i64) = .empty,
    const_tables: std.ArrayList(ConstTableSymbol) = .empty,
    next_const: u32 = 0,
    /// A WRITTEN module-scope binding is ONE storage location, and this is where
    /// it lives: one 8-byte `__DATA,__bss` word per name, module-wide.
    ///
    /// It had none. The native-scalar profile gave a file-scope binding no
    /// storage at all — every function body treated the name as its own
    /// register-resident local re-materialized from the initializer — so a write
    /// landed nowhere the next read could see. Measured against `--backend=c` on
    /// the two fixtures that record it:
    ///
    ///     g066  for i = 1,3 / total = total + i   direct 0 5 (exit 0)   c 6 5 (exit 6)
    ///     g108  main writes 8, show() reads       direct 8 5            c 8 8
    ///
    /// Exit 0 both times, `ok compile` both times, no diagnostic. The
    /// `mod-global-written:` precheck refused that miscompile while this map
    /// could not answer; the map now answers every read, so the precheck is
    /// DELETED (2026-08-18) and both fixtures are promoted into the differential
    /// corpus proper with the C column's answers.
    ///
    /// `__DATA,__bss` and not `__TEXT,__const`: the whole point is that it is
    /// WRITABLE. Zerofill costs no file bytes, and a non-zero initializer is not
    /// lost by that — a module-scope initializer is an executable statement, so
    /// it is emitted as a store like any other write.
    ///
    /// Keys are borrowed from the DNIR instruction's `.field`, which outlives the
    /// compile, exactly as `string_map` borrows its content.
    globals: std.StringHashMapUnmanaged(u32) = .empty,
    /// Symbol indices in word order: position `i` owns bss word `i`.
    global_syms: std.ArrayList(u32) = .empty,
    /// WHAT EACH WORD HOLDS BEFORE ANYTHING RUNS, published by DNIR lowering as
    /// `dnir.Module.globals`. Name -> the raw 8 bytes of the initial value.
    ///
    /// Only NON-ZERO entries are here. A zero word is what a zerofill section
    /// already is, so the absence of an entry IS the representation of zero
    /// (`HPLS.md` §31) and a module with nothing but zero initializers emits the
    /// same `__DATA,__bss` bytes it always did.
    global_init: std.StringHashMapUnmanaged(u64) = .empty,
    /// String-literal initializers for globals: global name -> interned
    /// __cstring symbol. Populated by compileDnirModule (which interns the
    /// literal); internGlobal records the word index when storage is
    /// allocated. The word's load-time content is the string's address.
    global_str_inits: std.StringHashMapUnmanaged(u32) = .empty,
    /// Words whose load-time content is a string address, in allocation order.
    /// finish emits a data-section relocation for each.
    global_str_fixups: std.ArrayListUnmanaged(GlobalStrFixup) = .empty,
    /// Data-section relocations (RelocKind.abs64), recorded by finish and
    /// serialized by the Mach-O writer into __DATA,__data's relocation list.
    data_relocations: std.ArrayListUnmanaged(Relocation) = .empty,
    /// Initial word content in WORD ORDER, appended by `internGlobal` alongside
    /// `global_syms` so the two can never drift. `finish` writes these as the
    /// section payload.
    global_words: std.ArrayList(u64) = .empty,
    // f64 native emission: per-function physical FP state. FP params arrive
    // in d0-d7 (caller-saved) and the result returns in d0.
    cur_func_float: bool = false,
    /// Function returns f64 but is not a pure-f64 kernel (zero-param shell, etc.).
    cur_func_ret_float: bool = false,
    /// The function's DECLARED return type. `cur_func_float` is derived from
    /// parameters alone (`f64AbiParamSlots`), so on its own it cannot answer
    /// what a `ret` should do — see the `.ret` arm.
    cur_func_ret: native_types.ResolvedType = .any,
    cur_func_name: ?[]const u8 = null,
    /// Every function in the module being compiled, borrowed for the length of
    /// `compileDnirModule`. §12 TAIL needs the CALLEE's declaration to decide
    /// whether a call in tail position may reuse this frame — its return
    /// descriptor, its result convention, and how many argument slots it reads
    /// — and a caller cannot answer any of those from the call site. Empty
    /// means "no module in hand" (the DNIR-only entry points and the unit
    /// tests), and an empty roster admits no tail call at all, so those paths
    /// keep today's emission byte for byte.
    cur_module_functions: []const dnir.Function = &.{},
    /// SEVERING CONTROL for §12 TAIL. `IDOL_NO_TAILCALL=1` restores the
    /// `bl`-then-epilogue emission for every call in tail position. Read once
    /// per process; `main.behaviourEnvClass` treats any `IDOL_*` this compiler
    /// reads as `.affects`, so the two arms decline each other's build cache.
    tailcall: bool = true,
    /// Calls this compilation realized as a jump rather than a frame. Census
    /// only — `IDOL_TAILCALL_REPORT` prints it.
    tailcall_admitted: u32 = 0,
    /// Census for `IDOL_PROBE_CENSUS`: how many functions were compiled,
    /// how many throwaway probe compilations that took, how many ladder
    /// descents, and the plan-class breakdown. Purely diagnostic.
    probe_census_functions: u32 = 0,
    probe_census_probes: u32 = 0,
    probe_census_descents: u32 = 0,
    probe_census_plan_zero: u32 = 0,
    probe_census_plan_all: u32 = 0,
    probe_census_plan_partial: u32 = 0,
    probe_census_call_plan0: u32 = 0,
    probe_census_call_non0: u32 = 0,
    probe_census_leaf_plan0: u32 = 0,
    probe_census_leaf_non0: u32 = 0,
    probe_census_singlepass: u32 = 0,
    probe_census_fallback: u32 = 0,
    /// Sites of callee-saved `str`/`ldr` pairs from the current single-pass
    /// attempt, so the pairs for untouched registers can be nop'd once
    /// `callee_touched` is known. Cleared at each attempt; read only on the
    /// fast path. Recorded in `emitSaveCalleeRegs`/`emitRestoreCalleeRegs`.
    callee_save_sites: std.ArrayList(CalleeSaveSite) = .empty,
    /// When set, `compileDnirFunction` skips recording the function symbol;
    /// the single-pass driver records it after a successful attempt, so a
    /// rewound attempt leaves no stale symbol behind.
    defer_func_symbol: bool = false,
    /// SEVERING CONTROL for §12 `error.depth`. `IDOL_NO_DEPTH=1` restores the
    /// unmetered prologue — and with it the SIGSEGV — for every function.
    /// Read the same way and for the same reason as `tailcall`.
    depth_meter: bool = true,
    /// The module functions whose prologue meters the stack, by name. Computed
    /// ONCE per module in `compileDnirModule` from the DNIR call graph, so the
    /// probe pass and the real pass are handed the SAME answer and emit the
    /// same bytes — the premise `probeCalleeSaveUse` is built on.
    depth_metered_names: std.StringHashMapUnmanaged(void) = .empty,
    /// Whether the function about to be compiled is one of them. Set by
    /// `compileDnirModule` from the map above and COPIED INTO THE PROBE, so the
    /// two passes emit the same prologue. Every other entry point into
    /// `compileDnirFunction` — object mode, the DNIR-only unit tests — leaves it
    /// false and keeps today's emission byte for byte; none of them has an entry
    /// to run the initializer either, so a check there would test a zero limit.
    next_func_metered: bool = false,
    /// Whether ANY function in this module is metered. A module that meters
    /// nothing emits no initializer either, so its artifact is byte for byte
    /// what it is today.
    depth_module_meters: bool = false,
    /// Functions this compilation metered. Census only — `IDOL_DEPTH_REPORT`.
    depth_metered_count: u32 = 0,
    /// The `__DATA,__bss` word holding the lowest `sp` a metered prologue may
    /// stand on, interned on first demand. ZERO IS THE DISABLED VALUE and it is
    /// what a zerofill word already holds: `sp` is never zero, so a module whose
    /// entry never ran the initializer (object mode, a library, a unit test)
    /// takes the in-range branch every time and behaves exactly as it does now.
    depth_limit_sym: ?u32 = null,
    /// When set, this function's f64 return is coerced to i64 for process exit.
    entry: ?[]const u8 = null,
    cur_func_ret_record: ?ScalRecordDesc = null,
    cur_func_ret_pack: []const native_types.ResolvedType = &.{},
    cur_func_ret_f64_record: ?F64RecordDesc = null,
    /// Where this function parked the AAPCS64 indirect-result pointer it was
    /// handed in x8. Set when `dnir_lower.recordReturnIsIndirectFields` says this
    /// record crosses THIS function's boundary indirectly — the argument register
    /// file for an internal relation, 16 bytes for one that declared itself to C.
    /// x8 is caller-saved, so a body containing any call would lose it;
    /// `emitSaveCallerRegs` preserves x9..x28, which is why the pointer moves
    /// there on entry rather than being read at `ret`.
    cur_ret_indirect_reg: ?u5 = null,
    /// Does the function being compiled answer on C's convention? Set from
    /// `dnir.Function.foreign_boundary`, which reads the same `@comp.c.export` /
    /// `@ffi` declaration that names the exported symbol.
    cur_func_foreign: bool = false,
    /// Backing store for `dnirRetRecordVals`'s lhs/rhs/third fallback.
    ret_record_scratch: [3]dnir.Value = @splat(.void),
    fp_locals: std.StringHashMapUnmanaged(u5) = .empty,
    /// Which `temps` entries hold an FP register. `temps` is ONE map for two
    /// register files and the reader picks the file, which worked only by
    /// numeric accident: GP values came from x9-x28 and FP values from d0-d7,
    /// so a register number implied its file. Moving FP values to d16-d30 (to
    /// get them out of the argument-staging range) made the ranges overlap and
    /// the accident vanished — `i < 100` began emitting `fcmp d10, d18` against
    /// x10's number. See gap[058].
    fp_temps: std.AutoHashMapUnmanaged(u32, void) = .empty,
    used_fp_regs: [32]bool = @splat(false),
    /// LIVENESS for the FP value range. `releaseFpReg` was a no-op, so
    /// allocation was a monotonic cursor and every float loop walked off the
    /// end of the pool; the standing answer was to raise the pool size, which
    /// converted honest DNB003 refusals into hangs twice (gap[057]).
    ///
    /// Three facts make a release safe:
    ///   * `fp reg owner` — which DNIR id currently reads out of this register.
    ///     A register with an owner is not scratch and cannot be handed back by
    ///     an operand-release at the point of use.
    ///   * `fp home regs` — this register is a LOCAL's home. A local keeps one
    ///     register for its whole lifetime, so a home is never freed.
    ///   * `value free at` — the last instruction index that READS an id, extended
    ///     across any enclosing back edge. Freeing on the last TEXTUAL use is
    ///     wrong inside a loop: a value defined before the loop and last read
    ///     inside it is read again on the next iteration, after the reuse has
    ///     already clobbered the register.
    fp_reg_owner: [32]?u32 = @splat(null),
    fp_home_regs: [32]bool = @splat(false),
    /// GP temp ownership and local homes — same contract as the FP fields above.
    gp_reg_owner: [32]?u32 = @splat(null),
    gp_home_regs: [32]bool = @splat(false),
    /// The callee-bank homes THIS change hands out (`allocHomeReg`), and the one
    /// thing that must never happen to them: being spilled.
    ///
    /// `spillReg` clears `used_regs` and records the victim in `spilled_regs`;
    /// `ensureRegLiveRemap` then reloads into a DIFFERENT register and rewrites
    /// `temps` — but NOT `pinned`, which is the map `evalDnirValue` consults
    /// FIRST for a local. Spill a local's home and its pinned entry goes on
    /// naming a register whose value has moved, so the next read of that local
    /// returns whatever was allocated into the vacancy.
    ///
    /// MEASURED, and it is a WRONG ANSWER rather than a refusal: `sha.id`
    /// answered 0 instead of 16 — both `sb()` and `mb()`, ~20 locals and three
    /// memory-backed tables each, every NIST digest word wrong — while
    /// `native.id` fell from 210 agreements to 128.
    ///
    /// Refusing instead is free HERE and only here: a calling function that
    /// cannot allocate makes `probeFunctionPlan` step down the ladder, and the
    /// bottom rung is zero homes, i.e. exactly the frame-slot behaviour that
    /// preceded this change. Leaf homes are NOT in this set and keep spilling as
    /// they always have; the same latent hazard exists there and is older than
    /// this change, but a leaf has no ladder to fall back on and taking its
    /// spill victims away would refuse programs that compile today.
    gp_call_home_regs: u32 = 0,
    /// Argument registers (x0..x7) already STAGED for the call currently being
    /// marshaled. A multi-argument call stages a2→x0, a1→x1, … in order; a later
    /// argument whose operand must be LOADED needs a scratch register, and once
    /// x9..x28 are exhausted `allocRegExcluding` falls back into x0..x7 — handing
    /// out a low register that already holds a staged earlier argument. That
    /// clobbers the earlier arg silently (the callee then reads x0 = q instead of
    /// a2), a wrong answer rather than a refusal. Each bit set here is a staged
    /// arg register that must not be reallocated as scratch until the `bl`
    /// consumes it; `emitBl` clears the mask. Zero outside argument marshaling,
    /// so it never perturbs code that is not staging a call.
    pending_arg_regs: u8 = 0,
    /// How many locals may keep a REGISTER home for the whole function.
    ///
    /// This has to be smaller than the pool, and it was not: x9–x17 and x19–x28
    /// are nineteen allocatable registers (x18 is Apple's reserved platform
    /// register), and the budget was twenty. Every instruction also needs
    /// scratch, so a body that actually claimed its allowance had nothing left
    /// to compute with and refused DNB003.
    ///
    /// It never showed, because the budget is only consulted when locals are NOT
    /// all being spilled — that is, in a function with no call — and until the
    /// bounds trap stopped being `call_extern abort` a function that indexed a
    /// table dynamically was a "caller" and never reached this path. A
    /// twenty-element select-chain loop is the smallest program that does:
    /// leaf, ~20 locals, and it went straight from 33 to DNB003.
    ///
    /// Gate transport raises it (`m.graph.gateTransportModule()`), which is safe
    /// for the same structural reason: those bodies call `gatecap`, so their
    /// locals are stack-homed and this number is never read.
    gp_local_home_budget: u32 = gp_allocatable - gp_scratch_floor,
    /// How many GP locals a function THAT CALLS may keep in registers.
    ///
    /// At most ten, because that is how many registers AAPCS64 makes a caller's
    /// to keep: x19–x28. A home in that bank survives `bl` by the callee's
    /// obligation, so it needs neither a frame slot nor a save-set entry, and
    /// the carried local it holds costs one `mov` per assignment instead of a
    /// `str` and an `ldr`. Above the budget the surplus still goes to the frame,
    /// exactly as before.
    ///
    /// SET PER FUNCTION, BY MEASUREMENT — see `probeFunctionPlan`. Ten is the
    /// ceiling, not the answer: a home is a register held for the whole body, so
    /// a body with heavy expression pressure compiles at four homes and refuses
    /// with DNB003 at ten. `sha.id` and `tree.id` are both that shape.
    gp_call_home_budget: u32 = callee_save_count,
    cur_loop_ranges: std.ArrayList([2]u32) = .empty,
    spill_frame_budget: u16 = 65520,
    /// Gate/ledger transport: allow reclaiming spilled temp registers when the
    /// pool is exhausted instead of refusing with DNB003.
    gate_transport: bool = false,
    /// Param slot count for the function being compiled; used to stack-spill
    /// incoming str/any params in gate transport (x0-x7 do not survive gatecap).
    gate_param_slots: u32 = 0,
    /// Active `pinned` map while lowering one function; `evalDnirValue` consults
    /// it before `temps` so gatecap cannot serve stale register homes.
    eval_pinned: ?*const std.AutoHashMapUnmanaged(u32, u5) = null,
    /// Active `temps` map while lowering one function. A call or pack result
    /// the ABI left in x0..x7 is recorded HERE AND NOWHERE ELSE: every write to
    /// `gp_reg_owner` skips `r < 9`, so `temps` is that value's only location
    /// record and the only fact that answers whether a frame slot is still read.
    eval_temps: ?*std.AutoHashMapUnmanaged(u32, u5) = null,
    /// Flat index of the DNIR instruction currently being emitted. Rebound at
    /// every compileDnirInstr entry (nested collapsed-window calls pass at
    /// through) so releaseReg reads the right index in all emission paths.
    /// releaseReg reads it to protect a live temp's x0..x7 register.
    cur_emit_idx: u32 = 0,
    cur_func_has_call: bool = false,
    /// Last instruction that reads each DNIR value/slot id. The map is shared
    /// by both register files; physical file selection is a separate fact.
    value_free_at: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    /// Pre-mask temps elided by the ubfx pre-mask peephole (see
    /// `ubfxPremaskElidable`): maps the elided `band` result temp to the
    /// band's non-mask operand, which the fused `ubfx` reads directly.
    /// Cleared per function with the rest of the register state.
    premask_elided: std.AutoHashMapUnmanaged(u32, dnir.Value) = .empty,
    /// Value ids with a READ THIS COMPILER CANNOT ATTRIBUTE to the definition
    /// immediately before it. See `computeTightReads`, which fills it, and
    /// `singleReaderByTightDef`, which is the only thing that asks.
    loose_read_values: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Census `IDOL_TIGHTDEF_REPORT` prints: compare/branch pairs the tight-def
    /// fact admitted that `value_free_at` alone refused.
    tightdef_admitted: u32 = 0,
    /// SEVERING CONTROL for the tight-def fact. `IDOL_NO_TIGHTDEF=1` restores
    /// the `value_free_at`-only test. Any `IDOL_*` name this compiler reads is
    /// `.affects` by default in `main.behaviourEnvClass`, so setting it to `0`
    /// on the other arm declines the build cache on BOTH sides and neither arm
    /// can be handed the other's artifact.
    tightdef: bool = true,
    fp_abi_passthrough: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Loop-invariant immediate hoisting (FTCFTW debt (1); GAP-172 / GAP-169).
    /// A `.i64` constant used inside a loop is otherwise re-materialized by a
    /// fresh `mov`/`movk` chain every iteration (evidence/recurrence.txt: ~13 of
    /// ~21 hot-loop instructions). `hoist_plan` records, per loop head, the
    /// distinct constants worth pre-materializing into a reserved register in the
    /// preheader; `imm_hoist` maps a currently-hoisted constant to that register
    /// so `evalDnirValue` returns it instead of re-emitting. Constants are
    /// loop-invariant by definition, so this is the safest possible motion — no
    /// aliasing, effect, or order obligation is involved (law.observation.minimum).
    imm_hoist: std.AutoHashMapUnmanaged(i64, u5) = .empty,
    hoist_plan: std.AutoHashMapUnmanaged(u32, HoistPlan) = .empty,
    hoist_active: [max_hoist_depth]HoistActive = @splat(.{}),
    hoist_depth: u8 = 0,
    /// Loop head flat index -> code offset where that head's preheader `mov`s
    /// begin. The preheader is emitted BEFORE the head's `code_offsets` entry so
    /// the back edge re-enters after it, which is right for the back edge and
    /// WRONG for every other way in. A loop preceded by an `if` is entered by a
    /// FORWARD branch to the head — both the `b.cond` that skips the then-block
    /// and the `b` that ends it target the head — and both landed past the
    /// preheader, so the loop ran against registers that were never initialized.
    /// That is the declare/branch/loop silent wrong answer. Forward branches are
    /// re-pointed at this offset in the patch pass; back edges keep the head's
    /// own offset. Emptied per function with the rest of the hoist state.
    hoist_preheader: std.AutoHashMapUnmanaged(u32, u32) = .empty,
    /// Stack slots for sealed record fields (f64 or i64): "c.pos" -> slot meta.
    fp_stack_slots: std.StringHashMapUnmanaged(StackSlot) = .empty,
    stack_frame_bytes: u16 = 0,
    /// Bytes `sp` currently sits below the frame base `stack_frame_bytes` measures from.
    sp_temp_bytes: u16 = 0,
    /// True once the prologue has finished laying the frame out and body
    /// emission owns it. The prologue rebases what its own growth displaces;
    /// after this there is no rebasing owner, so `frameGrow` over a resident
    /// would rename that resident's address and refuses instead.
    frame_sealed: bool = false,
    /// x19–x28 belong to the caller. Saved under the locals/spill frame so
    /// `[sp,#off]` homes stay zero-based. Without this, `strip`'s `i += 1`
    /// left x19–x21 in the caller's registers and `callfirstrel` SIGSEGV'd.
    callee_save_bytes: u16 = 0,
    /// STICKY record of every callee-saved register (x19–x28) this function's
    /// body has claimed. `used_regs` is cleared on release, so it answers "is
    /// this register busy right now", which is not the question the prologue
    /// asks. Bit `r` set means x`r` was written at some point and its incoming
    /// value therefore has to be preserved.
    callee_touched: u32 = 0,
    /// The set the prologue actually saves. `callee_save_all` is the old
    /// unconditional block; a probe pass narrows it to `callee_touched`.
    callee_save_plan: u32 = 0,
    /// `alloc_slots` result temp -> sp-relative byte offset of its slot region.
    slot_bases: std.AutoHashMapUnmanaged(u32, u16) = .empty,
    spilled_regs: std.AutoHashMapUnmanaged(u5, u16) = .empty,
    /// Registers currently handed to emitter code, which may still name them
    /// in a local and read them raw without re-deriving through
    /// `evalDnirValue`. `spillTempVictim` never chooses one: spilling it
    /// would leave the emitter's register number stale. Set at every
    /// hand-out (`evalDnirValue` family, `allocRegExcluding`,
    /// `allocRegOutsideSaveSet`), cleared at every free (`releaseReg`,
    /// `sweepGpLive`, the direct free sites). A missed clear over-protects
    /// toward honest refusal; the set points are complete by construction,
    /// so no emitter can be missed the way a per-site list can be.
    held_regs: u32 = 0,
    /// Frame slot per spilled TEMPORARY id. `spilled_regs` keys on the physical
    /// register, which the victim's register is immediately re-let for, so it
    /// cannot name the value once the register is reused. This map keys on the
    /// temporary id instead: spilling a temp stores the register into a frame
    /// slot, removes the temp's register name, and records the slot here. A
    /// later read reloads from the slot into whichever register is then free
    /// and re-names the temp. Only unpinned, unhomed, unstaged, non-FP temps
    /// whose register names no other live value are admitted; pins, homes,
    /// staged argument registers, and the staged variadic tail keep their
    /// existing records.
    temp_frame_slots: std.AutoHashMapUnmanaged(u32, u16) = .empty,
    /// Spill slots returned to the pool when a spilled register reloads.
    free_spill_slots: std.ArrayList(u16) = .empty,
    /// Locals spilled to the stack frame when the GP home budget is exhausted.
    gp_stack_locals: std.AutoHashMapUnmanaged(u32, u16) = .empty,
    /// Pre-reserved temp spill pool when GP locals already occupy [sp,#off].
    /// Mid-function `sub sp` would invalidate those fixed offsets (gate scripts).
    gate_spill_base: u16 = 0,
    gate_spill_end: u16 = 0,
    gate_spill_cursor: u16 = 0,
    /// `snprintf(buf, …)` returns a length in x0 and clobbers caller-saved
    /// registers that may still own `buf` in the temp map.
    extern_preserve_x0: bool = false,
    extern_preserve_x0_temp: ?u32 = null,
    cost: CostLedger = .{},
    /// Arguments staged for the NEXT call's variadic tail. Apple's ARM64 ABI
    /// diverges from AAPCS64 here: every argument past a variadic function's
    /// last NAMED parameter travels on the STACK, 8-byte aligned, never in
    /// x0..x7. A `mov_arg` marked `.field = "vararg"` lands here instead of in
    /// a parameter register, and the call flushes the list to [sp, #i*8].
    pending_varargs: [8]VarArg = @splat(.{}),
    pending_vararg_count: u5 = 0,

    /// Max distinct constants hoisted per loop, and max loop-nest depth tracked.
    /// Bounded so hoisting never starves the scratch pool into a spill; deeper
    /// or wider loops simply hoist their most expensive constants and leave the
    /// rest to inline materialization.
    const max_hoist_per_loop = 8;
    const max_hoist_depth = 8;

    const HoistPlan = struct {
        latch: u32 = 0,
        count: u8 = 0,
        values: [max_hoist_per_loop]i64 = @splat(0),
    };

    const HoistActive = struct {
        latch: u32 = 0,
        count: u8 = 0,
        values: [max_hoist_per_loop]i64 = @splat(0),
        regs: [max_hoist_per_loop]u5 = @splat(0),
    };

    const VarArg = struct {
        reg: u5 = 0,
        /// When set, the operand is evaluated immediately before the tail is
        /// written to the stack — after named `mov_arg` slots and any
        /// `preserve_x0` staging for `snprintf`, so a hole is not read from a
        /// register that was clobbered between `mov_arg` and `emitPushVarargs`.
        operand: ?dnir.Value = null,
        /// The register was allocated for this argument alone (an immediate or
        /// a string address), so the call must hand it back. A `.temp`/`.local`
        /// register is owned by the slot map and outlives the call.
        scratch: bool = false,
        /// `reg` HOLDS THIS ARGUMENT NOW — the tail's counterpart of
        /// `pending_arg_regs`, and the fact both paths that take a register
        /// away from the map naming it read: `reclaimSpilledReg`, which would
        /// hand it back as scratch, and `ensureRegLiveRemap`, which would
        /// relocate the value out of it and leave `reg` below naming the
        /// register the move vacated.
        ///
        /// `operand == null` alone cannot say it. A slot inside
        /// `pending_vararg_count` that no `mov_arg` ever wrote is `.{}`, whose
        /// operand is null and whose `reg` is 0, so reading the cleared operand
        /// as "materialized" reserves x0 for a hole. `materializePendingVarargs`
        /// sets this where it assigns `reg`, and the whole-struct `.{}` writes
        /// in `mov_arg` and `emitPopVarargs` are what clear it.
        staged: bool = false,
    };

    const CallPatch = struct {
        offset: u32,
        target: []const u8,
    };

    const StackSlot = struct {
        off: u16,
        float: bool,
    };

    const SaveSet = struct {
        regs: [28]u5 = @splat(0),
        count: u5 = 0,
        /// Live FP VALUE registers (d16-d30). Every d register is caller-saved
        /// on AAPCS64, so without this no float survives a call — which is why
        /// widening the FP pool before adding this hung mandelbrot (gap[057]).
        /// d0-d7 are NOT saved, matching the integer side's decision not to save
        /// x0-x8: those are argument and result registers, and saving the result
        /// register would clobber the value the call just produced.
        fp_regs: [16]u5 = @splat(0),
        fp_count: u5 = 0,
        stack_bytes: u16 = 0,
    };

    const StringSymbol = struct {
        bytes: []const u8,
        name: []const u8,
        symbol_index: u32,
    };

    /// One promoted table's place in `__TEXT,__const`. It owns NO memory: the
    /// name belongs to `symbols` and the words to `const_words`, so there is
    /// exactly one owner of each and nothing to double-free when `finish`
    /// hands the symbol table to the output.
    const ConstTableSymbol = struct {
        symbol_index: u32,
        word_off: u32,
        word_len: u32,
    };

    const DnirBranchPatch = struct {
        patch_off: u32,
        target_instr: u32,
        is_cond: bool,
    };

    fn refuse(self: *Arm64Compiler, src: std.builtin.SourceLocation) Error {
        return recordRefusal(self.diagnostic, src);
    }

    fn refuseWith(self: *Arm64Compiler, src: std.builtin.SourceLocation, note: []const u8) Error {
        return recordRefusalWith(self.diagnostic, src, note);
    }

    fn undefinedKey(self: *Arm64Compiler, src: std.builtin.SourceLocation, kind: []const u8, key: []const u8) Error {
        return recordUndefinedKey(self.diagnostic, src, kind, key);
    }

    fn undefinedAt(self: *Arm64Compiler, src: std.builtin.SourceLocation, kind: []const u8, id: u32) Error {
        return recordUndefinedAt(self.diagnostic, src, kind, id);
    }

    fn deinit(self: *Arm64Compiler) void {
        self.callee_save_sites.deinit(self.alloc);
        self.code.deinit(self.alloc);
        self.asm_text.deinit(self.alloc);
        for (self.symbols.items) |sym| self.alloc.free(sym.name);
        self.symbols.deinit(self.alloc);
        self.extern_symbols.deinit(self.alloc);
        self.relocations.deinit(self.alloc);
        self.lineage.deinit(self.alloc);
        for (self.call_patches.items) |patch| self.alloc.free(patch.target);
        self.call_patches.deinit(self.alloc);
        for (self.strings.items) |s| {
            self.alloc.free(s.bytes);
            self.alloc.free(s.name);
        }
        self.strings.deinit(self.alloc);
        self.string_map.deinit(self.alloc);
        self.const_bases.deinit(self.alloc);
        self.graph_const_bases.deinit(self.alloc);
        self.const_words.deinit(self.alloc);
        self.const_tables.deinit(self.alloc);
        // Keys are borrowed; the symbol NAMES are owned and freed with the
        // symbol list, so only the containers go here.
        self.globals.deinit(self.alloc);
        // Keys are the module's own function names, borrowed for the length of
        // `compileDnirModule` exactly as `cur_module_functions` is.
        self.depth_metered_names.deinit(self.alloc);
        self.global_syms.deinit(self.alloc);
        self.global_init.deinit(self.alloc);
        self.global_str_inits.deinit(self.alloc);
        self.global_str_fixups.deinit(self.alloc);
        self.global_words.deinit(self.alloc);
        self.fp_locals.deinit(self.alloc);
        self.fp_temps.deinit(self.alloc);
        self.value_free_at.deinit(self.alloc);
        self.loose_read_values.deinit(self.alloc);
        self.imm_hoist.deinit(self.alloc);
        self.hoist_plan.deinit(self.alloc);
        self.hoist_preheader.deinit(self.alloc);
        self.fp_abi_passthrough.deinit(self.alloc);
        self.fp_stack_slots.deinit(self.alloc);
        self.slot_bases.deinit(self.alloc);
        self.spilled_regs.deinit(self.alloc);
        self.temp_frame_slots.deinit(self.alloc);
        self.free_spill_slots.deinit(self.alloc);
        self.gp_stack_locals.deinit(self.alloc);
        self.cost.deinit(self.alloc);
    }

    fn emitAsmHeader(self: *Arm64Compiler) Error!void {
        try self.asm_text.appendSlice(self.alloc,
            \\.section __TEXT,__text,regular,pure_instructions
            \\.p2align 2
        );
    }

    fn finish(self: *Arm64Compiler) Error!Arm64Output {
        try self.patchCalls();

        var cstring: std.ArrayList(u8) = .empty;
        errdefer cstring.deinit(self.alloc);
        // ONE INTERIOR NUL ANYWHERE DISQUALIFIES THE WHOLE BLOB, because the
        // blob is what ld splits — it does not know which entry the NUL came
        // from. `Arm64Output.cstring_coalescable` states why.
        var coalescable = true;
        for (self.strings.items) |s| {
            if (std.mem.indexOfScalar(u8, s.bytes, 0) != null) coalescable = false;
        }
        if (self.strings.items.len > 0) {
            // The ASM FACE SAYS THE SAME THING THE OBJECT DOES. `.cstring`
            // is the assembler directive for `S_CSTRING_LITERALS`; a blob that
            // must not be resplit is plain `S_REGULAR` read-only data, and
            // `__TEXT,__conststr` is a section of its own so it cannot collide
            // with the `__TEXT,__const` the determined tables already own.
            try self.asm_text.appendSlice(
                self.alloc,
                if (coalescable)
                    "\n.section __TEXT,__cstring\n"
                else
                    "\n.section __TEXT,__conststr\n",
            );
            var str_off: u32 = 0;
            for (self.strings.items) |s| {
                self.symbols.items[s.symbol_index].offset = @intCast(self.code.items.len + str_off);
                try self.asm_text.appendSlice(self.alloc, s.name);
                try self.asm_text.appendSlice(self.alloc, ":\n");
                try self.emitAscizAsm(s.bytes);
                try cstring.appendSlice(self.alloc, s.bytes);
                try cstring.append(self.alloc, 0);
                str_off += @intCast(s.bytes.len + 1);
            }
        }
        // `__TEXT,__const` — the determined tables, as data.
        //
        // THE VM LAYOUT THE SYMBOLS ARE MEASURED AGAINST. A relocatable object's
        // sections are laid out here at __text, then __cstring, then __const, and
        // a defined local symbol's `n_value` is its ABSOLUTE address in that
        // layout — never a section-relative offset, which clang's linker rejects
        // (the same rule the string labels above already obey). `__const` is
        // 8-byte aligned because every element is an 8-byte word and the access
        // path is `ldr x, [base, idx, lsl #3]`.
        var const_data: std.ArrayList(u8) = .empty;
        errdefer const_data.deinit(self.alloc);
        if (self.const_words.items.len > 0) {
            // Section INDEX, not a constant: __cstring only exists when this
            // module has a string literal, so __const is section 2 or 3.
            const section_index: u8 = if (self.strings.items.len > 0) 3 else 2;
            const base_addr = alignForward(self.code.items.len + cstring.items.len, 8);
            try self.asm_text.appendSlice(self.alloc, "\n.section __TEXT,__const\n.p2align 3\n");
            for (self.const_tables.items) |entry| {
                const sym = &self.symbols.items[entry.symbol_index];
                sym.offset = @intCast(base_addr + @as(usize, entry.word_off) * 8);
                sym.section = section_index;
                try self.asm_text.appendSlice(self.alloc, sym.name);
                try self.asm_text.appendSlice(self.alloc, ":\n");
                const words = self.const_words.items[entry.word_off..][0..entry.word_len];
                for (words) |w| try self.asm_text.print(self.alloc, "\t.quad {d}\n", .{w});
            }
            for (self.const_words.items) |w| {
                var buf: [8]u8 = undefined;
                std.mem.writeInt(i64, &buf, w, .little);
                try const_data.appendSlice(self.alloc, &buf);
            }
        }
        // `__DATA,__bss` — the written module-scope bindings, as storage.
        //
        // THE SAME RULE `__const` OBEYS, and it has to be computed the same way
        // on both sides: `emitMachOArm64ObjectWithConst` derives `bss_addr`
        // independently, and if the two disagree ld resolves every global's
        // adrp/add to the wrong word. Sections are laid out __text, __cstring,
        // __const, __bss, each present only when non-empty, so the index is not
        // a constant either.
        var bss_size: u64 = 0;
        var global_data: std.ArrayList(u8) = .empty;
        errdefer global_data.deinit(self.alloc);
        if (self.global_syms.items.len > 0) {
            var section_index: u8 = 2;
            if (self.strings.items.len > 0) section_index += 1;
            if (self.const_words.items.len > 0) section_index += 1;
            const base_addr = bssBaseAddr(
                self.code.items.len,
                cstring.items.len,
                self.const_words.items.len * 8,
            );
            // ONE ARENA, TWO REALIZATIONS, AND THE CHEAPER ONE IS THE DEFAULT.
            //
            // Every word zero -> `__DATA,__bss`, S_ZEROFILL, no file bytes: the
            // bytes this emitter always wrote. Any word non-zero -> the SAME
            // arena at the SAME address as `__DATA,__data`, S_REGULAR, with the
            // initial content in the file. The loader maps it; nothing executes.
            //
            // WHY NOT A THIRD SECTION SPLITTING ZERO FROM NON-ZERO. It would
            // save (zero words x 8) file bytes and cost a second section header
            // (80 bytes), a second address derivation and a second index — a
            // section header is bigger than ten saved words, and two derivations
            // of one address is exactly how a relocation lands on the wrong
            // word. `bssBaseAddr` stays the sole derivation.
            var any_nonzero = false;
            for (self.global_words.items) |w| {
                if (w != 0) any_nonzero = true;
            }
            // A string-initialized word is zero in the object but non-zero
            // after the linker resolves its relocation, so it forces
            // __DATA,__data like any other non-zero word.
            var str_fixup_by_word = std.AutoHashMap(u32, u32).init(self.alloc);
            defer str_fixup_by_word.deinit();
            for (self.global_str_fixups.items) |f| {
                try str_fixup_by_word.put(f.word, f.str_sym);
                any_nonzero = true;
            }
            try self.asm_text.appendSlice(
                self.alloc,
                if (any_nonzero)
                    "\n.section __DATA,__data\n.p2align 3\n"
                else
                    "\n.section __DATA,__bss\n.p2align 3\n",
            );
            for (self.global_syms.items, 0..) |sidx, w| {
                const sym = &self.symbols.items[sidx];
                sym.offset = @intCast(base_addr + w * 8);
                sym.section = section_index;
                try self.asm_text.appendSlice(self.alloc, sym.name);
                const word = self.global_words.items[w];
                if (any_nonzero) {
                    if (str_fixup_by_word.get(@intCast(w))) |str_sym| {
                        // The address is a link-time fact: the assembler
                        // resolves the symbol, and the object writer records
                        // a data-section relocation for the linker.
                        const str_name = self.symbols.items[str_sym].name;
                        try self.asm_text.print(self.alloc, ":\n\t.quad {s}\n", .{str_name});
                        var buf: [8]u8 = undefined;
                        std.mem.writeInt(u64, &buf, 0, .little);
                        try global_data.appendSlice(self.alloc, &buf);
                        try self.data_relocations.append(self.alloc, .{
                            .offset = @intCast(w * 8),
                            .symbol_index = str_sym,
                            .kind = .abs64,
                        });
                    } else {
                        try self.asm_text.print(self.alloc, ":\n\t.quad {d}\n", .{@as(i64, @bitCast(word))});
                        var buf: [8]u8 = undefined;
                        std.mem.writeInt(u64, &buf, word, .little);
                        try global_data.appendSlice(self.alloc, &buf);
                    }
                } else {
                    try self.asm_text.appendSlice(self.alloc, ":\n\t.zero 8\n");
                }
            }
            bss_size = @as(u64, self.global_syms.items.len) * 8;
        }
        const global_data_bytes = try global_data.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(global_data_bytes);

        const const_bytes = try const_data.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(const_bytes);

        const cstring_bytes = try cstring.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(cstring_bytes);

        // Mach-O stores section relocations sorted by descending r_address.
        std.mem.sort(Relocation, self.relocations.items, {}, relocDescByOffset);
        std.mem.sort(Relocation, self.data_relocations.items, {}, relocDescByOffset);

        const text = try self.code.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(text);
        const asm_text = try self.asm_text.toOwnedSlice(self.alloc);
        errdefer self.alloc.free(asm_text);
        const symbols = try self.symbols.toOwnedSlice(self.alloc);
        self.symbols = .empty;
        errdefer {
            for (symbols) |sym| self.alloc.free(sym.name);
            self.alloc.free(symbols);
        }
        const relocations = try self.relocations.toOwnedSlice(self.alloc);
        self.relocations = .empty;
        const data_relocations = try self.data_relocations.toOwnedSlice(self.alloc);
        self.data_relocations = .empty;
        errdefer self.alloc.free(relocations);
        const lineage = try self.lineage.toOwnedSlice(self.alloc);
        self.lineage = .empty;
        const cost = try self.cost.entries.toOwnedSlice(self.alloc);
        self.cost.entries = .empty;
        return .{
            .text = text,
            .asm_text = asm_text,
            .cstring = cstring_bytes,
            .cstring_coalescable = coalescable,
            .const_data = const_bytes,
            .symbols = symbols,
            .relocations = relocations,
            .data_relocations = data_relocations,
            .lineage = lineage,
            .bss_size = bss_size,
            .global_data = global_data_bytes,
            .cost = cost,
        };
    }

    fn recordBootstrapExternCost(self: *Arm64Compiler, ins: dnir.Instr) !void {
        if (ins.op != .call_extern or ins.application != null) return;
        try self.cost.record(
            self.alloc,
            .extern_call,
            "bootstrap extern call without graph application lineage",
        );
    }

    fn internString(self: *Arm64Compiler, content: []const u8) Error!u32 {
        if (self.string_map.get(content)) |idx| return idx;
        try self.cost.record(
            self.alloc,
            .string_intern_hash,
            "literal string dedup table miss before rodata emission",
        );
        const idx: u32 = @intCast(self.symbols.items.len);
        const owned_name = try std.fmt.allocPrint(self.alloc, "Lduo_str_{d}", .{self.next_string});
        self.next_string += 1;
        errdefer self.alloc.free(owned_name);
        try self.symbols.append(self.alloc, .{
            .name = owned_name,
            .offset = 0,
            .defined = true,
            .section = 2,
            .external = false,
        });
        const owned_bytes = try self.alloc.dupe(u8, content);
        errdefer self.alloc.free(owned_bytes);
        // The strings table owns its OWN copy of the label. `finish` moves
        // `symbols` into the emitted output while `strings` stays with the
        // compiler, so sharing one allocation dangles the output's symbol
        // name the moment `deinit` frees the strings table — a use-after-free
        // that surfaced as garbage local-symbol names in the object file and,
        // nondeterministically, in the linked binary's LINKEDIT (extra bytes
        // ld could otherwise strip as an `L`-local).
        const string_name = try self.alloc.dupe(u8, owned_name);
        errdefer self.alloc.free(string_name);
        try self.strings.append(self.alloc, .{ .bytes = owned_bytes, .name = string_name, .symbol_index = idx });
        try self.string_map.put(self.alloc, owned_bytes, idx);
        return idx;
    }

    /// The `__TEXT,__const` symbol for these words, creating it if this is the
    /// first table with these contents.
    ///
    /// Deduped by contents for the same reason string literals are: two bindings
    /// of the same determined table are the same data, and the address is all
    /// either one can observe. Nothing writes the section, so sharing it cannot
    /// be witnessed.
    fn internConstTable(self: *Arm64Compiler, values: []const i64) Error!u32 {
        for (self.const_tables.items) |entry| {
            const have = self.const_words.items[entry.word_off..][0..entry.word_len];
            if (std.mem.eql(i64, have, values)) return entry.symbol_index;
        }
        const idx: u32 = @intCast(self.symbols.items.len);
        const owned_name = try std.fmt.allocPrint(self.alloc, "Lduo_const_{d}", .{self.next_const});
        errdefer self.alloc.free(owned_name);
        self.next_const += 1;
        // `.section` is stamped in `finish`, which is the only place that knows
        // whether a __cstring section exists to sit between this and __text.
        try self.symbols.append(self.alloc, .{
            .name = owned_name,
            .offset = 0,
            .defined = true,
            .section = 2,
            .external = false,
        });
        const word_off: u32 = @intCast(self.const_words.items.len);
        try self.const_words.appendSlice(self.alloc, values);
        try self.const_tables.append(self.alloc, .{
            .symbol_index = idx,
            .word_off = word_off,
            .word_len = @intCast(values.len),
        });
        return idx;
    }

    /// The `__DATA,__bss` symbol for a written module-scope binding, creating it
    /// on first mention.
    ///
    /// NOT deduped by contents the way `internConstTable` is — that dedup is
    /// sound only because nothing writes `__TEXT,__const`. Here two bindings that
    /// happen to hold equal values are still two locations, and sharing one word
    /// between them would be observable the instant either is written.
    fn internGlobal(self: *Arm64Compiler, name: []const u8) Error!u32 {
        if (self.globals.get(name)) |idx| return idx;
        const idx: u32 = @intCast(self.symbols.items.len);
        const owned_name = try std.fmt.allocPrint(self.alloc, "Lduo_g_{s}", .{name});
        errdefer self.alloc.free(owned_name);
        // `.section` and `.offset` are stamped in `finish`, the only place that
        // knows which of __cstring and __const exist ahead of this one.
        try self.symbols.append(self.alloc, .{
            .name = owned_name,
            .offset = 0,
            .defined = true,
            .section = 2,
            .external = false,
        });
        try self.global_syms.append(self.alloc, idx);
        // WORD ORDER IS SYMBOL ORDER, and both are appended here so no later
        // pass has to re-derive the correspondence. A name with no published
        // initializer holds zero, which is what a zerofill word already is.
        try self.global_words.append(self.alloc, self.global_init.get(name) orelse 0);
        if (self.global_str_inits.get(name)) |str_sym| {
            try self.global_str_fixups.append(self.alloc, .{
                .word = @intCast(self.global_words.items.len - 1),
                .str_sym = str_sym,
            });
        }
        try self.globals.put(self.alloc, name, idx);
        return idx;
    }

    fn emitAdrpAdd(self: *Arm64Compiler, reg: u5, symbol_index: u32) Error!void {
        const sname = self.symbols.items[symbol_index].name;
        const page_off: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x90000000 | @as(u32, reg), "adrp x{d}, {s}@PAGE", .{ reg, sname });
        try self.relocations.append(self.alloc, .{ .offset = page_off, .symbol_index = symbol_index, .kind = .page21 });
        const off_off: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x91000000 | (@as(u32, reg) << 5) | @as(u32, reg), "add x{d}, x{d}, {s}@PAGEOFF", .{ reg, reg, sname });
        try self.relocations.append(self.alloc, .{ .offset = off_off, .symbol_index = symbol_index, .kind = .pageoff12 });
    }

    fn emitAscizAsm(self: *Arm64Compiler, bytes: []const u8) Error!void {
        try self.asm_text.appendSlice(self.alloc, "\t.asciz \"");
        for (bytes) |b| {
            switch (b) {
                '"' => try self.asm_text.appendSlice(self.alloc, "\\\""),
                '\\' => try self.asm_text.appendSlice(self.alloc, "\\\\"),
                '\n' => try self.asm_text.appendSlice(self.alloc, "\\n"),
                '\t' => try self.asm_text.appendSlice(self.alloc, "\\t"),
                '\r' => try self.asm_text.appendSlice(self.alloc, "\\r"),
                0x20...0x21, 0x23...0x5b, 0x5d...0x7e => try self.asm_text.append(self.alloc, b),
                else => try self.asm_text.print(self.alloc, "\\x{x:0>2}", .{b}),
            }
        }
        try self.asm_text.appendSlice(self.alloc, "\"\n");
    }

    fn isProcessEntry(self: *const Arm64Compiler) bool {
        const entry = self.entry orelse return false;
        const cur = self.cur_func_name orelse return false;
        return std.mem.eql(u8, entry, cur);
    }

    fn needsProcessExitF64Coerce(self: *const Arm64Compiler) bool {
        if (!self.isProcessEntry()) return false;
        return self.cur_func_float or self.cur_func_ret_float;
    }

    fn compileDnirModule(self: *Arm64Compiler, m: dnir.Module) Error!void {
        self.graph = m.graph;
        try self.emitAsmHeader();
        for (m.dense_tables) |table| {
            if (table.elem_ty != .i64 or table.values.len == 0) return self.refuse(@src());
            const symbol = try self.internConstTable(table.values);
            const entry = try self.graph_const_bases.getOrPut(self.alloc, table.value);
            if (entry.found_existing and entry.value_ptr.* != symbol) return self.refuse(@src());
            entry.value_ptr.* = symbol;
        }
        // The load-time content of the module's storage, BEFORE any function is
        // compiled — `internGlobal` reads it on first mention of each name.
        for (m.globals) |g| {
            const word: u64 = switch (g.init) {
                .i64 => |n| @bitCast(n),
                .f64 => |f| @bitCast(f),
                .str => |s| blk: {
                    // The word holds the string's address -- a link-time fact.
                    // Intern the literal, remember the symbol by global name,
                    // and leave a zero word the data-section relocation
                    // resolves at link time.
                    const str_sym = try self.internString(s);
                    try self.global_str_inits.put(self.alloc, g.name, str_sym);
                    break :blk 0;
                },
                // lowerModuleFromGraph publishes only .i64/.f64/.str and
                // refuses everything else, so this is unreachable in practice
                // and refuses rather than guessing if that ever stops holding.
                else => return self.refuse(@src()),
            };
            try self.global_init.put(self.alloc, g.name, word);
        }
        // `MissingMain` MEANS MISSING MAIN. Object mode passes `entry = null`
        // (`emitObjectMode…` at the top of this file), and a LIBRARY module
        // with no declarations has no main to miss — it has nothing, which is
        // a legal thing for a module to have and the base case the module
        // system needs. This was the third copy of one conflation: zero
        // functions read as "refuse" in `lowerModuleFromGraph`, again in
        // `moduleIsNativeDirectReady`, and again here. When an entry IS
        // demanded the error is exactly as before.
        if (m.functions.len == 0 and self.entry != null) return error.MissingMain;
        // §12 TAIL reads the CALLEE's declaration out of here. Borrowed for the
        // length of this call; `m` outlives it.
        self.cur_module_functions = m.functions;
        self.record = m.records;
        // §12 `error.depth` — which frames are metered, decided ONCE for the
        // whole module and BEFORE any function is probed. Both passes read this
        // map, so both emit the same prologue: `probeCalleeSaveUse`'s premise is
        // that they differ only in which `str`/`ldr` pairs the prologue holds,
        // and a check present in one and absent from the other would measure a
        // different function.
        try self.computeDepthMeteredSet(m.functions);
        for (m.functions) |f| {
            // Single-pass codegen: the attempt IS the measurement. See
            // `compileDnirFunctionSinglePass`.
            self.next_func_metered = self.depth_metered_names.contains(f.name);
            self.probe_census_functions += 1;
            try self.compileDnirFunctionSinglePass(f);
        }
        for (m.externs) |ext| {
            try self.ensureExternalSymbol(ext.symbol);
        }
    }

    /// Which callee-saved registers this function's body actually writes.
    ///
    /// The answer is MEASURED, by compiling the function once into a throwaway
    /// compiler and reading back what its allocator claimed. Nothing else can
    /// answer it: the highest register reached is decided by the allocator's own
    /// spill-and-reuse behaviour over the whole body, and `dnirGpPressure` — a
    /// census of names MENTIONED anywhere, with no notion of liveness — is not a
    /// bound on it in either direction. That census is what made one extra local
    /// (5 -> 6, liveness never above 2) turn 16 instructions into 41, all of the
    /// difference being twenty saves and restores of registers the function did
    /// not go on to use.
    ///
    /// The probe runs with `callee_save_plan = callee_save_all`, i.e. EXACTLY
    /// today's prologue, so the two passes differ only in which `str`/`ldr` pairs
    /// the prologue emits. Register allocation reads no code offset and no frame
    /// size, so the second pass claims the same registers as the first — and the
    /// caller verifies that rather than trusting it.
    ///
    /// The probe gets its own `Diagnostic`: a refusal encountered while probing
    /// is not this compilation's refusal, and must not be left behind for the
    /// real pass's error to be read from. If no rung of the ladder can compile
    /// the function, `probeFunctionPlan` answers `callee_save_all` — the old
    /// behaviour — and the real pass reports the real failure.
    /// What the real pass must be told before it compiles `f`: which
    /// callee-saved registers to save, and how many locals it may home.
    const FunctionPlan = struct { callee_save: u32, home_budget: u32 };

    /// BISECTION HANDLE for the home budget, read once per process.
    ///
    /// `IDOL_HOME_BUDGET=n` caps every rung of the ladder at n, so the same
    /// compiler can be asked "is this program's answer a function of how many
    /// locals were homed?" without a rebuild per point. It only ever LOWERS a
    /// rung, so `IDOL_HOME_BUDGET=0` is exactly the frame-slot behaviour that
    /// preceded homing — which makes it a control, not just a knob: if a
    /// suspected miscompile survives 0, it is not this change's.
    fn homeBudgetOverride() ?u32 {
        const S = struct {
            var read: bool = false;
            var value: ?u32 = null;
        };
        if (!S.read) {
            S.read = true;
            if (std.c.getenv("IDOL_HOME_BUDGET")) |raw| {
                S.value = std.fmt.parseInt(u32, std.mem.span(raw), 10) catch null;
            }
        }
        return S.value;
    }

    /// The two per-function facts, measured together in one throwaway compile.
    ///
    /// HOW MANY LOCALS A BODY MAY HOME IS ALSO A MEASUREMENT, and for the same
    /// reason the callee-save set is: a home holds a register for the WHOLE
    /// function, so it is subtracted from the pool every expression in the body
    /// draws on, and no census of names says whether what is left is enough.
    /// Compiled at the full ten homes, `sha.id` and `tree.id` refuse outright
    /// (DNB003, `RegisterExhausted`) — bodies whose expression pressure needs
    /// the registers more than their locals do.
    ///
    /// So the budget is found by asking, descending, and the ladder ends at ZERO
    /// — every local in the frame, exactly the behaviour that preceded homing —
    /// which is why the search always terminates on something the compiler could
    /// already do. Ten is tried FIRST and answers on the first attempt for
    /// everything that fits, so the common function costs the same one probe it
    /// cost before.
    ///
    /// A leaf never reads the budget (`planGpStackLocals` only consults it when
    /// the body calls), so a leaf is probed once and the ladder is skipped: a
    /// leaf that cannot compile must not be compiled four more times to learn
    /// the same thing.
    fn probeFunctionPlan(self: *Arm64Compiler, f: dnir.Function) FunctionPlan {
        var ladder = [_]u32{ callee_save_count, 6, 3, 0 };
        if (homeBudgetOverride()) |cap| {
            for (&ladder) |*rung| rung.* = @min(rung.*, cap);
        }
        const steps: usize = if (dnirFunctionHasCall(f)) ladder.len else 1;
        var i: usize = 0;
        while (i < steps) : (i += 1) {
            self.probe_census_probes += 1;
            if (i > 0) self.probe_census_descents += 1;
            if (self.probeCalleeSaveUse(f, ladder[i])) |touched| {
                return .{ .callee_save = touched, .home_budget = ladder[i] };
            }
        }
        return .{ .callee_save = callee_save_all, .home_budget = 0 };
    }

    /// Compile one function in a SINGLE pass.
    ///
    /// The old driver compiled every function twice: once into a throwaway
    /// probe compiler to measure `callee_touched`, once for real with the
    /// measured plan. But the measurement IS the compilation —
    /// `callee_touched` is whatever the allocator claimed while emitting —
    /// so the first pass's bytes are already the right body. This compiles
    /// once, with `callee_save_plan = callee_save_all` (or 0 for a predicted
    /// leaf), then nops the `str`/`ldr` pairs for registers the allocator
    /// never touched. Positions never move, so every recorded offset stays
    /// valid: no branch, patch, or relocation needs rebasing.
    ///
    /// The predicted shape comes from `dnirFunctionHasCall`: leaves almost
    /// always plan 0, calls almost always need the save area. A mispredict
    /// rewinds the attempt's bytes and retries with the other shape; a failed
    /// first rung rewinds and falls back to the two-pass ladder: the failed
    /// attempt plus the ladder's probe and real passes, three compilations.
    /// Worse than today's two only when the prediction is wrong; the
    /// common path costs one.
    const CalleeSaveSite = struct { offset: u32, reg: u5 };
    fn compileDnirFunctionSinglePass(self: *Arm64Compiler, f: dnir.Function) Error!void {
        var want_save_area = dnirFunctionHasCall(f);
        while (true) {
            self.callee_save_plan = if (want_save_area) callee_save_all else 0;
            self.gp_call_home_budget = callee_save_count;
            if (homeBudgetOverride()) |cap| {
                if (cap < self.gp_call_home_budget) self.gp_call_home_budget = cap;
            }

            const mark_code = self.code.items.len;
            const mark_asm = self.asm_text.items.len;
            const mark_patches = self.call_patches.items.len;
            const mark_relocs = self.relocations.items.len;
            const mark_lineage = self.lineage.items.len;
            self.callee_save_sites.clearRetainingCapacity();
            self.defer_func_symbol = true;
            var attempt_diag: Diagnostic = .{};
            const saved_diag = self.diagnostic;
            self.diagnostic = &attempt_diag;

            var ok = true;
            self.compileDnirFunction(f) catch {
                ok = false;
            };

            self.diagnostic = saved_diag;
            self.defer_func_symbol = false;

            if (!ok) {
                // First rung failed: rewind, fall back to the two-pass ladder.
                self.rewindFunctionAttempt(mark_code, mark_asm, mark_patches, mark_relocs, mark_lineage);
                self.probe_census_fallback += 1;
                return self.compileDnirFunctionTwoPass(f);
            }

            const touched = self.callee_touched;
            if (!want_save_area and touched != 0) {
                // Mispredicted leaf: rewind and retry with the save area.
                self.rewindFunctionAttempt(mark_code, mark_asm, mark_patches, mark_relocs, mark_lineage);
                want_save_area = true;
                continue;
            }
            if (want_save_area) {
                self.patchUnusedCalleeSaves(touched);
                self.callee_save_plan = touched;
            }
            self.probe_census_singlepass += 1;
            self.countPlanCensus(touched, dnirFunctionHasCall(f));
            const link_name = try linkerSymbolName(self.alloc, f.name);
            try self.symbols.append(self.alloc, .{ .name = link_name, .offset = @intCast(mark_code), .defined = true });
            return;
        }
    }

    /// Today's two-pass path, kept as the fallback: probe the ladder, then
    /// compile for real with the measured plan.
    fn compileDnirFunctionTwoPass(self: *Arm64Compiler, f: dnir.Function) Error!void {
        const plan = self.probeFunctionPlan(f);
        self.countPlanCensus(plan.callee_save, dnirFunctionHasCall(f));
        self.callee_save_plan = plan.callee_save;
        self.gp_call_home_budget = plan.home_budget;
        try self.compileDnirFunction(f);
        // The plan was measured, not guessed, so a body that reached outside
        // it means the measurement and the emission disagreed — and the
        // artifact just written would hand the CALLER back a register it
        // clobbered. That is invisible to any test of this function. Refuse
        // instead.
        if (self.callee_touched & ~self.callee_save_plan != 0) return self.refuse(@src());
    }

    /// Classify a measured plan for `IDOL_PROBE_CENSUS`.
    fn countPlanCensus(self: *Arm64Compiler, plan: u32, has_call: bool) void {
        if (plan == 0) self.probe_census_plan_zero += 1;
        if (plan == callee_save_all) self.probe_census_plan_all += 1;
        if (plan != 0 and plan != callee_save_all) self.probe_census_plan_partial += 1;
        if (has_call and plan == 0) self.probe_census_call_plan0 += 1;
        if (has_call and plan != 0) self.probe_census_call_non0 += 1;
        if (!has_call and plan == 0) self.probe_census_leaf_plan0 += 1;
        if (!has_call and plan != 0) self.probe_census_leaf_non0 += 1;
    }

    /// Truncate the attempt's bytes, leaving interned strings/constants (and
    /// their dedup maps) valid. The function symbol was deferred, so nothing
    /// defined is left behind. Lineage rows are truncated too: the attempt
    /// published one row per graph application it emitted, and the retry
    /// re-emits the same rows, which must not appear twice
    /// (`validateMachineLineage` requires exactly one row per application).
    fn rewindFunctionAttempt(self: *Arm64Compiler, mark_code: usize, mark_asm: usize, mark_patches: usize, mark_relocs: usize, mark_lineage: usize) void {
        self.code.items.len = mark_code;
        self.asm_text.items.len = mark_asm;
        self.call_patches.items.len = mark_patches;
        self.relocations.items.len = mark_relocs;
        self.lineage.items.len = mark_lineage;
        self.callee_save_sites.clearRetainingCapacity();
    }

    /// Replace the save/restore pairs for untouched registers with NOPs.
    /// Positions never move: each pair was one 4-byte instruction, so recorded
    /// offsets stay valid and nothing needs rebasing.
    fn patchUnusedCalleeSaves(self: *Arm64Compiler, touched: u32) void {
        for (self.callee_save_sites.items) |site| {
            if (touched & (@as(u32, 1) << site.reg) == 0) {
                std.mem.writeInt(u32, self.code.items[site.offset..][0..4], 0xd503201f, .little);
            }
        }
    }

    /// Null when the function does not compile at `home_budget` homes.
    fn probeCalleeSaveUse(self: *Arm64Compiler, f: dnir.Function, home_budget: u32) ?u32 {
        var scratch: Diagnostic = .{};
        var probe = Arm64Compiler{
            .alloc = self.alloc,
            .diagnostic = &scratch,
            .f64_records = self.f64_records,
            .scal_records = self.scal_records,
            .entry = self.entry,
        };
        probe.gate_transport = self.gate_transport;
        probe.gp_local_home_budget = self.gp_local_home_budget;
        probe.gp_call_home_budget = home_budget;
        probe.spill_frame_budget = self.spill_frame_budget;
        // THE PROBE MUST COMPILE THE SAME BODY THE REAL PASS WILL. Its whole
        // premise (see above) is that the two passes differ only in the prologue's
        // save/restore pairs. A licence in one and not the other would give the
        // probe a table built word by word — one value register per element —
        // against a real pass that emits none of it, so the measurement would be
        // of a different function.
        probe.const_licence = self.const_licence;
        // …AND THAT INCLUDES THE SEVERING CONTROL. `tightdef` decides which
        // compare/branch pairs fuse, which decides how many value registers the
        // body claims. A probe that fused where the real pass would not measured
        // a DIFFERENT function's callee-save set, and the mismatch surfaced as
        // `callee_touched & ~callee_save_plan != 0` — a refusal of a program the
        // unsevered arm compiles. The severing arm would then have been
        // measured against a REFUSAL rather than against the code it severs.
        probe.tightdef = self.tightdef;
        // …AND SO DOES §12 TAIL. A tail call emits no caller-save block and no
        // result marshaling, so admitting one in the probe and not in the real
        // pass (or the reverse) measures a different function's callee-save set
        // — the same divergence `tightdef` is copied here to avoid. Both the
        // control and the roster it reads have to cross.
        probe.tailcall = self.tailcall;
        // …AND SO DOES §12 `error.depth`, for the third time and the same
        // reason: five prologue instructions present in one pass and absent from
        // the other measure a different function's callee-save set.
        probe.depth_meter = self.depth_meter;
        probe.depth_module_meters = self.depth_module_meters;
        probe.next_func_metered = self.next_func_metered;
        probe.cur_module_functions = self.cur_module_functions;
        probe.record = self.record;
        if (self.graph_const_bases.count() != 0) {
            var last_symbol: u32 = 0;
            var bases = self.graph_const_bases.iterator();
            while (bases.next()) |entry| last_symbol = @max(last_symbol, entry.value_ptr.*);
            if (last_symbol >= self.symbols.items.len) return null;
            for (self.symbols.items[0 .. last_symbol + 1]) |symbol| {
                var copy = symbol;
                copy.name = self.alloc.dupe(u8, symbol.name) catch return null;
                probe.symbols.append(self.alloc, copy) catch {
                    self.alloc.free(copy.name);
                    return null;
                };
            }
            bases = self.graph_const_bases.iterator();
            while (bases.next()) |entry| {
                probe.graph_const_bases.put(
                    self.alloc,
                    entry.key_ptr.*,
                    entry.value_ptr.*,
                ) catch return null;
            }
        }
        probe.callee_save_plan = callee_save_all;
        defer probe.deinit();
        probe.compileDnirFunction(f) catch |err| {
            var gp_count: u32 = 0;
            for (self.used_regs) |r| {
                if (r) gp_count += 1;
            }
            var fp_count: u32 = 0;
            for (self.used_fp_regs) |r| {
                if (r) fp_count += 1;
            }
            const pressure = dnirGpPressure(f);
            std.debug.print("probe fail: {s} home_budget={d} stack_bytes={d} gp_used={d} fp_used={d} pressure={d}\n", .{ @errorName(err), home_budget, self.stack_frame_bytes, gp_count, fp_count, pressure });
            return null;
        };
        return probe.callee_touched;
    }

    /// True when the body contains any call, so parameters must be relocated out
    /// of the argument/return registers to survive it.
    ///
    /// `print_value` IS A CALL. It emits `bl _printf` / `bl _puts` (and
    /// `bl _fflush` on the `stdout:write` shape) exactly as `call_extern` does,
    /// and the only reason it is a separate opcode is that its argument shape is
    /// fixed rather than lowered. Omitting it here told every consumer of this
    /// predicate that a printing body is a LEAF, and a leaf is allowed to keep
    /// its parameters in the incoming ABI registers — which is what the
    /// comment eighty lines below in `compileDnirFunction` says is safe only
    /// "with no call there is no staging".
    ///
    /// It bit both register files. On the integer side x0..x7 at least reached
    /// `emitSaveCallerRegs`; on the FLOAT side it is unrecoverable there,
    /// because that save covers d16..d30 only (`fp_value_reg_base`), while an
    /// f64 parameter left in place sits in d0..d7 — caller-saved, and printf
    /// clobbers them. MEASURED:
    ///
    ///     _fshow: f64 = (x: f64, y: f64)   print(99)   return x + y
    ///
    /// compiled to `bl _printf` followed by `fadd d16, d0, d1`, and
    /// `_fshow(1.5, 2.25)` answered something other than 3.75. Naming the call
    /// here is the fix: `fp_body_has_call` then copies d0..d7 into the value
    /// bank in the prologue, which is what every other call already gets.
    fn dnirFunctionHasCall(f: dnir.Function) bool {
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                switch (ins.op) {
                    .call_direct, .call_extern, .print_value => return true,
                    else => {},
                }
            }
        }
        return false;
    }

    /// x9–x18 are caller-save GP homes. Pressure past that lands in x19–x28,
    /// which AAPCS64 requires saving even in a leaf.
    const gp_caller_save_homes: u32 = 10;

    fn dnirNeedsCalleeSave(f: dnir.Function) bool {
        if (dnirFunctionHasCall(f)) return true;
        return dnirGpPressure(f) > gp_caller_save_homes;
    }

    fn dnirGpPressure(f: dnir.Function) u32 {
        var locals = std.mem.zeroes([256]u8);
        var temps = std.mem.zeroes([256]u8);
        var n: u32 = 0;
        const mark = struct {
            fn slot(map: *[256]u8, count: *u32, id: u32) void {
                if (id >= 256) {
                    count.* += 1;
                    return;
                }
                if (map.*[id] != 0) return;
                map.*[id] = 1;
                count.* += 1;
            }
            fn value(loc: *[256]u8, tmp: *[256]u8, count: *u32, v: dnir.Value) void {
                switch (v) {
                    .local => |id| slot(loc, count, id),
                    .temp => |id| slot(tmp, count, id),
                    else => {},
                }
            }
        };
        for (f.params, 0..) |p, i| {
            if (p.ty == .f64) continue;
            mark.slot(&locals, &n, @intCast(i));
        }
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                // A defined value only demands a GP home when it is read. A dead
                // immediate binding (defined, never consumed) needs no register
                // or stack slot, so it must not inflate pressure into a spurious
                // callee-save frame (`law.profile.evidence` — spill only the live).
                if (dnir.definition(ins)) |id| {
                    const want_local = ins.op == .store_local;
                    if (dnirDefinitionUsed(f, want_local, id)) {
                        if (want_local) {
                            mark.slot(&locals, &n, id);
                        } else {
                            mark.slot(&temps, &n, id);
                        }
                    }
                }
                for (ins.pack_results) |result| {
                    const id = result.temp orelse continue;
                    if (dnirDefinitionUsed(f, false, id)) mark.slot(&temps, &n, id);
                }
                mark.value(&locals, &temps, &n, ins.lhs);
                mark.value(&locals, &temps, &n, ins.rhs);
                mark.value(&locals, &temps, &n, ins.third);
                for (ins.vals) |v| mark.value(&locals, &temps, &n, v);
            }
        }
        return n;
    }

    fn dnirValueMatches(v: dnir.Value, want_local: bool, id: u32) bool {
        return switch (v) {
            .local => |slot| want_local and slot == id,
            .temp => |slot| !want_local and slot == id,
            else => false,
        };
    }

    fn dnirInstrReadsValue(ins: dnir.Instr, want_local: bool, id: u32) bool {
        const fixed = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
        for (fixed) |v| if (dnirValueMatches(v, want_local, id)) return true;
        for (ins.vals) |v| if (dnirValueMatches(v, want_local, id)) return true;
        return false;
    }

    fn dnirDefinitionUsed(f: dnir.Function, want_local: bool, id: u32) bool {
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (dnirInstrReadsValue(ins, want_local, id)) return true;
            }
        }
        return false;
    }

    /// Every DNIR id this instruction READS. `vals` carries the fields of a
    /// wide record return that lhs/rhs/third cannot express, so a scan that
    /// stopped at `third` would call a fourth field dead while it is still read.
    fn forEachOperandId(ins: dnir.Instr, ctx: anytype, comptime visit: fn (@TypeOf(ctx), u32) void) void {
        const fixed = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
        for (fixed) |v| switch (v) {
            .local, .temp => |id| visit(ctx, id),
            else => {},
        };
        for (ins.vals) |v| switch (v) {
            .local, .temp => |id| visit(ctx, id),
            else => {},
        };
    }

    fn instructionReadsId(ins: dnir.Instr, id: u32) bool {
        const fixed = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
        for (fixed) |value| switch (value) {
            .local, .temp => |slot| if (slot == id) return true,
            else => {},
        };
        for (ins.vals) |value| switch (value) {
            .local, .temp => |slot| if (slot == id) return true,
            else => {},
        };
        return false;
    }

    /// Does this instruction WRITE the value id `t`?
    ///
    /// `mov_arg`/`fp_mov_arg` are excluded because their `result` carries a
    /// PHYSICAL ABI register slot (0..7), not a value id — the same aliasing
    /// the emit loop's ownership rebind already guards against, and treating a
    /// slot number as a definition would make a live value look dead.
    fn instructionDefinesId(ins: dnir.Instr, t: u32) bool {
        switch (ins.op) {
            .mov_arg, .fp_mov_arg => {},
            else => if (ins.result) |r| {
                if (r == t) return true;
            },
        }
        for (ins.pack_results) |result| {
            const temp = result.temp orelse continue;
            if (temp == t) return true;
        }
        return false;
    }

    // ------------------------------------------------------------------
    // THE TIGHT-DEFINITION FACT — "this definition's ONLY reader is the next
    // instruction", asked of the FUNCTION instead of guessed from an index.
    //
    // `value_free_at` answers a different question: the last index at which an
    // ID is mentioned anywhere. Every peephole that wants "single reader"
    // asks it as `last == flat_idx + 1`, and that stands in for the fact only
    // while ids are unique. `dnir_lower`'s LOOP UNROLLER REUSES THEM: the four
    // copies it makes of a body all name the compare's boolean `t7`, so `t7`'s
    // last mention is in copy FOUR and copies one through three refuse a fusion
    // whose precondition they actually satisfy.
    //
    // MEASURED, on a 4x-unrolled loop with an unpredictable branch
    // (`s ^= s<<13 / s ^= s>>7 / s ^= s<<17 ; if s&1 == 0 then t += 3`, 5e7
    // trips, min of 4, four interleaved trials, both arms from ONE compiler
    // with only `IDOL_NO_TIGHTDEF` between them, artifact checksums
    // 7ffc97a6… and b60b021c… and the same answer 74991183 from both:
    //
    //     value_free_at only   0.1856 0.1870 0.1865 0.1855 s
    //     tight-def fact       0.1742 0.1784 0.1779 0.1781 s   1.046x
    //
    // Three of four copies emitted `cmp ; cset ; cmp #0 ; b.eq` where the
    // fourth emitted `cmp ; b.ne`. The two erased instructions sit BETWEEN the
    // compare and the branch that mispredicts on it, so what they cost is
    // resolution latency on every mispredict, not issue slots — which is why
    // this reads 1.049x where removing the same two instructions from a
    // predictable loop reads 1.000x.
    //
    // WHAT MAKES IT SOUND. A read at position `q` reads THIS definition only if
    // control can arrive at `q` with this definition as the last write of the
    // id. So an id is TIGHT when, for every read of it in the function:
    //
    //   * the read is not at the start of a block (a block start is entered,
    //     not fallen into), and
    //   * the instruction immediately before it DEFINES the id, and
    //   * NOTHING BRANCHES TO the read's own index — otherwise the preceding
    //     definition can be skipped and the read sees an older one.
    //
    // Under those three, every read of a tight id reads the definition
    // immediately above it. Our compare's definition therefore has exactly one
    // reader — the branch immediately below it — which is the precondition the
    // index comparison was standing in for.
    //
    // The fact is computed ONCE per function next to `value_free_at` rather
    // than re-derived per candidate, and it does NOT alter `value_free_at`
    // itself: shortening live ranges globally would change register allocation
    // in every function, which is a different change with its own measurement
    // to earn.
    //
    // REACH, COUNTED AND NOT ASSUMED. `IDOL_TIGHTDEF_REPORT` over the whole
    // corpus — every `.id` under `examples/`, `lib/` and `scripts/` outside
    // `compile_fail/`, 921 files, 231 of which reach this backend — admits
    // ZERO pairs. Not one corpus program has both an unrolled loop and a
    // compare feeding a branch inside it. So this changes no byte of any
    // artifact the corpus builds today, and the 0-difference corpus answer
    // check that accompanies it proves the absence of a regression rather than
    // the presence of a win. What it is worth is 1.046x on the shape above,
    // which the default 4x unroller manufactures out of any such loop.
    // ------------------------------------------------------------------
    fn computeTightReads(self: *Arm64Compiler, f: dnir.Function) Error!void {
        self.loose_read_values.clearRetainingCapacity();
        var targets: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer targets.deinit(self.alloc);
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op != .br) continue;
                try targets.put(self.alloc, ins.branch_target, {});
            }
        }
        const Sink = struct {
            set: *std.AutoHashMapUnmanaged(u32, void),
            alloc: std.mem.Allocator,
            prev: ?dnir.Instr,
            entered: bool,
            failed: bool = false,
            fn note(s: *@This(), id: u32) void {
                const attributable = !s.entered and if (s.prev) |p|
                    Arm64Compiler.instructionDefinesId(p, id)
                else
                    false;
                if (attributable) return;
                s.set.put(s.alloc, id, {}) catch {
                    s.failed = true;
                };
            }
        };
        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs, 0..) |ins, p| {
                var sink: Sink = .{
                    .set = &self.loose_read_values,
                    .alloc = self.alloc,
                    .prev = if (p == 0) null else b.instrs[p - 1],
                    .entered = targets.contains(idx),
                };
                forEachOperandId(ins, &sink, Sink.note);
                if (sink.failed) return error.OutOfMemory;
                idx += 1;
            }
        }
    }

    /// Census only: this fusion was admitted by the tight-def fact and would
    /// have been refused by the index test alone.
    fn countTightDefAdmission(self: *Arm64Compiler, ins: dnir.Instr, flat_idx: u32) void {
        const t = ins.result orelse return;
        const last = self.value_free_at.get(t) orelse return;
        if (last != flat_idx + 1) self.tightdef_admitted += 1;
    }

    /// Is `t`'s definition at `flat_idx` read ONLY by the instruction at
    /// `flat_idx + 1`? `value_free_at` answers it directly when ids are unique;
    /// the tight-def fact answers it when the unroller has reused them.
    fn singleReaderByTightDef(self: *const Arm64Compiler, t: u32, flat_idx: u32) bool {
        const last = self.value_free_at.get(t) orelse return false;
        if (last == flat_idx + 1) return true;
        if (!self.tightdef) return false;
        return !self.loose_read_values.contains(t);
    }

    fn widenValueLastUses(
        value_free_at: *std.AutoHashMapUnmanaged(u32, u32),
        reads: []const [2]u32,
        def_at: *const std.AutoHashMapUnmanaged(u32, u32),
        back: []const [2]u32,
        forward: []const [2]u32,
    ) void {
        // This is a finite monotone dataflow problem: every update moves an end
        // to one of the function's back-edge tails. Iterate to the actual
        // fixpoint. A fixed round limit made CFG shape select a different,
        // all-function fallback even though convergence was still progressing.
        var changed = true;
        while (changed) {
            changed = false;
            var it = value_free_at.iterator();
            while (it.next()) |e| {
                const definition = def_at.get(e.key_ptr.*);
                for (back) |edge| {
                    const head = edge[0];
                    const tail = edge[1];
                    const begins_before = if (definition) |def| blk: {
                        if (def < head) break :blk true;
                        for (reads) |read| {
                            // Operands are read before an instruction publishes
                            // its result. An update that reads and redefines the
                            // same id at `def` therefore carries the entering
                            // value just as surely as an earlier instruction.
                            if (read[0] == e.key_ptr.* and read[1] >= head and read[1] <= def) break :blk true;
                        }
                        for (forward) |jump| {
                            if (jump[0] >= head and jump[0] < def and jump[1] > def and
                                jump[1] <= tail and jump[1] <= e.value_ptr.*) break :blk true;
                        }
                        break :blk false;
                    }
                    else
                        true;
                    if (begins_before and e.value_ptr.* >= head and e.value_ptr.* < tail) {
                        e.value_ptr.* = tail;
                        changed = true;
                    }
                }
            }
        }
    }

    /// Last instruction index that reads each id, widened so that no live range
    /// ends inside a loop it did not start in. See the `value free at` field.
    fn computeValueLastUse(self: *Arm64Compiler, f: dnir.Function) Error!void {
        self.value_free_at.clearRetainingCapacity();
        self.premask_elided.clearRetainingCapacity();
        self.fp_abi_passthrough.clearRetainingCapacity();
        var reads: std.ArrayList([2]u32) = .empty;
        defer reads.deinit(self.alloc);
        var def_at: std.AutoHashMapUnmanaged(u32, u32) = .empty;
        defer def_at.deinit(self.alloc);
        var back: std.ArrayList([2]u32) = .empty;
        defer back.deinit(self.alloc);
        var forward: std.ArrayList([2]u32) = .empty;
        defer forward.deinit(self.alloc);

        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                const Sink = struct {
                    map: *std.AutoHashMapUnmanaged(u32, u32),
                    alloc: std.mem.Allocator,
                    at: u32,
                    failed: bool = false,
                    fn note(s: *@This(), id: u32) void {
                        s.map.put(s.alloc, id, s.at) catch {
                            s.failed = true;
                        };
                    }
                };
                var sink: Sink = .{ .map = &self.value_free_at, .alloc = self.alloc, .at = idx };
                forEachOperandId(ins, &sink, Sink.note);
                if (sink.failed) return error.OutOfMemory;
                const ReadSink = struct {
                    list: *std.ArrayList([2]u32),
                    alloc: std.mem.Allocator,
                    at: u32,
                    failed: bool = false,
                    fn note(s: *@This(), id: u32) void {
                        s.list.append(s.alloc, .{ id, s.at }) catch {
                            s.failed = true;
                        };
                    }
                };
                var read_sink: ReadSink = .{ .list = &reads, .alloc = self.alloc, .at = idx };
                forEachOperandId(ins, &read_sink, ReadSink.note);
                if (read_sink.failed) return error.OutOfMemory;
                if (dnir.definition(ins)) |r| {
                    if (!def_at.contains(r)) try def_at.put(self.alloc, r, idx);
                }
                for (ins.pack_results) |result| {
                    const temp = result.temp orelse continue;
                    if (!def_at.contains(temp)) try def_at.put(self.alloc, temp, idx);
                }
                switch (ins.op) {
                    .br => {
                        if (ins.branch_target <= idx) {
                            try back.append(self.alloc, .{ ins.branch_target, idx });
                        } else {
                            try forward.append(self.alloc, .{ idx, ins.branch_target });
                        }
                    },
                    else => {},
                }
                idx += 1;
            }
        }

        // Staged GP marshaling (`mov_arg` slot 0 → `call_direct` void lhs) must
        // keep the operand live through the call — same regalloc contract as an
        // inline lhs on `call_direct`. Otherwise compact and staged DNIR diverge
        // in emitted bytes even when the physical ABI work is identical.
        idx = 0;
        for (f.blocks) |block| {
            const instrs = block.instrs;
            for (instrs, 0..) |ins, i| {
                if (i + 1 < instrs.len) {
                    const next = instrs[i + 1];
                    if (ins.op == .mov_arg and ins.result == 0 and next.op == .call_direct and
                        next.lhs == .void and next.application != null)
                    {
                        const operand_id: ?u32 = switch (ins.lhs) {
                            .local, .temp => |id| id,
                            else => null,
                        };
                        if (operand_id) |id| {
                            if (self.value_free_at.get(id)) |last| {
                                if (last == idx) {
                                    try self.value_free_at.put(self.alloc, id, idx + 1);
                                }
                            }
                        }
                    }
                }
                idx += 1;
            }
        }

        // A VARIADIC-TAIL `mov_arg` DOES NOT READ ITS OPERAND. It records it —
        // `pending_varargs[idx].operand = ins.lhs` — and the register is not
        // read until `materializePendingVarargs`, which runs inside the CALL
        // that consumes the tail. The scan above stops a value's range at the
        // instruction that mentions it, so a staged operand died one instruction
        // before its only real use, `sweepGpLive` handed the register back, and
        // the call's own format string was allocated straight into it.
        //
        // MEASURED, on the canonical backend, `stdout:write("A=" .. idr(idr("V")) .. "\n")`:
        //
        //     mov  x9, x0                 ; outer idr result -> x9   (the hole)
        //     adrp x9, … ; add x9, …      ; "A=%s\n\n"        -> x9   (CLOBBER)
        //     mov  x0, x9                 ; format string to the format slot
        //     str  x9, [sp]               ; …and the tail gets the format string
        //
        // which printed `A=A=%s\n\n\n\n`. The format string was passed as its own
        // argument. One `..` hole that is a NESTED call is enough: the inner call
        // puts x0 in the outer call's save set, so the outer result is homed at
        // x9 instead of staying in x0, and x9 is exactly what `allocReg` hands
        // out next.
        //
        // The fix is the liveness fact, not a register preference: a staged
        // operand is live until the call reads it. Widen to the consuming call,
        // which is the next call instruction at or after the staging — never
        // past a block boundary, because `pending_varargs` is cleared per call.
        var base: u32 = 0;
        for (f.blocks) |block| {
            const instrs = block.instrs;
            defer base += @intCast(instrs.len);
            for (instrs, 0..) |ins, i| {
                if (ins.op != .mov_arg and ins.op != .fp_mov_arg) continue;
                if (!std.mem.eql(u8, ins.field, "vararg")) continue;
                const operand_id: u32 = switch (ins.lhs) {
                    .local, .temp => |id| id,
                    else => continue,
                };
                var j = i + 1;
                const consumer: ?u32 = while (j < instrs.len) : (j += 1) {
                    switch (instrs[j].op) {
                        .call_direct, .call_extern => break base + @as(u32, @intCast(j)),
                        // Anything that is not staging is not part of this tail;
                        // an unterminated run stages nothing and needs no widening.
                        .mov_arg, .fp_mov_arg => {},
                        else => break null,
                    }
                } else null;
                const at = consumer orelse continue;
                const last = self.value_free_at.get(operand_id) orelse continue;
                if (last < at) try self.value_free_at.put(self.alloc, operand_id, at);
            }
        }

        // A range that STARTS before a loop and ENDS inside it must survive to
        // the back edge, or the next iteration reads a register that the tail of
        // the body has already reused. Nested loops make one pass insufficient:
        // widening to an inner back edge can drag a range into an outer one, so
        // iterate to a fixpoint (bounded — every step only moves ends forward).
        widenValueLastUses(&self.value_free_at, reads.items, &def_at, back.items, forward.items);

        // Keep a checked f64 result in d0 only when the next instruction
        // immediately consumes it as an ABI argument or function result.
        // Otherwise a later call may overwrite d0, and store_local would
        // incorrectly make the ABI register look like stable storage.
        var previous_call_result: ?u32 = null;
        idx = 0;
        for (f.blocks) |block| {
            for (block.instrs) |instruction| {
                if (previous_call_result) |result| {
                    const direct_consumer = instruction.op == .fp_mov_arg or instruction.op == .ret;
                    if (direct_consumer and
                        self.value_free_at.get(result) == idx and
                        instructionReadsId(instruction, result))
                    {
                        try self.fp_abi_passthrough.put(self.alloc, result, {});
                    }
                }
                previous_call_result = switch (instruction.op) {
                    .call_direct, .call_extern => instruction.result,
                    else => null,
                };
                idx += 1;
            }
        }
    }

    /// Instructions a `mov`/`movk` chain needs to materialize `value` — the
    /// count of nonzero 16-bit lanes (minimum one). Used to spend a bounded
    /// hoist-register budget on the constants whose re-materialization costs the
    /// most per loop iteration.
    fn immCost(value: i64) u8 {
        const u: u64 = @bitCast(value);
        var parts: u8 = 0;
        var shift: u6 = 0;
        while (true) {
            if (((u >> shift) & 0xffff) != 0) parts += 1;
            if (shift == 48) break;
            shift += 16;
        }
        return if (parts == 0) 1 else parts;
    }

    /// Plan loop-invariant immediate hoisting: for every natural loop (a `br`
    /// whose target is at or before it), collect the distinct `.i64` constants
    /// its body re-materializes and keep the most expensive up to the budget.
    /// Constants are loop-invariant by definition, so no dependence analysis is
    /// required — the only question is register budget.
    fn planImmHoist(self: *Arm64Compiler, f: dnir.Function) Error!void {
        self.hoist_plan.clearRetainingCapacity();
        if (self.gate_transport) return;

        var heads: std.AutoHashMapUnmanaged(u32, u32) = .empty; // head -> furthest latch
        defer heads.deinit(self.alloc);
        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op == .br and ins.branch_target <= idx) {
                    const head = ins.branch_target;
                    const prev = heads.get(head) orelse 0;
                    if (idx > prev) try heads.put(self.alloc, head, idx);
                }
                idx += 1;
            }
        }
        if (heads.count() == 0) return;

        var hit = heads.iterator();
        while (hit.next()) |e| {
            const head = e.key_ptr.*;
            const latch = e.value_ptr.*;
            var plan: HoistPlan = .{ .latch = latch };
            idx = 0;
            scan: for (f.blocks) |b| {
                for (b.instrs) |ins| {
                    if (idx >= head and idx <= latch) {
                        for ([_]dnir.Value{ ins.lhs, ins.rhs }) |v| {
                            switch (v) {
                                .i64 => |n| self.considerHoist(&plan, n),
                                else => {},
                            }
                        }
                        // The floored-magic multiplier is a pure function of the
                        // literal divisor and appears nowhere in dnir, so the
                        // operand scan above never plans it. Same admission as
                        // the emitter (magicFlooredDivisor), so plan and emission
                        // cannot disagree on which divisors get a hoisted magic.
                        if (ins.op == .binop and (ins.binop == .div or ins.binop == .idiv or ins.binop == .mod) and ins.rhs == .i64) {
                            const k: i64 = ins.rhs.i64;
                            if (magicFlooredDivisor(k)) |mg| self.considerHoist(&plan, mg.m);
                        }
                    }
                    idx += 1;
                    if (idx > latch) break :scan;
                }
            }
            if (plan.count > 0) try self.hoist_plan.put(self.alloc, head, plan);
        }
    }

    /// Add constant `n` to a loop's hoist plan, deduping and — once the budget
    /// is full — evicting the cheapest resident constant when `n` costs more.
    fn considerHoist(self: *Arm64Compiler, plan: *HoistPlan, n: i64) void {
        _ = self;
        var k: u8 = 0;
        while (k < plan.count) : (k += 1) if (plan.values[k] == n) return;
        if (plan.count < max_hoist_per_loop) {
            plan.values[plan.count] = n;
            plan.count += 1;
            return;
        }
        var mink: u8 = 0;
        var mincost = immCost(plan.values[0]);
        var j: u8 = 1;
        while (j < plan.count) : (j += 1) {
            const c = immCost(plan.values[j]);
            if (c < mincost) {
                mincost = c;
                mink = j;
            }
        }
        if (immCost(n) > mincost) plan.values[mink] = n;
    }

    /// At a loop head (in emission order, once per compile), pre-materialize the
    /// planned constants into reserved home registers. Emitting BEFORE the head's
    /// `code_offsets` entry means the back edge re-enters AFTER these movs, so the
    /// constants are computed once on fall-in and reused every iteration.
    ///
    /// FALL-IN IS NOT THE ONLY WAY IN, and assuming it was is what made this a
    /// wrong answer rather than a missed optimization. A head is also entered by
    /// any FORWARD branch that targets it, and an `if` immediately before a loop
    /// produces two of them. Record where the preheader starts so the patch pass
    /// can send those entries through it; a head that hoisted nothing records
    /// nothing and every branch to it keeps the head offset.
    fn immHoistEnter(self: *Arm64Compiler, flat_idx: u32) Error!void {
        const plan = self.hoist_plan.get(flat_idx) orelse return;
        if (self.hoist_depth >= max_hoist_depth) return;
        const preheader_off: u32 = @intCast(self.code.items.len);
        var active: HoistActive = .{ .latch = plan.latch };
        var k: u8 = 0;
        while (k < plan.count) : (k += 1) {
            const v = plan.values[k];
            if (self.imm_hoist.contains(v)) continue; // enclosing loop already holds it
            const r = try self.allocReg();
            if (r < 9 or r >= 29 or r == platform_reserved_reg) {
                self.releaseReg(r);
                continue;
            }
            self.markGpHome(r);
            try self.emitMovImm(r, v);
            try self.imm_hoist.put(self.alloc, v, r);
            active.values[active.count] = v;
            active.regs[active.count] = r;
            active.count += 1;
        }
        if (self.code.items.len != preheader_off) {
            try self.hoist_preheader.put(self.alloc, flat_idx, preheader_off);
        }
        self.hoist_active[self.hoist_depth] = active;
        self.hoist_depth += 1;
    }

    /// Once emission has passed a loop's latch, release its reserved registers
    /// so the loop-exit code and any sibling loop can reuse them.
    ///
    /// A RELEASE THAT LEAVES THE SPILL ENTRY GIVES THE REGISTER BACK TO NOBODY.
    ///
    /// The three lines below are the whole release, and they are the release of
    /// a register that is still IN one: `gp_home_regs`, `gp_reg_owner`, and
    /// `used_regs` are exactly the records `markGpHome` wrote, and none of them
    /// is what keeps a spilled register out of the pool. `spilled_regs` is —
    /// both free scans in `allocRegExcluding` skip anything that map contains,
    /// which is the fail-closed guard that stands in for the claim `spillReg`
    /// dropped. So a hoist home that was spilled came out of this loop with
    /// `used_regs` clear, no home flag, no owner, and an entry that makes every
    /// scan pass over it: unallocatable for the rest of the function, on the one
    /// path whose whole job is to hand the register back. Its frame slot goes
    /// the same way — `ensureRegLive` and `ensureRegLiveRemap` are that slot's
    /// only readers and both key on the entry, so nothing can read it again,
    /// while holding it keeps `spillReg` stepping `gate_spill_cursor` toward
    /// `gate_spill_end` and refusing spills the pre-reserved area still had room
    /// for. Both are the failure `reclaimSpilledReg` records, reached through
    /// the unwind instead, and only that emergency reclaim could still take the
    /// entry — once the home flag above cleared, which is what let it.
    ///
    /// Only a LEAF's hoist home can be here. The first spill pass in
    /// `allocRegExcluding` skips every home and the second skips
    /// `gp_call_home_regs`, which a calling function sets for its whole bank and
    /// a leaf never sets, so a hoisted constant's reserved register is a victim
    /// exactly where `gp_call_home_regs` says a leaf home is one.
    ///
    /// The value is not owed a reload, which is why the entry may simply go:
    /// `imm_hoist` is the only reader of a hoisted constant's register
    /// (`evalDnirValue`'s three constant arms and `constRetImm`), the loop above
    /// removes that entry in the same step, and `immHoistEnter` never re-hoists
    /// a constant an enclosing loop already holds, so no surviving entry names
    /// `r`. Releasing the slot on the removal that actually took the entry is
    /// what `sweepGpLive` and `releaseReg` both already do; this makes the third
    /// path agree. Not the closure — closure is authoritative `register`/`frame`
    /// assignment before emission, per GAP-148's record, under which a hoisted
    /// constant's location is carried by the assignment rather than restated by
    /// a map the unwind has to remember to clear.
    fn immHoistExit(self: *Arm64Compiler, flat_idx: u32) void {
        while (self.hoist_depth > 0) {
            const top = self.hoist_active[self.hoist_depth - 1];
            if (flat_idx <= top.latch) break;
            var k: u8 = 0;
            while (k < top.count) : (k += 1) {
                const v = top.values[k];
                const r = top.regs[k];
                if (self.imm_hoist.get(v)) |cur| {
                    if (cur == r) _ = self.imm_hoist.remove(v);
                }
                self.gp_home_regs[r] = false;
                self.gp_reg_owner[r] = null;
                self.unprotectReg(r);
                self.used_regs[r] = false;
                if (self.spilled_regs.fetchRemove(r)) |entry| {
                    self.free_spill_slots.append(self.alloc, entry.value) catch {};
                }
            }
            self.hoist_depth -= 1;
        }
    }

    /// The value band is the only part of the FP file a call preserves:
    /// `emitSaveCallerRegs` walks it from `fp_value_reg_base`, and d0..d7 are
    /// preserved by nothing. A register outside it cannot hold a value across
    /// an instruction that calls, so it cannot be a home.
    fn fpValueReg(reg: u5) bool {
        return reg >= fp_value_reg_base and reg < fp_value_reg_base + fp_value_reg_count;
    }

    /// This register is a local's home for the rest of the function.
    fn markFpHome(self: *Arm64Compiler, reg: u5) void {
        self.fp_home_regs[reg] = true;
        self.used_fp_regs[reg] = true;
    }

    /// Free every FP value register whose owner has no read left after `idx`.
    fn sweepFpLive(self: *Arm64Compiler, idx: u32) void {
        var reg: u5 = fp_value_reg_base;
        while (reg < fp_value_reg_base + fp_value_reg_count) : (reg += 1) {
            const owner = self.fp_reg_owner[reg] orelse continue;
            if (self.fp_home_regs[reg]) continue;
            const last = self.value_free_at.get(owner) orelse 0;
            if (last > idx) continue;
            self.fp_reg_owner[reg] = null;
            self.used_fp_regs[reg] = false;
        }
    }

    /// Does this `temps` name still stand for `id`'s claim on `reg`?
    ///
    /// The sweep above frees a float value register by owner record and leaves
    /// the `temps` name alone, so a name outlives the claim it stood for; the
    /// emission loop then writes `fp_reg_owner[r]` for whichever id took the
    /// register next. A PRESENT owner that is not `id` is exactly that re-let.
    /// An ABSENT owner is ordinary scratch — `releaseFpReg` returns above any
    /// owned register — and every writer of `fp_reg_owner` is already confined
    /// to the value band and skips homes, so neither needs restating here.
    fn foreignFpName(self: *const Arm64Compiler, reg: u5, id: u32) bool {
        const owner = self.fp_reg_owner[reg] orelse return false;
        return owner != id;
    }

    /// This register is a local's home for the rest of the function.
    fn markGpHome(self: *Arm64Compiler, reg: u5) void {
        if (reg < 9 or reg >= 29) return;
        if (reg == platform_reserved_reg) return;
        self.gp_home_regs[reg] = true;
        self.claimReg(reg);
        self.gp_reg_owner[reg] = null;
    }

    fn countGpHomes(self: *const Arm64Compiler) u32 {
        var n: u32 = 0;
        var reg: u5 = 9;
        while (reg < 29) : (reg += 1) {
            if (reg == platform_reserved_reg) continue;
            if (self.gp_home_regs[reg]) n += 1;
        }
        return n;
    }

    fn gpLocalNeedsStack(self: *const Arm64Compiler) bool {
        return self.countGpHomes() >= self.gp_local_home_budget;
    }

    /// Pre-pass: decide which GP locals spill to the stack when register homes
    /// are exhausted. Reserving at first store on one branch and restoring the
    /// whole frame on every `ret` imbalanced paths — `endpos = j` on the true
    /// branch reserved 8 bytes while the false branch still ran `add sp, #8`.
    fn planGpStackLocals(self: *Arm64Compiler, f: dnir.Function, body_has_call: bool) Error!void {
        self.gp_stack_locals.clearRetainingCapacity();
        var home_count: u32 = 0;
        var homed_slots: std.AutoHashMapUnmanaged(u32, void) = .empty;
        defer homed_slots.deinit(self.alloc);
        var param_slots: u32 = 0;
        for (f.params) |p| {
            var slots_for_param: u32 = 1;
            if (p.record) |rec_name| {
                if (scalRecordDesc(self.scal_records, rec_name)) |rec| {
                    slots_for_param = @intCast(rec.field_names.len);
                }
            }
            param_slots += slots_for_param;
        }
        // A CALL DOES NOT REQUIRE A LOCAL TO LIVE IN MEMORY.
        //
        // It requires the local's home to survive `bl`, and this used to be met
        // by giving EVERY local in a calling function a frame slot: every read a
        // `ldr`, every write a `str`, on every path including a loop body. The
        // hazard the memory form was answering is real and is named below —
        // "Any call clobbers x0–x17. Locals left in caller-saved homes made
        // `bare`'s `n` a heap pointer, so `sub` malloc'd gigabytes" — but the
        // frame is not the only storage a `bl` cannot touch. AAPCS64 has ten
        // registers with exactly that property, x19–x28, and the prologue
        // already saves precisely the ones a body claims (`callee_save_plan`,
        // measured by `probeCalleeSaveUse`).
        //
        // MEASURED, on `benchmarks/cyc/w/ilp4.id`'s loop — four carried values
        // plus a counter, one call in the function and it is before the loop:
        //
        //     ldr x12, [sp, #0x18] / ldr x13, [sp, #0x38]   ; reload a, i
        //     eor x14, x12, x13 / mul x12, x14, x9 / and x13, x12, x10
        //     str x13, [sp, #0x18]                          ; and store a back
        //
        // — x4, plus the counter's own round trip, per iteration. The round trip
        // is not free even out of L1: benchmarks/cyc PROBE 11 minus PROBE 5 puts
        // four of them in an issue-dense loop at +4.563 cyc/op, which is the
        // whole of that row's distance from its answer-checked floor.
        //
        // So the question the plan asks changes from "does this function call?"
        // to "is there a register left that a call cannot reach?", and only the
        // surplus past `gp_call_home_budget` still goes to the frame.
        //
        // GATE TRANSPORT KEEPS THE MEMORY FORM. Those bodies call `gatecap`/`sh`
        // repeatedly under a raised home budget (`gp_local_home_budget = 32`)
        // and their spilled-register reclaim path (`reclaimSpilledReg`) hands
        // out registers the pinned map still names; a register home there would
        // be reclaimed under its owner. That is a separate defect from this one
        // and it is not this change's to take.
        const gate_spill_all_locals = self.gate_transport and body_has_call;
        self.gate_param_slots = if (gate_spill_all_locals) @max(param_slots, 1) else 0;
        const home_budget: u32 = if (body_has_call)
            @min(self.gp_call_home_budget, self.gp_local_home_budget)
        else
            self.gp_local_home_budget;

        const planSlot = struct {
            fn go(
                ctx: *Arm64Compiler,
                slot: u32,
                homes_used: *u32,
                homed: *std.AutoHashMapUnmanaged(u32, void),
                force_stack: bool,
                force_reason: []const u8,
                budget: u32,
            ) Error!void {
                if (homed.contains(slot)) return;
                // Gate scripts call gatecap/sh repeatedly; every local must
                // reload from the prologue stack frame after each call.
                if (force_stack) {
                    // Offset is the slot id, not insertion order. A bump from
                    // `count()*8` gave `i` and the `and` temp the same home.
                    if (slot > 4094) return error.RegisterExhausted;
                    const off: u16 = @intCast(slot * 8);
                    try ctx.gp_stack_locals.put(ctx.alloc, slot, off);
                    // The REASON is the fact worth recording, not the fact that
                    // something was spilled: gate transport and an unpromotable
                    // parameter reach this by different rules, and a ledger that
                    // spells both "gate transport" cannot tell a test which one
                    // it just observed.
                    try ctx.cost.record(ctx.alloc, .stack_local, force_reason);
                } else if (homes_used.* >= budget) {
                    if (slot > 4094) return error.RegisterExhausted;
                    const off: u16 = @intCast(slot * 8);
                    try ctx.gp_stack_locals.put(ctx.alloc, slot, off);
                    try ctx.cost.record(
                        ctx.alloc,
                        .stack_local,
                        "GP home budget exhausted; local spilled to stack frame",
                    );
                } else {
                    try homed.put(ctx.alloc, slot, {});
                    homes_used.* += 1;
                }
            }
        }.go;

        var slot_cursor: u32 = 0;
        for (f.params) |p| {
            var slots_for_param: u32 = 1;
            if (p.record) |rec_name| {
                if (scalRecordDesc(self.scal_records, rec_name)) |rec| {
                    slots_for_param = @intCast(rec.field_names.len);
                }
            }
            var k: u32 = 0;
            while (k < slots_for_param) : (k += 1) {
                if (body_has_call) {
                    // A PARAMETER KEEPS ITS FRAME SLOT, unchanged from before
                    // this lane. Its incoming register has to be vacated either
                    // way, so the only question a home answers for it is where
                    // the copy lands — and a parameter that is never reassigned
                    // gains nothing per iteration to repay the prologue
                    // save/restore its home would cost.
                    try planSlot(
                        self,
                        slot_cursor,
                        &home_count,
                        &homed_slots,
                        true,
                        "parameter is not loop-carried; kept in the stack frame",
                        home_budget,
                    );
                } else {
                    try homed_slots.put(self.alloc, slot_cursor, {});
                }
                slot_cursor += 1;
            }
        }

        // A HOME IS EARNED BY BEING CARRIED, in a function that calls.
        //
        // The home is not free there: it costs a `str` in the prologue and an
        // `ldr` in the epilogue, because the register it takes is one the callee
        // must give back. A local ASSIGNED INSIDE A LOOP repays that once per
        // iteration and the loop makes the trade unbounded. A local assigned on
        // a straight line repays it at most once and usually not at all — and
        // three of `gate/edge.sh`'s static ledger entries measured exactly that
        // loss when every local was eligible: `LAW len/str-world` 28 -> 31,
        // `LAW to/str` 47 -> 52, `CONTROL glue/len-world` 28 -> 31, all of it
        // prologue.
        //
        // So the first pass admits only the slots stored inside a loop body.
        // That is the defect's own definition — "every carried local, stored and
        // reloaded on every assignment" — rather than a proxy for it, and a
        // function with no loop is left exactly as it was.
        var loop_ranges: std.ArrayList([2]u32) = .empty;
        defer loop_ranges.deinit(self.alloc);
        {
            var idx: u32 = 0;
            for (f.blocks) |b| {
                for (b.instrs) |ins| {
                    if (ins.op == .br and ins.branch_target <= idx) {
                        try loop_ranges.append(self.alloc, .{ ins.branch_target, idx });
                    }
                    idx += 1;
                }
            }
        }
        self.cur_loop_ranges.clearRetainingCapacity();
        try self.cur_loop_ranges.appendSlice(self.alloc, loop_ranges.items);
        var pass: u8 = 0;
        while (pass < 2) : (pass += 1) {
            // Pass 1 is loop-stored slots only. Pass 2 admits the rest, and runs
            // ONLY for a leaf — where a home costs nothing to save and the old
            // budget rule already handed them out.
            if (pass == 1 and body_has_call) break;
            if (pass == 0) {
                // Homes follow estimated traffic, not nesting depth alone.
                // Deepest-first spent the budget inside the innermost loop even
                // when the outer loop's carried values dominate the traffic:
                // hashtable's 4M-iteration lookup loop spilled its counter, LCG
                // state, key, index and probe count ~12x per iteration while the
                // ~1-trip probe loop's locals held the homes (-8% measured).
                // A slot whose live range crosses exactly one further nesting
                // level is admitted first: the value is live across that whole
                // nested region, so spilling it costs traffic at the outer rate
                // with no inner-loop amortization. The single-level bound is
                // load-bearing: a slot live across several levels pins its
                // register through every nested region, and qsort's rep/gap
                // showed that pinning ten such slots exhausts the allocator
                // (RegisterExhausted in the probe, ladder forced down to 6).
                // Inside each tier the deeper store still wins, so qsort's
                // inner-while locals keep the homes deepest-first earned them
                // (+26% measured).
                const Cand = struct { slot: u32, depth: u32, cross: bool };
                var cands: std.ArrayListUnmanaged(Cand) = .empty;
                defer cands.deinit(self.alloc);
                var first_store: std.AutoHashMapUnmanaged(u32, u32) = .empty;
                defer first_store.deinit(self.alloc);
                var last_use: std.AutoHashMapUnmanaged(u32, u32) = .empty;
                defer last_use.deinit(self.alloc);
                {
                    var idx: u32 = 0;
                    for (f.blocks) |b| {
                        for (b.instrs) |ins| {
                            defer idx += 1;
                            const fixed = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
                            for (fixed) |v| switch (v) {
                                .local => |slot| {
                                    const lu = last_use.get(slot);
                                    if (lu == null or idx > lu.?) try last_use.put(self.alloc, slot, idx);
                                },
                                else => {},
                            };
                            for (ins.vals) |v| switch (v) {
                                .local => |slot| {
                                    const lu = last_use.get(slot);
                                    if (lu == null or idx > lu.?) try last_use.put(self.alloc, slot, idx);
                                },
                                else => {},
                            };
                            if (ins.op != .store_local) continue;
                            const slot = ins.result orelse continue;
                            if (ins.ty == .f64 or self.valueIsFp(ins.lhs)) continue;
                            if (ins.application == null and !self.value_free_at.contains(slot)) switch (ins.lhs) {
                                .i64 => continue,
                                else => {},
                            };
                            const fs = first_store.get(slot);
                            if (fs == null or idx < fs.?) try first_store.put(self.alloc, slot, idx);
                        }
                    }
                }
                var idx: u32 = 0;
                for (f.blocks) |b| {
                    for (b.instrs) |ins| {
                        defer idx += 1;
                        if (ins.op != .store_local) continue;
                        const slot = ins.result orelse continue;
                        if (ins.ty == .f64 or self.valueIsFp(ins.lhs)) continue;
                        if (ins.application == null and !self.value_free_at.contains(slot)) switch (ins.lhs) {
                            .i64 => continue,
                            else => {},
                        };
                        var depth: u32 = 0;
                        for (loop_ranges.items) |r| {
                            if (idx >= r[0] and idx <= r[1]) depth += 1;
                        }
                        if (body_has_call and depth == 0) continue;
                        var max_rd: u32 = 0;
                        if (first_store.get(slot)) |fs| {
                            if (last_use.get(slot)) |lu| {
                                for (loop_ranges.items) |r| {
                                    if (fs < r[0] and lu > r[0]) {
                                        var rd: u32 = 0;
                                        for (loop_ranges.items) |r2| {
                                            if (r[0] >= r2[0] and r[0] <= r2[1]) rd += 1;
                                        }
                                        max_rd = @max(max_rd, rd);
                                    }
                                }
                            }
                        }
                        const cross = max_rd == depth + 1;
                        try cands.append(self.alloc, .{ .slot = slot, .depth = depth, .cross = cross });
                    }
                }
                var tier: u8 = 0;
                while (tier < 2) : (tier += 1) {
                    const want_cross = tier == 0;
                    var max_depth: u32 = 0;
                    for (cands.items) |c| {
                        if (c.cross == want_cross) max_depth = @max(max_depth, c.depth);
                    }
                    var d: u32 = max_depth + 1;
                    while (d > 1) {
                        d -= 1;
                        for (cands.items) |c| {
                            if (c.cross != want_cross or c.depth != d) continue;
                            try planSlot(
                                self,
                                c.slot,
                                &home_count,
                                &homed_slots,
                                gate_spill_all_locals,
                                "gate transport local spilled to stack frame",
                                home_budget,
                            );
                        }
                    }
                }
            } else {
                var idx: u32 = 0;
                for (f.blocks) |b| {
                    for (b.instrs) |ins| {
                        defer idx += 1;
                        if (ins.op != .store_local) continue;
                        const slot = ins.result orelse continue;
                        if (ins.ty == .f64 or self.valueIsFp(ins.lhs)) continue;
                        if (ins.application == null and !self.value_free_at.contains(slot)) switch (ins.lhs) {
                            .i64 => continue,
                            else => {},
                        };
                        try planSlot(
                            self,
                            slot,
                            &home_count,
                            &homed_slots,
                            gate_spill_all_locals,
                            "gate transport local spilled to stack frame",
                            home_budget,
                        );
                    }
                }
            }
        }

        // Everything the passes above did not admit still needs a frame slot.
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op != .store_local) continue;
                const slot = ins.result orelse continue;
                if (ins.ty == .f64 or self.valueIsFp(ins.lhs)) continue;
                // In a calling body, every unread local still needs a frame home
                // because a later read may arrive through aggregate access on a
                // table/record binding — skipping dead-looking i64 stores left
                // high slot numbers with no home and eval refused at `local 30`.
                if (!body_has_call) {
                    if (ins.application == null and !self.value_free_at.contains(slot)) switch (ins.lhs) {
                        .i64 => continue,
                        else => {},
                    };
                }
                if (homed_slots.contains(slot) or self.gp_stack_locals.contains(slot)) continue;
                if (slot > 4094) return error.RegisterExhausted;
                try self.gp_stack_locals.put(self.alloc, slot, @intCast(slot * 8));
                try self.cost.record(
                    self.alloc,
                    .stack_local,
                    "local not carried across a loop; kept in the stack frame",
                );
            }
        }
    }

    fn reserveGpStackLocal(self: *Arm64Compiler, slot: u32) Error!u16 {
        return self.gp_stack_locals.get(slot) orelse error.RegisterExhausted;
    }

    fn loadGpStackLocal(self: *Arm64Compiler, off: u16) Error!u5 {
        const reg = try self.allocReg();
        // GP spill slots live in the prologue's bottom `sub sp` region; offsets
        // are assigned from sp upward (0, 8, 16, …), not from the frame top.
        try self.emitLdrFrame(reg, off);
        return reg;
    }

    fn storeGpStackLocal(self: *Arm64Compiler, off: u16, src: u5) Error!void {
        try self.emitStrFrame(src, off);
    }

    /// Free every GP temp register whose owner has no read left after `idx`.
    fn sweepGpLive(self: *Arm64Compiler, idx: u32) void {
        // Per-instruction scope: no emitter local survives past this point,
        // so every hand-out is re-derived (and re-held) by the next emitter.
        // A live temp's register is therefore spillable again here exactly
        // when no emitter holds it raw, which is the benign case.
        self.held_regs = 0;
        var reg: u5 = 0;
        while (reg < 29) : (reg += 1) {
            if (reg == platform_reserved_reg) continue;
            const owner = self.gp_reg_owner[reg] orelse continue;
            if (reg >= 9 and self.gp_home_regs[reg]) continue;
            const last = self.value_free_at.get(owner) orelse 0;
            if (last > idx) continue;
            self.gp_reg_owner[reg] = null;
            self.used_regs[reg] = false;
            if (self.spilled_regs.fetchRemove(reg)) |entry| {
                self.free_spill_slots.append(self.alloc, entry.value) catch {};
            }
        }
        // A spilled temporary whose last read is behind emission holds no
        // register, so the sweep above cannot see it: retire its frame slot
        // here so the slot rejoins the pool. `value_free_at` records every
        // operand occurrence, so an id with no entry was never read and is
        // dead by the same reading the register sweep uses.
        while (true) {
            var victim: ?u32 = null;
            var vit = self.temp_frame_slots.iterator();
            while (vit.next()) |entry| {
                const last = self.value_free_at.get(entry.key_ptr.*) orelse 0;
                if (last <= idx) {
                    victim = entry.key_ptr.*;
                    break;
                }
            }
            const t = victim orelse break;
            const slot = self.temp_frame_slots.fetchRemove(t).?.value;
            self.free_spill_slots.append(self.alloc, slot) catch {};
        }
    }

    fn regIsPinned(pinned: *const std.AutoHashMapUnmanaged(u32, u5), reg: u5) bool {
        var it = pinned.valueIterator();
        while (it.next()) |slot_reg| {
            if (slot_reg.* == reg) return true;
        }
        return false;
    }

    /// The same question `regIsPinned` answers, asked by a function that was
    /// never handed the map.
    ///
    /// `eval_pinned` is the pin map of the function being lowered, and it
    /// exists because `evalDnirValue` consults it before `temps`. Anything that
    /// MOVES a value between registers owes the same reader the same fact, and
    /// `ensureRegLiveRemap` is the only such mover that cannot rewrite the map
    /// it would invalidate. Null outside a function body, where there is no pin
    /// to honour.
    fn evalPinNames(self: *const Arm64Compiler, reg: u5) bool {
        const pinned = self.eval_pinned orelse return false;
        return regIsPinned(pinned, reg);
    }

    /// The same walk over the map `evalDnirValue` reads SECOND. `temps` names a
    /// register for a value with no `gp_reg_owner` whenever the ABI placed that
    /// value in x0..x7. Null outside a function body, where there is no
    /// evaluation whose reads a frame slot could still serve.
    fn evalTempNames(self: *const Arm64Compiler, reg: u5) bool {
        const temps = self.eval_temps orelse return false;
        return regIsPinned(temps, reg);
    }

    /// Does this `temps` name still stand for `id`'s claim on `reg`?
    ///
    /// `temps` entries outlive the claims they stood for — `emitPopVarargs`
    /// releases scratch the map still names and `sweepGpLive` frees by owner
    /// record while leaving the name alone — so the name alone cannot say. A
    /// VALID name carries its owner: the emission loop rebinds `gp_reg_owner[r]`
    /// to the defining id after every value instruction, so ownerless or
    /// otherwise-owned in the allocatable band is exactly a name whose claim is
    /// gone. Homes and pins restate their claims in other maps and the ABI bank
    /// is `preserveArgReg`'s to guard, so the test is that band only.
    fn staleGpName(self: *const Arm64Compiler, reg: u5, id: u32) bool {
        return reg >= 9 and reg < 29 and reg != platform_reserved_reg and
            !self.gp_home_regs[reg] and self.gp_reg_owner[reg] != id;
    }

    /// The register a local's value is IN, out of the two maps that name one.
    ///
    /// The same two facts `evalDnirValue` reads for a `.local`, in the same
    /// order: `pinned` first, then a `temps` name that is still that local's.
    /// A stale name is not a location on either side of a store.
    fn gpLocalHomeReg(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        slot: u32,
    ) ?u5 {
        if (pinned.get(slot)) |reg| return reg;
        const named = temps.get(slot) orelse return null;
        if (self.staleGpName(named, slot)) return null;
        return named;
    }

    fn compileDnirFunction(self: *Arm64Compiler, f: dnir.Function) Error!void {
        self.cur_func_name = f.name;
        self.fp_locals.clearRetainingCapacity();
        self.fp_temps.clearRetainingCapacity();
        // A staged variadic tail belongs to exactly one call. Carrying a
        // leftover across a function boundary would push a stale register onto
        // the next call's memory-argument area, so clear it with the rest of
        // the per-function register state.
        self.pending_vararg_count = 0;
        self.used_regs = @splat(false);
        self.used_fp_regs = @splat(false);
        self.fp_reg_owner = @splat(null);
        self.fp_home_regs = @splat(false);
        self.gp_reg_owner = @splat(null);
        self.gp_home_regs = @splat(false);
        self.gp_call_home_regs = 0;
        try self.computeValueLastUse(f);
        try self.computeTightReads(f);
        self.synth_value_next = maxDnirValueId(f) +| 1;
        self.imm_hoist.clearRetainingCapacity();
        self.hoist_preheader.clearRetainingCapacity();
        self.hoist_depth = 0;
        try self.planImmHoist(f);
        self.returned = false;
        self.fp_stack_slots.clearRetainingCapacity();
        self.stack_frame_bytes = 0;
        self.sp_temp_bytes = 0;
        self.frame_sealed = false;
        self.callee_save_bytes = 0;
        // `callee_save_plan` is set by the CALLER from the probe and must
        // survive this reset; what it measures must not.
        self.callee_touched = 0;
        self.spilled_regs.clearRetainingCapacity();
        self.temp_frame_slots.clearRetainingCapacity();
        self.free_spill_slots.clearRetainingCapacity();
        self.gp_stack_locals.clearRetainingCapacity();
        self.gate_spill_base = 0;
        self.gate_spill_end = 0;
        self.gate_spill_cursor = 0;
        self.gate_param_slots = 0;
        self.eval_pinned = null;
        self.eval_temps = null;
        self.held_regs = 0;
        self.cur_func_has_call = false;
        self.extern_preserve_x0 = false;
        self.extern_preserve_x0_temp = null;
        self.cur_func_ret_record = if (f.ret_record) |rn| scalRecordDesc(self.scal_records, rn) else null;
        self.cur_func_ret_pack = f.ret_pack;
        self.cur_func_ret_f64_record = if (f.ret_record) |rn| f64RecordDesc(self.f64_records, rn) else null;
        self.cur_ret_indirect_reg = null;
        self.cur_func_foreign = f.foreign_boundary;
        self.cur_func_float = f.is_float_kernel;
        self.cur_func_ret_float = f.ret == .f64 and !f.is_float_kernel;
        self.cur_func_ret = f.ret;

        const offset: u32 = @intCast(self.code.items.len);
        const link_name = try linkerSymbolName(self.alloc, f.name);
        if (!self.defer_func_symbol) {
            try self.symbols.append(self.alloc, .{ .name = link_name, .offset = offset, .defined = true });
        }
        try self.asm_text.appendSlice(self.alloc, "\n.globl _");
        try self.asm_text.appendSlice(self.alloc, link_name);
        try self.asm_text.appendSlice(self.alloc, "\n.p2align 2\n_");
        try self.asm_text.appendSlice(self.alloc, link_name);
        try self.asm_text.appendSlice(self.alloc, ":\n");

        var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
        defer temps.deinit(self.alloc);
        var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
        defer pinned.deinit(self.alloc);
        const scalar_body_has_call = if (!f.is_float_kernel) dnirFunctionHasCall(f) else false;
        self.cur_func_has_call = scalar_body_has_call or dnirFunctionHasCall(f);
        self.eval_pinned = &pinned;
        self.eval_temps = &temps;
        self.held_regs = 0;
        // §12 `error.depth`. The initializer runs ONCE, at the top of the
        // process entry and before anything has been pushed, so the `sp` it
        // reads is the deepest this process will ever stand on. The check goes
        // ahead of the callee-save bank for the same reason: it must answer for
        // the frame this function is ABOUT to take, not the one it has taken.
        // A module that meters NOTHING emits neither, so its artifact is byte
        // for byte what it is today — which is most of the corpus.
        const is_entry = if (self.entry) |e| std.mem.eql(u8, e, f.name) else false;
        if (self.depth_meter and self.depth_module_meters and is_entry) try self.emitDepthLimitInit();
        if (self.depth_meter and self.next_func_metered) try self.emitDepthCheck();
        // `dnirNeedsCalleeSave` no longer decides here: it gates the PROBE (see
        // `compileDnirModule`), and the probe's answer is the plan. An empty plan
        // emits nothing at all.
        try self.emitSaveCalleeRegs();

        if (f.is_float_kernel) {
            // Exactly the move the integer path below makes, and for exactly
            // the same reason. d0-d7 are BOTH the f64 argument registers and
            // the staging registers for an outgoing call, so a parameter left
            // in its incoming register is destroyed the moment the body calls
            // anything: `p: f64 = 9.0; one(2.0)` overwrote p's home, and
            // `two(4.0, p)` swapped two registers through each other and passed
            // (4.0, 4.0). The integer side solved this long ago by copying
            // parameters out of x0-x7 into the x9+ value range; the FP side
            // never did, and lowering papered over it by REFUSING such calls
            // (`requireSafeFpStaging`).
            //
            // Leaf functions keep the incoming register and pay nothing, which
            // is both free and safe: with no call there is no staging.
            const fp_body_has_call = dnirFunctionHasCall(f);
            var dreg: u5 = 0;
            for (f.params, 0..) |p, i| {
                const slot: u32 = @intCast(i);
                if (p.ty == .f64) {
                    self.used_fp_regs[dreg] = true;
                    const home = if (fp_body_has_call) blk: {
                        const h = try self.allocFpReg();
                        try self.emitFmovReg(h, dreg);
                        break :blk h;
                    } else dreg;
                    self.markFpHome(home);
                    try self.fp_locals.put(self.alloc, p.name, home);
                    try temps.put(self.alloc, slot, home);
                    try self.markFpTemp(slot);
                    dreg += 1;
                } else if (p.record) |rec_name| {
                    const rec = f64RecordDesc(self.f64_records, rec_name) orelse return self.refuse(@src());
                    for (rec.field_names) |fname| {
                        self.used_fp_regs[dreg] = true;
                        const home = if (fp_body_has_call) blk: {
                            const h = try self.allocFpReg();
                            try self.emitFmovReg(h, dreg);
                            break :blk h;
                        } else dreg;
                        self.markFpHome(home);
                        const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ p.name, fname });
                        try self.fp_locals.put(self.alloc, key, home);
                        dreg += 1;
                    }
                } else return self.refuse(@src());
            }
        } else {
            // x0..x7 are both the argument registers and the return-value
            // register, so a parameter left in its incoming register is
            // ARGUMENT-STAGING TERRITORY for the body's own calls: in
            // `fib(n-1) + fib(n-2)` the second operand read x0 after the first
            // call and computed `fib(n-1) - 2` instead of `n - 2`. Copy
            // parameters into the caller-saved range when the body can call;
            // leaf functions keep the incoming register and pay nothing.
            //
            // `emitSaveCallerRegs` DOES cover x0..x7 (it walks 0..8 and then
            // 9..28) — this comment claimed it stopped at x9, which is false and
            // reads as a licence to leave things in the argument file. What it
            // does not cover is the FP argument file: its FP loop starts at
            // `fp_value_reg_base` = d16, so d0..d7 are preserved by NOTHING and
            // an f64 parameter's survival rests entirely on the relocation
            // above, hence on `dnirFunctionHasCall` naming every call.
            try self.planGpStackLocals(f, scalar_body_has_call);
            // Claim the indirect-result pointer FIRST, while x8 still holds what
            // the caller put there. Everything after this can call, and x8 does
            // not survive a call.
            if (self.cur_func_ret_record) |rec| {
                if (scalRecordReturnsIndirect(rec, self.cur_func_foreign)) {
                    const home = try self.allocReg();
                    try self.emitMovReg(home, 8);
                    self.cur_ret_indirect_reg = home;
                }
            }
        }

        // Reserve every record's stack slot ONCE, here in the prologue.
        //
        // Reserving where the record is produced re-executes on each loop
        // iteration and is never balanced before the back-edge, so `sp` walks
        // down a frame per iteration and every field offset shifts — a record
        // built inside a loop then reads garbage. Offsets are sp-relative and
        // only meaningful against a frame reserved once, so size the frame by a
        // pre-pass and hand out fixed offsets.
        //
        // Skipped when the function also builds f64 records: those still reserve
        // at point of use, and their `sub sp` would shift offsets assigned here.
        var has_f64_record = false;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.record.len == 0) continue;
                if (f64RecordDesc(self.f64_records, ins.record) != null) has_f64_record = true;
            }
        }
        // Does anything in this body address a record region under the FALLBACK
        // base "rec"? `load_field` uses `req_alias` and falls back to "rec" when
        // it is empty; `indirectResultBuffer` does the same with `.field`. Those
        // are the only readers. A record LITERAL binding (dnir_lower.zig:4317,
        // :4415) emits `init_record` with `.field` empty and keeps its fields in
        // ordinary locals under `x.a`, so it reserves a region nothing can name.
        // That region is not free: it costs `sub sp`/`add sp`, every table and
        // GP-local offset is rebased around it, and a non-empty `fp_stack_slots`
        // makes the mid-body spill path refuse outright.
        var bare_rec_demand = false;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                switch (ins.op) {
                    .load_field => if (ins.req_alias.len == 0) {
                        bare_rec_demand = true;
                    },
                    .call_direct, .call_extern => if (ins.record.len > 0 and ins.field.len == 0) {
                        bare_rec_demand = true;
                    },
                    else => {},
                }
            }
        }
        if (!has_f64_record) {
            var record_frame: u16 = 0;
            for (f.blocks) |b| {
                for (b.instrs) |ins| {
                    if (ins.record.len == 0) continue;
                    switch (ins.op) {
                        .init_record => if (ins.field.len == 0 and !bare_rec_demand) continue,
                        .call_direct, .call_extern => {},
                        else => continue,
                    }
                    const rec = scalRecordDesc(self.scal_records, ins.record) orelse continue;
                    // A record wider than the argument file is returned
                    // INDIRECTLY, and this reservation is the buffer the callee
                    // writes through — so it has to be made here too, not only
                    // for the records that arrive in x0..x7.
                    if (rec.field_names.len == 0 or rec.field_names.len > dnir_lower.max_record_fields) continue;
                    const base = if (ins.field.len > 0) ins.field else "rec";
                    const probe = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, rec.field_names[0] });
                    defer self.alloc.free(probe);
                    if (self.fp_stack_slots.contains(probe)) continue;
                    for (rec.field_names, 0..) |fname, i| {
                        const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, fname });
                        const off: u16 = record_frame + @as(u16, @intCast(i * 8));
                        try self.fp_stack_slots.put(self.alloc, key, .{
                            .off = off,
                            .float = rec.field_kinds[i] == .f64,
                        });
                    }
                    record_frame += @intCast(std.mem.alignForward(usize, rec.field_names.len * 8, 16));
                }
            }
            if (record_frame > 0) {
                try self.frameGrow(record_frame);
            }
        }

        // WHICH TABLES NEED NO STORAGE AT ALL, and therefore no frame region and
        // no instructions to fill one. `const_table.zig` states the whole rule;
        // the precondition itself comes from `table_facts.zig` and is not
        // restated. This runs BEFORE the slot-base pass below because its answer
        // is what that pass has to skip.
        self.const_bases.clearRetainingCapacity();
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op != .alloc_slots or ins.aggregate == null) continue;
                const base = ins.result orelse return self.refuse(@src());
                const symbol = self.graph_const_bases.get(ins.aggregate.?) orelse return self.refuse(@src());
                const entry = try self.const_bases.getOrPut(self.alloc, base);
                if (entry.found_existing and entry.value_ptr.* != symbol) return self.refuse(@src());
                entry.value_ptr.* = symbol;
            }
        }
        if (self.const_licence) |lic| {
            var promotions = try const_table.recognize(self.alloc, f, lic);
            defer promotions.deinit();
            for (promotions.items) |p| {
                const sym = try self.internConstTable(p.values);
                const entry = try self.const_bases.getOrPut(self.alloc, p.base);
                if (entry.found_existing and entry.value_ptr.* != sym) return self.refuse(@src());
                entry.value_ptr.* = sym;
            }
        }

        // Memory-backed positional tables. Same reasoning as records above: the
        // reservation must happen once, not at the point of use, or a table
        // built inside a loop walks `sp` down a frame per iteration. Each
        // `alloc_slots` gets a fixed sp-relative offset assigned here, keyed by
        // the instruction's own result temp.
        self.slot_bases.clearRetainingCapacity();
        {
            var slots_frame: u16 = 0;
            for (f.blocks) |b| {
                for (b.instrs) |ins| {
                    if (ins.op != .alloc_slots) continue;
                    const t = ins.result orelse continue;
                    // A promoted table lives in `__TEXT,__const`. Reserving a
                    // frame region for it as well would not merely waste stack —
                    // the region shifts every sp-relative offset handed out
                    // afterwards, which is the exact mechanism behind the
                    // overlap that made a scalar read 50 instead of 33.
                    if (self.const_bases.contains(t)) continue;
                    const n: u16 = switch (ins.lhs) {
                        .i64 => |v| if (v > 0 and v <= 4096) @intCast(v) else return self.refuse(@src()),
                        else => return self.refuse(@src()),
                    };
                    const bytes: u16 = @intCast(std.mem.alignForward(usize, @as(usize, n) * 8, 16));
                    if (@as(u32, slots_frame) + bytes > 32752) return self.refuse(@src());
                    try self.slot_bases.put(self.alloc, t, slots_frame);
                    slots_frame += bytes;
                }
            }
            if (slots_frame > 0) {
                // EVERY sp-RELATIVE OFFSET ALREADY HANDED OUT IS NOW WRONG BY
                // THIS MUCH. That is the invariant this prologue kept breaking:
                // each region is measured from the `sp` that existed when the
                // region was reserved, and every later `sub sp` silently
                // renumbers all of them. Three regions are reserved in sequence
                // (records, tables, GP locals + spill), so each `sub sp` must
                // rebase everything handed out before it — here and below.
                //
                // Left unrebased, the regions do not merely shift, they OVERLAP:
                // GP stack locals are addressed from the FINAL `sp` starting at
                // [sp,#0], which is exactly where an unrebased table region also
                // claims to start. Measured on a 33-element table in a relation
                // that also makes a call (the call is what forces locals to
                // memory at all): `t(3) + ident(3)` answered 50 instead of 33,
                // the scalar reading element 2 of the table. No refusal, no
                // diagnostic, a program that compiles and runs and is wrong.
                //
                // WHY IT SURVIVED THE GATES: tables are covered, calls are
                // covered, and nothing covered BOTH IN ONE RELATION. Below 33
                // elements the table is a select chain — registers, not frame —
                // so the corpus's tables never met the spill area.
                try self.frameGrow(slots_frame);
                // Every region reserved EARLIER is now that much further from
                // `sp`. The record region is the only one, and it is rebased
                // here for the same reason the table region is rebased below.
                var rec_it = self.fp_stack_slots.valueIterator();
                while (rec_it.next()) |slot| {
                    const rebased: u32 = @as(u32, slot.off) + slots_frame;
                    if (rebased > 32752) return self.refuse(@src());
                    slot.off = @intCast(rebased);
                }
            }
        }

        if (!f.is_float_kernel) {
            var gp_need: usize = 0;
            var git = self.gp_stack_locals.valueIterator();
            while (git.next()) |off| {
                const end = @as(usize, off.*) + 8;
                if (end > gp_need) gp_need = end;
            }
            const gp_stack_bytes: u16 = @intCast(std.mem.alignForward(usize, gp_need, 16));
            // Locals sit at [sp,#0]…; spill temps sit above them. One `sub sp`
            // for both — a second sub moved sp and left local offsets pointing
            // into the spill pit, so `bare`'s `i` and the `c != " "` bool shared
            // a slot and the walk never advanced.
            // SPILL SPACE IS NOT A PROPERTY OF CALLING, and reserving it only
            // for callers was an accident that held because something else was
            // wrong. A dynamic table index emits a bounds trap; the trap used to
            // be `call_extern abort`; so every function that indexed a table
            // dynamically counted as a caller and got a spill area it needed for
            // an entirely unrelated reason — register pressure. Making the trap a
            // real trap took the area away with it, and a 20-element select-chain
            // loop with no call in it went from answering 33 to DNB003.
            //
            // The two facts are now asked separately. A CALL forces locals out of
            // caller-saved homes (`gate_spill_all_locals`, above). PRESSURE is
            // what needs somewhere to spill to, and it is `dnirNeedsCalleeSave`
            // — the same question the prologue asks about x19–x28 — that says a
            // function has more live values than caller-saved homes.
            //
            // Over-reserving costs one `sub sp`/`add sp` pair and some untouched
            // stack; under-reserving costs a working program. The budget check
            // still HARD-FAILS for a caller, because a caller that cannot spill
            // really is out of capacity; for a leaf it simply reserves what is
            // left, which may be nothing.
            const wants_spill = scalar_body_has_call or dnirNeedsCalleeSave(f);
            var spill_reserve: u16 = 0;
            if (wants_spill) {
                const used: u32 = @as(u32, self.stack_frame_bytes) + gp_stack_bytes;
                if (used >= self.spill_frame_budget) {
                    if (scalar_body_has_call) return error.RegisterExhausted;
                } else {
                    const remain: u32 = self.spill_frame_budget - used;
                    // SIZED FROM PRESSURE, NOT A FLAT 8 KiB — and the flat 8 KiB
                    // is what capped recursion at ~1,000 frames.
                    //
                    // This reserved 8192 bytes for every function that calls,
                    // whatever it spills. A two-parameter `tail(n, acc)` got a
                    // frame of 8192 + 16 = 8208 bytes, so an 8 MiB stack holds
                    // 8388608 / 8208 = 1022 frames. MEASURED before this: depth
                    // 1,000 answers correctly, depth 5,000 is SIGSEGV. §12
                    // promises PROPER TAIL CALLS and the guarantee was missing
                    // by three orders of magnitude — but the frame is the reason
                    // the cliff sits where it does, and it costs every recursive
                    // formulation whether or not its calls are in tail position.
                    //
                    // Only a value `dnirGpPressure` already counted can ever be
                    // spilled — it walks the same locals and temps the allocator
                    // draws from — so `pressure * 16` is a true upper bound, 16
                    // being the slot size `spillReg` hands out. Clamped to the
                    // old 8192 so this can only ever reserve LESS, never more.
                    //
                    // Under-reserving is SAFE HERE and that is why this is a
                    // legal change rather than a gamble: `spillReg` refuses with
                    // `RegisterExhausted` when `gate_spill_cursor + 16 >
                    // gate_spill_end`, so a bound that is too tight costs a
                    // named refusal, not a frame written below `sp`.
                    const pressure_bytes: u32 = @as(u32, dnirGpPressure(f)) * 16;
                    const want: u32 = @min(@min(remain, pressure_bytes), 8192);
                    spill_reserve = @intCast(std.mem.alignForward(u32, want, 16));
                    if (spill_reserve < 64) spill_reserve = 0;
                }
            }
            const frame: u16 = gp_stack_bytes + spill_reserve;
            if (frame > 0) {
                if (@as(u32, self.stack_frame_bytes) + frame > self.spill_frame_budget) {
                    return error.RegisterExhausted;
                }
                try self.frameGrow(frame);
                // REBASE the memory-backed table regions.
                //
                // `slot_bases` was measured against the `sp` that existed before
                // this reservation, and GP stack locals are addressed from the
                // NEW `sp` starting at [sp,#0]. Without this shift the two name
                // the same bytes: a 40-element table sat at [sp,#0..320) while
                // the loop counter's home sat at [sp,#0xb0] — inside it, element
                // 23 — so every iteration's `i` store overwrote a table element.
                //
                // That is a WRONG ANSWER, not a crash, and it hid for a long
                // time behind test data: the corpus tables are `{1,2,3,…}`, and
                // storing `i` over element `i` writes the value that was already
                // there. It only becomes visible when the elements stop equalling
                // their own index (`t[k] = k + 100`) or when something reads the
                // region at a different point in the loop.
                //
                // Records (`fp_stack_slots`) are reserved BEFORE the table
                // region, so they are stale by `slots_frame + frame` and are
                // rebased by the same rule immediately below.
                var slot_it = self.slot_bases.valueIterator();
                while (slot_it.next()) |off| {
                    const rebased: u32 = @as(u32, off.*) + frame;
                    if (rebased > 32752) return self.refuse(@src());
                    off.* = @intCast(rebased);
                }
                var rec_it = self.fp_stack_slots.valueIterator();
                while (rec_it.next()) |slot| {
                    const rebased: u32 = @as(u32, slot.off) + frame;
                    if (rebased > 32752) return self.refuse(@src());
                    slot.off = @intCast(rebased);
                }
            }
            if (spill_reserve >= 64) {
                const band = gateSpillBand(self.stack_frame_bytes, gp_stack_bytes, spill_reserve);
                self.gate_spill_base = band.base;
                self.gate_spill_end = band.end;
                self.gate_spill_cursor = self.gate_spill_base;
            }
            // Parameter homes are set up after the prologue so stack-relative
            // displacements match `storeGpStackLocal` / `loadGpStackLocal`.
            var slot_cursor: u32 = 0;
            for (f.params) |p| {
                var slots_for_param: u32 = 1;
                if (p.record) |rec_name| {
                    if (scalRecordDesc(self.scal_records, rec_name)) |rec| {
                        slots_for_param = @intCast(rec.field_names.len);
                    }
                }
                // A DECLARED narrow parameter arrives in a 64-bit register and
                // the caller may not have narrowed it: `f(x: i32)` under the C
                // backend receives an `int32_t`, truncated by C at the call.
                // Refit on entry instead of at each call site — one place, one
                // instruction, and it holds for callers this compilation never
                // sees. Record parameters keep i64 fields, so only the
                // one-slot (scalar) case carries a declared width.
                const param_fit: native_types.ResolvedType =
                    if (slots_for_param == 1) p.ty else .any;
                var k: u32 = 0;
                while (k < slots_for_param) : (k += 1) {
                    const slot = slot_cursor;
                    if (slot >= 8) {
                        // AAPCS64 stack argument: the ninth and later GP params
                        // arrive in the caller's outgoing area, which now sits
                        // just above this frame (callee-saves + locals + spill).
                        // EVERY STACKED SLOT IS ONE 8-BYTE WORD, whatever it is
                        // a slot OF: `slot_cursor` counts a record parameter's
                        // exploded fields alongside scalar parameters, and every
                        // field this backend puts in a scalar record occupies 8
                        // bytes at an 8-byte stride (i64, bool, a narrow int
                        // widened on entry, and str-as-address alike). So the
                        // home is [sp, #(callee_save+frame)+(slot-8)*8] and the
                        // provenance of the word never enters the address.
                        const frame_total: u32 = @as(u32, self.callee_save_bytes) + @as(u32, self.stack_frame_bytes);
                        const off: u32 = frame_total + (slot - 8) * 8;
                        if (off > 32760) return self.refuse(@src());
                        const home = if (self.gpSlotUsesStack(slot))
                            try self.allocReg()
                        else
                            try self.allocHomeReg();
                        try self.emitLdrFrame(home, @intCast(off));
                        _ = try self.emitNarrowFit(home, home, param_fit);
                        if (self.gpSlotUsesStack(slot)) {
                            const soff = try self.reserveGpStackLocal(slot);
                            try self.storeGpStackLocal(soff, home);
                            if (!Arm64Compiler.regIsPinned(&pinned, home)) self.releaseReg(home);
                        } else {
                            self.markGpHome(home);
                            try temps.put(self.alloc, slot, home);
                            try pinned.put(self.alloc, slot, home);
                        }
                        slot_cursor += 1;
                        continue;
                    }
                    const arg_reg: u5 = @intCast(slot);
                    if (scalar_body_has_call) {
                        // A frame-bound param only needs a scratch register to
                        // reach its slot; a register-homed one needs a home the
                        // call cannot reach.
                        if (self.gpSlotUsesStack(slot)) {
                            const off = try self.reserveGpStackLocal(slot);
                            // Store directly from the incoming arg register.
                            // narrowedFrameSource refits the value if the type
                            // needs narrowing, returning arg_reg itself when
                            // no refit is needed. This avoids the temp-register
                            // mov that the old path emitted.
                            const src = try self.narrowedFrameSource(arg_reg, param_fit);
                            try self.storeGpStackLocal(off, src);
                            if (src != arg_reg) self.releaseReg(src);
                        } else {
                            const home = try self.allocHomeReg();
                            try self.emitMovRegFit(home, arg_reg, param_fit);
                            self.markGpHome(home);
                            try temps.put(self.alloc, slot, home);
                            try pinned.put(self.alloc, slot, home);
                        }
                    } else {
                        // A LEAF KEEPS ITS PARAMETER IN THE INCOMING REGISTER,
                        // AND THAT REGISTER IS THEN LIVE FOR THE WHOLE BODY.
                        // `pinned` stops the release paths from freeing it, but
                        // `allocRegExcluding` does not read `pinned` -- when
                        // x9..x28 are all busy it falls through to x0..x7 and asks
                        // only `used_regs`. Nothing ever set `used_regs[x0]` here,
                        // so the allocator handed out the live trip count: an
                        // 8-field record literal in a `while` loop exhausted
                        // x9..x28 on its fields, `s + x.a + x.h` was computed INTO
                        // x0, and the back edge's `cmp i, x0` compared the
                        // induction variable against the running sum. The loop ran
                        // to signed overflow (~3e9 iterations, 3.8 s) and returned
                        // a value INDEPENDENT OF ITS ARGUMENT. Claim it, and
                        // exhaustion refuses instead.
                        self.claimReg(arg_reg);
                        // The leaf keeps the incoming register, so the refit is
                        // in place — the argument register belongs to this
                        // frame from entry and has no other reader.
                        _ = try self.emitNarrowFit(arg_reg, arg_reg, param_fit);
                        try temps.put(self.alloc, slot, arg_reg);
                        try pinned.put(self.alloc, slot, arg_reg);
                    }
                    slot_cursor += 1;
                }
            }
        }

        self.frame_sealed = true;

        var code_offsets: std.ArrayList(u32) = .empty;
        defer code_offsets.deinit(self.alloc);
        var branch_patches: std.ArrayList(DnirBranchPatch) = .empty;
        defer branch_patches.deinit(self.alloc);

        // Whether the LAST instruction emitted was a terminator. `self.returned`
        // is a single flag for the whole function, so an early `return` inside an
        // `if` marks it true even when the fall-through path just runs off the
        // end — the function then executes whatever symbol the linker placed
        // next. Track the final instruction separately.
        var tail_terminates = false;
        var flat_idx: u32 = 0;
        // Severing control for the madd shift-add strength reduction below:
        // IDOL_MADD_SHIFTADD_OFF=1 restores the stock madd emission exactly.
        // Read once per function; the emission loop must not pay a libc call
        // per instruction.
        const madd_shiftadd_off = std.c.getenv("IDOL_MADD_SHIFTADD_OFF") != null;
        // Severing control for the ubfx pre-mask elision below:
        // IDOL_UBFX_PREMASK_OFF=1 restores the stock emission exactly.
        // Read once per function; the emission loop must not pay a libc call
        // per instruction.
        const premask_off = std.c.getenv("IDOL_UBFX_PREMASK_OFF") != null;
        for (f.blocks) |b| {
            var bi: usize = 0;
            while (bi < b.instrs.len) : (bi += 1) {
                const ins = b.instrs[bi];
                // Pre-materialize loop-invariant constants into reserved
                // registers in the preheader — before this head's code offset,
                // so the back edge re-enters after the movs (FTCFTW debt (1)).
                try self.immHoistEnter(flat_idx);
                const text_start: u32 = @intCast(self.code.items.len);
                try code_offsets.append(self.alloc, text_start);
                // Peephole: elide a dead pre-mask feeding a ubfx fusion.
                // band(X, M) -> Tb ; div(Tb, 2^k) -> T ; ... where the div
                // fuses to ubfx D, Tb, #k, #w and M covers every extracted
                // bit: the band is not emitted and the fused ubfx reads X
                // directly (see ubfxPremaskElidable).
                const premask_elision = if (!premask_off) self.ubfxPremaskElidable(f, b, bi, flat_idx) else null;
                // Peephole: fold `binop(cmp) -> T ; br when_x T` into `cmp; b.cond`
                // when T's only reader is that branch. The branch instruction is
                // then consumed below with no bytes of its own.
                const fuse_branch = ins.op == .binop and bi + 1 < b.instrs.len and
                    self.compareBranchFusible(ins, b.instrs[bi + 1], flat_idx);
                // R15: the SAME compare, given a name. `c = a > b ; if c` puts a
                // `store_local` between the two, which the adjacency test above
                // cannot see past; `namedCompareBranchFusible` counts the name's
                // readers instead and folds to the identical `cmp; b.cond`.
                const fuse_named = !fuse_branch and ins.op == .binop and bi + 2 < b.instrs.len and
                    self.namedCompareBranchFusible(f, ins, b.instrs[bi + 1], b.instrs[bi + 2], flat_idx);
                // Peephole: fold `mul -> T ; add(T, c) -> D` into `madd D,a,b,c`
                // when T's only reader is that add (FTCFTW debt (2)).
                const fuse_madd = !fuse_branch and !fuse_named and ins.op == .binop and bi + 1 < b.instrs.len and
                    self.mulAddFusible(ins, b.instrs[bi + 1], flat_idx);
                // Peephole: fold `div(X, 2^k) -> T ; band(T, 2^w - 1) -> D`
                // into `ubfx D, X, #k, #w` when T's only reader is that
                // `and` and the dividend is proved non-negative (the exact
                // identity `lsr`+`and` computes; see `ubfxFusible`).
                const fuse_ubfx = !fuse_branch and !fuse_named and !fuse_madd and ins.op == .binop and bi + 1 < b.instrs.len and
                    self.ubfxFusible(ins, b.instrs[bi + 1], flat_idx);
                // R15-style named variant: `div(X, 2^k) -> T ; store_local L <- T ;
                // band(L, 2^w - 1) -> D ; store_local L <- D` folds to the same
                // `ubfx D, X, #k, #w` when the shift passes through a named local
                // (see `namedUbfxFusible`).
                const fuse_named_ubfx = !fuse_branch and !fuse_named and !fuse_madd and !fuse_ubfx and
                    ins.op == .binop and bi + 3 < b.instrs.len and
                    self.namedUbfxFusible(f, ins, b.instrs[bi + 1], b.instrs[bi + 2], b.instrs[bi + 3], flat_idx);
                // Divmod: fold `div(X, k) -> T ; store_local Lq <- T ;
                // mul(Lq, k) -> M ; sub(X, M) -> D` into one magic-division
                // sequence that materializes BOTH the corrected quotient
                // (for Lq) and the already-computed floored residual (for D).
                // The separate multiply/subtract never execute; see
                // `divmodFusible` for every ground on which it is declined.
                const fuse_divmod = !fuse_branch and !fuse_named and !fuse_madd and !fuse_ubfx and !fuse_named_ubfx and
                    ins.op == .binop and bi + 3 < b.instrs.len and
                    self.divmodFusible(f, ins, b.instrs[bi + 1], b.instrs[bi + 2], b.instrs[bi + 3], flat_idx);
                const fuse_divmod_rt = !fuse_branch and !fuse_named and !fuse_madd and !fuse_ubfx and !fuse_named_ubfx and !fuse_divmod and
                    ins.op == .binop and bi + 3 < b.instrs.len and
                    self.divmodRuntimeFusible(f, ins, b.instrs[bi + 1], b.instrs[bi + 2], b.instrs[bi + 3], flat_idx);
                const fuse_absd = !fuse_branch and !fuse_named and !fuse_madd and !fuse_ubfx and !fuse_named_ubfx and !fuse_divmod and !fuse_divmod_rt and
                    ins.op == .binop and bi + 4 < b.instrs.len and
                    self.absdFusible(ins, b.instrs[bi + 1], b.instrs[bi + 2], b.instrs[bi + 3], b.instrs[bi + 4], flat_idx);
                // §12 TAIL: `call_direct -> T ; ret T` is a JUMP, not a frame.
                // The pair is folded into `restore the frame; b <callee>` — see
                // `tailCallFusible` for every ground on which it is declined.
                const fuse_tail = ins.op == .call_direct and bi + 1 < b.instrs.len and
                    self.tailCallFusible(f, ins, b.instrs[bi + 1], flat_idx + 1);
                // W7: the whole one-sided `if` becomes `csel`, on top of
                // whichever of the three condition shapes reached here.
                const ifconv: ?IfConvPlan = if (fuse_branch)
                    self.ifConversionArm(f, b.instrs[bi + 1 ..], flat_idx + 1, ins, 1)
                else if (fuse_named)
                    self.ifConversionArm(f, b.instrs[bi + 2 ..], flat_idx + 2, ins, 2)
                else if (ins.op == .br and ins.branch_condition != .unconditional)
                    self.ifConversionArm(f, b.instrs[bi..], flat_idx, null, 0)
                else
                    null;
                // W8: the same three condition shapes, with BOTH arms present.
                // Tried only after W7 declines, so a one-sided `if` keeps the
                // emission it has today byte for byte.
                const ifconv2: ?TwoSidedPlan = if (ifconv != null)
                    null
                else if (fuse_branch)
                    self.ifConversionTwoSided(f, b.instrs[bi + 1 ..], flat_idx + 1, ins, 1)
                else if (fuse_named)
                    self.ifConversionTwoSided(f, b.instrs[bi + 2 ..], flat_idx + 2, ins, 2)
                else if (ins.op == .br and ins.branch_condition != .unconditional)
                    self.ifConversionTwoSided(f, b.instrs[bi..], flat_idx, null, 0)
                else
                    null;
                // DNIR instructions this iteration consumes BEYOND `ins`. Each
                // one still gets a code offset below so branch targets resolve.
                if (self.ifconv_refusal.len != 0) {
                    self.ifconv_candidates += 1;
                    if (self.ifconv_trace) {
                        std.debug.print("  ifconv2 refuse {s} @{d} in {s}\n", .{ self.ifconv_refusal, flat_idx, f.name });
                    }
                    self.ifconv_refusal = "";
                }
                var extra_consumed: u32 = 0;
                if (ifconv) |plan| {
                    if (fuse_branch or fuse_named) self.countTightDefAdmission(ins, flat_idx);
                    if (plan.op != null) {
                        try self.emitIfConverted(&temps, &pinned, plan, &branch_patches, flat_idx);
                    } else {
                        try self.emitIfConvertedCopy(&temps, &pinned, plan, &branch_patches, flat_idx);
                    }
                    extra_consumed = plan.extra;
                } else if (ifconv2) |plan| {
                    if (fuse_branch or fuse_named) self.countTightDefAdmission(ins, flat_idx);
                    try self.emitIfConvertedTwoSided(&temps, &pinned, plan, &branch_patches, flat_idx);
                    extra_consumed = plan.extra;
                } else if (fuse_branch) {
                    self.countTightDefAdmission(ins, flat_idx);
                    try self.emitFusedCompareBranch(&temps, &pinned, ins, b.instrs[bi + 1], &branch_patches);
                    extra_consumed = 1;
                } else if (fuse_named) {
                    self.countTightDefAdmission(ins, flat_idx);
                    try self.emitFusedCompareBranch(&temps, &pinned, ins, b.instrs[bi + 2], &branch_patches);
                    extra_consumed = 2;
                } else if (fuse_madd) {
                    const after_madd = if (bi + 2 < b.instrs.len) b.instrs[bi + 2] else null;
                    try self.emitFusedMulAdd(&temps, &pinned, ins, b.instrs[bi + 1], after_madd, madd_shiftadd_off);
                    extra_consumed = 1;
                } else if (fuse_ubfx) {
                    try self.emitFusedUbfx(&temps, &pinned, ins, b.instrs[bi + 1]);
                    extra_consumed = 1;
                } else if (fuse_named_ubfx) {
                    try self.emitFusedUbfx(&temps, &pinned, ins, b.instrs[bi + 2]);
                    extra_consumed = 2;
                } else if (fuse_divmod) {
                    try self.emitFusedDivmod(&temps, &pinned, ins, b.instrs[bi + 1], b.instrs[bi + 3], &branch_patches, flat_idx);
                    extra_consumed = 3;
                } else if (fuse_divmod_rt) {
                    const q_dead = divmodQuotientDead(f, b.instrs[bi + 1], flat_idx);
                    try self.emitFusedDivmodRuntime(&temps, &pinned, ins, b.instrs[bi + 1], b.instrs[bi + 3], &branch_patches, flat_idx, q_dead);
                    extra_consumed = 3;
                } else if (fuse_absd) {
                    try self.emitFusedAbsd(&temps, ins, b.instrs[bi + 4]);
                    extra_consumed = 4;
                } else if (fuse_tail) {
                    try self.emitTailCallDirect(&temps, &pinned, ins, flat_idx);
                    extra_consumed = 1;
                } else if (premask_elision) |info| {
                    // Elided pre-mask band: no bytes emitted. Record Tb -> X
                    // so the fused ubfx at the div reads X directly, and
                    // extend X's liveness past the elided band to the div.
                    // The post-div sweep then frees X exactly when dead.
                    try self.premask_elided.put(self.alloc, info.t_band, info.x);
                    if (info.x == .temp) {
                        const xid = info.x.temp;
                        const div_flat = flat_idx + 1;
                        const cur = self.value_free_at.get(xid) orelse 0;
                        if (div_flat > cur) try self.value_free_at.put(self.alloc, xid, div_flat);
                    }
                } else {
                    const preferred_result = if (bi + 1 < b.instrs.len)
                        self.returnPackBinopDestination(&temps, ins, b.instrs[bi + 1]) orelse
                            self.returnConstDestination(ins, b.instrs[bi + 1], flat_idx) orelse
                            self.returnStoreLocalDestination(&temps, &pinned, ins, b.instrs[bi + 1], flat_idx)
                    else
                        null;
                    try self.compileDnirInstr(&temps, &pinned, ins, &branch_patches, preferred_result, flat_idx);
                }
                const fact_count: u2 = @as(u2, @intFromBool(ins.relation != null)) +
                    @as(u2, @intFromBool(ins.application != null)) +
                    @as(u2, @intFromBool(ins.value != null));
                if (fact_count != 0 and fact_count != 3) {
                    return self.refuseWith(@src(), "partial-application-lineage");
                }
                if (fact_count == 0 and ins.subject != null) {
                    return self.refuseWith(@src(), "orphan-application-subject");
                }
                if ((fact_count == 3) != (ins.realization_start != null)) {
                    return self.refuseWith(@src(), "partial-realization-lineage");
                }
                if (ins.application) |application| {
                    const realization_start = ins.realization_start.?;
                    if (realization_start > flat_idx or realization_start >= code_offsets.items.len) {
                        return self.refuseWith(@src(), "invalid-realization-start");
                    }
                    try self.lineage.append(self.alloc, .{
                        .relation = ins.relation.?,
                        .target = ins.target orelse return self.refuseWith(@src(), "missing-application-target"),
                        .application = application,
                        .value = ins.value.?,
                        .subject = ins.subject,
                        .descriptor = ins.ty,
                        .caller = f.id orelse
                            return self.refuseWith(@src(), "application-caller"),
                        .instruction_start = realization_start,
                        .instruction_end = flat_idx + 1,
                        .text_start = code_offsets.items[realization_start],
                        .text_end = @intCast(self.code.items.len),
                    });
                }
                // Ownership is recorded HERE, once, rather than at each of the
                // eight `temps.put` + `markFpTemp` pairs: the pair is exactly
                // "this id now reads out of this register", and one place
                // cannot drift out of step with another.
                // `mov_arg`/`fp_mov_arg` alone carry a PHYSICAL ABI register slot
                // (0..7) in `result`, not a value id. The value-id space (locals +
                // temps) is one shared unique counter, so a low slot index like 0
                // aliases real value id 0: looking it up in `temps` returned the
                // register of a live call result that happened to hold value 0's
                // home, and the ownership rebind below then handed that live
                // register to a long-dead value — the very next `sweepGpLive` freed
                // it mid-use, collapsing multi-argument marshaling (both operands of
                // an inner call read the same clobbered register). Every other op
                // reports a genuine value id in `result` (or none), so gate only the
                // two ABI-slot ops; gating more would leak `cmp`/`load_global`
                // registers that never get swept, exhausting the pool.
                const owned_value: ?u32 = switch (ins.op) {
                    .mov_arg, .fp_mov_arg => null,
                    else => ins.result,
                };
                if (owned_value) |t| {
                    if (temps.get(t)) |r| {
                        if (self.fp_temps.contains(t)) {
                            if (r >= fp_value_reg_base and
                                r < fp_value_reg_base + fp_value_reg_count and
                                !self.fp_home_regs[r])
                            {
                                self.fp_reg_owner[r] = t;
                            }
                        } else if (r >= 9 and r < 29 and r != platform_reserved_reg and
                            !self.gp_home_regs[r])
                        {
                            self.gp_reg_owner[r] = t;
                        }
                    }
                }
                for (ins.pack_results) |result| {
                    const t = result.temp orelse continue;
                    const r = temps.get(t) orelse continue;
                    if (r >= 9 and r < 29 and r != platform_reserved_reg and !self.gp_home_regs[r]) {
                        self.gp_reg_owner[r] = t;
                    }
                }
                self.sweepFpLive(flat_idx);
                self.sweepGpLive(flat_idx);
                tail_terminates = switch (ins.op) {
                    .ret, .ret_pack, .ret_record => true,
                    .br => ins.branch_condition == .unconditional,
                    else => false,
                };
                flat_idx += 1;
                var consumed: u32 = 0;
                while (consumed < extra_consumed) : (consumed += 1) {
                    // The following instructions (a conditional `br` folded into
                    // the compare, the `add` folded into the `madd`, or the whole
                    // arm of an if-converted `if`) emitted no bytes of their own.
                    // Consume them while preserving the one-code-offset-per-
                    // instruction alignment that DNIR branch targets resolve
                    // against. Each recognizer has already proved that nothing
                    // branches INTO the window it collapses.
                    bi += 1;
                    try code_offsets.append(self.alloc, @intCast(self.code.items.len));
                    self.sweepFpLive(flat_idx);
                    self.sweepGpLive(flat_idx);
                    tail_terminates = false;
                    flat_idx += 1;
                }
                // A JUMP OUT OF THE FUNCTION IS A TERMINATOR. `tail_terminates`
                // is read from the op above, which is `call_direct` and is not
                // one; the `ret` that would have said so was consumed. Without
                // this the function reports "falls off the end" and refuses.
                if (fuse_tail) tail_terminates = true;
                // Release hoist registers once emission has passed a loop latch.
                self.immHoistExit(flat_idx);
            }
        }
        // Sentinel: branch_target may equal instr count (fall-through past if-block).
        try code_offsets.append(self.alloc, @intCast(self.code.items.len));
        for (branch_patches.items) |p| {
            if (p.target_instr >= code_offsets.items.len) return self.refuse(@src());
            var target_off = code_offsets.items[p.target_instr];
            // A loop head whose constants were pre-materialized has TWO entry
            // points, and which one a branch wants is decided by the direction of
            // the branch, not by the target. The back edge is already past the
            // preheader and must stay past it, or the movs run every iteration
            // and the hoist buys nothing. Everything else — the `b.cond` that
            // skips an `if` and the `b` that closes it are the two that mattered
            // — is entering the loop for the first time and MUST run them.
            //
            // Direction is read off the offsets rather than carried on the patch:
            // emission is strictly in order, so a branch emitted before the
            // preheader is exactly a branch from before the head. Keeping
            // `code_offsets` pointing at the head itself leaves instruction
            // lineage spans (`text_start`) measuring the instruction and not its
            // preheader.
            if (self.hoist_preheader.get(p.target_instr)) |pre_off| {
                if (p.patch_off < pre_off) target_off = pre_off;
            }
            if (p.is_cond) {
                try self.patchCondBranch(p.patch_off, target_off);
            } else {
                try self.patchB(p.patch_off, target_off);
            }
        }
        // NAME THE FUNCTION. Both refusals below are about ONE function's
        // instruction stream, and the compiler is holding its name in
        // `cur_func_name`; reporting a bare source location made the reader
        // bisect the subject to find out which one.
        if (!self.returned) return self.refuseWith(@src(), self.cur_func_name orelse "?");
        // Falling off the end of a function is never recoverable at runtime:
        // execution continues into whatever symbol the linker placed next
        // (here, straight into _duo_keyword_classify → SIGSEGV). Refuse instead
        // of emitting it, so the honest DNB001 path reports the gap.
        if (!tail_terminates) return self.refuseWith(@src(), self.cur_func_name orelse "?");
        self.eval_pinned = null;
        self.eval_temps = null;
        self.held_regs = 0;
        self.cur_func_has_call = false;
    }

    fn mappedGpValueReg(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        value: dnir.Value,
    ) ?u5 {
        return switch (value) {
            .local => |slot| if (self.gp_stack_locals.contains(slot)) null else temps.get(slot),
            .temp => |slot| temps.get(slot),
            else => null,
        };
    }

    /// Select the ABI result register as a binop destination when the following
    /// pack return proves that overwriting it cannot destroy another member.
    fn returnPackBinopDestination(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        next: dnir.Instr,
    ) ?u5 {
        if (ins.op != .binop or next.op != .ret_pack) return null;
        const result = ins.result orelse return null;
        var destination: ?u5 = null;
        for (next.vals, 0..) |value, i| switch (value) {
            .temp => |slot| if (slot == result and destination == null) {
                if (i >= dnir_lower.max_reg_record_fields) return null;
                destination = @intCast(i);
            },
            else => {},
        };
        const dest = destination orelse return null;
        // The destination must not alias the binop's own operands. The
        // sh>1 unproved signed div-pow2 sequence clobbers lhs on its first
        // instruction (asr dst,lhs,#63) and answers 0 for every input when
        // dst==lhs. Declining is safe: the ordinary allocation holds lhs
        // first, so the fallback destination cannot equal lhs.
        if (self.mappedGpValueReg(temps, ins.lhs)) |source| {
            if (source == dest) return null;
        }
        if (self.mappedGpValueReg(temps, ins.rhs)) |source| {
            if (source == dest) return null;
        }
        for (next.vals, 0..) |value, i| {
            if (i == dest) continue;
            switch (value) {
                .temp => |slot| if (slot == result) continue,
                else => {},
            }
            if (self.mappedGpValueReg(temps, value)) |source| {
                if (source == dest) return null;
            }
        }
        return dest;
    }

    /// Materialize an integer constant directly in the ABI return register
    /// when its only remaining consumer is the immediately following return.
    /// The DNIR constant still owns the application realization and machine
    /// lineage; this only prevents that ownership edge from adding a scratch
    /// move to the previously optimal `mov x0,#k ; ret` sequence.
    fn returnConstDestination(
        self: *const Arm64Compiler,
        ins: dnir.Instr,
        next: dnir.Instr,
        flat_idx: u32,
    ) ?u5 {
        if (ins.op != .@"const" or !ins.ty.is_integer() or next.op != .ret) return null;
        const result = ins.result orelse return null;
        if (next.lhs != .temp or next.lhs.temp != result) return null;
        if (self.value_free_at.get(result) != flat_idx + 1) return null;
        return 0;
    }

    fn returnStoreLocalDestination(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        next: dnir.Instr,
        at: u32,
    ) ?u5 {
        if (next.op != .store_local) return null;
        switch (ins.op) {
            .binop => switch (ins.binop) {
                .add, .sub, .shl, .shr, .band, .bor, .bxor, .mul => {},
                else => return null,
            },
            // An integer constant materializes with a write-only move, so it
            // lands in the home directly: no operand to alias, and the old
            // home value dies with the store exactly like the binop case.
            .@"const" => if (!ins.ty.is_integer()) return null,
            else => return null,
        }
        // Every admitted op emits a single read-before-write instruction on
        // every path (reg-reg op, immediate shift/mask, or multiply-by-const
        // lowering, plus an optional single dst-to-dst narrowing), so the
        // home may alias an operand: the old home value dies with the store.
        const result = ins.result orelse return null;
        if (next.lhs != .temp or next.lhs.temp != result) return null;
        const slot = next.result orelse return null;
        const home = self.gpLocalHomeReg(temps, pinned, slot) orelse return null;
        const reads_home = for ([_]dnir.Value{ ins.lhs, ins.rhs, ins.third }) |op| {
            if (op == .local and op.local == slot) break true;
        } else false;
        if (!reads_home) {
            if (self.gp_reg_owner[home]) |owner| {
                if (self.value_free_at.get(owner)) |last| {
                    if (last > at) return null;
                } else return null;
            } else return null;
        }
        if (pinned.get(slot) != home) return null;
        return home;
    }

    /// Forward the destination of a const binop that answers its lhs
    /// unchanged (x + 0, x * 1, x & -1, x << 0, ...): when the lhs
    /// temp dies here, the result takes over the lhs register instead of a
    /// fresh allocation plus a move. The register is one allocReg would
    /// have handed out — value band, no home, no pin — so the ownership
    /// rebind and the sweep treat it exactly like a fresh destination, and
    /// the emitter skips the move that became a self-copy.
    fn identityBinopForwardDst(
        self: *const Arm64Compiler,
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        k: i64,
        lhs: u5,
        at: u32,
    ) ?u5 {
        const identity = switch (ins.binop) {
            .add, .sub => k == 0,
            .mul, .div, .idiv => k == 1,
            .band => k == -1,
            .bor, .bxor, .shl, .shr => k == 0,
            else => false,
        };
        if (!identity) return null;
        const t = switch (ins.lhs) {
            .temp => |id| id,
            else => return null,
        };
        const last = self.value_free_at.get(t) orelse return null;
        if (last != at) return null;
        if (lhs < 9 or lhs >= 29) return null;
        if (lhs == platform_reserved_reg) return null;
        if (!self.used_regs[lhs]) return null;
        if (self.gp_home_regs[lhs]) return null;
        if (Arm64Compiler.regIsPinned(pinned, lhs)) return null;
        return lhs;
    }

    /// Whether a fresh integer store_local may take the stored temp's
    /// register as the local's first home instead of allocating one. The
    /// register already holds the value in the value band, so a fresh home
    /// plus a move is a redundant alloc+mov; the sweep skips homes, so the
    /// dying temp cannot free the adopted register. Restricted to call-free
    /// functions: a caller must home locals in the callee-saved bank.
    fn adoptTempAsLocalHome(
        self: *const Arm64Compiler,
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        val_reg: u5,
        at: u32,
    ) bool {
        if (self.cur_func_has_call) return false;
        const t = switch (ins.lhs) {
            .temp => |id| id,
            else => return false,
        };
        const last = self.value_free_at.get(t) orelse return false;
        if (last != at) return false;
        if (val_reg < 9 or val_reg >= 29) return false;
        if (val_reg == platform_reserved_reg) return false;
        if (!self.used_regs[val_reg]) return false;
        if (self.gp_home_regs[val_reg]) return false;
        if (Arm64Compiler.regIsPinned(pinned, val_reg)) return false;
        return true;
    }

    fn maddStoreHome(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        add: dnir.Instr,
        after: ?dnir.Instr,
    ) ?u5 {
        const nx = after orelse return null;
        if (nx.op != .store_local) return null;
        const result = add.result orelse return null;
        if (nx.lhs != .temp or nx.lhs.temp != result) return null;
        const slot = nx.result orelse return null;
        const home = self.gpLocalHomeReg(temps, pinned, slot) orelse return null;
        // The old home value does NOT die with the store when it is
        // loop-carried: the next iteration reads it. Aliasing the home
        // register then clobbers the value the back edge expects.
        if (self.gp_reg_owner[home]) |owner| {
            if (self.value_free_at.get(owner)) |last| {
                if (last > self.cur_emit_idx) return null;
            } else return null;
        } else return null;
        return home;
    }

    /// `at` is the flat instruction index of `ins` in the function being
    /// lowered — the same index `sweepGpLive` and `immHoistExit` are given
    /// after this returns. It is here because `preserveArgReg` reads
    /// `value_free_at` against it to tell a `temps` entry whose value is still
    /// owed a register from one that only still names one (GAP-148).
    fn compileDnirInstr(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        preferred_result: ?u5,
        at: u32,
    ) Error!void {
        // Nested compileDnirInstr calls (collapsed windows) pass at through;
        // rebinding here keeps cur_emit_idx correct for releaseReg in all of
        // them, not just the top-level emission loop.
        self.cur_emit_idx = at;
        if ((ins.op == .load_index or ins.op == .store_index) and try self.cell(ins)) {
            const base = try self.evalDnirValue(temps, ins.lhs);
            if (ins.op == .load_index) {
                const result = ins.result orelse return self.refuse(@src());
                const value = try self.allocReg();
                try self.emitLdrBaseImm(value, base, 0);
                _ = try self.emitNarrowFit(value, value, ins.ty);
                try temps.put(self.alloc, result, value);
            } else {
                const value = try self.evalDnirValue(temps, ins.third);
                const fit = try self.narrowedFrameSource(value, ins.ty);
                try self.emitStrBaseImm(fit, base, 0);
                if (fit != value) self.releaseReg(fit);
                self.releaseDnirTemp(pinned, ins.third, value);
            }
            self.releaseDnirTemp(pinned, ins.lhs, base);
            return;
        }
        switch (ins.op) {
            .@"const" => switch (ins.ty) {
                .f64 => {
                    const d = try self.allocFpReg();
                    const val = switch (ins.lhs) {
                        .f64 => |v| v,
                        else => return self.refuse(@src()),
                    };
                    try self.emitFmovImmFp(d, val);
                    if (ins.result) |t| try temps.put(self.alloc, t, d);
                    try self.markFpTemp(ins.result);
                },
                .str => {
                    const reg = try self.allocReg();
                    const s = switch (ins.lhs) {
                        .str => |v| v,
                        else => return self.refuse(@src()),
                    };
                    const sym = try self.internString(s);
                    try self.emitAdrpAdd(reg, sym);
                    if (ins.result) |t| try temps.put(self.alloc, t, reg);
                },
                else => {
                    if (!ins.ty.is_integer()) return self.refuse(@src());
                    const val = switch (ins.lhs) {
                        .i64 => |v| v,
                        else => return self.refuse(@src()),
                    };
                    // A loop-invariant constant already sits in a reserved preheader
                    // register; reuse it instead of re-emitting the mov/movk chain
                    // every iteration. The constant arms of evalDnirValue consult
                    // imm_hoist; this op did not, so the hoist never paid off for
                    // const-defined values (bit-reverse swap masks, mulh loop
                    // constants). The temp must die inside the hoisting loop:
                    // immHoistExit frees the register at the latch, and temps
                    // would otherwise name a reallocated register past it. The
                    // hoisted register is a marked home, so releaseReg,
                    // sweepGpLive, and ensureRegLiveRemap treat it as unfreeable
                    // and reload-into-itself, the same guarantee the constant
                    // arms already rely on.
                    if (self.hoist_depth > 0) {
                        if (self.imm_hoist.get(val)) |hr| {
                            const latch = self.hoist_active[self.hoist_depth - 1].latch;
                            const last_use = if (ins.result) |t|
                                self.value_free_at.get(t) orelse std.math.maxInt(u32)
                            else
                                0;
                            if (last_use <= latch) {
                                try self.ensureRegLive(hr);
                                if (ins.result) |t| try temps.put(self.alloc, t, hr);
                                return;
                            }
                        }
                    }
                    const reg = preferred_result orelse try self.allocReg();
                    if (preferred_result != null) self.claimReg(reg);
                    try self.emitMovImm(reg, val);
                    if (ins.result) |t| try temps.put(self.alloc, t, reg);
                },
            },
            .fp_mov_arg => {
                const d_slot: u5 = @intCast(ins.result orelse return self.refuse(@src()));
                self.used_fp_regs[d_slot] = true;
                switch (ins.lhs) {
                    .f64 => |n| try self.emitFmovImmFp(d_slot, n),
                    else => {
                        const src = try self.evalDnirFpArg(temps, ins.lhs);
                        if (src != d_slot) try self.emitFmovReg(d_slot, src);
                        if (src != d_slot) self.releaseFpReg(src);
                    },
                }
            },
            .mov_arg => {
                // `.field = "vararg"` means `result` is a VARIADIC-tail index,
                // not a parameter register. See `pending_varargs`: on Apple
                // ARM64 the tail is passed in memory, so staging it in x3 (as
                // the plain arm below would) leaves snprintf reading whatever
                // the stack happened to hold — the four-argument
                // `snprintf(buf, 24, "%lld", n)` printed a pointer, while the
                // three-argument `snprintf(buf, 24, "AB")` was already correct.
                if (std.mem.eql(u8, ins.field, "vararg")) {
                    const idx: u5 = @intCast(ins.result orelse return self.refuse(@src()));
                    if (idx >= self.pending_varargs.len) return self.refuse(@src());
                    self.pending_varargs[idx] = .{ .operand = ins.lhs };
                    if (idx + 1 > self.pending_vararg_count) self.pending_vararg_count = idx + 1;
                    return;
                }
                const slot: u5 = @intCast(ins.result orelse return self.refuse(@src()));
                if (slot >= 8) {
                    // AAPCS64 stack argument: the ninth and later GP arguments
                    // travel on the stack at [sp,#(slot-8)*8]. Defer them through
                    // the same stack-flush the variadic tail uses — the call arms
                    // materialize and push the block between the caller-save area
                    // and `bl`, and the callee prologue loads them back. No packing.
                    const idx: u5 = slot - 8;
                    if (idx >= self.pending_varargs.len) return self.refuse(@src());
                    self.pending_varargs[idx] = .{ .operand = ins.lhs };
                    if (idx + 1 > self.pending_vararg_count) self.pending_vararg_count = idx + 1;
                    return;
                }
                switch (ins.lhs) {
                    .i64 => |n| {
                        try self.preserveArgReg(temps, pinned, slot, at);
                        try self.emitMovImm(slot, n);
                        self.markStagedArgReg(slot);
                        return;
                    },
                    .str => |s| {
                        try self.preserveArgReg(temps, pinned, slot, at);
                        const sym = try self.internString(s);
                        try self.emitAdrpAdd(slot, sym);
                        self.markStagedArgReg(slot);
                        return;
                    },
                    else => {},
                }
                const reg = try self.evalDnirValue(temps, ins.lhs);
                if (reg != slot) {
                    try self.preserveArgReg(temps, pinned, slot, at);
                    try self.emitMovReg(slot, reg);
                }
                if (slot == 0 and ins.lhs == .temp) {
                    self.extern_preserve_x0 = true;
                    self.extern_preserve_x0_temp = ins.lhs.temp;
                }
                // Match `call_direct` inline-lhs cleanup when the operand already
                // occupies the target ABI slot.
                self.releaseDnirTemp(pinned, ins.lhs, reg);
                // Now this argument occupies `slot`; keep the scratch allocator out
                // of it until the call is emitted (see `pending_arg_regs`).
                self.markStagedArgReg(slot);
            },
            .store_local => {
                // A binding with no DNIR consumer does not demand a physical
                // place. An integer immediate has no effect to preserve, so
                // omit both materialization and the permanent local home. This is
                // deliberately narrower than general dead-code elimination:
                // temp/local operands still carry ownership and may need their
                // producer register retired by the value allocator.
                if (ins.result) |slot| {
                    if (ins.application == null and !self.value_free_at.contains(slot)) switch (ins.lhs) {
                        .i64 => return,
                        else => {},
                    };
                }
                // Dispatch on what the VALUE is, not only on how the
                // instruction is typed. `x2: f64 = x * x` arrived with a
                // non-f64 `ty`, so the store took the integer path and emitted
                // `mov x9, x18` — a general-purpose move of an FP register's
                // NUMBER. The later `fadd` then read d9 instead of d18 and
                // mandelbrot's escape test never fired, answering 100 for a
                // point that escapes at 5.
                if (ins.ty == .f64 or self.valueIsFp(ins.lhs)) {
                    const d = try self.evalDnirValueFp(temps, ins.lhs);
                    if (ins.result) |slot| {
                        // Same rule the integer path below documents: a local
                        // keeps ONE register for its whole lifetime. This arm
                        // REBOUND the slot to whatever register the value
                        // happened to be in, so a consumer emitted against the
                        // local's original home read a register the store never
                        // wrote — `r = math.sqrt(x)` put the result in d1 and
                        // the comparison read d9.
                        // A LOCAL'S FIRST HOME IS NOT ANOTHER LOCAL'S HOME
                        // (GAP-148).
                        //
                        // `orelse d` adopts whatever register the value arrived
                        // in. For a temp that is right and free — the temp dies
                        // into the local and `x2 = x * y` pays no move — but
                        // `evalDnirValueFp`'s `.local` arm answers with another
                        // local's HOME, and `b: f64 = a` then homed `b` in `a`'s
                        // register with nothing emitted at all. Two locals, one
                        // register, for the rest of the function: the next store
                        // to either one writes both, and every later read of the
                        // other answers with it. `markFpHome` also flags a
                        // register d0..d7 wide, so a leaf's f64 parameter is
                        // reachable here too.
                        //
                        // The integer path below never had this: its fresh-home
                        // arms take `allocHomeReg` and MOVE, and adopt `val_reg`
                        // never. `fp_home_regs` is the record that separates the
                        // two cases, and it is already the term `sweepFpLive`
                        // and `releaseFpReg` retire a register by.
                        //
                        // A register OUTSIDE the value band cannot be a home
                        // either: both call arms park an f64 result in d0 —
                        // unconditionally when `ins.application` is absent, which
                        // is every bootstrap `sqrt`/`floor`/`fabs` — and nothing
                        // preserves d0 across the next `bl`. `fpValueReg` is the
                        // one test, asked here and by the claim below, so the
                        // register a store homes in is the register `markFpHome`
                        // is allowed to flag.
                        //
                        // Not the closure — closure is authoritative
                        // `register`/`frame` assignment before emission, per
                        // GAP-148's record, under which a local's home is one
                        // fact the assignment carries rather than one the store
                        // reads off whichever register its operand came in.
                        const kept = if (temps.get(slot)) |r| (if (!self.fp_home_regs[r] and !self.foreignFpName(r, slot)) r else null) else null;
                        const home = pinned.get(slot) orelse kept orelse
                            if (self.fp_home_regs[d] or !fpValueReg(d)) try self.allocFpReg() else d;
                        // Claim the home BEFORE releasing the value register:
                        // on a local's first store they are the same register,
                        // and a release that ran first would hand the local's
                        // home to the next allocation.
                        if (fpValueReg(home)) {
                            self.fp_reg_owner[home] = null;
                            self.markFpHome(home);
                        }
                        if (home != d) {
                            try self.emitFmovReg(home, d);
                            self.releaseFpReg(d);
                        }
                        try pinned.put(self.alloc, slot, home);
                        try temps.put(self.alloc, slot, home);
                        // FP-ness has to travel through the local, not just
                        // through the temp. `x2: f64 = x * x` stores an FP temp
                        // into a slot; without this the later `x2 + y2 > 4.0`
                        // saw two operands it believed were integers, took the
                        // GP comparison path, and never fired — mandelbrot ran
                        // all 100 iterations and answered 100 instead of 5.
                        try self.markFpTemp(slot);
                    } else {
                        self.releaseFpReg(d);
                    }
                } else {
                    var stored_imm_direct = false;
                    if (ins.lhs == .i64 and self.imm_hoist.get(ins.lhs.i64) == null) {
                        if (ins.result) |imm_slot| {
                            if (self.gp_stack_locals.get(imm_slot) == null and
                                self.gpLocalHomeReg(temps, pinned, imm_slot) == null and
                                !self.gpSlotUsesStack(imm_slot))
                            {
                                const imm_home = try self.allocHomeReg();
                                try self.emitMovImm(imm_home, ins.lhs.i64);
                                _ = try self.emitNarrowFit(imm_home, imm_home, ins.ty);
                                self.markGpHome(imm_home);
                                try pinned.put(self.alloc, imm_slot, imm_home);
                                try temps.put(self.alloc, imm_slot, imm_home);
                                stored_imm_direct = true;
                            }
                        }
                    }
                    if (!stored_imm_direct) {
                    const val_reg = try self.evalDnirValue(temps, ins.lhs);
                    // A STORE IS WHERE THE DECLARED WIDTH APPLIES. The C
                    // backend spells this `x = ((uint32_t)(expr))` on every
                    // assignment to a narrow binding, and it is the assignment
                    // — not the arithmetic — that C guarantees to truncate:
                    // `uint8_t e = 250; print(e + 10)` prints 260 in C and
                    // `e = e + 10; print(e)` prints 4. Refitting here
                    // reproduces exactly that, and for the register-homed cases
                    // it costs NOTHING, because the refit replaces the `mov`
                    // that was already being emitted.
                    if (ins.result) |slot| {
                        if (self.gp_stack_locals.get(slot)) |off| {
                            const src = try self.narrowedFrameSource(val_reg, ins.ty);
                            try self.storeGpStackLocal(off, src);
                            if (src != val_reg) self.releaseReg(src);
                            _ = pinned.remove(slot);
                            _ = temps.remove(slot);
                            if (!Arm64Compiler.regIsPinned(pinned, val_reg)) self.releaseReg(val_reg);
                        } else if (self.gpLocalHomeReg(temps, pinned, slot)) |local_reg| {
                            // A STALE NAME IS NOT A PLACE TO STORE INTO EITHER
                            // (GAP-148).
                            //
                            // This arm read `temps` raw, and `evalDnirValue`
                            // refuses that same name for the same local: in
                            // x9..x28, neither a home nor its own id's owner is
                            // a claim `sweepGpLive` or `emitPopVarargs` gave
                            // back, and the pool has since handed the register
                            // to somebody else. The read side falls through to
                            // the frame home; this side moved the local's new
                            // value INTO the stranger's register and homed it
                            // there — and `markGpHome` sets the very flag that
                            // stops `staleGpName` firing, so the STRANGER's own
                            // name, refused a moment earlier, then answers with
                            // the local's value. Two wrong answers, the second
                            // one the read repair being undone.
                            //
                            // A local with no location falls through to the arms
                            // below, which are already the answer for a local
                            // that never had one. Under pressure that refuses
                            // where reuse would have miscompiled.
                            //
                            // Not the closure — closure is authoritative
                            // `register`/`frame` assignment before emission, per
                            // GAP-148's record, under which a local's location
                            // is one fact the assignment carries rather than two
                            // maps a store and a read each interpret.
                            //
                            // THE STORE IS THIS REGISTER'S RELOAD, SO THE ENTRY
                            // THAT WOULD RELOAD IT HAS TO GO.
                            //
                            // `spilled_regs` says the value is in the frame and
                            // the register is not the answer; every read path in
                            // this backend honours that, and `ensureRegLive` is
                            // the `ldr` that makes it true again. The move below
                            // makes it FALSE — it writes this local's new value
                            // into the register the maps name, and the frame
                            // copy it wrote over is the local's PREVIOUS value,
                            // which nothing may read after the store. Leaving
                            // the entry left `ensureRegLiveRemap`'s home branch
                            // free to fire on the very next read and put that
                            // previous value back over the one just stored: a
                            // silent wrong answer for every later read of the
                            // local, on the one path that had just written it.
                            //
                            // A LEAF's home is the victim that reaches here —
                            // the first spill pass in `allocRegExcluding` skips
                            // every home and the second skips only
                            // `gp_call_home_regs`, which a leaf never sets.
                            // Bounded to gate transport with the rest of
                            // GAP-148, since that function refuses above its
                            // spill passes otherwise and `spilled_regs` is empty
                            // everywhere else.
                            //
                            // The claim goes back for the reason `ensureRegLive`
                            // states: `spillReg` performs two halves of one act,
                            // and the half this store does not perform is the
                            // one that stopped the register standing for the
                            // value. `markGpHome` below pays it again for a
                            // homeable register; a `temps`-only local in x0..x7
                            // has no other payer, and restoring it returns the
                            // register to exactly the state it held before the
                            // spill. The slot is released by the removal that
                            // actually took the entry — the removal is
                            // idempotent and a release is not — which is the
                            // rule `sweepGpLive`, `releaseReg`, the hoist unwind
                            // and both reloads already share.
                            //
                            // Not the closure: closure is authoritative
                            // `register`/`frame` assignment before emission, per
                            // GAP-148's record, under which a local's location
                            // is carried by the assignment rather than restated
                            // by a map the store has to remember to retire.
                            if (self.spilled_regs.fetchRemove(local_reg)) |entry| {
                                try self.free_spill_slots.append(self.alloc, entry.value);
                                self.claimReg(local_reg);
                            }
                            try self.emitMovRegFit(local_reg, val_reg, ins.ty);
                            if (val_reg != local_reg and !Arm64Compiler.regIsPinned(pinned, val_reg)) {
                                self.releaseReg(val_reg);
                            }
                            self.markGpHome(local_reg);
                            try pinned.put(self.alloc, slot, local_reg);
                            try temps.put(self.alloc, slot, local_reg);
                        } else if (self.gpSlotUsesStack(slot)) {
                            const off = try self.reserveGpStackLocal(slot);
                            const src = try self.narrowedFrameSource(val_reg, ins.ty);
                            try self.storeGpStackLocal(off, src);
                            if (src != val_reg) self.releaseReg(src);
                            if (!Arm64Compiler.regIsPinned(pinned, val_reg)) self.releaseReg(val_reg);
                        } else {
                            // ADOPT THE PRODUCER REGISTER AS THE HOME. When the
                            // stored value is a temp that dies here, its register
                            // already holds the value in the value band; a fresh
                            // home plus a move is a redundant alloc+mov. The sweep
                            // skips homes, so the dying temp cannot free the
                            // adopted register. Call-free functions only: a caller
                            // must home locals in the callee-saved bank.
                            const adopt = self.adoptTempAsLocalHome(pinned, ins, val_reg, at);
                            const local_reg = if (adopt) val_reg else try self.allocHomeReg();
                            if (adopt) {
                                _ = try self.emitNarrowFit(local_reg, local_reg, ins.ty);
                            } else {
                                try self.emitMovRegFit(local_reg, val_reg, ins.ty);
                            }
                            if (val_reg != local_reg and !Arm64Compiler.regIsPinned(pinned, val_reg)) {
                                self.releaseReg(val_reg);
                            }
                            self.markGpHome(local_reg);
                            try pinned.put(self.alloc, slot, local_reg);
                            try temps.put(self.alloc, slot, local_reg);
                        }
                    } else if (!Arm64Compiler.regIsPinned(pinned, val_reg)) {
                        self.releaseReg(val_reg);
                    }
                    }
                }
            },
            .conv => {
                // THE explicit numeric conversion: the one place
                // float<->int conversion happens. f64->i64 truncates
                // toward zero (fcvtzs; NaN -> 0, out-of-range ->
                // INT64_MIN, exactly the folder's total law). i64->f64
                // widens (scvtf). The crossFile fmov in evalDnirValue is
                // bit transport for spill/ABI and is never consulted
                // here; a conversion that arrived as transport was the
                // f2i miscompile (2.7 -> 4613262278296967578).
                if (ins.ty == .i64) {
                    const d = try self.evalDnirValueFp(temps, ins.lhs);
                    const x = try self.allocReg();
                    try self.emitFcvtzsFromFp(x, d);
                    self.releaseFpReg(d);
                    if (ins.result) |t| try temps.put(self.alloc, t, x);
                } else if (ins.ty == .f64) {
                    const x = try self.evalDnirValue(temps, ins.lhs);
                    const d = try self.allocFpReg();
                    try self.emitScvtfFromGpr(d, x);
                    if (!Arm64Compiler.regIsPinned(pinned, x)) self.releaseReg(x);
                    if (ins.result) |t| try temps.put(self.alloc, t, d);
                    try self.markFpTemp(ins.result);
                } else return self.refuseWith(@src(), "conv-ty");
            },
            .binop => blk: {
                // Both operands are integer literals: answer at compile time.
                // `1000000 / 7` becomes a mov of 142857, never an `sdiv`.
                if (ins.ty != .f64 and ins.lhs == .i64 and ins.rhs == .i64) {
                    if (foldConstBinop(ins.binop, ins.lhs.i64, ins.rhs.i64)) |folded| {
                        const dst = preferred_result orelse try self.allocReg();
                        if (preferred_result != null) self.claimReg(dst);
                        try self.emitMovImm(dst, folded);
                        if (ins.result) |t| try temps.put(self.alloc, t, dst);
                        break :blk;
                    }
                }
                if (ins.ty == .f64) {
                    const comparison = comparisonCondition(ins.binop);
                    // f64 ARITHMETIC outside a float-returning function. The
                    // arm below emits exactly this and is gated on
                    // `cur_func_float`, a per-FUNCTION property — so
                    // `mandel(cx: f64, cy: f64): i64`, a float kernel that
                    // answers with a count, had nowhere to go and was refused.
                    //
                    // `temps` is disambiguated by the CONSUMING instruction's
                    // `ty`, not by the function's: a consumer typed f64 reads
                    // through evalDnirValueFp, an integer consumer through
                    // evalDnirValue. So an FP result is correct here regardless
                    // of what the function returns.
                    if (comparison == null) {
                        const alhs = try self.evalDnirValueFp(temps, ins.lhs);
                        const arhs = try self.evalDnirValueFp(temps, ins.rhs);
                        const adst = try self.allocFpReg();
                        switch (ins.binop) {
                            .add => try self.emitFaddReg(adst, alhs, arhs),
                            .sub => try self.emitFsubReg(adst, alhs, arhs),
                            .mul => try self.emitFmulReg(adst, alhs, arhs),
                            .div => try self.emitFdivReg(adst, alhs, arhs),
                            else => return self.refuseWith(@src(), @tagName(ins.binop)),
                        }
                        if (alhs != adst) self.releaseFpReg(alhs);
                        if (arhs != adst) self.releaseFpReg(arhs);
                        if (ins.result) |t| try temps.put(self.alloc, t, adst);
                        try self.markFpTemp(ins.result);
                        break :blk;
                    }
                    const lhs = try self.evalDnirValueFp(temps, ins.lhs);
                    const rhs = try self.evalDnirValueFp(temps, ins.rhs);
                    const dst = try self.allocReg();
                    try self.emitFcmpReg(lhs, rhs);
                    try self.emitCsetFp(dst, comparison.?);
                    // The sibling comparison arm inside a float kernel already
                    // does this. Both operands are consumed by the `fcmp` and
                    // neither survives into the boolean, so an immediate staged
                    // here (the `4.0` of `x2 + y2 > 4.0`) is pure scratch. It
                    // was leaked, which mattered when nothing was ever freed.
                    self.releaseFpReg(lhs);
                    self.releaseFpReg(rhs);
                    if (ins.result) |t| try temps.put(self.alloc, t, dst);
                } else if (self.cur_func_float) {
                    // A COMPARISON here answers with a boolean, not a double,
                    // so it belongs in a GP register via fcmp+cset — exactly
                    // what the `ins.ty == .f64` branch above already does. That
                    // branch is only selected when the instruction is TYPED
                    // f64, and an integer-valued comparison over float operands
                    // is not, so `zx*zx + zy*zy < 4.0` inside a float kernel
                    // reached this arm, which emits only arithmetic, and was
                    // refused with `lt`.
                    //
                    // Putting a GP index into `temps` inside a float function
                    // looks like a register-space confusion and is not: the
                    // branch above does the same thing for the same reason, and
                    // a comparison's consumer reads an integer.
                    // ...but only when the OPERANDS are floats. Being inside a
                    // float kernel says nothing about `i < 100`, whose operands
                    // are both integers. Comparing them with `fcmp` read the GP
                    // register NUMBER as an FP register — `i` lives in x10 and
                    // the loop condition became `fcmp d10, d18` — so the branch
                    // was decided by unrelated float state and mandelbrot's
                    // inner loop never terminated (gap[058]).
                    //
                    // `valueIsFp` answers from `fp_temps` instead of from the
                    // function's kind. One FP operand is enough: an integer on
                    // the other side is converted by `evalDnirValueFp` with
                    // `scvtf`, which is what makes `zx*zx + zy*zy < 4.0` — the
                    // shape this arm was written for — still work.
                    const any_fp = self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs);
                    if (comparisonCondition(ins.binop)) |condition| {
                        if (any_fp) {
                            const clhs = try self.evalDnirValueFp(temps, ins.lhs);
                            const crhs = try self.evalDnirValueFp(temps, ins.rhs);
                            const cdst = try self.allocReg();
                            try self.emitFcmpReg(clhs, crhs);
                            try self.emitCsetFp(cdst, condition);
                            self.releaseFpReg(clhs);
                            self.releaseFpReg(crhs);
                            if (ins.result) |t| try temps.put(self.alloc, t, cdst);
                            break :blk;
                        }
                    }
                    // An all-integer OPERATION inside a float kernel is an
                    // ordinary integer operation. Nothing about the enclosing
                    // function changes that.
                    //
                    // This used to classify comparisons and let every
                    // other integer op fall into the FP arithmetic below, which
                    // is the same confusion one step further along:
                    // `i += 1` on an i64 counter emitted
                    // `scvtf d28, x9 / fadd d29, d10, d28 / fmov d10, d29` —
                    // an FP add of `i`'s GENERAL-PURPOSE register number, x10
                    // read as d10. x10 never advanced, so the loop head
                    // `cmp x10, #100` was true forever and the escape test at
                    // iteration 6 answered with `i` still 0. gap[058] found the
                    // comparison half of this; the arithmetic half survived it.
                    if (!any_fp) {
                        const ilhs = try self.evalDnirValue(temps, ins.lhs);
                        const ilhs_held = self.holdReg(ilhs, pinned);
                        const irhs = try self.evalDnirValue(temps, ins.rhs);
                        const irhs_held = self.holdReg(irhs, pinned);
                        const idst = preferred_result orelse try self.allocReg();
                        if (preferred_result != null) self.claimReg(idst);
                        try self.emitCompareOrBinop(idst, ilhs, irhs, ins.binop, ins.ty, ins.divisor, ins.dividend);
                        if (ilhs_held) self.gp_reg_owner[ilhs] = null;
                        if (irhs_held) self.gp_reg_owner[irhs] = null;
                        if (ilhs != idst and !Arm64Compiler.regIsPinned(pinned, ilhs)) self.releaseReg(ilhs);
                        if (irhs != idst and !Arm64Compiler.regIsPinned(pinned, irhs)) self.releaseReg(irhs);
                        if (ins.result) |t| try temps.put(self.alloc, t, idst);
                        break :blk;
                    }
                    const lhs = try self.evalDnirValueFp(temps, ins.lhs);
                    const rhs = try self.evalDnirValueFp(temps, ins.rhs);
                    const dst = try self.allocFpReg();
                    switch (ins.binop) {
                        .add => try self.emitFaddReg(dst, lhs, rhs),
                        .sub => try self.emitFsubReg(dst, lhs, rhs),
                        .mul => try self.emitFmulReg(dst, lhs, rhs),
                        .div => try self.emitFdivReg(dst, lhs, rhs),
                        else => return self.refuseWith(@src(), @tagName(ins.binop)),
                    }
                    if (lhs != dst) self.releaseFpReg(lhs);
                    if (rhs != dst) self.releaseFpReg(rhs);
                    if (ins.result) |t| try temps.put(self.alloc, t, dst);
                    try self.markFpTemp(ins.result);
                } else if (constBinopRealization(ins)) |k| {
                    // THE OPERAND IS A LITERAL, AND THE SELECTOR CAN SEE IT.
                    // Every other arm calls `evalDnirValue` on `ins.rhs` first,
                    // which turns `.i64 = k` into a register with a `mov` and
                    // hands `emitCompareOrBinop` two register NUMBERS. The
                    // constant is true, represented and propagated all the way
                    // here — and then erased one line before instruction
                    // selection by the selector's own signature. That is why
                    // `x * 1`, `x + 0` and `x % 1` each cost a `mov` and an
                    // arithmetic instruction, and why `x % 1` reached `sdiv`.
                    const lhs = try self.evalDnirValue(temps, ins.lhs);
                    const lhs_held = self.holdReg(lhs, pinned);
                    const fwd = if (preferred_result == null)
                        self.identityBinopForwardDst(pinned, ins, k, lhs, at)
                    else
                        null;
                    const dst = fwd orelse preferred_result orelse try self.allocReg();
                    if (fwd == null and preferred_result != null) self.claimReg(dst);
