                        // the buffer a callee just filled through x8, or a
                        // literal whose fields already live in their own
                        // locals; copying eight argument registers over it
                        // would overwrite real data with call debris.
                        //
                        // NEITHER DID A NARROW LITERAL. `.field` is the fact, and it is
                        // already in the IR: `lowerRecordCallAssign` (dnir_lower.zig:3484) is
                        // the ONLY site that names the binding, and the only one that follows
                        // a `call_direct` whose record result is really in x0..x7. The two
                        // literal sites (:4317, :4415) leave `.field` empty and their fields
                        // are already in their own locals under `x.a`, never under `rec.a`.
                        // Copying the argument file over `rec.*` was n stores nothing can
                        // load -- argc/argv/envp for `_main`, live call debris anywhere else.
                        //
                        // `foreign = false` IS THE HONEST ANSWER HERE TODAY, and it is
                        // not the same claim as the callee's. This is the CALLER, and a
                        // caller only knows its callee's convention if the call carries
                        // the fact. It does not: nothing on `dnir.Instr` says "the
                        // relation I am calling declared itself to C", and inferring it
                        // from the callee's SPELLING is exactly the spelling-detector-
                        // as-authority `AGENTS.md` rejects. Publishing the fact with no
                        // consumer would be scenery (HPLS §7), and there is no consumer:
                        // MEASURED — an Idol caller cannot get a record back at all today
                        // (`p = mk(x)` refuses with `application-realization-count`), so
                        // the only live caller of a record-returning relation is C, and C
                        // is the side the callee change above now agrees with.
                        // WHEN THE IDOL CALLER SIDE LANDS this must take the callee's
                        // flag, or a call to an `@comp.c.export` relation reads x0..x2
                        // for a result that arrived in memory.
                        if (ins.field.len > 0 and
                            !scalRecordReturnsIndirect(rec, false))
                        {
                            try self.assignRecordFromAbiRegs(ins.field, rec);
                        }
                    } else return self.refuse(@src());
                }
            },
            .ret => {
                // What comes BACK decides how it comes back. `cur_func_float`
                // is `is_float_kernel`, computed by `f64AbiParamSlots` from
                // PARAMETERS only — it means "this function's arguments arrive
                // in d0-d7" and says nothing about the result. Treating it as a
                // return property sent `f(p: Point): str` down the FP path
                // whenever Point had f64 fields, and the string died in
                // `evalDnirValueFp`. The i64-field spelling of the same
                // function compiled fine, which is what made it look like a
                // record bug rather than a return-classification one.
                //
                // So: the declared return type wins, and the kernel flag only
                // decides when the return type is unknown.
                const ret_via_fp = ins.ty == .f64 or
                    self.cur_func_ret == .f64 or
                    (self.cur_func_float and self.cur_func_ret == .any and ins.ty == .any);
                if (ret_via_fp) {
                    const d = try self.evalDnirValueFp(temps, ins.lhs);
                    if (d != 0) try self.emitFmovReg(0, d);
                    // The coercion is owed whenever the process entry answer
                    // actually leaves in d0. The declared-type gate covers named
                    // f64 entries; untyped roots (script programs) declare .any,
                    // so the instruction own FP type is the second witness.
                    if (self.needsProcessExitF64Coerce() or
                        (self.isProcessEntry() and ret_via_fp)) try self.emitFcvtzsX0FromD0();
                    self.releaseFpReg(d);
                } else if (constRetImm(self, ins.lhs)) |imm| {
                    // A DECLARED narrow return type truncates the answer, and a
                    // literal answer truncates at compile time rather than
                    // costing an instruction: `g: i32 = () \n h: u32 = ... \n h`
                    // is `return (int32_t)h` under the C backend, and a folded
                    // constant must land on the same value the register path
                    // would have produced.
                    const n = narrowFitConst(imm, self.cur_func_ret);
                    // A constant return materializes DIRECTLY into x0. Routing it
                    // through evalDnirValue allocates a scratch register first, so
                    // the emitted floor was `mov x9,#k ; mov x0,x9 ; ret` where the
                    // actual floor — and what clang -O3 emits — is `mov x0,#k ; ret`.
                    // One wasted instruction on the single hottest shape the direct
                    // backend produces (every folded recognizer result returns this
                    // way), so it is worth the special case.
                    try self.emitMovImm(0, n);
                } else if (ins.lhs == .local and self.gp_stack_locals.contains(ins.lhs.local)) {
                    // A stack-homed local return loads DIRECTLY into x0.
                    // Routing it through evalDnirValue allocates a scratch
                    // register first, emitting ldr x9,[sp,#off] ; mov x0,x9
                    // where ldr x0,[sp,#off] suffices. One wasted instruction
                    // on the function-return path.
                    const off2 = self.gp_stack_locals.get(ins.lhs.local).?; try self.emitLdrFrame(0, off2);
                    _ = try self.emitNarrowFit(0, 0, self.cur_func_ret);
                } else {
                    const reg = try self.evalDnirValue(temps, ins.lhs);
                    try self.emitMovRegFit(0, reg, self.cur_func_ret);
                    // Register allocation is linear over the instruction stream
                    // and does not model control flow, so freeing a pinned local
                    // here leaks across the branch: after an early `return n`
                    // the parameter's register looks free and the fall-through
                    // path reuses it for a constant (`n - 1` became `1 - 1`).
                    // A local's register stays reserved for the whole function.
                    if (!Arm64Compiler.regIsPinned(pinned, reg)) self.releaseReg(reg);
                }
                try self.restoreStackFrame();
                try self.emitRet();
                self.returned = true;
            },
            .ret_pack => {
                const vals = ins.vals;
                // NON-EMPTY, and the same count the relation declared, are
                // `realization_validate.resultPackShape`'s questions, asked
                // once for both targets before this file sees the module.
                // WHAT SURVIVES IS THE ABI FACT: AAPCS64 returns at most
                // `max_reg_record_fields` members in registers and selects the
                // x8 indirect-result convention past that. Wasm multi-value has
                // no such window and needs no such choice, so this bound is not
                // a ruling about the pack and does not belong in the shared
                // validator.
                if (vals.len > dnir_lower.max_reg_record_fields) {
                    return self.refuse(@src());
                }
                for (self.cur_func_ret_pack) |ty| switch (ty) {
                    .i8,
                    .i16,
                    .i32,
                    .i64,
                    .u8,
                    .u16,
                    .u32,
                    .u64,
                    .bool,
                    .str,
                    .pointer,
                    => {},
                    else => return self.refuse(@src()),
                };
                // A pack return is a parallel register assignment, not a tuple
                // copy. Emit every acyclic move in place and spend one scratch
                // only for a real cycle. The common `(n, n + 1)` shape is then
                // exactly `add x1,x0,#1; ret`, instead of staging both members.
                var srcs: [dnir_lower.max_reg_record_fields]u5 = @splat(0);
                var pending: [dnir_lower.max_reg_record_fields]bool = @splat(false);
                var cycle_scratch: ?u5 = null;
                for (vals, 0..) |value, i| srcs[i] = try self.evalDnirValue(temps, value);
                for (srcs[0..vals.len], 0..) |src, i| pending[i] = src != @as(u5, @intCast(i));
                while (true) {
                    var remaining = false;
                    var emitted = false;
                    for (pending[0..vals.len], 0..) |move, i| {
                        if (!move) continue;
                        remaining = true;
                        var destination_is_source = false;
                        for (pending[0..vals.len], srcs[0..vals.len], 0..) |other, source, j| {
                            if (j != i and other and source == @as(u5, @intCast(i))) destination_is_source = true;
                        }
                        if (destination_is_source) continue;
                        try self.emitMovReg(@intCast(i), srcs[i]);
                        pending[i] = false;
                        emitted = true;
                    }
                    if (!remaining) break;
                    if (emitted) {
                        if (cycle_scratch) |scratch| {
                            var read = false;
                            for (pending[0..vals.len], srcs[0..vals.len]) |move, source| {
                                if (move and source == scratch) read = true;
                            }
                            if (!read) {
                                self.releaseReg(scratch);
                                cycle_scratch = null;
                            }
                        }
                        continue;
                    }

                    // Every remaining destination is also a remaining source:
                    // a cycle. Preserve one source and redirect every reader of
                    // it through the scratch, which makes the cycle acyclic.
                    var first: usize = 0;
                    while (!pending[first]) : (first += 1) {}
                    const saved = srcs[first];
                    const scratch = try self.allocReg();
                    cycle_scratch = scratch;
                    try self.emitMovReg(scratch, saved);
                    for (pending[0..vals.len], 0..) |move, i| {
                        if (move and srcs[i] == saved) srcs[i] = scratch;
                    }
                }
                if (cycle_scratch) |scratch| self.releaseReg(scratch);
                // Apply declared widths only after all raw values landed; doing
                // it during the parallel copy could narrow a register that a
                // later pack member still needs at full width.
                for (self.cur_func_ret_pack, 0..) |ty, i| {
                    _ = try self.emitNarrowFit(@intCast(i), @intCast(i), ty);
                }
                try self.restoreStackFrame();
                try self.emitRet();
                self.returned = true;
            },
            .ret_record => {
                if (self.cur_func_ret_f64_record != null or
                    (ins.record.len > 0 and f64RecordDesc(self.f64_records, ins.record) != null))
                {
                    try self.emitRetF64RecordFromDnir(temps, ins);
                } else if (self.cur_ret_indirect_reg) |buf| {
                    // AAPCS64 indirect result: the caller reserved the buffer
                    // and handed us its address in x8 (parked in `buf` on
                    // entry). Write every field through it. There is no
                    // parallel-move hazard here — a store cannot clobber a
                    // source register — but a field left UNWRITTEN is worse
                    // than a wrong register, because the caller reads the slot
                    // regardless and sees whatever the frame held. The lowerer
                    // guarantees one value per declared field; assert the count
                    // rather than trust it.
                    const vals = try self.dnirRetRecordVals(ins);
                    const rec = self.cur_func_ret_record orelse return self.refuse(@src());
                    if (vals.len != rec.field_names.len) return self.refuse(@src());
                    for (vals, 0..) |v, i| {
                        const off: u16 = @intCast(i * 8);
                        switch (rec.field_kinds[i]) {
                            .f64 => {
                                const d = try self.evalDnirValueFp(temps, v);
                                try self.emitStrBaseImmFp(d, buf, off);
                                self.releaseFpReg(d);
                            },
                            .i64, .str => {
                                const src = try self.evalDnirValueBits(temps, v);
                                try self.emitStrBaseImm(src, buf, off);
                                if (!Arm64Compiler.regIsPinned(pinned, src)) self.releaseReg(src);
                            },
                        }
                    }
                } else {
                    // Returning a record is a PARALLEL move into x0..x7, not a
                    // sequential one. Writing x0 first and then reading a later
                    // field that still lives in x0 — a parameter, typically —
                    // substitutes the value just stored: `{ kind = 1, start = pos }`
                    // with `pos` in x0 returned `kind` for `start`.
                    //
                    // Evaluate every field, stage each through a scratch register
                    // (allocReg hands out x9+, so it can never alias an ABI
                    // destination), then commit. Redundant `mov`s here are folded
                    // by the peephole; a wrong answer is not recoverable.
                    //
                    // This used to read `lhs`/`rhs`/`third` and stop, so a
                    // 4th..8th field was simply never returned while the caller
                    // still copied x0..x7 out — `{ a=1 … e=5 }` handed back
                    // whatever x4 held. Walk every field.
                    const vals = try self.dnirRetRecordVals(ins);
                    const n = vals.len;
                    if (n == 0 or n > dnir_lower.max_reg_record_fields) return self.refuse(@src());
                    // Mixed records now retain their exact field classes in the
                    // scalar map. A two-word foreign result still lawfully arrives
                    // in x0/x1; an indirect mixed result is rejected by lowering
                    // because this emitter has no mixed GP/FP buffer-store path.
                    // Keep the physical threshold here as a final guard for
                    // hand-built DNIR: a wrong number that links is not a refusal.
                    if (dnir_lower.recordReturnIsIndirectFields(n, self.cur_func_foreign)) {
                        return self.refuse(@src());
                    }
                    var srcs: [dnir_lower.max_reg_record_fields]u5 = @splat(0);
                    var staged: [dnir_lower.max_reg_record_fields]u5 = @splat(0);
                    for (vals, 0..) |v, i| srcs[i] = try self.evalDnirValue(temps, v);

                    var i: usize = 0;
                    while (i < n) : (i += 1) {
                        staged[i] = try self.allocReg();
                        try self.emitMovReg(staged[i], srcs[i]);
                    }
                    i = 0;
                    while (i < n) : (i += 1) {
                        try self.emitMovReg(@intCast(i), staged[i]);
                        self.releaseReg(staged[i]);
                    }
                    i = 0;
                    while (i < n) : (i += 1) {
                        if (!Arm64Compiler.regIsPinned(pinned, srcs[i])) self.releaseReg(srcs[i]);
                    }
                }
                try self.restoreStackFrame();
                try self.emitRet();
                self.returned = true;
            },
            .br => {
                switch (ins.branch_condition) {
                    .unconditional => {
                        const patch_off = try self.emitB(0);
                        try branch_patches.append(self.alloc, .{ .patch_off = patch_off, .target_instr = ins.branch_target, .is_cond = false });
                    },
                    .when_true, .when_false => {
                        const cond = try self.evalDnirValue(temps, ins.lhs);
                        // The condition is a materialized boolean; compare that
                        // value rather than reusing flags from its producer.
                        try self.emitCmpZero(cond);
                        const arm: Condition = if (ins.branch_condition == .when_true) .ne else .eq;
                        const patch_off = try self.emitBCond(arm, 0);
                        self.releaseReg(cond);
                        try branch_patches.append(self.alloc, .{ .patch_off = patch_off, .target_instr = ins.branch_target, .is_cond = true });
                    },
                }
            },
            .load_field => {
                const base = if (ins.req_alias.len > 0) ins.req_alias else "rec";
                const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, ins.field });
                defer self.alloc.free(key);
                if (self.fp_stack_slots.get(key)) |slot| {
                    if (slot.float) {
                        const d = try self.allocFpReg();
                        try self.emitLdrFrameFp(d, slot.off);
                        if (ins.result) |t| try temps.put(self.alloc, t, d);
                        try self.markFpTemp(ins.result);
                    } else {
                        const reg = try self.loadStackField(key);
                        if (ins.result) |t| try temps.put(self.alloc, t, reg);
                    }
                } else if (self.cur_func_float) {
                    const d = self.fp_locals.get(key) orelse return self.undefinedKey(@src(), "fp local", key);
                    if (ins.result) |t| try temps.put(self.alloc, t, d);
                    try self.markFpTemp(ins.result);
                } else {
                    const reg = try self.loadStackField(key);
                    if (ins.result) |t| try temps.put(self.alloc, t, reg);
                }
            },
            .str_len => {
                // Inline byte-length scan — the sovereign form of `string.len`.
                // No libc `strlen`, no runtime helper: just a load/compare loop,
                // so a tokenizer using it stays in the direct backend subset.
                //
                //     len = 0
                //   loop: b = ldrb [base + len]
                //         if b == 0 goto done
                //         len += 1
                //         goto loop
                //   done:
                const base = try self.evalDnirValue(temps, ins.lhs);
                const len = try self.allocReg();
                try self.emitMovImm(len, 0);
                // GAP-118: NULL is unknown, not "". A strlen walk must not
                // `ldrb` it — `cited(path)` after `hits += flag(...)` saw
                // address 0 and SIGSEGV'd.
                try self.emitCmpZero(base);
                const null_patch = try self.emitBCond(.eq, 0);
                const one = try self.allocReg();
                try self.emitMovImm(one, 1);
                const addr = try self.allocReg();
                const byte = try self.allocReg();

                const loop_off: u32 = @intCast(self.code.items.len);
                try self.emitAddReg(addr, base, len);
                try self.emitLdrb(byte, addr);
                try self.emitCmpZero(byte);
                const done_patch = try self.emitBCond(.eq, 0);
                try self.emitAddReg(len, len, one);
                const back_patch = try self.emitB(0);
                const done_off: u32 = @intCast(self.code.items.len);

                try self.patchCondBranch(done_patch, done_off);
                try self.patchCondBranch(null_patch, done_off);
                try self.patchB(back_patch, loop_off);

                self.releaseReg(byte);
                self.releaseReg(addr);
                self.releaseReg(one);
                if (!Arm64Compiler.regIsPinned(pinned, base)) self.releaseReg(base);
                if (ins.result) |t| try temps.put(self.alloc, t, len);
            },
            .print_value => {
                // Native observable output — the construct that used to force
                // the C-emit bootstrap fallback. `print` lowers to libc
                // puts/printf (Mach-O `_puts`/`_printf` externs), so a program
                // whose only dynamic surface is output stays sovereign machine
                // code. `.ty` selects the call shape:
                //   .str  → puts(v)                 (puts appends \n, Lua print shape)
                //   .i64  → printf("%lld\n", v)
                //   .f64  → printf("%f\n", v)
                //   else  → printf("\n")            (zero-arg print → blank line;
                //           puts would append its own \n and print two lines)
                // ABI (Apple arm64 variadic convention): printf's variadic
                // arguments are passed ON THE STACK at the caller's sp, not in
                // x1/d0 (verified against xcrun clang -S output and raw asm:
                // passing in x1 prints garbage, storing at [sp,#0] prints
                // correctly). So the arg is parked in x2 and stored at [sp,#0]
                // after reserving the vararg slot. w8 is NOT needed (Apple's
                // printf ignores the AAPCS FP-count register for the stack
                // convention).
                //
                // THE ARGUMENTS ARE PLACED AFTER `emitSaveCallerRegs`, NOT
                // BEFORE IT. x0 and x2 are not scratch: they are ordinary
                // allocatable registers, and in a body that reads a RECORD
                // PARAMETER they are that record's second and fourth incoming
                // fields. Staging `adrp x0, fmt` and `mov x2, value` ahead of
                // the save made the save preserve PRINTF'S OWN ARGUMENTS, and
                // the restore then wrote them back over the caller's live
                // values — so the fields riding EVEN argument registers came
                // back destroyed while the odd ones survived. Measured on
                //
                //     _r4: { a: i64, b: i64, c: i64, d: i64 }
                //     _show: i64 = (p: _r4)   print(99)   return p.<f>
                //
                // as a = 208 (the low byte of the format string's address),
                // b = 2, c = 99 (print's OWN argument, read back as a field),
                // d = 4. Exit 0, no diagnostic: a silent wrong answer in the
                // middle of a core feature.
                //
                // The split the fix keeps is between EVALUATION and PLACEMENT.
                // Evaluation may load from `[sp,#off]` and therefore must stay
                // ABOVE the save, which moves `sp`; placement is a register
                // move that reads a register the save copied but did not
                // change, so it belongs BELOW it, where x0..x7 are already
                // preserved and free to overwrite. This is exactly the
                // discipline `call_direct` gets from `preserveArgReg`, which
                // `print_value` never called.
                //
                // `.field = "nonl"` is `stdout:write`: THE SAME EGRESS WITHOUT
                // THE LINE ENDING. It is a caller property, not a value one, so
                // it selects the call shape rather than editing it — `puts`
                // cannot be asked not to append, so the `.str` arm becomes
                // `printf("%s", v)` and travels the stack-vararg path the
                // numeric arms already use. `print` is untouched.
                const nonl = std.mem.eql(u8, ins.field, "nonl") or std.mem.eql(u8, ins.field, "byte");
                // `puts` alone takes the value in x0 and no format. Every other
                // shape is a `printf`: format in x0, value in x2 and then at
                // [sp,#0]. A VALUELESS print is a `printf` with no value at all,
                // and must reserve no slot — its emitted bytes are unchanged.
                const use_puts = ins.ty == .str and !nonl;
                const has_value = ins.ty == .str or ins.ty == .i64 or ins.ty == .f64;
                const stack_arg = has_value and !use_puts;
                // 0 is a VALID interned-string symbol (the first one), so it cannot mean
                // "no format": a program whose first print is numeric skipped its
                // adrp x0 and trapped inside printf. null is the absence.
                var fmt_sym: ?u32 = null;
                // WHERE THE VALUE IS *NOW*, above the save. `value_home` is
                // where it has to BE at the call; the move between them is
                // emitted below the save.
                const value_home: u5 = if (use_puts) 0 else 2;
                var value_reg: ?u5 = null;
                var value_fp: ?u5 = null;
                var value_imm: ?i64 = null;
                switch (ins.ty) {
                    .str => {
                        const reg = try self.evalDnirValue(temps, ins.lhs);
                        value_reg = reg;
                        self.releaseDnirTemp(pinned, ins.lhs, reg);
                        fmt_sym = if (use_puts) null else try self.internString("%s");
                    },
                    .i64 => {
                        const reg = try self.evalDnirValue(temps, ins.lhs);
                        value_reg = reg;
                        self.releaseDnirTemp(pinned, ins.lhs, reg);
                        const is_byte = std.mem.eql(u8, ins.field, "byte");
                        fmt_sym = try self.internString(if (is_byte) "%c" else if (nonl) "%lld" else "%lld\n");
                    },
                    .f64 => switch (ins.lhs) {
                        // Literal: the bit pattern goes straight into x2, which
                        // carries this physical mixed-ABI source — no FP reg.
                        .f64 => |n| value_imm = @bitCast(n),
                        // A live FP register is preserved by the save and not
                        // altered by it, so the `fmov` reads it just as well
                        // below the save as above.
                        else => value_fp = try self.evalDnirValueFp(temps, ins.lhs),
                    },
                    // A valueless `print` is a blank line. A valueless WRITE is
                    // nothing at all, and emitting `printf("")` for it would be
                    // a call with no effect rather than no call.
                    else => fmt_sym = if (nonl) null else try self.internString("\n"),
                }
                if (ins.ty == .f64) fmt_sym = try self.internString(if (nonl) "%f" else "%f\n");
                // A valueless WRITE is nothing at all — no call, not an empty one.
                if (!has_value and nonl) {
                    try self.syncGateLocalTempsAfterCall(temps, pinned);
                    return;
                }
                // Unknown str (NULL from missing os.args / os.env) is not a
                // C "(null)" sentinel. Skip the call. Present empty still prints.
                // The guard reads the register the string is IN — which above
                // the save is wherever evaluation left it, not yet the ABI
                // home. Testing x0 unconditionally would have tested the FORMAT
                // string — never null — and passed a null through to `%s`.
                var skip: ?u32 = null;
                if (ins.ty == .str) {
                    try self.emitCmpZero(value_reg orelse return self.refuse(@src()));
                    skip = try self.emitBCond(.eq, 0);
                }
                const save = try self.emitSaveCallerRegs();
                // PLACEMENT. x0..x7 are on the stack now, so writing them costs
                // the caller nothing. Value first, format second: a value that
                // evaluation happened to leave in x0 would otherwise be
                // overwritten by its own format string.
                if (value_reg) |reg| {
                    if (reg != value_home) try self.emitMovReg(value_home, reg);
                } else if (value_fp) |d| {
                    try self.emitFmovToGpr(value_home, d);
                } else if (value_imm) |bits| {
                    try self.emitMovImm(value_home, bits);
                }
                if (fmt_sym) |sym| try self.emitAdrpAdd(0, sym);
                if (stack_arg) {
                    // Reserve a 16-byte slot so sp stays 16-byte aligned at the
                    // call; the vararg goes at [sp,#0], [sp,#8] is padding.
                    try self.emitSubSpTemp(16);
                    try self.emitStrSp(2, 0);
                }
                try self.ensureExternalSymbol(if (use_puts) "puts" else "printf");
                try self.emitBl(if (use_puts) "puts" else "printf");
                if (nonl) {
                    // `stdout:write` is RAW HOST EGRESS: the peer is a protocol
                    // client (newline-delimited JSON-RPC over a pipe), not a
                    // terminal, and libc stdio is block-buffered on a pipe — an
                    // unflushed write is a write the peer never receives until
                    // 4 KiB accumulate or the process exits. A long-lived stdio
                    // server (tools/mcp/native.id) hangs its client's handshake
                    // forever on exactly that; measured, the initialize response
                    // sat unflushed for the full 60 s client timeout. `print`/
                    // `puts` keeps the buffered line shape: programs that print
                    // and exit pay nothing.
                    try self.emitMovImm(0, 0); // fflush(NULL): flush every output stream
                    try self.ensureExternalSymbol("fflush");
                    try self.emitBl("fflush");
                }
                if (stack_arg) try self.emitAddSpTemp(16);
                try self.emitRestoreCallerRegs(save);
                if (skip) |off| try self.patchCondBranch(off, @intCast(self.code.items.len));
                try self.syncGateLocalTempsAfterCall(temps, pinned);
            },
            .load_global => {
                const t = ins.result orelse return self.refuse(@src());
                if (ins.field.len == 0) return self.refuse(@src());
                const sym = try self.internGlobal(ins.field);
                const dst = try self.allocReg();
                try self.emitAdrpAdd(dst, sym);
                // The address register IS the destination: `adrp/add` computes
                // the word's address into it and the load overwrites it with the
                // word. One register, not two, and nothing else is live in it.
                try self.emitLdrBaseImm(dst, dst, 0);
                try temps.put(self.alloc, t, dst);
            },
            .store_global => {
                if (ins.field.len == 0) return self.refuse(@src());
                const sym = try self.internGlobal(ins.field);
                // The VALUE is evaluated first. Materializing the address first
                // would hold a register across whatever the value's own lowering
                // needs, which for a call operand is the whole call.
                const val = try self.evalDnirValue(temps, ins.lhs);
                const addr = try self.allocReg();
                try self.emitAdrpAdd(addr, sym);
                try self.emitStrBaseImm(val, addr, 0);
                self.releaseReg(addr);
                self.releaseDnirTemp(pinned, ins.lhs, val);
            },
            .alloc_slots => {
                const t = ins.result orelse return self.refuse(@src());
                if (self.const_bases.get(t)) |symbol_index| {
                    // DETERMINED, NEVER WRITTEN, NEVER ESCAPING. The words are
                    // already in `__TEXT,__const`, so there is nothing to build:
                    // two instructions place the section's address and the
                    // element stores below are not emitted at all. `load_index`
                    // needs no change — it indexes this base exactly as it
                    // indexed a frame base.
                    const dst = try self.allocReg();
                    try self.emitAdrpAdd(dst, symbol_index);
                    try temps.put(self.alloc, t, dst);
                    return;
                }
                const off = self.slot_bases.get(t) orelse return self.refuse(@src());
                const dst = try self.allocReg();
                try self.emitAddFrameImm(dst, off);
                try temps.put(self.alloc, t, dst);
            },
            .load_index, .store_index => |op| switch (ins.ty) {
                .i64 => {
                    const is_const_store = op == .store_index and b: {
                        const base_id = switch (ins.lhs) {
                            .temp, .local => |id| id,
                            else => break :b false,
                        };
                        break :b self.const_bases.contains(base_id);
                    };
                    if (is_const_store) {
                        // THE INITIALIZING RUN OF A PROMOTED TABLE IS NOT EMITTED.
                        //
                        // This is the whole win: `mov` the literal / `str` it at a folded
                        // offset, twice per element, replaced by nothing. It is only safe
                        // because `const_table.recognize` proved these stores are the ONLY
                        // writes this base ever receives and that they all precede every
                        // read — a table that is written anywhere else never reaches here,
                        // it keeps its frame region and every one of these instructions.
                        //
                        // BOTH FACES OF THE BASE. The initializing run addresses the
                        // region as a `.temp`; once the table's name is bound to the same
                        // id every later mention arrives as a `.local`. They are one
                        // storage (`evalDnirValue` resolves both through `temps`), so
                        // both have to be recognized here.
                        return;
                    }
                    const base = try self.evalDnirValue(temps, ins.lhs);
                    // A CONSTANT INDEX NEEDS NO INDEX REGISTER AT ALL.
                    //
                    // `base + (k - 1) * 8` is a compile-time number when `k` is, so
                    // the whole address computation collapses into the load/store's
                    // own unsigned-offset field. That removed three instructions per
                    // element from the materialization of a positional table — the
                    // binding emits one `store_index` per element with a LITERAL
                    // index, and was paying `mov idx / mov one / sub` to rediscover
                    // a number the compiler already had. A 32-element table cost 160
                    // instructions to set up; it now costs 64. Same for a constant
                    // read: `t(3)` is one `ldr`.
                    //
                    // The guard is the encoding's, not a heuristic: the offset field
                    // is a 12-bit count of 8-byte units, so `k` must be at least 1
                    // (Idol's own lower bound) and no more than 4096. Anything else
                    // falls through to the register form below, which is correct at
                    // every index.
                    const const_off: ?u16 = blk: {
                        const k = switch (ins.rhs) {
                            .i64 => |n| n,
                            else => break :blk null,
                        };
                        if (k < 1 or k > 4096) break :blk null;
                        break :blk @intCast((k - 1) * 8);
                    };
                    if (const_off) |off| {
                        if (op == .load_index) {
                            const dst = try self.allocReg();
                            try self.emitLdrBaseImm(dst, base, off);
                            if (ins.result) |t| try temps.put(self.alloc, t, dst);
                        } else {
                            const val = try self.evalDnirValueBits(temps, ins.third);
                            try self.emitStrBaseImm(val, base, off);
                            self.releaseDnirTemp(pinned, ins.third, val);
                        }
                        self.releaseDnirTemp(pinned, ins.lhs, base);
                        return;
                    }
                    const idx = try self.evalDnirValue(temps, ins.rhs);
                    const biased = try self.allocReg();
                    try self.emitSubImm(biased, idx, 1);
                    if (op == .load_index) {
                        const dst = try self.allocReg();
                        try self.emitLdrScaled(dst, base, biased);
                        if (ins.result) |t| try temps.put(self.alloc, t, dst);
                    } else {
                        const val = try self.evalDnirValueBits(temps, ins.third);
                        try self.emitStrScaled(val, base, biased);
                        self.releaseDnirTemp(pinned, ins.third, val);
                    }
                    self.releaseReg(biased);
                    self.releaseDnirTemp(pinned, ins.lhs, base);
                    self.releaseDnirTemp(pinned, ins.rhs, idx);
                },
                .f64 => {
                    const is_const_store = op == .store_index and b: {
                        const base_id = switch (ins.lhs) {
                            .temp, .local => |id| id,
                            else => break :b false,
                        };
                        break :b self.const_bases.contains(base_id);
                    };
                    if (is_const_store) return;
                    const base = try self.evalDnirValue(temps, ins.lhs);
                    const const_off: ?u16 = blk: {
                        const k = switch (ins.rhs) {
                            .i64 => |n| n,
                            else => break :blk null,
                        };
                        if (k < 1 or k > 4096) break :blk null;
                        break :blk @intCast((k - 1) * 8);
                    };
                    if (const_off) |off| {
                        if (op == .load_index) {
                            const dst = try self.allocReg();
                            try self.emitLdrBaseImmFp(dst, base, off);
                            if (ins.result) |t| try temps.put(self.alloc, t, dst);
                        } else {
                            const val = try self.evalDnirValueFp(temps, ins.third);
                            try self.emitStrBaseImmFp(val, base, off);
                            self.releaseDnirTemp(pinned, ins.third, val);
                        }
                        self.releaseDnirTemp(pinned, ins.lhs, base);
                        return;
                    }
                    const idx = try self.evalDnirValue(temps, ins.rhs);
                    const biased = try self.allocReg();
                    try self.emitSubImm(biased, idx, 1);
                    if (op == .load_index) {
                        const dst = try self.allocReg();
                        try self.emitLdrScaledFp(dst, base, biased);
                        if (ins.result) |t| try temps.put(self.alloc, t, dst);
                    } else {
                        const val = try self.evalDnirValueFp(temps, ins.third);
                        try self.emitStrScaledFp(val, base, biased);
                        self.releaseDnirTemp(pinned, ins.third, val);
                    }
                    self.releaseReg(biased);
                    self.releaseDnirTemp(pinned, ins.lhs, base);
                    self.releaseDnirTemp(pinned, ins.rhs, idx);
                },
                .f32 => {
                    // 4-byte elements, Idol-indexed from 1. No const-index fast path
                    // (offset field counts 8-byte units); always use register form.
                    // `emitLdrScaled` / `emitStrScaled` are integer-only (GP registers),
                    // so load/store through GP and convert to/from FP at the boundary.
                    const base = try self.evalDnirValue(temps, ins.lhs);
                    const idx = try self.evalDnirValue(temps, ins.rhs);
                    const biased = try self.allocReg();
                    try self.emitSubImm(biased, idx, 1);
                    if (op == .store_index) {
                        const val = try self.evalDnirValueFp(temps, ins.third);
                        const val_bits = try self.allocReg();
                        try self.emitFmovToGpr(val_bits, val);
                        try self.emitStrScaled(val_bits, base, biased);
                        self.releaseDnirTemp(pinned, ins.third, val);
                        self.releaseReg(val_bits);
                    } else {
                        const bits = try self.allocReg();
                        try self.emitLdrScaled(bits, base, biased);
                        const dst = try self.allocReg();
                        try self.emitFmovFromGpr(dst, bits);
                        if (ins.result) |t| try temps.put(self.alloc, t, dst);
                        self.releaseReg(bits);
                    }
                    self.releaseReg(biased);
                    self.releaseDnirTemp(pinned, ins.lhs, base);
                    self.releaseDnirTemp(pinned, ins.rhs, idx);
                },
                else => {
                    // Byte-width: string.byte / string.char semantics.
                    if (op == .store_index) {
                        const sbase = try self.evalDnirValue(temps, ins.lhs);
                        const sidx = try self.evalDnirValue(temps, ins.rhs);
                        const sval = try self.evalDnirValue(temps, ins.third);
                        const saddr = try self.allocReg();
                        if (ins.zero_based_index) {
                            try self.emitAddReg(saddr, sbase, sidx);
                        } else {
                            try self.emitSubImm(saddr, sidx, 1);
                            try self.emitAddReg(saddr, sbase, saddr);
                        }
                        try self.emitStrb(sval, saddr);
                        self.releaseReg(saddr);
                        self.releaseDnirTemp(pinned, ins.lhs, sbase);
                        self.releaseDnirTemp(pinned, ins.rhs, sidx);
                        self.releaseDnirTemp(pinned, ins.third, sval);
                    } else {
                        const base = try self.evalDnirValue(temps, ins.lhs);
                        const idx = try self.evalDnirValue(temps, ins.rhs);
                        const addr = try self.allocReg();
                        if (ins.zero_based_index) {
                            try self.emitAddReg(addr, base, idx);
                        } else {
                            try self.emitSubImm(addr, idx, 1);
                            try self.emitAddReg(addr, base, addr);
                        }
                        const dst = try self.allocReg();
                        try self.emitLdrb(dst, addr);
                        self.releaseReg(addr);
                        if (!Arm64Compiler.regIsPinned(pinned, base)) self.releaseReg(base);
                        if (!Arm64Compiler.regIsPinned(pinned, idx)) self.releaseReg(idx);
                        if (ins.result) |t| try temps.put(self.alloc, t, dst);
                    }
                },
            },
            .hw_fence => {
                if (dnir_hardware.arm64FixedWord(.fence)) |word| {
                    try self.emit(word, "dmb ish");
                } else return self.refuse(@src());
            },
            .hw_spin => {
                if (dnir_hardware.arm64FixedWord(.spin_wait)) |word| {
                    try self.emit(word, "yield");
                } else return self.refuse(@src());
            },
            .hw_unary => {
                // The tags are checked BEFORE `.hw`, so a trap or a vector
                // reduction never reaches `emitHwUnary` and `.hw` stays `.none`
                // for every other consumer of this instruction. See
                // `dnir_lower.trap_abort_tag` / `vec_reduce_add_i64_tag`.
                if (std.mem.eql(u8, ins.field, dnir_lower.trap_abort_tag)) {
                    try self.emitTrapAbort();
                    return;
                }
                if (std.mem.eql(u8, ins.field, dnir_lower.vec_reduce_add_i64_tag)) {
                    try self.emitVecReduceAddI64(temps, pinned, ins);
                    return;
                }
                if (std.mem.eql(u8, ins.field, dnir_lower.index_bounds_tag)) {
                    try self.emitIndexBoundsCheck(temps, pinned, ins);
                    return;
                }
                const src = try self.evalDnirValue(temps, ins.lhs);
                const dst = try self.allocReg();
                try self.emitHwUnary(dst, src, ins.hw);
                if (!Arm64Compiler.regIsPinned(pinned, src)) self.releaseReg(src);
                if (ins.result) |t| try temps.put(self.alloc, t, dst);
            },
            else => return self.refuse(@src()),
        }
    }

    /// The expansion of `dnir_lower.trap_abort_tag` — `abort()` WITHOUT a call.
    ///
    /// Six words, no `bl`, no x30, no relocation, no import. The syscall
    /// number register differs per host; the shape does not:
    ///
    ///     host          getpid          svc       kill
    ///     macOS/aarch64 mov x16, #20   svc #0x80 mov x16, #37
    ///     Linux/aarch64 mov x8,  #172  svc #0    mov x8,  #129
    ///
    ///     mov x1,  #6       ; SIGABRT — must not reuse x0 (it holds the pid)
    ///     brk #1            ; unreachable; SIGTRAP if the kernel ever returns
    ///
    /// macOS takes the BSD number in x16; Linux aarch64 takes the __NR_*
    /// number in x8 — the kernel reads x8 on svc #0, so x16 would be ignored
    /// there.
    ///
    /// WHY THE SIGNAL AND NOT JUST `brk`. `brk` alone is one word and terminates,
    /// but it raises SIGTRAP, so the process exits 133 where `abort()` exited
    /// 134. The exit code is this subset's ONLY observable — it is how every gate
    /// on the surface states its answer — so silently renumbering the trap would
    /// change observable behaviour to buy five words in a block that never
    /// executes. `kill(getpid(), SIGABRT)` reproduces `abort()`'s exit code
    /// EXACTLY, and the trailing `brk` means even a kernel that returned from
    /// `kill` (it cannot for an unblocked SIGABRT, but the register allocator has
    /// no way to know that) still stops here rather than falling through into the
    /// success path with a clobbered x0/x1/x16.
    ///
    /// WHY CLOBBERING x0/x1/x16 IS SAFE, which is the only thing that makes six
    /// unallocated registers acceptable: control never leaves this sequence.
    /// There is no path from here to any later instruction, so no live value can
    /// be read after it, so nothing needs saving — which is precisely the
    /// property `call_extern` did NOT have and precisely why it cost so much.
    ///
    /// `svc` is a kernel entry, not a procedure call: it does not write x30 and
    /// does not consume a frame, so a function whose only "call" was this one is
    /// still a leaf.
    fn emitTrapAbort(self: *Arm64Compiler) Error!void {
        if (self.target_windows) {
            // __fastfail: the documented immediate-termination primitive on
            // Windows. MSVC lowers it to exactly `brk #0xF000` with the
            // failure code in w0; there is no stable raw syscall to use
            // instead (NTDLL numbers change between builds and Microsoft
            // documents direct invocation as unsupported). 0x1D01 is the
            // Idol generic-trap class; WER reports it with the crash.
            try self.emit(0xd283a020, "movz w0, #0x1d01");
            try self.emit(0xd43e0000, "brk #0xF000");
            return;
        }
        // Per-host trap syscalls. builtin.os.tag is comptime, so the
        // unchosen arm vanishes and macOS emission is bit-identical.
        const host_linux = builtin.os.tag == .linux;
        const sc: u5 = if (host_linux) 8 else 16;
        const nr_getpid: u16 = if (host_linux) 172 else 20;
        const nr_kill: u16 = if (host_linux) 129 else 37;
        const svc_word: u32 = if (host_linux) 0xd4000001 else 0xd4001001;
        const svc_text: []const u8 = if (host_linux) "svc #0" else "svc #0x80";
        const movz = struct {
            fn word(reg: u5, imm: u16) u32 {
                return 0xd2800000 | (@as(u32, imm) << 5) | @as(u32, reg);
            }
        }.word;
        try self.emitFmt(movz(sc, nr_getpid), "mov x{d}, #{d}", .{ sc, nr_getpid });
        try self.emit(svc_word, svc_text);
        try self.emitFmt(movz(1, 6), "mov x1, #{d}", .{6});
        try self.emitFmt(movz(sc, nr_kill), "mov x{d}, #{d}", .{ sc, nr_kill });
        try self.emit(svc_word, svc_text);
        try self.emit(0xd4200020, "brk #1");
    }

    /// The expansion of `dnir_lower.index_bounds_tag` — `1 <= i <= len` in ONE
    /// compare.
    ///
    /// The two-sided test used to be two DNIR comparisons and three branches,
    /// which the backend fused into five instructions on the path that is taken:
    ///
    ///     cmp x15, x13        ; x13 hoisted #1
    ///     b.lt  trap
    ///     cmp x15, x14        ; x14 hoisted #len
    ///     b.gt  trap
    ///     b     ok            ; jump over the trap block
    ///
    /// plus two `mov`s outside the loop to hold the two constants. Three of
    /// those five run on EVERY subscript of EVERY iteration, and a subscript is
    /// the single hottest idiom in this tree — an exact dynamic attribution put
    /// array indexing at 66.3% of all executed instructions in `native.out`.
    ///
    /// One UNSIGNED compare answers both sides. `i - 1` wraps for every `i <= 0`
    /// to a value at the top of the range, so
    ///
    ///     sub x16, x15, #1
    ///     cmp x16, #len-1
    ///     b.ls  ok            ; unsigned: in range
    ///     <trap>
    ///     ok:
    ///
    /// rejects `i = 0` and `i = -1` by the same comparison that rejects
    /// `i = len + 1`. Three instructions on the taken path, no hoisted
    /// constants, and the trap block is jumped over by the SAME branch that
    /// tests the range rather than by an extra unconditional one.
    ///
    /// THE SIGNED FORM WOULD BE WRONG HERE, which is why `Condition` grew `ls`
    /// rather than reusing `le`: `-1 <= len - 1` is true signed and false
    /// unsigned, so a signed `b.le` would let `xs(0 - 1)` through to read the
    /// word below the region — the exact defect gap[063] exists to stop.
    ///
    /// `len` is the table's static extent, so `len - 1` is a compile-time
    /// number; the 12-bit immediate covers extents to 4096. Anything wider
    /// refuses rather than guessing, and `guardedTableIndex` never emits this
    /// for a table whose extent is unknown.
    fn emitIndexBoundsCheck(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
    ) Error!void {
        const len = switch (ins.rhs) {
            .i64 => |n| n,
            else => return self.refuse(@src()),
        };
        if (len < 1 or len > 4096) return self.refuse(@src());
        const idx = try self.evalDnirValue(temps, ins.lhs);
        const biased = try self.allocReg();
        try self.emitSubImm(biased, idx, 1);
        try self.emitCmpImm(biased, @intCast(len - 1));
        const in_range = try self.emitBCond(.ls, 0);
        try self.emitTrapAbort();
        try self.patchCondBranch(in_range, @intCast(self.code.items.len));
        self.releaseReg(biased);
        self.releaseDnirTemp(pinned, ins.lhs, idx);
    }

    fn emitHwUnary(self: *Arm64Compiler, dst: u5, src: u5, hw: dnir.HwIntrinsic) Error!void {
        try self.ensureRegLive(src);
        if (hw == .popcount) {
            try self.emitPopcountReg(dst, src);
            return;
        }
        if (hw == .ctz) {
            const tmp = try self.allocReg();
            // RBIT **64-bit** is 0xdac00000. This read 0x5ac00000 -- the 32-bit
            // form -- until `zig build isa-fidelity` diffed the descriptor in
            // lib/target/arm64.id against clang. A 32-bit reverse writes
            // w{tmp}, which zero-fills the top half of x{tmp}, so the `clz x`
            // below counted those 32 zeros as well: `@ctz(8)` answered 35
            // natively and 3 through the C backend. No corpus program takes ctz
            // of anything, so the native differential could not see it; a
            // generated per-instruction sweep could.
            try self.emitFmt(0xdac00000 | (@as(u32, src) << 5) | @as(u32, tmp), "rbit x{d}, x{d}", .{ tmp, src });
            try self.emitFmt(0xdac01000 | (@as(u32, tmp) << 5) | @as(u32, dst), "clz x{d}, x{d}", .{ dst, tmp });
            self.releaseReg(tmp);
            return;
        }
        const word = dnir_hardware.arm64UnaryWord(hw, dst, src) orelse return self.refuse(@src());
        const mnem = switch (hw) {
            .clz => "clz",
            else => return self.refuse(@src()),
        };
        try self.emitFmt(word, "{s} x{d}, x{d}", .{ mnem, dst, src });
    }

    /// Population count via baseline AdvSIMD: `fmov dV,xS / cnt.8b / addv.8b / fmov xD,dV`.
    /// Scalar CNT is FEAT_CSSC, which is 0 on this machine; the vector form is
    /// ARMv8.0 base. The scratch comes from `allocFpReg` (d16-d30, caller-saved,
    /// disjoint from the d0-d7 argument range) and is freed before return; no
    /// slot names it, so its lifetime is exactly these four instructions.
    fn emitPopcountReg(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        const v = try self.allocFpReg();
        try self.emitFmovFromGpr(v, src);
        // cnt Vd.8b, Vn.8b — ground-truth base 0x0E205800 (cnt v16.8b,v16.8b => 0x0E205A10).
        try self.emitFmt(0x0e205800 | (@as(u32, v) << 5) | @as(u32, v), "cnt.8b v{d}, v{d}", .{ v, v });
        // addv Bd, Vn.8b — ground-truth base 0x0E31B800 (addv b16,v16.8b => 0x0E31BA10).
        try self.emitFmt(0x0e31b800 | (@as(u32, v) << 5) | @as(u32, v), "addv.8b b{d}, v{d}", .{ v, v });
        try self.emitFmovToGpr(dst, v);
        self.used_fp_regs[v] = false;
    }

    /// A read whose register FILE disagrees with the file the value lives in.
    ///
    /// `temps` is one map for two register files, so this is not a type error
    /// that some other layer would have caught — it is a plain integer that
    /// names d18 in one reader and x18 in the other, and the emitted
    /// instruction is well-formed nonsense. `render()` in
    /// `examples/mandelbrot.id` reached both directions in one expression:
    /// `(col - WIDTH / 2) * 3.5 / WIDTH` emitted `fmul d17, d12, d16` for a
    /// `col - 40` that lives in x12, then `sdiv x13, x17, x9` for a product
    /// that lives in d17. It printed 80 lines where C printed 3280.
    ///
    /// Refusing is the whole point: DNB001 sends the program to the C backend,
    /// which is right, whereas emitting sends it to a plausible wrong answer.
    /// gap[058] asks for this by name.
    fn crossFile(self: *const Arm64Compiler, v: dnir.Value, want_fp: bool) bool {
        return switch (v) {
            .local, .temp => |id| self.fp_temps.contains(id) != want_fp,
            else => false,
        };
    }

    /// An i64 constant that can be materialized straight into the return register.
    /// Null when the value is not a plain constant, or when it is already hoisted
    /// into a reserved register (reusing that register is cheaper than re-emitting
    /// the mov/movk chain).
    fn constRetImm(self: *Arm64Compiler, v: dnir.Value) ?i64 {
        return switch (v) {
            .i64 => |n| if (self.imm_hoist.get(n) == null) n else null,
            else => null,
        };
    }

    /// A HOISTED CONSTANT IS READ OUT OF A THIRD MAP, AND IT IS SPILLABLE TOO.
    ///
    /// `ensureRegLiveRemap` names the rule: a value's register is only where the
    /// value is while `spilled_regs` does not contain it, and the maps that name
    /// a register cannot rewrite themselves. It answers that for the two maps a
    /// `.local` is read through — `pinned` and `temps`, both reached below — by
    /// reloading a spilled home into the register they already name. `imm_hoist`
    /// is the third such map, named in that same comment, and the three constant
    /// arms are its only readers that hand back a register. They handed it back
    /// without consulting `spilled_regs` at all.
    ///
    /// A hoisted constant's register is a spill victim exactly where a leaf home
    /// is one, and in a CALLING function too: `immHoistEnter` takes it from
    /// `allocReg`, not `allocHomeReg`, so `markGpHome` flags it while
    /// `gp_call_home_regs` — the mask the second spill pass in
    /// `allocRegExcluding` skips — stays clear for it. The first pass skips every
    /// home, the second takes this one.
    ///
    /// After that spill the value is in the frame and the register is not the
    /// answer. `spillReg` clears `used_regs`, and `used_regs` is the whole save
    /// set `emitSaveCallerRegs` builds — so the spill takes the constant out of
    /// the save set while `imm_hoist` still names its register, the next `bl`
    /// clobbers x9..x17, and every later read of that constant answers with the
    /// call's leavings. No diagnostic: the read looks like the reuse it was
    /// written to be.
    ///
    /// `ensureRegLive` is the whole repair, and it is the same reload the home
    /// branch of `ensureRegLiveRemap` already performs: the `ldr` back into the
    /// register every map names, the entry removed, the slot released once on
    /// that removal, and the `claimReg` the loaded value is owed — which is also
    /// the save-set membership the spill took away. Nothing else applies to a
    /// hoisted home: `gp_reg_owner` is null because `markGpHome` nulls it, and
    /// `sweepGpLive` and `releaseReg` both return above a home. It is a no-op
    /// on every unspilled read, which is every read outside gate transport,
    /// because `allocRegExcluding` refuses above its spill passes otherwise.
    ///
    /// Not the closure — closure is authoritative `register`/`frame` assignment
    /// before emission, per GAP-148's record, under which a hoisted constant's
    /// location is carried by the assignment rather than restated by a map each
    /// reader has to remember to check against a second one.
    fn evalDnirValue(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        const r = try self.evalDnirValueUnheld(temps, v);
        self.protectReg(r);
        return r;
    }

    fn evalDnirValueUnheld(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        // FP temp on GP path: convert via fmov instead of refusing.
        // Under high register pressure, spill/reload can leave an FP-marked
        // temp reaching a GP consumer; the bits conversion is lossless.
        if (self.crossFile(v, false)) {
            const d = try self.evalDnirValueFp(temps, v);
            const bits = try self.allocReg();
            try self.emitFmovToGpr(bits, d);
            return bits;
        }
        return switch (v) {
            .void => try self.allocReg(),
            .i64 => |n| blk: {
                // A loop-invariant constant already sits in a reserved register;
                // reuse it instead of re-emitting a mov/movk chain (FTCFTW debt (1)).
                if (self.imm_hoist.get(n)) |r| {
                    try self.ensureRegLive(r);
                    break :blk r;
                }
                const r = try self.allocReg();
                try self.emitMovImm(r, n);
                break :blk r;
            },
            .f64 => |n| blk: {
                const bits: i64 = @bitCast(n);
                if (self.imm_hoist.get(bits)) |r| {
                    try self.ensureRegLive(r);
                    break :blk r;
                }
                const r = try self.allocReg();
                try self.emitMovImm(r, @bitCast(n));
                break :blk r;
            },
            .f32 => |n| blk: {
                // f32 bits in low 4 bytes of the 8-byte slot.
                const bits: i64 = @intCast(@as(u32, @bitCast(n)));
                if (self.imm_hoist.get(bits)) |r| {
                    try self.ensureRegLive(r);
                    break :blk r;
                }
                const r = try self.allocReg();
                try self.emitMovImm(r, bits);
                break :blk r;
            },
            .str => |s| blk: {
                const r = try self.allocReg();
                const sym = try self.internString(s);
                try self.emitAdrpAdd(r, sym);
                break :blk r;
            },
            .local => |slot| {
                if (self.eval_pinned) |p| {
                    if (p.get(slot)) |r| {
                        return try self.ensureRegLiveRemap(temps, r);
                    }
                }
                if (temps.get(slot)) |r| {
                    // A STALE NAME IS NOT A VALUE — THE READ SIDE (GAP-148).
                    //
                    // `temps` entries outlive the claims they stood for:
                    // `emitPopVarargs` releases a scratch register the map
                    // still names, and `sweepGpLive` frees by owner record
                    // while leaving the name alone. Serving such a name hands
                    // back whatever the pool has since put in that register —
                    // measured as `realloc(newsize, newsize)` in a chunked
                    // concat, where the buffer argument read the size temp
                    // through a name `emitPopVarargs` had already released.
                    //
                    // A VALID name carries its owner, which is what
                    // `staleGpName` reads. A stale name falls through to the
                    // frame home — the one place a local's value is still
                    // authoritative — instead of answering with a stranger.
                    if (!self.staleGpName(r, slot)) return try self.ensureRegLiveRemap(temps, r);
                }
                if (self.gp_stack_locals.get(slot)) |off| {
                    return try self.loadGpStackLocal(off);
                }
                return self.undefinedAt(@src(), "local", slot);
            },
            .temp => |t| {
                // A temporary spilled for capacity lives in the frame, not in
                // the register map: reload it into whichever register is free
                // now and re-name it. The slot is released back to the pool —
                // exactly once, because the map entry is removed here and the
                // sweep in `sweepGpLive` only releases entries still present.
                if (self.temp_frame_slots.get(t)) |slot| {
                    const f = try self.allocReg();
                    try self.emitLdrFrame(f, try self.frameSlotOff(slot));
                    _ = self.temp_frame_slots.remove(t);
                    try self.free_spill_slots.append(self.alloc, slot);
                    try temps.put(self.alloc, t, f);
                    if (f >= 9 and f < 29 and f != platform_reserved_reg and !self.gp_home_regs[f]) {
                        self.gp_reg_owner[f] = t;
                    }
                    return f;
                }
                const r = temps.get(t) orelse return self.undefinedAt(@src(), "temp", t);
                // `staleGpName` reads an ABSENT owner as stale because the arm
                // above answers that with the frame home. `planGpStackLocals`
                // keys frame homes by `store_local` result and parameter slots,
                // so a temp has no such fallback, and ownerless-but-claimed is
                // ordinary scratch here — `releaseReg` returns above any owned
                // register, so that is the only state a scratch temp can be in.
                // A register ANOTHER id owns has no such reading: `sweepGpLive`
                // frees by owner record without unnaming, so the map goes on
                // pointing at a register the pool has since re-let.
                if (self.gp_reg_owner[r] != null and self.staleGpName(r, t)) {
                    return self.undefinedAt(@src(), "temp", t);
                }
                return try self.ensureRegLiveRemap(temps, r);
            },
            .record => return self.refuse(@src()),
        };
    }

    /// The 64 BITS of a value, in a general register, whichever register file
    /// the value actually lives in.
    ///
    /// An 8-byte store does not care what the bits MEAN, and `evalDnirValue`
    /// does: for an `.f64` IMMEDIATE it already answers `@bitCast(n)` in a GP
    /// register — exactly this — but for an fp TEMP it answers the number
    /// `temps` holds, which is a `d` register index, and the caller then emits
    /// `str x<that number>`. Same number, wrong register file, no diagnostic:
    /// the store writes whatever integer register shares the index.
    ///
    /// So the immediate and the temp of one type disagreed, and only the
    /// immediate was right. `fmov x, d` is the whole repair and it is free at
    /// every site that was already correct — `valueIsFp` is false there and
    /// this is `evalDnirValue` verbatim.
    fn evalDnirValueBits(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        const r = try self.evalDnirValueBitsUnheld(temps, v);
        self.protectReg(r);
        return r;
    }

    fn evalDnirValueBitsUnheld(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        if (!self.valueIsFp(v)) return self.evalDnirValue(temps, v);
        if (v == .f64) return self.evalDnirValue(temps, v);
        const d = try self.evalDnirValueFp(temps, v);
        const bits = try self.allocReg();
        try self.emitFmovToGpr(bits, d);
        return bits;
    }

    fn evalDnirValueFp(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        const r = try self.evalDnirValueFpUnheld(temps, v);
        self.protectReg(r);
        return r;
    }

    fn evalDnirValueFpUnheld(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        // gap[101]: an INTEGER-classed temp in a float position is a LOSSLESS
        // WIDENING, not a refusal. The `.i64` arm below already does exactly
        // this for an immediate, and its comment reads: "scvtf already existed
        // for exactly this and nothing reached it from here." A temp is the case
        // that never reached it — `(col - WIDTH/2) * 3.5` is a binop, so the
        // integer subexpression arrives as a temp and the immediate arm cannot
        // see it. Traced, not inferred: mandelbrot refuses here on temp 6,
        // defined by an integer binop and consumed by a float operand.
        //
        // Only this direction. float->int is NOT symmetric and must not be
        // added: it truncates, mandelbrot writes no conversion at all, and a
        // backend that truncates unasked still renders an image — the wrong
        // one, past a passing fixture. See gap[101].
        // WHICH GENERAL REGISTER HOLDS THIS VALUE HAS ONE PRODUCER, AND THIS
        // ARM ASKED THE MAP (GAP-148).
        //
        // `temps` is a NAME, and `evalDnirValue` is the function that turns a
        // name into a location: it consults `eval_pinned` above the map, it
        // refuses a name in x9..x28 whose `gp_reg_owner` does not match — the
        // claim released under a name nobody rewrote — and it falls through to
        // the frame home, which is the one place a local's value stays
        // authoritative. This arm read the map raw and converted whatever the
        // named register happened to hold. `crossFile` is true only for
        // `.local`/`.temp`, so the value arms it used to spell are the arms
        // `evalDnirValue` already answers, including the frame home it refused.
        if (self.crossFile(v, true)) {
            const gp = try self.evalDnirValue(temps, v);
            const d = try self.allocFpReg();
            try self.emitScvtfFromGpr(d, gp);
            return d;
        }
        return switch (v) {
            .void => try self.allocFpReg(),
            .f64 => |n| blk: {
                const d = try self.allocFpReg();
                try self.emitFmovImmFp(d, n);
                break :blk d;
            },
            // A STALE NAME IS NOT A VALUE — THE FLOAT FILE (GAP-148). The
            // general arms fall through to `gp_stack_locals`, which
            // `planGpStackLocals` keys for the general file only; here a name
            // whose claim is gone gets the refusal an absent name gets.
            .local => |slot| {
                const r = temps.get(slot) orelse return self.undefinedAt(@src(), "local", slot);
                if (self.foreignFpName(r, slot)) return self.undefinedAt(@src(), "local", slot);
                return r;
            },
            .temp => |t| {
                const r = temps.get(t) orelse return self.undefinedAt(@src(), "temp", t);
                if (self.foreignFpName(r, t)) return self.undefinedAt(@src(), "temp", t);
                return r;
            },
            // An integer immediate in a float position. `(col - WIDTH / 2) *
            // 3.5 / WIDTH` folds `WIDTH / 2` to an i64 constant and then wants
            // it as a double; there is no fmov for an arbitrary integer, so it
            // materializes into a GP register and converts. scvtf already
            // existed for exactly this and nothing reached it from here.
            .i64 => |n| blk: {
                const x = try self.allocReg();
                try self.emitMovImm(x, n);
                const d = try self.allocFpReg();
                try self.emitScvtfFromGpr(d, x);
                self.releaseReg(x);
                break :blk d;
            },
            else => self.refuse(@src()),
        };
    }

    fn evalDnirFpArg(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), v: dnir.Value) Error!u5 {
        if (self.crossFile(v, true)) return self.refuse(@src());
        return switch (v) {
            .f64 => |n| blk: {
                const d = try self.allocFpReg();
                try self.emitFmovImmFp(d, n);
                break :blk d;
            },
            // A STALE NAME IS NOT AN ARGUMENT (GAP-148). This read's one caller
            // emits `fmov d<abi>, d<src>` into an outgoing argument register, so
            // a name `sweepFpLive` left behind and `allocFpReg` re-let sends
            // another value's double to the callee.
            .local => |slot| {
                const r = temps.get(slot) orelse return self.undefinedAt(@src(), "local", slot);
                if (self.foreignFpName(r, slot)) return self.undefinedAt(@src(), "local", slot);
                return r;
            },
            .temp => |t| {
                const r = temps.get(t) orelse return self.undefinedAt(@src(), "temp", t);
                if (self.foreignFpName(r, t)) return self.undefinedAt(@src(), "temp", t);
                return r;
            },
            else => self.refuse(@src()),
        };
    }

    /// Hand a SCRATCH FP register back. Scratch means exactly: inside the value
    /// range, not a local's home, and not currently read by any id. Every
    /// caller passes the register an operand happened to arrive in, and that
    /// register is very often a live local or a temp with reads still ahead —
    /// which is why this function was a no-op, and why making it free
    /// unconditionally would clobber the loop state it is supposed to preserve.
    /// Owned registers retire in `sweepFpLive`, at the instruction index where
    /// their last read is behind them.
    fn releaseFpReg(self: *Arm64Compiler, reg: u5) void {
        if (reg < fp_value_reg_base) return;
        if (reg >= fp_value_reg_base + fp_value_reg_count) return;
        if (self.fp_home_regs[reg]) return;
        if (self.fp_reg_owner[reg] != null) return;
        self.used_fp_regs[reg] = false;
    }

    /// `ty` is the DECLARED width of the operation's result, not of its
    /// operands. A comparison answers 0 or 1 and is never refitted; every other
    /// operation is refitted when the result type is narrower than the
    /// register, which is what makes `h * 16777619` on a `u32` wrap the way the
    /// C backend's `uint32_t` does.
    fn emitCompareOrBinop(
        self: *Arm64Compiler,
        dst: u5,
        lhs: u5,
        rhs: u5,
        op: dnir.BinOpTag,
        ty: native_types.ResolvedType,
        divisor: dnir.DivisorSign,
        dividend: dnir.DivisorSign,
    ) Error!void {
        if (comparisonCondition(op)) |condition| {
            try self.emitCompareResult(dst, lhs, rhs, condition);
            return;
        }
        if (wForm32(ty, op)) {
            try self.emitBinopW32(dst, lhs, rhs, op);
            return;
        }
        try self.emitCompareOrBinopWide(dst, lhs, rhs, op, divisor, dividend);
        _ = try self.emitNarrowFit(dst, dst, ty);
    }

    /// IS THE 32-BIT DESTINATION FORM OF `op` EXACTLY THE REFIT `ty` DEMANDS?
    ///
    /// Two independent facts, and BOTH are needed. A `w` destination
    /// ZERO-EXTENDS into the whole `x` register, which is bit for bit what
    /// `ubfx xd, xn, #0, #32` leaves behind — so the narrowing stops being an
    /// instruction and becomes the encoding. That is only the unsigned answer:
    /// `i32` wants SIGN extension, and a `w` form alone would turn -1 into
    /// 4294967295, so `signed` refuses here and keeps `sxtw`.
    ///
    /// And the low 32 bits of `add`, `sub`, `mul`, `and`, `orr` and `eor`
    /// depend ONLY on the low 32 bits of their operands — carries and borrows
    /// travel upward, never down — so no operand needs to be canonical first.
    /// That is what makes this a pure instruction SELECTION and not a
    /// known-bits analysis.
    ///
    /// EVERYTHING ELSE IS REFUSED, and each for its own reason rather than out
    /// of caution:
    ///   * `shl`/`shr` mask the shift amount to 5 bits in the 32-bit form and 6
    ///     in the 64-bit one, and `dnir_lower.exprCRank` ranks a shift `.int64`
    ///     precisely because the operand is WIDENED before it — `h << 13` on a
    ///     `u32` is a 64-bit value by this language's own conversions, so a
    ///     32-bit shift would answer a different number, not a narrower one.
    ///   * `div`/`idiv`/`mod` are realized with SIGNED `sdiv`, which reads bit
    ///     31 as a sign in the 32-bit form and as an ordinary bit in the 64-bit
    ///     form over a canonical `u32`. Same instruction, different answer.
    ///   * comparisons answer 0 or 1 and are never refitted at all.
    ///   * `u8`/`u16` are not 32 bits wide; their refit is a real mask.
    fn wForm32(ty: native_types.ResolvedType, op: dnir.BinOpTag) bool {
        const fit = narrowFit(ty) orelse return false;
        if (fit.bits != 32 or fit.signed) return false;
        return lowThirtyTwoExact(op);
    }

    /// Is `k` `2^n` for some `1 <= n <= 62`? Returns `n`.
    fn powerOfTwoShift(k: i64) ?u6 {
        if (k <= 1) return null;
        const u: u64 = @bitCast(k);
        if (u & (u - 1) != 0) return null;
        const n = @ctz(u);
        if (n < 1 or n > 62) return null;
        return @intCast(n);
    }

    /// Is `k` `2^n - 1` for some `1 <= n <= 63`? Returns `n`. These are exactly
    /// the low-run AArch64 logical bitmask immediates, encoded `N=1, immr=0,
    /// imms=n-1` — verified against clang's own `and x0, x0, #0x3ff`
    /// (`0x92402400`), `orr #0xf` (`0xb2400c00`) and `eor #0xff` (`0xd2401c00`).
    fn lowMaskWidth(k: i64) ?u6 {
        if (k <= 0) return null;
        const u: u64 = @bitCast(k);
        if (u & (u +% 1) != 0) return null;
        const n = 64 - @clz(u);
        if (n < 1 or n > 63) return null;
        return @intCast(n);
    }

    /// THE MULTIPLIER, SHIFT AND FIXUP SHAPE that turn `x // k` and `x % k`
    /// into a high multiply for a CONSTANT non-power-of-two divisor, or null
    /// when this backend has no sound one.
    ///
    /// `m` is the multiplier as it is MATERIALIZED — a 64-bit pattern. The
    /// EFFECTIVE multiplier is that pattern read UNSIGNED, so when the top bit
    /// is set `m` is a negative i64 and the effective value is `m + 2^64`.
    /// `smulh` computes the high half of the SIGNED product, so the sequence
    /// adds the dividend back to recover the unsigned-multiplier product:
    /// `floor((m + 2^64)*n / 2^64) = smulh(m, n) + n`. That is what
    /// `add_dividend` names, and it is a property of the multiplier's
    /// magnitude, never a choice.
    const FlooredMagic = struct {
        m: i64,
        shift: u6,
        add_dividend: bool,
    };

    /// THE SHIFTED HIGH PRODUCT IS NOT THE FLOORED QUOTIENT, and the whole
    /// design of the emitted sequence follows from exactly how it differs.
    ///
    /// Write `S(n) = floor(Meff*n / 2^(64+s))` — what `smulh`, the optional
    /// `add`, and one `asr` compute. Granlund-Montgomery / Warren choose
    /// `(Meff, s)` so the TRUNCATING quotient is `S(n) + [S(n) < 0]`. Idol's
    /// law is FLOORED, so the naive
    /// port of that sequence is a silent wrong answer for negative dividends,
    /// which is why the literature's shape is not what this emits.
    ///
    /// Chasing the two definitions through each other gives the exact
    /// relation, and it is much sharper than "truncate then fix up":
    ///
    ///     S(n) = floor(n/k) - [n < 0 AND k divides n]
    ///
    /// — the shifted product IS the floored quotient everywhere except at
    /// NEGATIVE EXACT MULTIPLES of the divisor, where it is one lower. So the
    /// residue `v = n - k*S(n)` lies in `[0, k]`, equals the floored remainder
    /// everywhere, and equals `k` — a value a remainder can never take — in
    /// precisely the one case where `S` is short by one. ONE COMPARE against
    /// the divisor register that `msub` already needed distinguishes them:
    ///
    ///     idiv:  q = S + (v == k)
    ///     mod:   r = (v == k) ? 0 : v
    ///
    /// That is why this costs a `cmp` and a `csinc`/`csel` and not the five
    /// instruction sign-disagreement fixup `emitFlooredDivRem` pays: the SIGN
    /// OF THE DIVISOR IS KNOWN HERE, so the correction collapses to an
    /// equality test the multiply's own residue already carries.
    ///
    /// SCOPE: `k >= 3`, not a power of two. `k == 1` and powers of two have
    /// single-instruction realizations above and must not reach this. A
    /// NEGATIVE constant divisor is refused — the relation above is derived for
    /// `k > 0` and the mirrored one is a different proof, so it keeps the
    /// unchanged `sdiv` path rather than an unproved sequence.
    fn magicFlooredDivisor(k: i64) ?FlooredMagic {
        if (k < 3) return null;
        if (powerOfTwoShift(k) != null) return null;
        const ak: u128 = @intCast(k);
        const two63: u128 = @as(u128, 1) << 63;
        const rem63 = two63 % ak;
        if (rem63 + 1 > two63) return null;
        const anc: u128 = two63 - 1 - rem63;
        if (anc == 0) return null;
        var p: u32 = 63;
        var q1: u128 = two63 / anc;
        var r1: u128 = two63 - q1 * anc;
        var q2: u128 = two63 / ak;
        var r2: u128 = two63 - q2 * ak;
        while (true) {
            p += 1;
            if (p > 127) return null;
            q1 *= 2;
            r1 *= 2;
            if (r1 >= anc) {
                q1 += 1;
                r1 -= anc;
            }
            q2 *= 2;
            r2 *= 2;
            if (r2 >= ak) {
                q2 += 1;
                r2 -= ak;
            }
            const delta = ak - r2;
            if (!(q1 < delta or (q1 == delta and r1 == 0))) break;
        }
        const meff: u128 = q2 + 1;
        if (meff == 0 or meff >= (@as(u128, 1) << 64)) return null;
        if (p < 64 or p - 64 > 63) return null;
        const cand = FlooredMagic{
            .m = @bitCast(@as(u64, @intCast(meff))),
            .shift = @intCast(p - 64),
            .add_dividend = meff >= (@as(u128, 1) << 63),
        };
        if (!flooredMagicSound(k, cand)) return null;
        return cand;
    }

    /// THE PROOF, RUN. Not a spot check and not the search's own opinion of
    /// itself: this re-derives `S(n) = floor(n/k) - [n<0 AND k|n]` from
    /// `(m, shift)` alone, over the WHOLE i64 dividend range, in arithmetic
    /// wide enough that nothing wraps.
    ///
    /// It is exhaustive without enumerating 2^64 dividends because the error
    /// term is LINEAR. Writing `n = q*k + r` with `0 <= r < k`,
    ///
    ///     Meff*n / 2^e = q + (q*delta + Meff*r) / 2^e,   delta = Meff*k - 2^e
    ///
    /// so `S(n) = q + floor(A/2^e)` with `A = q*delta + Meff*r` AFFINE in both
    /// `q` and `r`. The requirement is `floor(A/2^e) = -[q < 0 AND r = 0]`, and
    /// an affine function over a rectangle attains its extremes at corners — so
    /// checking the corners of the realizable `(q, r)` region PROVES every
    /// dividend at once. The `r = 0` edge is checked separately because its
    /// target is a different constant.
    ///
    /// A magic that fails here is REFUSED, not repaired: `magicFlooredDivisor`
    /// returns null and the divisor keeps the unchanged `sdiv` realization. So
    /// no search bug can become a wrong answer; it can only cost a divide.
    fn flooredMagicSound(k: i64, mg: FlooredMagic) bool {
        const W = i256;
        const kk: W = k;
        if (kk < 2) return false;
        const meff: W = @as(W, @as(u64, @bitCast(mg.m)));
        if (mg.add_dividend != (meff >= (@as(W, 1) << 63))) return false;
        const e: u9 = 64 + @as(u9, mg.shift);
        const two_e: W = @as(W, 1) << @intCast(e);
        const delta: W = meff * kk - two_e;
        if (delta < 1) return false;

        const nmin: W = -(@as(W, 1) << 63);
        const nmax: W = (@as(W, 1) << 63) - 1;
        const qmin: W = @divFloor(nmin, kk);
        const qmax: W = @divFloor(nmax, kk);
        if (qmin > qmax) return false;
        const rlo: W = nmin - qmin * kk;
        const rhi: W = nmax - qmax * kk;

        // `r = 0`: the target is `floor(q*delta / 2^e) = -[q < 0]`.
        const q0lo: W = if (rlo == 0) qmin else qmin + 1;
        if (q0lo <= qmax) {
            if (q0lo < 0 and q0lo * delta < -two_e) return false;
            if (qmax > 0 and qmax * delta > two_e - 1) return false;
        }

        // `r >= 1`: the target is `floor(A / 2^e) = 0`, i.e. `0 <= A < 2^e`.
        var lo_seen = false;
        var lo: W = 0;
        const rstart: W = if (rlo > 1) rlo else 1;
        if (rstart <= kk - 1) {
            lo = qmin * delta + meff * rstart;
            lo_seen = true;
        }
        if (qmin + 1 <= qmax) {
            const v = (qmin + 1) * delta + meff;
            if (!lo_seen or v < lo) lo = v;
            lo_seen = true;
        }
        if (lo_seen and lo < 0) return false;

        var hi_seen = false;
        var hi: W = 0;
        const rend: W = if (rhi < kk - 1) rhi else kk - 1;
        if (rend >= 1) {
            hi = qmax * delta + meff * rend;
            hi_seen = true;
        }
        if (qmax - 1 >= qmin) {
            const v = (qmax - 1) * delta + meff * (kk - 1);
            if (!hi_seen or v > hi) hi = v;
            hi_seen = true;
        }
        if (hi_seen and hi > two_e - 1) return false;
        return true;
    }

    /// THE EMITTED SEQUENCE MODELLED EXACTLY, in the same wrapping i64 the
    /// machine uses. Exists so a test can compare it against `@divFloor` and
    /// `@mod` on dividends the proof reasons about abstractly — the proof and
    /// the emitter are two authorities and this is what keeps them one.
    fn flooredMagicAnswer(k: i64, mg: FlooredMagic, n: i64, want_mod: bool) i64 {
        const prod: i128 = @as(i128, mg.m) * @as(i128, n);
        var t: i64 = @truncate(prod >> 64);
        if (mg.add_dividend) t = t +% n;
        if (mg.shift > 0) t = t >> mg.shift;
        const v: i64 = n -% t *% k;
        if (want_mod) return if (v == k) 0 else v;
        return if (v == k) t +% 1 else t;
    }

    /// The CANDIDATE PREDICATE. Non-null exactly when `ins.rhs` is a literal
    /// AND `emitBinopConst` has a realization for that (op, value) pair. Kept
    /// separate from the emitter so the two cannot disagree: a value this
    /// returns is a value the emitter must handle, and everything else falls
    /// through to the unchanged register path.
    ///
    /// LAWFULNESS. Every case below is an identity over the FULL i64 domain and
    /// needs no range, sign or alias fact:
    ///   `x±0 = x`  `x*1 = x`  `x*0 = 0`  `x//1 = x`  `x%±1 = 0`
    ///   `x&0 = 0`  `x&-1 = x` `x|0 = x`  `x^0 = x`   `x*2^n = x<<n` (wrapping)
    ///   `x^-1 = ~x` — realized as `mvn`, the ONE instruction AArch64 has for
    ///   it. All-ones is NOT an encodable logical immediate (the bitmask
    ///   encoding excludes it), so `lowMaskWidth(-1)` is null and without this
    ///   case the pair materialized -1 into a register and paid an `eor`.
    /// plus the pure re-encodings `add/sub #imm12`, `and/orr/eor #bitmask` and
    /// `lsl/lsr #sh`, which change no value at all.
    ///
    /// `x % 2^n -> x & (2^n - 1)` AND `x // 2^n -> x >> n` ARE HERE, and the
    /// reason they are here is a LAW ruling, not a new analysis.
    ///
    /// This comment used to say the opposite, correctly for the time: "`%` and
    /// `//` are TRUNCATING here (`-7 % 10` answers -7, measured) and the
    /// mask/shift answer the FLOORED result. They become lawful the moment a
    /// `x >= 0` range fact exists — and no range or known-bits fact exists
    /// anywhere in this compiler."
    ///
    /// Both halves were true. The conclusion was wrong, because the premise was
    /// an ACCIDENT: nothing had ever ruled that `%` truncates. It truncated
    /// because `msub` truncates. `docs/rulings.md` settles it as FLOORED —
    /// `docs/spec/law.md`'s first line makes ordinary Lua meaning the entry of
    /// the specialization chain and Lua's `%` is floored — and under floored
    /// law the mask and the arithmetic shift are IDENTITIES OVER THE FULL i64
    /// DOMAIN for a positive power-of-two divisor, requiring no range fact at
    /// all. `(-7) mod 8 = 1` and `-7 & 7 = 1`; `(-7) // 8 = -1` and
    /// `-7 asr 3 = -1`.
    ///
    /// **THE LAW THAT NEEDS NO FACT IS THE CHEAPER LAW.** That is not a
    /// coincidence to be noted; it is HPLS §2 working — a truer semantics
    /// adding no observable obligation enlarged the realization space.
    ///
    /// LAWFULNESS. Every case below is an identity over the FULL i64 domain and
    /// needs no range, sign or alias fact:
    ///   `x±0 = x`  `x*1 = x`  `x*0 = 0`  `x/1 = x`  `x//1 = x`  `x%±1 = 0`
    ///   `x&0 = 0`  `x&-1 = x` `x|0 = x`  `x^0 = x`   `x*2^n = x<<n` (wrapping)
    ///   `x % 2^n = x & (2^n-1)`   `x // 2^n = x asr n`        (floored law)
    /// plus the pure re-encodings `add/sub #imm12`, `and/orr/eor #bitmask` and
    /// `lsl/lsr/asr #sh`, which change no value at all.
    ///
    /// A POSITIVE NON-POWER-OF-TWO CONSTANT DIVISOR IS NOW HERE TOO, and it is
    /// the one admitted pair whose realization is a SEQUENCE rather than an
    /// instruction. That was the standing reason to exclude it, and it was the
    /// wrong reason: this function's contract is "the emitter has a realization
    /// for this pair", and `emitBinopFlooredConstDivisor` is that realization.
    /// What it costs is `smulh` plus five to eight ALU instructions; what it
    /// replaces is `sdiv`, which no amount of instruction count makes up for.
    ///
    /// `magicFlooredDivisor` is the admission, and it REFUSES rather than
    /// guesses: it re-derives the multiplier's soundness over the whole i64
    /// dividend range and returns null if the proof does not close, so a
    /// divisor it cannot prove keeps the unchanged `sdiv` path. That is why
    /// calling it here and again in the emitter cannot make the two disagree.
    ///
    /// A NEGATIVE CONSTANT DIVISOR IS STILL NOT HERE. The relation the
    /// sequence rests on — `shifted product = floor(n/k) - [n<0 AND k|n]` — is
    /// derived for `k > 0`; the mirrored statement for `k < 0` is a different
    /// proof, and an unproved sequence is worth less than the divide it saves.
    /// Z3-verified shift-add multiply constants. Returns the lsl shift for
    /// `add d, x, x, lsl #sh` (k = 2^sh + 1), or the negated shift for
    /// `sub d, x, x, lsl #sh` (k = -(2^sh - 1)). Proofs in
    /// research/wsuperopt/proofs/mul_const_*. Each beats mov+mul by 1 insn.
    /// `k = 2^sh - 1` (7, 15, 31, 63): `lsl tmp, x, #sh` then
    /// `sub tmp, tmp, x` computes `x*k` exactly mod 2^64 by ring arithmetic.
    /// Used for the madd strength reduction where the 3-cycle latency still
    /// beats madd's 4 on loop-carried recurrences.
    fn sevenLikeShift(k: i64) ?u6 {
        return switch (k) {
            7 => 3,
            15 => 4,
            31 => 5,
            63 => 6,
            else => null,
        };
    }

    fn mulShiftAddShift(k: i64) ?struct { sh: u6, neg: bool } {
        return switch (k) {
            3 => .{ .sh = 1, .neg = false },
            5 => .{ .sh = 2, .neg = false },
            9 => .{ .sh = 3, .neg = false },
            17 => .{ .sh = 4, .neg = false },
            33 => .{ .sh = 5, .neg = false },
            65 => .{ .sh = 6, .neg = false },
            -7 => .{ .sh = 3, .neg = true },
            else => null,
        };
    }

    /// Fold a binary operation on two integer literals to its compile-time
    /// answer, so `1000000 / 7` never emits an `sdiv`. Division by zero and
    /// `minInt / -1` are NOT folded -- null falls through to the hardware path,
    /// preserving the trap the program would have executed. div, idiv,
    /// and mod are ALL floored (P0-1: int slash settled to floor so it
    /// coheres with floored percent), matching the emitted code.


    fn foldConstBinop(op: dnir.BinOpTag, l: i64, r: i64) ?i64 {
        return switch (op) {
            .add => l +% r,
            .sub => l -% r,
            .mul => l *% r,
            .div => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
                null
            else
                @divFloor(l, r),
            .idiv => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
                null
            else
                @divFloor(l, r),
            .mod => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
                null
            else
                @mod(l, r),
            .band => l & r,
            .bor => l | r,
            .bxor => l ^ r,
            else => null,
        };
    }

    fn constBinopRealization(ins: dnir.Instr) ?i64 {
        if (comparisonCondition(ins.binop) != null) return null;
        const k: i64 = switch (ins.rhs) {
            .i64 => |v| v,
            else => return null,
        };
        return switch (ins.binop) {
            .add, .sub => if (k == 0 or (k > 0 and k <= 4095) or (k < 0 and k >= -4095)) k else null,
            .mul => if (k == 0 or k == 1 or powerOfTwoShift(k) != null or mulShiftAddShift(k) != null) k else null,
            // P0-1: div and idiv share the floored law, so they share admission.
            .div, .idiv => if (k == 1 or powerOfTwoShift(k) != null or magicFlooredDivisor(k) != null) k else null,
            .mod => if (k == 1 or k == -1 or powerOfTwoShift(k) != null or magicFlooredDivisor(k) != null) k else null,
            .band => if (k == 0 or k == -1 or lowMaskWidth(k) != null) k else null,
            .bor => if (k == 0 or lowMaskWidth(k) != null) k else null,
            .bxor => if (k == 0 or k == -1 or lowMaskWidth(k) != null) k else null,
            .shl, .shr => if (k >= 0 and k < 64) k else null,
            .eq, .neq, .lt, .gt, .leq, .geq => null,
        };
    }

    /// `lsl xd, xn, #sh` and `lsr xd, xn, #sh` are UBFM aliases.
    fn emitLslImm(self: *Arm64Compiler, dst: u5, lhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        const immr: u32 = (64 - @as(u32, sh)) % 64;
        const imms: u32 = 63 - @as(u32, sh);
        try self.emitFmt(
            0xd3400000 | (immr << 16) | (imms << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "lsl x{d}, x{d}, #{d}",
            .{ dst, lhs, sh },
        );
    }

    /// `lsl wd, wn, #sh` — the 32-bit UBFM alias, `sh < 32`.
    ///
    /// NOT the 64-bit word with `sf` cleared: UBFM carries its own `N` bit and
    /// its immediates are element-size relative, so the 32-bit form is
    /// `N = 0, immr = (32-sh) mod 32, imms = 31-sh`. Emitted only where the
    /// declared width already discards everything above bit 31, which is why
    /// dropping the high `sh` bits here is the ANSWER rather than a loss.
    fn emitLslImmW32(self: *Arm64Compiler, dst: u5, lhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        const immr: u32 = (32 - @as(u32, sh)) % 32;
        const imms: u32 = 31 - @as(u32, sh);
        try self.emitFmt(
            0x53000000 | (immr << 16) | (imms << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "lsl w{d}, w{d}, #{d}",
            .{ dst, lhs, sh },
        );
    }

    fn emitLsrImm(self: *Arm64Compiler, dst: u5, lhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        try self.emitFmt(
            0xd3400000 | (@as(u32, sh) << 16) | (63 << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "lsr x{d}, x{d}, #{d}",
            .{ dst, lhs, sh },
        );
    }

    /// `asr xd, xn, #sh` — SBFM with immr=sh, imms=63, the signed twin of the
    /// UBFM above. The only difference in the encoding is bit 30 (`0x93` vs
    /// `0xd3`), and the only difference in the ANSWER is what fills the top
    /// bits — which is the whole of floor division for a power-of-two divisor.
    fn emitAsrImm(self: *Arm64Compiler, dst: u5, lhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        try self.emitFmt(
            0x9340fc00 | (@as(u32, sh) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "asr x{d}, x{d}, #{d}",
            .{ dst, lhs, sh },
        );
    }

    /// `mvn xd, xn` — the assembler's alias for `orn xd, xzr, xn`, base word
    /// 0xAA200000 with Rn = 31 (xzr). This is the whole realization of prefix
    /// `~`: `dnir_lower` lowers it to `bxor` against -1 and the constant path
    /// above selects this instruction for that operand.
    fn emitMvn(self: *Arm64Compiler, dst: u5, src: u5, w32: bool) Error!void {
        try self.ensureRegLive(src);
        const base: u32 = if (w32) 0x2a2003e0 else 0xaa2003e0;
        const r: u8 = if (w32) 'w' else 'x';
        try self.emitFmt(
            base | (@as(u32, src) << 16) | @as(u32, dst),
            "mvn {c}{d}, {c}{d}",
            .{ r, dst, r, src },
        );
    }

    fn emitAddImm(self: *Arm64Compiler, dst: u5, lhs: u5, imm: u12) Error!void {
        try self.emitAddImmSized(dst, lhs, imm, false);
    }

    /// `add xd, xn, #imm12`, and its 32-bit twin. `w32` clears bit 31 and the
    /// destination zero-extends — see `wForm32` for why that IS the refit.
    fn emitAddImmSized(self: *Arm64Compiler, dst: u5, lhs: u5, imm: u12, w32: bool) Error!void {
        try self.ensureRegLive(lhs);
        const base: u32 = if (w32) 0x11000000 else 0x91000000;
        const r: u8 = if (w32) 'w' else 'x';
        try self.emitFmt(
            base | (@as(u32, imm) << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "add {c}{d}, {c}{d}, #{d}",
            .{ r, dst, r, lhs, imm },
        );
    }

    /// `and`/`orr`/`eor` with a low-run bitmask immediate, `N=1, immr=0`.
    fn emitLogicalLowMask(
        self: *Arm64Compiler,
        base: u32,
        mnemonic: []const u8,
        dst: u5,
        lhs: u5,
        width: u6,
    ) Error!void {
        try self.ensureRegLive(lhs);
        const imms: u32 = @as(u32, width) - 1;
        try self.emitFmt(
            base | (imms << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "{s} x{d}, x{d}, #{d}",
            .{ mnemonic, dst, lhs, (@as(u64, 1) << width) - 1 },
        );
    }

    /// FLOOR DIVISION AND FLOORED REMAINDER over a POSITIVE CONSTANT divisor
    /// that is not a power of two — the multiply-high realization whose
    /// derivation lives on `magicFlooredDivisor`.
    ///
    ///     mov   m, #M                 ; 1-4, and off the dependency chain
    ///     smulh t, m, x
    ///     add   t, t, x               ; only when M's top bit is set
    ///     asr   t, t, #s              ; only when s > 0
    ///     mov   d, #k                 ; the divisor `msub` and `cmp` both read
    ///     msub  v, t, d, x            ; v = x - k*S(x), in [0, k]
    ///     cmp   v, d
    ///     idiv: csinc dst, t, t, ne   ; S + (v == k)
    ///     mod:  csel  dst, xzr, v, eq ; (v == k) ? 0 : v
    ///
    /// NO `sdiv`. Against the `sdiv`+`msub`+five-instruction floor fixup this
    /// replaces, the instruction COUNT is roughly a wash and the dependency
    /// chain is not: every instruction here is a 1-to-4 cycle ALU or multiply
    /// op, and the `mov` chain that materializes `M` depends on nothing, so it
    /// issues in parallel with whatever produced the dividend.
    ///
    /// `dst` IS WRITTEN LAST AND ONLY ONCE, which is what makes `dst == lhs`
    /// safe: the dividend's final read is the `msub`, two instructions earlier.
    ///
    /// `msub`'s product wraps and that is not a defect. `S*k` may exceed i64,
    /// but `x - S*k` is exact modulo 2^64 and its TRUE value is in `[0, k]`, so
    /// the low 64 bits are the answer.
    /// Acquire a register holding an integer constant for the floored-magic
    /// division sequence: reuse the reserved preheader register when
    /// `planImmHoist` hoisted the value, otherwise materialize it inline.
    /// `exclude` is the claimed destination the sequence must not spill,
    /// for the reason `emitBinopFlooredConstDivisor` states. A hoisted
    /// register is a home, so the caller's `releaseReg` is a no-op on it.
    fn acquireMagicConstReg(self: *Arm64Compiler, exclude: u5, value: i64) Error!u5 {
        if (self.hoist_depth > 0) {
            if (self.imm_hoist.get(value)) |hr| {
                try self.ensureRegLive(hr);
                return hr;
            }
        }
        const r = try self.allocRegExcluding(exclude);
        try self.emitMovImm(r, value);
        return r;
    }

    fn emitBinopFlooredConstDivisor(
        self: *Arm64Compiler,
        dst: u5,
        lhs: u5,
        k: i64,
        mg: FlooredMagic,
        op: dnir.BinOpTag,
    ) Error!void {
        // `allocRegExcluding(dst)` AND NOT `allocReg`. Allocation may SPILL a
        // claimed register to make room, and `dst` is claimed by the caller —
        // so plain `allocReg` can choose it as the victim. The spill would
        // leave `dst` mapped to a stack slot holding the value it had BEFORE
        // this sequence, and the next `ensureRegLive(dst)` would reload that
        // over the quotient written below. Excluding it is free; it is the
        // last write of the sequence and never a source.
        // A loop-invariant magic multiplier already sits in a reserved
        // preheader register (planImmHoist plans it); reuse it instead of
        // re-materializing the mov/movk chain every iteration. The divisor k
        // is planned as an ordinary .i64 operand. A missed plan falls back
        // to the inline mov. Hoisted registers are marked homes, so the
        // releaseReg calls below are no-ops on them, and dst can never name
        // one (local homes predate the preheader allocation; later
        // allocations skip homes).
        const rm = try self.acquireMagicConstReg(dst, mg.m);
        const rt = try self.allocRegExcluding(dst);
        try self.emitSmulhReg(rt, rm, lhs);
        self.releaseReg(rm);
        if (mg.add_dividend) try self.emitAddReg(rt, rt, lhs);
        if (mg.shift > 0) try self.emitAsrImm(rt, rt, mg.shift);
        const rd = try self.acquireMagicConstReg(dst, k);
        const rv = try self.allocRegExcluding(dst);
        try self.emitMsubReg(rv, rt, rd, lhs);
        try self.emitCmpReg(rv, rd);
        if (op == .idiv) {
            try self.emitCincEqReg(dst, rt);
        } else {
            try self.emitCselZeroEqReg(dst, rv);
        }
        self.releaseReg(rv);
        self.releaseReg(rd);
        self.releaseReg(rt);
    }

    /// Realize `dst = lhs op k`. Only reached for pairs `constBinopRealization`
    /// admitted, so the final `unreachable` is a contract between the two, not
    /// a guess about the operand.
    ///
    /// `fitted` IS THE WHOLE WIDTH ACCOUNTING, and it is set by the branch that
    /// knows. A realization is "fitted" when `dst` already holds exactly what
    /// the declared width demands — either because the branch chose a 32-bit
    /// destination form (`wForm32`), or because the value it wrote is canonical
    /// on its own (a zero, a low-run mask). Every other branch falls through to
    /// the refit, unchanged. A branch that forgets to set it emits a redundant
    /// but CORRECT instruction; a branch that sets it wrongly is a silent wrong
    /// answer, which is why the two are not merged into one predicate computed
    /// away from the realization it describes.
    fn emitBinopConst(
        self: *Arm64Compiler,
        dst: u5,
        lhs: u5,
        k: i64,
        op: dnir.BinOpTag,
        ty: native_types.ResolvedType,
    ) Error!void {
        const w32 = wForm32(ty, op);
        var fitted = false;
        switch (op) {
            .add => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else if (k > 0) {
                    try self.emitAddImmSized(dst, lhs, @intCast(k), w32);
                    fitted = w32;
                } else {
                    try self.emitSubImmSized(dst, lhs, @intCast(-k), w32);
                    fitted = w32;
                }
            },
            .sub => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else if (k > 0) {
                    try self.emitSubImmSized(dst, lhs, @intCast(k), w32);
                    fitted = w32;
                } else {
                    try self.emitAddImmSized(dst, lhs, @intCast(-k), w32);
                    fitted = w32;
                }
            },
            .mul => {
                if (k == 0) {
                    try self.emitMovImm(dst, 0);
                    // Zero is canonical at every width; the refit would be a
                    // second instruction writing the same bits.
                    fitted = w32;
                } else if (k == 1) {
                    if (dst != lhs) try self.emitMovReg(dst, lhs);
                } else if (powerOfTwoShift(k)) |sh| {
                    if (w32 and sh < 32) {
                        try self.emitLslImmW32(dst, lhs, sh);
                        fitted = true;
                    } else try self.emitLslImm(dst, lhs, sh);
                } else if (mulShiftAddShift(k)) |spec| {
                    // Z3-verified: 1 insn vs mov+mul (2+). Proofs in
                    // research/wsuperopt/proofs/mul_const_*.
                    if (spec.neg) {
                        try self.emitSubLslReg(dst, lhs, lhs, spec.sh);
                    } else {
                        try self.emitAddLslReg(dst, lhs, lhs, spec.sh);
                    }
                } else unreachable; // constBinopRealization gates
            },
            // P0-1: int slash is floored, so x / 2n = x asr n for every x,
            // with no range fact. Merged with idiv: one law, one realization.
            .div, .idiv => {

                if (k == 1) {
                    if (dst != lhs) try self.emitMovReg(dst, lhs);
                } else if (powerOfTwoShift(k)) |sh| {
                    try self.emitAsrImm(dst, lhs, sh);
                } else {
                    try self.emitBinopFlooredConstDivisor(dst, lhs, k, magicFlooredDivisor(k).?, .idiv);
                }
            },
            // `x % ±1 = 0`; `x % 2^n = x & (2^n - 1)` under FLOORED law, for
            // every x, with no range fact. Under the truncating law this file
            // used to implement, the same mask needed a proof that `x >= 0`
            // that nothing in this compiler can supply — so the truer law is
            // the one that costs 1 instruction where the accident cost 2 plus a
            // 20-cycle divide.
            .mod => {
                if (k == 1 or k == -1)
                    try self.emitMovImm(dst, 0)
                else if (powerOfTwoShift(k)) |sh|
                    try self.emitLogicalLowMask(0x92400000, "and", dst, lhs, sh)
                else
                    try self.emitBinopFlooredConstDivisor(dst, lhs, k, magicFlooredDivisor(k).?, .mod);
            },
            .band => {
                if (k == 0) {
                    try self.emitMovImm(dst, 0);
                    fitted = w32;
                } else if (k == -1) {
                    if (dst != lhs) try self.emitMovReg(dst, lhs);
                } else {
                    const width = lowMaskWidth(k).?;
                    try self.emitLogicalLowMask(0x92400000, "and", dst, lhs, width);
                    // A low-run mask no wider than the declared width leaves
                    // every bit above it clear, so the 64-bit form is ALREADY
                    // the refitted value — no `w` form and no second
                    // instruction. `orr`/`eor` get no such argument: they can
                    // only set bits, so a non-canonical operand leaks through.
                    fitted = w32 and width <= 32;
                }
            },
            .bor => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else try self.emitLogicalLowMask(0xb2400000, "orr", dst, lhs, lowMaskWidth(k).?);
            },
            .bxor => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else if (k == -1) {
                    try self.emitMvn(dst, lhs, w32);
                    fitted = w32;
                } else try self.emitLogicalLowMask(0xd2400000, "eor", dst, lhs, lowMaskWidth(k).?);
            },
            .shl => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else try self.emitLslImm(dst, lhs, @intCast(k));
            },
            .shr => {
                if (k == 0) { if (dst != lhs) try self.emitMovReg(dst, lhs); } else try self.emitLsrImm(dst, lhs, @intCast(k));
            },
            .eq, .neq, .lt, .gt, .leq, .geq => unreachable,
        }
        if (fitted) return;
        _ = try self.emitNarrowFit(dst, dst, ty);
    }

    /// FLOOR DIVISION AND FLOORED REMAINDER over a RUNTIME divisor
    /// `sdiv` truncates toward zero
    /// and `msub`'s remainder takes the sign of the DIVIDEND; the law rounds
    /// toward negative infinity and the remainder takes the sign of the
    /// DIVISOR. Those agree exactly when the operand signs agree, so the
    /// correction is: if the truncated remainder is non-zero AND the signs
    /// disagree, the quotient is one lower and the remainder is one divisor
    /// higher.
    ///
    ///     sdiv q, x, y          q = trunc(x/y)
    ///     msub r, q, y, x       r = x - q*y, sign of x
    ///     eor  s, r, y          s < 0  iff  sign(r) != sign(y)
    ///     asr  s, s, #63        s = -1 if signs disagree, else 0
    ///     mod:  and s, y, s ; add q, r, s ; cmp r, #0 ; csel dst, r, q, eq
    ///     idiv:              add s, q, s ; cmp r, #0 ; csel dst, q, s, eq
    ///
    /// BRANCHLESS AND FLAG-CHEAP ON PURPOSE. `csel` on `eq` rather than a
    /// branch keeps this straight-line, so it composes with if-conversion and
    /// with the peephole that folds a compare into its consumer, and the
    /// `asr #63` sign-broadcast avoids needing an `mi` condition this backend's
    /// `Condition` set does not carry.
    ///
    /// THE `r == 0` SELECT IS LOAD-BEARING, not defensive. `x = 20, y = -10`
    /// gives `r = 0`, and `0 ^ y` is negative for every negative `y` — so the
    /// sign-broadcast says "disagree" and the naive form would answer `-10` for
    /// a remainder that is exactly zero. It was written without this select
    /// first and that is the case that caught it.
    ///
    /// COST. Eight instructions against the old two, for a runtime divisor. The
    /// trade is deliberate and it is measured in `docs/rulings.md`: a runtime
    /// divisor is already paying a ~20-cycle `sdiv`, while a CONSTANT
    /// power-of-two divisor — which is what the corpus actually contains —
    /// drops from `sdiv`+`msub` to a single `and` or `asr`, and that
    /// realization is only lawful BECAUSE the law is floored.
    /// `IDOL_UNSAFE_TRUNC_DIVREM=1` — A MEASUREMENT PROBE, NOT AN OPTIMIZATION,
    /// AND IT EMITS A WRONG ANSWER BY CONSTRUCTION.
    ///
    /// Set it and the six-instruction sign correction below is simply not
    /// emitted: `//` becomes bare `sdiv` and `%` becomes `sdiv`+`msub`, which
    /// is C's TRUNCATED division and not this language's FLOORED division. On
    /// operands whose signs agree the two agree, so a kernel that only ever
    /// divides non-negative values answers identically under both — and that is
    /// exactly the arm needed to price the fixup without first having to build
    /// the analysis that would legitimately remove it.
    ///
    /// It is deliberately spelled `UNSAFE` and deliberately has no source-level
    /// surface. Anything that reads this flag as a feature has read it wrong;
    /// the only claim it can support is "the fixup costs N", and the answer to
    /// a mixed-sign program under it is a defect this backend already had a
    /// gate against (`(0-7) // 10` answers 0 here and -1 in the law).
    fn truncDivRemProbe() bool {
        return std.c.getenv("IDOL_UNSAFE_TRUNC_DIVREM") != null;
    }

    /// `IDOL_PROBE_NONNEG_DIVISOR=1` — the CHEAP FIXUP, priced before the
    /// analysis that would make it lawful was written.
    ///
    /// When the DIVISOR is positive the correction stops needing a sign
    /// broadcast and stops needing the `r == 0` select. The floored remainder
    /// then takes the divisor's sign, which is positive, so:
    ///
    ///     sdiv q, x, y ; msub r, q, y, x ; add t, r, y ; cmp r, #0 ; csel d, t, r, lt
    ///
    /// and for `//` the same shape with `sub t, q, #1` and a select on `q`.
    /// Five instructions against eight, and — the part that matters on a serial
    /// chain — TWO dependent steps after `msub` instead of five.
    ///
    /// `r == 0` needs no special case here, which is the whole reason the
    /// divisor's sign is worth proving: the general form needs it because
    /// `0 ^ y` is negative for negative `y`, and a positive `y` cannot produce
    /// that. A NEGATIVE divisor under this flag answers wrong, which is why it
    /// is a probe and not a realization until a proof selects it.
    fn nonNegDivisorProbe() bool {
        return std.c.getenv("IDOL_PROBE_NONNEG_DIVISOR") != null;
    }

    fn emitFlooredDivRem(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, op: dnir.BinOpTag, divisor: dnir.DivisorSign, dividend: dnir.DivisorSign) Error!void {
        // BARE SDIV: the dividend is proved non-negative and the divisor is
        // proved non-negative (the zero trap fires separately, so on the
        // fall-through path the divisor is positive). For non-negative
        // dividend and positive divisor, truncation equals floor -- the
        // correction cannot fire, so no msub/sub/cmp/csel is emitted.
        if (op == .div and dividend.proved() and divisor.proved()) {
            try self.emitSdivReg(dst, lhs, rhs);
            return;
        }
        // EVERY TEMPORARY HERE EXCLUDES `dst`, and the exclusion is load-bearing
        // rather than tidy. `dst` is already claimed on entry, so plain
        // `allocReg` reaches the spill ladder in `allocRegExcluding` with `dst`
        // a legal victim; `spillReg` then stores it and leaves the owning slot
        // still mapped to that register, and the next `ensureRegLive(dst)`
        // reloads the PRE-DIVISION value straight over the quotient this
        // function just computed. Nothing in the sequence below reloads `dst`,
        // which is why the hazard was latent and not observed — a later
        // instruction in the same function is what collects it. The
        // constant-divisor path already allocates this way for the same reason.
        const q = try self.allocRegExcluding(dst);
        try self.emitSdivReg(q, lhs, rhs);
        // THE UNSOUND CEILING PROBE IS TESTED FIRST, so that it stays a
        // CEILING. Ordered the other way, a divisor the pass has proved takes
        // the cheap form and the probe never runs — which silently turns the
        // headroom arm into the shipped arm and makes the two agree.
        if (truncDivRemProbe()) {
            if (op == .mod) {
                try self.emitMsubReg(dst, q, rhs, lhs);
            } else {
                try self.emitMovReg(dst, q);
            }
            self.releaseReg(q);
            return;
        }
        if (divisor.proved() or nonNegDivisorProbe()) {
            const r2 = try self.allocRegExcluding(dst);
            try self.emitMsubReg(r2, q, rhs, lhs);
            const t2 = try self.allocRegExcluding(dst);
            if (op == .mod) try self.emitAddReg(t2, r2, rhs) else try self.emitSubImm(t2, q, 1);
            try self.emitCmpZero(r2);
            try self.emitCselReg(dst, t2, if (op == .mod) r2 else q, .lt);
            self.releaseReg(t2);
            self.releaseReg(r2);
            self.releaseReg(q);
            return;
        }
        const r = try self.allocRegExcluding(dst);
        try self.emitMsubReg(r, q, rhs, lhs);
        const s = try self.allocRegExcluding(dst);
        try self.emitEorReg(s, r, rhs);
        try self.emitAsrImm(s, s, 63);
        if (op == .mod) {
            try self.emitAndReg(s, rhs, s);
            try self.emitAddReg(q, r, s);
            try self.emitCmpZero(r);
            try self.emitCselReg(dst, r, q, .eq);
        } else {
            try self.emitAddReg(s, q, s);
            try self.emitCmpZero(r);
            try self.emitCselReg(dst, q, s, .eq);
        }
        self.releaseReg(s);
        self.releaseReg(r);
        self.releaseReg(q);
    }

    fn emitCompareOrBinopWide(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, op: dnir.BinOpTag, divisor: dnir.DivisorSign, dividend: dnir.DivisorSign) Error!void {
        switch (op) {
            .add => try self.emitAddReg(dst, lhs, rhs),
            .sub => try self.emitSubReg(dst, lhs, rhs),
            .mul => try self.emitMulReg(dst, lhs, rhs),
            // P0-1: int slash is floored, so it shares the floored divrem
            // step inside the floored sequence.
            .div, .idiv, .mod => try self.emitFlooredDivRem(dst, lhs, rhs, op, divisor, dividend),

            // Bitwise and shift, register forms. AArch64 encodes all five with
            // the same field layout as add/sub, so they share one emitter.
            .band => try self.emitBitReg(0x8a000000, "and", dst, lhs, rhs),
            .bor => try self.emitBitReg(0xaa000000, "orr", dst, lhs, rhs),
            .bxor => try self.emitBitReg(0xca000000, "eor", dst, lhs, rhs),
            .shl => try self.emitBitReg(0x9ac02000, "lsl", dst, lhs, rhs),
            .shr => try self.emitBitReg(0x9ac02400, "lsr", dst, lhs, rhs),
            .eq, .neq, .lt, .gt, .leq, .geq => unreachable,
        }
    }

    /// The 32-BIT DESTINATION forms of the six operations `wForm32` admits.
    ///
    /// The encoding is the 64-bit word with bit 31 — `sf`, the size field —
    /// cleared, and nothing else changes: same Rm/Rn/Rd placement, same
    /// operation. This is the whole realization the width fact was missing, and
    /// it REPLACES an instruction rather than adding one.
    ///
    /// Only reachable through `wForm32`, so the `unreachable` is a contract
    /// between the two and not a guess about the operand.
    fn emitBinopW32(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, op: dnir.BinOpTag) Error!void {
        const word: u32 = switch (op) {
            .add => 0x0b000000,
            .sub => 0x4b000000,
            .mul => 0x1b007c00,
            .band => 0x0a000000,
            .bor => 0x2a000000,
            .bxor => 0x4a000000,
            else => unreachable,
        };
        const mnemonic: []const u8 = switch (op) {
            .add => "add",
            .sub => "sub",
            .mul => "mul",
            .band => "and",
            .bor => "orr",
            .bxor => "eor",
            else => unreachable,
        };
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(
            word | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "{s} w{d}, w{d}, w{d}",
            .{ mnemonic, dst, lhs, rhs },
        );
    }

    fn emit(self: *Arm64Compiler, word: u32, asm_line: []const u8) Error!void {
        try appendU32(&self.code, self.alloc, word);
        try self.asm_text.appendSlice(self.alloc, "\t");
        try self.asm_text.appendSlice(self.alloc, asm_line);
        try self.asm_text.appendSlice(self.alloc, "\n");
    }

    fn emitFmt(self: *Arm64Compiler, word: u32, comptime fmt: []const u8, args: anytype) Error!void {
        const line = try std.fmt.allocPrint(self.alloc, fmt, args);
        defer self.alloc.free(line);
        try self.emit(word, line);
    }

    fn gpSlotUsesStack(self: *const Arm64Compiler, slot: u32) bool {
        return self.gp_stack_locals.contains(slot);
    }

    /// After gatecap/sh calls, `temps` may still name caller-saved registers the
    /// call clobbered. Stack locals must reload from the frame; register homes in
    /// `pinned` survived `emitSaveCallerRegs` and must be republished to `temps`.
    fn syncGateLocalTempsAfterCall(
        self: *const Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
    ) Error!void {
        if (self.gp_stack_locals.count() == 0 or !self.cur_func_has_call) return;
        var sit = self.gp_stack_locals.keyIterator();
        while (sit.next()) |slot| {
            _ = temps.remove(slot.*);
            _ = pinned.remove(slot.*);
        }
        var pit = pinned.keyIterator();
        while (pit.next()) |slot| {
            if (pinned.get(slot.*)) |reg| {
                try temps.put(self.alloc, slot.*, reg);
            }
        }
    }

    /// ARM64 `str xN, [sp, #imm]` scaled offset is limited (~32 KiB frame).
    ///
    /// THE RELOAD RESTORES THE CLAIM IT IS UNDOING, NOT ONLY THE VALUE.
    ///
    /// `spillReg` performs two halves of one act: it moves the value out of the
    /// register (`str`, `spilled_regs.put`) and it stops the register standing
    /// for that value (`used_regs[victim] = false`). This function is the exact
    /// inverse and used to undo only the first half. The value came back into
    /// THAT SAME register while the register stayed unclaimed — and the entry
    /// that had been substituting for the claim went away in the same breath,
    /// because both free scans in `allocRegExcluding` skip a register
    /// `spilled_regs` contains and neither skips this one now. So the next
    /// allocation of any kind returns a register holding a live value whose
    /// owner still names it, and the second owner's first write is a silent
    /// wrong answer for the first.
    ///
    /// Restoring the claim returns the register to the state it held before the
    /// spill, which is also why it cannot leak: `spillReg` never cleared
    /// `gp_reg_owner[victim]`, so `sweepGpLive` releases this claim on the same
    /// owner record, at the same index, as it would have had the register never
    /// spilled at all.
    ///
    /// Bounded to gate transport with the rest of GAP-148: `spillReg` is reached
    /// only from `allocRegExcluding`, which refuses above its spill loops unless
    /// `gate_transport`, so `spilled_regs` is empty elsewhere and this whole body
    /// is skipped. Not the closure — closure is authoritative `register`/`frame`
    /// assignment before emission, per that gap's record.
    fn ensureRegLive(self: *Arm64Compiler, reg: u5) Error!void {
        if (self.spilled_regs.get(reg)) |off| {
            try self.emitLdrFrame(reg, try self.frameSlotOff(off));
            _ = self.spilled_regs.remove(reg);
            try self.free_spill_slots.append(self.alloc, off);
            self.claimReg(reg);
        }
    }

    /// Reload a spilled register into a fresh register and remap every temp
    /// that still names the old one. Without this, a spilled register stays
    /// reserved in `spilled_regs` until its owner is read again into the same
    /// physical register, which caps live values at the allocatable pool size.
    fn ensureRegLiveRemap(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        reg: u5,
    ) Error!u5 {
        const off = self.spilled_regs.get(reg) orelse return reg;
        // A HOME IS NAMED BY A MAP THIS FUNCTION CANNOT REWRITE, SO IT RELOADS
        // INTO ITSELF.
        //
        // The remap below rewrites `temps`, and `temps` is the SECOND map
        // `evalDnirValue` consults for a local. The first is `pinned`, which
        // this function does not receive and cannot rewrite, and `imm_hoist` is
        // a third with the same problem for a hoisted immediate. Move a value
        // out of `reg` and leave those naming it, and the next read of that
        // local answers `reg` — a register the move left free, so the pool hands
        // it to the next allocation and the read returns that instead. Wrong
        // answer, no diagnostic. `gp_call_home_regs` states this failure and its
        // measurement (`sha.id` answered 0 instead of 16, `native.id` fell from
        // 210 agreements to 128) and buys the calling function out of it by
        // making the callee-bank homes unspillable. It says in the same breath
        // that a LEAF's home is still a spill victim and carries the hazard
        // unrepaired, because a leaf has no `probeFunctionPlan` ladder to step
        // down and taking its victims away would refuse programs that compile
        // today. This is that repair, and it takes no victim away: the home
        // still spills, it just comes back to the register every map already
        // names.
        //
        // Reloading into `reg` is available here for the reason the exhaustion
        // arm below states at length — a register in `spilled_regs` holds
        // nothing, because both free scans in `allocRegExcluding` skip that map
        // and all three of its spill passes require `used_regs`, which
        // `spillReg` cleared. So the destination is free, no owner is abandoned,
        // and `ensureRegLive` is already exactly this reload: the `ldr` into
        // `reg`, the entry removed, the slot released once on that removal, and
        // the `claimReg` the loaded value is owed. Nothing else in the function
        // below applies to a home — `temps` names `reg` and still should,
        // `gp_reg_owner[reg]` is null because `markGpHome` nulls it, and
        // `sweepGpLive` and `releaseReg` both return above a home rather than
        // freeing one.
        //
        // Not the closure: closure is authoritative `register`/`frame`
        // assignment before emission, per this gap's record — under which a
        // home's location is a fact the assignment carries, not one four maps
        // restate.
        //
        // A PIN IS THAT MAP, AND `gp_home_regs` IS NOT THE WHOLE OF IT
        // (GAP-148).
        //
        // The branch below read the home flag as if it were the question, and
        // the question is whether `pinned` names `reg`. Those are the same set
        // at five of the six `pinned.put` sites, each of which calls
        // `markGpHome` first. The sixth is the one a LEAF's parameter takes:
        // `compileDnirFunction` keeps an incoming argument in its own x0..x7
        // register, claims it, and writes BOTH maps — and marks no home,
        // because there is no home to mark. Its `gp_home_regs` bit is clear
        // until a store to that slot sets it, so a parameter that is only ever
        // READ, which is every leaf parameter this backend compiles today,
        // is pinned and is not a home for its whole life.
        //
        // That register is a spill victim: the third pass in
        // `allocRegExcluding` walks x7..x0 and takes any `used_regs` register
        // that is neither `exclude` nor a staged argument, and a parameter at
        // rest is neither. After the spill the value is in the frame and the
        // remap below relocates it — rewriting `temps`, which names it, and
        // leaving `pinned`, which names it too and which `evalDnirValue`
        // consults FIRST. The next read of that parameter answers the vacated
        // register, and it is vacant: `spillReg` cleared `used_regs` and the
        // remap removed the `spilled_regs` entry, so both free scans hand it
        // out. Whatever the pool put there is what the parameter reads. A
        // wrong answer, no diagnostic — the same failure `gp_call_home_regs`
        // measured for a home (`sha.id` 0 instead of 16, `native.id` 210
        // agreements down to 128), reached through the one pinned register
        // that was never a home to begin with.
        //
        // Reloading into `reg` is available here for exactly the reasons the
        // home branch states, and none of them mention the home flag: a
        // register in `spilled_regs` holds nothing, because both free scans in
        // `allocRegExcluding` skip that map and all three of its spill passes
        // require `used_regs`, which `spillReg` cleared. So the destination is
        // free, no owner is abandoned, and `ensureRegLive` is that reload — the
        // `ldr` into `reg`, the entry removed, the slot released once on that
        // removal, and the `claimReg` the loaded value is owed. Nothing below
        // applies: `temps` names `reg` and still should, and `gp_reg_owner[reg]`
        // is whatever `spillReg` preserved across the store, at the index the
        // sweep would have released it at had the register never spilled.
        //
        // It takes no victim away — the parameter still spills, it just comes
        // back to the register both maps already name — and it costs the pool
        // the register the relocation would have freed, which is the trade the
        // home branch already makes. Bounded to gate transport with the rest of
        // this gap: `allocRegExcluding` refuses above its spill passes
        // otherwise, so `spilled_regs` is empty elsewhere and this function
        // returns above the branch. Not the closure — closure is authoritative
        // `register`/`frame` assignment before emission, per this gap's record,
        // under which a parameter's location is a fact the assignment carries
        // rather than one two maps restate and one of them cannot be reached.
        // A STAGED VARIADIC TAIL REGISTER IS NOT THE RELOCATION'S TO MOVE
        // (GAP-148).
        //
        // `pending_varargs[i].reg` is the FOURTH map that names a register, and
        // it names one for the same reason `pending_arg_regs` names x_k: the
        // register holds an argument for the `bl` being marshaled.
        // `reclaimSpilledReg` was taught that reservation in the section above;
        // this function is the other path that takes a register away from the
        // map naming it, and it had never been asked.
        //
        // The window is `materializePendingVarargs`'s own loop and nothing
        // else. Slot i is `staged` while slot j's operand is evaluated; that
        // evaluation allocates, the cascade spills slot i's register — the
        // spill passes read `used_regs`, which is all a staged tail register
        // has — and if slot j's operand is a value that LIVES in that register,
        // `evalDnirValue` arrives here for it. The relocation then rewrites
        // `temps`, which names it, and leaves `pending_varargs[i].reg`, which
        // names it too and which nothing below can reach. `emitPushVarargs`
        // reads that field and stores the vacated register into the callee's
        // memory-argument slot — and the register IS vacated, because
        // `spillReg` cleared `used_regs` and the removal below drops the entry
        // both free scans were skipping, so the pool hands it out. A wrong
        // variadic argument with no diagnostic, which is where every
        // `printf`/`snprintf` in this compiler passes its tail.
        //
        // Reloading into `reg` is available here for exactly the reasons the
        // two branches above state, and this one adds nothing to them: a
        // register in `spilled_regs` holds nothing, because both free scans in
        // `allocRegExcluding` skip that map, all three of its spill passes
        // require `used_regs`, and the reclaim at its bottom now skips a staged
        // tail. So the destination is free, no owner is abandoned, and
        // `ensureRegLive` is that reload. Nothing below applies: `temps` names
        // `reg` and still should, `pending_varargs[i].reg` names it and still
        // should, and `gp_reg_owner[reg]` is what `spillReg` preserved across
        // the store.
        //
        // It costs the pool nothing at all, which is weaker than the trade the
        // two branches above make: a relocation is net zero in registers — it
        // frees `reg` and claims `fresh` — so reloading into `reg` gives up no
        // register the move would have produced. Rewriting the fourth map
        // instead would work and was not taken: it adds `pending_varargs` to
        // the set every mover must keep in step, for a move that buys nothing.
        // Bounded to gate transport with the rest of this gap. Not the closure
        // — closure is authoritative `register`/`frame` assignment before
        // emission, per this gap's record, under which a tail argument's
        // location is a fact the assignment carries rather than one a fourth
        // map restates and a mover has to remember.
        if (self.gp_home_regs[reg] or self.evalPinNames(reg) or self.stagedTailReg(reg)) {
            try self.ensureRegLive(reg);
            return reg;
        }
        const reload_off = try self.frameSlotOff(off);
        const fresh = self.allocRegExcluding(null) catch |e| blk: {
            if (e != error.RegisterExhausted or !self.gate_transport) return e;
            // THE VALUE'S OWN REGISTER IS THE DESTINATION THAT COSTS NOTHING.
            //
            // This arm needs a register to load `[sp, #reload_off]` into, and
            // it used to ask `reclaimSpilledReg` for one. A reclaim frees a
            // register by dropping the `spilled_regs` entry that would have
            // reloaded it, which abandons that register's value in the frame
            // with nothing left able to read it — the two-owner hazard this gap
            // is open on. But `reg` IS a spilled register, and it is the one
            // whose entry this function drops anyway a few lines down, because
            // its value is being loaded out of the frame. Reloading into `reg`
            // therefore frees exactly the one register the reclaim would have
            // freed and abandons nobody: the reclaim's arbitrary hash-order
            // choice was never anything but a strictly worse spelling of this
            // one, and when it happened to pick `reg` it was this one.
            //
            // Every fact the rest of the function needs already holds. `reg`'s
            // value is at `off`, and no OTHER value is in `reg`: `spillReg` put
            // it in `spilled_regs` and both free scans in `allocRegExcluding`
            // skip anything that map contains, so nothing has been handed `reg`
            // since. `used_regs[reg]` is false for the same reason, and
            // `claimReg` is the claim the loaded value is owed —
            // `ensureRegLive`, which is this same reload into this same
            // register, pays exactly it. `gp_reg_owner[reg]` is untouched,
            // which is what `spillReg` preserved it across the store FOR: the
            // sweep releases this claim on the same owner record, at the same
            // index, as it would have had the register never spilled. The
            // reclaim nulled that record on the register it returned, so
            // reaching `reg` through it stranded the reload's own destination
            // under a null owner — `sweepGpLive` skips an unowned register.
            //
            // `reclaimSpilledReg` keeps its remaining caller at the bottom of
            // `allocRegExcluding`, where there is genuinely no register to give.
            // The abandonment there is unchanged and still bounded to gate
            // transport. Not the closure: closure is authoritative
            // `register`/`frame` assignment before emission, per this gap's
            // record.
            self.claimReg(reg);
            break :blk reg;
        };
        try self.emitLdrFrame(fresh, reload_off);
        // THE SLOT IS RELEASED BY WHOEVER REMOVES THE ENTRY, AND ONLY THEN.
        //
        // The removal is idempotent; a release is not. An unconditional append
        // behind a removal that took nothing puts one frame slot in
        // `free_spill_slots` twice, and then two later spills store two live
        // values over each other at the same offset. That was reachable while
        // the exhaustion arm above went through `reclaimSpilledReg`, which
        // removes and releases the entry it takes; the arm takes nothing now,
        // so this removal is what empties the entry and this append is the one
        // release of the slot. The guard states the rule rather than the
        // reachability, because it is the rule that has to hold for the next
        // caller.
        if (self.spilled_regs.remove(reg)) {
            try self.free_spill_slots.append(self.alloc, off);
        }
        var it = temps.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.* == reg) entry.value_ptr.* = fresh;
        }
        // THE OWNER RECORD IS PART OF THE MOVE, NOT A SEPARATE BOOKKEEPING STEP.
        //
        // Everything above relocates this value from `reg` to `fresh` — the
        // `ldr`, the dropped `spilled_regs` entry, the released slot, and every
        // temp that named `reg`. `gp_reg_owner` is the fifth record naming the
        // same thing and was the only one left behind, which is the identical
        // relocation `preserveArgReg` performs and finishes by writing
        // `gp_reg_owner[fresh]`. Leaving both ends untouched is wrong in both
        // directions at once:
        //
        //   - `reg` keeps an owner it no longer holds. `spillReg` cleared
        //     `used_regs[reg]` and the removal above took it out of
        //     `spilled_regs`, so both free scans in `allocRegExcluding` hand it
        //     out — and then `sweepGpLive`, reading that stale owner against a
        //     `value_free_at` whose reads are behind emission, clears
        //     `used_regs[reg]` for the register a live value was just given, and
        //     the pool hands it out a second time. Two owners, one register, no
        //     diagnostic: this gap's shape, reached here rather than through
        //     `reclaimSpilledReg`.
        //   - `fresh` holds a live value under a null owner, and `sweepGpLive`
        //     skips an unowned register. Nothing reclaims it for the rest of the
        //     function, so the pool shrinks by one on the one path whose whole
        //     job is to relieve register pressure. `preserveArgReg` names this
        //     failure from the other side — owner null there ran `tree.id` out
        //     of registers.
        //
        // The owner that travels is the one `spillReg` deliberately preserved
        // across the store: it already IS the record the sweep would have
        // released had the register never spilled. When the `catch` above
        // reclaimed `reg` itself, `fresh == reg` and there is nothing to move.
        // A home register is excluded for the same reason `sweepGpLive` skips
        // it — a home is not the sweep's to release.
        if (fresh != reg) {
            if (self.gp_reg_owner[reg]) |owner| {
                self.gp_reg_owner[reg] = null;
                if (!self.gp_home_regs[fresh]) self.gp_reg_owner[fresh] = owner;
            }
        }
        return fresh;
    }

    /// WHICH `off` VALUES THE PRE-RESERVED SPILL AREA MAY HAND OUT — in the
    /// coordinate the store and the reload actually address a slot with.
    ///
    /// `spillReg` and `ensureRegLive` both reach a slot as
    /// `stack_frame_bytes - off - 8`, so `off` counts DOWN FROM THE TOP of the
    /// frame. That is what the last-resort branch below means when it takes
    /// `off = self.stack_frame_bytes` for the sixteen bytes it has just
    /// subtracted: at that instant `off` IS the distance from the top, and it
    /// stays correct as the frame grows underneath it.
    ///
    /// The prologue names its reservation at the OTHER END. It subtracts
    /// `gp_stack_bytes + spill_reserve` in one `sub sp` and puts the spill area
    /// at `[sp, gp_stack_bytes .. gp_stack_bytes + spill_reserve)`, directly
    /// above the GP stack locals at `[sp, 0 .. gp_stack_bytes)` — "locals sit at
    /// [sp,#0]…; spill temps sit above them". Handing the cursor's `off` values
    /// out of THAT range mixes the two coordinates, and the mixture is not a
    /// shifted area but an overlapping one: `off = gp_stack_bytes` addresses the
    /// TOP of the reservation and the cursor then walks DOWNWARD through the
    /// frame, out of the reserved area, across the GP stack locals, and into
    /// whatever the frame already held.
    ///
    /// Measured on the layout the prologue itself builds — ten locals
    /// (`gp_stack_bytes = 80`), `spill_reserve = 256`, nothing else in the frame
    /// so `stack_frame_bytes = 336`. The band `[80, 336)` steps sixteen at a
    /// time and its addresses `336 - off - 8` run 248, 232, … , 8. The first
    /// eleven land in the reservation; the twelfth is 72 and the last is 8, and
    /// those are the homes of locals 9 and 1. The store is a wrong answer for
    /// the local and the local's next store is a wrong answer for the spilled
    /// value, in both directions, with no diagnostic — the frame face of this
    /// gap's two-owner shape. With a table or record already in the frame the
    /// same walk runs the other way off the reservation and over the rebased
    /// region instead.
    ///
    /// The band is therefore measured from the top like the offsets that read
    /// it: it starts at whatever the frame held BEFORE this prologue's `sub` and
    /// runs for `spill_reserve` bytes, which maps exactly onto
    /// `[sp, gp_stack_bytes + 8 .. gp_stack_bytes + spill_reserve)` and touches
    /// nothing else. No slot is lost — the count is `spill_reserve / 16` either
    /// way — and `spillReg` still refuses with `RegisterExhausted` at the end of
    /// it, which is the refusal the reserve's own sizing comment relies on.
    ///
    /// Bounded to gate transport with the rest of GAP-148: `spillReg` is reached
    /// only from `allocRegExcluding`, which refuses above its spill passes
    /// otherwise. Not the closure — closure is authoritative `register`/`frame`
    /// assignment before emission, per that gap's record, under which a spilled
    /// value's frame location is carried by the assignment rather than by two
    /// coordinates that have to agree by hand.
    fn gateSpillBand(
        frame_bytes: u16,
        gp_stack_bytes: u16,
        spill_reserve: u16,
    ) struct { base: u16, end: u16 } {
        const base: u16 = frame_bytes - gp_stack_bytes - spill_reserve;
        return .{ .base = base, .end = base + spill_reserve };
    }

    /// Spill one temporary to the frame to make its register reusable,
    /// outside gate transport. `spillReg` stores a register into a frame slot
    /// but keys the record on the physical register, and `allocRegExcluding`
    /// skips every register `spilled_regs` names — so spilling never frees
    /// capacity. This pass keys the record on the TEMPORARY id instead
    /// (`temp_frame_slots`): the victim's value is stored into a frame slot,
    /// the temp's register name is removed, and the physical register is
    /// immediately re-let. A later read of the temp reloads from the slot into
    /// whichever register is then free (see the `.temp` arm of
    /// `evalDnirValue`) and re-names the temp, so the value survives the
    /// register being reused.
    ///
    /// Only an unpinned, unhomed, unstaged, non-FP temporary whose register
    /// names no other live value may be a victim. Pins name values the frame
    /// layout and the ABI depend on; `gp_home_regs`/`gp_call_home_regs` name
    /// locals whose homes other maps restate; `pending_arg_regs` names staged
    /// call arguments; `stagedTailReg` names the variadic tail the call
    /// marshaling is still writing; `imm_hoist` values are claimed by the hoist
    /// map, not by `temps`. Spilling any of those would move a value a reader
    /// still addresses by register. `spillReg` may still throw
    /// `RegisterExhausted` when no frame slot exists — the refusal then stands,
    /// exactly as before; this pass only converts pressure into frame slots
    /// where the frame has room for them.
    fn spillTempForCapacity(self: *Arm64Compiler, exclude: ?u5) Error!?u5 {
        const temps = self.eval_temps orelse return null;
        // Top-down like the existing spill passes: the callee-saved bank
        // first, then the ABI bank. `platform_reserved_reg` (x8) never carries
        // a `temps` value.
        var v: u5 = 28;
        while (true) {
            if (try self.spillTempVictim(temps, v, exclude)) |reg| return reg;
            if (v == 9) break;
            v -= 1;
        }
        v = 7;
        while (true) {
            if (try self.spillTempVictim(temps, v, exclude)) |reg| return reg;
            if (v == 0) break;
            v -= 1;
        }
        return null;
    }

    /// Spill the temporary in `reg` to the frame and hand `reg` back, or null
    /// when `reg` is not a spillable temporary. Every early return names a
    /// reader that still addresses the register's value by register: pinned
    /// ids, home regs, call-surviving homes, staged ABI arguments, the staged
    /// variadic tail, and hoisted immediates. The one `temps` entry naming the
    /// register must also agree with `gp_reg_owner` — a name that outlived its
    /// claim (GAP-148) is not a value and is left for the stale-name refusal.
    fn spillTempVictim(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        reg: u5,
        exclude: ?u5,
    ) Error!?u5 {
        if (exclude) |x| if (reg == x) return null;
        if ((self.held_regs >> reg) & 1 != 0) return null;
        if (!self.used_regs[reg]) return null;
        if (self.spilled_regs.contains(reg)) return null;
        if (self.gp_home_regs[reg]) return null;
        if ((self.gp_call_home_regs >> reg) & 1 != 0) return null;
        if (reg < 8 and ((self.pending_arg_regs >> @as(u3, @intCast(reg))) & 1) != 0) return null;
        if (self.stagedTailReg(reg)) return null;
        if (self.evalPinNames(reg)) return null;
        var hoist = self.imm_hoist.iterator();
        while (hoist.next()) |entry| if (entry.value_ptr.* == reg) return null;
        var found: ?u32 = null;
        var count: u8 = 0;
        var it = temps.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.* != reg) continue;
            count += 1;
            if (count > 1) return null;
            found = entry.key_ptr.*;
        }
        const id = found orelse return null;
        // An FP-marked id names a double register that shares this index; the
        // general register's bits are not its value.
        if (self.fp_temps.contains(id)) return null;
        // The owner record is authoritative for the x9..x28 bank: the emission
        // loop rebinds it after every value instruction. A register another id
        // owns is a stale name, not a value.
        const owner = self.gp_reg_owner[reg];
        if (owner != null and owner.? != id) return null;
        // Store the value, then move the slot record from the register key to
        // the temp id key before the register is re-let: from here on the
        // frame slot is the value's only address.
        try self.spillReg(reg);
        const slot = self.spilled_regs.fetchRemove(reg).?.value;
        try self.temp_frame_slots.put(self.alloc, id, slot);
        _ = temps.remove(id);
        self.gp_reg_owner[reg] = null;
        self.claimReg(reg);
        return reg;
    }

    fn spillReg(self: *Arm64Compiler, victim: u5) Error!void {
        try self.cost.record(
            self.alloc,
            .spill,
            "register pool exhausted; spilled live temp to stack frame",
        );
        const off: u16 = if (self.free_spill_slots.pop()) |slot|
            slot
        else if (self.gate_spill_end > self.gate_spill_base) blk: {
            if (self.gate_spill_cursor + 16 > self.gate_spill_end) return error.RegisterExhausted;
            const slot = self.gate_spill_cursor;
            self.gate_spill_cursor += 16;
            break :blk slot;
        } else blk: {
            // LAST RESORT, AND ONLY WHEN NOTHING ELSE LIVES IN THE FRAME.
            //
            // This moves `sp` in the MIDDLE of the body, and every offset the
            // prologue handed out is measured from the `sp` the prologue left
            // behind. Gate transport was already excluded for exactly this
            // reason (`digits(gatecap(...))` read `12` out of `181` after the
            // first loop iteration, from a local whose slot had shifted under
            // it), but the exclusion named one symptom instead of the rule.
            //
            // The rule: a frame with ANY other resident — GP stack locals, a
            // memory-backed table region, a record region — cannot have `sp`
            // moved under it. Refusing preserves correctness and remains visible
            // through auto; the explicit C99 source realizer is not a fallback.
            // The alternative is an artifact that computes the wrong answer and
            // reports success, which is the failure this area produced twice.
            //
            // Reachable much less often than it looks: spilling requires all
            // nineteen allocatable registers to be busy, which implies pressure
            // above the caller-save homes, which now reserves a spill area in
            // the prologue (see `wants_spill`) and takes the branch above.
            if (self.gate_transport) return error.RegisterExhausted;
            if (self.frameResidents() > 0) return error.RegisterExhausted;
            if (self.stack_frame_bytes + 16 > self.spill_frame_budget) return error.RegisterExhausted;
            const slot = self.stack_frame_bytes;
            try self.frameGrow(16);
            break :blk slot;
        };
        try self.ensureRegLive(victim);
        try self.emitStrFrame(victim, try self.frameSlotOff(off));
        try self.spilled_regs.put(self.alloc, victim, off);
        self.unprotectReg(victim);
        self.used_regs[victim] = false;
    }

    /// x18 is Apple's PLATFORM REGISTER. AAPCS64 leaves it to the platform and
    /// Apple's arm64 ABI reserves it outright — "don't use this register" —
    /// so it is not part of the allocatable pool even though it sits in the
    /// middle of x9..x28. The pool could always reach it under pressure; a
    /// record return staging eight fields at once reaches it reliably.
    const platform_reserved_reg: u5 = 18;

    /// TAKE A SPILLED REGISTER BACK, AND LEAVE NOTHING OF ITS OWNER BEHIND.
    ///
    /// Dropping the `spilled_regs` entry is what makes the register allocatable
    /// again, and it is also what abandons the owner: that entry was the only
    /// thing that would have reloaded the value, so after the drop the owner
    /// names a register holding someone else's value. That hazard is this gap's
    /// and is unchanged here — bounded to gate transport, and a wrong read is
    /// still a wrong read. What the drop did NOT do was clear the two other
    /// records the owner held, and each of those is a defect in the OTHER
    /// direction, against the value the reclaim just handed the register TO:
    ///
    ///   - `gp_reg_owner[reg]` still named the abandoned owner. That owner is
    ///     normally absent from `value_free_at` — its reads are behind emission
    ///     — which `sweepGpLive` reads as dead at every index, so the next sweep
    ///     cleared `used_regs[reg]` for a register a LIVE value had just been
    ///     given, and `allocRegExcluding` handed the same register out twice.
    ///   - the frame slot stayed reserved. `ensureRegLive` and
    ///     `ensureRegLiveRemap` are its only readers and both key on the entry
    ///     just removed, so nothing can ever read it again; holding it kept
    ///     `spillReg` stepping `gate_spill_cursor` toward `gate_spill_end` and
    ///     refusing spills the pre-reserved area still had room for.
    ///
    /// Releasing the slot is safe for the same reason it is dead: the abandoned
    /// owner cannot reach it either. `sweepGpLive` already returns a slot to
    /// `free_spill_slots` on exactly this removal; this makes the two paths
    /// agree. Not the closure — closure is authoritative `register`/`frame`
    /// assignment before emission, per this gap's record.
    ///
    /// `exclude` IS THE CALLER'S, AND HASH ORDER MUST NOT REACH IT. Every other
    /// path in `allocRegExcluding` keeps that promise — both free scans skip
    /// `exclude`, and so do all three spill passes, which is why this call can
    /// never be what put `exclude` into `spilled_regs`. Only a register spilled
    /// BEFORE the call can be here, and `emitIfConverted` and
    /// `emitIfConvertedTwoSided` both open that window: each holds a register
    /// across evaluation that allocates, and then excludes it. Handing it back
    /// is worse than the spill
    /// the exclusion exists to prevent — the drop above abandons the caller's
    /// own value in the frame, the caller writes its second value into the same
    /// register, and both reads are wrong with no diagnostic. Skipping the entry
    /// costs the reclaim one candidate out of a map the cascade filled with
    /// every allocatable register; when it is genuinely the last one, the
    /// refusal below is the same bail this function already answers with.
    ///
    /// A HOME IS NOT A REGISTER ANYONE CAN GIVE BACK, so it is not one this
    /// function may take. The abandonment above is symmetric for a temp — one
    /// owner loses its reload — but a home is abandoned in a second, independent
    /// direction at the same time, against the value the reclaim hands the
    /// register TO. `markGpHome` sets `gp_home_regs[reg]` and nothing clears it
    /// for the rest of the function: `sweepGpLive` skips a home, `releaseReg`
    /// returns above one, and only the hoist unwind or the per-function reset
    /// touches the array. So the returned register arrives still flagged as
    /// somebody's home, no release path can ever take it back, and the pool
    /// shrinks by one for the rest of the function — on the one path whose whole
    /// job is to relieve register pressure. `ensureRegLiveRemap` compounds it
    /// from the other side: it refuses to write `gp_reg_owner` for a home
    /// destination, so a value later relocated into this register lives under a
    /// null owner the sweep also skips.
    ///
    /// Only a LEAF's home can be here. The first spill pass in
    /// `allocRegExcluding` skips every home and the second skips
    /// `gp_call_home_regs`, which a calling function sets for its whole bank and
    /// a leaf never sets at all — the leaf victim `gp_call_home_regs` names and
    /// leaves unrepaired, reached through the reclaim rather than through the
    /// reload. The reload path answers it by returning a home to the register
    /// every map already names; this path has no such answer, because the value
    /// it is asked for is not the home's.
    ///
    /// The cost is the `exclude` skip's cost, one candidate, and the same
    /// argument covers it: when a home is genuinely the only entry, the refusal
    /// below is the bail this function already answers with, and a refusal is a
    /// bail while the alternative is a wrong answer. Not the closure — closure
    /// is authoritative `register`/`frame` assignment before emission, per this
    /// gap's record, under which a home's location is carried by the assignment
    /// and is not a register the reclaim can bid for.
    ///
    /// A STAGED ARGUMENT IS THE THIRD RESERVATION, AND IT IS THIS FUNCTION'S
    /// ALONE TO MISS (GAP-148).
    ///
    /// `pending_arg_regs` is the caller's statement that x_k already holds an
    /// argument for the `bl` being marshaled. `allocRegExcluding` honours it in
    /// its x0..x7 free scan and again in its x7..x0 spill pass — "a staged
    /// argument register is not a spill candidate: its live value belongs to
    /// the call being marshaled, not to a temp we can park" — and then reaches
    /// this reclaim at its bottom without asking the question a third time. The
    /// entry that made `slot` reachable here is exactly the fact the marshaling
    /// left stale: `mov_arg` writes the argument into `slot` with `emitMovImm`,
    /// `emitAdrpAdd` or `emitMovReg`, none of which touches `spilled_regs`, so
    /// an entry that predates the staging survives it and now describes a frame
    /// copy the register no longer holds.
    ///
    /// It survives because `preserveArgReg` had nothing to move. That function
    /// is what empties `slot` before the staging, and it reloads through
    /// `emitMovReg`'s `ensureRegLive` for every LIVE id that names it; when the
    /// only names are ids whose last read is already behind emission — the
    /// stale names it now passes over — it returns without a move and the
    /// entry stays. Then the reclaim finds `slot`, drops that entry, claims the
    /// register and hands it back as scratch, the caller's first write lands on
    /// top of the staged argument, and the `bl` passes it. A wrong argument, no
    /// diagnostic, on the one register the marshaling had already declared
    /// spoken for.
    ///
    /// The skip is the `exclude` skip's shape and carries its cost — one
    /// candidate out of a map the cascade filled with every allocatable
    /// register, and when a staged argument is genuinely the last entry the
    /// refusal below is the bail this function already answers with. Not the
    /// closure — closure is authoritative `register`/`frame` assignment before
    /// emission, per this gap's record, under which an argument's location is
    /// carried by the assignment and no scratch allocator bids against it.
    ///
    /// THE VARIADIC TAIL IS THE SAME RESERVATION, AND `pending_arg_regs` DOES
    /// NOT COVER IT (GAP-148).
    ///
    /// Apple's ARM64 ABI passes every argument past a variadic function's last
    /// named parameter in MEMORY, so `materializePendingVarargs` evaluates each
    /// one into an ordinary allocatable register and records it in
    /// `pending_varargs[i].reg`; `emitPushVarargs` stores those registers to
    /// [sp, #i*8] after `emitSaveCallerRegs`. Between the two the register holds
    /// an argument for the `bl` being built — the identical statement
    /// `markStagedArgReg` makes about x_k — and `pending_arg_regs` cannot carry
    /// it, because it is eight bits describing x0..x7 and a tail register is
    /// whatever the pool gave, normally x9..x28.
    ///
    /// The window is the materialization's own loop: slot 0's register is
    /// staged while slot 1's operand is evaluated, and that evaluation
    /// allocates. Both free scans in `allocRegExcluding` do pass over a staged
    /// tail register, but for the wrong reason — `used_regs` is set, and the
    /// cascade's spill passes take exactly the registers `used_regs` names.
    /// After `spillReg` the claim is gone, the value is in the frame and the
    /// entry is in this map, and this function took it: entry dropped,
    /// `gp_reg_owner` nulled, `claimReg`, and the staged tail argument handed
    /// back as scratch. The caller's first write lands on it, `emitPushVarargs`
    /// stores that write into the callee's memory-argument slot, and the
    /// variadic call is made with it. A wrong argument with no diagnostic —
    /// `printf`/`snprintf`'s tail is where every such call in this compiler
    /// goes.
    ///
    /// A spill alone does not clobber it: a register in this map is skipped by
    /// both free scans, so the bytes survive and `emitPushVarargs` happens to
    /// store the right ones. THIS is the arm that makes it wrong, and it is the
    /// arm no reservation was ever stated to.
    ///
    /// The skip is the `exclude` skip's shape and carries its cost — one
    /// candidate out of a map the cascade filled with every allocatable
    /// register, and when a staged tail register is genuinely the last entry the
    /// refusal below is the bail this function already answers with. Not the
    /// closure — closure is authoritative `register`/`frame` assignment before
    /// emission, per this gap's record, under which a tail argument's location
    /// is carried by the assignment rather than by a register the marshaling
    /// holds across an allocation that may bid for it.
    ///
    /// A PIN IS THE FIFTH RESERVATION, AND `gp_home_regs` IS NOT THE WHOLE OF
    /// IT (GAP-148).
    ///
    /// The home skip above reads the home flag as if it were the question, and
    /// the question is whether `pinned` names `reg`. `ensureRegLiveRemap` asks
    /// it that way; this function still asks the flag. The two sets agree at
    /// five of the six `pinned.put` sites, each of which calls `markGpHome`
    /// first. The sixth is a LEAF's parameter: `compileDnirFunction` keeps an
    /// incoming argument in its own x0..x7 register, claims it, writes BOTH
    /// maps, and marks no home because there is none to mark. That bit stays
    /// clear until a store to the slot sets it, so a parameter that is only
    /// ever READ — which is every leaf parameter this backend compiles today —
    /// is pinned and is not a home for its whole life.
    ///
    /// It is a spill victim: the third pass in `allocRegExcluding` walks x7..x0
    /// and takes any `used_regs` register that is neither `exclude` nor a staged
    /// argument, and a parameter at rest is neither. Once the entry is in the
    /// map this function takes it — entry dropped, `gp_reg_owner` nulled, slot
    /// released, `claimReg`, handed back as scratch — while `pinned` still names
    /// the register and `evalDnirValue` consults `pinned` FIRST for a local. The
    /// next read of that parameter therefore answers a register the caller was
    /// just given and is about to write, and the frame copy is unreachable in
    /// both directions at once: `ensureRegLive` and `ensureRegLiveRemap` are its
    /// only readers and both key on the entry just dropped, and its slot is back
    /// in `free_spill_slots` for the next spill to store a second value over. A
    /// wrong answer with no diagnostic — the failure `gp_call_home_regs`
    /// measured for a home (`sha.id` answered 0 instead of 16, `native.id` fell
    /// from 210 agreements to 128), reached through the one pinned register the
    /// home flag does not cover.
    ///
    /// The reload path already answers this and answers it the other way: it
    /// returns the parameter to the register both maps name. This path has no
    /// such answer, because the value it is asked for is not the parameter's —
    /// which is exactly the argument the home skip above makes, with the home
    /// flag replaced by the map that actually decides the read.
    ///
    /// The skip is the `exclude` skip's shape and carries its cost — one
    /// candidate out of a map the cascade filled with every allocatable
    /// register, and when a pinned register is genuinely the last entry the
    /// refusal below is the bail this function already answers with. False
    /// outside a function body, where `eval_pinned` is null and there is no pin
    /// to honour. Not the closure — closure is authoritative `register`/`frame`
    /// assignment before emission, per this gap's record, under which a
    /// parameter's location is carried by the assignment rather than by a map
    /// one path reads and another passes over.
    ///
    /// AN OWNED FRAME VALUE IS NOT RECLAIMABLE (GAP-148).
    ///
    /// `gp_reg_owner[reg]` names the DNIR value whose only current location is
    /// the frame slot in `spilled_regs`. Removing that entry does not relocate
    /// the value: it deletes its last readable location. The reclaim may still
    /// retire an ownerless stale entry left by register staging, but an owned
    /// entry remains a value location and pressure refuses when those are the
    /// only entries available.
    /// A NAMED TEMP IS THE SIXTH RESERVATION, AND `gp_reg_owner` NEVER CARRIES
    /// IT (GAP-148).
    ///
    /// Every write to `gp_reg_owner` skips `r < 9`, so a call or pack result the
    /// ABI left in x0..x7 is ownerless for its whole life while `temps` names
    /// its register -- and `temps` is what `evalDnirValue` reads for that value.
    /// Ownerless is what this function reads as dead storage, so it dropped the
    /// entry and released the slot while the only reader still pointed at the
    /// register it handed back as scratch.
    fn reclaimSpilledReg(self: *Arm64Compiler, exclude: ?u5) Error!u5 {
        var it = self.spilled_regs.iterator();
        while (it.next()) |entry| {
            const reg = entry.key_ptr.*;
            if (exclude != null and reg == exclude.?) continue;
            // An owner means this entry is the only remaining location of a
            // live DNIR value. Dropping it would make the value permanently
            // unreadable; only ownerless stale entries are reclaimable.
            if (self.gp_reg_owner[reg] != null) continue;
            if (self.gp_home_regs[reg]) continue;
            if (self.evalPinNames(reg)) continue;
            if (self.evalTempNames(reg)) continue;
            if (reg < 8 and
                self.pending_arg_regs & (@as(u8, 1) << @as(u3, @intCast(reg))) != 0) continue;
            if (self.stagedTailReg(reg)) continue;
            const off = entry.value_ptr.*;
            _ = self.spilled_regs.remove(reg);
            self.gp_reg_owner[reg] = null;
            try self.free_spill_slots.append(self.alloc, off);
            self.claimReg(reg);
            return reg;
        }
        return error.RegisterExhausted;
    }

    fn allocRegExcluding(self: *Arm64Compiler, exclude: ?u5) Error!u5 {
        const reg = try self.allocRegExcludingUnheld(exclude);
        self.protectReg(reg);
        return reg;
    }

    fn allocRegExcludingUnheld(self: *Arm64Compiler, exclude: ?u5) Error!u5 {
        var reg: u5 = 9;
        while (reg < 29) : (reg += 1) {
            if (reg == platform_reserved_reg) continue;
            if (exclude != null and reg == exclude.?) continue;
            // A SPILLED register is not free, however `used_regs` reads.
            //
            // `spillReg` stores the victim and clears `used_regs`, but the slot
            // that owned it still MAPS to it, and `ensureRegLive` reloads into
            // THAT SAME register. So handing it out here gives two owners one
            // register, and the later reload silently overwrites whichever
            // arrived second. Disassembled from a 3-read program answering 0:
            //
            //     add x22, x23, x25     ; a + b
            //     str x28, [sp, #0x8]   ; spill x28
            //     add x28, x22, x27     ; result computed INTO the freed x28
            //     ldr x28, [sp, #0x8]   ; reload clobbers it
            //     mov x0,  x28          ; returns the spilled garbage
            //
            // The real repair is a reload that may land in a DIFFERENT register
            // — `ensureRegLive` returning one instead of assuming the original.
            // That is an allocator change. Until then this keeps a spilled
            // register reserved to its owner: exhaustion then REFUSES, and a
            // refusal is a bail while the alternative is a wrong answer.
            if (self.spilled_regs.contains(reg)) continue;
            if (!self.used_regs[reg]) {
                self.claimReg(reg);
                return reg;
            }
        }
        reg = 0;
        while (reg < 8) : (reg += 1) {
            if (exclude != null and reg == exclude.?) continue;
            if (self.pending_arg_regs & (@as(u8, 1) << @as(u3, @intCast(reg))) != 0) continue;
            if (self.spilled_regs.contains(reg)) continue;
            if (!self.used_regs[reg]) {
                self.claimReg(reg);
                return reg;
            }
        }
        // THE SPILL PASSES BELOW CANNOT PRODUCE A REGISTER, AND OUTSIDE GATE
        // TRANSPORT THEY NEVER COULD. Refuse here instead of proving it again by
        // emitting the stores.
        //
        // `spillReg` clears `used_regs[victim]` and puts the victim in
        // `spilled_regs` — and BOTH free scans above skip anything
        // `spilled_regs` contains (that skip is the fail-closed guard, see its
        // comment). So a spill moves a register from "busy" to "reserved to its
        // owner" and the recursion re-scans a pool with exactly as many
        // allocatable registers as before: zero. Nothing else in the call can
        // change that. `spillReg`'s only removal from `spilled_regs` is
        // `ensureRegLive(victim)`, which touches the victim alone and re-adds it
        // one line later; `emitStrSp`/`emitLdrSp`/`emitSubSp` allocate nothing;
        // and `sweepGpLive`, the one path that does free a spilled register, is
        // never reached from here. So the recursion walks x28..x9 and then
        // x7..x0, spills every non-home register on the way down, and arrives at
        // the `error.RegisterExhausted` below with an empty pool — always.
        //
        // Discarded work, not a wrong answer: `probeCalleeSaveUse` compiles each
        // ladder rung on a FRESH `Arm64Compiler`, and the sole catch of this
        // error (`ensureRegLiveRemap`) rethrows it outside gate transport, so no
        // emitted `str`, no moved `sp`, and no `.spill` ledger entry from this
        // path ever reaches an artifact. Returning early is therefore the same
        // refusal, minus ~20 spill stores and recursion levels per doomed rung —
        // and each doomed rung is walked before the ladder can step down.
        //
        // GATE TRANSPORT IS THE EXCEPTION AND KEEPS THE PASSES VERBATIM: there
        // the cascade is load-bearing, because it is what populates
        // `spilled_regs` for the `reclaimSpilledReg` at the bottom of this
        // function. That reclaim hands back a register whose value is still in
        // the frame and drops the `spilled_regs` entry that would reload it —
        // the GAP-148 two-owner hazard, bounded to bootstrap transport. Not
        // widened, not repaired, and not closed by this fact.
        // Outside gate transport a spilled temporary's frame slot frees its
        // register: `spillTempForCapacity` moves one unpinned, unhomed,
        // unstaged temporary to the frame and hands its register back. Gate
        // transport keeps the passes below verbatim.
        if (!self.gate_transport) {
            if (try self.spillTempForCapacity(exclude)) |freed| return freed;
            return error.RegisterExhausted;
        }

        // SPILL A TEMP BEFORE A HOME, AND NEVER SPILL A CALL-SURVIVING HOME AT
        // ALL — see `gp_call_home_regs` for why the second is a wrong answer and
        // not merely a slow one.
        //
        // Two passes rather than one exclusion, so no LEAF loses a spill victim
        // it has today: a leaf's home is still a last-resort victim, just not
        // the first one reached from x28 down. The callee-bank homes are skipped
        // in both, because for them refusing costs nothing — the ladder in
        // `probeFunctionPlan` steps down and the bottom rung is the behaviour
        // that preceded homing.
        var victim: u5 = 28;
        while (victim >= 9) : (victim -= 1) {
            if (exclude != null and victim == exclude.?) continue;
            if (!self.used_regs[victim]) continue;
            if (self.gp_home_regs[victim]) continue;
            try self.spillReg(victim);
            return self.allocRegExcludingUnheld(exclude);
        }
        victim = 28;
        while (victim >= 9) : (victim -= 1) {
            if (exclude != null and victim == exclude.?) continue;
            if (!self.used_regs[victim]) continue;
            if (self.gp_call_home_regs & (@as(u32, 1) << victim) != 0) continue;
            try self.spillReg(victim);
            return self.allocRegExcludingUnheld(exclude);
        }
        victim = 7;
        while (true) : (victim -= 1) {
            if (exclude != null and victim == exclude.?) {
                if (victim == 0) break;
                continue;
            }
            // A staged argument register is not a spill candidate: its live value
            // belongs to the call being marshaled, not to a temp we can park.
            if (self.pending_arg_regs & (@as(u8, 1) << @as(u3, @intCast(victim))) != 0) {
                if (victim == 0) break;
                continue;
            }
            if (!self.used_regs[victim]) {
                if (victim == 0) break;
                continue;
            }
            try self.spillReg(victim);
            return self.allocRegExcludingUnheld(exclude);
        }
        if (self.gate_transport) return self.reclaimSpilledReg(exclude);
        return error.RegisterExhausted;
    }

    fn allocReg(self: *Arm64Compiler) Error!u5 {
        return self.allocRegExcluding(null);
    }

    /// A register to HOME A LOCAL IN for the rest of the function.
    ///
    /// In a function that calls, the bank is x19–x28 and the preference is not
    /// cosmetic: a home anywhere else is a value the next `bl` can reach, which
    /// is why every local in a calling function used to get a frame slot
    /// instead. `emitSaveCallerRegs` would preserve a caller-saved home across
    /// the call, but it preserves it BY STORING IT, so a home in x9..x17 pays
    /// per call what a frame slot pays per assignment — and a home in x0..x7
    /// is not preserved at all until something sets `used_regs` for it, which
    /// is the shape of the `bare` miscompile the memory form was answering.
    ///
    /// x19–x28 are the callee's to preserve, so nothing has to be emitted at
    /// the call at all; the prologue saves exactly the ones this body claims
    /// (`claimReg` records them, `probeCalleeSaveUse` measures them, and
    /// `compileDnirModule` refuses if the two disagree).
    ///
    /// Falls through to the ordinary pool when the bank is full or the function
    /// is a leaf: a leaf's caller-saved homes are already safe, and paying a
    /// prologue save/restore pair for them would be a regression.
    fn allocHomeReg(self: *Arm64Compiler) Error!u5 {
        if (self.cur_func_has_call) {
            var reg: u5 = callee_save_first;
            while (reg <= callee_save_last) : (reg += 1) {
                if (self.used_regs[reg]) continue;
                if (self.spilled_regs.contains(reg)) continue;
                self.claimReg(reg);
                self.gp_call_home_regs |= @as(u32, 1) << reg;
                return reg;
            }
            // THE BANK IS THE ONLY PLACE A CALLING FUNCTION MAY HOME A LOCAL,
            // and running out of it is a refusal rather than a fallback.
            //
            // `allocRegExcluding` ends in x0..x7, and a local homed THERE is the
            // `bare` miscompile the frame-slot rule was written to prevent —
            // reached again from the other side. It is not the `bl` that breaks
            // it: `emitSaveCallerRegs` does preserve a claimed x0..x7 across the
            // call. It is ARGUMENT STAGING for the NEXT call, because
            // `preserveArgReg` — whose whole job is to move a live value out of
            // an argument register before it is staged — begins
            // `if (regIsPinned(pinned, slot)) return;`. It treats "pinned" as
            // "safe", an assumption that held exactly as long as no local was
            // ever homed in x0..x7.
            //
            // MEASURED, on a 40-line reduction of `sha.id`'s compression loop
            // (two memory-backed tables, a dynamically indexed table WRITE, and
            // a call in the loop). Nine locals took x19..x27, a hoisted
            // immediate took x28, and the tenth local `si` fell through to x0:
            //
            //     and  x0, x27, x12      ; si = (t & 15) …
            //     add  x1, x0, x13
            //     mov  x0, x1            ; …homed in x0
            //     …
            //     mov  x0, x23           ; and staged over, for the next call
            //
            // Answer 134; the frame-slot build and `--backend=c` both answer
            // 159. `sha.id` degraded the same way — 0 instead of 16, every NIST
            // digest word wrong — and `native.id` fell from 210 to 128.
            //
            // Refusing costs nothing HERE: `probeFunctionPlan` catches it, steps
            // the ladder down, and fewer locals are homed. The bottom rung is
            // the frame, which is where all of them used to live.
            return error.RegisterExhausted;
        }
        return self.allocRegExcluding(null);
    }

    fn restoreStackFrame(self: *Arm64Compiler) Error!void {
        if (self.sp_temp_bytes != 0) return self.refuse(@src());
        if (self.stack_frame_bytes > 0) {
            try self.emitAddSp(self.stack_frame_bytes);
        }
        try self.emitRestoreCalleeRegs();
    }

    /// Apple AAPCS64: x19–x28 belong to the caller. Save them under the
    /// locals/spill frame so `[sp,#off]` homes stay zero-based.
    const callee_save_first: u5 = 19;
    const callee_save_last: u5 = 28;
    const callee_save_count: u16 = @as(u16, callee_save_last - callee_save_first + 1);
    const callee_save_span: u16 = callee_save_count * 8;
    /// Every callee-saved register, i.e. what the prologue used to save
    /// unconditionally.
    const callee_save_all: u32 = blk: {
        var m: u32 = 0;
        var r: u5 = callee_save_first;
        while (r <= callee_save_last) : (r += 1) m |= @as(u32, 1) << r;
        break :blk m;
    };

    /// Mark a register as claimed, remembering it if the ABI makes it ours to
    /// give back. One funnel, because a claim that skips this is a register
    /// saved by nobody — an ABI violation in the CALLER, which is the class of
    /// defect that cannot be found by running the callee.
    fn claimReg(self: *Arm64Compiler, reg: u5) void {
        self.used_regs[reg] = true;
        if (reg >= callee_save_first and reg <= callee_save_last) {
            self.callee_touched |= @as(u32, 1) << reg;
        }
    }

    fn protectReg(self: *Arm64Compiler, reg: u5) void {
        self.held_regs |= @as(u32, 1) << reg;
    }

    fn unprotectReg(self: *Arm64Compiler, reg: u5) void {
        self.held_regs &= ~(@as(u32, 1) << reg);
    }

    /// Save exactly the callee-saved registers in `callee_save_plan`.
    ///
    /// This block used to be ten stores and ten loads in every function that
    /// reached x19 at all, whether it reached x28 or stopped at x19. Measured
    /// across the surface's artifacts, 737 of 790 saved registers were never
    /// written — 1,474 instructions preserving values nothing touched, and in
    /// five artifacts (`lex`, `array`, `branch`, `control`, `match`) not a single
    /// saved register was used by anything.
    ///
    /// The SPAN is deliberately NOT narrowed with the set. Every register keeps
    /// its fixed slot at `(r - 19) * 8`, so `callee_save_bytes` stays 80 whenever
    /// anything is saved and no stacked-parameter displacement moves as a
    /// function of WHICH registers were needed. Only the empty plan collapses
    /// the frame, and then it collapses completely — no `sub sp`, no `add sp`,
    /// nothing.
    fn emitSaveCalleeRegs(self: *Arm64Compiler) Error!void {
        if (self.callee_save_plan == 0) return;
        try self.emitSubSp(callee_save_span);
        var reg: u5 = callee_save_first;
        while (reg <= callee_save_last) : (reg += 1) {
            if (self.callee_save_plan & (@as(u32, 1) << reg) == 0) continue;
            try self.emitStrSp(reg, (@as(u16, reg) - callee_save_first) * 8);
            try self.callee_save_sites.append(self.alloc, .{ .offset = @intCast(self.code.items.len - 4), .reg = reg });
        }
        self.callee_save_bytes = callee_save_span;
    }

    fn emitRestoreCalleeRegs(self: *Arm64Compiler) Error!void {
        if (self.callee_save_bytes == 0) return;
        var reg: u5 = callee_save_first;
        while (reg <= callee_save_last) : (reg += 1) {
            if (self.callee_save_plan & (@as(u32, 1) << reg) == 0) continue;
            try self.emitLdrSp(reg, (@as(u16, reg) - callee_save_first) * 8);
            try self.callee_save_sites.append(self.alloc, .{ .offset = @intCast(self.code.items.len - 4), .reg = reg });
        }
        try self.emitAddSp(self.callee_save_bytes);
    }

    fn emitStrSpFp(self: *Arm64Compiler, dreg: u5, offset: u16) Error!void {
        const imm = try self.spScaledDisp(offset);
        try self.emitFmt(0xfd0003e0 | (imm << 10) | @as(u32, dreg), "str d{d}, [sp, #{d}]", .{ dreg, offset });
    }

    fn emitLdrSpFp(self: *Arm64Compiler, dreg: u5, offset: u16) Error!void {
        const imm = try self.spScaledDisp(offset);
        try self.emitFmt(0xfd4003e0 | (imm << 10) | @as(u32, dreg), "ldr d{d}, [sp, #{d}]", .{ dreg, offset });
    }

    /// A GENERAL REGISTER READ INTO THE FLOAT FILE IS STILL A GENERAL REGISTER
    /// READ (GAP-148).
    ///
    /// `xreg` is a SOURCE, and every other emitter in this file that reads one
    /// asks `ensureRegLive` first, because `spilled_regs` naming a register is
    /// this backend's statement that the register is not where the value is.
    /// The two GP->FP transfers were the ones never asked, and the widening
    /// caller reaches this from `temps` directly rather than through
    /// `evalDnirValue`, so no reload happens above it either: under pressure
    /// the cascade spills the integer, `spillReg` clears `used_regs` and takes
    /// it out of `emitSaveCallerRegs`'s save set, the next `bl` clobbers it,
    /// and this converts the call's leavings into a float. No diagnostic.
    ///
    /// The destination side is deliberately not symmetric: `emitFmovToGpr` and
    /// `emitFcvtzsFromFp` WRITE their `xreg`, and `spilled_regs` is keyed by GP
    /// index, so reloading against an FP operand would `ldr` a GP slot at an
    /// index from the wrong register file.
    ///
    /// Bounded to gate transport with the rest of GAP-148: `allocRegExcluding`
    /// refuses above its spill passes otherwise, so `spilled_regs` is empty
    /// elsewhere and this is a no-op. Not the closure -- closure is
    /// authoritative `register`/`frame` assignment before emission, per that
    /// gap's record, under which the location of a value crossing register
    /// files is carried by the assignment rather than reasked at each emitter.
    fn emitScvtfFromGpr(self: *Arm64Compiler, dreg: u5, xreg: u5) Error!void {
        // SCVTF from a **64-bit** GPR is 0x9e620000. This read 0x1e620000, which
        // is the 32-bit source form, while both callers hand it an x register:
        // anything at or above 2^32 would have converted from its low half. The
        // asm text said `scvtf d, x` either way, so only a byte-level oracle
        // could tell the two apart -- `zig build isa-fidelity` is that oracle.
        try self.ensureRegLive(xreg);
        try self.emitFmt(0x9e620000 | (@as(u32, xreg) << 5) | @as(u32, dreg), "scvtf d{d}, x{d}", .{ dreg, xreg });
    }

    fn emitFmovToGpr(self: *Arm64Compiler, xreg: u5, dreg: u5) Error!void {
        try self.emitFmt(0x9e660000 | (@as(u32, dreg) << 5) | @as(u32, xreg), "fmov x{d}, d{d}", .{ xreg, dreg });
    }

    fn emitFcvtzsFromFp(self: *Arm64Compiler, xreg: u5, dreg: u5) Error!void {
        try self.emitFmt(0x9e780000 | (@as(u32, dreg) << 5) | @as(u32, xreg), "fcvtzs x{d}, d{d}", .{ xreg, dreg });
    }

    fn emitFmovImmFp(self: *Arm64Compiler, dreg: u5, value: f64) Error!void {
        const tmp = try self.allocReg();
        try self.emitMovImm(tmp, @bitCast(value));
        try self.emitFmovFromGpr(dreg, tmp);
        self.releaseReg(tmp);
    }

    fn emitFcmpReg(self: *Arm64Compiler, lhs: u5, rhs: u5) Error!void {
        try self.emitFmt(0x1e602000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5), "fcmp d{d}, d{d}", .{ lhs, rhs });
    }

    fn emitCsetFp(self: *Arm64Compiler, dst: u5, cond: Condition) Error!void {
        try self.emitFmt(encodeCset(dst, cond), "cset x{d}, {s}", .{ dst, conditionName(cond) });
    }

    fn loadStackField(self: *Arm64Compiler, key: []const u8) Error!u5 {
        const slot = self.fp_stack_slots.get(key) orelse return self.undefinedKey(@src(), "fp stack slot", key);
        const reg = try self.allocReg();
        try self.emitLdrFrame(reg, slot.off);
        return reg;
    }

    /// THE RELEASE DROPPED THE ENTRY AND KEPT THE SLOT.
    ///
    /// Taking a register out of `spilled_regs` is what makes the frame slot
    /// behind it unreadable: `ensureRegLive` and `ensureRegLiveRemap` are that
    /// slot's only readers and both key on the entry this line removes. So the
    /// removal is also the moment the slot becomes dead, and every other path
    /// that performs it hands the slot back on the spot — `sweepGpLive` and
    /// `reclaimSpilledReg` for a register they take from its owner, both reloads
    /// for a value they move out of the frame. This one kept it, and a slot
    /// nothing can ever read again stayed reserved for the rest of the function:
    /// `spillReg` stepped `gate_spill_cursor` past it toward `gate_spill_end`
    /// and then refused a spill the pre-reserved area still had room for, which
    /// is the condition that drives `ensureRegLiveRemap` into its exhaustion arm
    /// and `allocRegExcluding` into the reclaim at its bottom.
    ///
    /// The release is safe for the same reason it is owed: this body is reached
    /// only with `gp_reg_owner[reg]` null, so no owner is left to read the slot
    /// either. The removal is idempotent and a release is not — the emit paths
    /// release the same register more than once, `releaseReg(addr)` beside
    /// `releaseReg(base)` where both resolved to one register — so the append
    /// belongs to the removal that actually took the entry, exactly as
    /// `sweepGpLive` writes it.
    ///
    /// Bounded to gate transport with the rest of GAP-148: `allocRegExcluding`
    /// refuses above its spill loops otherwise, so `spilled_regs` is empty
    /// elsewhere and this is the `used_regs` clear alone. Not the closure —
    /// closure is authoritative `register`/`frame` assignment before emission,
    /// per that gap's record.
    ///
    /// GIVING BACK A CLAIM IS NOT RETIRING STORAGE, AND BELOW x9 NO OWNER
    /// RECORD SAYS WHICH IT IS (GAP-148).
    ///
    /// Every write to `gp_reg_owner` skips `r < 9`, so the ownerless test above
    /// reads a call or pack result the ABI left in x0..x7 as scratch while
    /// `temps` names its register — and the third spill pass walks x7..x0, so
    /// that register reaches `spilled_regs`. Dropping the entry there deleted
    /// the value's last location and handed its slot to the next spill; the
    /// next read found no entry, got the register back unchanged, and answered
    /// with whatever had landed in it. The claim is still given back, because
    /// the caller is done with the register either way; only the storage stays,
    /// and `allocRegExcluding` skips a register `spilled_regs` contains, so
    /// pressure refuses instead of handing out a second owner.
    ///
    /// The term is the BAND and not the map. At x9 and above the owner record
    /// is rebound after every value instruction, so ownerless there means the
    /// claim is genuinely gone — `evalDnirValue` says so itself, refusing a
    /// `temps` name in that band whose owner does not match and falling through
    /// to the frame home. Skipping on the name there would leak the slot of
    /// ordinary released scratch, which is the leak the paragraph above repairs.
    /// One walk answering "does a temp naming reg still need it after index at".
    /// Both the staged-argument guard and releaseReg's low-register guard ask
    /// this; the walk is shared so the two cannot drift into different
    /// readings of temp liveness. unknown_live is the policy for a temp with
    /// no value_free_at entry (never seen as an operand): releaseReg treats it
    /// as dead (a value never used is dead); staged call marshaling treats it
    /// as live (defensive at calls, where a mistake corrupts the callee's
    /// arguments).
    fn tempNamesLiveReg(
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        value_free_at: *const std.AutoHashMapUnmanaged(u32, u32),
        reg: u5,
        at: u32,
        unknown_live: bool,
    ) bool {
        var it = temps.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.* != reg) continue;
            const last = value_free_at.get(entry.key_ptr.*) orelse
                (if (unknown_live) std.math.maxInt(u32) else @as(u32, 0));
            if (last > at) return true;
        }
        return false;
    }

    fn lowRegHoldsLiveTemp(self: *const Arm64Compiler, reg: u5) bool {
        const tm = self.eval_temps orelse return false;
        return tempNamesLiveReg(tm, &self.value_free_at, reg, self.cur_emit_idx, false);
    }

test "native backend: tempNamesLiveReg protects a low-register temp with a future use" {
    // The t35 shape: temp 35 names x4, last used at instruction 55.
    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(std.testing.allocator);
    var free_at: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer free_at.deinit(std.testing.allocator);
    try temps.put(std.testing.allocator, 35, 4);
    try free_at.put(std.testing.allocator, 35, 55);

    // At instruction 50 the temp is live under both policies.
    try std.testing.expect(Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 4, 50, false));
    try std.testing.expect(Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 4, 50, true));
    // At its last use the temp is dead: the register may be reused.
    try std.testing.expect(!Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 4, 55, false));
    // A register no temp names is never protected.
    try std.testing.expect(!Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 5, 50, false));
    try std.testing.expect(!Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 5, 50, true));

    // A temp with no value_free_at entry (never seen as an operand): the
    // releaseReg policy treats it as dead so the register does not leak;
    // the staged call-marshaling policy treats it as live, defensively.
    try temps.put(std.testing.allocator, 99, 6);
    try std.testing.expect(!Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 6, 50, false));
    try temps.put(std.testing.allocator, 99, 6);
    try std.testing.expect(!Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 6, 50, false));
    try std.testing.expect(Arm64Compiler.tempNamesLiveReg(&temps, &free_at, 6, 50, true));
}

test "native backend: destfwd adopts dying temp register as first local home" {
    var diag: Diagnostic = .{};
    var f64m: F64RecordMap = .empty;
    var scalm: ScalRecordMap = .empty;
    var comp = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diag,
        .f64_records = &f64m,
        .scal_records = &scalm,
    };
    defer comp.value_free_at.deinit(comp.alloc);
    defer comp.asm_text.deinit(comp.alloc);
    comp.cur_func_has_call = false;
    try comp.value_free_at.put(comp.alloc, 7, 10);
    comp.used_regs[22] = true;
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(std.testing.allocator);
    const ins = dnir.Instr{ .op = .binop, .binop = .add, .lhs = .{ .temp = 7 } };
    // Temp 7 dies at instruction 10 in claimed x22: its register becomes
    // the local home with no fresh allocation and no move.
    try std.testing.expect(comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
}

test "native backend: destfwd refuses adoption outside its guard band" {
    var diag: Diagnostic = .{};
    var f64m: F64RecordMap = .empty;
    var scalm: ScalRecordMap = .empty;
    var comp = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diag,
        .f64_records = &f64m,
        .scal_records = &scalm,
    };
    defer comp.value_free_at.deinit(comp.alloc);
    try comp.value_free_at.put(comp.alloc, 7, 10);
    comp.used_regs[22] = true;
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(std.testing.allocator);
    const ins = dnir.Instr{ .op = .binop, .binop = .add, .lhs = .{ .temp = 7 } };
    try std.testing.expect(comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
    // A calling function keeps the callee-saved home path.
    comp.cur_func_has_call = true;
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
    comp.cur_func_has_call = false;
    // The temp still has a later read: adopting would steal a live value.
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 22, 9));
    // The argument band is not an adoptable value register.
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 8, 10));
    // An unclaimed register carries no value to adopt.
    comp.used_regs[22] = false;
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
    comp.used_regs[22] = true;
    // A register already homed stays a home.
    comp.gp_home_regs[22] = true;
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
    comp.gp_home_regs[22] = false;
    // A pinned register belongs to the local it was pinned for.
    try pinned.put(std.testing.allocator, 3, 22);
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, ins, 22, 10));
    // A non-temp operand has no dying register to adopt.
    const imm = dnir.Instr{ .op = .binop, .binop = .add, .lhs = .{ .i64 = 4 } };
    try std.testing.expect(!comp.adoptTempAsLocalHome(&pinned, imm, 22, 10));
}

test "native backend: identity forwarding keeps a dying operand register" {
    var diag: Diagnostic = .{};
    var f64m: F64RecordMap = .empty;
    var scalm: ScalRecordMap = .empty;
    var comp = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diag,
        .f64_records = &f64m,
        .scal_records = &scalm,
    };
    defer comp.value_free_at.deinit(comp.alloc);
    defer comp.asm_text.deinit(comp.alloc);
    try comp.value_free_at.put(comp.alloc, 5, 20);
    comp.used_regs[21] = true;
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(std.testing.allocator);
    const ins = dnir.Instr{ .op = .binop, .binop = .add, .lhs = .{ .temp = 5 } };
    // x + 0 with the operand dying here reuses its register.
    try std.testing.expectEqual(@as(?u5, 21), comp.identityBinopForwardDst(&pinned, ins, 0, 21, 20));
    // A non-identity constant still allocates a fresh destination.
    try std.testing.expect(comp.identityBinopForwardDst(&pinned, ins, 1, 21, 20) == null);
    // The operand lives past this instruction: forwarding would steal it.
    try std.testing.expect(comp.identityBinopForwardDst(&pinned, ins, 0, 21, 19) == null);
    // The argument band is not a forwarding candidate.
    try std.testing.expect(comp.identityBinopForwardDst(&pinned, ins, 0, 8, 20) == null);
    // A homed register is never forwarded.
    comp.gp_home_regs[21] = true;
    try std.testing.expect(comp.identityBinopForwardDst(&pinned, ins, 0, 21, 20) == null);
}

test "native backend: identity emitter skips the self move" {
    var diag: Diagnostic = .{};
    var f64m: F64RecordMap = .empty;
    var scalm: ScalRecordMap = .empty;
    var comp = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diag,
        .f64_records = &f64m,
        .scal_records = &scalm,
    };
    defer comp.code.deinit(comp.alloc);
    defer comp.asm_text.deinit(comp.alloc);
    const before = comp.code.items.len;
    try comp.emitBinopConst(22, 22, 0, .add, .i64);
    try std.testing.expectEqual(before, comp.code.items.len);
    // A distinct destination still gets its move.
    try comp.emitBinopConst(23, 22, 0, .add, .i64);
    try std.testing.expect(comp.code.items.len > before);
}

test "native backend: adopted home narrows in place without a move" {
    var diag: Diagnostic = .{};
    var f64m: F64RecordMap = .empty;
    var scalm: ScalRecordMap = .empty;
    var comp = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diag,
        .f64_records = &f64m,
        .scal_records = &scalm,
    };
    defer comp.code.deinit(comp.alloc);
    defer comp.asm_text.deinit(comp.alloc);
    // This is the exact call the adoption arm makes for a u8 local.
    _ = try comp.emitNarrowFit(22, 22, .u8);
    try std.testing.expectEqual(@as(usize, 4), comp.code.items.len);
    const word = std.mem.readInt(u32, comp.code.items[0..4], .little);
    // A self move (orr x22, xzr, x22) is 0xAA1603D6; the narrow is the
    // in-place ubfx, whose source and destination fields both name x22.
    try std.testing.expect(word != 0xAA1603D6);
    try std.testing.expectEqual(@as(u32, 22), word & 0x1f);
    try std.testing.expectEqual(@as(u32, 22), (word >> 5) & 0x1f);
    // Full-width types narrow to nothing.
    const full_before = comp.code.items.len;
    _ = try comp.emitNarrowFit(22, 22, .i64);
    try std.testing.expectEqual(full_before, comp.code.items.len);
}

    fn releaseReg(self: *Arm64Compiler, reg: u5) void {
        self.unprotectReg(reg);
        if (reg >= 29) return;
        if (reg == platform_reserved_reg) return;
        if (reg >= 9 and reg < 29 and self.gp_home_regs[reg]) return;
        // A PIN IS A CLAIM, AND THIRTY CALL SITES WERE ASKING IT INSTEAD OF
        // THIS ONE (GAP-148).
        //
        // `regIsPinned(pinned, r)` guards roughly thirty of the calls into this
        // function and is absent from the rest — `.br`'s `releaseReg(cond)`,
        // the record return's staging release, `store_global`'s address — and
        // every absence is a claim given back for a register a map still names.
        // `gp_home_regs` is not that map: it is empty below x9, so the LEAF
        // parameter `compileDnirFunction` keeps in its incoming x0..x7 register
        // reaches this body pinned, ownerless, and unflagged.
        //
        // That parameter's claim is the repair immediately above its own
        // `pinned.put`: `allocRegExcluding` does not read `pinned`, so with
        // x9..x28 busy it falls to x0..x7 and asks only `used_regs` — the
        // measurement there is a loop that ran to signed overflow and answered
        // independently of its argument. `claimReg(arg_reg)` bought that back,
        // and `if c then ... else ...` on a parameter handed it straight to
        // this line, which cleared `used_regs` and undid it.
        //
        // The term is the one `ensureRegLiveRemap` and `reclaimSpilledReg`
        // already honour for the same register, asked by the third path that
        // takes a register away from the map naming it. Behaviour at the
        // guarded call sites is unchanged — they never reached this body with a
        // pinned register — so what changes is only where the question lives.
        // Under pressure a leaf that would have miscompiled now refuses.
        //
        // Not the closure — closure is authoritative `register`/`frame`
        // assignment before emission, per this gap's record, under which a
        // parameter's claim is carried by the assignment rather than restated
        // by a map each caller has to remember to consult.
        if (self.evalPinNames(reg)) return;
        if (self.gp_reg_owner[reg] != null) return;
        // Below x9 no gp_reg_owner record exists, so the owner test above
        // cannot tell a live temp's register from scratch: allocRegExcluding
        // hands x0..x7 out under pressure and an emitter's unconditional
        // releaseReg(lhs/rhs) then cleared used_regs while the temp was
        // still live, so a later allocReg reused the register and a later
        // read through the stale temps name saw the new value. Ask the temps
        // map instead: a temp still live at the current instruction keeps
        // its register. Same reading stagedRegHoldsLiveValue uses.
        if (reg < 9 and self.lowRegHoldsLiveTemp(reg)) return;
        self.used_regs[reg] = false;
        if (reg < 9 and self.evalTempNames(reg)) return;
        if (self.spilled_regs.fetchRemove(reg)) |entry| {
            self.free_spill_slots.append(self.alloc, entry.value) catch {};
        }
    }

    /// Before an argument is written into a caller-saved ABI register (x0-x7),
    /// move any live temp that still occupies it into an owned register (x9-x28).
    /// The first of two calls in `f(a) + f(b)` — e.g. `fib(n-1) + fib(n-2)` —
    /// homes its result in x0 as the fast path, and x0 is never tracked in
    /// `gp_reg_owner`. Without this relocation the second call's argument
    /// marshaling overwrote that result BEFORE `emitSaveCallerRegs` could
    /// preserve it, so the `+` read the second argument in place of the first
    /// result: recursion collapsed to `f(n) = (n-2) + f(n-2)` and returned
    /// wrong values for fib(n) >= 7. An owned register is preserved across the
    /// call by the ordinary save/restore and freed by the liveness sweep.
    /// Reserve `slot` (an x0..x7 argument register) as holding a staged argument
    /// for the call being marshaled, so `allocRegExcluding` will not hand it out
    /// as scratch while a later argument's operand is loaded. Cleared by `emitBl`.
    fn markStagedArgReg(self: *Arm64Compiler, slot: u5) void {
        if (slot < 8) self.pending_arg_regs |= (@as(u8, 1) << @as(u3, @intCast(slot)));
    }

    fn releaseStagedArgRegs(
        self: *Arm64Compiler,
        staged: u8,
        call_result: ?u5,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        at: u32,
    ) void {
        var r: u5 = 0;
        while (r < 8) : (r += 1) {
            if (staged & (@as(u8, 1) << @as(u3, @intCast(r))) == 0) continue;
            if (call_result == r) continue;
            // A staged register still holds its pre-call value: the save around
            // the call preserved it and the restore put it back. Releasing the
            // register while a live temps id still names it orphans the name:
            // the next call's save set skips the register (it reads used_regs),
            // the callee clobbers it, and the surviving name reads the clobbered
            // value. staleGpName cannot see this -- it covers x9..x28 only, and
            // an ABI-placed value carries no gp_reg_owner at all. So the release
            // is conditional on no live claim surviving. temps entries are never
            // removed when their value dies, so the name alone cannot tell live
            // from dead; value_free_at against this call's index does, the same
            // reading preserveArgReg's victim scan uses.
            if (self.stagedRegHoldsLiveValue(temps, r, at)) continue;
            self.unprotectReg(r);
            self.used_regs[r] = false;
        }
        self.pending_arg_regs &= ~staged;
    }

    // Does a live value still claim reg through temps after the call at index
    // at? x0..x7 never carry gp_reg_owner (it is only ever set for x9..x28),
    // so for a staged argument register the temps name is the whole claim.
    fn stagedRegHoldsLiveValue(
        self: *const Arm64Compiler,
        temps: *const std.AutoHashMapUnmanaged(u32, u5),
        reg: u5,
        at: u32,
    ) bool {
        return tempNamesLiveReg(temps, &self.value_free_at, reg, at, true);
    }

    /// The same question `pending_arg_regs` answers for x0..x7, asked for the
    /// VARIADIC TAIL — whose arguments are staged in ordinary allocatable
    /// registers and written to the callee's memory-argument area, not into a
    /// parameter register.
    ///
    /// Derived from `pending_varargs` rather than restated in a second mask:
    /// `reg` is already recorded there and `staged` is already the fact that it
    /// holds the argument, so there is nothing here for the two to disagree
    /// about. Empty outside a call being marshaled — `pending_vararg_count` is
    /// zero until `mov_arg` stages a tail and `emitPopVarargs` returns it to
    /// zero — so this is false everywhere else.
    fn stagedTailReg(self: *const Arm64Compiler, reg: u5) bool {
        var i: u5 = 0;
        while (i < self.pending_vararg_count) : (i += 1) {
            const slot = self.pending_varargs[i];
            if (slot.staged and slot.reg == reg) return true;
        }
        return false;
    }

    fn preserveArgReg(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        slot: u5,
        at: u32,
    ) Error!void {
        if (slot >= 8) return;
        if (Arm64Compiler.regIsPinned(pinned, slot)) return;
        // EVERY id THAT NAMES THIS REGISTER MOVES, not the first one found.
        //
        // One register routinely carries two ids: `store_local` writes
        // `temps[slot] = R` for the binding while `temps[temp_id] = R` still
        // names the value that produced it, and `evalDnirValue` will serve
        // either. Relocating one and leaving the other is worse than relocating
        // neither — the surviving entry keeps pointing at an ABI register that
        // the very next instruction stages an argument into, and it reads that
        // argument instead of its own value.
        //
        // It stayed hidden while nothing much lived in x0..x7. Homing carried
        // locals in the callee bank tightens x9..x28, and the allocator's
        // x0..x7 fallback stops being the rare path: `sha.id` began answering 0
        // instead of 16, and `native.id` 128 instead of 210, at six homes and
        // above — with the register-home mechanism itself innocent, since the
        // same programs are correct at five.
        // The owner that travels with the register is the LONGEST-LIVED of the
        // ids that named it. `sweepGpLive` frees a register once its owner has
        // no read left, so naming any earlier-dying id would hand the register
        // back while another id is still reading it — and naming none at all
        // (owner null) is the other way to be wrong: the sweep then never
        // reclaims it, and `tree.id` runs the direct backend out of registers
        // (DNB003) on the spot.
        var victim: ?u32 = null;
        var victim_last: u32 = 0;
        var it = temps.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.* != slot) continue;
            const id = entry.key_ptr.*;
            const last = self.value_free_at.get(id) orelse std.math.maxInt(u32);
            // A STALE NAME IS NOT A VALUE (GAP-148).
            //
            // Nothing removes a `temps` entry when its value dies —
            // `sweepGpLive` clears `gp_reg_owner` and `used_regs` and leaves
            // `temps` alone — so an id whose last read is already behind
            // emission goes on naming this register for the rest of the
            // function. Relocating for it costs a move and a register nobody
            // needed, and when the pool has nothing but `slot` the exclusion
            // below turns that cost into a REFUSAL of a program with no live
            // value in the slot at all. `value_free_at` is the fact that tells
            // the two apart, and `at` is the instruction index it has to be
            // read against — which is the whole reason this function is handed
            // one.
            //
            // `last < at`, not the `last <= idx` `sweepGpLive` uses. The sweep
            // runs AFTER the instruction at `idx` and may retire an id that
            // instruction read; this runs BEFORE the marshaling it guards
            // completes, so an id whose last read IS the call being marshaled
            // is still owed its value and stays a victim.
            //
            // An id ABSENT from the map stays a victim too, which is what
            // `orelse maxInt` above already spells. Absence is "no read this
            // compiler attributed to the id", not "no read": `sweepGpLive`
            // reads it as dead at every index, and the register it hands back
            // for it is the abandonment `reclaimSpilledReg` records. On a path
            // whose act is to MOVE a live value, the safe reading of the same
            // silence is the opposite one.
            if (last < at) continue;
            if (victim == null or last > victim_last) {
                victim = id;
                victim_last = last;
            }
        }
        const t = victim orelse return;
        // THE REGISTER BEING PRESERVED IS NOT A DESTINATION IT MAY BE HANDED
        // (GAP-148).
        //
        // This asked `allocReg` for somewhere to put `slot`'s value while
        // holding `slot` across the call, and `allocReg` is
        // `allocRegExcluding(null)` — it may return `slot` itself. The old
        // `fresh == slot` arm read that as "nothing to do" and returned. It is
        // the opposite: a victim was already found, so `temps` names `slot`,
        // and the caller's very next instruction writes the staged argument
        // into `slot` (`emitMovImm`, `emitAdrpAdd`, `emitMovReg`). Returning
        // leaves every id that named `slot` reading that argument instead of
        // its own value — the exact miscompile this function was written for
        // (`fib(n-1) + fib(n-2)` collapsing to `(n-2) + f(n-2)`), reached
        // through the allocator rather than through the marshaling.
        //
        // `slot` comes back in two states, and both are this gap's shape. In
        // the free scan, x9..x28 are all busy and the x0..x7 fallback reaches
        // `slot` because `used_regs[slot]` is false while `temps` still names
        // it — the released-but-named register `releaseDnirTemp` documents at
        // the `call_direct` operand, and the state that makes a victim findable
        // at all. Under gate transport `reclaimSpilledReg` reaches it a second
        // way: the cascade spills `slot`, the reclaim drops the `spilled_regs`
        // entry that was the only thing able to reload it, and hands `slot`
        // back with its value abandoned in the frame. Then `releaseReg(fresh)`
        // frees `slot` for the argument, and there is no longer anything that
        // holds the value at all.
        //
        // `exclude` is what every other holder-across-allocation already uses
        // for this, and `reclaimSpilledReg` states the promise in its own name:
        // hash order must not reach the caller's register. `emitIfConverted`
        // and `emitIfConvertedTwoSided` open the identical window and both
        // close it. This one did not.
        //
        // When the pool has nothing but `slot`, the exclusion refuses instead
        // of relocating. That is the trade this file makes everywhere else — a
        // refusal is a bail while the alternative is a wrong answer — and it is
        // now paid only for a value that is actually live: the victim scan
        // above reads `value_free_at` against `at` and passes over an id whose
        // last read is already behind emission, so a slot named only by dead
        // ids leaves this function without a move, without a register, and
        // without a bail.
        //
        // Not the closure — closure is authoritative `register`/`frame`
        // assignment before emission, per this gap's record, under which the
        // value in an ABI slot has a location the assignment names and is not
        // one the scratch allocator can bid for.
        const fresh = try self.allocRegExcluding(slot);
        try self.emitMovReg(fresh, slot);
        var wit = temps.iterator();
        while (wit.next()) |entry| {
            if (entry.value_ptr.* == slot) entry.value_ptr.* = fresh;
        }
        if (fresh != platform_reserved_reg and !self.gp_home_regs[fresh]) {
            self.gp_reg_owner[fresh] = t;
        }
    }

    fn assignRecordFromAbiRegs(self: *Arm64Compiler, base: []const u8, desc: ScalRecordDesc) Error!void {
        const n = desc.field_names.len;
        if (n == 0 or n > 8) return self.refuse(@src());

        // The slot is reserved once per record local, not once per execution.
        // This code runs again on every loop iteration, and emitting `sub sp`
        // each time walks the stack pointer down by a frame per iteration —
        // every field offset shifts and the loads return garbage. Reuse the
        // reservation when this base already has one.
        const first_key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, desc.field_names[0] });
        defer self.alloc.free(first_key);
        const already_reserved = self.fp_stack_slots.contains(first_key);

        var base_off: u16 = 0;
        if (already_reserved) {
            base_off = (self.fp_stack_slots.get(first_key) orelse unreachable).off;
        } else {
            const raw_frame: u16 = @intCast(n * 8);
            const frame: u16 = @intCast(std.mem.alignForward(u16, raw_frame, 16));
            try self.frameGrow(frame);
        }

        var i: usize = 0;
        while (i < n) : (i += 1) {
            const off: u16 = base_off + @as(u16, @intCast(i * 8));
            const abi_reg: u5 = @intCast(i);
            try self.emitStrFrame(abi_reg, off);
            if (already_reserved) continue;
            const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, desc.field_names[i] });
            try self.fp_stack_slots.put(self.alloc, key, .{ .off = off, .float = desc.field_kinds[i] == .f64 });
        }
    }

    fn assignF64RecordFromFpAbiRegs(self: *Arm64Compiler, base: []const u8, desc: F64RecordDesc) Error!void {
        const n = desc.field_names.len;
        if (n == 0 or n > 8) return self.refuse(@src());

        // Reserved once per record local, not once per execution — the same
        // reuse the scalar arm above carries. Growing again on the next loop
        // iteration walks `sp` down by a frame per iteration.
        const first_key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, desc.field_names[0] });
        defer self.alloc.free(first_key);
        var base_off: u16 = 0;
        if (self.fp_stack_slots.get(first_key)) |slot| {
            base_off = slot.off;
        } else {
            const raw_frame: u16 = @intCast(n * 8);
            const frame: u16 = @intCast(std.mem.alignForward(u16, raw_frame, 16));
            try self.frameGrow(frame);
        }
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const off: u16 = base_off + @as(u16, @intCast(i * 8));
            const abi_d: u5 = @intCast(i);
            self.used_fp_regs[abi_d] = true;
            try self.emitStrFrameFp(abi_d, off);
            const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, desc.field_names[i] });
            try self.fp_locals.put(self.alloc, key, abi_d);
            try self.fp_stack_slots.put(self.alloc, key, .{ .off = off, .float = true });
        }
    }

    fn emitRetF64RecordFromDnir(self: *Arm64Compiler, temps: *std.AutoHashMapUnmanaged(u32, u5), ins: dnir.Instr) Error!void {
        const vals = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
        const count = ins.result orelse 1;
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            const d = try self.evalDnirValueFp(temps, vals[@intCast(i)]);
            const abi_d: u5 = @intCast(i);
            if (d != abi_d) try self.emitFmovReg(abi_d, d);
            if (d != abi_d) self.releaseFpReg(d);
            self.used_fp_regs[abi_d] = true;
        }
    }

    fn ensureExternalSymbol(self: *Arm64Compiler, symbol_name: []const u8) Error!void {
        // One physical spelling cannot be both defined here and imported. A
        // prior silent return let a local export named `puts` capture an exact
        // C-import application before relocation was emitted.
        if (self.definedSymbolOffset(symbol_name) != null) return error.DuplicateSymbol;
        if (self.extern_symbols.contains(symbol_name)) return;
        if (self.symbolOffset(symbol_name)) |_| return error.DuplicateSymbol;
        const owned_name = try self.alloc.dupe(u8, symbol_name);
        errdefer self.alloc.free(owned_name);
        const symbol_index: u32 = @intCast(self.symbols.items.len);
        try self.symbols.append(self.alloc, .{ .name = owned_name, .offset = 0, .defined = false });
        try self.extern_symbols.put(self.alloc, symbol_name, symbol_index);
    }

    fn emitMovImm(self: *Arm64Compiler, reg: u5, value: i64) Error!void {
        const unsigned = @as(u64, @bitCast(value));
        var emitted = false;
        var shift: u32 = 0;
        while (shift < 64) : (shift += 16) {
            const part: u16 = @intCast((unsigned >> @as(u6, @intCast(shift))) & 0xffff);
            const hw = shift / 16;
            if (!emitted) {
                const word = 0xd2800000 | (hw << 21) | (@as(u32, part) << 5) | @as(u32, reg);
                if (shift == 0) {
                    try self.emitFmt(word, "mov x{d}, #{d}", .{ reg, part });
                } else {
                    try self.emitFmt(word, "movz x{d}, #{d}, lsl #{d}", .{ reg, part, shift });
                }
                emitted = true;
            } else if (part != 0) {
                try self.emitFmt(0xf2800000 | (hw << 21) | (@as(u32, part) << 5) | @as(u32, reg), "movk x{d}, #{d}, lsl #{d}", .{ reg, part, shift });
            }
        }
        if (!emitted) try self.emitFmt(0xd2800000 | @as(u32, reg), "mov x{d}, #0", .{reg});
    }

    fn emitMovReg(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        try self.ensureRegLive(src);
        try self.emitMovRegRaw(dst, src);
    }

    /// `mov dst, src` for a source THIS BACKEND'S ALLOCATOR DID NOT WRITE.
    ///
    /// `emitMovReg` reloads its source because a source register may hold a
    /// value this function spilled, and `spilled_regs` is where that value
    /// went. That question is only meaningful while the entry describes the
    /// register's CURRENT contents. After a `bl` it does not: x0 holds the
    /// callee's answer, and any entry naming x0 describes a DIFFERENT owner's
    /// frame copy from before the call. Reloading it there puts that copy over
    /// the answer, and does it at an offset measured from a stack pointer the
    /// save area has already moved. So the ABI result is copied out with the
    /// move alone, and the entry is left to the owner it belongs to.
    fn emitMovRegRaw(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        try self.emitFmt(0xaa0003e0 | (@as(u32, src) << 16) | @as(u32, dst), "mov x{d}, x{d}", .{ dst, src });
    }

    /// Refit a 64-bit register to a DECLARED sub-64-bit integer width.
    ///
    /// Every value in this backend lives in a 64-bit register, so a `u32` local
    /// held its full 64-bit history and `h: u32 = 4294967295; h = h + 5`
    /// answered 4294967300 where `--backend=c` — which emits a real
    /// `uint32_t` and a real `((uint32_t)(...))` cast on every store — answered
    /// 4. Same source, two backends, different answers, `ok compile` both
    /// times. That is the whole defect: the register is wide and the TYPE is
    /// not, and nothing ever narrowed it back.
    ///
    /// One instruction, and the signedness is the part that must not be
    /// guessed: `u32` ZERO-extends (SBFM would make 0xFFFFFFFF into -1) and
    /// `i32` SIGN-extends (UBFM would make -1 into 4294967295). Getting that
    /// backwards trades one silent wrong answer for another, so the two use
    /// physically different opcodes rather than a shared "mask" with a sign
    /// flag applied afterwards.
    ///
    /// Returns false when `ty` is not a narrow integer, so callers can keep
    /// their existing move rather than emitting a redundant one.
    fn emitNarrowFit(self: *Arm64Compiler, dst: u5, src: u5, ty: native_types.ResolvedType) Error!bool {
        const fit = narrowFit(ty) orelse return false;
        try self.ensureRegLive(src);
        const imms: u32 = @as(u32, fit.bits) - 1;
        if (fit.signed) {
            // SBFM Xd, Xn, #0, #(bits-1) — `sxtb`/`sxth`/`sxtw`.
            const mnemonic = switch (fit.bits) {
                8 => "sxtb",
                16 => "sxth",
                else => "sxtw",
            };
            try self.emitFmt(
                0x93400000 | (imms << 10) | (@as(u32, src) << 5) | @as(u32, dst),
                "{s} x{d}, w{d}",
                .{ mnemonic, dst, src },
            );
        } else {
            // UBFM Xd, Xn, #0, #(bits-1) — `ubfx xd, xn, #0, #bits`.
            try self.emitFmt(
                0xd3400000 | (imms << 10) | (@as(u32, src) << 5) | @as(u32, dst),
                "ubfx x{d}, x{d}, #0, #{d}",
                .{ dst, src, fit.bits },
            );
        }
        return true;
    }

    /// `emitNarrowFit` when the width demands it, an ordinary `mov` otherwise,
    /// and NOTHING when the register already is the destination and the width
    /// does not demand a refit. The narrow case therefore costs zero extra
    /// instructions wherever a move was already being emitted.
    fn emitMovRegFit(self: *Arm64Compiler, dst: u5, src: u5, ty: native_types.ResolvedType) Error!void {
        if (try self.emitNarrowFit(dst, src, ty)) return;
        if (dst != src) try self.emitMovReg(dst, src);
    }

    /// A register holding `ty`'s value, refitted, for a store that has no
    /// destination register to refit INTO — a frame-homed local.
    ///
    /// Never refits `src` in place. The value being stored may have further
    /// readers (`a = t` followed by `b = t`), and truncating the shared
    /// register would answer the second read with the first read's width. A
    /// scratch costs one register; getting this wrong costs a wrong answer that
    /// only appears under register pressure.
    fn narrowedFrameSource(self: *Arm64Compiler, src: u5, ty: native_types.ResolvedType) Error!u5 {
        if (narrowFit(ty) == null) return src;
        const scratch = try self.allocRegExcluding(src);
        _ = try self.emitNarrowFit(scratch, src, ty);
        return scratch;
    }

    fn cell(self: *const Arm64Compiler, instruction: dnir.Instr) Error!bool {
        if (instruction.record.len == 0) return false;
        var record: ?dnir.RecordDesc = null;
        for (self.record) |candidate| {
            if (!std.mem.eql(u8, candidate.name, instruction.record)) continue;
            if (record != null) return recordRefusalWith(self.diagnostic, @src(), "record-cell-descriptor");
            record = candidate;
        }
        const layout = record orelse return recordRefusalWith(self.diagnostic, @src(), "record-cell-descriptor");
        if (layout.fields.len != layout.kinds.len or instruction.rhs != .i64 or instruction.rhs.i64 != 1)
            return recordRefusalWith(self.diagnostic, @src(), "record-cell-layout");
        var found = false;
        for (layout.fields, layout.kinds, 0..) |field, kind, index| {
            if (!std.mem.eql(u8, field, instruction.field)) continue;
            if (found) return recordRefusalWith(self.diagnostic, @src(), "record-cell-field");
            const descriptor: native_types.ResolvedType = switch (kind) {
                .str => .str,
                .f64 => .f64,
                .i64 => if (index < layout.widths.len) layout.widths[index] orelse .i64 else .i64,
            };
            if (!descriptor.eql(instruction.ty)) return recordRefusalWith(self.diagnostic, @src(), "record-cell-carrier");
            found = true;
        }
        if (!found) return recordRefusalWith(self.diagnostic, @src(), "record-cell-field");
        switch (instruction.ty) {
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .bool, .str, .pointer => {},
            else => return recordRefusalWith(self.diagnostic, @src(), "record-cell-carrier"),
        }
        return true;
    }

    fn emitRet(self: *Arm64Compiler) Error!void {
        try self.emit(0xd65f03c0, "ret");
    }

    /// §12 TAIL — `b <symbol>`. A BRANCH to another function, not a call: x30
    /// is left holding OUR caller's return address, so the callee's `ret`
    /// returns past us and this frame never comes back.
    ///
    /// Registered as an ordinary call patch. `b` and `bl` differ only in the
    /// top six bits and share the imm26 field, so relocation is the same
    /// arithmetic — see `patchCalls`, which now keeps whichever opcode was
    /// emitted here instead of writing BL over it.
    fn emitTailB(self: *Arm64Compiler, target: []const u8) Error!void {
        const offset: u32 = @intCast(self.code.items.len);
        const link_name = try linkerSymbolName(self.alloc, target);
        defer self.alloc.free(link_name);
        const owned_target = try self.alloc.dupe(u8, link_name);
        errdefer self.alloc.free(owned_target);
        try self.emitFmt(0x14000000, "b _{s}", .{link_name});
        try self.call_patches.append(self.alloc, .{ .offset = offset, .target = owned_target });
        self.pending_arg_regs = 0;
    }

    /// §12 TAIL — realize a call in tail position as a JUMP into the callee.
    ///
    /// THE ARGUMENTS ARE ALREADY WHERE THE CALLEE READS THEM, and that is the
    /// answer to the staging question. Every one of them was written into
    /// x0..x7 by `mov_arg` while this frame still stood; `restoreStackFrame`
    /// moves `sp` and reloads x19..x28 and touches nothing else, so the
    /// tear-down cannot reach a staged argument and none of them needs to
    /// survive it anywhere but where it already is. No shuffle, no scratch
    /// area, no second copy.
    ///
    /// The one shape that would need somewhere in between is a NINTH argument,
    /// whose home is memory ABOVE this frame — and `tailCallFusible` refuses
    /// that outright rather than inventing a staging area for it.
    ///
    /// `emitSaveCallerRegs` is not emitted at all, and must not be: it exists
    /// to carry values ACROSS a call, and nothing here comes back.
    fn emitTailCallDirect(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        at: u32,
    ) Error!void {
        if (ins.lhs != .void) {
            const arg_reg = try self.evalDnirValue(temps, ins.lhs);
            if (arg_reg != 0) {
                try self.preserveArgReg(temps, pinned, 0, at);
                try self.emitMovReg(0, arg_reg);
            }
            self.releaseDnirTemp(pinned, ins.lhs, arg_reg);
        }
        // EXACTLY WHAT THE PROLOGUE DID, IN REVERSE, and it is the same call
        // `ret` makes one line before its own `ret` — the frame region, then
        // the callee-saved bank `emitSaveCalleeRegs` actually saved. Sharing
        // the function is the point: a tear-down that drifted from the ordinary
        // return's would hand the callee a stack pointer no `ret` agrees with.
        try self.restoreStackFrame();
        try self.emitTailB(ins.callee);
        self.returned = true;
        self.tailcall_admitted += 1;
    }

    /// GP argument slots `g` reads, counted the way the prologue assigns them:
    /// one 8-byte word per scalar parameter and one per exploded field of a
    /// scalar record parameter. Null when a parameter names a record this
    /// compilation has no descriptor for, which is not a count of anything.
    fn gpArgSlotCount(self: *const Arm64Compiler, g: dnir.Function) ?u32 {
        var slots: u32 = 0;
        for (g.params) |p| {
            var k: u32 = 1;
            if (p.record) |rec_name| {
                const rec = scalRecordDesc(self.scal_records, rec_name) orelse return null;
                k = @intCast(rec.field_names.len);
            }
            slots += k;
        }
        return slots;
    }

    fn moduleFunctionNamed(self: *const Arm64Compiler, name: []const u8) ?dnir.Function {
        for (self.cur_module_functions) |g| {
            if (std.mem.eql(u8, g.name, name)) return g;
        }
        return null;
    }

    /// §12 TAIL's ADMISSION, asked at the point of emission because two of its
    /// grounds are only knowable there: whether this call staged anything into
    /// the outgoing memory area, and what this frame still owes on the way out.
    ///
    /// The transform is physical and nothing else. The application is still
    /// realized, still a call to the same target with the same arguments, and
    /// still publishes its lineage row over the bytes emitted for it; only the
    /// stack discipline changes. That is why this lives here and not in
    /// `dnir_lower`, where the same rewrite would be a GRAPH transformation
    /// (replacing an application with a branch) and needs a transform entity
    /// and a witness — which is exactly why `dnir_lower.tryEmitSelfTail`
    /// declines every checked application and, in a graph-lifted module, fires
    /// on nothing at all.
    ///
    /// Every ground below is a REFUSAL, and the cost of each refusal is one
    /// ordinary call — today's emission, byte for byte.
    fn tailCallFusible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        ins: dnir.Instr,
        next: dnir.Instr,
        ret_index: u32,
    ) bool {
        if (!self.tailcall) return false;
        if (ins.op != .call_direct or next.op != .ret) return false;
        // Gate transport spills parameters to the frame and runs a raised home
        // budget; it is a bootstrap transport, not a place to prove a new stack
        // discipline. Declined, and it pays one ordinary call for that.
        if (self.gate_transport) return false;
        // THE CALL'S RESULT MUST BE THE ANSWER, UNCHANGED. Anything between the
        // two — a narrowing refit, a record copy-out from x0..x7, a second pack
        // member — is work this frame still owes, and a frame that still owes
        // work cannot be given away.
        const result = ins.result orelse return false;
        const returns_the_call = switch (next.lhs) {
            .temp => |t| t == result,
            else => false,
        };
        if (!returns_the_call) return false;
        if (ins.pack_results.len != 0 or ins.record.len != 0 or ins.field.len != 0) return false;
        // The `ret` is CONSUMED and emits no bytes of its own, so it must carry
        // no lineage to publish. Nothing lowers a `ret` with application facts
        // today; if that ever changes, this declines rather than dropping a row.
        if (next.application != null or next.relation != null or next.value != null) return false;
        // ONE REGISTER FILE. The f64 arms stage through d0..d7 and return
        // through d0 under their own conventions, and `restoreStackFrame` says
        // nothing about d8..d15. A tail call across the FP boundary is a
        // separate proof; this is not it.
        if (ins.ty == .f64 or next.ty == .f64) return false;
        if (self.cur_func_float or self.cur_func_ret_float or self.cur_func_ret == .f64) return false;
        // WHAT THIS FRAME STILL OWES ON THE WAY OUT. A record result leaves
        // through a buffer this frame owns or through x8; a pack leaves in
        // several registers; the entry relation may owe a coercion for process
        // exit. Each is a real obligation and none of them survives the frame.
        if (self.cur_func_ret_record != null or self.cur_func_ret_pack.len != 0) return false;
        if (self.cur_func_ret_f64_record != null or self.cur_ret_indirect_reg != null) return false;
        if (self.needsProcessExitF64Coerce()) return false;
        // STACKED ARGUMENTS — THE REFUSAL CONDITION, STATED.
        //
        // A ninth GP argument does not travel in a register. It is written into
        // an OUTGOING MEMORY AREA that this call site opens BELOW the current
        // frame (`emitPushVarargs`), and the callee reads it from just above
        // its own. Reusing this frame means giving that region back before the
        // branch, so the argument would have to be written into the INCOMING
        // area instead — which requires the incoming area to be at least as
        // large as the outgoing one AND requires every word to be written after
        // the tear-down, from values that lived in the frame that just went
        // away. Neither is free and neither is proved here.
        //
        // So: a call in tail position that staged ANY stacked argument is
        // refused. `pending_vararg_count` is exactly that question — `mov_arg`
        // routes every slot at or past 8 into it — and it is asked at emission
        // because it is the call site's own fact, not the callee's.
        if (self.pending_vararg_count != 0) return false;
        // THE CALLEE'S DECLARATION, not the call site's spelling. A caller
        // cannot read a convention off a symbol name (`AGENTS.md`), so a callee
        // this compilation does not hold the declaration of is refused —
        // including every call that leaves this object.
        const g = self.moduleFunctionNamed(ins.callee) orelse return false;
        // A boundary that answers on C's convention is not ours to jump into
        // on Idol's, in either direction.
        if (g.foreign_boundary or f.foreign_boundary) return false;
        if (g.is_float_kernel or g.ret == .f64) return false;
        if (g.ret_record != null or g.ret_pack.len != 0) return false;
        // THE CALLEE NARROWS ITS OWN RESULT ON ITS OWN `ret`, and that is only
        // OUR answer when the two descriptors are the same one. A caller
        // declaring i32 over a callee declaring i64 still owes the truncation
        // `emitMovRegFit` would have emitted, so it keeps its call.
        if (!std.meta.eql(g.ret, f.ret)) return false;
        // Belt and braces over `pending_vararg_count`: a callee that reads a
        // ninth slot must never be jumped to from a site that staged eight.
        const slots = self.gpArgSlotCount(g) orelse return false;
        if (slots > 8) return false;
        // NOTHING MAY BRANCH TO THE `ret` WE ARE ABOUT TO CONSUME. A consumed
        // instruction's code offset is the byte AFTER the bytes this iteration
        // emitted — here, after the jump — so a branch aimed at it would land
        // on whatever the emitter puts next, which is the next function.
        for (f.blocks) |b| {
            for (b.instrs) |other| {
                if (other.op == .br and other.branch_target == ret_index) return false;
            }
        }
        return true;
    }

    // ===================== §12 `error.depth` =====================
    //
    // WHAT THE FAULT IS. `docs/spec/cost.md`'s non-tail-recursion row reads
    // "metered `error.depth`, routed", and its fault contract reads "No SIGSEGV
    // as an API". Before this, a non-tail recursion deep enough to walk off the
    // stack died at exit 139 with an EMPTY stderr: the process was killed by the
    // guard page, and nothing in the artifact had an opinion about it. The
    // hardware was already detecting the fault perfectly. What was missing was
    // its NAME.
    //
    // WHERE THE LIMIT COMES FROM, and it is the actual one. `emitDepthLimitInit`
    // asks the kernel for `RLIMIT_STACK` at process entry and subtracts it from
    // the `sp` the entry stood on, so the metered limit tracks `ulimit -s`
    // rather than a number this compiler made up. A fixed budget would have been
    // one instruction cheaper and WRONG IN BOTH DIRECTIONS: too large under
    // `ulimit -s 1024` (the guard page still wins, and the fault is still
    // unnamed), too small under `ulimit -s 65536` (a program the user
    // deliberately gave room to would start faulting — the exact regression this
    // work must not cause).
    //
    // WHY NOT A GUARD-PAGE HANDLER, which would have cost ZERO instructions.
    // Naming a SIGSEGV requires `sigaltstack` + `sigaction` installed before
    // `main` and a handler that decides whether the faulting address is the
    // stack's guard region. That is a RUNTIME, and this backend deliberately has
    // none: `docs/spec/cost.md` records that its only fixed runtime symbols are
    // `printf` and `puts`, and every other branch target is a user callee. A
    // handler would put a second entry point, an import, and a signal-safe
    // writer into every artifact this backend emits. The metered form buys the
    // same name for five instructions in the prologues of the few functions that
    // can recurse at all, and nothing anywhere else.
    //
    // WHY NOT A DEPTH COUNTER, which is what the fault is NAMED after. A counter
    // is a load, an add, a store and a compare on the way in and a second
    // read-modify-write on EVERY way out, including every early `return` — and
    // it measures the wrong thing, because what runs out is bytes, not levels.
    // `sp` is the counter, the machine maintains it for free, and one `cmp`
    // reads it.

    /// §12 `error.depth` — the static half of `tailCallFusible`, asked of the
    /// DNIR alone.
    ///
    /// `tailCallFusible` is asked at the point of EMISSION because two of its
    /// grounds are only knowable there. This asks every other ground — the two
    /// declarations and the module roster — before a byte is emitted, which is
    /// when the metering decision has to be made, because the check it decides
    /// goes in the PROLOGUE.
    ///
    /// It is deliberately the WEAKER predicate. It admits everything
    /// `tailCallFusible` admits and possibly more, and `keepsAFrameInCycle`
    /// reads it NEGATED, so erring here costs metering that was not needed
    /// (instructions) and never metering that was. The one direction it can be
    /// wrong in is a call this admits and emission then declines: that frame is
    /// metered by nobody, which is exactly today's behaviour for that shape and
    /// is recorded as a residual rather than hidden.
    fn tailCallStaticallyAdmissible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        ins: dnir.Instr,
        next: dnir.Instr,
        ret_index: u32,
    ) bool {
        if (!self.tailcall) return false;
        if (self.gate_transport) return false;
        if (ins.op != .call_direct or next.op != .ret) return false;
        const result = ins.result orelse return false;
        const returns_the_call = switch (next.lhs) {
            .temp => |t| t == result,
            else => false,
        };
        if (!returns_the_call) return false;
        if (ins.pack_results.len != 0 or ins.record.len != 0 or ins.field.len != 0) return false;
        if (next.application != null or next.relation != null or next.value != null) return false;
        if (ins.ty == .f64 or next.ty == .f64) return false;
        if (f.is_float_kernel or f.ret == .f64 or f.foreign_boundary) return false;
        if (f.ret_record != null or f.ret_pack.len != 0) return false;
        const g = self.moduleFunctionNamed(ins.callee) orelse return false;
        if (g.foreign_boundary or g.is_float_kernel or g.ret == .f64) return false;
        if (g.ret_record != null or g.ret_pack.len != 0) return false;
        if (!std.meta.eql(g.ret, f.ret)) return false;
        const slots = self.gpArgSlotCount(g) orelse return false;
        if (slots > 8) return false;
        for (f.blocks) |b| {
            for (b.instrs) |other| {
                if (other.op == .br and other.branch_target == ret_index) return false;
            }
        }
        return true;
    }

    /// Does `f` hold a call to a cycle co-member that KEEPS ITS FRAME?
    ///
    /// A tail call is a jump — `examples/table/tailcall.id` runs ten million
    /// levels in constant stack — so metering the textbook tail-recursive shape
    /// would put a compare and a branch in the hottest loop this language has,
    /// ten million times, to test a pointer that never moves. Only a recursive
    /// call that is not in tail position, or one in tail position the transform
    /// will not take, can exhaust anything.
    fn keepsAFrameInCycle(
        self: *const Arm64Compiler,
        f: dnir.Function,
        cycle: *const std.StringHashMapUnmanaged(void),
    ) bool {
        var flat_idx: u32 = 0;
        for (f.blocks) |b| {
            var bi: usize = 0;
            while (bi < b.instrs.len) : ({
                bi += 1;
                flat_idx += 1;
            }) {
                const ins = b.instrs[bi];
                if (ins.op != .call_direct) continue;
                if (!cycle.contains(ins.callee)) continue;
                if (bi + 1 >= b.instrs.len) return true;
                if (!self.tailCallStaticallyAdmissible(f, ins, b.instrs[bi + 1], flat_idx + 1)) return true;
            }
        }
        return false;
    }

    /// The metered set: every module function that can reach ITSELF and holds a
    /// recursive call that keeps its frame.
    ///
    /// Reachability is exact rather than conservative because this IR has no
    /// indirect call. `native_ir.Op` carries `call_direct` and `call_extern` and
    /// nothing else, so every edge out of a function names its callee, and a
    /// module with no cycle through `f` bounds every chain through `f` by the
    /// number of functions in the module. A hundred distinct frames is not a
    /// stack exhaustion; a hundred thousand copies of one frame is.
    ///
    /// Transitive closure by repeated relaxation over an n x n bit matrix. n is
    /// the function count of ONE module, and the largest in this tree is in the
    /// low hundreds, so the cubic bound is not worth an SCC pass to avoid.
    fn computeDepthMeteredSet(self: *Arm64Compiler, functions: []const dnir.Function) Error!void {
        self.depth_metered_names.clearRetainingCapacity();
        self.depth_module_meters = false;
        if (!self.depth_meter) return;
        const n = functions.len;
        if (n == 0) return;
        const reach = try self.alloc.alloc(bool, n * n);
        defer self.alloc.free(reach);
        @memset(reach, false);
        for (functions, 0..) |f, i| {
            for (f.blocks) |b| {
                for (b.instrs) |ins| {
                    if (ins.op != .call_direct) continue;
                    for (functions, 0..) |g, j| {
                        if (std.mem.eql(u8, g.name, ins.callee)) reach[i * n + j] = true;
                    }
                }
            }
        }
        // Skip the O(n^3) transitive closure when the call graph is acyclic:
        // a cycle-free graph has no function reaching itself, so
        // depth_metered_names would stay empty. Kahn's check is O(n^2).
        {
            const indeg = try self.alloc.alloc(u32, n);
            defer self.alloc.free(indeg);
            @memset(indeg, 0);
            var ci: usize = 0;
            while (ci < n) : (ci += 1) {
                var cj: usize = 0;
                while (cj < n) : (cj += 1) {
                    if (reach[ci * n + cj]) indeg[cj] += 1;
                }
            }
            const queue = try self.alloc.alloc(usize, n);
            defer self.alloc.free(queue);
            var qh: usize = 0;
            var qt: usize = 0;
            var ii: usize = 0;
            while (ii < n) : (ii += 1) {
                if (indeg[ii] == 0) {
                    queue[qt] = ii;
                    qt += 1;
                }
            }
            var visited: usize = 0;
            while (qh < qt) : (qh += 1) {
                const u = queue[qh];
                visited += 1;
                var vv: usize = 0;
                while (vv < n) : (vv += 1) {
                    if (reach[u * n + vv]) {
                        indeg[vv] -= 1;
                        if (indeg[vv] == 0) {
                            queue[qt] = vv;
                            qt += 1;
                        }
                    }
                }
            }
            if (visited == n) return;
        }
        var changed = true;
        while (changed) {
            changed = false;
            var k: usize = 0;
            while (k < n) : (k += 1) {
                var i: usize = 0;
                while (i < n) : (i += 1) {
                    if (!reach[i * n + k]) continue;
                    var j: usize = 0;
                    while (j < n) : (j += 1) {
                        if (reach[k * n + j] and !reach[i * n + j]) {
                            reach[i * n + j] = true;
                            changed = true;
                        }
                    }
                }
            }
        }
        var cycle: std.StringHashMapUnmanaged(void) = .empty;
        defer cycle.deinit(self.alloc);
        for (functions, 0..) |f, i| {
            if (reach[i * n + i]) try cycle.put(self.alloc, f.name, {});
        }
        if (cycle.count() == 0) return;
        for (functions) |f| {
            if (!cycle.contains(f.name)) continue;
            if (!self.keepsAFrameInCycle(f, &cycle)) continue;
            try self.depth_metered_names.put(self.alloc, f.name, {});
        }
        self.depth_module_meters = self.depth_metered_names.count() != 0;
    }

    /// The `__DATA,__bss` word holding the metered limit, interned on demand.
    fn depthLimitSymbol(self: *Arm64Compiler) Error!u32 {
        if (self.depth_limit_sym) |idx| return idx;
        // `.` cannot occur in an Idol binding name and is legal in a Mach-O
        // label, so this word cannot collide with `internGlobal`'s namespace for
        // any program and the `.s` face still assembles.
        const idx = try self.internGlobal("idol.depth.limit");
        self.depth_limit_sym = idx;
        return idx;
    }

    /// SYS_write to fd 2, then the SAME abort `emitTrapAbort` raises.
    ///
    /// The exit code is 134 and NOT a fresh ordinary one, deliberately. A
    /// module's answer becomes its process exit status truncated to a byte
    /// (`_sum(300)` exits 45150 & 0xff = 158), so NO ordinary code is
    /// unambiguous in this language — the name has to live on stderr, and once
    /// it does, the status may as well agree with every other deliberate fault
    /// this backend raises rather than inventing a second convention.
    ///
    /// Control never leaves this block, which is what makes clobbering
    /// x0/x1/x2/x16 safe here for exactly the reason `emitTrapAbort` states.
    fn emitDepthFault(self: *Arm64Compiler) Error!void {
        const msg = "idol: error.depth: stack exhausted by non-tail recursion (§12; raise `ulimit -s`, or make the recursion a tail call)\n";
        const sym = try self.internString(msg);
        if (self.target_windows) {
            // puts(msg); __fastfail(0x1D02). Raw fd-2 write(2) does not
            // exist on Windows, so the message travels the normal msvcrt
            // import (a `bl puts` the PE writer routes through its thunk)
            // instead of a syscall; the 0x1D02 code distinguishes a
            // depth/bounds fault from the generic 0x1D01 trap.
            try self.ensureExternalSymbol("puts");
            try self.emitAdrpAdd(0, sym);
            try self.emitBl("puts");
            try self.emit(0xd283a040, "movz w0, #0x1d02");
            try self.emit(0xd43e0000, "brk #0xF000");
            return;
        }
        const movz = struct {
            fn word(reg: u5, imm: u16) u32 {
                return 0xd2800000 | (@as(u32, imm) << 5) | @as(u32, reg);
            }
        }.word;
        try self.emitFmt(movz(0, 2), "mov x0, #{d}", .{2});
        try self.emitAdrpAdd(1, sym);
        try self.emitFmt(movz(2, @intCast(msg.len)), "mov x2, #{d}", .{msg.len});
        // Per-host write(2): macOS BSD 4 via x16/svc #0x80, Linux __NR 64 via
        // x8/svc #0. (See emitTrapAbort for why the register differs.)
        const host_linux = builtin.os.tag == .linux;
        const sc: u5 = if (host_linux) 8 else 16;
        const nr_write: u16 = if (host_linux) 64 else 4;
        const svc_word: u32 = if (host_linux) 0xd4000001 else 0xd4001001;
        const svc_text: []const u8 = if (host_linux) "svc #0" else "svc #0x80";
        try self.emitFmt(movz(sc, nr_write), "mov x{d}, #{d}", .{ sc, nr_write });
        try self.emit(svc_word, svc_text);
        try self.emitTrapAbort();
    }

    /// The metered prologue: FIVE instructions on the path that is taken.
    ///
    ///     adrp x16, limit@PAGE
    ///     add  x16, x16, limit@PAGEOFF
    ///     ldr  x16, [x16]
    ///     cmp  sp, x16
    ///     b.hi .Lok              ; unsigned: still above the floor
    ///     <fault>                ; cold, jumped over, never executed
    ///   .Lok:
    ///
    /// `cmp sp, x16` reads the stack pointer DIRECTLY — SUBS accepts SP as its
    /// first operand in the extended-register form — so no scratch register is
    /// moved and no value is spilled to make room for one. x16 is IP0, which the
    /// ABI reserves for exactly this and which `claimReg` never hands out, so the
    /// probe pass and the real pass measure the same callee-saved set with the
    /// check present in both.
    ///
    /// THE UNSIGNED COMPARE IS THE ONE THAT IS RIGHT. A stack address is a
    /// pointer, not a number with a sign; `b.gt` would let a limit above
    /// 0x7fff… through as "below". `hi` is the same choice, for the same reason,
    /// that `emitIndexBoundsCheck` makes.
    ///
    /// ZERO IS THE DISABLED LIMIT and it is what a zerofill word already holds,
    /// so a module whose entry never ran the initializer takes `b.hi` every time
    /// — `sp` is never zero — and behaves exactly as it does now.
    fn emitDepthCheck(self: *Arm64Compiler) Error!void {
        const sym = try self.depthLimitSymbol();
        const sname = self.symbols.items[sym].name;
        const page_off: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x90000000 | @as(u32, 16), "adrp x{d}, {s}@PAGE", .{ 16, sname });
        try self.relocations.append(self.alloc, .{ .offset = page_off, .symbol_index = sym, .kind = .page21 });
        const ldr_off: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0xf9400000 | (@as(u32, 16) << 5) | 16, "ldr x{d}, [x{d}, {s}@PAGEOFF]", .{ 16, 16, sname });
        try self.relocations.append(self.alloc, .{ .offset = ldr_off, .symbol_index = sym, .kind = .pageoff12 });
        try self.emit(0xeb3063ff, "cmp sp, x16");
        const cond: u32 = @intFromEnum(Condition.hi);
        const branch_off: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x54000000 | cond, "b.hi .Lduo_depth_ok_{d}", .{self.depth_metered_count});
        try self.emitDepthFault();
        // The fault block is jumped over by the SAME branch that tests the
        // limit, exactly as `emitIndexBoundsCheck` jumps its trap — no second
        // unconditional branch, and the cold bytes cost nothing at run time.
        const over: u32 = (@as(u32, @intCast(self.code.items.len)) - branch_off) / 4;
        if (over >= (1 << 18)) return self.refuse(@src());
        std.mem.writeInt(
            u32,
            self.code.items[branch_off..][0..4],
            0x54000000 | (over << 5) | cond,
            .little,
        );
        try self.asm_text.print(self.alloc, ".Lduo_depth_ok_{d}:\n", .{self.depth_metered_count});
        self.depth_metered_count += 1;
    }

    /// Run ONCE, at the top of the process entry: publish the lowest `sp` a
    /// metered prologue may stand on.
    ///
    ///     limit = sp_at_entry - (min(RLIMIT_STACK.rlim_cur, 8 MiB when absurd
    ///                                or unavailable) - 64 KiB)
    ///
    /// `getrlimit` answers into a two-word buffer: BSD syscall 194 on macOS,
    /// __NR 163 on Linux aarch64. macOS reports failure in the CARRY flag, so
    /// the fallback is a `csel`; Linux returns -errno in x0 with flags
    /// untouched, so the Linux arm synthesizes carry with
    /// `adds x16, x0, #4096` first. The 64 KiB margin is what the fault block
    /// itself and the frame
    /// that trips the check stand on, and it is generous by an order of
    /// magnitude over the largest prologue this backend emits.
    ///
    /// x0 and x1 are the syscall's argument registers AND the entry's incoming
    /// `argc`/`argv`, so both are saved and reloaded around it. Everything else
    /// this touches is x16/x17 (IP0/IP1), which no allocation reaches.
    fn emitDepthLimitInit(self: *Arm64Compiler) Error!void {
        const sym = try self.depthLimitSymbol();
        const movz = struct {
            fn word(reg: u5, imm: u16, shift: u2) u32 {
                return 0xd2800000 | (@as(u32, shift) << 21) | (@as(u32, imm) << 5) | @as(u32, reg);
            }
        }.word;
        // getrlimit(RLIMIT_STACK = 3, &buf) into a 32-byte scratch that also
        // parks argc/argv.
        try self.emit(0xd10083ff, "sub sp, sp, #32");
        try self.emitStrSp(0, 16);
        try self.emitStrSp(1, 24);
        try self.emitFmt(movz(0, 3, 0), "mov x0, #{d}", .{3});
        try self.emit(0x910003e1, "mov x1, sp");
        // Per-host getrlimit: macOS BSD 194 via x16/svc #0x80, Linux __NR
        // 163 via x8/svc #0. (See emitTrapAbort for why the register differs.)
        const host_linux = builtin.os.tag == .linux;
        const sc: u5 = if (host_linux) 8 else 16;
        const nr_getrlimit: u16 = if (host_linux) 163 else 194;
        const svc_word: u32 = if (host_linux) 0xd4000001 else 0xd4001001;
        const svc_text: []const u8 = if (host_linux) "svc #0" else "svc #0x80";
        if (self.target_windows) {
            // No getrlimit on Windows and no stable raw syscall to probe
            // with — but there is nothing to probe: the PE header this same
            // compilation writes declares SizeOfStackReserve (peStackReserve
            // = 1 MiB), so x17 takes the fixed budget directly.
            try self.emitFmt(movz(17, 0x10, 1), "mov x17, #{d}", .{0x100000});
        } else {
            try self.emitFmt(movz(sc, nr_getrlimit, 0), "mov x{d}, #{d}", .{ sc, nr_getrlimit });
            try self.emit(svc_word, svc_text);
            try self.emitFmt(0xf9400000 | (@as(u32, 31) << 5) | 17, "ldr x17, [sp]", .{});
            if (host_linux) {
                // Linux returns -errno in x0 and leaves PSTATE alone, so the
                // macOS carry-set-on-failure test below would read a stale flag.
                // Synthesize it: x0 + 4096 carries out iff x0 is in [-4096, -1],
                // exactly the kernel's error range. x0 is reloaded from its park
                // slot two instructions later, so clobbering x16 here is free;
                // the `csel cs` below then reads this adds-set carry.
                try self.emit(0xb1400010, "adds x16, x0, #4096");
            }
        }
        try self.emitLdrSp(0, 16);
        try self.emitLdrSp(1, 24);
        try self.emit(0x910083ff, "add sp, sp, #32");
        // 8 MiB, the Darwin main-thread default, as the fallback for both the
        // failed call (carry set) and an rlim_cur at or past 2 GiB — which is how
        // RLIM_INFINITY arrives and is not a budget anything can stand on.
        if (!self.target_windows) {
            try self.emitFmt(movz(16, 0x80, 1), "mov x16, #{d}", .{0x800000});
            try self.emit(0x9a912211, "csel x17, x16, x17, cs");
            try self.emit(0xd35ffe2f, "lsr x15, x17, #31");
            try self.emit(0xf10001ff, "cmp x15, #0");
            try self.emit(0x9a911211, "csel x17, x16, x17, ne");
        }
        // Reserve the margin, then floor = sp - budget.
        try self.emit(0xd1404231, "sub x17, x17, #16, lsl #12");
        try self.emit(0x910003f0, "mov x16, sp");
        try self.emit(0xcb110210, "sub x16, x16, x17");
        try self.emitAdrpAdd(17, sym);
        try self.emitFmt(0xf9000000 | (@as(u32, 17) << 5) | 16, "str x{d}, [x{d}]", .{ 16, 17 });
    }

    fn emitBl(self: *Arm64Compiler, target: []const u8) Error!void {
        const offset: u32 = @intCast(self.code.items.len);
        const link_name = try linkerSymbolName(self.alloc, target);
        defer self.alloc.free(link_name);
        const owned_target = try self.alloc.dupe(u8, link_name);
        errdefer self.alloc.free(owned_target);
        try self.emitFmt(0x94000000, "bl _{s}", .{link_name});
        try self.call_patches.append(self.alloc, .{ .offset = offset, .target = owned_target });
        // The call has consumed its argument registers; they are ordinary scratch
        // again for the result marshaling and the code that follows.
        self.pending_arg_regs = 0;
    }

    fn emitB(self: *Arm64Compiler, label: u32) Error!u32 {
        const offset: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x14000000, "b .Lduo_{d}", .{label});
        return offset;
    }

    fn emitBCond(self: *Arm64Compiler, cond: Condition, label: u32) Error!u32 {
        const offset: u32 = @intCast(self.code.items.len);
        try self.emitFmt(0x54000000 | @as(u32, @intFromEnum(cond)), "b.{s} .Lduo_{d}", .{ conditionName(cond), label });
        return offset;
    }

    fn saveSetContains(save: SaveSet, reg: u5) bool {
        var i: u5 = 0;
        while (i < save.count) : (i += 1) {
            if (save.regs[i] == reg) return true;
        }
        return false;
    }

    fn resultRegFree(self: *const Arm64Compiler, save: ?SaveSet, reg: u5) bool {
        if (save) |s| {
            if (saveSetContains(s, reg)) return false;
        }
        if (self.spilled_regs.contains(reg)) return false;
        return !self.used_regs[reg];
    }

    /// A GP register `emitRestoreCallerRegs` will not reload: a return value
    /// parked in a register that was live at save time is overwritten by
    /// restore even when the mov ran after `bl`. x8 and x18 are not candidates
    /// and are not scanned.
    ///
    /// ONE PRODUCER, READ TWICE. `save` is null before the save window opens,
    /// where the set that window will contain is exactly the `used_regs`
    /// registers and nothing between the two points claims or releases one, so
    /// the null answer here is the answer `allocRegOutsideSaveSet` gives after
    /// it. That is what the frame park's reservation is decided from.
    fn resultReg(self: *const Arm64Compiler, save: ?SaveSet) ?u5 {
        var reg: u5 = 9;
        while (reg < 29) : (reg += 1) {
            if (reg == platform_reserved_reg) continue;
            if (self.resultRegFree(save, reg)) return reg;
        }
        return null;
    }

    fn allocRegOutsideSaveSet(self: *Arm64Compiler, save: SaveSet) Error!u5 {
        const reg = self.resultReg(save) orelse return error.RegisterExhausted;
        self.claimReg(reg);
        self.protectReg(reg);
        return reg;
    }

    /// The park's reservation, read before the save window opens: sixteen bytes
    /// exactly when the answer will have no register to go to, and nothing
    /// otherwise.
    fn parkReserve(self: *const Arm64Compiler, wants_result: bool) u16 {
        if (!wants_result) return 0;
        return if (self.resultReg(null) == null) 16 else 0;
    }

    /// WHERE THE CALL'S ANSWER LIVES, assigned once before the call is emitted.
    ///
    /// `base` is `sp_temp_bytes` at the instant the slot became this
    /// function's, so `parkDisp` recovers the slot's `[sp,#imm]` from wherever
    /// `sp` is standing rather than from what any one window happens to be.
    const Park = struct {
        bytes: u16 = 0,
        base: u16 = 0,
    };

    fn parkOpen(self: *Arm64Compiler, wants_result: bool) Error!Park {
        return self.parkOpenBytes(self.parkReserve(wants_result));
    }

    /// The pack answer's reservation: one eight-byte slot per returned member,
    /// on the sixteen-byte grid `emitSubSp` encodes.
    fn parkReserveSlots(slots: usize) Error!u16 {
        const bytes = std.mem.alignForward(usize, slots * 8, 16);
        if (bytes > 65535) return error.RegisterExhausted;
        return @intCast(bytes);
    }

    fn parkOpenSlots(self: *Arm64Compiler, slots: usize) Error!Park {
        return self.parkOpenBytes(try parkReserveSlots(slots));
    }

    fn parkOpenBytes(self: *Arm64Compiler, bytes: u16) Error!Park {
        if (bytes == 0) return .{};
        try self.emitSubSpTemp(bytes);
        return .{ .bytes = bytes, .base = self.sp_temp_bytes };
    }

    /// The sole reader of a `Park`: `frameDisp` for the one value location the
    /// frame does not name. An unreserved park has no byte of this function's
    /// to read, and `sp` below `base` means the slot's window is gone.
    fn parkDisp(self: *Arm64Compiler, park: Park) Error!u16 {
        if (park.bytes == 0) return error.RegisterExhausted;
        if (self.sp_temp_bytes < park.base) return self.refuse(@src());
        return self.sp_temp_bytes - park.base;
    }

    /// The `[sp,#imm]` of the park's slot `index`, measured like `parkDisp`
    /// from wherever `sp` stands. A slot past the reservation is not a byte
    /// this park was assigned, and answers with the capacity error rather than
    /// an encodable displacement into someone else's window.
    fn parkSlotDisp(self: *Arm64Compiler, park: Park, index: usize) Error!u16 {
        const off = index * 8;
        if (off + 8 > park.bytes) return error.RegisterExhausted;
        const disp: usize = @as(usize, try self.parkDisp(park)) + off;
        if (disp > 65535) return error.RegisterExhausted;
        return @intCast(disp);
    }

    /// Store the call's answer in the slot `parkOpen` assigned it.
    fn parkCallResult(self: *Arm64Compiler, park: Park) Error!void {
        try self.emitStrSp(0, try self.parkDisp(park));
    }

    /// Close the park's own window and no other. `emitAddSpTemp` governs the
    /// WIDTH of a close; this governs its ORDER, because a close taken while a
    /// later window is still open leaves `sp` inside the park and every
    /// `frameDisp` after it wrong by that window.
    fn parkClose(self: *Arm64Compiler, park: Park) Error!void {
        if (park.bytes == 0) return;
        if (self.sp_temp_bytes != park.base) return self.refuse(@src());
        try self.emitAddSpTemp(park.bytes);
    }

    fn emitSaveCallerRegs(self: *Arm64Compiler) Error!SaveSet {
        var save_set = SaveSet{};
        var reg: u5 = 0;
        while (reg < 8) : (reg += 1) {
            // A staged argument register still joins the save set. The operand
            // can already occupy the ABI slot (so no copy is made), and when
            // that operand stays live past the call the slot holds its only
            // copy: excluding it from the save loses the value across the
            // call. A dead staged copy costs one save/restore pair; a lost
            // live value is a miscompile.
            if (self.used_regs[reg]) {
                save_set.regs[save_set.count] = reg;
                save_set.count += 1;
            }
        }
        reg = 9;
        while (reg <= 18) : (reg += 1) {
            if (self.used_regs[reg]) {
                save_set.regs[save_set.count] = reg;
                save_set.count += 1;
            }
        }
        // x19-x28 are callee-saved (AAPCS64): the callee preserves them, so
        // the caller never spills them around a call. Homes live there.
        var fpr: u5 = fp_value_reg_base;
        while (fpr < fp_value_reg_base + fp_value_reg_count) : (fpr += 1) {
            if (self.used_fp_regs[fpr]) {
                save_set.fp_regs[save_set.fp_count] = fpr;
                save_set.fp_count += 1;
            }
        }
        var slots: u16 = @as(u16, save_set.count) + 1 + @as(u16, save_set.fp_count);
        if ((slots % 2) != 0) slots += 1;
        save_set.stack_bytes = slots * 8;
        try self.emitSubSpTemp(save_set.stack_bytes);
        var offset: u16 = 0;
        var i: u5 = 0;
        while (i < save_set.count) : ({
            i += 1;
            offset += 8;
        }) {
            try self.emitStrSp(save_set.regs[i], offset);
        }
        try self.emitStrSp(30, @as(u16, save_set.count) * 8);
        // FP block sits after the GP block and x30.
        var fo: u16 = (@as(u16, save_set.count) + 1) * 8;
        var j: u5 = 0;
        while (j < save_set.fp_count) : ({
            j += 1;
            fo += 8;
        }) {
            try self.emitStrSpFp(save_set.fp_regs[j], fo);
        }
        return save_set;
    }

    /// Lay the staged variadic tail out at [sp, #0], [sp, #8], … and return the
    /// number of bytes sp moved by. Emitted AFTER `emitSaveCallerRegs`, so the
    /// callee's memory-argument area starts exactly at sp — which is what
    /// `va_arg` reads on Apple ARM64 — while the save area sits above it and
    /// stays addressable at its original offsets once sp is restored.
    fn restorePreservedX0(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        t: u32,
    ) Error!void {
        const reg = try self.allocReg();
        try self.emitLdrSp(reg, 0);
        try temps.put(self.alloc, t, reg);
        if (reg >= 9 and reg < 29 and reg != platform_reserved_reg and !self.gp_home_regs[reg]) {
            self.gp_reg_owner[reg] = t;
        }
    }

    fn materializePendingVarargs(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
    ) Error!void {
        var i: u5 = 0;
        while (i < self.pending_vararg_count) : (i += 1) {
            var slot = &self.pending_varargs[i];
            const v = slot.operand orelse continue;
            var reg = try self.evalDnirValueBits(temps, v);
            // A STACK-homed local is read by loadGpStackLocal into a FRESH register
            // that no map owns, so treating it as owned leaks one register per
            // stack argument per call — the pool drains and the body refuses with
            // DNB003 even though nothing is genuinely live. Same rule releaseDnirTemp
            // already applies on the register-argument path.
            const owned = switch (v) {
                .temp => true,
                .local => |home| !self.gp_stack_locals.contains(home),
                else => false,
            };
            var relocated = false;
            if (reg < 8) {
                const fresh = try self.allocReg();
                try self.emitMovReg(fresh, reg);
                if (!owned and !Arm64Compiler.regIsPinned(pinned, reg)) self.releaseReg(reg);
                reg = fresh;
                relocated = true;
            }
            slot.reg = reg;
            slot.operand = null;
            slot.scratch = relocated or (!owned and !Arm64Compiler.regIsPinned(pinned, reg));
            // From here to `emitPushVarargs` this register is the marshaling's,
            // exactly as `markStagedArgReg` says x_k is for a named argument.
            // The remaining slots of this same loop allocate underneath it.
            slot.staged = true;
        }
    }

    fn emitPushVarargs(self: *Arm64Compiler) Error!u16 {
        if (self.pending_vararg_count == 0) return 0;
        var bytes: u16 = @as(u16, self.pending_vararg_count) * 8;
        if ((bytes % 16) != 0) bytes += 8;
        try self.emitSubSpTemp(bytes);
        var i: u5 = 0;
        while (i < self.pending_vararg_count) : (i += 1) {
            const slot = self.pending_varargs[i];
            if (slot.operand != null) return self.refuse(@src());
            try self.emitStrSp(slot.reg, @as(u16, i) * 8);
        }
        return bytes;
    }

    /// Undo `emitPushVarargs` and clear the staging list. Registers allocated
    /// solely to carry a tail argument go back to the pool here; a `.temp` or
    /// `.local` register belongs to the slot map and is left alone.
    fn emitPopVarargs(self: *Arm64Compiler, bytes: u16) Error!void {
        if (bytes > 0) try self.emitAddSpTemp(bytes);
        var i: u5 = 0;
        while (i < self.pending_vararg_count) : (i += 1) {
            if (self.pending_varargs[i].scratch) self.releaseReg(self.pending_varargs[i].reg);
            self.pending_varargs[i] = .{};
        }
        self.pending_vararg_count = 0;
    }

    fn emitRestoreCallerRegs(self: *Arm64Compiler, save_set: SaveSet) Error!void {
        var offset: u16 = 0;
        var i: u5 = 0;
        while (i < save_set.count) : ({
            i += 1;
            offset += 8;
        }) {
            try self.emitLdrSp(save_set.regs[i], offset);
        }
        try self.emitLdrSp(30, @as(u16, save_set.count) * 8);
        var fo: u16 = (@as(u16, save_set.count) + 1) * 8;
        var j: u5 = 0;
        while (j < save_set.fp_count) : ({
            j += 1;
            fo += 8;
        }) {
            try self.emitLdrSpFp(save_set.fp_regs[j], fo);
        }
        try self.emitAddSpTemp(save_set.stack_bytes);
    }

    /// Largest 16-byte-aligned `sub/add sp` immediate on AArch64 (imm12 max 4095).
    const sp_imm_max: u16 = 4080;

    /// `sp` is the base every frame and window displacement is measured from,
    /// and AAPCS64 requires it sixteen-aligned at every instruction that uses
    /// it. `sp_imm_max` is a multiple of sixteen so each chunk keeps the grid.
    fn emitSubSp(self: *Arm64Compiler, bytes: u16) Error!void {
        if (bytes % 16 != 0) return self.refuse(@src());
        var rem: u32 = bytes;
        while (rem > 0) {
            const chunk: u16 = if (rem > sp_imm_max) sp_imm_max else @intCast(rem);
            try self.emitFmt(0xd10003ff | (@as(u32, chunk) << 10), "sub sp, sp, #{d}", .{chunk});
            rem -= chunk;
        }
    }

    fn emitAddSp(self: *Arm64Compiler, bytes: u16) Error!void {
        if (bytes % 16 != 0) return self.refuse(@src());
        var rem: u32 = bytes;
        while (rem > 0) {
            const chunk: u16 = if (rem > sp_imm_max) sp_imm_max else @intCast(rem);
            try self.emitFmt(0x910003ff | (@as(u32, chunk) << 10), "add sp, sp, #{d}", .{chunk});
            rem -= chunk;
        }
    }

    /// `sp` moves for a window that closes before the frame does; `frameGrow`
    /// is the other kind and moves the frame base with it.
    fn emitSubSpTemp(self: *Arm64Compiler, bytes: u16) Error!void {
        try self.emitSubSp(bytes);
        self.sp_temp_bytes += bytes;
    }

    fn emitAddSpTemp(self: *Arm64Compiler, bytes: u16) Error!void {
        if (bytes > self.sp_temp_bytes) return self.refuse(@src());
        try self.emitAddSp(bytes);
        self.sp_temp_bytes -= bytes;
    }

    /// Frame residents named from the BOTTOM — a distance UP from `sp` — so a
    /// move of `sp` renames every one of them. `frameSlotOff`'s spill
    /// coordinate counts down from the top instead and rides growth unchanged;
    /// these do not, and only their owner knows the rebase.
    fn frameResidents(self: *const Arm64Compiler) usize {
        return self.gp_stack_locals.count() +
            self.slot_bases.count() +
            self.fp_stack_slots.count();
    }

    fn frameGrow(self: *Arm64Compiler, bytes: u16) Error!void {
        if (self.sp_temp_bytes != 0) return self.refuse(@src());
        if (self.frame_sealed and self.frameResidents() > 0) return self.refuse(@src());
        try self.emitSubSp(bytes);
        self.stack_frame_bytes += bytes;
    }

    /// The frame-base offset of the spill slot `off` names; `off` counts down
    /// from the top of the frame, per `gateSpillBand`.
    fn frameSlotOff(self: *const Arm64Compiler, off: u16) Error!u16 {
        if (@as(u32, off) + 8 > @as(u32, self.stack_frame_bytes)) return error.RegisterExhausted;
        return self.stack_frame_bytes - off - 8;
    }

    /// The sole reader of `sp_temp_bytes` for a FRAME coordinate: a frame-base
    /// offset as a `[sp,#imm]` displacement from wherever `sp` is standing now.
    /// `parkDisp` is the counterpart for the one value location the frame does
    /// not name.
    fn frameDisp(self: *const Arm64Compiler, frame_off: u16) Error!u16 {
        const disp: u32 = @as(u32, frame_off) + @as(u32, self.sp_temp_bytes);
        if (disp > 65535) return error.RegisterExhausted;
        return @intCast(disp);
    }

    /// `emitStrSp`/`emitLdrSp` place `disp / 8` in a 12-bit unsigned field, so
    /// 32760 is the last addressable byte and above it a displacement wraps into
    /// a different slot; refuse instead.
    fn frameScaledDisp(self: *const Arm64Compiler, frame_off: u16) Error!u16 {
        const disp = try self.frameDisp(frame_off);
        if (disp > 32760) return error.RegisterExhausted;
        return disp;
    }

    fn emitStrFrame(self: *Arm64Compiler, reg: u5, frame_off: u16) Error!void {
        try self.emitStrSp(reg, try self.frameScaledDisp(frame_off));
    }

    fn emitLdrFrame(self: *Arm64Compiler, reg: u5, frame_off: u16) Error!void {
        try self.emitLdrSp(reg, try self.frameScaledDisp(frame_off));
    }

    fn emitStrFrameFp(self: *Arm64Compiler, dreg: u5, frame_off: u16) Error!void {
        try self.emitStrSpFp(dreg, try self.frameScaledDisp(frame_off));
    }

    fn emitLdrFrameFp(self: *Arm64Compiler, dreg: u5, frame_off: u16) Error!void {
        try self.emitLdrSpFp(dreg, try self.frameScaledDisp(frame_off));
    }

    /// `add` chains past its imm12, so this carries no scaled-encoding limit.
    fn emitAddFrameImm(self: *Arm64Compiler, dst: u5, frame_off: u16) Error!void {
        try self.emitAddSpImm(dst, try self.frameDisp(frame_off));
    }

    /// The scaled `[sp,#imm]` field carries `offset / 8`. A displacement with a
    /// low bit set addressed `offset & ~7` in the OBJECT while `asm_text`
    /// printed `offset`, and one past 32760 left the field for the base
    /// register. Both were held by construction at ten producers and asked at
    /// none of them.
    fn spScaledDisp(self: *Arm64Compiler, offset: u16) Error!u32 {
        if (offset % 8 != 0) return self.refuse(@src());
        if (offset > 32760) return self.refuse(@src());
        return @as(u32, offset) / 8;
    }

    fn emitStrSp(self: *Arm64Compiler, reg: u5, offset: u16) Error!void {
        const imm = try self.spScaledDisp(offset);
        try self.emitFmt(0xf90003e0 | (imm << 10) | @as(u32, reg), "str x{d}, [sp, #{d}]", .{ reg, offset });
    }

    fn emitLdrSp(self: *Arm64Compiler, reg: u5, offset: u16) Error!void {
        const imm = try self.spScaledDisp(offset);
        try self.emitFmt(0xf94003e0 | (imm << 10) | @as(u32, reg), "ldr x{d}, [sp, #{d}]", .{ reg, offset });
    }

    /// Release `reg` only if it was scratch for this instruction. A `.temp` or a
    /// register-homed `.local` operand's register is owned by the slot map and
    /// outlives us. A STACK `.local`, however, is reloaded into a fresh scratch
    /// register by `loadGpStackLocal` on every read — that copy is owned by no
    /// map and the liveness sweep (which only frees OWNED registers) can never
    /// reclaim it. Freeing it here is the operand's only exit: staging a stack
    /// local into an argument slot otherwise orphans one register per argument
    /// until the pool is exhausted (surfaced as DNB003 in a call-dense body like
    /// `dorec4` once the mov_arg ownership-rebind that used to mask it was
    /// removed).
    fn releaseDnirTemp(
        self: *Arm64Compiler,
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        v: dnir.Value,
        reg: u5,
    ) void {
        switch (v) {
            .temp => return,
            .local => |slot| if (!self.gp_stack_locals.contains(slot)) return,
            else => {},
        }
        if (Arm64Compiler.regIsPinned(pinned, reg)) return;
        self.releaseReg(reg);
    }

    /// `str xs, [xbase, #imm]` — 8-byte store at a constant offset from an
    /// arbitrary base. `emitStrSp` is the same encoding pinned to x31/sp; the
    /// indirect-result buffer lives at a pointer the caller chose, so the base
    /// has to be a register.
    fn emitStrBaseImm(self: *Arm64Compiler, src: u5, base: u5, offset: u16) Error!void {
        if (offset % 8 != 0 or offset / 8 > 4095) return self.refuse(@src());
        try self.ensureRegLive(base);
        try self.ensureRegLive(src);
        try self.emitFmt(
            0xf9000000 | ((@as(u32, offset) / 8) << 10) | (@as(u32, base) << 5) | @as(u32, src),
            "str x{d}, [x{d}, #{d}]",
            .{ src, base, offset },
        );
    }

    fn emitStrBaseImmFp(self: *Arm64Compiler, dreg: u5, base: u5, offset: u16) Error!void {
        if (offset % 8 != 0 or offset / 8 > 4095) return self.refuse(@src());
        try self.ensureRegLive(base);
        try self.emitFmt(
            0xfd000000 | ((@as(u32, offset) / 8) << 10) | (@as(u32, base) << 5) | @as(u32, dreg),
            "str d{d}, [x{d}, #{d}]",
            .{ dreg, base, offset },
        );
    }

    /// `ldr xd, [xbase, #imm]` — the read half of `emitStrBaseImm`, same
    /// unsigned-offset form. Used when a table subscript's index is known at
    /// compile time: `base + (k - 1) * 8` is then a constant and needs no
    /// register, no `mov` and no `sub`.
    fn emitLdrBaseImm(self: *Arm64Compiler, dst: u5, base: u5, offset: u16) Error!void {
        if (offset % 8 != 0 or offset / 8 > 4095) return self.refuse(@src());
        try self.ensureRegLive(base);
        try self.emitFmt(
            0xf9400000 | ((@as(u32, offset) / 8) << 10) | (@as(u32, base) << 5) | @as(u32, dst),
            "ldr x{d}, [x{d}, #{d}]",
            .{ dst, base, offset },
        );
    }

    /// `ldr dd, [xbase, xidx, lsl #3]` — 8-byte scaled indexed load into FP register.
    fn emitLdrScaledFp(self: *Arm64Compiler, dst: u5, base: u5, idx: u5) Error!void {
        try self.ensureRegLive(base);
        try self.ensureRegLive(idx);
        try self.emitFmt(
            0xf8607800 | ((@as(u32, idx) << 16)) | ((@as(u32, base) << 5)) | @as(u32, dst),
            "ldr d{d}, [x{d}, x{d}, lsl #3]",
            .{ dst, base, idx },
        );
    }

    /// `str ds, [xbase, xidx, lsl #3]` — 8-byte scaled indexed store from FP register.
    fn emitStrScaledFp(self: *Arm64Compiler, src: u5, base: u5, idx: u5) Error!void {
        try self.ensureRegLive(base);
        try self.ensureRegLive(idx);
        try self.ensureRegLive(src);
        try self.emitFmt(
            0xf8207800 | ((@as(u32, idx) << 16)) | ((@as(u32, base) << 5)) | @as(u32, src),
            "str d{d}, [x{d}, x{d}, lsl #3]",
            .{ src, base, idx },
        );
    }

    /// `ldr dd, [xbase, #imm]` — 8-byte load into FP register at a constant offset.
    fn emitLdrBaseImmFp(self: *Arm64Compiler, dst: u5, base: u5, offset: u16) Error!void {
        if (offset % 8 != 0 or offset / 8 > 4095) return self.refuse(@src());
        try self.ensureRegLive(base);
        try self.emitFmt(
            0xfd400000 | ((@as(u32, offset) / 8) << 10) | ((@as(u32, base) << 5)) | @as(u32, dst),
            "ldr d{d}, [x{d}, #{d}]",
            .{ dst, base, offset },
        );
    }

    /// Every field value of a `ret_record`, in descriptor order.
    ///
    /// `vals` is authoritative when the lowerer set it. The `lhs`/`rhs`/`third`
    /// fallback exists for DNIR built by hand in tests, and stops at three for
    /// the same reason it always did — there is no fourth inline slot.
    fn dnirRetRecordVals(self: *Arm64Compiler, ins: dnir.Instr) Error![]const dnir.Value {
        if (ins.vals.len > 0) return ins.vals;
        var n: usize = 0;
        self.ret_record_scratch[0] = ins.lhs;
        n = 1;
        if (ins.rhs != .void) {
            self.ret_record_scratch[1] = ins.rhs;
            n = 2;
        }
        if (ins.third != .void) {
            self.ret_record_scratch[2] = ins.third;
            n = 3;
        }
        return self.ret_record_scratch[0..n];
    }

    /// The frame offset of the buffer this call must fill through x8, or null
    /// when the call returns in registers (or returns no record at all).
    fn indirectResultBuffer(self: *Arm64Compiler, ins: dnir.Instr) Error!?u16 {
        if (ins.record.len == 0) return null;
        const rec = scalRecordDesc(self.scal_records, ins.record) orelse return null;
        // Caller side, and the same `foreign = false` obligation recorded at the
        // `call_direct` result copy above: the call does not carry the callee's
        // boundary fact, and no Idol caller can receive a record today.
        if (!scalRecordReturnsIndirect(rec, false)) return null;
        const base = if (ins.field.len > 0) ins.field else "rec";
        const key = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ base, rec.field_names[0] });
        defer self.alloc.free(key);
        // The prologue pre-pass reserves one region per record base. If it did
        // not, there is no buffer to point x8 at and the callee would write
        // through whatever x8 held on entry — refuse rather than emit that.
        const slot = self.fp_stack_slots.get(key) orelse return self.refuse(@src());
        return slot.off;
    }

    /// `add xd, sp, #imm` — materialize the address of a frame slot region.
    ///
    /// `add` immediates are 12 bits, and a frame can be deeper than 4095 bytes,
    /// so a displacement past that is CHAINED rather than refused. It has to be:
    /// the slot region now sits above the GP local/spill region (see the rebase
    /// in the prologue), which pushes ordinary table bases past 4095 in any
    /// function that both builds a table and spills. Refusing there would turn
    /// working programs into fallbacks purely as a side effect of the rebase.
    /// No scratch register is used — each step adds into `dst` itself.
    fn emitAddSpImm(self: *Arm64Compiler, dst: u5, bytes: u16) Error!void {
        const first: u16 = @min(bytes, 4095);
        try self.emitFmt(
            0x910003e0 | (@as(u32, first) << 10) | @as(u32, dst),
            "add x{d}, sp, #{d}",
            .{ dst, first },
        );
        var rest: u16 = bytes - first;
        while (rest > 0) {
            const step: u16 = @min(rest, 4095);
            try self.emitFmt(
                0x91000000 | (@as(u32, step) << 10) | (@as(u32, dst) << 5) | @as(u32, dst),
                "add x{d}, x{d}, #{d}",
                .{ dst, dst, step },
            );
            rest -= step;
        }
    }

    /// `ldr xd, [xbase, xidx, lsl #3]` — 8-byte scaled indexed load.
    fn emitLdrScaled(self: *Arm64Compiler, dst: u5, base: u5, idx: u5) Error!void {
        try self.ensureRegLive(base);
        try self.ensureRegLive(idx);
        try self.emitFmt(
            0xf8607800 | (@as(u32, idx) << 16) | (@as(u32, base) << 5) | @as(u32, dst),
            "ldr x{d}, [x{d}, x{d}, lsl #3]",
            .{ dst, base, idx },
        );
    }

    // -----------------------------------------------------------------------
    // NEON. The first vector instructions this backend has ever emitted.
    //
    // Every word below was checked against the system assembler rather than
    // read off a table, because the failure mode is silent: a wrong lane size
    // still assembles, still runs, and answers with the wrong number. The
    // reference assembly and its bytes:
    //
    //     eor.16b  v16, v16, v16      6e301e10
    //     ldr      q17, [x9], #0x10   3cc10531
    //     add.2d   v16, v16, v17      4ef18610
    //     addp.2d  d16, v16           5ef1ba10
    //     fmov     x9, d16            9e660209
    //     subs     x9, x9, #0x1       f1000529
    //
    // Note the arm64 spelling: the LANE SUFFIX IS ON THE MNEMONIC, not on the
    // operands. `docs/hardware-baseline.md` records two probes that reported a
    // clean zero for densely vectorized code because they searched for
    // `v0\.4s`. The listing strings here are written the way the disassembler
    // prints them so the two agree.
    // -----------------------------------------------------------------------

    /// `eor.16b vd, vd, vd` — zero a whole 128-bit register.
    fn emitVecZero(self: *Arm64Compiler, v: u5) Error!void {
        try self.emitFmt(
            0x6e201c00 | (@as(u32, v) << 16) | (@as(u32, v) << 5) | @as(u32, v),
            "eor.16b v{d}, v{d}, v{d}",
            .{ v, v, v },
        );
    }

    /// `ldr qt, [xn], #16` — load two i64 lanes and post-increment the pointer.
    fn emitVecLdrQPost16(self: *Arm64Compiler, t: u5, n: u5) Error!void {
        try self.ensureRegLive(n);
        // imm9 = 16, then the `01` post-index selector in bits 11:10.
        try self.emitFmt(
            0x3cc00400 | (@as(u32, 16) << 12) | (@as(u32, n) << 5) | @as(u32, t),
            "ldr q{d}, [x{d}], #16",
            .{ t, n },
        );
    }

    /// `add.2d vd, vn, vm` — two lanes of 64-bit integer addition. Wraps exactly
    /// as the scalar `add` does, which is what makes regrouping a reduction
    /// exact rather than approximate.
    fn emitVecAdd2d(self: *Arm64Compiler, d: u5, n: u5, m: u5) Error!void {
        try self.emitFmt(
            0x4ee08400 | (@as(u32, m) << 16) | (@as(u32, n) << 5) | @as(u32, d),
            "add.2d v{d}, v{d}, v{d}",
            .{ d, n, m },
        );
    }

    /// `addp.2d dd, vn` — horizontal add of the two lanes into the low double.
    fn emitVecAddp2d(self: *Arm64Compiler, d: u5, n: u5) Error!void {
        try self.emitFmt(
            0x5ef1b800 | (@as(u32, n) << 5) | @as(u32, d),
            "addp.2d d{d}, v{d}",
            .{ d, n },
        );
    }

    /// `fmov xd, dn` — move lane 0 into a general-purpose register.
    fn emitFmovGpFromFp(self: *Arm64Compiler, d: u5, n: u5) Error!void {
        try self.emitFmt(
            0x9e660000 | (@as(u32, n) << 5) | @as(u32, d),
            "fmov x{d}, d{d}",
            .{ d, n },
        );
    }

    /// `subs xd, xn, #imm` — decrement and set flags, so the loop latch needs no
    /// separate compare and no immediate staged in a register per iteration.
    fn emitSubsReg(self: *Arm64Compiler, d: u5, n: u5, m: u5) Error!void {
        try self.ensureRegLive(n);
        try self.ensureRegLive(m);
        try self.emitFmt(
            0xeb000000 | (@as(u32, m) << 16) | (@as(u32, n) << 5) | @as(u32, d),
            "subs x{d}, x{d}, x{d}",
            .{ d, n, m },
        );
    }

    fn emitCsneg(self: *Arm64Compiler, d: u5, n: u5, m: u5, cond: u4) Error!void {
        try self.ensureRegLive(n);
        try self.ensureRegLive(m);
        try self.emitFmt(
            0xda800400 | (@as(u32, m) << 16) | (@as(u32, cond) << 12) | (@as(u32, n) << 5) | @as(u32, d),
            "csneg x{d}, x{d}, x{d}",
            .{ d, n, m },
        );
    }

    fn emitSubsImm(self: *Arm64Compiler, d: u5, n: u5, imm: u12) Error!void {
        try self.ensureRegLive(n);
        try self.emitFmt(
            0xf1000000 | (@as(u32, imm) << 10) | (@as(u32, n) << 5) | @as(u32, d),
            "subs x{d}, x{d}, #{d}",
            .{ d, n, imm },
        );
    }

    /// The expansion of `dnir_lower.vec_reduce_add_i64_tag`: sum `count`
    /// consecutive i64 words starting at 1-based element `lo` of the table whose
    /// base is `ins.lhs`, and leave the total in `ins.result`.
    ///
    /// `count` is an exact multiple of the lane width and `lo`/`count` were
    /// proven inside the table's extent by the recognizer, so there is no
    /// prologue, no epilogue and no in-loop guard here — the odd element, if
    /// there is one, is handled by the ordinary scalar loop that follows this
    /// instruction. The conditions are re-checked anyway: this is the only place
    /// that knows the load width, and a malformed operand must refuse rather
    /// than read past the region.
    ///
    /// The vector registers come from `allocFpReg`, i.e. the SAME pool the f64
    /// path uses. `d16` and `v16` are one physical register, so allocating from
    /// anywhere else would be the mixed-representation bug in another form.
    /// They are freed here because their whole lifetime is this expansion — no
    /// slot ever names one.
    fn emitVecReduceAddI64(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
    ) Error!void {
        const lo: i64 = switch (ins.rhs) {
            .i64 => |v| v,
            else => return self.refuse(@src()),
        };
        const count: i64 = switch (ins.third) {
            .i64 => |v| v,
            else => return self.refuse(@src()),
        };
        if (lo < 1 or count < 2 or @rem(count, 2) != 0) return self.refuse(@src());
        const byte_off: i64 = (lo - 1) * 8;
        if (byte_off > 0xffff) return self.refuse(@src());

        const base = try self.evalDnirValue(temps, ins.lhs);
        try self.ensureRegLive(base);

        const cursor = try self.allocReg();
        const pairs = try self.allocReg();
        if (byte_off == 0) {
            try self.emitMovReg(cursor, base);
        } else {
            try self.emitMovImm(cursor, byte_off);
            try self.emitAddReg(cursor, base, cursor);
        }
        try self.emitMovImm(pairs, @divTrunc(count, 2));

        const acc_v = try self.allocFpReg();
        const dat_v = try self.allocFpReg();
        try self.emitVecZero(acc_v);

        const loop_off: u32 = @intCast(self.code.items.len);
        try self.emitVecLdrQPost16(dat_v, cursor);
        try self.emitVecAdd2d(acc_v, acc_v, dat_v);
        try self.emitSubsImm(pairs, pairs, 1);
        const latch = try self.emitBCond(.ne, 0);
        try self.patchCondBranch(latch, loop_off);

        try self.emitVecAddp2d(acc_v, acc_v);
        self.used_fp_regs[dat_v] = false;

        // Retire the cursor and the trip counter BEFORE claiming the result
        // register. Both are dead once the loop has fallen through, and holding
        // them across the allocation raises this instruction's peak GP demand by
        // two for no reason — which in a register-tight function is the
        // difference between compiling and a DNB003 refusal that the scalar
        // lowering of the same loop would not have hit.
        self.releaseReg(cursor);
        self.releaseReg(pairs);

        const dst = try self.allocReg();
        try self.emitFmovGpFromFp(dst, acc_v);
        self.used_fp_regs[acc_v] = false;
        self.releaseDnirTemp(pinned, ins.lhs, base);
        if (ins.result) |t| try temps.put(self.alloc, t, dst);
    }

    /// `str xs, [xbase, xidx, lsl #3]` — 8-byte scaled indexed store.
    fn emitStrScaled(self: *Arm64Compiler, src: u5, base: u5, idx: u5) Error!void {
        try self.ensureRegLive(base);
        try self.ensureRegLive(idx);
        try self.ensureRegLive(src);
        try self.emitFmt(
            0xf8207800 | (@as(u32, idx) << 16) | (@as(u32, base) << 5) | @as(u32, src),
            "str x{d}, [x{d}, x{d}, lsl #3]",
            .{ src, base, idx },
        );
    }

    /// STRB, immediate, unsigned offset — the write half of the pair emitLdrb
    /// has had all along. Same addressing form: 0x39000000 against LDRB's
    /// 0x39400000.
    fn emitStrb(self: *Arm64Compiler, src: u5, base: u5) Error!void {
        try self.ensureRegLive(base);
        try self.ensureRegLive(src);
        try self.emitFmt(0x39000000 | (@as(u32, base) << 5) | @as(u32, src), "strb w{d}, [x{d}]", .{ src, base });
    }

    fn emitLdrb(self: *Arm64Compiler, dst: u5, base: u5) Error!void {
        try self.ensureRegLive(base);
        try self.emitFmt(0x39400000 | (@as(u32, base) << 5) | @as(u32, dst), "ldrb x{d}, [x{d}]", .{ dst, base });
    }

    /// Bitwise and shift, register forms. Same field layout as add/sub:
    /// opcode | (Rm << 16) | (Rn << 5) | Rd.
    fn emitBitReg(self: *Arm64Compiler, op: u32, mnemonic: []const u8, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(op | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "{s} x{d}, x{d}, x{d}", .{ mnemonic, dst, lhs, rhs });
    }

    fn emitAddReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x8b000000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "add x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    fn emitSubReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0xcb000000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "sub x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    /// `neg xd, xn` — the assembler alias for `sub xd, xzr, xn`, base word
    /// 0xCB000000 with Rn = 31 (xzr). The sign flip for a negative constant
    /// divisor: trunc(n/-k) = -trunc(n/k), exact because |trunc(n/k)| < 2^63.
    fn emitNegReg(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        try self.emitSubReg(dst, 31, src);
    }

    /// `add xd, xn, xm, lsl #sh` — Z3-verified shift-add for constant multiply.
    /// Proof: research/wsuperopt/proofs/mul_const_*.
    fn emitAddLslReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x8b000000 | (@as(u32, sh) << 10) | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "add x{d}, x{d}, x{d}, lsl #{d}", .{ dst, lhs, rhs, sh });
    }
    /// `add xd, xn, xm, lsr #sh` -- the lsr twin of `emitAddLslReg`, for the
    /// signed-divide-by-pow2 bias fusion. Encoding verified byte-identical
    /// against clang 21 `add x8, x0, x0, lsr #63` (0x8b40fc08).
    fn emitAddLsrReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x8b000000 | (@as(u32, 1) << 22) | (@as(u32, sh) << 10) | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "add x{d}, x{d}, x{d}, lsr #{d}", .{ dst, lhs, rhs, sh });
    }

    /// `sub xd, xn, xm, lsl #sh` — Z3-verified for x * -7.
    /// Proof: research/wsuperopt/proofs/mul_const_m7.
    fn emitSubLslReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, sh: u6) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0xcb000000 | (@as(u32, sh) << 10) | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "sub x{d}, x{d}, x{d}, lsl #{d}", .{ dst, lhs, rhs, sh });
    }

    /// `sub xd, xn, #imm12` — SUB immediate, 64-bit, no shift.
    ///
    /// The register form needs a second register holding the constant AND the
    /// `mov` that puts it there. Every 1-based table subscript pays that bias,
    /// so the pair was two instructions on the hottest path in the tree. This is
    /// one, and it frees the register the `mov` was consuming.
    fn emitSubImm(self: *Arm64Compiler, dst: u5, lhs: u5, imm: u12) Error!void {
        try self.emitSubImmSized(dst, lhs, imm, false);
    }

    /// `sub xd, xn, #imm12`, and its 32-bit twin — see `emitAddImmSized`.
    fn emitSubImmSized(self: *Arm64Compiler, dst: u5, lhs: u5, imm: u12, w32: bool) Error!void {
        try self.ensureRegLive(lhs);
        const base: u32 = if (w32) 0x51000000 else 0xd1000000;
        const r: u8 = if (w32) 'w' else 'x';
        try self.emitFmt(
            base | (@as(u32, imm) << 10) | (@as(u32, lhs) << 5) | @as(u32, dst),
            "sub {c}{d}, {c}{d}, #{d}",
            .{ r, dst, r, lhs, imm },
        );
    }

    fn emitCmpReg(self: *Arm64Compiler, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0xeb00001f | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5), "cmp x{d}, x{d}", .{ lhs, rhs });
    }

    fn emitCmpZero(self: *Arm64Compiler, reg: u5) Error!void {
        try self.ensureRegLive(reg);
        try self.emitFmt(0xf100001f | (@as(u32, reg) << 5), "cmp x{d}, #0", .{reg});
    }

    /// `cmp xn, #imm12` — SUBS xzr, xn, #imm, the same form `emitCmpZero`
    /// emits with a zero immediate.
    fn emitCmpImm(self: *Arm64Compiler, reg: u5, imm: u12) Error!void {
        try self.ensureRegLive(reg);
        try self.emitFmt(
            0xf100001f | (@as(u32, imm) << 10) | (@as(u32, reg) << 5),
            "cmp x{d}, #{d}",
            .{ reg, imm },
        );
    }

    /// `cmn xn, #imm12` is ADDS XZR, Xn, #imm: the add twin of `emitCmpImm`,
    /// same encoding with bit 29 set (`0xb100001f`), flags set from `xn+imm`.
    /// `cmn xd, #1` tests `xd == -1` with no materialized constant.
    fn emitCmnImm(self: *Arm64Compiler, reg: u5, imm: u12) Error!void {
        try self.ensureRegLive(reg);
        try self.emitFmt(
            0xb100001f | (@as(u32, imm) << 10) | (@as(u32, reg) << 5),
            "cmn x{d}, #{d}",
            .{ reg, imm },
        );
    }

    fn emitCompareResult(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, cond: Condition) Error!void {
        try self.emitCmpReg(lhs, rhs);
        try self.emitFmt(encodeCset(dst, cond), "cset x{d}, {s}", .{ dst, conditionName(cond) });
    }

    /// `csel xd, xn, xm, cond` — `xd = cond ? xn : xm`.
    ///
    /// Nothing between the `cmp` that set the flags and this instruction may
    /// write NZCV. `ensureRegLive` can only emit a reload (`ldr`), which does
    /// not, so calling it here is safe; an emitter that could touch the flags
    /// would not be.
    fn emitCselReg(self: *Arm64Compiler, dst: u5, n: u5, m: u5, cond: Condition) Error!void {
        try self.ensureRegLive(n);
        try self.ensureRegLive(m);
        try self.emitFmt(
            encodeCsel(dst, n, m, cond),
            "csel x{d}, x{d}, x{d}, {s}",
            .{ dst, n, m, conditionName(cond) },
        );
    }

    /// Peephole precondition for folding `binop(cmp) -> T ; br when_x T` into a
    /// single `cmp; b.cond`. The stock lowering materializes the boolean with
    /// `cset` and then the branch re-tests it with `cmp T, #0` — four
    /// instructions where two suffice. Fusing is admissible only when the
    /// comparison result is an integer boolean consumed by the immediately
    /// following conditional branch and by nothing else, so the materialized
    /// value has no other reader whose register the fold would erase.
    fn compareBranchFusible(self: *const Arm64Compiler, ins: dnir.Instr, nx: dnir.Instr, flat_idx: u32) bool {
        if (ins.op != .binop) return false;
        if (comparisonCondition(ins.binop) == null) return false;
        if (ins.ty == .f64) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        if (self.cur_func_float) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return false;
        const t = ins.result orelse return false;
        if (nx.op != .br) return false;
        switch (nx.branch_condition) {
            .when_true, .when_false => {},
            .unconditional => return false,
        }
        if (nx.lhs != .temp or nx.lhs.temp != t) return false;
        // The comparison result may have exactly one reader: this branch. A
        // widened live range (loop-crossing) or a second consumer leaves the
        // last-use index past the branch, and the conservative answer is to
        // keep the materialized boolean rather than erase a value still read.
        //
        // ASKED OF THE FUNCTION, not only of the index: the unroller reuses
        // value ids, so `value_free_at` reports copy four's read for copy one's
        // boolean and refuses three of every four fusible pairs. See
        // `computeTightReads`.
        return self.singleReaderByTightDef(t, flat_idx);
    }

    // ------------------------------------------------------------------
    // R15 — A NAMED CONDITION IS THE SAME CONDITION.
    //
    // `compareBranchFusible` above states its precondition as "consumed by the
    // IMMEDIATELY FOLLOWING conditional branch". That is a syntactic adjacency
    // standing in for the fact it means — SINGLE READER, NO INTERVENING EFFECT
    // — and the two come apart the moment the condition is given a name:
    //
    //     if a > b        ->  cmp ; b.le                    (2)
    //     c = a > b       ->  cmp ; cset ; str ; ldr ; cmp ; b.eq   (6)
    //     if c
    //
    // Measured on a 1e8-trip loop with identical answers: 1.26x instructions,
    // 1.35x cycles (`docs/optimization-space.md` R15). The defect shape is the
    // one this project has closed twice already — a fixed rule standing in for
    // a fact — and the fact is available exactly: the DNIR of the whole
    // function is in hand, so "read once, written once" can be COUNTED.
    // ------------------------------------------------------------------

    /// Reads of local slot `id` across the whole function, and `store_local`
    /// writes to it. Counted rather than inferred: the naming store may only be
    /// erased when this branch is the binding's ONLY reader.
    fn dnirLocalUseCensus(f: dnir.Function, id: u32, reads: *u32, writes: *u32, read_at: *u32, write_at: *u32) void {
        reads.* = 0;
        writes.* = 0;
        read_at.* = 0;
        write_at.* = 0;
        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (dnirInstrReadsValue(ins, true, id)) {
                    reads.* += 1;
                    read_at.* = idx;
                }
                if (ins.op == .store_local and ins.result != null and ins.result.? == id) {
                    writes.* += 1;
                    write_at.* = idx;
                }
                idx += 1;
            }
        }
    }

    /// Does any branch FROM OUTSIDE `[window_lo, window_hi]` land inside
    /// `[lo, hi]`?
    ///
    /// `dnirBranchLandsWithin` cannot answer this question for a two-sided
    /// window, and the difference is not a detail: the window's OWN conditional
    /// branch targets the else arm, which is inside the window by construction.
    /// Asking the one-sided question refuses every two-sided `if` there is.
    /// What actually has to hold is that no branch the fold does not erase
    /// lands on an index the fold collapses.
    fn dnirBranchIntoWindow(f: dnir.Function, lo: u32, hi: u32, window_lo: u32, window_hi: u32) bool {
        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                defer idx += 1;
                if (ins.op != .br) continue;
                if (idx >= window_lo and idx <= window_hi) continue;
                if (ins.branch_target >= lo and ins.branch_target <= hi) return true;
            }
        }
        return false;
    }

    /// The largest value id this function mentions, over every id-bearing
    /// field of every instruction. Locals and temps share one counter, so
    /// `max + 1` is a value id that names neither.
    fn maxDnirValueId(f: dnir.Function) u32 {
        var top: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.result) |r| top = @max(top, r);
                const fixed = [_]dnir.Value{ ins.lhs, ins.rhs, ins.third };
                for (fixed) |v| switch (v) {
                    .local, .temp => |slot| top = @max(top, slot),
                    else => {},
                };
                for (ins.vals) |v| switch (v) {
                    .local, .temp => |slot| top = @max(top, slot),
                    else => {},
                };
                for (ins.pack_results) |pr| {
                    if (pr.temp) |t| top = @max(top, t);
                }
            }
        }
        return top;
    }

    /// Does any branch in the function land strictly inside `[lo, hi]`? A fold
    /// that erases instructions must not erase a landing site: every consumed
    /// index collapses onto one code offset, so a branch INTO the window would
    /// arrive somewhere the window never meant.
    fn dnirBranchLandsWithin(f: dnir.Function, lo: u32, hi: u32) bool {
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op != .br) continue;
                if (ins.branch_target >= lo and ins.branch_target <= hi) return true;
            }
        }
        return false;
    }

    /// Precondition for folding `binop(cmp) -> T ; store_local L <- T ;
    /// br when_x L` into the same `cmp; b.cond` the unnamed form gets.
    ///
    /// Admissible only when, over the WHOLE function: `T`'s single reader is the
    /// naming store, `L` is written exactly once (by that store) and read
    /// exactly once (by this branch), and nothing branches into the two
    /// instructions being erased. Then the stored boolean is dead the instant it
    /// is written, and the name has no observer left to disagree with the flags.
    ///
    /// Where it stops: a binding read anywhere else — later in the body, on
    /// another path, across a loop back edge — keeps its store, because the
    /// value is then genuinely live and erasing it is the miscompile this repo
    /// has already shipped once. `L`'s frame slot is still reserved either way,
    /// so the frame layout does not move.
    fn namedCompareBranchFusible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        cmp_ins: dnir.Instr,
        st: dnir.Instr,
        br: dnir.Instr,
        flat_idx: u32,
    ) bool {
        if (cmp_ins.op != .binop) return false;
        if (comparisonCondition(cmp_ins.binop) == null) return false;
        if (cmp_ins.ty == .f64) return false;
        if (cmp_ins.application != null or cmp_ins.relation != null or cmp_ins.value != null) return false;
        if (self.cur_func_float) return false;
        if (self.valueIsFp(cmp_ins.lhs) or self.valueIsFp(cmp_ins.rhs)) return false;
        const t = cmp_ins.result orelse return false;

        if (st.op != .store_local) return false;
        if (st.ty == .f64) return false;
        // The naming store carries no application lineage of its own to lose.
        if (st.application != null or st.relation != null or st.value != null) return false;
        if (st.lhs != .temp or st.lhs.temp != t) return false;
        const l = st.result orelse return false;

        if (br.op != .br) return false;
        switch (br.branch_condition) {
            .when_true, .when_false => {},
            .unconditional => return false,
        }
        if (br.lhs != .local or br.lhs.local != l) return false;

        // The comparison result's only reader is the naming store — asked of
        // the function, for the reason `compareBranchFusible` states.
        if (!self.singleReaderByTightDef(t, flat_idx)) return false;

        var reads: u32 = 0;
        var writes: u32 = 0;
        var read_at: u32 = 0;
        var write_at: u32 = 0;
        dnirLocalUseCensus(f, l, &reads, &writes, &read_at, &write_at);
        if (reads != 1 or writes != 1) return false;
        if (read_at != flat_idx + 2 or write_at != flat_idx + 1) return false;

        if (dnirBranchLandsWithin(f, flat_idx + 1, flat_idx + 2)) return false;
        return true;
    }

    // ------------------------------------------------------------------
    // W7 — IF-CONVERSION.
    //
    // A one-sided `if` whose whole body assigns one pure value to one binding
    // is a SELECT, and AArch64 has had the instruction all along: `csel`
    // appears nowhere in this backend, yet `encodeCset` is already the same
    // conditional-select family with `Rn`/`Rm` pinned to `xzr`.
    //
    // Measured worth, `docs/ftc.md` W7 written both ways by hand with identical
    // answers over 0/1/7/1001/65535: 2.15x CYCLES on an unpredictable branch,
    // where the instruction count barely moves. The whole difference is
    // mispredicts — IPC doubles from 1.00 to 2.03.
    //
    // ADMISSION RULE, and it has two independent halves.
    //
    // SOUNDNESS. If-conversion executes the arm that the branch would have
    // skipped, so anything the arm can do on a path it never took becomes real.
    // Admitted: exactly one integer ALU `binop` from a closed whitelist —
    // add, sub, mul, and, or, xor, shl, shr, and the six comparisons — feeding
    // exactly one `store_local` of a scalar local. Everything else is refused,
    // and the refusals are the point:
    //   - `div`/`mod`: division is THE trapping arithmetic. This backend's
    //     `sdiv` happens not to fault on zero today, which is precisely why it
    //     must be excluded — the exclusion has to survive a future divide check.
    //   - `load_index`/`store_index`: bounds-checked, and a check that fails
    //     ends in `brk`. An out-of-range index in an untaken arm would become a
    //     crash that did not exist.
    //   - `load_field`/`store_field`/`str_len`/`alloc_slots`: memory that may
    //     not be there on the untaken path.
    //   - `call_direct`/`call_extern`/`print_value`/`hw_*`: effects, and a call
    //     clobbers the flags between the compare and the select.
    //   - f64 anywhere: `fcsel` is a different encoding and is not emitted here.
    // The one store the arm does perform is made safe rather than forbidden:
    // the select feeds it the binding's OWN CURRENT VALUE when the condition is
    // false, so the write-back is a no-op on the path that used to skip it.
    //
    // PROFITABILITY, and it is a real boundary, not a formality. Converting
    // pays for the arm on every iteration and saves a mispredict only when the
    // branch is unpredictable. With the arm capped at ONE ALU op the trade is
    // bounded on both sides: at most +3 executed instructions when the branch
    // was never taken (~0.6 cycles at this stream's measured IPC of 4.74),
    // against ~13 cycles per mispredict avoided. Break-even is a misprediction
    // rate near 5%, so the conversion loses only on a branch predicted better
    // than ~95% — and there it loses less than a cycle. A LONGER arm has no
    // such bound: its cost grows with its length while the saving stays capped
    // at one mispredict, which is why the cap is the rule and not a tuning knob.
    // Idol has no edge-probability fact (`ApplicationFact.authority` is still
    // unpopulated), so a profile-driven widening is a separate decision that
    // needs a fact this compiler does not yet have.
    // ------------------------------------------------------------------

    const IfConvPlan = struct {
        /// Comparison feeding the branch, when it is fusible into `cmp`.
        cmp: ?dnir.Instr,
        /// The conditional branch itself.
        br: dnir.Instr,
        /// The arm's single ALU operation, or null when the arm is a pure
        /// value copy (`store_local L <- V` with no op between the branch and
        /// the store); the arm's value is then `store.lhs` evaluated directly.
        op: ?dnir.Instr,
        /// The arm's terminating `store_local`.
        store: dnir.Instr,
        /// DNIR instructions consumed AFTER the one the driver is holding.
        extra: u32,
    };

    fn ifConvArmOpAdmissible(self: *const Arm64Compiler, ins: dnir.Instr) bool {
        if (ins.op != .binop) return false;
        if (ins.ty == .f64 or self.cur_func_float) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        if (ins.result == null) return false;
        // Division is the trapping one, and WHICH tags those are is
        // `BinOpTag.requiresNonzeroDivisor`'s answer, not a list kept here. See the
        // admission rule above.
        return !ins.binop.requiresNonzeroDivisor();
    }

    /// Recognize the copy-arm shape `store_local L <- V ; br unconditional
    /// -> J` at `body[1..2]` with `J = at + 3`, returning the store. The
    /// conditional branch (`body[0]`) and its target were checked by the
    /// caller: both branches must land on the instruction just past the
    /// window, which is what makes the `if` one-sided. `V` is restricted to
    /// locals, temps, and immediates, so evaluating it on the path the branch
    /// would have skipped emits at most a home read, a frame `ldr`, or a
    /// `mov` chain. A self-copy (`L = L`) is declined: selecting a value
    /// against itself is correct but never profitable.
    fn ifConvCopyArm(
        self: *const Arm64Compiler,
        f: dnir.Function,
        body: []const dnir.Instr,
        at: u32,
        br: dnir.Instr,
    ) ?dnir.Instr {
        const st = body[1];
        if (st.op != .store_local) return null;
        if (st.ty == .f64) return null;
        if (st.application != null or st.relation != null or st.value != null) return null;
        const l = st.result orelse return null;
        if (self.valueIsFp(.{ .local = l }) or self.valueIsFp(st.lhs)) return null;
        switch (st.lhs) {
            .local => |slot| if (slot == l) return null,
            .temp, .i64 => {},
            else => return null,
        }
        const join = body[2];
        if (join.op != .br or join.branch_condition != .unconditional) return null;
        const join_idx = at + 3;
        if (join.branch_target != join_idx) return null;
        if (br.branch_target != join_idx) return null;
        if (dnirBranchLandsWithin(f, at + 1, at + 2)) return null;
        return st;
    }

    /// Recognize `br when_x C -> J ; <one ALU op> ; store_local L ;
    /// br unconditional -> J` with `J` the instruction just past the window,
    /// plus the degenerate copy-arm shape `br when_x C -> J ; store_local
    /// L <- V ; br unconditional -> J` (no ALU op; the arm is the pure value
    /// `V`, a local, temp, or immediate).
    ///
    /// `at` is the flat index of `body[0]`; `body` is the remainder of the
    /// current block starting there. Returns the plan, or null.
    fn ifConversionArm(
        self: *const Arm64Compiler,
        f: dnir.Function,
        body: []const dnir.Instr,
        at: u32,
        cmp: ?dnir.Instr,
        consumed_before: u32,
    ) ?IfConvPlan {
        if (body.len < 3) return null;
        const br = body[0];
        if (br.op != .br) return null;
        switch (br.branch_condition) {
            .when_true, .when_false => {},
            .unconditional => return null,
        }
        // Copy-arm shape: the arm is a pure value rather than an ALU op, so
        // the select chooses between it and the binding's own current value.
        if (self.ifConvCopyArm(f, body, at, br)) |st| {
            return .{ .cmp = cmp, .br = br, .op = null, .store = st, .extra = consumed_before + 2 };
        }
        if (body.len < 4) return null;
        const op = body[1];
        if (!self.ifConvArmOpAdmissible(op)) return null;
        const st = body[2];
        if (st.op != .store_local) return null;
        if (st.ty == .f64) return null;
        if (st.application != null or st.relation != null or st.value != null) return null;
        const t = op.result.?;
        if (st.lhs != .temp or st.lhs.temp != t) return null;
        const l = st.result orelse return null;
        if (self.valueIsFp(.{ .local = l }) or self.valueIsFp(.{ .temp = t })) return null;
        const join = body[3];
        if (join.op != .br or join.branch_condition != .unconditional) return null;

        // The join must be the instruction immediately past the window, and the
        // conditional branch must go to the SAME place — otherwise there is an
        // `else` arm this shape does not model.
        const join_idx = at + 4;
        if (join.branch_target != join_idx) return null;
        if (br.branch_target != join_idx) return null;

        // The arm's value has no reader outside the arm.
        const last = self.value_free_at.get(t) orelse return null;
        if (last != at + 2) return null;

        // Nothing may branch into the arm.
        if (dnirBranchLandsWithin(f, at + 1, at + 3)) return null;

        return .{ .cmp = cmp, .br = br, .op = op, .store = st, .extra = consumed_before + 3 };
    }

    /// Emit the `csel` form of a recognized one-sided `if`.
    ///
    /// Emission ORDER is load-bearing. The flags are set last before the select
    /// because the arm's own operation may write them (`emitCompareResult` is
    /// `cmp` + `cset`), and the binding's old value is read first because a
    /// reload between the compare and the select would be the same hazard. What
    /// is left between `cmp` and `csel` is at most an `ldr` from
    /// `ensureRegLive`, which does not touch NZCV.
    fn emitIfConverted(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        plan: IfConvPlan,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        at: u32,
    ) Error!void {
        const l = plan.store.result.?;
        const op = plan.op.?; // Null (copy arm) dispatches to emitIfConvertedCopy.
        const t = op.result.?;

        // (1) The binding's current value — the arm's "else".
        const old = try self.evalDnirValue(temps, .{ .local = l });
        // AND THE SELECT'S OTHER OPERAND IS HELD IN NO MAP EITHER (GAP-148).
        //
        // `allocRegExcluding(old)` at step (2) covers `old` for the arm's own
        // allocation — the exclusion is skipped by both free scans, all three
        // spill passes and the reclaim. The CONDITION at step (3) excludes
        // nothing, and a frame-homed binding answers step (1) through
        // `loadGpStackLocal`: `allocReg` plus an `ldr`, recording no owner. So
        // between the two the binding's current value sits in a register
        // `gp_reg_owner` calls empty, and the cascade the condition can run ends
        // at the reclaim, which retires exactly that entry and hands the
        // register back for `emitMovImm` to write the condition's immediate
        // into. `ensureRegLive(old)` at step (4) then finds no entry to reload
        // and the `csel` selects the condition's operand as the binding's own
        // previous value. `holdReg` states the full rule; a
        // register-homed or pinned binding answers with its home and is left
        // alone.
        const old_held = self.holdReg(old, pinned);

        // (2) The arm's operation, now unconditional. An accumulator update
        //     (`a = a + k`) READS the same binding the select falls back to, so
        //     that operand reuses the register already loaded rather than
        //     emitting a second `ldr` of the same frame slot — which is what the
        //     first version of this emitter did, and it is the redundant-reload
        //     class this document measures at 8.9% of the program elsewhere.
        const lhs_is_dest = op.lhs == .local and op.lhs.local == l;
        const rhs_is_dest = op.rhs == .local and op.rhs.local == l;
        const a = if (lhs_is_dest) old else try self.evalDnirValue(temps, op.lhs);
        // AND THE LEFT OPERAND IS HELD ACROSS THE RIGHT ONE'S EVALUATION
        // (GAP-148).
        //
        // The hold at step (1) covers `old` and the record below covers `dst`.
        // Between them stands a third register with the same problem and no map
        // naming it: `a` is established on the line above and the line below
        // evaluates `plan.op.rhs`, which EXCLUDES NOTHING. An immediate is
        // `allocReg` plus `emitMovImm`, a frame local is `loadGpStackLocal`, and
        // under gate transport either can run the whole cascade — every free
        // scan skips `spilled_regs`, so the passes walk x28..x9 and x7..x0
        // spilling everything, `a` among them — and end at `reclaimSpilledReg`,
        // which retires an entry with a NULL owner and hands the register back
        // as the right operand's own scratch. The write that follows lands on
        // the left operand's value, `a == b`, and `emitCompareOrBinop` computes
        // the right operand against itself.
        //
        // NOTHING ON THIS PATH WAS CORRECT BY COINCIDENCE, so the hold narrows
        // nothing: every spelling in which `evalDnirValue` answers with a FRESH
        // register writes that register before anything reads it — `emitMovImm`
        // for an immediate, an `ldr` for a frame local, `adrp`/`add` for a
        // string — and the spellings that allocate nothing (a home, a pin, a
        // hoisted immediate, a live temp) reach `holdReg` already owned or
        // out of band and mint no record at all.
        //
        // THE WINDOW IS THE RIGHT OPERAND'S EVALUATION AND STOPS THERE. The
        // drop is on the line after, before `allocRegExcluding(old)`, because
        // that allocation MAY still answer with `a` and is right to:
        // `emitCompareOrBinop(a, a, b)` reads both operands before it writes its
        // destination — a comparison is `cmp` then `cset`, and every admitted
        // arithmetic form is a single three-register instruction — so reusing
        // the left operand as the destination is a register this emitter has
        // always been allowed to take, and holding it past this line would
        // refuse it.
        const a_held = self.holdReg(a, pinned);
        const b = if (rhs_is_dest) old else try self.evalDnirValue(temps, op.rhs);
        if (a_held) self.gp_reg_owner[a] = null;
        const dst = try self.allocRegExcluding(old);
        try self.emitCompareOrBinop(dst, a, b, op.binop, op.ty, op.divisor, op.dividend);
        // THE OWNER IS RECORDED WHEN THE REGISTER TAKES THE VALUE, NOT AFTER THE
        // SELECT (GAP-148).
        //
        // The line below used to sit at step (5), past the `csel`, and between
        // the two the arm's answer sat in `dst` under a NULL owner. That is the
        // one state `reclaimSpilledReg` bids for. Its skip list is `exclude`, a
        // home, a pin, a staged argument, a staged tail — and an OWNED entry,
        // which is the rule that says a spilled register's frame slot is the
        // only remaining location of a live value and may not be retired. An
        // unowned entry is, by that same rule, a stale name left by staging and
        // free to take.
        //
        // `dst` between here and the select is neither: it is a live value with
        // no owner record yet. The condition at step (3) allocates — an
        // immediate operand is `allocReg` — and under gate transport an
        // allocation that fails runs the whole cascade: every free scan skips
        // `spilled_regs`, so a spill frees nothing and the passes walk x28..x9
        // and x7..x0 spilling everything, `dst` among them, and arrive at the
        // reclaim. The reclaim then finds `dst` unowned, drops the entry,
        // claims it and hands it back as the condition's own scratch register —
        // and `evalDnirValue`'s `emitMovImm` writes the condition operand over
        // the arm's computed value. The `csel` then selects between the
        // condition's immediate and the binding's old value. A wrong answer
        // with no diagnostic, on the register the transform exists to produce.
        //
        // Recording the owner here is the whole repair and it changes nothing
        // else. The record's other readers cannot observe the move: `sweepGpLive`
        // does not run inside a collapsed window — the driver sweeps once per
        // CONSUMED index, after this emitter returns — `releaseReg` is called
        // below only for registers the guards already prove are not `dst`, and
        // `ensureRegLiveRemap` reads the record only for a register
        // `spilled_regs` names. Outside gate transport `spilled_regs` is empty,
        // `reclaimSpilledReg` is unreachable, and the record is the same record
        // at a different line.
        //
        // With `dst` owned the cascade refuses instead, which is the bail this
        // allocator already answers with when the pool is genuinely empty. Not
        // the closure — closure is authoritative `register`/`frame` assignment
        // before emission, per this gap's record, under which the select's
        // destination is a location the assignment carries rather than a claim
        // an emitter holds across an allocator that may bid for it.
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = t;
        }
        if (a != old and !Arm64Compiler.regIsPinned(pinned, a)) self.releaseReg(a);
        if (b != old and !Arm64Compiler.regIsPinned(pinned, b)) self.releaseReg(b);

        // (3) The condition. Nothing below this line may write the flags.
        var arm_cond: Condition = undefined;
        if (plan.cmp) |c| {
            const clhs = try self.evalDnirValue(temps, c.lhs);
            // THE COMPARE'S LEFT OPERAND IS THE SAME BID (GAP-148), reached
            // through the one register in this emitter that no earlier hold
            // covers. `crhs`'s evaluation allocates and excludes nothing, so the
            // cascade can spill `clhs` and the reclaim hand it back as `crhs`'s
            // own register; `emitCmpReg` then compares the right operand against
            // itself and the `csel` below runs on that condition. `ensureRegLive`
            // inside `emitCmpReg` cannot help — the reclaim removed the entry it
            // keys on.
            //
            // Held for exactly that window and dropped before the compare:
            // nothing between the drop and `emitCmpReg` allocates, and the
            // releases below are the same releases because the record is already
            // gone by the time they run. A `clhs` that is `old` or `dst` — the
            // two registers a fused compare most often reads — arrives ALREADY
            // OWNED and mints nothing.
            const clhs_held = self.holdReg(clhs, pinned);
            const crhs = try self.evalDnirValue(temps, c.rhs);
            if (clhs_held) self.gp_reg_owner[clhs] = null;
            try self.emitCmpReg(clhs, crhs);
            if (clhs != old and clhs != dst and !Arm64Compiler.regIsPinned(pinned, clhs)) self.releaseReg(clhs);
            if (crhs != old and crhs != dst and !Arm64Compiler.regIsPinned(pinned, crhs)) self.releaseReg(crhs);
            arm_cond = comparisonCondition(c.binop).?;
        } else {
            const cr = try self.evalDnirValue(temps, plan.br.lhs);
            try self.emitCmpZero(cr);
            if (cr != old and cr != dst and !Arm64Compiler.regIsPinned(pinned, cr)) self.releaseReg(cr);
            arm_cond = .ne;
        }
        // `when_false -> join` skips the arm when the condition is FALSE, so the
        // arm runs ON the condition; `when_true -> join` is its mirror.
        if (plan.br.branch_condition == .when_true) arm_cond = invertCondition(arm_cond);

        // (4) The select, in place of the branch.
        //
        // THE SELECT'S REGISTERS ARE ONLY WHERE ITS VALUES ARE WHILE
        // `spilled_regs` DOES NOT NAME THEM (GAP-148).
        //
        // `old` was established at step (1) and `dst` at step (2), and every
        // allocation since — the operand at step (2), the condition at step (3)
        // — could have spilled either. A spill does not move the bytes out of
        // the register, so the `csel` below still reads what it means to read;
        // what it leaves behind is the wrong part. `dst` is published to
        // `temps` at step (5) and the store immediately reads it back through
        // `ensureRegLiveRemap`, which finds the entry, loads the FRAME copy —
        // the register's pre-select content — and remaps the id onto that. The
        // store then writes the value the select was emitted to replace. Same
        // shape for `old` when the binding is read again later.
        //
        // `ensureRegLive` is the whole repair and it is the reload this file
        // already answers every other spelling of this question with: the `ldr`
        // back into the register every map names, the entry removed, the slot
        // released once on that removal, and the `claimReg` the loaded value is
        // owed — after which no map says the value is anywhere but here. An
        // `ldr` is also the ONE instruction this emitter's own order permits
        // between the compare and the select: it does not touch NZCV, which is
        // what the note at step (3) is stating.
        //
        // A no-op on every unspilled select, which is every select outside gate
        // transport, because `allocRegExcluding` refuses above its spill passes
        // otherwise. Not the closure — closure is authoritative
        // `register`/`frame` assignment before emission, per this gap's record.
        try self.ensureRegLive(old);
        try self.ensureRegLive(dst);
        try self.emitCselReg(dst, dst, old, arm_cond);
        // The hold ends where the allocations do, and before the release it
        // would otherwise turn into a no-op — `releaseReg` returns above an
        // owned register. `old != dst` holds by `allocRegExcluding(old)`.
        if (old_held) self.gp_reg_owner[old] = null;
        if (old != dst and !Arm64Compiler.regIsPinned(pinned, old)) self.releaseReg(old);

        // (5) The write-back, through the ordinary `store_local` path so that a
        //     register-homed local and a frame-homed one stay exactly as they
        //     were — this fold changes WHAT is stored, never WHERE.
        try temps.put(self.alloc, t, dst);
        try self.compileDnirInstr(temps, pinned, plan.store, branch_patches, null, at);
    }

    /// Emit the `csel` form of a recognized one-sided `if` whose arm is a
    /// pure value copy (`if c \n L = V` with `V` a local, temp, or
    /// immediate): `csel dst, newv, old, cond` followed by the ordinary
    /// `store_local`.
    ///
    /// Register discipline mirrors `emitIfConverted`. `old` (the binding's
    /// current value) is the select's "else"; `newv` (the arm's value) is
    /// evaluated unconditionally, which admission restricts to a home read, a
    /// frame `ldr`, or a `mov` chain. Both are held across the condition's
    /// evaluation — the condition allocates, and under gate transport an
    /// allocation that fails walks the spill cascade, which retires exactly
    /// the unowned. The select lands in a FRESH `dst` rather than `newv`'s
    /// register: `newv` may name a local or temp that stays live past the
    /// join, and selecting in place would clobber it on the taken path. The
    /// store is compiled through the ordinary `store_local` path with its
    /// source rebound to a fresh synthesized id, so later reads of a
    /// `.local`/`.temp` source still answer with the source's own value and
    /// not the selected one. Nothing between the condition's `cmp` and the
    /// `csel` writes NZCV.
    fn emitIfConvertedCopy(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        plan: IfConvPlan,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        at: u32,
    ) Error!void {
        const l = plan.store.result.?;
        // (1) The binding's current value — the select's "else".
        const old = try self.evalDnirValue(temps, .{ .local = l });
        const old_held = self.holdReg(old, pinned);
        // (2) The arm's value. Pure by admission: a local answers with its
        // home or a frame `ldr`, a temp with its register, an immediate with
        // a fresh `mov` chain.
        const newv = try self.evalDnirValue(temps, plan.store.lhs);
        const newv_held = self.holdReg(newv, pinned);
        // The select's destination. Fresh by construction: `newv`'s register
        // is claimed so the scan cannot answer it, and `old` is excluded by
        // name, so both select inputs survive the allocation.
        const dst = try self.allocRegExcluding(old);
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = 0xFFFFFFFF;
        }
        // (3) The condition. `newv` joins `old` and `dst` in the keep set: the
        // compare's operands are released only when they are scratch the
        // condition itself materialized — `newv` may BE the compare's left
        // operand (`if b < m \n m = b`), and releasing it would free the
        // select's input while the `csel` still has to read it.
        var arm_cond: Condition = undefined;
        if (plan.cmp) |c| {
            const clhs = try self.evalDnirValue(temps, c.lhs);
            const clhs_held = self.holdReg(clhs, pinned);
            const crhs = try self.evalDnirValue(temps, c.rhs);
            if (clhs_held) self.gp_reg_owner[clhs] = null;
            try self.emitCmpReg(clhs, crhs);
            if (clhs != old and clhs != newv and clhs != dst and !Arm64Compiler.regIsPinned(pinned, clhs)) self.releaseReg(clhs);
            if (crhs != old and crhs != newv and crhs != dst and !Arm64Compiler.regIsPinned(pinned, crhs)) self.releaseReg(crhs);
            arm_cond = comparisonCondition(c.binop).?;
        } else {
            const cr = try self.evalDnirValue(temps, plan.br.lhs);
            try self.emitCmpZero(cr);
            if (cr != old and cr != newv and cr != dst and !Arm64Compiler.regIsPinned(pinned, cr)) self.releaseReg(cr);
            arm_cond = .ne;
        }
        // `when_false -> join` skips the arm when the condition is FALSE, so
        // the arm runs ON the condition; `when_true -> join` is its mirror.
        if (plan.br.branch_condition == .when_true) arm_cond = invertCondition(arm_cond);
        // (4) The select, in place of the branch. `emitCselReg` re-ensures
        // both inputs itself; the explicit ensures match `emitIfConverted`.
        try self.ensureRegLive(old);
        try self.ensureRegLive(newv);
        try self.emitCselReg(dst, newv, old, arm_cond);
        if (old_held) self.gp_reg_owner[old] = null;
        if (newv_held) self.gp_reg_owner[newv] = null;
        if (old != dst and !Arm64Compiler.regIsPinned(pinned, old)) self.releaseReg(old);
        // `newv` is scratch only for an immediate source; `releaseReg` is a
        // no-op over homes, pins, and owned registers, so local/temp sources
        // — which may stay live past the join — are untouched.
        if (newv != old and newv != dst and !Arm64Compiler.regIsPinned(pinned, newv)) self.releaseReg(newv);
        // (5) The write-back, through the ordinary `store_local` path so a
        // register-homed local and a frame-homed one stay exactly as they
        // were. The source is rebound to a fresh synthesized id: publishing
        // `dst` under the source's own id would make later reads of a local
        // or temp source answer with the SELECTED value — the binding's old
        // value when the condition is false — instead of the source's own.
        const s: u32 = 0xFFFFFFFF;
        try temps.put(self.alloc, s, dst);
        var store2 = plan.store;
        store2.lhs = .{ .temp = s };
        try self.compileDnirInstr(temps, pinned, store2, branch_patches, null, at);
    }

    // ------------------------------------------------------------------
    // W8 — TWO-SIDED IF-CONVERSION.
    //
    // W7 above converts `if c \n L = <op>`, a branch with ONE arm. The shape
    // that carries the measured cost is the branch with TWO:
    //
    //     if x % 2 == 0        cmp/b.ne  -> else
    //         x = x // 2       asr ; mov ; b join
    //     else
    //         x = 3 * x + 1    madd ; mov
    //
    // Both arms assign ONE binding, so the whole `if` is a select between two
    // values — `csel`.
    //
    // GAP-205 names this branch as collatz's ENTIRE remaining gap to clang -O2
    // (1.47x, with the arithmetic already equal: `and #1`, `asr #1`, `madd`).
    // THAT IS MEASURED HERE AND IT IS WRONG. Converting collatz's branch and
    // changing nothing else makes the kernel SLOWER, 1.53x -> 1.70x, because
    // the select makes the expensive arm's latency loop-carried. The full
    // ladder is in `ifConvArmOpAdmissibleTwoSided`, which is where the
    // profitability rule that declines collatz lives.
    //
    // The transform is kept, and measured, because on the shape it is actually
    // for — an unpredictable branch with CHEAP arms — it is worth 3.02x
    // (`sel.id`: 0.1703s branchy, 0.0564s converted, 5e7 iterations, min of 9,
    // both from this same compiler with only this flag between them).
    //
    // SOUNDNESS. Converting executes BOTH arms, so everything W7's admission
    // rule refuses is refused here for the same reasons and one more besides:
    //
    //   - EFFECTS. An arm may contain no application at all. Where an
    //     instruction DOES carry application lineage the graph's
    //     `ApplicationFact.effect` is consulted (`armInstrEffectAdmissible`)
    //     and only `.none` licenses anything; `.unknown` is "nobody published
    //     a fact", which is a refusal. Such an instruction is then STILL
    //     refused, because collapsing the window erases the realization row
    //     the module's `application-realization-count` check requires — the
    //     fact would license the speculation, the emitter cannot yet carry the
    //     lineage. Both refusals are counted separately (`IDOL_IFCONV_REPORT`).
    //   - TRAPS. `div`/`idiv`/`mod` and every indexed or field access stay out
    //     of the whitelist. A speculated arm must not be able to fault, and
    //     that is also why this transform does NOT interact with the div-by-zero
    //     trap block: an arm that could reach one is never admitted.
    //   - DIVERGENCE. The window is straight-line by construction: anything
    //     other than the exact `br / ops / store / br / ops / store` shape
    //     refuses, and `dnirBranchLandsWithin` refuses a branch INTO it.
    //   - ALLOCATION. `alloc_slots` is not in the whitelist.
    //   - f64. `fcsel` is a different encoding and is not emitted here.
    //
    // THE JOIN. Both arms must store to the SAME local with the same
    // descriptor. The converted form performs that store EXACTLY ONCE, through
    // the ordinary `store_local` path, so a binding read after the join reads
    // from where it always did and a register-homed local stays homed. This is
    // the failure mode a prior loop transform here shipped: semantically
    // profitable, and it moved the value the process exits with.
    //
    // PROFITABILITY. Each arm is capped at `if_conv_arm_op_cap` ALU operations,
    // so conversion pays at most that many extra executed instructions per
    // iteration (the arm that would not have run) plus one `csel`, and saves
    // one branch. At the ~4 IPC this backend's scalar streams measure that is
    // under a cycle against ~13 cycles per mispredict, so the break-even
    // misprediction rate is a few percent. The cap is the bound: a longer arm's
    // cost grows while the saving stays capped at one mispredict. Idol still
    // publishes no edge-probability fact, so nothing here is profile-driven.
    // ------------------------------------------------------------------

    /// Ops admitted in ONE arm. Two is not a tuning knob: it is the length of
    /// `3 * x + 1` (a `mul` and an `add`, which the `madd` fusion then folds
    /// back into one instruction), and the bound the profitability argument
    /// above is stated against.
    const if_conv_arm_op_cap: u32 = 2;

    /// Master switch for W8. The SEVERING control flips this to `false` and
    /// rebuilds: the branch comes back, and so does the timing.
    const two_sided_if_conversion = true;

    const TwoSidedPlan = struct {
        cmp: ?dnir.Instr,
        br: dnir.Instr,
        then_ops: []const dnir.Instr,
        then_store: dnir.Instr,
        else_ops: []const dnir.Instr,
        else_store: dnir.Instr,
        extra: u32,
    };

    /// W8's arm whitelist: W7's, plus the ONE widening two-sided conversion
    /// needs and can justify.
    ///
    /// W7 refuses `div`/`idiv`/`mod` outright, and its reason is exact:
    /// "division is THE trapping arithmetic... this backend's `sdiv` happens
    /// not to fault on zero today, which is precisely why it must be excluded
    /// — the exclusion has to survive a future divide check."
    ///
    /// That reason is about the DIVIDE INSTRUCTION, and `constBinopRealization`
    /// answers exactly when no divide instruction is emitted. `x // 2` is
    /// `asr xd, xn, #1` — an identity over the full i64 domain under floored
    /// law, needing no range fact, and containing nothing that can fault now or
    /// under any future divide check, because there is no divide left in it.
    /// A divisor that is not a literal, or a literal that reaches `sdiv`, is
    /// still refused; the rule is "this arm emits no trapping instruction",
    /// not "this divisor looks safe".
    ///
    /// It is also the widening the measured shape needs: collatz's then-arm IS
    /// `x = x // 2`, and without this the whole kernel refuses.
    fn ifConvArmOpAdmissibleTwoSided(self: *const Arm64Compiler, ins: dnir.Instr) bool {
        // THE LATENCY GUARD, AND IT IS MEASURED, NOT ASSUMED.
        //
        // One-sided conversion speculates an arm the branch might have skipped.
        // TWO-SIDED conversion converts a CONTROL dependence into a DATA
        // dependence: after the fold the select cannot retire until BOTH arms
        // have, so both arms' latency lands on whatever path the selected value
        // is on — and when that value is loop-carried, on the recurrence, every
        // iteration. The branchy form paid the expensive arm only on the
        // fraction of iterations that took it.
        //
        // MEASURED ON COLLATZ, the kernel this transform was written for
        // (2e6 seeds, min of 6, each variant hand-written in asm and answering
        // 277182223; clang -O2 = 1.000x):
        //
        //     branchy, `madd` for 3*x+1        1.531x
        //     csel,    `madd` for 3*x+1        1.714x   <- CONVERSION LOSES
        //     csel,    3*x as `add x,x,x lsl 1` 1.377x
        //      + `tst` for the parity test      1.337x
        //      + `csinc` folding the +1         0.998x  <- parity
        //
        // `madd`'s ~3-cycle latency on a 2-3 cycle recurrence is the whole
        // reversal: with a one-cycle shifted add in its place the SAME
        // conversion is a win. So the admissible arm is one whose realization
        // is single-cycle ALU work, and a hardware multiply is refused. A
        // multiply by a constant that `constBinopRealization` turns into a
        // `mov`/`lsl` is not a hardware multiply and stays admitted.
        //
        // WHAT WOULD REPLACE THIS RULE with something better is a fact Idol
        // does not publish: whether the assigned binding is on a recurrence,
        // and what the branch's misprediction rate is. `ApplicationFact` has
        // neither. Until it does, "the speculated arm must be as cheap as the
        // branch it replaces" is the bound that can actually be checked.
        if (ins.op == .binop and ins.binop == .mul and constBinopRealization(ins) == null) return false;
        if (self.ifConvArmOpAdmissible(ins)) return true;
        if (ins.op != .binop) return false;
        // Only the divisor-obligation tags reach here: everything else was
        // already answered by `ifConvArmOpAdmissible` above. The obligation is
        // `BinOpTag.requiresNonzeroDivisor`'s to state; this asks it.
        if (!ins.binop.requiresNonzeroDivisor()) return false;
        if (ins.ty == .f64 or self.cur_func_float) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        if (ins.result == null) return false;
        return constBinopRealization(ins) != null;
    }

    /// THE GRAPH'S EFFECT FACT, for one instruction of a speculated arm.
    ///
    /// An instruction with no application lineage denotes no relation
    /// application: there is no call to speculate and nothing to ask about.
    /// One that DOES carry lineage is decided by the graph and by nothing else
    /// — `.none` is the only answer that licenses executing it on a path the
    /// branch was protecting. `.unknown` is the honest "no fact was published"
    /// and refuses; a null graph refuses for the same reason.
    ///
    /// AND `.none` IS NOT ENOUGH, WHICH IS MEASURED AND NOT ARGUED. The five
    /// conditions `publishApplicationEffects` closes over are about
    /// OBSERVABILITY — foreign declarations, unresolved calls, captures, world
    /// members. None of them is about TERMINATION. A relation whose whole body
    /// is `while i > 0 \n i = i + 1` satisfies every one of them, and
    /// `idol graph` publishes `effect: none, authority: none` for its
    /// application (control 3, `c3_diverge.id`). Speculating it hangs the
    /// process, and the effect card says go ahead.
    ///
    /// So the fact this transform needs — "this arm terminates" — is a fact
    /// Idol does not publish. `dnirInstrIsCall` below refuses on that ground
    /// explicitly, rather than leaving the safety to the lineage rule that
    /// happens to catch the same instructions for an unrelated reason.
    fn armInstrEffectAdmissible(self: *const Arm64Compiler, ins: dnir.Instr) bool {
        const application = ins.application orelse return true;
        const graph = self.graph orelse return false;
        const fact = graph.application(application) orelse return false;
        return fact.effect == .none and fact.authority == .none;
    }

    /// An applied relation. No published fact answers whether one terminates,
    /// so none may be speculated whatever its effect card says.
    fn dnirInstrIsCall(ins: dnir.Instr) bool {
        return switch (ins.op) {
            .call_direct, .call_extern => true,
            else => false,
        };
    }

    /// THE COUNTERFACTUAL FOR A FACT THAT DOES NOT EXIST YET.
    ///
    /// `gate/effect.sh` can sever a published fact and watch the artifact
    /// change. Termination has no producer to sever, so the control has to run
    /// the other way: ASSUME the strongest answer the fact could ever give —
    /// every applied relation terminates — and watch whether a single decision
    /// moves. If the artifact is byte-identical under the assumption, then
    /// building the producer buys nothing today, and the census counter
    /// `ifconv_refused_diverge_masked` says why: an independent ground already
    /// refuses the same arms.
    ///
    /// IT CANNOT ADMIT ANYTHING, AND THAT IS THE WHOLE DESIGN. The first
    /// version of this control let the assumed arm fall through to the
    /// remaining grounds and, had they all passed, would have CONVERTED. That
    /// put a measuring instrument on the production path: any compiler process
    /// that inherited the name would have silently lost the refusal for every
    /// compilation, which is the same class of defect as an environment
    /// variable the artifact cache does not answer for. Assuming termination
    /// about a relation that diverges is exactly the miscompile the refusal
    /// exists to prevent, so the assumption may never reach an admission.
    ///
    /// What it does instead: the arm chain CONTINUES past the termination
    /// ground so the next ground can be observed, and `ifconv_assumed_call`
    /// makes the successful return refuse with `termination-would-admit`. The
    /// flag can therefore only ever turn one refusal into a different refusal.
    /// The artifact is inert by CONSTRUCTION, and `gate/speculation.sh` still
    /// byte-compares both arms, because a control whose inertness is only
    /// argued is a control nobody checked.
    ///
    /// So the reading is a COUNTER, not a diff: `termination_would_admit` is
    /// how many arms a real producer would have unblocked. Zero means the
    /// producer would govern nothing.
    ///
    /// Read by VALUE, so both arms of a measurement carry the name and neither
    /// is silently the default. Nothing in the tree sets it; `main.zig`
    /// classifies it `.affects` so the artifact cache answers for it.
    fn terminationAssumed() bool {
        const raw = std.c.getenv("IDOL_TERMINATION_ASSUME") orelse return false;
        return std.mem.eql(u8, std.mem.span(raw), "1");
    }

    /// One arm's operation list, checked as a straight-line chain of pure
    /// integer ALU work whose intermediate values die inside the arm.
    ///
    /// `ops` are the instructions strictly between the arm's entry and its
    /// terminating `store_local`; `at` is the flat index of `ops[0]`.
    fn ifConvArmChainAdmissible(
        self: *Arm64Compiler,
        ops: []const dnir.Instr,
        at: u32,
        store: dnir.Instr,
    ) bool {
        self.ifconv_assumed_call = false;
        if (ops.len > if_conv_arm_op_cap) {
            self.ifconv_refusal = "arm-op-cap";
            return false;
        }
        if (store.op != .store_local) {
            self.ifconv_refusal = "arm-tail-not-store";
            return false;
        }
        if (store.ty == .f64) {
            self.ifconv_refusal = "f64";
            return false;
        }
        if (store.application != null or store.relation != null or store.value != null) {
            self.ifconv_refusal = "store-lineage";
            return false;
        }
        if (store.result == null) {
            self.ifconv_refusal = "store-no-local";
            return false;
        }
        if (self.valueIsFp(.{ .local = store.result.? })) {
            self.ifconv_refusal = "f64";
            return false;
        }

        for (ops, 0..) |op, i| {
            // THE FACT FIRST, so a refusal names the missing fact rather than
            // the shape that happens to imply it.
            if (!self.armInstrEffectAdmissible(op)) {
                self.ifconv_refusal = "effect-not-none";
                self.ifconv_refused_effect_unknown += 1;
                return false;
            }
            // AND THE FACT THAT IS NOT PUBLISHED AT ALL. See
            // `armInstrEffectAdmissible`: `effect: none` is measured to hold
            // for a relation that never returns.
            if (dnirInstrIsCall(op)) {
                self.ifconv_refusal = "no-termination-fact";
                self.ifconv_refused_diverge += 1;
                // AND WHETHER THAT REFUSAL WAS LOAD-BEARING. The lineage rule
                // below is an INDEPENDENT ground: it refuses any op carrying
                // graph lineage because the collapsed window emits no
                // realization row for it. A call that carries lineage is
                // refused twice over, and publishing the termination fact
                // would move nothing.
                if (op.application != null or op.relation != null or op.value != null) {
                    self.ifconv_refused_diverge_masked += 1;
                }
                // THE CONTROL DOES NOT RETURN HERE; it carries. See
                // `terminationAssumed`: continuing lets the NEXT ground be
                // observed, and the carry flag guarantees the chain still
                // refuses even if every remaining ground passes.
                if (!terminationAssumed()) return false;
                self.ifconv_assumed_call = true;
            }
            if (op.application != null or op.relation != null or op.value != null) {
                // Effect-free by the graph, and still refused: the collapsed
                // window emits no realization row for it.
                self.ifconv_refusal = "arm-op-lineage";
                self.ifconv_refused_lineage += 1;
                return false;
            }
            if (!self.ifConvArmOpAdmissibleTwoSided(op)) {
                self.ifconv_refusal = switch (op.op) {
                    .binop => if (op.binop.requiresNonzeroDivisor())
                        "arm-op-trapping"
                    else if (op.binop == .mul)
                        "arm-op-latency"
                    else
                        "arm-op-shape",
                    .load_index, .store_index, .load_field, .store_field, .alloc_slots => "arm-op-trapping",
                    else => "arm-op-shape",
                };
                if (std.mem.eql(u8, self.ifconv_refusal, "arm-op-trapping")) {
                    self.ifconv_refused_trap += 1;
                } else if (std.mem.eql(u8, self.ifconv_refusal, "arm-op-latency")) {
                    self.ifconv_refused_latency += 1;
                }
                return false;
            }
            const t = op.result.?;
            const consumer_at: u32 = at + @as(u32, @intCast(i)) + 1;
            // Every intermediate value dies at the next instruction of this
            // arm; the last one dies at the store. A wider live range means the
            // value is read outside the window, and the window is collapsing.
            const last = self.value_free_at.get(t) orelse {
                self.ifconv_refusal = "arm-value-no-range";
                return false;
            };
            if (last != consumer_at) {
                self.ifconv_refusal = "arm-value-escapes";
                return false;
            }
            if (i + 1 < ops.len) {
                const nx = ops[i + 1];
                const feeds = (nx.lhs == .temp and nx.lhs.temp == t) or
                    (nx.rhs == .temp and nx.rhs.temp == t);
                if (!feeds) {
                    self.ifconv_refusal = "arm-not-a-chain";
                    return false;
                }
            } else {
                if (store.lhs != .temp or store.lhs.temp != t) {
                    self.ifconv_refusal = "arm-store-reads-elsewhere";
                    return false;
                }
            }
        }

        if (ops.len == 0) {
            // A ZERO-OP ARM (`x = 5`, `x = y`) is admitted, but only for a
            // value that is already in hand: an immediate or another local.
            // A temp would be a value produced OUTSIDE the arm whose live
            // range this window is not entitled to reason about.
            switch (store.lhs) {
                .i64, .local => {},
                else => {
                    self.ifconv_refusal = "arm-empty-store-source";
                    return false;
                },
            }
            if (self.valueIsFp(store.lhs)) {
                self.ifconv_refusal = "f64";
                return false;
            }
        }
        // THE ASSUMPTION NEVER ADMITS. Every other ground passed, so a real
        // termination producer WOULD have unblocked this arm: count it, and
        // refuse anyway.
        if (self.ifconv_assumed_call) {
            self.ifconv_refusal = "termination-would-admit";
            self.ifconv_termination_would_admit += 1;
            return false;
        }
        return true;
    }

    /// Recognize
    ///
    ///     br when_x C -> E ; <then ops> ; store_local L ; br -> J
    ///     E: <else ops> ; store_local L ; J:
    ///
    /// `at` is the flat index of `body[0]`, which must be the conditional
    /// branch. Returns the plan, or null with `ifconv_refusal` set.
    fn ifConversionTwoSided(
        self: *Arm64Compiler,
        f: dnir.Function,
        body: []const dnir.Instr,
        at: u32,
        cmp: ?dnir.Instr,
        consumed_before: u32,
    ) ?TwoSidedPlan {
        self.ifconv_refusal = "";
        if (!two_sided_if_conversion) return null;
        if (self.cur_func_float) return null;
        if (body.len < 4) return null;
        const br = body[0];
        if (br.op != .br) return null;
        switch (br.branch_condition) {
            .when_true, .when_false => {},
            .unconditional => return null,
        }

        // ---- STRUCTURE FIRST, AND SILENTLY. Everything down to the join test
        // is deciding whether this branch is a two-sided `if` AT ALL. A loop's
        // back edge and a guard clause reach here too, and counting them as
        // declined conversions makes the census a count of branches rather than
        // a count of decisions. Only past the join test does a refusal get a
        // name and a tally.
        //
        // The conditional branch's target is where the ELSE arm starts, and
        // that fixes the length of the THEN arm exactly.
        if (br.branch_target < at + 3) return null;
        const then_ops_len_wide = br.branch_target - at - 3;
        if (then_ops_len_wide >= body.len) return null;
        const n_then: usize = @intCast(then_ops_len_wide);
        if (body.len < n_then + 3) return null;

        const then_store = body[1 + n_then];
        const then_join = body[2 + n_then];
        if (then_join.op != .br or then_join.branch_condition != .unconditional) return null;
        const join_idx = then_join.branch_target;
        if (join_idx < at + 4 + n_then) return null;
        const else_ops_len_wide = join_idx - at - 4 - @as(u32, @intCast(n_then));
        if (else_ops_len_wide >= body.len) return null;
        const n_else: usize = @intCast(else_ops_len_wide);
        const window_len = 4 + n_then + n_else;
        if (body.len < window_len) return null;
        const else_store = body[3 + n_then + n_else];

        // ---- FROM HERE IT IS A TWO-SIDED `if`, and every exit is a decision.
        if (then_ops_len_wide > if_conv_arm_op_cap or else_ops_len_wide > if_conv_arm_op_cap) {
            self.ifconv_refusal = "arm-op-cap";
            self.ifconv_refused_cap += 1;
            return null;
        }

        const then_ops = body[1 .. 1 + n_then];
        const else_ops = body[3 + n_then .. 3 + n_then + n_else];

        if (!self.ifConvArmChainAdmissible(then_ops, at + 1, then_store)) return null;
        if (!self.ifConvArmChainAdmissible(else_ops, at + 3 + @as(u32, @intCast(n_then)), else_store)) return null;

        // ONE BINDING, ONE DESCRIPTOR. Two arms that assign different locals
        // are two selects, and two that assign the same local at different
        // widths disagree about what the store means.
        if (then_store.result.? != else_store.result.?) {
            self.ifconv_refusal = "arms-assign-different-bindings";
            return null;
        }
        if (!std.meta.eql(then_store.ty, else_store.ty)) {
            self.ifconv_refusal = "arms-disagree-on-descriptor";
            return null;
        }

        // Nothing may branch INTO the window: every consumed index collapses
        // onto one code offset, so a landing site inside it arrives somewhere
        // the window never meant.
        // The window physically begins at the HEAD instruction the driver is
        // holding, which is `consumed_before` indices before this branch when a
        // compare (or a compare and its naming store) was folded in. Only the
        // head keeps a code offset that means what it meant: every other index
        // in the window collapses onto the offset PAST it, so a branch to any
        // of them would arrive after the whole `if` instead of inside it.
        const window_lo = at - consumed_before;
        const window_hi = at + @as(u32, @intCast(window_len)) - 1;
        if (dnirBranchIntoWindow(f, window_lo + 1, window_hi, window_lo, window_hi)) {
            self.ifconv_refusal = "branch-into-window";
            return null;
        }

        self.ifconv_refusal = "";
        return .{
            .cmp = cmp,
            .br = br,
            .then_ops = then_ops,
            .then_store = then_store,
            .else_ops = else_ops,
            .else_store = else_store,
            .extra = consumed_before + @as(u32, @intCast(window_len)) - 1,
        };
    }

    /// Emit one arm's ALU chain unconditionally, answering with the register
    /// holding the value the arm would have stored.
    ///
    /// A VALUE AN EMITTER HOLDS IN A LOCAL VARIABLE IS HELD IN NO MAP AT ALL,
    /// AND THAT IS THE ENTRY THE RECLAIM BIDS FOR (GAP-148).
    ///
    /// The record `emitIfConverted` makes for `dst` states the rule: an entry in
    /// `spilled_regs` whose `gp_reg_owner` is null is, to `reclaimSpilledReg`, a
    /// stale name register staging left behind and free to take, while an owned
    /// entry is a live value's only remaining location. Both if-conversion
    /// emitters hold OTHER registers across evaluation that allocates, and each
    /// of those is the same unowned live value:
    ///
    ///   - `emitIfConverted`'s `old`, the binding's current value at step (1).
    ///     A frame-homed binding answers through `loadGpStackLocal`, which is
    ///     `allocReg` plus an `ldr` and records nothing; `allocRegExcluding(old)`
    ///     covers it for step (2) and the condition at step (3) excludes
    ///     nothing.
    ///   - `emitIfConvertedTwoSided`'s `rt` and `re` for an arm with NO ops,
    ///     which answer `evalDnirValue(store.lhs)` — an immediate is `allocReg`
    ///     plus `emitMovImm`, a frame local is `loadGpStackLocal`, and neither
    ///     leaves an owner behind. That register then carries the arm's value
    ///     across the OTHER arm's allocations, the destination's, and the
    ///     condition's.
    ///   - THE LEFT OF ANY TWO OPERANDS EVALUATED IN SEQUENCE: `emitIfConverted`'s
    ///     `a` across `plan.op.rhs`, and `clhs` across `c.rhs` in BOTH emitters.
    ///     The right operand's evaluation excludes nothing, so the register the
    ///     reclaim hands it is the left operand's own, and the instruction that
    ///     follows reads its right operand twice.
    ///   - THE ORDINARY INTEGER BINOP'S OPERANDS, in `compileDnirInstr`. The
    ///     same two-operand sequence outside any if-conversion, plus the
    ///     destination's `allocReg` after it and, for `idiv`/`mod`,
    ///     `emitFlooredDivRem`'s three `allocRegExcluding(dst)` — none of which
    ///     excludes an operand. `ensureRegLive` inside every register-form
    ///     emitter reloads a merely SPILLED operand and cannot reload a
    ///     reclaimed one: the reclaim removed the entry it keys on.
    ///
    /// In each case an allocation that fails under gate transport runs the whole
    /// cascade — every free scan skips `spilled_regs`, so a spill frees nothing
    /// and the passes walk x28..x9 and then x7..x0 spilling everything, the held
    /// register among them — and ends at the reclaim, which drops the entry,
    /// releases the slot, claims the register and hands it back as the
    /// allocation's own scratch. `emitMovImm` then writes over the value the
    /// emitter is still holding, and the `csel` selects against it. A wrong
    /// answer with no diagnostic.
    ///
    /// The hold is the ownership record and nothing else. The id is synthetic
    /// because the register stands for no DNIR value — a zero-op arm has no temp
    /// of its own and the local's id is not one — and a synthetic id carries no
    /// `value_free_at` entry, which is exactly what `dst`'s carrier relies on.
    /// It is dropped by name before the emitter's own release, so the register
    /// returns to the pool on the same line, at the same index, as it did
    /// before; `sweepGpLive` does not run inside a collapsed window, so nothing
    /// observes it in between. Outside gate transport `spilled_regs` is empty,
    /// `reclaimSpilledReg` is unreachable, and the hold is a record no reader
    /// consults.
    ///
    /// Answers whether a record was minted, so the drop touches only what this
    /// held: a register that is a home, a pin, outside the allocatable band or
    /// ALREADY owned is somebody else's and is left exactly as found.
    ///
    /// Not the closure — closure is authoritative `register`/`frame` assignment
    /// before emission, per this gap's record, under which a held value's
    /// location is a fact the assignment carries rather than a claim an emitter
    /// keeps in a local variable across an allocator that may bid for it.
    fn holdReg(
        self: *Arm64Compiler,
        reg: u5,
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
    ) bool {
        if (reg < 9 or reg >= 29) return false;
        if (reg == platform_reserved_reg) return false;
        if (self.gp_home_regs[reg]) return false;
        if (Arm64Compiler.regIsPinned(pinned, reg)) return false;
        if (self.gp_reg_owner[reg] != null) return false;
        self.gp_reg_owner[reg] = self.synth_value_next;
        self.synth_value_next += 1;
        return true;
    }

    /// THE `madd` FUSION IS DELIBERATELY NOT APPLIED HERE. `mulAddFusible`
    /// would fold `mul ; add` into one `madd`, which is FEWER INSTRUCTIONS and
    /// MORE LATENCY — and latency is what the guard in
    /// `ifConvArmOpAdmissibleTwoSided` refuses. Folding here would reintroduce
    /// a hardware multiply into a speculated arm through the back door, for a
    /// `x * 4 + 1` the whitelist admitted only because the multiply reduces to
    /// a shift. Instruction count is not the axis this window is bounded on.
    fn emitIfConvArm(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        ops: []const dnir.Instr,
        store: dnir.Instr,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        owned: *bool,
        at: u32,
    ) Error!u5 {
        if (ops.len == 0) {
            owned.* = false;
            return try self.evalDnirValue(temps, store.lhs);
        }
        for (ops) |op| {
            try self.compileDnirInstr(temps, pinned, op, branch_patches, null, at);
            const t = op.result.?;
            if (temps.get(t)) |r| {
                if (r >= 9 and r < 29 and r != platform_reserved_reg and !self.gp_home_regs[r]) {
                    self.gp_reg_owner[r] = t;
                }
            }
        }
        const last = ops[ops.len - 1].result.?;
        owned.* = true;
        return temps.get(last) orelse return self.refuseWith(@src(), "ifconv-arm-value-lost");
    }

    /// Emit the `csel` form of a recognized two-sided `if`.
    ///
    /// ORDER IS LOAD-BEARING, exactly as in `emitIfConverted`: both arms are
    /// computed first (either may write NZCV — a comparison arm is `cmp`+`cset`
    /// — and a spill may be emitted for either), THEN the condition's `cmp`,
    /// then the select. Between the two only `ensureRegLive`'s `ldr` may
    /// appear, and a load does not touch the flags.
    fn emitIfConvertedTwoSided(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        plan: TwoSidedPlan,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        at: u32,
    ) Error!void {
        var then_owned = false;
        var else_owned = false;
        const rt = try self.emitIfConvArm(temps, pinned, plan.then_ops, plan.then_store, branch_patches, &then_owned, at);
        // The then-arm's register must survive the else-arm's allocations. It
        // does because `emitIfConvArm` leaves it claimed (`allocReg` sets
        // `used_regs`) and no sweep runs inside a collapsed window — the driver
        // sweeps once per CONSUMED index, after this emitter returns.
        //
        // A CLAIM IS NOT AN OWNER, AND SURVIVING THE ALLOCATION IS NOT THE SAME
        // AS SURVIVING THE CASCADE (GAP-148). `used_regs` keeps the free scans
        // off this register; it is also the exact bit the spill passes require,
        // so under gate transport an exhausted else-arm allocation spills it and
        // reaches `reclaimSpilledReg` — which retires an entry with a null owner
        // and hands the register back as the else arm's own scratch. An arm with
        // OPS leaves an owner behind (`emitIfConvArm` records the last op's
        // result), so the reclaim already passes over it. An arm with NO ops
        // answers `evalDnirValue(store.lhs)`, and an immediate or a frame local
        // is a fresh register no map yet names. `holdReg` is that missing
        // record and refuses to mint one for anything already owned, so the
        // op-carrying arm is untouched.
        const rt_held = self.holdReg(rt, pinned);
        const re = try self.emitIfConvArm(temps, pinned, plan.else_ops, plan.else_store, branch_patches, &else_owned, at);
        // The else arm's answer is held for the same reason across what remains:
        // the destination's allocation and the condition's.
        const re_held = self.holdReg(re, pinned);

        // The destination. Reusing the then-arm's own scratch is free — `csel`
        // writes its destination and `xd == xn` is legal — but only when that
        // register belongs to this window. A zero-op arm answers with somebody
        // else's home or pinned register, and writing there is the clobber.
        const dst = if (then_owned and rt >= 9 and rt < 29 and rt != platform_reserved_reg and
            !self.gp_home_regs[rt] and !Arm64Compiler.regIsPinned(pinned, rt))
            rt
        else
            try self.allocRegExcluding(rt);

        // THE OWNER IS RECORDED WHEN THE REGISTER IS CHOSEN, NOT AFTER THE
        // SELECT (GAP-148) — the sibling of the record `emitIfConverted` makes
        // at its step (2), for the same reader and the same reason.
        //
        // The carrier id is minted here rather than below because the record
        // needs it here: between this line and the `csel` the condition
        // allocates, and under gate transport an allocation that fails spills
        // every register and ends at `reclaimSpilledReg`, whose skip list
        // treats an entry with a NULL owner as a stale name free to take. `dst`
        // under a null owner is exactly that entry, and when `dst == rt` the
        // register the reclaim would hand back as scratch is the then-arm's own
        // answer, which the condition's `emitMovImm` then writes over.
        //
        // Nothing observes the move. `sweepGpLive` does not run inside a
        // collapsed window, the releases below are guarded against `dst` by
        // name, and the carrier still carries no `value_free_at` entry — so the
        // driver's next sweep retires `dst` immediately after the store, which
        // is the live range the note at the store already states. Outside gate
        // transport `spilled_regs` is empty and this is the same record at a
        // different line.
        const carrier = self.synth_value_next;
        self.synth_value_next += 1;
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = carrier;
        }

        // The condition. Nothing below this line may write the flags.
        var then_cond: Condition = undefined;
        if (plan.cmp) |c| {
            const clhs = try self.evalDnirValue(temps, c.lhs);
            // THE COMPARE'S LEFT OPERAND, HELD ACROSS THE RIGHT ONE'S
            // EVALUATION (GAP-148) — `emitIfConverted`'s condition states this
            // in full and it is the same three lines, because it is the same
            // sentence about the same allocator. Here `rt`, `re` and `dst` are
            // all held or owned by the time the condition runs, so `clhs` is
            // once again the only register the reclaim can still take, and
            // taking it makes the `cmp` read its right operand twice.
            const clhs_held = self.holdReg(clhs, pinned);
            const crhs = try self.evalDnirValue(temps, c.rhs);
            if (clhs_held) self.gp_reg_owner[clhs] = null;
            try self.emitCmpReg(clhs, crhs);
            if (clhs != rt and clhs != re and clhs != dst and !Arm64Compiler.regIsPinned(pinned, clhs)) self.releaseReg(clhs);
            if (crhs != rt and crhs != re and crhs != dst and !Arm64Compiler.regIsPinned(pinned, crhs)) self.releaseReg(crhs);
            then_cond = comparisonCondition(c.binop).?;
        } else {
            const cr = try self.evalDnirValue(temps, plan.br.lhs);
            try self.emitCmpZero(cr);
            if (cr != rt and cr != re and cr != dst and !Arm64Compiler.regIsPinned(pinned, cr)) self.releaseReg(cr);
            then_cond = .ne;
        }
        // `br when_false -> else` leaves the THEN arm on the condition being
        // true; `when_true -> else` is its mirror.
        if (plan.br.branch_condition == .when_true) then_cond = invertCondition(then_cond);

        // THE SELECT'S REGISTERS ARE ONLY WHERE ITS VALUES ARE WHILE
        // `spilled_regs` DOES NOT NAME THEM (GAP-148) — `emitIfConverted`'s
        // step (4) states this in full; here there are three of them because
        // both arms are computed before the condition, and each of the three is
        // established by a step a later step can spill. `ensureRegLive` is the
        // reload into the register every map already names, and an `ldr` is the
        // one instruction this emitter's order permits between the compare and
        // the select. A no-op on every unspilled select.
        try self.ensureRegLive(rt);
        try self.ensureRegLive(re);
        try self.ensureRegLive(dst);
        try self.emitCselReg(dst, rt, re, then_cond);

        // THE HOLD ENDS WHERE THE ALLOCATIONS DO. `releaseReg` returns above an
        // owned register, so a hold left standing would keep a zero-op arm's
        // scratch claimed past the release the unrepaired emitter performed
        // here. Dropping it by name first makes the four releases below the
        // same four releases. Neither hold can be `dst`: `dst == rt` only when
        // `then_owned`, which mints no hold, and `allocRegExcluding` cannot
        // answer with `re`, which is claimed.
        if (rt_held) self.gp_reg_owner[rt] = null;
        if (re_held) self.gp_reg_owner[re] = null;

        // Release whatever the select consumed and this window owns.
        if (re != dst and else_owned and !Arm64Compiler.regIsPinned(pinned, re)) self.releaseReg(re);
        if (!else_owned and re != dst and !self.gp_home_regs[re] and !Arm64Compiler.regIsPinned(pinned, re)) self.releaseReg(re);
        if (rt != dst and then_owned and !Arm64Compiler.regIsPinned(pinned, rt)) self.releaseReg(rt);
        if (!then_owned and rt != dst and !self.gp_home_regs[rt] and !Arm64Compiler.regIsPinned(pinned, rt)) self.releaseReg(rt);

        // THE STORE, ONCE, through the ordinary path — the binding keeps its
        // home or its frame slot exactly as it had it. This fold changes WHAT
        // is stored, never WHERE.
        // The store reads a SYNTHETIC value id rather than either arm's own
        // temp. Locals and temps share one id counter, so a zero-op arm has no
        // temp of its own to borrow and the local's id is not one; a fresh id
        // past every id this function uses belongs to nobody. It carries no
        // `value_free_at` entry, so the driver's next sweep retires `dst`
        // immediately after the store — which is exactly its live range. It is
        // minted above the condition rather than here, because the ownership
        // record it carries is what keeps the reclaim off `dst` while the
        // condition allocates.
        var store = plan.then_store;
        store.lhs = .{ .temp = carrier };
        try temps.put(self.alloc, carrier, dst);
        try self.compileDnirInstr(temps, pinned, store, branch_patches, null, at);
        self.ifconv_admitted += 1;
    }

    /// Peephole precondition for folding `mul -> T ; add(T, c) -> D` into a
    /// single `madd D, a, b, c` (a*b + c). Admissible only when the product is a
    /// pure integer `mul` whose result feeds the immediately following pure
    /// integer `add` as exactly one operand and has no other reader — so the
    /// intermediate register the fold erases held nothing else. `add` is
    /// commutative, so either operand may be the product; `sub` is intentionally
    /// excluded (only `c - a*b` maps to `msub`, not `a*b - c`).
    fn mulAddFusible(self: *const Arm64Compiler, ins: dnir.Instr, nx: dnir.Instr, flat_idx: u32) bool {
        if (ins.op != .binop or ins.binop != .mul) return false;
        if (ins.ty == .f64 or self.cur_func_float) return false;
        // THE INTERMEDIATE PRODUCT'S OWN REFIT IS ERASED BY THE FUSION, so a
        // product that must be projected before it is added cannot be fused —
        // `(a * b)` narrowed to `u8` and then added is not `madd`'s answer.
        // The SUM's refit is a different matter and is preserved rather than
        // refused: see `emitFusedMulAdd`.
        //
        // THE ONE EXCEPTION IS NOT A TOLERANCE, IT IS AN IDENTITY. When BOTH
        // the product and the sum want the unsigned-32 projection, the 32-bit
        // fused form performs both at once:
        //
        //     ((a*b mod 2^32) + c) mod 2^32  ==  (a*b + c) mod 2^32
        //
        // because mod-2^32 is a ring homomorphism and `mul` and `add` are both
        // low-32 closed (`lowThirtyTwoExact`). So `madd Wd,Wn,Wm,Wa` is the
        // exact answer for both writes in ONE instruction. Without this the
        // repair costs a real instruction on the recurrence of every narrow
        // multiply-accumulate loop — MEASURED on an FNV-style `h = h * k + i`
        // over `u32`: 6 instructions per iteration became 7, and this returns
        // it to 6 with the answer the law demands (171, where the unrepaired
        // fusion answered 168 and no compiler should ever have answered).
        if (narrowFit(ins.ty) != null and
            !(wForm32(ins.ty, ins.binop) and wForm32(nx.ty, nx.binop))) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        const t = ins.result orelse return false;
        if (nx.op != .binop or nx.binop != .add) return false;
        if (nx.ty == .f64) return false;
        if (nx.application != null or nx.relation != null or nx.value != null) return false;
        if (self.valueIsFp(nx.lhs) or self.valueIsFp(nx.rhs)) return false;
        if (nx.result == null) return false;
        const lhs_is_t = nx.lhs == .temp and nx.lhs.temp == t;
        const rhs_is_t = nx.rhs == .temp and nx.rhs.temp == t;
        if (lhs_is_t == rhs_is_t) return false; // both or neither — not a clean accumulate
        // The product may have exactly one reader: this add. A widened
        // (loop-crossing) or second-consumer range keeps the last use past the
        // add, and the conservative answer is to materialize the product.
        const last = self.value_free_at.get(t) orelse return false;
        return last == flat_idx + 1;
    }

    fn absdFusible(
        self: *const Arm64Compiler,
        ins: dnir.Instr,
        s1: dnir.Instr,
        s2: dnir.Instr,
        s3: dnir.Instr,
        s4: dnir.Instr,
        flat_idx: u32,
    ) bool {
        if (ins.op != .binop or ins.binop != .sub) return false;
        if (ins.ty == .f64 or self.cur_func_float) return false;
        if (narrowFit(ins.ty) != null) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        const t1 = ins.result orelse return false;
        if (s1.op != .binop or s1.binop != .shr) return false;
        if (s1.ty == .f64) return false;
        if (narrowFit(s1.ty) != null) return false;
        if (s1.application != null or s1.relation != null or s1.value != null) return false;
        if (s1.lhs != .temp or s1.lhs.temp != t1) return false;
        if (s1.rhs != .i64 or s1.rhs.i64 != 63) return false;
        const t2 = s1.result orelse return false;
        if (s2.op != .binop or s2.binop != .sub) return false;
        if (s2.ty == .f64) return false;
        if (narrowFit(s2.ty) != null) return false;
        if (s2.application != null or s2.relation != null or s2.value != null) return false;
        if (s2.lhs != .i64 or s2.lhs.i64 != 0) return false;
        if (s2.rhs != .temp or s2.rhs.temp != t2) return false;
        const t3 = s2.result orelse return false;
        if (s3.op != .binop or s3.binop != .bxor) return false;
        if (s3.ty == .f64) return false;
        if (narrowFit(s3.ty) != null) return false;
        if (s3.application != null or s3.relation != null or s3.value != null) return false;
        if (s3.lhs != .temp or s3.lhs.temp != t1) return false;
        if (s3.rhs != .temp or s3.rhs.temp != t3) return false;
        const t4 = s3.result orelse return false;
        if (s4.op != .binop or s4.binop != .add) return false;
        if (s4.ty == .f64) return false;
        if (narrowFit(s4.ty) != null) return false;
        if (s4.application != null or s4.relation != null or s4.value != null) return false;
        if (s4.lhs != .temp or s4.lhs.temp != t4) return false;
        if (s4.rhs != .temp or s4.rhs.temp != t2) return false;
        if (s4.result == null) return false;
        const last1 = self.value_free_at.get(t1) orelse return false;
        if (last1 != flat_idx + 3) return false;
        const last2 = self.value_free_at.get(t2) orelse return false;
        if (last2 != flat_idx + 4) return false;
        const last3 = self.value_free_at.get(t3) orelse return false;
        if (last3 != flat_idx + 3) return false;
        const last4 = self.value_free_at.get(t4) orelse return false;
        if (last4 != flat_idx + 4) return false;
        return true;
    }

    fn emitFusedAbsd(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        s4: dnir.Instr,
    ) Error!void {
        const ra = try self.evalDnirValue(temps, ins.lhs);
        const rb = try self.evalDnirValue(temps, ins.rhs);
        const t5 = s4.result.?;
        const rd = try self.allocReg();
        try self.emitSubsReg(rd, ra, rb);
        try self.emitCsneg(rd, rd, rd, 0xa);
        try temps.put(self.alloc, t5, rd);
    }

    /// Peephole: `t = div(X, 2^k)` (dividend proved non-negative, so the
    /// backend realizes it as `lsr`) followed by `d = band(t, 2^w - 1)` is
    /// one `ubfx d, X, #k, #w`. The identity is exact for every 64-bit X:
    /// `ubfx` computes `(X >> k) & ((1<<w)-1)` by definition, which is what
    /// the `lsr`+`and` pair computes. The preconditions are not tolerances:
    ///
    /// - `ins` is the `.div` (not `.idiv`/`.mod`), with a constant
    ///   power-of-two divisor, and the dividend proved non-negative
    ///   (`ins.dividend.proved()`) — the same proof the shift realization
    ///   itself demands: a negative dividend's floored quotient is an
    ///   arithmetic shift, and `ubfx` is the logical form;
    /// - the mask is a low run `2^w - 1` (`lowMaskWidth`), so the `and` is
    ///   the logical-immediate form;
    /// - `k + w <= 64`, the UBFM field constraint;
    /// - the shift's type is full-width (`narrowFit(ins.ty) == null`): a
    ///   narrowed intermediate would truncate bits the mask keeps, and the
    ///   fusion must not move that truncation;
    /// - the shift's temp has exactly one reader (this `and`), the same
    ///   last-use gate as the `madd` fusion.
    ///
    /// The `and`'s own refit is preserved unchanged: the fused instruction
    /// produces bit-for-bit what the `and` produced, so it owes the same
    /// narrowing.
    fn ubfxFusible(self: *const Arm64Compiler, ins: dnir.Instr, nx: dnir.Instr, flat_idx: u32) bool {
        if (ins.op != .binop or ins.binop != .div) return false;
        if (ins.ty == .f64 or self.cur_func_float) return false;
        if (narrowFit(ins.ty) != null) return false;
        if (!ins.dividend.proved()) return false;
        if (ins.application != null or ins.relation != null or ins.value != null) return false;
        const t = ins.result orelse return false;
        const ck = switch (ins.rhs) {
            .i64 => |v| v,
            else => return false,
        };
        const k = powerOfTwoShift(ck) orelse return false;
        if (nx.op != .binop or nx.binop != .band) return false;
        if (nx.ty == .f64) return false;
        if (nx.application != null or nx.relation != null or nx.value != null) return false;
        if (nx.result == null) return false;
        const t_is_lhs = nx.lhs == .temp and nx.lhs.temp == t;
        const t_is_rhs = nx.rhs == .temp and nx.rhs.temp == t;
        if (t_is_lhs == t_is_rhs) return false;
        const mask_val = if (t_is_lhs) nx.rhs else nx.lhs;
        const cm = switch (mask_val) {
            .i64 => |v| v,
            else => return false,
        };
        const w = lowMaskWidth(cm) orelse return false;
        if (@as(u32, k) + @as(u32, w) > 64) return false;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(nx.lhs) or self.valueIsFp(nx.rhs)) return false;
        const last = self.value_free_at.get(t) orelse return false;
        return last == flat_idx + 1;
    }

    /// Named variant of the `ubfx` peephole, following the R15
    /// (`namedCompareBranchFusible`) pattern: the shift-then-mask passes
    /// through a named local —
    /// `div(X, 2^k) -> T ; store_local L <- T ; band(L, 2^w - 1) -> D ;
    /// store_local L <- D` — because `L = X >> k ; L = L & w` names the
    /// intermediate. Folds to the same `ubfx D, X, #k, #w` the unnamed form
    /// gets. brm2's bit-test `c = (x & 2147483647) / 65536 ; c = c & 1`
    /// is this shape: the two names force the unnamed fusion's adjacency
    /// test to fail.
    ///
    /// Admissible only when, over the whole function:
    /// - the div meets every `ubfxFusible` ground (`.div`,
    ///   constant power-of-two divisor, dividend proved non-negative, full
    ///   width, no f64) — the dividend proof is load-bearing, not a
    ///   tolerance: without it the original is a floored division of a
    ///   possibly-negative value, not a logical shift;
    /// - the div temp's single reader is the naming store
    ///   (`singleReaderByTightDef`, the R15 ground);
    /// - the band reads exactly the named local on one side and a low-run
    ///   immediate mask on the other, `k + w <= 64`;
    /// - the band's store writes back to the SAME local: the intermediate
    ///   shifted value is then unobservable. The three consumed instructions
    ///   are straight-line by shape and no branch lands inside the window,
    ///   so the window executes atomically — every read before it sees the
    ///   pre-window value in both versions, every read after the band's
    ///   store sees the band's value in both;
    /// - neither the div nor the naming store reads the local (conservative:
    ///   the value would still be the same, but the census stays a simple
    ///   positional check);
    /// - the three consumed instructions carry no application lineage of
    ///   their own to lose (the fused instruction is emitted without it,
    ///   exactly like the unnamed form).
    /// Where it stops: a different-name write-back (`e = c & 1`), any
    /// lineage on a consumed instruction, a non-low-run mask, `k + w > 64`,
    /// a narrowed div, or any branch landing in the consumed window.
    fn namedUbfxFusible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        div_ins: dnir.Instr,
        st: dnir.Instr,
        nx: dnir.Instr,
        st2: dnir.Instr,
        flat_idx: u32,
    ) bool {
        if (div_ins.op != .binop or div_ins.binop != .div) return false;
        if (div_ins.ty == .f64 or self.cur_func_float) return false;
        if (narrowFit(div_ins.ty) != null) return false;
        if (!div_ins.dividend.proved()) return false;
        if (div_ins.application != null or div_ins.relation != null or div_ins.value != null) return false;
        const t = div_ins.result orelse return false;
        const ck = switch (div_ins.rhs) {
            .i64 => |v| v,
            else => return false,
        };
        const k = powerOfTwoShift(ck) orelse return false;
        if (self.valueIsFp(div_ins.lhs) or self.valueIsFp(div_ins.rhs)) return false;

        if (st.op != .store_local) return false;
        if (st.ty == .f64) return false;
        if (st.application != null or st.relation != null or st.value != null) return false;
        if (st.lhs != .temp or st.lhs.temp != t) return false;
        const l = st.result orelse return false;

        if (nx.op != .binop or nx.binop != .band) return false;
        if (nx.ty == .f64) return false;
        if (nx.application != null or nx.relation != null or nx.value != null) return false;
        if (nx.result == null) return false;
        const l_is_lhs = nx.lhs == .local and nx.lhs.local == l;
        const l_is_rhs = nx.rhs == .local and nx.rhs.local == l;
        if (l_is_lhs == l_is_rhs) return false;
        const mask_val = if (l_is_lhs) nx.rhs else nx.lhs;
        const cm = switch (mask_val) {
            .i64 => |v| v,
            else => return false,
        };
        const w = lowMaskWidth(cm) orelse return false;
        if (@as(u32, k) + @as(u32, w) > 64) return false;
        if (self.valueIsFp(nx.lhs) or self.valueIsFp(nx.rhs)) return false;

        // Same-name write-back: the band's store must overwrite the local
        // the div's store named. The shifted intermediate then has no
        // observer left, and the band's value reaches every later reader
        // through the kept store, identically in both versions.
        if (st2.op != .store_local) return false;
        if (st2.ty == .f64) return false;
        if (st2.result == null or st2.result.? != l) return false;
        const d = nx.result.?;
        if (st2.lhs != .temp or st2.lhs.temp != d) return false;

        // Neither the div nor the naming store may read the local: its value
        // is being replaced under it. (The band's own read is the shape; reads
        // before the window and after the band's store are unaffected — see the
        // atomicity argument above.)
        if (dnirInstrReadsValue(div_ins, true, l)) return false;
        if (dnirInstrReadsValue(st, true, l)) return false;

        // The div temp's only reader is the naming store (R15 ground).
        if (!self.singleReaderByTightDef(t, flat_idx)) return false;

        // Nothing may branch into the consumed window: every consumed index
        // collapses onto one code offset.
        if (dnirBranchLandsWithin(f, flat_idx, flat_idx + 2)) return false;
        return true;
    }

    /// Do all bits `[k, k+w)` of the i64 mask `m` read 1? The ubfx pre-mask
    /// peephole uses this to prove a leading `and` cannot change any bit the
    /// fused `ubfx` extracts.
    fn maskCoversExtractedBits(m: i64, k: u6, w: u6) bool {
        const u: u64 = @bitCast(m);
        const width_mask: u64 = (@as(u64, 1) << w) - 1;
        return ((u >> k) & width_mask) == width_mask;
    }

    /// Pre-mask elision for the `ubfx` fusion. `band(X, M) -> Tb` immediately
    /// followed by `div(Tb, 2^k) -> T`, where the div plus its trailing
    /// instructions already fuse to `ubfx D, Tb, #k, #w` (either the unnamed
    /// or the R15-named form): when every bit the `ubfx` extracts is already
    /// 1 in M, the leading `and` is dead. `((X & M) >> k) & ((1<<w)-1)`
    /// reads exactly the bits `[k, k+w)` of `X & M`, and each of those is
    /// `(bit of X) & 1 = (bit of X)`, so the fused `ubfx` can read X
    /// directly and the `and` is not emitted.
    ///
    /// Admitted only when every ground below holds; anything unproved
    /// declines:
    /// - `b.instrs[bi]` is a `.band` with an `.i64` mask M on one side and
    ///   X on the other, integer-typed, no f64, carrying no application
    ///   lineage of its own to lose (the fused instruction is emitted
    ///   without it, exactly like the underlying fusion);
    /// - the immediately following instruction is a `.div` whose dividend
    ///   is exactly Tb (adjacency keeps the liveness extension exact);
    /// - the div plus its trailing instructions satisfy `ubfxFusible` or
    ///   `namedUbfxFusible` at the div's position — every ground of the
    ///   underlying fusion (dividend proof, single readers, no branches
    ///   into its window, lineage) is re-checked here, not assumed;
    /// - M covers the extracted bits `[k, k+w)`;
    /// - Tb's only reader is the div (`singleReaderByTightDef`, the R15
    ///   ground the fusions themselves use);
    /// - no branch lands on the elided `and` itself.
    /// Where it stops: a non-immediate mask, a non-adjacent div, any
    /// extracted bit the mask clears, a reused Tb, lineage on the `and`,
    /// or any branch into the elided position.
    fn ubfxPremaskElidable(
        self: *const Arm64Compiler,
        f: dnir.Function,
        b: dnir.Block,
        bi: usize,
        flat_idx: u32,
    ) ?struct { t_band: u32, x: dnir.Value } {
        const ins = b.instrs[bi];
        if (ins.op == .binop and ins.binop == .band) {
        }
        if (ins.op != .binop or ins.binop != .band) return null;
        if (ins.ty == .f64) return null;
        if (ins.application != null or ins.relation != null or ins.value != null) return null;
        if (narrowFit(ins.ty) != null) return null;
        const t_band = ins.result orelse return null;
        const lhs_is_mask = ins.lhs == .i64;
        const rhs_is_mask = ins.rhs == .i64;
        if (lhs_is_mask == rhs_is_mask) return null;
        const m: i64 = if (lhs_is_mask) ins.lhs.i64 else ins.rhs.i64;
        const x: dnir.Value = if (lhs_is_mask) ins.rhs else ins.lhs;
        if (self.valueIsFp(ins.lhs) or self.valueIsFp(ins.rhs)) return null;
        if (bi + 1 >= b.instrs.len) return null;
        const div_ins = b.instrs[bi + 1];
        if (div_ins.op != .binop or div_ins.binop != .div) return null;
        if (div_ins.lhs != .temp or div_ins.lhs.temp != t_band) return null;
        const ck = switch (div_ins.rhs) {
            .i64 => |v| v,
            else => return null,
        };
        const k = powerOfTwoShift(ck) orelse return null;
        // The underlying fusion must fire at the div's position; re-derive
        // the extracted width from the trailing band it consumes.
        var w: u6 = undefined;
        if (bi + 2 < b.instrs.len and self.ubfxFusible(div_ins, b.instrs[bi + 2], flat_idx + 1)) {
            const trailing = b.instrs[bi + 2];
            const t = div_ins.result orelse return null;
            const t_is_lhs = trailing.lhs == .temp and trailing.lhs.temp == t;
            const t_is_rhs = trailing.rhs == .temp and trailing.rhs.temp == t;
            if (t_is_lhs == t_is_rhs) return null;
            const mask_val = if (t_is_lhs) trailing.rhs else trailing.lhs;
            const cm = switch (mask_val) {
                .i64 => |v| v,
                else => return null,
            };
            w = lowMaskWidth(cm) orelse return null;
        } else if (bi + 4 < b.instrs.len and self.namedUbfxFusible(f, div_ins, b.instrs[bi + 2], b.instrs[bi + 3], b.instrs[bi + 4], flat_idx + 1)) {
            const trailing = b.instrs[bi + 3];
            const l_is_lhs = trailing.lhs == .local;
            const l_is_rhs = trailing.rhs == .local;
            if (l_is_lhs == l_is_rhs) return null;
            const mask_val = if (l_is_lhs) trailing.rhs else trailing.lhs;
            const cm = switch (mask_val) {
                .i64 => |v| v,
                else => return null,
            };
            w = lowMaskWidth(cm) orelse return null;
        } else {
            return null;
        }
        if (!maskCoversExtractedBits(m, k, w)) return null;
        if (!self.singleReaderByTightDef(t_band, flat_idx)) return null;
        if (dnirBranchLandsWithin(f, flat_idx, flat_idx)) return null;
        return .{ .t_band = t_band, .x = x };
    }

    /// Precondition for folding the divmod idiom
    ///   `div(X, k) -> T ; store_local Lq <- T ; mul(Lq, k) -> M ; sub(X, M) -> D`
    /// into one magic-division sequence that materializes BOTH the corrected
    /// quotient (for the quotient local) and the already-computed floored
    /// residual (for `D`). The separate `mul`/`sub` never execute; their
    /// results are the sequence's own byproducts.
    ///
    /// Admitted only when every ground below holds; anything unproved declines:
    /// * the div is `.div`/`.idiv`, integer-typed, over a runtime dividend
    ///   (a `.local` or `.temp` — a literal dividend would already have been
    ///   constant-folded), and `magicFlooredDivisor` admits its `.i64`
    ///   divisor `k`: positive and non-power-of-two, exactly the sequence
    ///   whose byproduct residual the fusion reuses. A divisor the magic
    ///   sequence refuses keeps its existing realization.
    /// * the mul multiplies the quotient local by the SAME literal `k`
    ///   (either operand order);
    /// * the sub subtracts the mul's temp from the SAME dividend value the
    ///   div read (union equality on the operand);
    /// * the div temp's only reader is the naming store, and the mul temp's
    ///   only reader is the sub — strict `value_free_at` index tests, the
    ///   ground `mulAddFusible` uses. A reused id (the loop unroller reuses
    ///   them) widens the map and declines;
    /// * neither the div nor the naming store reads the quotient local: its
    ///   value is replaced under the window (the mul's read is the shape,
    ///   and the sub's minuend is tied to the div's dividend above, so a
    ///   quotient-local dividend is refused here rather than misread later);
    /// * nothing branches into the consumed window.
    /// The quotient local keeps its store — the emitter runs it as written,
    /// since the name is read later (e.g. `x = q`) — and the remainder temp
    /// is materialized for whatever consumes it; only the mul and the sub
    /// are erased. The dividend is never mutated by the window.
    fn divmodFusible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        div_ins: dnir.Instr,
        st_q: dnir.Instr,
        mul_ins: dnir.Instr,
        sub_ins: dnir.Instr,
        flat_idx: u32,
    ) bool {
        if (div_ins.op != .binop) return false;
        if (div_ins.binop != .div and div_ins.binop != .idiv) return false;
        if (div_ins.ty == .f64) return false;
        if (div_ins.application != null or div_ins.relation != null or div_ins.value != null) return false;
        if (div_ins.result == null) return false;
        if (self.cur_func_float) return false;
        if (div_ins.lhs != .local and div_ins.lhs != .temp) return false;
        if (div_ins.rhs != .i64) return false;
        const k = div_ins.rhs.i64;
        if (magicFlooredDivisor(k) == null) return false;

        // `store_local Lq <- T`.
        if (st_q.op != .store_local) return false;
        const t_q = div_ins.result.?;
        if (st_q.lhs != .temp or st_q.lhs.temp != t_q) return false;
        const lq = st_q.result orelse return false;

        // `mul(Lq, k) -> M`, either operand order, the same literal `k`.
        if (mul_ins.op != .binop or mul_ins.binop != .mul) return false;
        if (mul_ins.ty == .f64) return false;
        if (mul_ins.application != null or mul_ins.relation != null or mul_ins.value != null) return false;
        if (mul_ins.result == null) return false;
        const t_m = mul_ins.result.?;
        const mul_ok = (mul_ins.lhs == .local and mul_ins.lhs.local == lq and
            mul_ins.rhs == .i64 and mul_ins.rhs.i64 == k) or
            (mul_ins.rhs == .local and mul_ins.rhs.local == lq and
                mul_ins.lhs == .i64 and mul_ins.lhs.i64 == k);
        if (!mul_ok) return false;

        // `sub(X, M) -> D`: the minuend is the div's dividend, the subtrahend
        // the mul's temp.
        if (sub_ins.op != .binop or sub_ins.binop != .sub) return false;
        if (sub_ins.ty == .f64) return false;
        if (sub_ins.application != null or sub_ins.relation != null or sub_ins.value != null) return false;
        if (sub_ins.result == null) return false;
        // The sub's minuend is the div's dividend: same tag and same id.
        // (`div_ins.lhs` is already proved `.local`/`.temp` above.)
        const same_dividend = switch (div_ins.lhs) {
            .local => |l| sub_ins.lhs == .local and sub_ins.lhs.local == l,
            .temp => |t| sub_ins.lhs == .temp and sub_ins.lhs.temp == t,
            else => false,
        };
        if (!same_dividend) return false;
        if (sub_ins.rhs != .temp or sub_ins.rhs.temp != t_m) return false;

        // The div and the naming store may not read the quotient local: its
        // value is replaced under the window.
        if (dnirInstrReadsValue(div_ins, true, lq)) return false;
        if (dnirInstrReadsValue(st_q, true, lq)) return false;

        // The div temp's only reader is the naming store; the mul temp's only
        // reader is the sub.
        const q_last = self.value_free_at.get(t_q) orelse return false;
        if (q_last != flat_idx + 1) return false;
        const m_last = self.value_free_at.get(t_m) orelse return false;
        if (m_last != flat_idx + 3) return false;

        // Nothing may branch into the consumed window: every consumed index
        // collapses onto one code offset. A branch TO the div itself (the
        // loop back edge) is fine — it lands at the start of the fused
        // sequence — but a branch into the middle (the store, mul, or sub)
        // would land mid-sequence.
        if (dnirBranchLandsWithin(f, flat_idx + 1, flat_idx + 3)) return false;
        return true;
    }

    fn dnirValuesEqual(a: dnir.Value, b: dnir.Value) bool {
        return switch (a) {
            .local => |x| b == .local and b.local == x,
            .temp => |x| b == .temp and b.temp == x,
            .i64 => |x| b == .i64 and b.i64 == x,
            else => false,
        };
    }

    fn divmodRuntimeFusible(
        self: *const Arm64Compiler,
        f: dnir.Function,
        div_ins: dnir.Instr,
        st_q: dnir.Instr,
        mul_ins: dnir.Instr,
        sub_ins: dnir.Instr,
        flat_idx: u32,
    ) bool {
        if (div_ins.op != .binop) return false;
        if (div_ins.binop != .div) return false;
        if (div_ins.ty == .f64) return false;
        if (div_ins.application != null or div_ins.relation != null or div_ins.value != null) return false;
        if (div_ins.result == null) return false;
        if (self.cur_func_float) return false;
        if (dnirValuesEqual(div_ins.lhs, div_ins.rhs)) return false;
        if (div_ins.lhs != .local and div_ins.lhs != .temp and div_ins.lhs != .i64) return false;
        if (div_ins.rhs != .local and div_ins.rhs != .temp) return false;
        if (!div_ins.divisor.proved()) return false;
        if (st_q.op != .store_local) return false;
        const t_q = div_ins.result.?;
        if (st_q.lhs != .temp or st_q.lhs.temp != t_q) return false;
        const lq = st_q.result orelse return false;
        if (mul_ins.op != .binop or mul_ins.binop != .mul) return false;
        if (mul_ins.ty == .f64) return false;
        if (mul_ins.application != null or mul_ins.relation != null or mul_ins.value != null) return false;
        if (mul_ins.result == null) return false;
        const t_m = mul_ins.result.?;
        const mul_divisor = if (mul_ins.lhs == .local and mul_ins.lhs.local == lq)
            mul_ins.rhs
        else if (mul_ins.rhs == .local and mul_ins.rhs.local == lq)
            mul_ins.lhs
        else
            return false;
        if (!dnirValuesEqual(mul_divisor, div_ins.rhs)) return false;
        if (sub_ins.op != .binop or sub_ins.binop != .sub) return false;
        if (sub_ins.ty == .f64) return false;
        if (sub_ins.application != null or sub_ins.relation != null or sub_ins.value != null) return false;
        if (sub_ins.result == null) return false;
        if (!dnirValuesEqual(sub_ins.lhs, div_ins.lhs)) return false;
        if (sub_ins.rhs != .temp or sub_ins.rhs.temp != t_m) return false;
        if (dnirInstrReadsValue(div_ins, true, lq)) return false;
        if (dnirInstrReadsValue(st_q, true, lq)) return false;
        const q_last = self.value_free_at.get(t_q) orelse return false;
        if (q_last != flat_idx + 1) return false;
        const m_last = self.value_free_at.get(t_m) orelse return false;
        if (m_last != flat_idx + 3) return false;
        if (dnirBranchLandsWithin(f, flat_idx + 1, flat_idx + 3)) return false;
        return true;
    }

    fn divmodQuotientDead(f: dnir.Function, st_q: dnir.Instr, flat_idx: u32) bool {
        const lq = st_q.result orelse return false;
        var idx: u32 = 0;
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if ((idx < flat_idx or idx > flat_idx + 3) and dnirInstrReadsValue(ins, true, lq)) return false;
                idx += 1;
            }
        }
        return true;
    }

    /// Emit the fused `ubfx` for a `ubfxFusible` pair. The shift temp is never
    /// materialized; the destination owns the `and`'s result temp.
    fn emitFusedUbfx(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        nx: dnir.Instr,
    ) Error!void {
        const ck = switch (ins.rhs) {
            .i64 => |v| v,
            else => return self.refuse(@src()),
        };
        const k = powerOfTwoShift(ck) orelse return self.refuse(@src());
        const t = ins.result orelse return self.refuse(@src());
        // The band's non-shift operand: the shift temp in the unnamed form,
        // the named local in the named form (`namedUbfxFusible`). The firing
        // predicate has proved exactly one side is that operand and the other
        // is the i64 mask, so this selection is exact in both forms.
        const shift_is_lhs = (nx.lhs == .temp and nx.lhs.temp == t) or nx.lhs == .local;
        const mask_val = if (shift_is_lhs) nx.rhs else nx.lhs;
        const cm = switch (mask_val) {
            .i64 => |v| v,
            else => return self.refuse(@src()),
        };
        const w = lowMaskWidth(cm) orelse return self.refuse(@src());
        // Pre-mask elision: if the dividend temp was an elided pre-mask
        // band, read its source operand directly. The elision extended the
        // source's liveness to this div, so the register is valid here.
        const elided_src = switch (ins.lhs) {
            .temp => |tb| self.premask_elided.get(tb),
            else => null,
        };
        const dividend_src = elided_src orelse ins.lhs;
        const x = try self.evalDnirValue(temps, dividend_src);
        const dst = try self.allocReg();
        try self.ensureRegLive(x);
        // UBFX #lsb,#width is UBFM with immr=lsb, imms=lsb+width-1 (not
        // width-1: imms<immr would decode as UBFIZ, a different operation).
        try self.emitFmt(
            0xd3400000 | (@as(u32, k) << 16) | ((@as(u32, k) + @as(u32, w) - 1) << 10) | (@as(u32, x) << 5) | @as(u32, dst),
            "ubfx x{d}, x{d}, #{d}, #{d}",
            .{ dst, x, k, w },
        );
        // The `and`'s refit, unchanged: a low-run mask no wider than the
        // declared width leaves every bit above it clear, so the 64-bit form
        // is already the refitted value — the same argument `.band` makes.
        const fitted = wForm32(nx.ty, .band) and w <= 32;
        if (!fitted) _ = try self.emitNarrowFit(dst, dst, nx.ty);
        if (elided_src == null) {
            if (!Arm64Compiler.regIsPinned(pinned, x)) self.releaseReg(x);
        }
        const d = nx.result orelse return self.refuse(@src());
        try temps.put(self.alloc, d, dst);
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = d;
        }
    }

    /// Emit the fused `madd` for a `mulAddFusible` pair and record the sum's
    /// register ownership (the product temp is never materialized).
    fn emitFusedMulAdd(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        nx: dnir.Instr,
        after: ?dnir.Instr,
        shiftadd_off: bool,
    ) Error!void {
        const t = ins.result.?;
        // Strength reduction: when the multiply is by a Z3-verified shift-add
        // constant, the shift-add + add sequence (2-cycle latency) beats madd
        // (4-cycle latency) on loop-carried recurrences. The madd fusion was
        // stealing these from the shift-add path.
        if (!shiftadd_off and !wForm32(nx.ty, .add)) {
            const k: ?i64 = switch (ins.lhs) {
                .i64 => |v| switch (ins.rhs) {
                    .i64 => null,
                    else => v,
                },
                else => switch (ins.rhs) {
                    .i64 => |v| v,
                    else => null,
                },
            };
            if (k) |kk| {
                if (mulShiftAddShift(kk) != null or sevenLikeShift(kk) != null) {
                    try self.emitShiftAddMulAdd(temps, pinned, ins, nx, after, kk);
                    return;
                }
            }
        }
        const a = try self.evalDnirValue(temps, ins.lhs);
        const b = try self.evalDnirValue(temps, ins.rhs);
        const acc_val = if (nx.lhs == .temp and nx.lhs.temp == t) nx.rhs else nx.lhs;
        const c = try self.evalDnirValue(temps, acc_val);
        //  is a single read-before-write instruction (plus an optional
        // single dst-to-dst narrowing), so the home may alias any of its
        // three sources: the old home value dies with the store.
        const home = self.maddStoreHome(temps, pinned, nx, after);
        const dst = home orelse try self.allocReg();
        if (home != null) self.claimReg(dst);
        // THE SUM'S DECLARED WIDTH SURVIVES THE FUSION.
        //
        // `dnir_lower.subsumeProducerRefit` MOVES a `u32` store's refit onto
        // this `add` and clears the store's, on the reasoning that the
        // producer's 32-bit destination form performs the narrowing for free.
        // The fusion then rewrote that producer as a 64-bit `madd` and dropped
        // the obligation it had just accepted — two independently correct
        // transforms composing into a wrong answer, and the only one in this
        // gate's matrix that survives to the EMITTED program.
        //
        // `madd Wd, Wn, Wm, Wa` exists and its low 32 bits are exact for the
        // same reason `add`'s are (`lowThirtyTwoExact`: mul and add are both
        // low-32 closed, so their composition is), and a `w` destination
        // zero-extends. So the unsigned-32 case keeps the fusion AND the free
        // narrowing; every other width pays one refit instruction, which is
        // what it would have paid unfused.
        if (wForm32(nx.ty, .add)) {
            try self.emitMaddRegW(dst, a, b, c);
        } else {
            try self.emitMaddReg(dst, a, b, c);
            _ = try self.emitNarrowFit(dst, dst, nx.ty);
        }
        if (a != dst and !Arm64Compiler.regIsPinned(pinned, a)) self.releaseReg(a);
        if (b != dst and !Arm64Compiler.regIsPinned(pinned, b)) self.releaseReg(b);
        if (c != dst and !Arm64Compiler.regIsPinned(pinned, c)) self.releaseReg(c);
        const d = nx.result.?;
        try temps.put(self.alloc, d, dst);
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = d;
        }
    }

    /// Emit `D = x*k + c` for a Z3-verified shift-add constant k as
    /// `add/sub tmp, x, x, lsl #sh` then `add dst, tmp, c`, instead of madd.
    /// The 2-cycle latency (vs madd's 4) wins on loop-carried recurrences.
    /// Exact: the shift-add is proved `== x*k` mod 2^64, and `+c` is exact;
    /// both ops are low-32 closed so the inherited narrow refit is preserved.
    fn emitShiftAddMulAdd(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        nx: dnir.Instr,
        after: ?dnir.Instr,
        k: i64,
    ) Error!void {
        const t = ins.result.?;
        const x_val = switch (ins.lhs) {
            .i64 => ins.rhs,
            else => ins.lhs,
        };
        const x = try self.evalDnirValue(temps, x_val);
        const acc_val = if (nx.lhs == .temp and nx.lhs.temp == t) nx.rhs else nx.lhs;
        const c = try self.evalDnirValue(temps, acc_val);
        // Same home logic as the madd path: the result may feed a store_local.
        const home = self.maddStoreHome(temps, pinned, nx, after);
        const dst = home orelse try self.allocReg();
        if (home != null) self.claimReg(dst);
        // Fresh intermediate: x, c, dst are all live, so allocReg cannot
        // return any of them; the two-instruction sequence is aliasing-safe
        // by construction (tmp is written once, read once, then released).
        const tmp = try self.allocReg();
        // k = 2^sh + 1: single shift-add (Z3-verified). k = 2^sh - 1:
        // lsl + sub, exact by ring arithmetic ((x<<sh) - x = x*(2^sh-1)).
        if (mulShiftAddShift(k)) |sa| {
            if (sa.neg) {
                try self.emitSubLslReg(tmp, x, x, sa.sh);
            } else {
                try self.emitAddLslReg(tmp, x, x, sa.sh);
            }
        } else if (sevenLikeShift(k)) |sh| {
            try self.emitLslImm(tmp, x, sh);
            try self.emitSubReg(tmp, tmp, x);
        } else unreachable;
        try self.emitAddReg(dst, tmp, c);
        _ = try self.emitNarrowFit(dst, dst, nx.ty);
        self.releaseReg(tmp);
        if (x != dst and !Arm64Compiler.regIsPinned(pinned, x)) self.releaseReg(x);
        if (c != dst and !Arm64Compiler.regIsPinned(pinned, c)) self.releaseReg(c);
        const d = nx.result.?;
        try temps.put(self.alloc, d, dst);
        if (dst >= 9 and dst < 29 and dst != platform_reserved_reg and !self.gp_home_regs[dst]) {
            self.gp_reg_owner[dst] = d;
        }
    }

    /// Emit the fused divmod for a `divmodFusible` window. One magic-division
    /// sequence materializes BOTH results: the corrected quotient into the
    /// div's destination (via `cinc`, exactly as `emitBinopFlooredConstDivisor`
    /// realizes `.idiv`) and the already-computed floored residual into a
    /// second destination (via `csel xzr`, exactly as it realizes `.mod`).
    /// No separate multiply/subtract executes.
    ///
    /// The quotient's naming store runs as written through the standard
    /// `store_local` path — the name stays live for later readers — and the
    /// remainder temp is left in `temps` for its consumer. Register
    /// discipline mirrors the constant-binop arm: the dividend is held for
    /// the sequence and released exactly as that arm releases it, and every
    /// sequence temporary excludes the claimed quotient destination, for
    /// the reason `emitBinopFlooredConstDivisor` states.
    fn emitFusedDivmod(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        div_ins: dnir.Instr,
        st_q: dnir.Instr,
        sub_ins: dnir.Instr,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        flat_idx: u32,
    ) Error!void {
        // Fail closed: the recognizer proved these, but the emitter must not
        // miscompile if it is ever reached another way.
        const k: i64 = switch (div_ins.rhs) {
            .i64 => |kk| kk,
            else => return self.refuseWith(@src(), "divmod-rhs"),
        };
        const mg = magicFlooredDivisor(k) orelse
            return self.refuseWith(@src(), "divmod-magic");
        const t_q = div_ins.result orelse return self.refuseWith(@src(), "divmod-no-tq");
        const t_d = sub_ins.result orelse return self.refuseWith(@src(), "divmod-no-td");

        const x = try self.evalDnirValue(temps, div_ins.lhs);
        const x_held = self.holdReg(x, pinned);
        const q_dst = try self.allocReg();
        // The sequence is `emitBinopFlooredConstDivisor` with `.idiv`,
        // inlined so the residual survives for the remainder; the constant
        // acquisition is shared, so hoisted preheader registers are reused
        // here exactly as in the plain division.
        const rm = try self.acquireMagicConstReg(q_dst, mg.m);
        const rt = try self.allocRegExcluding(q_dst);
        try self.emitSmulhReg(rt, rm, x);
        self.releaseReg(rm);
        if (mg.add_dividend) try self.emitAddReg(rt, rt, x);
        if (mg.shift > 0) try self.emitAsrImm(rt, rt, mg.shift);
        const rd = try self.acquireMagicConstReg(q_dst, k);
        const rv = try self.allocRegExcluding(q_dst);
        try self.emitMsubReg(rv, rt, rd, x);
        try self.emitCmpReg(rv, rd);
        try self.emitCincEqReg(q_dst, rt);
        self.releaseReg(rt);
        _ = try self.emitNarrowFit(q_dst, q_dst, div_ins.ty);
        const d_dst = try self.allocRegExcluding(q_dst);
        try self.emitCselZeroEqReg(d_dst, rv);
        self.releaseReg(rv);
        self.releaseReg(rd);
        _ = try self.emitNarrowFit(d_dst, d_dst, sub_ins.ty);

        if (x_held) self.gp_reg_owner[x] = null;
        if (x != q_dst and x != d_dst and !Arm64Compiler.regIsPinned(pinned, x)) self.releaseReg(x);

        try temps.put(self.alloc, t_q, q_dst);
        try temps.put(self.alloc, t_d, d_dst);
        if (d_dst >= 9 and d_dst < 29 and d_dst != platform_reserved_reg and !self.gp_home_regs[d_dst]) {
            self.gp_reg_owner[d_dst] = t_d;
        }
        // The quotient's naming store executes as written; the mul and the
        // sub never execute. `t_q`'s ownership is recorded by the main loop
        // from the div's result, exactly as for every other binop.
        try self.compileDnirInstr(temps, pinned, st_q, branch_patches, null, flat_idx + 1);
    }

    fn emitFusedDivmodRuntime(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *std.AutoHashMapUnmanaged(u32, u5),
        div_ins: dnir.Instr,
        st_q: dnir.Instr,
        sub_ins: dnir.Instr,
        branch_patches: *std.ArrayList(DnirBranchPatch),
        flat_idx: u32,
        q_dead: bool,
    ) Error!void {
        if (div_ins.binop != .div) return self.refuseWith(@src(), "divmod-rt-op");
        if (!div_ins.divisor.proved()) return self.refuseWith(@src(), "divmod-rt-divisor");
        const t_q = div_ins.result orelse return self.refuseWith(@src(), "divmod-rt-tq");
        const t_d = sub_ins.result orelse return self.refuseWith(@src(), "divmod-rt-td");
        const x = try self.evalDnirValue(temps, div_ins.lhs);
        const x_held = self.holdReg(x, pinned);
        const d = try self.evalDnirValue(temps, div_ins.rhs);
        const d_held = self.holdReg(d, pinned);
        const q_t = try self.allocReg();
        try self.emitSdivReg(q_t, x, d);
        const rem = try self.allocRegExcluding(q_t);
        try self.emitMsubReg(rem, q_t, d, x);
        // A proved-non-negative dividend makes floored division coincide with
        // the truncating sdiv/msub pair, so the sign corrections below are
        // dead. IDOL_DIVMOD_BARE_OFF=1 or IDOL_DIVMOD_REMCORR_OFF=1 restores the correcting sequence.
        const bare = div_ins.dividend.proved() and std.c.getenv("IDOL_DIVMOD_BARE_OFF") == null and
            std.c.getenv("IDOL_DIVMOD_REMCORR_OFF") == null;
        const rp: u5 = if (bare) 0 else try self.allocRegExcluding(q_t);
        if (!bare) {
            try self.emitAddReg(rp, rem, d);
            try self.emitCmpZero(rem);
        }
        const d_dst: u5 = if (bare) rem else try self.allocRegExcluding(q_t);
        var q_dst: u5 = 0;
        if (bare) {
            if (!q_dead) {
                q_dst = q_t;
                _ = try self.emitNarrowFit(q_dst, q_dst, div_ins.ty);
                try temps.put(self.alloc, t_q, q_dst);
            }
        } else if (q_dead) {
            try self.emitCselReg(d_dst, rp, rem, .lt);
        } else {
            const qm1 = try self.allocRegExcluding(q_t);
            try self.emitSubImm(qm1, q_t, 1);
            q_dst = try self.allocRegExcluding(q_t);
            try self.emitCselReg(q_dst, qm1, q_t, .lt);
            self.releaseReg(qm1);
            try self.emitCselReg(d_dst, rp, rem, .lt);
            _ = try self.emitNarrowFit(q_dst, q_dst, div_ins.ty);
            try temps.put(self.alloc, t_q, q_dst);
        }
        _ = try self.emitNarrowFit(d_dst, d_dst, sub_ins.ty);
        if (bare) {
            if (q_dead) self.releaseReg(q_t);
        } else {
            self.releaseReg(rp);
            self.releaseReg(rem);
            self.releaseReg(q_t);
        }
        if (x_held) self.gp_reg_owner[x] = null;
        if (d_held) self.gp_reg_owner[d] = null;
        if (x != d_dst and (q_dead or x != q_dst) and !Arm64Compiler.regIsPinned(pinned, x)) self.releaseReg(x);
        if (d != d_dst and !Arm64Compiler.regIsPinned(pinned, d)) self.releaseReg(d);
        try temps.put(self.alloc, t_d, d_dst);
        if (d_dst >= 9 and d_dst < 29 and d_dst != platform_reserved_reg and !self.gp_home_regs[d_dst]) {
            self.gp_reg_owner[d_dst] = t_d;
        }
        if (!q_dead) {
            try self.compileDnirInstr(temps, pinned, st_q, branch_patches, null, flat_idx + 1);
        }
    }

    /// Emit the fused `cmp; b.cond` for a `compareBranchFusible` pair. `when_true`
    /// branches on the comparison condition; `when_false` branches on its
    /// inverse (the branch is taken when the boolean would have been zero).
    fn emitFusedCompareBranch(
        self: *Arm64Compiler,
        temps: *std.AutoHashMapUnmanaged(u32, u5),
        pinned: *const std.AutoHashMapUnmanaged(u32, u5),
        ins: dnir.Instr,
        nx: dnir.Instr,
        branch_patches: *std.ArrayList(DnirBranchPatch),
    ) Error!void {
        const lhs = try self.evalDnirValue(temps, ins.lhs);
        // A small constant on the right folds into the compare itself —
        // `cmp xn, #imm` instead of a `mov` that materializes the constant
        // into a register and a register-to-register `cmp`. One fewer
        // instruction and one fewer live register on the comparison, which
        // is the whole hot path of a recursive base case.
        const rhs_imm: ?u12 = switch (ins.rhs) {
            .i64 => |k| if (k >= 0 and k <= 4095) @intCast(k) else null,
            else => null,
        };
        if (rhs_imm) |imm| {
            try self.emitCmpImm(lhs, imm);
            if (!Arm64Compiler.regIsPinned(pinned, lhs)) self.releaseReg(lhs);
        } else {
            const rhs = try self.evalDnirValue(temps, ins.rhs);
            try self.emitCmpReg(lhs, rhs);
            if (!Arm64Compiler.regIsPinned(pinned, lhs)) self.releaseReg(lhs);
            if (!Arm64Compiler.regIsPinned(pinned, rhs)) self.releaseReg(rhs);
        }
        const cond = comparisonCondition(ins.binop).?;
        const arm: Condition = if (nx.branch_condition == .when_true) cond else invertCondition(cond);
        const patch_off = try self.emitBCond(arm, 0);
        try branch_patches.append(self.alloc, .{ .patch_off = patch_off, .target_instr = nx.branch_target, .is_cond = true });
    }

    fn emitMulReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x9b007c00 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "mul x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    fn emitSdivReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x9ac00c00 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "sdiv x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    /// `smulh xd, xn, xm` — the HIGH 64 bits of the signed 128-bit product.
    /// Same 3-source encoding as `mul` with the `U` bit clear and `o0` set
    /// (bit 22), Ra forced to `xzr`. The one instruction that makes a constant
    /// divisor cheaper than `sdiv`.
    fn emitSmulhReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x9b407c00 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "smulh x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    /// `csinc xd, xn, xn, ne` — `xd = xn + (Z ? 1 : 0)`, spelled `cinc xd, xn,
    /// eq` by the alias. CSEL's encoding with bit 10 set. Emitted in the long
    /// form so the text a reader assembles is the text this encodes.
    ///
    /// Flag-safe for the same reason `emitCselReg` is: `ensureRegLive` can only
    /// add a reload, and a load does not write NZCV.
    fn emitCincEqReg(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        try self.ensureRegLive(src);
        try self.emitFmt(
            0x9a800400 | (@as(u32, src) << 16) | (@as(u32, @intFromEnum(Condition.ne)) << 12) | (@as(u32, src) << 5) | @as(u32, dst),
            "csinc x{d}, x{d}, x{d}, ne",
            .{ dst, src, src },
        );
    }

    /// `csel xd, xzr, xm, eq` — `xd = Z ? 0 : xm`. `xzr` is register 31 in the
    /// Rn field; CSEL has no SP-encoding ambiguity there.
    fn emitCselZeroEqReg(self: *Arm64Compiler, dst: u5, m: u5) Error!void {
        try self.ensureRegLive(m);
        try self.emitFmt(
            encodeCsel(dst, 31, m, .eq),
            "csel x{d}, xzr, x{d}, eq",
            .{ dst, m },
        );
    }

    fn emitMsubReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, acc: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.ensureRegLive(acc);
        try self.emitFmt(0x9b008000 | (@as(u32, rhs) << 16) | (@as(u32, acc) << 10) | (@as(u32, lhs) << 5) | @as(u32, dst), "msub x{d}, x{d}, x{d}, x{d}", .{ dst, lhs, rhs, acc });
    }

    /// `madd xd, xn, xm, xa` = xa + xn*xm. Same 3-source encoding as `msub`
    /// with bit 15 clear. Fuses a `mul` feeding an `add` (FTCFTW debt (2)).
    fn emitMaddReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, acc: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.ensureRegLive(acc);
        try self.emitFmt(0x9b000000 | (@as(u32, rhs) << 16) | (@as(u32, acc) << 10) | (@as(u32, lhs) << 5) | @as(u32, dst), "madd x{d}, x{d}, x{d}, x{d}", .{ dst, lhs, rhs, acc });
    }

    /// `madd wd, wn, wm, wa` — the 32-bit destination form, bit 31 clear.
    ///
    /// The `w` destination ZERO-EXTENDS into the whole `x` register, which is
    /// bit for bit what `ubfx xd, xn, #0, #32` leaves behind, so a `u32` sum
    /// keeps both the fusion and a free narrowing. `wForm32` is the one
    /// authority on when that substitution is exact; this only emits it.
    fn emitMaddRegW(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5, acc: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.ensureRegLive(acc);
        try self.emitFmt(0x1b000000 | (@as(u32, rhs) << 16) | (@as(u32, acc) << 10) | (@as(u32, lhs) << 5) | @as(u32, dst), "madd w{d}, w{d}, w{d}, w{d}", .{ dst, lhs, rhs, acc });
    }

    fn emitAndReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x8a000000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "and x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    fn emitOrrReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0xaa000000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "orr x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    fn emitEorReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0xca000000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "eor x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    // Variable (register-amount) shifts — Data-processing (2 source), 64-bit.
    // Rm=rhs (shift amount, bits 16-20), Rn=lhs (value, bits 5-9), Rd=dst.
    // Matches the C backend's int64_t << / >> (LSL / arithmetic ASR on arm64).
    fn emitLslReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x9ac02000 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "lsl x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    fn emitAsrReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.ensureRegLive(lhs);
        try self.ensureRegLive(rhs);
        try self.emitFmt(0x9ac02800 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "asr x{d}, x{d}, x{d}", .{ dst, lhs, rhs });
    }

    // --- f64 (scalar double) lowering. Verified encodings (from `as`/objdump
    // ground truth): double FADD=0x1E602800, FSUB=0x1E603800, FMUL=0x1E600800,
    // FDIV=0x1E601800, FMOV <Dd>,<Dn>=0x1E604000. (0x1EE0xxxx is HALF-precision,
    // a trap from miscounting the type field.) Register layout matches the
    // integer 2-source ops: Rm=rhs (bits 16-20), Rn=lhs (bits 5-9), Rd (0-4).
    /// Record that a temp/slot holds an FP register.
    fn markFpTemp(self: *Arm64Compiler, id: ?u32) Error!void {
        const t = id orelse return;
        try self.fp_temps.put(self.alloc, t, {});
    }

    /// Whether this operand is resident in the FP file. An `.f64` immediate
    /// counts: it materialises with `fmov`, not `mov`.
    fn valueIsFp(self: *const Arm64Compiler, v: dnir.Value) bool {
        return switch (v) {
            .f64 => true,
            .temp => |t| self.fp_temps.contains(t),
            .local => |sl| self.fp_temps.contains(sl),
            else => false,
        };
    }

    /// The FP VALUE range: d16-d30. Deliberately disjoint from d0-d7.
    ///
    /// This mirrors `allocRegExcluding`, which starts at x9 precisely so that a
    /// value never lives in an argument or result register. The FP allocator
    /// started at d0 instead, so values lived in the staging registers and were
    /// destroyed by any outgoing call — the defect `requireSafeFpStaging` in
    /// dnir_lower.zig currently refuses programs to avoid.
    ///
    /// d16-d31 are the caller-saved half of the FP file, so using them costs no
    /// prologue work. d8-d15 are deliberately skipped: they are CALLEE-saved
    /// (their low 64 bits must be preserved), so taking one without a
    /// prologue/epilogue save is a silent ABI violation rather than a refusal.
    /// d31 is left out as the staging scratch for a spill/restore that needs a
    /// register of its own.
    ///
    /// An earlier attempt simply widened the old d0-d7 pool to include d16-d31
    /// WITHOUT moving values out of the argument range or adding caller-save.
    /// That turned mandelbrot's honest DNB003 refusal into an infinite loop
    /// (gap[057]): more registers only meant the program got far enough to be
    /// wrong. Order matters — values out of the argument range first, then
    /// caller-save, then capacity.
    /// CAPACITY IS DELIBERATELY UNCHANGED AT EIGHT. d24-d30 are free and this
    /// loop could take them in one character, and it must not yet.
    ///
    /// `releaseFpReg` is still a no-op, so this is not allocation with liveness
    /// — it is a monotonic cursor, and every extra register only buys a longer
    /// run before the same wall. Widening it to 15 made
    /// `examples/mandelbrot.id` compile and then HANG, producing no output,
    /// which is strictly worse than the DNB003 refusal it replaced. That is the
    /// second time capacity has been taken before correctness here (gap[057]
    /// records the first).
    ///
    /// So: same eight registers, different eight registers. The move that
    /// mattered was OUT of the argument range, not upward in count. Raising
    /// this bound is step three of three, and step two is liveness.
    const fp_value_reg_base: u5 = 16;
    const fp_value_reg_count: u5 = 15;

    fn allocFpReg(self: *Arm64Compiler) Error!u5 {
        var reg: u5 = fp_value_reg_base;
        while (reg < fp_value_reg_base + fp_value_reg_count) : (reg += 1) {
            if (!self.used_fp_regs[reg]) {
                self.used_fp_regs[reg] = true;
                return reg;
            }
        }
        return error.RegisterExhausted;
    }

    fn emitFaddReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.emitFmt(0x1e602800 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "fadd d{d}, d{d}, d{d}", .{ dst, lhs, rhs });
    }

    fn emitFsubReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.emitFmt(0x1e603800 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "fsub d{d}, d{d}, d{d}", .{ dst, lhs, rhs });
    }

    fn emitFmulReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.emitFmt(0x1e600800 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "fmul d{d}, d{d}, d{d}", .{ dst, lhs, rhs });
    }

    fn emitFdivReg(self: *Arm64Compiler, dst: u5, lhs: u5, rhs: u5) Error!void {
        try self.emitFmt(0x1e601800 | (@as(u32, rhs) << 16) | (@as(u32, lhs) << 5) | @as(u32, dst), "fdiv d{d}, d{d}, d{d}", .{ dst, lhs, rhs });
    }

    fn emitFcvtzsX0FromD0(self: *Arm64Compiler) Error!void {
        try self.emit(0x9e780000, "fcvtzs x0, d0");
    }

    fn emitFmovReg(self: *Arm64Compiler, dst: u5, src: u5) Error!void {
        // FMOV <Dd>,<Dn> — ground-truth base 0x1E604000 (fmov d0,d2 => 0x1E604040).
        try self.emitFmt(0x1e604000 | (@as(u32, src) << 5) | @as(u32, dst), "fmov d{d}, d{d}", .{ dst, src });
    }

    /// The other GP->FP transfer, and the same source read — see
    /// `emitScvtfFromGpr` for why `spilled_regs` decides it. Its table-read
    /// caller allocates the FP destination AFTER loading the bits, and that
    /// allocation is one the cascade can answer by spilling the very register
    /// this then reads.
    fn emitFmovFromGpr(self: *Arm64Compiler, dreg: u5, xreg: u5) Error!void {
        // FMOV <Dd>,<Xn> — general-register to FP (64-bit). Ground-truth base
        // 0x9E670000 (fmov d0,x1 => 0x9E670020). Used to materialize an f64
        // literal: load its bit pattern into an x-reg, then transfer to d.
        try self.ensureRegLive(xreg);
        try self.emitFmt(0x9e670000 | (@as(u32, xreg) << 5) | @as(u32, dreg), "fmov d{d}, x{d}", .{ dreg, xreg });
    }

    fn patchCalls(self: *Arm64Compiler) Error!void {
        for (self.call_patches.items) |patch| {
            if (self.definedSymbolOffset(patch.target)) |target_offset| {
                const diff = @as(i64, target_offset) - @as(i64, patch.offset);
                if (@mod(diff, 4) != 0) return error.BranchOutOfRange;
                const imm = @divTrunc(diff, 4);
                if (imm < -(1 << 25) or imm >= (1 << 25)) return error.BranchOutOfRange;
                const imm26: u32 = @intCast(@as(i32, @intCast(imm)) & 0x03ff_ffff);
                // KEEP THE OPCODE THAT WAS EMITTED. This wrote a literal
                // `0x94000000` — BL — over whatever word sat at the patch site,
                // which was harmless while `emitBl` was the only producer and
                // silently turned a §12 TAIL `b` back into a call the moment
                // one existed. Both forms are `op | imm26` with the same imm26
                // field, so the top six bits are the whole difference and they
                // belong to the emitter, not to relocation.
                const emitted = std.mem.readInt(u32, self.code.items[patch.offset..][0..4], .little);
                const word = (emitted & 0xfc00_0000) | imm26;
                std.mem.writeInt(u32, self.code.items[patch.offset..][0..4], word, .little);
                continue;
            }
            if (self.extern_symbols.get(patch.target)) |symbol_index| {
                try self.relocations.append(self.alloc, .{ .offset = patch.offset, .symbol_index = symbol_index });
                continue;
            }
            // A call target that is neither defined here nor registered extern
            // is an undefined symbol — DNB007. Reporting it as DNB001 claimed
            // the *program* was outside the subset, when lowering had in fact
            // fully succeeded and only relocation failed; that misdirects every
            // investigation to the wrong phase.
            // No spelling-based libc rescue. Every lawful external call has
            // already registered an exact DNIR extern row; recreating one here
            // would let a damaged graph/lowering schedule emit successfully.
            // The symbol name was behind DUO_DNIR_TRACE, so the largest row in
            // the bail histogram (6 programs) said only "undefined symbol" and
            // named nothing. Every other refusal path reports unconditionally
            // now; this one has no reason to be different.
            self.diagnostic.record(@src(), patch.target);
            return error.UnknownSymbol;
        }
    }

    fn patchB(self: *Arm64Compiler, offset: u32, target: u32) Error!void {
        const diff = @as(i64, target) - @as(i64, offset);
        if (@mod(diff, 4) != 0) return error.BranchOutOfRange;
        const imm = @divTrunc(diff, 4);
        if (imm < -(1 << 25) or imm >= (1 << 25)) return error.BranchOutOfRange;
        const imm26: u32 = @intCast(@as(i32, @intCast(imm)) & 0x03ff_ffff);
        std.mem.writeInt(u32, self.code.items[offset..][0..4], 0x14000000 | imm26, .little);
    }

    fn patchCondBranch(self: *Arm64Compiler, offset: u32, target: u32) Error!void {
        const diff = @as(i64, target) - @as(i64, offset);
        if (@mod(diff, 4) != 0) return error.BranchOutOfRange;
        const imm = @divTrunc(diff, 4);
        if (imm < -(1 << 18) or imm >= (1 << 18)) return error.BranchOutOfRange;
        const old = std.mem.readInt(u32, self.code.items[offset..][0..4], .little);
        const imm19: u32 = @intCast(@as(i32, @intCast(imm)) & 0x7ffff);
        std.mem.writeInt(u32, self.code.items[offset..][0..4], 0x54000000 | (imm19 << 5) | (old & 0xf), .little);
    }

    fn definedSymbolOffset(self: *const Arm64Compiler, name: []const u8) ?u32 {
        for (self.symbols.items) |sym| {
            if (sym.defined and std.mem.eql(u8, sym.name, name)) return sym.offset;
        }
        return null;
    }

    fn symbolOffset(self: *const Arm64Compiler, name: []const u8) ?u32 {
        for (self.symbols.items) |sym| {
            if (std.mem.eql(u8, sym.name, name)) return sym.offset;
        }
        return null;
    }
};

fn returnsInteger(t: ast.TypeExpr) bool {
    return isIntegerAnnotation(t);
}

fn isIntegerAnnotation(t: ast.TypeExpr) bool {
    return switch (t) {
        .named => |name| std.mem.eql(u8, name, "i32") or
            std.mem.eql(u8, name, "i64") or
            std.mem.eql(u8, name, "u32") or
            std.mem.eql(u8, name, "u64"),
        else => false,
    };
}

fn returnsVoid(t: ast.TypeExpr) bool {
    return switch (t) {
        .named => |name| std.mem.eql(u8, name, "void"),
        else => false,
    };
}

/// The declared width of a sub-64-bit integer type, and the value a refit
/// leaves behind for a literal that never reaches a register.
///
/// ONE DEFINITION, in `dnir_lower.zig`, where the width is established. A
/// second copy here is the shape this tree keeps paying for: two spellings of
/// one fact, and nothing that makes them agree.
const narrowFit = dnir_lower.narrowFit;
const lowThirtyTwoExact = dnir_lower.lowThirtyTwoExact;
const narrowFitConst = dnir_lower.narrowFitConst;

fn comparisonCondition(op: dnir.BinOpTag) ?Condition {
    return switch (op) {
        .eq => .eq,
        .neq => .ne,
        .lt => .lt,
        .gt => .gt,
        .leq => .le,
        .geq => .ge,
        else => null,
    };
}

fn invertCondition(cond: Condition) Condition {
    return switch (cond) {
        .eq => .ne,
        .ne => .eq,
        .lt => .ge,
        .ge => .lt,
        .gt => .le,
        .le => .gt,
        .hi => .ls,
        .ls => .hi,
    };
}

fn conditionForCset(cond: Condition) Condition {
    return invertCondition(cond);
}

/// `CSET Xd, cond` is an alias for `CSINC Xd, XZR, XZR, invert(cond)`.
///
/// Base encoding is `0x9A800400 | Rm<<16 | cond<<12 | Rn<<5 | Rd`; with
/// `Rm = Rn = XZR (31)` that is `0x9A9F07E0`. The condition field MUST start at
/// zero — a base with any cond bit pre-set silently ORs into the condition and
/// corrupts every condition whose encoding has that bit clear (`ge`, `eq`,
/// `gt`), which is why this is one function rather than a repeated literal.
fn encodeCset(dst: u5, cond: Condition) u32 {
    const CSINC_XZR_XZR: u32 = 0x9a9f07e0;
    return CSINC_XZR_XZR | (@as(u32, @intFromEnum(conditionForCset(cond))) << 12) | @as(u32, dst);
}

/// `CSEL Xd, Xn, Xm, cond` — `Xd = cond ? Xn : Xm`, no branch.
///
/// Same conditional-select family as `CSET` above and one bit away from it:
/// `CSINC` sets bit 10, `CSEL` clears it. `0x9A800000 | Rm<<16 | cond<<12 |
/// Rn<<5 | Rd`, and `encodeCset`'s own literal `0x9a9f07e0` is this base with
/// `Rm = Rn = 31`, bit 10 set — which is the cross-check the unit test below
/// runs rather than trusting either constant on its own.
///
/// The condition field must start at zero here for exactly the reason recorded
/// above `encodeCset`: a pre-set bit ORs into the condition and corrupts every
/// condition whose encoding has that bit clear.
fn encodeCsel(dst: u5, n: u5, m: u5, cond: Condition) u32 {
    const CSEL_BASE: u32 = 0x9a800000;
    return CSEL_BASE | (@as(u32, m) << 16) |
        (@as(u32, @intFromEnum(cond)) << 12) | (@as(u32, n) << 5) | @as(u32, dst);
}

/// `CSINV Xd, Xn, Xm, cond` is `Xd = cond ? Xn : ~Xm`: CSEL with bit 30 set
/// (`0xDA800000`), everything else identical, and the inversion is on the
/// ELSE operand (verified on hardware: `csinv x0,x1,x2,eq` with Z=1 answers
/// x1, with Z=0 answers ~x2). So `encodeCsinv(d, d, d, .ne)` after
/// `cmn xd, #1` turns a `cset`-produced 0/1 into -1 exactly when the divisor
/// is -1: ne true keeps the value, ne false (x == -1) inverts it.
fn encodeCsinv(dst: u5, n: u5, m: u5, cond: Condition) u32 {
    const CSINV_BASE: u32 = 0xda800000;
    return CSINV_BASE | (@as(u32, m) << 16) |
        (@as(u32, @intFromEnum(cond)) << 12) | (@as(u32, n) << 5) | @as(u32, dst);
}

fn conditionName(cond: Condition) []const u8 {
    return switch (cond) {
        .eq => "eq",
        .ne => "ne",
        .lt => "lt",
        .ge => "ge",
        .gt => "gt",
        .le => "le",
        .hi => "hi",
        .ls => "ls",
    };
}

fn findTableFieldValue(fields: []const ast.TableField, name: []const u8) ?*const ast.Expr {
    for (fields) |fld| {
        switch (fld) {
            .named => |nf| {
                if (std.mem.eql(u8, nf.key, name)) return nf.val;
            },
            else => {},
        }
    }
    return null;
}

const CheckedApplication = semantic_graph.ApplicationFact;

fn checkedApplications(
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error![]const CheckedApplication {
    const applications = graph.applications();
    for (applications) |*application| {
        if (graph.application(application.application) != application or
            graph.applicationArguments(application.application) == null or
            graph.applicationResults(application.application) == null)
        {
            return invalidFactsWith(diagnostic, @src(), "application-facts");
        }
    }
    return applications;
}

fn applicationResult(
    graph: *const semantic_graph.SemanticGraph,
    application: CheckedApplication,
    diagnostic: *Diagnostic,
) Error!semantic_graph.id {
    const results = graph.applicationResults(application.application) orelse
        return invalidFactsWith(diagnostic, @src(), "application-results");
    if (results.len == 0) return invalidFactsWith(diagnostic, @src(), "application-result-count");
    return results[0];
}

fn optionalIdEql(a: ?semantic_graph.id, b: ?semantic_graph.id) bool {
    if (a == null or b == null) return a == null and b == null;
    return std.meta.eql(a.?, b.?);
}

fn nextMachineInstructionCoordinate(current: u32, diagnostic: *Diagnostic) Error!u32 {
    return std.math.add(u32, current, 1) catch
        return recordRefusalWith(
            diagnostic,
            @src(),
            "machine-instruction-coordinate-capacity",
        );
}

/// Foreign calls emitted by bootstrap lowering in `dnir_lower.zig` without
/// graph application facts (GAP-155). Validation admits only this closed set
/// when lineage is absent; every other bare `call_extern` stays unlawful.
fn isBootstrapForeignCall(callee: []const u8) bool {
    return dnir.isBootstrapForeignCall(callee);
}

/// Applications whose realization is KNOWN-ABSENT rather than missing.
///
/// `Card` has three values and the third was never written: an application can
/// have a realization (`.one`), or not yet be known to have one (`.unknown`),
/// or be known to have NONE. LAWFUL NONEXECUTION produces the third — a
/// relation evaluated whole at compile time keeps its published applications
/// but realizes none of them, because there is no body left for them to be
/// realized in.
///
/// `dnir_lower` is the only producer of that fact and records it on the
/// function it folded (`Function.folded_to_constant`); this reads it back and
/// says how many applications it accounts for. ONE implementation, called from
/// both count checks, because two would be two predicates for one question —
/// the shape that has produced a defect on this surface already.
///
/// NOT A RELAXATION. It subtracts exactly the applications published inside
/// folded relations and nothing else, so a call dropped anywhere else still
/// leaves `seen` short and still fails. A body that folded cannot also have
/// emitted a call — `validateDnirApplications` asserts that separately.
fn unrealizedApplicationCount(module: dnir.Module) usize {
    const graph = module.graph orelse return 0;
    var count: usize = 0;
    for (module.functions) |function| {
        if (!function.folded_to_constant) {
            // ONE PROJECTION ANSWERED FROM THE GRAPH, inside a relation that
            // still executes. `Function.absent_applications` is the lowering's
            // own statement of which; `validateDnirApplications` proves each
            // entry earned it before this subtraction is allowed to stand.
            count += function.absent_applications.len;
            // SUMMARY-FOLDED CALLS, answered from the callee's retained
            // summary and realized NOWHERE. `Function.summary_folded_applications`
            // is the lowering's statement; `validateSummaryFoldedApplications`
            // proves each entry earned it.
            count += function.summary_folded_applications.len;
            continue;
        }
        const relation = function.id orelse continue;
        for (graph.applicationsInCaller(relation)) |occurrence| {
            if (graph.application(occurrence) == null) continue;
            if (graph.isBootstrapApplicationNode(occurrence)) continue;
            count += 1;
        }
    }
    return count;
}

fn validateDnirApplications(
    alloc: std.mem.Allocator,
    module: dnir.Module,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!void {
    const context = module.graph orelse return invalidFactsWith(diagnostic, @src(), "missing-graph-context");
    if (context != graph) return invalidFactsWith(diagnostic, @src(), "graph-context-mismatch");
    if (realization_validate.aggregateSchedule(module)) |failure| {
        diagnostic.application = failure.application;
        return invalidFactsWith(diagnostic, @src(), failure.note);
    }
    const applications = try checkedApplications(graph, diagnostic);
    var seen: std.AutoHashMapUnmanaged(semantic_graph.id, void) = .empty;
    defer seen.deinit(alloc);

    const LinkTarget = struct {
        id: semantic_graph.id,
        linkage: []const u8,
    };
    var targets: std.AutoHashMapUnmanaged(semantic_graph.id, LinkTarget) = .empty;
    defer targets.deinit(alloc);
    var link_symbols: std.StringHashMapUnmanaged(void) = .empty;
    defer link_symbols.deinit(alloc);
    for (module.functions) |function| {
        const id = function.id orelse continue;
        if (graph.isModuleRoot(id)) {
            if (!std.mem.eql(u8, function.name, "main"))
                return invalidFactsWith(diagnostic, @src(), "root-link-symbol");
        } else if (graph.callableLinkage(id)) |graph_linkage| {
            if (graph_linkage.exposure == .c_import)
                return invalidFactsWith(diagnostic, @src(), "callable-import-definition");
            if (!std.mem.eql(u8, graph_linkage.symbol, function.name))
                return invalidFactsWith(diagnostic, @src(), "function-link-symbol");
        } else if (graph.requiresCallableLinkage()) {
            return invalidFactsWith(diagnostic, @src(), "missing-callable-linkage");
        }
        const symbol_slot = try link_symbols.getOrPut(alloc, function.name);
        if (symbol_slot.found_existing) return invalidFactsWith(diagnostic, @src(), "duplicate-link-symbol");
        const target = try targets.getOrPut(alloc, id);
        if (target.found_existing) return invalidFactsWith(diagnostic, @src(), "function-fact-collision");
        target.value_ptr.* = .{
            .id = id,
            .linkage = function.name,
        };
    }

    // Undefined linker inputs are a physical projection of graph-owned
    // callable linkage. Validate the projection itself: the machine emitter
    // must not be able to recreate a removed row merely because libc happens
    // to contain a symbol with the same spelling.
    var extern_symbols: std.StringHashMapUnmanaged(void) = .empty;
    defer extern_symbols.deinit(alloc);
    for (module.externs) |external| {
        if (external.symbol.len == 0)
            return invalidFactsWith(diagnostic, @src(), "invalid-callable-extern");
        const slot = try extern_symbols.getOrPut(alloc, external.symbol);
        if (slot.found_existing)
            return invalidFactsWith(diagnostic, @src(), "duplicate-callable-extern");
        if (link_symbols.contains(external.symbol))
            return invalidFactsWith(diagnostic, @src(), "callable-link-symbol-collision");
    }

    for (module.functions) |function| {
        var instruction_index: u32 = 0;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                const next_instruction_index = try nextMachineInstructionCoordinate(
                    instruction_index,
                    diagnostic,
                );
                defer instruction_index = next_instruction_index;
                if (instruction.application) |application_id| {
                    diagnostic.application = application_id;
                }
                const fact_count: u2 = @as(u2, @intFromBool(instruction.relation != null)) +
                    @as(u2, @intFromBool(instruction.application != null)) +
                    @as(u2, @intFromBool(instruction.value != null));
                if (fact_count == 0) {
                    if (instruction.subject != null or instruction.realization_start != null) {
                        return invalidFactsWith(diagnostic, @src(), "orphan-realization-lineage");
                    }
                    if (instruction.op == .call_direct) {
                        var module_local = false;
                        for (module.functions) |local_fn| {
                            if (std.mem.eql(u8, local_fn.name, instruction.callee)) {
                                module_local = true;
                                break;
                            }
                        }
                        if (module_local) continue;
                        return invalidFactsWith(diagnostic, @src(), "missing-application-lineage");
                    }
                    if (instruction.op == .call_extern) {
                        if (isBootstrapForeignCall(instruction.callee)) continue;
                        return invalidFactsWith(
                            diagnostic,
                            @src(),
                            "missing-foreign-application-lineage",
                        );
                    }
                    continue;
                }
                if (fact_count != 3) return invalidFactsWith(diagnostic, @src(), "partial-application-lineage");
                const realization_start = instruction.realization_start orelse
                    return invalidFactsWith(diagnostic, @src(), "partial-realization-lineage");
                if (realization_start > instruction_index) {
                    return invalidFactsWith(diagnostic, @src(), "invalid-realization-start");
                }

                const application = graph.application(instruction.application.?) orelse
                    return invalidFactsWith(diagnostic, @src(), "unknown-application-lineage");
                const result = try applicationResult(graph, application.*, diagnostic);
                const results = graph.applicationResults(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "application-results");
                const caller = graph.applicationCaller(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "application-caller-mismatch");
                if (function.id == null or !std.meta.eql(function.id.?, caller)) {
                    return invalidFactsWith(diagnostic, @src(), "application-caller-mismatch");
                }
                const descriptor = graph.applicationDescriptor(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "application-fact-mismatch");
                const relation = graph.applicationRelation(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "application-fact-mismatch");
                if (!std.meta.eql(application.application, instruction.application.?) or
                    !std.meta.eql(relation, instruction.relation.?) or
                    !std.meta.eql(result, instruction.value.?) or
                    !optionalIdEql(graph.applicationSubject(application.application), instruction.subject) or
                    !descriptor.eql(instruction.ty))
                {
                    return invalidFactsWith(diagnostic, @src(), "application-fact-mismatch");
                }
                const aggregate_access = graph.aggregateAccess(application.application) != null;
                if (!aggregate_access and instruction.op != .call_direct) {
                    // A checked call-to-constant or tail-call rewrite needs a
                    // semantic transform witness that the current graph does
                    // not publish. Until then, only the untransformed call is
                    // lawful. Aggregate access above is not this exception: its
                    // ordinary application, aggregate/member facts and place
                    // facts are the witness, and the helper validates the exact
                    // selected physical realization independently.
                    return invalidFactsWith(diagnostic, @src(), "unwitnessed-application-transform");
                }
                if (results.len == 1) {
                    if (instruction.pack_results.len != 0) {
                        return invalidFactsWith(diagnostic, @src(), "application-result-pack");
                    }
                } else {
                    if (results.len > dnir_lower.max_reg_record_fields or
                        instruction.pack_results.len != results.len or instruction.result != null or
                        instruction.record.len != 0)
                    {
                        return invalidFactsWith(diagnostic, @src(), "application-result-abi");
                    }
                    for (instruction.pack_results, results) |projected, value_id| {
                        if (!std.meta.eql(projected.value, value_id)) {
                            return invalidFactsWith(diagnostic, @src(), "application-result-pack");
                        }
                        const node = graph.get(value_id) orelse
                            return invalidFactsWith(diagnostic, @src(), "application-result-member");
                        const result_descriptor = node.descriptor orelse
                            return invalidFactsWith(diagnostic, @src(), "application-result-descriptor");
                        if (!result_descriptor.eql(projected.ty)) {
                            return invalidFactsWith(diagnostic, @src(), "application-result-descriptor");
                        }
                        switch (projected.ty) {
                            .i8,
                            .i16,
                            .i32,
                            .i64,
                            .u8,
                            .u16,
                            .u32,
                            .u64,
                            .bool,
                            .str,
                            .pointer,
                            => {},
                            else => return invalidFactsWith(diagnostic, @src(), "application-result-abi"),
                        }
                    }
                }
                const target_id = instruction.target orelse
                    return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                const selected_target = graph.applicationTarget(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                const applied = graph.applicationApplied(application.application) orelse
                    return invalidFactsWith(diagnostic, @src(), "missing-application-applied");
                if (aggregate_access) {
                    const subject = graph.applicationSubject(application.application) orelse
                        return invalidFactsWith(diagnostic, @src(), "aggregate-access-subject");
                    if (!std.meta.eql(target_id, selected_target) or
                        !std.meta.eql(selected_target, relation) or
                        !std.meta.eql(applied, subject))
                    {
                        return invalidFactsWith(diagnostic, @src(), "application-target-mismatch");
                    }
                } else if (!std.meta.eql(target_id, selected_target) or
                    !std.meta.eql(applied, selected_target))
                {
                    return invalidFactsWith(diagnostic, @src(), "application-target-mismatch");
                }
                const result_shape = graph.applicationResultShape(application.application, 0);
                if (result_shape) |shape| {
                    var result_record: ?dnir.RecordDesc = null;
                    for (module.records) |record| {
                        if (record.semantic_shape != shape) continue;
                        if (result_record != null) {
                            return invalidFactsWith(diagnostic, @src(), "application-result-shape-collision");
                        }
                        result_record = record;
                    }
                    const record = result_record orelse
                        return invalidFactsWith(diagnostic, @src(), "application-result-shape");
                    if (!std.mem.eql(u8, record.name, instruction.record)) {
                        return invalidFactsWith(diagnostic, @src(), "application-result-abi");
                    }
                } else {
                    if (descriptor == .@"struct" or descriptor == .table_type) {
                        return invalidFactsWith(diagnostic, @src(), "application-result-shape");
                    }
                    if (instruction.record.len != 0) {
                        return invalidFactsWith(diagnostic, @src(), "application-result-abi");
                    }
                }
                if (aggregate_access) {
                    if (function.folded_to_constant) {
                        return invalidFactsWith(diagnostic, @src(), "folded-application-lineage");
                    }
                    const use = try seen.getOrPut(alloc, application.application);
                    if (use.found_existing) {
                        return invalidFactsWith(diagnostic, @src(), "application-realization-count");
                    }
                    continue;
                }
                const target_linkage = graph.callableLinkage(target_id);
                if (graph.requiresCallableLinkage() and target_linkage == null) {
                    return invalidFactsWith(diagnostic, @src(), "missing-callable-linkage");
                }

                // A CROSS-HOME TARGET OR C IMPORT IS NOT IN `module.functions`
                // AND MUST NOT BE. `foreign_home` records residence; the
                // callable linkage fact independently records C origin. A local
                // `@ffi` target therefore reaches this branch without inventing
                // a synthetic foreign home.
                //
                // IT STILL VALIDATES, in the one way that is available: the
                // symbol the emitter chose must be the symbol the MANGLING LAW
                // derives from `(home, name)`. That is the whole content of a
                // link target for a relation this module cannot see the body
                // of, and it is two-sided — an emitter that invents a symbol,
                // or a lift that loses the home, both fail here.
                const c_import = if (target_linkage) |linkage|
                    linkage.exposure == .c_import
                else
                    false;
                if (c_import or graph.foreignHome(target_id) != null) {
                    if (target_linkage) |linkage| {
                        if (linkage.exposure == .c_import and linkage.origin != .c)
                            return invalidFactsWith(diagnostic, @src(), "callable-origin");
                        if (!std.mem.eql(u8, linkage.symbol, instruction.callee))
                            return invalidFactsWith(diagnostic, @src(), "application-link-symbol");
                        if (!extern_symbols.contains(linkage.symbol))
                            return invalidFactsWith(diagnostic, @src(), "missing-callable-extern");
                    } else {
                        const foreign_home = graph.foreignHome(target_id) orelse
                            return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                        const node = graph.get(target_id) orelse
                            return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                        const relation_name = node.name orelse
                            return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                        const want = if (std.mem.eql(u8, foreign_home, "c"))
                            try alloc.dupe(u8, relation_name)
                        else
                            try home_resolve.homeSymbol(alloc, foreign_home, relation_name);
                        defer alloc.free(want);
                        if (!std.mem.eql(u8, want, instruction.callee))
                            return invalidFactsWith(diagnostic, @src(), "application-link-symbol");
                        if (!extern_symbols.contains(want))
                            return invalidFactsWith(diagnostic, @src(), "missing-callable-extern");
                    }
                    const foreign_use = try seen.getOrPut(alloc, application.application);
                    if (foreign_use.found_existing) {
                        return invalidFactsWith(diagnostic, @src(), "application-realization-count");
                    }
                    continue;
                }
                const target = targets.get(target_id) orelse
                    return invalidFactsWith(diagnostic, @src(), "missing-application-target");
                if (!std.meta.eql(target.id, target_id)) {
                    return invalidFactsWith(diagnostic, @src(), "application-link-target");
                }
                if (!std.mem.eql(u8, target.linkage, instruction.callee)) {
                    return invalidFactsWith(diagnostic, @src(), "application-link-symbol");
                }
                // A FOLDED RELATION MAY NOT ALSO REALIZE SOMETHING. The fold
                // replaces the whole body with its constant, so lineage
                // surviving inside one means the body was only partly
                // discarded — and the count subtraction below would then be
                // excusing a call that really did go missing.
                if (function.folded_to_constant) {
                    return invalidFactsWith(diagnostic, @src(), "folded-application-lineage");
                }
                const use = try seen.getOrPut(alloc, application.application);
                if (use.found_existing) {
                    return invalidFactsWith(diagnostic, @src(), "application-realization-count");
                }
            }
        }
    }

    var expected: usize = 0;
    for (applications) |application| {
        if (!graph.isBootstrapApplicationNode(application.application)) expected += 1;
    }
    // Applications inside a relation that folded to its answer, and aggregate
    // projections whose exact graph answer removed their work, are realized
    // NOWHERE — known-absent, not missing. `aggregateSchedule` above is the one
    // validator of every named aggregate absence; this count only consumes it.
    const unrealized = unrealizedApplicationCount(module);
    if (unrealized > expected) return invalidFactsWith(diagnostic, @src(), "application-realization-count");
    if (seen.count() != expected - unrealized) {
        return invalidFactsWith(diagnostic, @src(), "application-realization-count");
    }
}

fn validateMachineLineage(
    alloc: std.mem.Allocator,
    output: Arm64Output,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!void {
    if (output.graph != graph) return invalidFactsWith(diagnostic, @src(), "machine-graph-context");
    const applications = try checkedApplications(graph, diagnostic);
    var expected: usize = 0;
    for (applications) |application| {
        if (!graph.isBootstrapApplicationNode(application.application)) expected += 1;
    }
    // Same subtraction as the DNIR check, from the same producer: a relation
    // folded to its answer has no machine text, so its applications have no
    // lineage row to be attributed to. `output.unrealized` was computed by
    // `unrealizedApplicationCount` over the module this output was emitted from.
    if (output.unrealized > expected) return invalidFactsWith(diagnostic, @src(), "machine-lineage-count");
    expected -= output.unrealized;
    if (output.lineage.len == 0 and expected == 0) return;
    if (output.lineage.len != expected) {
        return invalidFactsWith(diagnostic, @src(), "machine-lineage-count");
    }
    var seen: std.AutoHashMapUnmanaged(semantic_graph.id, void) = .empty;
    defer seen.deinit(alloc);
    for (output.lineage) |lineage| {
        const application = graph.application(lineage.application) orelse
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-unknown");
        const result = try applicationResult(graph, application.*, diagnostic);
        const descriptor = graph.applicationDescriptor(application.application) orelse
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-mismatch");
        const caller = graph.applicationCaller(application.application) orelse
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-mismatch");
        const relation = graph.applicationRelation(application.application) orelse
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-mismatch");
        const target = graph.applicationTarget(application.application) orelse
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-mismatch");
        if (!std.meta.eql(lineage.application, application.application) or
            !std.meta.eql(lineage.relation, relation) or
            !std.meta.eql(lineage.target, target) or
            !std.meta.eql(lineage.value, result) or
            !optionalIdEql(lineage.subject, graph.applicationSubject(application.application)) or
            !lineage.descriptor.eql(descriptor) or
            !std.meta.eql(lineage.caller, caller))
        {
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-mismatch");
        }
        if (lineage.instruction_start >= lineage.instruction_end) {
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-instruction-range");
        }
        if (lineage.text_start >= lineage.text_end or @as(usize, lineage.text_end) > output.text.len) {
            return invalidFactsWith(diagnostic, @src(), "machine-lineage-range");
        }
        const slot = try seen.getOrPut(alloc, lineage.application);
        if (slot.found_existing) return invalidFactsWith(diagnostic, @src(), "machine-lineage-count");
    }
    if (seen.count() != expected) return invalidFactsWith(diagnostic, @src(), "machine-lineage-count");
}

/// DNIR in, machine code out, with NO source facts in hand.
///
/// Nothing is promoted to `__TEXT,__const` on this path — a determined table
/// needs the source-level precondition from `table_facts.zig`, and a caller
/// holding only DNIR cannot supply it. That is a deliberate absence, not an
/// oversight: it keeps every oracle test below measuring the emission it was
/// written against.
fn emitArm64FromDnir(alloc: std.mem.Allocator, m: dnir.Module, entry: ?[]const u8, diagnostic: *Diagnostic) Error!Arm64Output {
    return emitArm64FromDnirLicensed(alloc, m, entry, diagnostic, null);
}

fn emitArm64FromDnirLicensed(
    alloc: std.mem.Allocator,
    m: dnir.Module,
    entry: ?[]const u8,
    diagnostic: *Diagnostic,
    licence: ?*const const_table.Licence,
) Error!Arm64Output {
    // THE SHARED RESULT-PACK ADMISSION, asked here rather than in
    // `validateDnirApplications` so that it is the same question at the same
    // point on both targets: immediately before a backend turns this module
    // into bytes, with no graph required and no gate-transport exemption.
    if (realization_validate.resultPackShape(m)) |failure| {
        return invalidFactsWith(diagnostic, @src(), failure.note);
    }
    var records = try collectF64RecordsFromDnir(alloc, m);
    defer freeF64Records(alloc, &records);
    var scal_records = try collectScalRecordsFromDnir(alloc, m);
    defer freeScalRecords(alloc, &scal_records);
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = diagnostic,
        .f64_records = &records,
        .scal_records = &scal_records,
        .entry = entry,
        .const_licence = licence,
        .target_windows = nativeHostKind() == .windows,
    };
    if (std.c.getenv("IDOL_IFCONV_TRACE") != null) compiler.ifconv_trace = true;
    // The tight-def fact's SEVERING CONTROL. Read as a VALUE, not a presence,
    // so both arms of a measurement can carry the name and both decline the
    // build cache — see the `tightdef` field.
    if (std.c.getenv("IDOL_NO_TIGHTDEF")) |raw| {
        if (std.mem.eql(u8, std.mem.span(raw), "1")) compiler.tightdef = false;
    }
    // §12 TAIL's SEVERING CONTROL, read the same way and for the same reason.
    if (std.c.getenv("IDOL_NO_TAILCALL")) |raw| {
        if (std.mem.eql(u8, std.mem.span(raw), "1")) compiler.tailcall = false;
    }
    // §12 `error.depth`'s SEVERING CONTROL. `IDOL_NO_DEPTH=1` restores the
    // unmetered prologue, and with it the unnamed SIGSEGV, so the two arms of
    // "does the meter cost anything / does it catch anything" are one binary.
    if (std.c.getenv("IDOL_NO_DEPTH")) |raw| {
        if (std.mem.eql(u8, std.mem.span(raw), "1")) compiler.depth_meter = false;
    }
    if (m.graph) |graph| {
        if (graph.gateTransportModule()) {
            compiler.gate_transport = true;
            compiler.gp_local_home_budget = 32;
        }
    }
    defer compiler.deinit();
    try compiler.compileDnirModule(m);
    // W8 CENSUS. Off unless asked for: the counts are how the population of
    // convertible and refused branches gets reported honestly rather than
    // asserted.
    if (std.c.getenv("IDOL_IFCONV_REPORT") != null) {
        std.debug.print(
            "ifconv2 two_sided_ifs={d} admitted={d} refused={d} (arm_op_cap={d} latency={d} trap={d} effect_not_none={d} no_termination_fact={d} no_termination_fact_masked={d} termination_would_admit={d} lineage={d})\n",
            .{
                compiler.ifconv_admitted + compiler.ifconv_candidates,
                compiler.ifconv_admitted,
                compiler.ifconv_candidates,
                compiler.ifconv_refused_cap,
                compiler.ifconv_refused_latency,
                compiler.ifconv_refused_trap,
                compiler.ifconv_refused_effect_unknown,
                compiler.ifconv_refused_diverge,
                compiler.ifconv_refused_diverge_masked,
                compiler.ifconv_termination_would_admit,
                compiler.ifconv_refused_lineage,
            },
        );
    }
    // TIGHT-DEF CENSUS. Off unless asked for: how many compare/branch pairs in
    // a real program the fact admits that the index test alone refused,
    // reported rather than asserted.
    if (std.c.getenv("IDOL_TIGHTDEF_REPORT") != null) {
        std.debug.print("tightdef admitted={d}\n", .{compiler.tightdef_admitted});
    }
    // §12 TAIL CENSUS: how many calls in tail position this module realized as
    // a jump. Off unless asked for.
    if (std.c.getenv("IDOL_TAILCALL_REPORT") != null) {
        std.debug.print("tailcall admitted={d}\n", .{compiler.tailcall_admitted});
    }
    // §12 `error.depth` CENSUS: how many of this module's functions carry the
    // metered prologue. Off unless asked for. The number that matters is how
    // FEW: it is the whole cost argument.
    if (std.c.getenv("IDOL_DEPTH_REPORT") != null) {
        std.debug.print(
            "depth metered={d} of {d}\n",
            .{ compiler.depth_metered_count, m.functions.len },
        );
    }
    if (std.c.getenv("IDOL_PROBE_CENSUS") != null) {
        std.debug.print(
            "probe functions={d} probe_compiles={d} descents={d} singlepass={d} fallback={d} plan0={d} planAll={d} planPart={d} call0={d} callN0={d} leaf0={d} leafN0={d}\n",
            .{ compiler.probe_census_functions, compiler.probe_census_probes, compiler.probe_census_descents, compiler.probe_census_singlepass, compiler.probe_census_fallback, compiler.probe_census_plan_zero, compiler.probe_census_plan_all, compiler.probe_census_plan_partial, compiler.probe_census_call_plan0, compiler.probe_census_call_non0, compiler.probe_census_leaf_plan0, compiler.probe_census_leaf_non0 },
        );
    }
    var output = try compiler.finish();
    output.graph = m.graph;
    output.unrealized = unrealizedApplicationCount(m);
    return output;
}

fn collectScalRecordsFromDnir(alloc: std.mem.Allocator, m: dnir.Module) Error!ScalRecordMap {
    var map: ScalRecordMap = .empty;
    errdefer freeScalRecords(alloc, &map);
    for (m.records) |r| {
        var all_f64 = r.kinds.len > 0;
        for (r.kinds) |k| {
            if (k != .f64) all_f64 = false;
        }
        if (all_f64) continue;
        try putScalRecordFromDnir(alloc, &map, r);
    }
    return map;
}

fn putScalRecordFromDnir(alloc: std.mem.Allocator, map: *ScalRecordMap, record: dnir.RecordDesc) Error!void {
    var kinds: std.ArrayListUnmanaged(ScalFieldKind) = .empty;
    defer kinds.deinit(alloc);
    for (record.kinds) |kind| {
        const physical: ScalFieldKind = switch (kind) {
            .str => .str,
            .f64 => .f64,
            .i64 => .i64,
        };
        try kinds.append(alloc, physical);
    }
    const owned_kinds = try kinds.toOwnedSlice(alloc);
    errdefer alloc.free(owned_kinds);
    const entry = try map.getOrPut(alloc, record.name);
    if (entry.found_existing) return error.DuplicateSymbol;
    entry.value_ptr.* = .{
        .field_names = record.fields,
        .field_kinds = owned_kinds,
    };
}

fn collectF64RecordsFromDnir(alloc: std.mem.Allocator, m: dnir.Module) Error!F64RecordMap {
    var map: F64RecordMap = .empty;
    errdefer freeF64Records(alloc, &map);
    for (m.records) |r| {
        if (r.kinds.len == 0) continue;
        var all_f64 = true;
        for (r.kinds) |k| {
            if (k != .f64) {
                all_f64 = false;
                break;
            }
        }
        if (!all_f64) continue;
        const entry = try map.getOrPut(alloc, r.name);
        if (entry.found_existing) return error.DuplicateSymbol;
        entry.value_ptr.* = .{ .field_names = r.fields };
    }
    return map;
}

fn collectDnirRecordMapsAllocationProbe(alloc: std.mem.Allocator) !void {
    const scalar_fields = [_][]const u8{ "count", "label" };
    const scalar_kinds = [_]dnir.FieldKind{ .i64, .str };
    const float_fields = [_][]const u8{ "x", "y" };
    const float_kinds = [_]dnir.FieldKind{ .f64, .f64 };
    const records = [_]dnir.RecordDesc{
        .{ .name = "Scalar", .fields = &scalar_fields, .kinds = &scalar_kinds },
        .{ .name = "Float", .fields = &float_fields, .kinds = &float_kinds },
    };
    const module: dnir.Module = .{ .functions = &.{}, .records = &records };
    var floats = try collectF64RecordsFromDnir(alloc, module);
    defer freeF64Records(alloc, &floats);
    var scalars = try collectScalRecordsFromDnir(alloc, module);
    defer freeScalRecords(alloc, &scalars);
    try std.testing.expect(scalRecordDesc(&scalars, "Scalar").?.field_names.ptr == scalar_fields[0..].ptr);
    try std.testing.expect(f64RecordDesc(&floats, "Float").?.field_names.ptr == float_fields[0..].ptr);
}

test "native backend: DNIR record projections release every failed allocation" {
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        collectDnirRecordMapsAllocationProbe,
        .{},
    );
}

fn emitArm64ModuleWithGraph(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    entry: ?[]const u8,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!Arm64Output {
    if (!graph.gateTransportModule()) {
        _ = try checkedApplications(graph, diagnostic);
    }
    if (!graph.gateTransportModule()) {
        if (graph.firstUnresolvedApplicationExcludingBootstrap(null)) |occurrence| {
            diagnostic.bindOccurrence(graph, occurrence);
            return invalidFactsWith(diagnostic, @src(), "unresolved-application-facts");
        }
    }

    // WHICH TABLES THE SOURCE PERMITS TO BECOME DATA. Computed here, from the
    // AST, because `table_facts.zig` answers over a function body and this is the
    // last place that has one. The DNIR carries no binding names, so the backend
    // could not ask this question for itself.
    var licence = try const_table.licenceForModule(alloc, mod);
    defer licence.deinit();

    const lowered_result = dnir_lower.lowerModuleWithGraphObserved(alloc, mod, graph, &diagnostic.lowering);
    if (lowered_result) |lowered| {
        defer dnir.deinitModule(alloc, lowered);
        if (!graph.gateTransportModule()) {
            try validateDnirApplications(alloc, lowered, graph, diagnostic);
        }
        if (dnir.moduleIsNativeDirectReady(lowered) or graph.gateTransportModule()) {
            var output = try emitArm64FromDnirLicensed(alloc, lowered, entry, diagnostic, &licence);
            errdefer output.deinit(alloc);
            output.graph = graph;
            if (!graph.gateTransportModule()) {
                try validateMachineLineage(alloc, output, graph, diagnostic);
            }
            return output;
        }
        return recordRefusalWith(diagnostic, @src(), "graph-direct-not-ready");
    } else |e| {
        if (std.c.getenv("DUO_DNIR_TRACE") != null) {
            std.debug.print("DUO_DNIR_TRACE: graph DNIR lowering refused with {s}\n", .{@errorName(e)});
            if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
        }
        return switch (e) {
            error.OutOfMemory => error.OutOfMemory,
            error.GraphFactsInvalid => blk: {
                diagnostic.adoptLoweringCause();
                break :blk invalidFactsWith(
                    diagnostic,
                    @src(),
                    diagnostic.lowering.note() orelse "graph-dnir-facts",
                );
            },
            error.UnsupportedConstruct => blk: {
                diagnostic.adoptLoweringCause();
                break :blk recordRefusalWith(
                    diagnostic,
                    @src(),
                    diagnostic.lowering.note() orelse "graph-dnir-unsupported",
                );
            },
        };
    }
}

fn machOTextOffset(cstring_len: usize, const_len: usize, bss_size: u64) usize {
    const header_size: usize = 32;
    const segment_size: usize = 72;
    const section_size: usize = 80;
    const symtab_size: usize = 24;
    const build_version_size: usize = 24;
    const nsects: usize = 1 +
        (if (cstring_len > 0) @as(usize, 1) else 0) +
        (if (const_len > 0) @as(usize, 1) else 0) +
        (if (bss_size > 0) @as(usize, 1) else 0);
    return header_size + segment_size + section_size * nsects + symtab_size + build_version_size;
}

/// The object writer at its established arity. Emits no `__TEXT,__const`, which
/// is exactly what a module with no promoted table needs — kept so every DNIR-
/// only caller and every oracle test below reads the same bytes it always did.
/// THE ONE PLACE `__DATA,__bss` STARTS.
///
/// `Arm64Compiler.finish` stamps every global's `n_value` from this, and
/// `emitMachOArm64ObjectWithConst` lays the section down at this address. Two
/// derivations of one number is how a relocation resolves to the wrong word, so
/// there is one derivation and both call it.
///
/// 8-ALIGNED UNCONDITIONALLY. The pre-existing expression aligned only on the
/// path that had a `__const` section, and fell through to a bare
/// `text.len + cstring.len` otherwise — which is 8-aligned only by luck. Every
/// global is an 8-byte word reached by `ldr x, [x]`, so the unaligned case was
/// a fault waiting for the first module with strings, globals and no promoted
/// table. Nothing observed it before because nothing ever set `bss_size`.
fn bssBaseAddr(text_len: usize, cstring_len: usize, const_len: usize) usize {
    const after_cstring = alignForward(text_len + cstring_len, 8);
    return alignForward(after_cstring + const_len, 8);
}

fn emitMachOArm64Object(alloc: std.mem.Allocator, text: []const u8, cstring: []const u8, symbols: []const Symbol, relocations: []const Relocation, bss_size: u64) Error![]u8 {
    return emitMachOArm64ObjectWithConst(alloc, text, cstring, &.{}, symbols, relocations, &.{}, bss_size, &.{}, true);
}

fn emitMachOArm64ObjectWithConst(
    alloc: std.mem.Allocator,
    text: []const u8,
    cstring: []const u8,
    const_data: []const u8,
    symbols: []const Symbol,
    relocations: []const Relocation,
    data_relocations: []const Relocation,
    bss_size: u64,
    /// The module-global arena's LOAD-TIME CONTENT, or empty for an all-zero
    /// arena. Empty realizes `__DATA,__bss` (S_ZEROFILL, no file bytes) exactly
    /// as before; non-empty realizes `__DATA,__data` (S_REGULAR) at the SAME
    /// address with these bytes, and must then be `bss_size` long.
    ///
    /// ONE SECTION EITHER WAY, so `machOTextOffset`'s section count, every
    /// address derived from `bssBaseAddr`, and every symbol `n_value` stamped in
    /// `finish` are untouched by the choice.
    global_data: []const u8,
    /// Whether the literal blob may be handed over as `S_CSTRING_LITERALS` —
    /// see `Arm64Output.cstring_coalescable`. False keeps the blob in its own
    /// `S_REGULAR` section, which ld copies whole instead of resplitting at
    /// every NUL.
    cstring_coalescable: bool,
) Error![]u8 {
    const segment_size: usize = 72;
    const section_size: usize = 80;
    const symtab_size: usize = 24;
    const build_version_size: usize = 24;
    const has_cstring = cstring.len > 0;
    // `__TEXT,__const` is S_REGULAR read-only data with its own section index.
    //
    // NEITHER OF THE TWO OBVIOUS PLACES WOULD DO. `__cstring` is
    // S_CSTRING_LITERALS — ld splits and dedups its contents at NUL bytes, and a
    // table of i64 literals is mostly NUL bytes, so a blob put there is silently
    // rearranged. `__text` would be counted as INSTRUCTIONS by `otool -tV`,
    // which is the measurement every gate and baseline on this surface is stated
    // in; moving data there would corrupt the numbers rather than improve them.
    const has_const = const_data.len > 0;
    // `__DATA,__bss` is S_ZEROFILL: it has a VM size but NO file bytes, so it
    // adds one section header and leaves every file offset below untouched.
    // That is what makes a writable arena affordable here.
    const has_bss = bss_size > 0;
    // The SAME arena, realized with file bytes because at least one word of it
    // is non-zero. `global_data.len == bss_size` is a requirement, not a
    // convenience: the section's VM size and its file content are the same
    // arena described twice, and a disagreement puts a global's word outside
    // what the loader maps.
    const has_data = has_bss and global_data.len > 0;
    std.debug.assert(!has_data or global_data.len == bss_size);
    const nsects: u32 = 1 +
        (if (has_cstring) @as(u32, 1) else 0) +
        (if (has_const) @as(u32, 1) else 0) +
        (if (has_bss) @as(u32, 1) else 0);
    const sizeofcmds = segment_size + section_size * nsects + symtab_size + build_version_size;
    const text_offset = machOTextOffset(cstring.len, const_data.len, bss_size);
    const reloff: usize = text_offset + text.len;
    const data_reloff: usize = reloff + relocations.len * 8;
    const after_relocs: usize = data_reloff + data_relocations.len * 8;
    const cstring_fileoff: usize = after_relocs;
    const after_cstring: usize = if (has_cstring) cstring_fileoff + cstring.len else after_relocs;
    // 8-byte aligned in the FILE as well as in the VM layout: every element is an
    // 8-byte word and the access path is `ldr x, [base, idx, lsl #3]`.
    const const_fileoff: usize = alignForward(after_cstring, 8);
    const after_const: usize = if (has_const) const_fileoff + const_data.len else after_cstring;
    // `__DATA,__data` is the only writable section with FILE bytes, so it is the
    // only one whose file offset had to be invented. Same 8-byte rule as
    // `__const`, for the same reason: every element is an 8-byte word reached by
    // `ldr x, [x]`.
    const data_fileoff: usize = alignForward(after_const, 8);
    const after_data: usize = if (has_data) data_fileoff + global_data.len else after_const;
    const symoff: usize = alignForward(after_data, 8);
    const stroff: usize = symoff + symbols.len * 16;
    const strtab = try buildStringTable(alloc, symbols);
    defer alloc.free(strtab);

    // The VM addresses the defined local symbols were measured against in
    // `Arm64Compiler.finish`. Both sides compute this the same way — sections in
    // emission order, `__const` rounded up to 8 — because a symbol's n_value and
    // its section's addr must agree or ld resolves the relocation to the wrong
    // word.
    const cstring_addr: usize = text.len;
    const const_addr: usize = alignForward(text.len + cstring.len, 8);
    const bss_addr: usize = bssBaseAddr(text.len, cstring.len, const_data.len);
    // `const_addr` and `bss_addr` must agree with `finish`; see `bssBaseAddr`.
    std.debug.assert(!has_const or const_addr + const_data.len <= bss_addr);

    // Relocation entries live in the file between __text and __cstring but not
    // in the VM layout. llvm-objdump and ld reject LC_SEGMENT_64 when filesize >
    // vmsize, which large gate modules hit once adrp/add relocations accumulate.
    const segment_filesize = symoff - text_offset;
    const segment_vmsize = @max(bss_addr + bss_size, segment_filesize);

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(alloc);

    // mach_header_64
    try appendU32(&out, alloc, 0xfeedfacf);
    try appendU32(&out, alloc, 0x0100000c); // CPU_TYPE_ARM64
    try appendU32(&out, alloc, 0); // CPU_SUBTYPE_ARM64_ALL
    try appendU32(&out, alloc, 1); // MH_OBJECT
    try appendU32(&out, alloc, 3);
    try appendU32(&out, alloc, @intCast(sizeofcmds));
    try appendU32(&out, alloc, 0);
    try appendU32(&out, alloc, 0);

    // LC_SEGMENT_64 (covers __text and, when present, __cstring).
    try appendU32(&out, alloc, 0x19);
    try appendU32(&out, alloc, @intCast(segment_size + section_size * nsects));
    try appendName16(&out, alloc, "");
    try appendU64(&out, alloc, 0); // vmaddr
    try appendU64(&out, alloc, segment_vmsize); // vmsize
    try appendU64(&out, alloc, text_offset); // fileoff
    try appendU64(&out, alloc, segment_filesize); // filesize: section data + their relocations
    try appendU32(&out, alloc, 7); // maxprot
    try appendU32(&out, alloc, 5); // initprot
    try appendU32(&out, alloc, nsects);
    try appendU32(&out, alloc, 0); // flags

    // section 1: __TEXT,__text
    try appendName16(&out, alloc, "__text");
    try appendName16(&out, alloc, "__TEXT");
    try appendU64(&out, alloc, 0); // addr
    try appendU64(&out, alloc, text.len); // size
    try appendU32(&out, alloc, @intCast(text_offset)); // offset
    try appendU32(&out, alloc, 2); // align (2^2 = 4)
    try appendU32(&out, alloc, @intCast(reloff));
    try appendU32(&out, alloc, @intCast(relocations.len));
    try appendU32(&out, alloc, 0x80000400); // S_ATTR_PURE_INSTRUCTIONS | S_ATTR_SOME_INSTRUCTIONS
    try appendU32(&out, alloc, 0);
    try appendU32(&out, alloc, 0);
    try appendU32(&out, alloc, 0);

    // section 2: the string-literal blob. `__TEXT,__cstring` /
    // S_CSTRING_LITERALS when no literal carries an interior NUL — which is
    // every NUL-free module, byte for byte as before — and its own
    // `__TEXT,__conststr` / S_REGULAR section when one does, so ld copies the
    // blob whole instead of re-deriving literal boundaries it cannot see.
    if (has_cstring) {
        try appendName16(&out, alloc, if (cstring_coalescable) "__cstring" else "__conststr");
        try appendName16(&out, alloc, "__TEXT");
        try appendU64(&out, alloc, cstring_addr); // addr (immediately after __text in VM)
        try appendU64(&out, alloc, cstring.len); // size
        try appendU32(&out, alloc, @intCast(cstring_fileoff)); // offset
        try appendU32(&out, alloc, 0); // align (byte)
        try appendU32(&out, alloc, 0); // reloff
        try appendU32(&out, alloc, 0); // nreloc
        try appendU32(&out, alloc, if (cstring_coalescable) 0x2 else 0x0); // S_CSTRING_LITERALS / S_REGULAR
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
    }

    // __TEXT,__const (determined positional tables, as read-only data)
    if (has_const) {
        try appendName16(&out, alloc, "__const");
        try appendName16(&out, alloc, "__TEXT");
        try appendU64(&out, alloc, const_addr); // addr
        try appendU64(&out, alloc, const_data.len); // size
        try appendU32(&out, alloc, @intCast(const_fileoff)); // offset
        try appendU32(&out, alloc, 3); // align (2^3 = 8)
        try appendU32(&out, alloc, 0); // reloff — the data holds no addresses
        try appendU32(&out, alloc, 0); // nreloc
        // S_REGULAR, and NO instruction attributes. `__text` carries
        // S_ATTR_PURE_INSTRUCTIONS | S_ATTR_SOME_INSTRUCTIONS above; a section
        // without them is data to every disassembler, which is what keeps
        // `otool -tV` counting instructions and not table elements.
        try appendU32(&out, alloc, 0x0);
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
    }

    // __DATA — the module-global arena. `__data` when it has load-time content,
    // `__bss` (zerofill) when every word of it is zero. Same address, same size,
    // same symbol offsets; only the flags, the file offset and whether bytes
    // follow differ.
    if (has_bss) {
        try appendName16(&out, alloc, if (has_data) "__data" else "__bss");
        try appendName16(&out, alloc, "__DATA");
        try appendU64(&out, alloc, bss_addr); // addr (after the __TEXT sections)
        try appendU64(&out, alloc, bss_size); // size
        // Zerofill occupies no file bytes and MUST carry offset 0; a regular
        // section carries its real one.
        try appendU32(&out, alloc, if (has_data) @as(u32, @intCast(data_fileoff)) else 0);
        try appendU32(&out, alloc, 3); // align (2^3 = 8)
        // String-literal initializers record ARM64_RELOC_UNSIGNED here; a
        // word with no address still holds no relocation.
        try appendU32(&out, alloc, if (data_relocations.len > 0) @as(u32, @intCast(data_reloff)) else 0); // reloff
        try appendU32(&out, alloc, @intCast(data_relocations.len)); // nreloc
        try appendU32(&out, alloc, if (has_data) @as(u32, 0x0) else 0x1); // S_REGULAR / S_ZEROFILL
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
        try appendU32(&out, alloc, 0);
    }

    // LC_SYMTAB
    try appendU32(&out, alloc, 0x2);
    try appendU32(&out, alloc, @intCast(symtab_size));
    try appendU32(&out, alloc, @intCast(symoff));
    try appendU32(&out, alloc, @intCast(symbols.len));
    try appendU32(&out, alloc, @intCast(stroff));
    try appendU32(&out, alloc, @intCast(strtab.len));

    // LC_BUILD_VERSION: platform macOS, minos/sdk 11.0.0, no tool records.
    try appendU32(&out, alloc, 0x32);
    try appendU32(&out, alloc, @intCast(build_version_size));
    try appendU32(&out, alloc, 1);
    try appendU32(&out, alloc, 0x000b0000);
    try appendU32(&out, alloc, 0x000b0000);
    try appendU32(&out, alloc, 0);

    try out.appendSlice(alloc, text);
    for (relocations) |reloc| {
        const flags: u32 = switch (reloc.kind) {
            .branch26 => reloc.symbol_index | (1 << 24) | (2 << 25) | (1 << 27) | (2 << 28), // pcrel, BR26
            .page21 => reloc.symbol_index | (1 << 24) | (2 << 25) | (1 << 27) | (3 << 28), // pcrel, PAGE21
            .pageoff12 => reloc.symbol_index | (0 << 24) | (2 << 25) | (1 << 27) | (4 << 28), // PAGEOFF12
            .abs64 => unreachable, // data-section only; serialized below
        };
        try appendU32(&out, alloc, reloc.offset);
        try appendU32(&out, alloc, flags);
    }
    for (data_relocations) |reloc| {
        // ARM64_RELOC_UNSIGNED: absolute 64-bit address of a local symbol.
        // r_pcrel=0, r_length=3 (8 bytes), r_extern=1, r_type=0.
        std.debug.assert(reloc.kind == .abs64);
        const flags: u32 = reloc.symbol_index | (0 << 24) | (3 << 25) | (1 << 27) | (0 << 28);
        try appendU32(&out, alloc, reloc.offset);
        try appendU32(&out, alloc, flags);
    }
    if (has_cstring) {
        try out.appendSlice(alloc, cstring);
    }
    if (has_const) {
        if (const_fileoff > out.items.len) try appendZeroes(&out, alloc, const_fileoff - out.items.len);
        try out.appendSlice(alloc, const_data);
    }
    if (has_data) {
        if (data_fileoff > out.items.len) try appendZeroes(&out, alloc, data_fileoff - out.items.len);
        try out.appendSlice(alloc, global_data);
    }
    if (symoff > out.items.len) try appendZeroes(&out, alloc, symoff - out.items.len);

    var strx: u32 = 1;
    for (symbols) |sym| {
        try appendU32(&out, alloc, strx);
        const add_underscore = !(sym.defined and !sym.external);
        if (!sym.defined) {
            try out.append(alloc, 0x01); // N_EXT | N_UNDF
            try out.append(alloc, 0); // n_sect = NO_SECT
        } else if (!sym.external) {
            try out.append(alloc, 0x0e); // N_SECT (local section symbol)
            try out.append(alloc, sym.section);
        } else {
            try out.append(alloc, 0x0f); // N_EXT | N_SECT
            try out.append(alloc, sym.section);
        }
        try appendU16(&out, alloc, 0);
        try appendU64(&out, alloc, sym.offset);
        strx += @intCast(sym.name.len + 1 + (@as(u32, if (add_underscore) 1 else 0)));
    }

    try out.appendSlice(alloc, strtab);
    return out.toOwnedSlice(alloc);
}

fn buildStringTable(alloc: std.mem.Allocator, symbols: []const Symbol) Error![]u8 {
    var table: std.ArrayList(u8) = .empty;
    errdefer table.deinit(alloc);
    try table.append(alloc, 0);
    for (symbols) |sym| {
        // Local string-literal labels are stored without the C-symbol underscore;
        // external/undefined symbols keep the leading underscore by convention.
        if (!(sym.defined and !sym.external)) try table.append(alloc, '_');
        try table.appendSlice(alloc, sym.name);
        try table.append(alloc, 0);
    }
    return table.toOwnedSlice(alloc);
}

fn relocDescByOffset(_: void, a: Relocation, b: Relocation) bool {
    // Mach-O object relocation entries are sorted by descending r_address.
    return a.offset > b.offset;
}

fn appendName16(out: *std.ArrayList(u8), alloc: std.mem.Allocator, name: []const u8) !void {
    var buf: [16]u8 = @splat(0);
    @memcpy(buf[0..@min(name.len, buf.len)], name[0..@min(name.len, buf.len)]);
    try out.appendSlice(alloc, &buf);
}

fn appendZeroes(out: *std.ArrayList(u8), alloc: std.mem.Allocator, count: usize) !void {
    var i: usize = 0;
    while (i < count) : (i += 1) try out.append(alloc, 0);
}

fn appendU16(out: *std.ArrayList(u8), alloc: std.mem.Allocator, value: u16) !void {
    var buf: [2]u8 = undefined;
    std.mem.writeInt(u16, &buf, value, .little);
    try out.appendSlice(alloc, &buf);
}

fn appendU32(out: *std.ArrayList(u8), alloc: std.mem.Allocator, value: u32) !void {
    var buf: [4]u8 = undefined;
    std.mem.writeInt(u32, &buf, value, .little);
    try out.appendSlice(alloc, &buf);
}

fn appendU64(out: *std.ArrayList(u8), alloc: std.mem.Allocator, value: u64) !void {
    var buf: [8]u8 = undefined;
    std.mem.writeInt(u64, &buf, value, .little);
    try out.appendSlice(alloc, &buf);
}


// ============================================================================
// Direct AArch64+Linux static ELF64 executable writer.
//
// Takes the same lowered module the Mach-O writer takes and returns a
// ready-to-run static executable: no assembler, no linker, no libc, no host
// toolchain. The Linux kernel maps the three PT_LOAD segments and jumps to
// the _start stub, which calls the Idol entry and exits via __NR_exit.
//
// Layout (file offsets; vaddr = elfBaseVaddr + file offset for every byte):
//   [0, 64)      ELF64 header (ET_EXEC, EM_AARCH64)
//   [64, 232)    3 x Elf64_Phdr: R+X headers+stub+text, R rodata, RW data
//   [232, 244)   _start stub: bl <entry>; mov x8, #93; svc #0
//   [244, ...)   .text
//   page-aligned .rodata = cstring ++ zero pad ++ const_data        (R)
//   page-aligned .data   = global_data                              (RW;
//                p_memsz covers the bss tail; the kernel zero-fills it)
//
// Relocations resolve here, at emission time: page21/pageoff12 against the
// symbol's final vaddr, abs64 as a little-endian u64. branch26 needs no
// patch — .text shifts as one unit, so PC-relative branches are already
// correct. Any undefined symbol is refused as DNB013 before this runs.
//
// A symbol's offset is stamped by `finish` as an absolute address in the VM
// layout (text at 0, then cstring, then 8-aligned const, then bss), NOT as a
// Mach-O section-relative value — so the writer maps each symbol to its ELF
// section by offset RANGE, without consulting Mach-O section indices at all.
// .rodata mirrors that VM order exactly (cstring, pad-to-8, const), so
// (offset - text.len) is the rodata offset.
// ============================================================================

/// Base virtual address every direct-ELF image is linked at, clear of the
/// Linux arm64 default mmap base. Each segment's vaddr is base + its file
/// offset, so p_offset === p_vaddr (mod p_align) holds by construction.
const elfBaseVaddr: u64 = 0x400000;
/// 64 KiB: the only page size Linux arm64 guarantees.
const elfPageAlign: u64 = 0x10000;
/// File offset of `.text`: 64-byte EHDR + 3x56-byte PHDR + 12-byte stub.
const elfTextOff: usize = 64 + 3 * 56 + 12;

/// File offset of `.text` in the direct-ELF image. Lineage rows add their
/// text-relative ranges to this, mirroring the `machOTextOffset` use.
fn elfTextFileOffset() usize {
    return elfTextOff;
}

/// Patch an `adrp` placeholder (emitted as `adrp rd, #0`) to target
/// `target_vaddr` from the instruction at `insn_vaddr`. Keeps Rd and the
/// opcode; rewrites immlo (bits 30:29) and immhi (bits 23:5).
fn patchAdrp(word: u32, insn_vaddr: u64, target_vaddr: u64) u32 {
    const page_mask = ~@as(u64, 0xfff);
    const diff: i64 = @as(i64, @intCast(target_vaddr & page_mask)) - @as(i64, @intCast(insn_vaddr & page_mask));
    std.debug.assert(@rem(diff, 0x1000) == 0);
    const imm21 = @divTrunc(diff, 0x1000);
    std.debug.assert(imm21 >= -(1 << 20) and imm21 < (1 << 20));
    const imm: u32 = @as(u32, @intCast(imm21 & 0x1fffff));
    return (word & 0x9f00001f) | ((imm & 0x3) << 29) | (((imm >> 2) & 0x7ffff) << 5);
}

/// Patch a page-offset imm12 (bits 21:10). The caller selects the value:
/// plain `add` takes the byte offset; load/store forms scale it by their
/// access size first (see the pageoff12 arm of the writer).
fn patchAddImm12(word: u32, page_offset: u32) u32 {
    std.debug.assert(page_offset < 0x1000);
    return (word & 0xffc003ff) | ((page_offset & 0xfff) << 10);
}

fn writeElfPhdr(phdr: *[56]u8, p_type: u32, p_flags: u32, p_offset: u64, p_vaddr: u64, p_filesz: u64, p_memsz: u64, p_align: u64) void {
    std.mem.writeInt(u32, phdr[0..4], p_type, .little);
    std.mem.writeInt(u32, phdr[4..8], p_flags, .little);
    std.mem.writeInt(u64, phdr[8..16], p_offset, .little);
    std.mem.writeInt(u64, phdr[16..24], p_vaddr, .little);
    std.mem.writeInt(u64, phdr[24..32], p_vaddr, .little); // p_paddr = p_vaddr
    std.mem.writeInt(u64, phdr[32..40], p_filesz, .little);
    std.mem.writeInt(u64, phdr[40..48], p_memsz, .little);
    std.mem.writeInt(u64, phdr[48..56], p_align, .little);
}

/// Final virtual address of a lowered symbol, by VM-layout offset range.
/// Anything outside the three known ranges is a lowering/writer
/// disagreement — fail closed, never guess a section.
fn elfSymbolVAddr(
    sym: Symbol,
    text_len: usize,
    rodata_len: usize,
    bss_base: usize,
    bss_size: u64,
    text_vaddr: u64,
    rodata_vaddr: u64,
    data_vaddr: u64,
) Error!u64 {
    const o: usize = sym.offset;
    if (o < text_len) return text_vaddr + @as(u64, o);
    if (o < text_len + rodata_len) return rodata_vaddr + @as(u64, o - text_len);
    if (o >= bss_base and o < bss_base + @as(usize, bss_size)) return data_vaddr + @as(u64, o - bss_base);
    return error.SemanticFactsInvalid;
}

fn emitElfArm64StaticExec(
    alloc: std.mem.Allocator,
    text: []const u8,
    cstring: []const u8,
    const_data: []const u8,
    symbols: []const Symbol,
    relocations: []const Relocation,
    data_relocations: []const Relocation,
    bss_size: u64,
    global_data: []const u8,
    entry: []const u8,
) Error![]u8 {
    // .rodata mirrors the VM layout: cstring, then zero padding to the same
    // 8-alignment `finish` uses, then const_data — so a symbol's VM offset
    // minus text.len is its rodata offset, with no section-index decoding.
    const rodata_pad = (8 - ((text.len + cstring.len) % 8)) % 8;
    const rodata_len = cstring.len + rodata_pad + const_data.len;
    const bss_base = bssBaseAddr(text.len, cstring.len, const_data.len);

    const text_off: usize = elfTextOff;
    const text_vaddr: u64 = elfBaseVaddr + @as(u64, text_off);
    const seg1_filesz: usize = text_off + text.len;

    const rodata_off: usize = alignForward(seg1_filesz, @intCast(elfPageAlign));
    const rodata_vaddr: u64 = elfBaseVaddr + @as(u64, rodata_off);
    const data_off: usize = alignForward(rodata_off + rodata_len, @intCast(elfPageAlign));
    const data_vaddr: u64 = elfBaseVaddr + @as(u64, data_off);
    const total: usize = data_off + global_data.len;

    // The stub's bl targets the ENTRY symbol, not text start, so a future
    // reordering of functions cannot silently break the entry point.
    const link_entry = try linkerSymbolName(alloc, entry);
    defer alloc.free(link_entry);
    var entry_off: ?u32 = null;
    for (symbols) |sym| {
        if (!sym.defined) continue;
        if (std.mem.eql(u8, sym.name, link_entry)) {
            entry_off = sym.offset;
            break;
        }
    }
    const eoff = entry_off orelse return error.MissingMain;
    if (@as(usize, eoff) >= text.len) return error.SemanticFactsInvalid;
    const entry_vaddr: u64 = text_vaddr + eoff;

    var out = try alloc.alloc(u8, total);
    errdefer alloc.free(out);
    @memset(out, 0);

    // --- ELF header ---
    out[0] = 0x7f;
    out[1] = 'E';
    out[2] = 'L';
    out[3] = 'F';
    out[4] = 2; // ELFCLASS64
    out[5] = 1; // ELFDATA2LSB
    out[6] = 1; // EV_CURRENT
    out[7] = 0; // ELFOSABI_SYSV
    // [8, 16) already zero
    std.mem.writeInt(u16, out[16..18], 2, .little); // ET_EXEC
    std.mem.writeInt(u16, out[18..20], 183, .little); // EM_AARCH64
    std.mem.writeInt(u32, out[20..24], 1, .little); // EV_CURRENT
    std.mem.writeInt(u64, out[24..32], elfBaseVaddr + 232, .little); // e_entry: the _start stub
    std.mem.writeInt(u64, out[32..40], 64, .little); // e_phoff
    // e_shoff = 0 (no section headers in an executable image)
    std.mem.writeInt(u32, out[48..52], 0, .little); // e_flags
    std.mem.writeInt(u16, out[52..54], 64, .little); // e_ehsize
    std.mem.writeInt(u16, out[54..56], 56, .little); // e_phentsize
    std.mem.writeInt(u16, out[56..58], 3, .little); // e_phnum
    // e_shentsize / e_shnum / e_shstrndx stay zero

    // --- Program headers: R+X headers+stub+text, R rodata, RW data ---
    writeElfPhdr(out[64..][0..56], 1, 5, 0, elfBaseVaddr, @intCast(seg1_filesz), @intCast(seg1_filesz), elfPageAlign);
    writeElfPhdr(out[120..][0..56], 1, 4, @intCast(rodata_off), rodata_vaddr, @intCast(rodata_len), @intCast(rodata_len), elfPageAlign);
    writeElfPhdr(out[176..][0..56], 1, 6, @intCast(data_off), data_vaddr, @intCast(global_data.len), bss_size, elfPageAlign);

    // --- _start stub: bl <entry>; mov x8, #93 (__NR_exit); svc #0 ---
    const stub_vaddr: u64 = elfBaseVaddr + 232;
    const delta: i64 = @as(i64, @intCast(entry_vaddr)) - @as(i64, @intCast(stub_vaddr));
    if (delta < -0x8000000 or delta >= 0x8000000) return error.BranchOutOfRange;
    if (@rem(delta, 4) != 0) return error.BranchOutOfRange;
    const bl_imm: u32 = @as(u32, @bitCast(@as(i32, @intCast(@divTrunc(delta, 4))))) & 0x03ffffff;
    std.mem.writeInt(u32, out[232..][0..4], 0x94000000 | bl_imm, .little);
    std.mem.writeInt(u32, out[236..][0..4], 0xd2800ba8, .little); // mov x8, #93
    std.mem.writeInt(u32, out[240..][0..4], 0xd4000001, .little); // svc #0

    // --- .text ---
    @memcpy(out[text_off..][0..text.len], text);
    for (relocations) |rel| {
        if (rel.symbol_index >= symbols.len) return error.SemanticFactsInvalid;
        if (@as(usize, rel.offset) + 4 > text.len) return error.SemanticFactsInvalid;
        const sym = symbols[rel.symbol_index];
        if (!sym.defined) return error.UnknownSymbol;
        const target = try elfSymbolVAddr(sym, text.len, rodata_len, bss_base, bss_size, text_vaddr, rodata_vaddr, data_vaddr);
        const at: usize = text_off + rel.offset;
        switch (rel.kind) {
            .branch26 => {
                // PC-relative: .text shifts as one unit, already correct.
            },
            .page21 => {
                const word = std.mem.readInt(u32, out[at..][0..4], .little);
                std.mem.writeInt(u32, out[at..][0..4], patchAdrp(word, text_vaddr + rel.offset, target), .little);
            },
            .pageoff12 => {
                const word = std.mem.readInt(u32, out[at..][0..4], .little);
                const page_offset: u32 = @intCast(target & 0xfff);
                // Opcode-aware: `add` takes the byte offset; `ldr`
                // scales the unsigned immediate by its 8-byte access
                // size. Anything else is a producer this writer does
                // not know — fail closed, never guess.
                const patched = if (word & 0xff000000 == 0x91000000)
                    patchAddImm12(word, page_offset)
                else if (word & 0xffc00000 == 0xf9400000) blk: {
                    if (page_offset % 8 != 0) return error.SemanticFactsInvalid;
                    break :blk patchAddImm12(word, page_offset >> 3);
                } else return error.SemanticFactsInvalid;
                std.mem.writeInt(u32, out[at..][0..4], patched, .little);
            },
            .abs64 => return error.SemanticFactsInvalid,
        }
    }

    // --- .rodata ---
    @memcpy(out[rodata_off..][0..cstring.len], cstring);
    // rodata_pad bytes are already zero
    @memcpy(out[rodata_off + cstring.len + rodata_pad ..][0..const_data.len], const_data);

    // --- .data (+ bss tail, zero-filled by the kernel via p_memsz) ---
    @memcpy(out[data_off..][0..global_data.len], global_data);
    for (data_relocations) |rel| {
        if (rel.symbol_index >= symbols.len) return error.SemanticFactsInvalid;
        if (rel.kind != .abs64) return error.SemanticFactsInvalid;
        if (@as(usize, rel.offset) + 8 > global_data.len) return error.SemanticFactsInvalid;
        const sym = symbols[rel.symbol_index];
        if (!sym.defined) return error.UnknownSymbol;
        const target = try elfSymbolVAddr(sym, text.len, rodata_len, bss_base, bss_size, text_vaddr, rodata_vaddr, data_vaddr);
        std.mem.writeInt(u64, out[data_off + rel.offset ..][0..8], target, .little);
    }

    return out;
}

// ============================================================================
// Direct AArch64+Windows PE32+ executable writer.
//
// Same structural role as the ELF writer above: the production native backend
// lowers Idol to AArch64 machine code once, and this writer packages the
// lowered image as a PE32+ for Windows on ARM64 (IMAGE_FILE_MACHINE_ARM64 =
// 0xAA64) — no linker, no CRT startup object, no import library.
//
// WHY IMPORTS, AND WHY THESE DLLS. Windows publishes no stable raw-syscall
// ABI: NTDLL syscall numbers change between builds and Microsoft documents
// direct system-call invocation as unsupported. The supported mechanism is
// the loader-resolved import table, so every OS service in a PE image is a
// DLL import:
//
//   msvcrt.dll    puts, printf, fflush (+ vprintf, memcpy, memmove, memset,
//                 memcmp, strlen for compiler-emitted helpers) — `print`
//                 lowers to `bl puts` / `bl printf` (see `print_value`); the
//                 call sites are unchanged, and each becomes a thunk (below)
//                 that calls through the IAT.
//   kernel32.dll  ExitProcess — the entry stub tail-calls it with the Idol
//                 entry's i64 exit code in x0. There is no raw exit syscall
//                 to use instead.
//
// GetStdHandle/WriteFile are deliberately NOT imported: nothing in the
// lowering does raw fd I/O (puts covers stdout; the depth-fault message goes
// through puts too), so they would be unused surface. NTDLL is deliberately
// NOT used: see the syscall paragraph above.
//
// Traps (div-by-zero, depth fault, bounds) cannot be syscalls either. They
// are `__fastfail`: the documented immediate-termination primitive, which on
// ARM64 is exactly `brk #0xF000` (0xD43E0000) with the failure code in w0 —
// no import, no return, WER reports the code.
//   0x1D01  generic trap (div-by-zero, unreachable)
//   0x1D02  depth/bounds fault (message already on stdout via puts)
//
// Calls to imports go through per-import thunks appended to .text:
//
//     sub sp, sp, #32        ; Windows callee home (shadow) space; 32 keeps
//     adrp x16, <iat page>   ; the 16-byte stack alignment
//     ldr x16, [x16, #<off>] ; x16 = IAT slot (loader-resolved)
//     blr x16
//     add sp, sp, #32
//     ret
//
// A `bl puts` (branch26 relocation against an undefined symbol) is rewritten
// to `bl <thunk>` — the same size, still PC-relative, so no layout shift.
// The thunk does the Windows-calling-convention work once per import
// instead of once per call site.
//
// The entry stub (16 bytes at the top of .text) is:
//
//     bl <entry>             ; the Idol entry; x0 = i64 exit code
//     adrp x16, <iat page>   ; ExitProcess slot
//     ldr x16, [x16, #<off>]
//     br x16                 ; tail-call; never returns
//
// Layout (RVAs; vaddr = ImageBase + rva):
//   DOS header (64 B; e_lfanew = 64; no stub — the loader needs MZ + lfanew)
//   PE sig + COFF (Machine 0xAA64, 3 sections) + PE32+ optional header
//   .text   RVA 0x1000: entry stub, .text bytes, import thunks
//   .rdata  section-aligned: import directory, ILT, IAT, hint/name table,
//           DLL names
//   .data   section-aligned: global_data; bss tail via VirtualSize (the
//           loader zero-fills what has no file bytes)
//
// Relocations resolve here, at emission time, exactly like the ELF writer:
// page21/pageoff12 against the symbol's final vaddr (ImageBase + rva),
// abs64 as a little-endian u64 in .data, branch26 PC-relative within .text
// (already correct) or rewritten to the import's thunk.
//
// No .reloc section is emitted and DllCharacteristics omits DYNAMIC_BASE:
// the image loads at its linked ImageBase, honestly fixed rather than
// pretending to be relocatable.
//
// Undefined symbols outside the known import set are refused as DNB014 —
// fail closed, never guessed into an import table.
// ============================================================================

/// IMAGE_FILE_MACHINE_ARM64.
const peMachineArm64: u16 = 0xAA64;
/// PE32+ optional-header magic.
const peOptMagic: u16 = 0x20b;
/// Default Windows image base for ARM64 executables.
const peImageBase: u64 = 0x140000000;
// Untyped: coerces to usize for alignForward and to u64 for RVA arithmetic.
const peSectionAlign = 0x1000;
const peFileAlign = 0x200;
/// Headers before the first section: DOS(64) + sig(4) + COFF(20) +
/// optional(240) + 3 section headers(120) = 448, rounded to FileAlignment.
const peSizeOfHeaders: usize = 0x200;
/// Entry stub: bl entry; adrp x16, iat; ldr x16, [x16, #off]; br x16.
const peStubLen: usize = 16;
/// Import thunk: sub sp,sp,#32; adrp; ldr; blr; add sp,sp,#32; ret.
const peThunkLen: usize = 24;
/// __fastfail codes (w0) — the classes are documented above.
const peTrapGeneric: u32 = 0x1d01;
const peTrapDepth: u32 = 0x1d02;
/// Stack reserve declared in the PE header; the depth-limit init on the PE
/// path derives its floor from this instead of probing getrlimit.
const peStackReserve: u64 = 0x100000;
const peDllMsvcrt = "msvcrt.dll";
const peDllKernel32 = "kernel32.dll";

/// File offset of `.text` content in the PE image (headers + entry stub).
/// Lineage rows add their text-relative ranges to this, mirroring the
/// `elfTextFileOffset` use.
fn peTextFileOffset() usize {
    return peSizeOfHeaders + peStubLen;
}

/// Which DLL provides a known import name. Anything else is DNB014.
fn peImportDll(name: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, name, "ExitProcess")) return peDllKernel32;
    const crt = [_][]const u8{ "puts", "printf", "fflush", "vprintf", "memcpy", "memmove", "memset", "memcmp", "strlen" };
    for (crt) |c| {
        if (std.mem.eql(u8, name, c)) return peDllMsvcrt;
    }
    return null;
}

/// Final virtual address of a lowered symbol, by VM-layout offset range —
/// the same VM layout the ELF writer uses (text, then cstring, then
/// 8-aligned const, then bss), so no section-index decoding is needed.
fn peSymbolVAddr(
    sym: Symbol,
    text_len: usize,
    rodata_len: usize,
    bss_base: usize,
    bss_size: u64,
    text_vaddr: u64,
    rodata_vaddr: u64,
    data_vaddr: u64,
) Error!u64 {
    const o: usize = sym.offset;
    if (o < text_len) return text_vaddr + @as(u64, o);
    if (o < text_len + rodata_len) return rodata_vaddr + @as(u64, o - text_len);
    if (o >= bss_base and o < bss_base + @as(usize, bss_size)) return data_vaddr + @as(u64, o - bss_base);
    return error.SemanticFactsInvalid;
}

fn writePeSectionHeader(sh: *[40]u8, name: []const u8, vsize: u32, vaddr: u32, raw_size: u32, raw_ptr: u32, chars: u32) void {
    @memset(sh[0..8], 0);
    const n = @min(name.len, 8);
    @memcpy(sh[0..n], name[0..n]);
    std.mem.writeInt(u32, sh[8..12], vsize, .little);
    std.mem.writeInt(u32, sh[12..16], vaddr, .little);
    std.mem.writeInt(u32, sh[16..20], raw_size, .little);
    std.mem.writeInt(u32, sh[20..24], raw_ptr, .little);
    std.mem.writeInt(u32, sh[36..40], chars, .little);
}

fn emitPeArm64StaticExec(
    alloc: std.mem.Allocator,
    text: []const u8,
    cstring: []const u8,
    const_data: []const u8,
    symbols: []const Symbol,
    relocations: []const Relocation,
    data_relocations: []const Relocation,
    bss_size: u64,
    global_data: []const u8,
    entry: []const u8,
) Error![]u8 {
    if (bss_size > 0xffffffff) return error.SemanticFactsInvalid;

    // --- imports: undefined symbols in first-seen order, ExitProcess appended.
    // A duplicate name cannot be both defined here and imported (the
    // lowerer refuses that as DuplicateSymbol), so first-seen order is
    // total and deterministic.
    var import_names: std.ArrayListUnmanaged([]const u8) = .empty;
    defer import_names.deinit(alloc);
    var seen_exit = false;
    for (symbols) |sym| {
        if (sym.defined) continue;
        var dup = false;
        for (import_names.items) |n| if (std.mem.eql(u8, n, sym.name)) {
            dup = true;
            break;
        };
        if (dup) continue;
        if (peImportDll(sym.name) == null) return error.UnknownImportSymbol;
        if (std.mem.eql(u8, sym.name, "ExitProcess")) seen_exit = true;
        try import_names.append(alloc, sym.name);
    }
    if (!seen_exit) try import_names.append(alloc, "ExitProcess");
    const nimports = import_names.items.len;

    // DLLs are emitted in a fixed order; imports keep first-seen order
    // within their DLL.
    const dlls = [_][]const u8{ peDllMsvcrt, peDllKernel32 };
    var dll_counts = [_]usize{ 0, 0 };
    var import_dll = try alloc.alloc(u8, nimports);
    defer alloc.free(import_dll);
    var import_slot = try alloc.alloc(u32, nimports);
    defer alloc.free(import_slot);
    for (import_names.items, 0..) |name, i| {
        const dll = peImportDll(name) orelse return error.UnknownImportSymbol;
        var di: u8 = 0;
        for (dlls, 0..) |d, k| if (std.mem.eql(u8, d, dll)) {
            di = @intCast(k);
            break;
        };
        import_dll[i] = di;
        import_slot[i] = @intCast(dll_counts[di]);
        dll_counts[di] += 1;
    }
    var ndll: usize = 0;
    for (dll_counts) |c| {
        if (c > 0) ndll += 1;
    }

    // --- section layout (RVAs; file offsets are FileAlignment-rounded) ---
    const text_rva: u64 = 0x1000;
    const text_file: usize = peSizeOfHeaders;
    const content_file: usize = text_file + peStubLen;
    const content_rva: u64 = text_rva + @as(u64, peStubLen);
    const content_vaddr: u64 = peImageBase + content_rva;
    const thunks_file: usize = content_file + text.len;
    const thunks_rva: u64 = content_rva + @as(u64, text.len);
    const text_vsize: u64 = @as(u64, peStubLen) + @as(u64, text.len) + @as(u64, peThunkLen) * @as(u64, nimports);
    const text_raw: usize = alignForward(@as(usize, @intCast(text_vsize)), peFileAlign);

    const rdata_rva: u64 = text_rva + @as(u64, alignForward(@as(usize, @intCast(text_vsize)), peSectionAlign));
    const rdata_file: usize = text_file + text_raw;
    // .rdata: import directory (20/dll + 20 null), ILT+IAT (8*(n+1) each
    // per dll), hint/name entries, DLL names.
    var rdata_len: usize = 20 * (ndll + 1);
    for (dll_counts) |c| {
        if (c == 0) continue;
        rdata_len += 16 * (c + 1);
    }
    for (import_names.items) |name| rdata_len += alignForward(2 + name.len + 1, 2);
    for (dlls, 0..) |d, k| {
        if (dll_counts[k] == 0) continue;
        rdata_len += d.len + 1;
    }
    const rdata_raw: usize = alignForward(rdata_len, peFileAlign);

    const data_rva: u64 = rdata_rva + @as(u64, alignForward(rdata_len, peSectionAlign));
    const data_file: usize = rdata_file + rdata_raw;
    const data_vsize: u64 = @as(u64, global_data.len) + bss_size;
    const data_raw: usize = alignForward(global_data.len, peFileAlign);
    const image_size: u64 = data_rva + @as(u64, alignForward(@as(usize, @intCast(data_vsize)), peSectionAlign));
    const total: usize = data_file + data_raw;

    // --- .rdata RVA assignment (all of these ARE rvas, not file offsets) ---
    var ilt_rva = [_]u64{ 0, 0 };
    var iat_rva = [_]u64{ 0, 0 };
    var dll_name_rva = [_]u64{ 0, 0 };
    var ro: usize = 20 * (ndll + 1);
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        ilt_rva[k] = rdata_rva + ro;
        ro += 8 * (dll_counts[k] + 1);
    }
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        iat_rva[k] = rdata_rva + ro;
        ro += 8 * (dll_counts[k] + 1);
    }
    var hn_rva = try alloc.alloc(u64, nimports);
    defer alloc.free(hn_rva);
    for (import_names.items, 0..) |name, i| {
        hn_rva[i] = rdata_rva + ro;
        ro += alignForward(2 + name.len + 1, 2);
    }
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        dll_name_rva[k] = rdata_rva + ro;
        ro += dlls[k].len + 1;
    }
    std.debug.assert(ro == rdata_len);

    // --- entry symbol ---
    const link_entry = try linkerSymbolName(alloc, entry);
    defer alloc.free(link_entry);
    var entry_off: ?u32 = null;
    for (symbols) |sym| {
        if (!sym.defined) continue;
        if (std.mem.eql(u8, sym.name, link_entry)) {
            entry_off = sym.offset;
            break;
        }
    }
    const eoff = entry_off orelse return error.MissingMain;
    if (@as(usize, eoff) >= text.len) return error.SemanticFactsInvalid;
    const entry_vaddr: u64 = content_vaddr + @as(u64, eoff);

    var out = try alloc.alloc(u8, total);
    errdefer alloc.free(out);
    @memset(out, 0);

    // --- DOS header: MZ + e_lfanew; no stub, the loader needs nothing else.
    out[0] = 'M';
    out[1] = 'Z';
    std.mem.writeInt(u32, out[60..64], 64, .little); // e_lfanew
    // --- PE signature ---
    out[64] = 'P';
    out[65] = 'E';
    // --- COFF header ---
    std.mem.writeInt(u16, out[68..70], peMachineArm64, .little);
    std.mem.writeInt(u16, out[70..72], 3, .little); // NumberOfSections
    // TimeDateStamp stays 0: deterministic output.
    std.mem.writeInt(u16, out[84..86], 240, .little); // SizeOfOptionalHeader
    std.mem.writeInt(u16, out[86..88], 0x0022, .little); // EXECUTABLE_IMAGE | LARGE_ADDRESS_AWARE
    // --- PE32+ optional header ---
    std.mem.writeInt(u16, out[88..90], peOptMagic, .little);
    std.mem.writeInt(u32, out[92..96], @as(u32, @intCast(text_raw)), .little); // SizeOfCode
    std.mem.writeInt(u32, out[96..100], @as(u32, @intCast(rdata_raw + data_raw)), .little); // SizeOfInitializedData
    std.mem.writeInt(u32, out[100..104], @as(u32, @intCast(bss_size)), .little); // SizeOfUninitializedData
    std.mem.writeInt(u32, out[104..108], @as(u32, @intCast(text_rva)), .little); // AddressOfEntryPoint: the stub
    std.mem.writeInt(u32, out[108..112], @as(u32, @intCast(text_rva)), .little); // BaseOfCode
    std.mem.writeInt(u64, out[112..120], peImageBase, .little);
    std.mem.writeInt(u32, out[120..124], @as(u32, @intCast(peSectionAlign)), .little);
    std.mem.writeInt(u32, out[124..128], @as(u32, @intCast(peFileAlign)), .little);
    std.mem.writeInt(u16, out[128..130], 6, .little); // MajorOperatingSystemVersion
    std.mem.writeInt(u16, out[136..138], 6, .little); // MajorSubsystemVersion
    std.mem.writeInt(u32, out[144..148], @as(u32, @intCast(image_size)), .little); // SizeOfImage
    std.mem.writeInt(u32, out[148..152], @as(u32, @intCast(peSizeOfHeaders)), .little); // SizeOfHeaders
    std.mem.writeInt(u16, out[156..158], 3, .little); // Subsystem: CONSOLE
    // DllCharacteristics: NX_COMPAT | TERMINAL_SERVER_AWARE. DYNAMIC_BASE is
    // deliberately NOT set: no .reloc section is emitted, so the image must
    // load at its linked ImageBase (all relocations resolve at emission).
    std.mem.writeInt(u16, out[158..160], 0x8100, .little);
    std.mem.writeInt(u64, out[160..168], peStackReserve, .little);
    std.mem.writeInt(u64, out[168..176], 0x1000, .little); // SizeOfStackCommit
    std.mem.writeInt(u64, out[176..184], 0x100000, .little); // SizeOfHeapReserve
    std.mem.writeInt(u64, out[184..192], 0x1000, .little); // SizeOfHeapCommit
    std.mem.writeInt(u32, out[196..200], 16, .little); // NumberOfRvaAndSizes
    std.mem.writeInt(u32, out[208..212], @as(u32, @intCast(rdata_rva)), .little); // Import Table RVA
    std.mem.writeInt(u32, out[212..216], @as(u32, @intCast(20 * (ndll + 1))), .little); // Import Table size
    // --- section headers ---
    writePeSectionHeader(out[328..][0..40], ".text", @as(u32, @intCast(text_vsize)), @as(u32, @intCast(text_rva)), @as(u32, @intCast(text_raw)), @as(u32, @intCast(text_file)), 0x60000020);
    writePeSectionHeader(out[368..][0..40], ".rdata", @as(u32, @intCast(rdata_len)), @as(u32, @intCast(rdata_rva)), @as(u32, @intCast(rdata_raw)), @as(u32, @intCast(rdata_file)), 0x40000040);
    writePeSectionHeader(out[408..][0..40], ".data", @as(u32, @intCast(data_vsize)), @as(u32, @intCast(data_rva)), @as(u32, @intCast(data_raw)), @as(u32, @intCast(data_file)), 0xc0000040);

    // --- .rdata: import directory (20 bytes per DLL + 20 null) ---
    var dir_n: usize = 0;
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        const e: usize = rdata_file + 20 * dir_n;
        std.mem.writeInt(u32, out[e..][0..4], @as(u32, @intCast(ilt_rva[k])), .little);
        // TimeDateStamp + ForwarderChain stay 0.
        std.mem.writeInt(u32, out[e + 12 ..][0..4], @as(u32, @intCast(dll_name_rva[k])), .little);
        std.mem.writeInt(u32, out[e + 16 ..][0..4], @as(u32, @intCast(iat_rva[k])), .little);
        dir_n += 1;
    }
    // --- .rdata: ILT (loader reads) + IAT (loader writes) ---
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        const ilt_file: usize = rdata_file + @as(usize, @intCast(ilt_rva[k] - rdata_rva));
        const iat_file: usize = rdata_file + @as(usize, @intCast(iat_rva[k] - rdata_rva));
        var s: usize = 0;
        for (import_names.items, 0..) |name, i| {
            if (import_dll[i] != k) continue;
            std.debug.assert(import_slot[i] == @as(u32, @intCast(s)));
            _ = name;
            const hrva: u64 = hn_rva[i];
            std.mem.writeInt(u64, out[ilt_file + s * 8 ..][0..8], hrva, .little);
            std.mem.writeInt(u64, out[iat_file + s * 8 ..][0..8], hrva, .little);
            s += 1;
        }
        std.debug.assert(s == dll_counts[k]);
    }
    // --- .rdata: hint/name entries ---
    for (import_names.items, 0..) |name, i| {
        const at: usize = rdata_file + @as(usize, @intCast(hn_rva[i] - rdata_rva));
        std.mem.writeInt(u16, out[at..][0..2], 0, .little); // hint
        @memcpy(out[at + 2 ..][0..name.len], name);
        out[at + 2 + name.len] = 0;
    }
    // --- .rdata: DLL names ---
    for (0..2) |k| {
        if (dll_counts[k] == 0) continue;
        const at: usize = rdata_file + @as(usize, @intCast(dll_name_rva[k] - rdata_rva));
        @memcpy(out[at..][0..dlls[k].len], dlls[k]);
        out[at + dlls[k].len] = 0;
    }

    // --- entry stub ---
    // ExitProcess is always an import (appended above); find its IAT slot.
    var exit_i: usize = 0;
    for (import_names.items, 0..) |name, i| if (std.mem.eql(u8, name, "ExitProcess")) {
        exit_i = i;
        break;
    };
    const exit_slot_vaddr: u64 = peImageBase + iat_rva[@as(usize, import_dll[exit_i])] + @as(u64, import_slot[exit_i]) * 8;
    const stub_vaddr: u64 = peImageBase + text_rva;
    const delta: i64 = @as(i64, @intCast(entry_vaddr)) - @as(i64, @intCast(stub_vaddr));
    if (delta < -0x8000000 or delta >= 0x8000000) return error.BranchOutOfRange;
    if (@rem(delta, 4) != 0) return error.BranchOutOfRange;
    const bl_imm: u32 = @as(u32, @bitCast(@as(i32, @intCast(@divTrunc(delta, 4))))) & 0x03ffffff;
    std.mem.writeInt(u32, out[text_file..][0..4], 0x94000000 | bl_imm, .little);
    std.mem.writeInt(u32, out[text_file + 4 ..][0..4], patchAdrp(0x90000010, stub_vaddr + 4, exit_slot_vaddr), .little);
    const exit_off: u32 = @intCast(exit_slot_vaddr & 0xfff);
    std.mem.writeInt(u32, out[text_file + 8 ..][0..4], 0xf9400000 | ((exit_off >> 3) << 10) | (16 << 5) | 16, .little); // ldr x16, [x16, #off]
    std.mem.writeInt(u32, out[text_file + 12 ..][0..4], 0xd61f0200, .little); // br x16

    // --- import thunks ---
    for (0..nimports) |i| {
        const t: usize = thunks_file + i * peThunkLen;
        const thunk_vaddr: u64 = peImageBase + thunks_rva + @as(u64, i) * @as(u64, peThunkLen);
        const slot_vaddr: u64 = peImageBase + iat_rva[@as(usize, import_dll[i])] + @as(u64, import_slot[i]) * 8;
        std.mem.writeInt(u32, out[t..][0..4], 0xd10083ff, .little); // sub sp, sp, #32
        std.mem.writeInt(u32, out[t + 4 ..][0..4], patchAdrp(0x90000010, thunk_vaddr + 4, slot_vaddr), .little);
        const so: u32 = @intCast(slot_vaddr & 0xfff);
        std.mem.writeInt(u32, out[t + 8 ..][0..4], 0xf9400000 | ((so >> 3) << 10) | (16 << 5) | 16, .little); // ldr x16, [x16, #off]
        std.mem.writeInt(u32, out[t + 12 ..][0..4], 0xd63f0200, .little); // blr x16
        std.mem.writeInt(u32, out[t + 16 ..][0..4], 0x910083ff, .little); // add sp, sp, #32
        std.mem.writeInt(u32, out[t + 20 ..][0..4], 0xd65f03c0, .little); // ret
    }

    // --- .text ---
    @memcpy(out[content_file..][0..text.len], text);
    const rodata_pad = (8 - ((text.len + cstring.len) % 8)) % 8;
    const rodata_len = cstring.len + rodata_pad + const_data.len;
    const bss_base = bssBaseAddr(text.len, cstring.len, const_data.len);
    const rodata_vaddr: u64 = peImageBase + rdata_rva;
    const data_vaddr: u64 = peImageBase + data_rva;
    for (relocations) |rel| {
        if (rel.symbol_index >= symbols.len) return error.SemanticFactsInvalid;
        if (@as(usize, rel.offset) + 4 > text.len) return error.SemanticFactsInvalid;
        const sym = symbols[rel.symbol_index];
        const at: usize = content_file + rel.offset;
        const insn_vaddr: u64 = content_vaddr + rel.offset;
        switch (rel.kind) {
            .branch26 => {
                if (sym.defined) {
                    // PC-relative within .text: the content shifts as one
                    // unit, already correct (same as the ELF writer).
                } else {
                    // Import call: rewrite `bl <sym>` to `bl <thunk>`.
                    var ti: ?usize = null;
                    for (import_names.items, 0..) |n, i| if (std.mem.eql(u8, n, sym.name)) {
                        ti = i;
                        break;
                    };
                    const thunk = ti orelse return error.SemanticFactsInvalid;
                    const thunk_vaddr: u64 = peImageBase + thunks_rva + @as(u64, thunk) * @as(u64, peThunkLen);
                    const tdelta: i64 = @as(i64, @intCast(thunk_vaddr)) - @as(i64, @intCast(insn_vaddr));
                    if (tdelta < -0x8000000 or tdelta >= 0x8000000) return error.BranchOutOfRange;
                    if (@rem(tdelta, 4) != 0) return error.BranchOutOfRange;
                    const imm: u32 = @as(u32, @bitCast(@as(i32, @intCast(@divTrunc(tdelta, 4))))) & 0x03ffffff;
                    const word = std.mem.readInt(u32, out[at..][0..4], .little);
                    std.mem.writeInt(u32, out[at..][0..4], (word & 0xfc000000) | imm, .little);
                }
            },
            .page21 => {
                if (!sym.defined) return error.UnknownSymbol;
                const target = try peSymbolVAddr(sym, text.len, rodata_len, bss_base, bss_size, content_vaddr, rodata_vaddr, data_vaddr);
                const word = std.mem.readInt(u32, out[at..][0..4], .little);
                std.mem.writeInt(u32, out[at..][0..4], patchAdrp(word, insn_vaddr, target), .little);
            },
            .pageoff12 => {
                if (!sym.defined) return error.UnknownSymbol;
                const target = try peSymbolVAddr(sym, text.len, rodata_len, bss_base, bss_size, content_vaddr, rodata_vaddr, data_vaddr);
                const word = std.mem.readInt(u32, out[at..][0..4], .little);
                const page_offset: u32 = @intCast(target & 0xfff);
                // Opcode-aware, same as the ELF writer: `add` takes the byte
                // offset; `ldr` scales by its 8-byte access size; anything
                // else is a producer this writer does not know.
                const patched = if (word & 0xff000000 == 0x91000000)
                    patchAddImm12(word, page_offset)
                else if (word & 0xffc00000 == 0xf9400000) blk: {
                    if (page_offset % 8 != 0) return error.SemanticFactsInvalid;
                    break :blk patchAddImm12(word, page_offset >> 3);
                } else return error.SemanticFactsInvalid;
                std.mem.writeInt(u32, out[at..][0..4], patched, .little);
            },
            .abs64 => return error.SemanticFactsInvalid,
        }
    }

    // --- .rdata: cstring ++ pad ++ const_data ---
    @memcpy(out[rdata_file..][0..cstring.len], cstring);
    // rodata_pad bytes are already zero
    @memcpy(out[rdata_file + cstring.len + rodata_pad ..][0..const_data.len], const_data);

    // --- .data (+ bss tail, zero-filled by the loader via VirtualSize) ---
    @memcpy(out[data_file..][0..global_data.len], global_data);
    for (data_relocations) |rel| {
        if (rel.symbol_index >= symbols.len) return error.SemanticFactsInvalid;
        if (rel.kind != .abs64) return error.SemanticFactsInvalid;
        if (@as(usize, rel.offset) + 8 > global_data.len) return error.SemanticFactsInvalid;
        const sym = symbols[rel.symbol_index];
        if (!sym.defined) return error.UnknownSymbol;
        const target = try peSymbolVAddr(sym, text.len, rodata_len, bss_base, bss_size, content_vaddr, rodata_vaddr, data_vaddr);
        std.mem.writeInt(u64, out[data_file + rel.offset ..][0..8], target, .little);
    }

    return out;
}


fn alignForward(value: usize, alignment: usize) usize {
    return (value + alignment - 1) & ~(alignment - 1);
}

fn expectLineageCallTarget(
    alloc: std.mem.Allocator,
    output: Arm64Output,
    module: dnir.Module,
    lineage: MachineLineage,
) !void {
    var target_function: ?dnir.Function = null;
    for (module.functions) |function| {
        if (function.id != null and std.meta.eql(function.id.?, lineage.target)) {
            target_function = function;
            break;
        }
    }
    const function = target_function orelse return error.TestExpectedEqual;
    const link_name = try linkerSymbolName(alloc, function.name);
    defer alloc.free(link_name);
    var target_offset: ?u32 = null;
    for (output.symbols) |symbol| {
        if (!symbol.defined or symbol.section != 1 or !std.mem.eql(u8, symbol.name, link_name)) continue;
        target_offset = symbol.offset;
        break;
    }

    // ONE CONTROL TRANSFER, TO THE NAMED TARGET — and `bl` is not the only
    // form it takes. §12 TAIL realizes an application in tail position as `b`,
    // which is the SAME transfer to the SAME target over the same imm26 field;
    // only x30 differs, and x30 is the frame question, not the identity one.
    // Scanning for BL alone read a lawful tail realization as no call at all.
    var call_count: usize = 0;
    var offset: u32 = lineage.text_start;
    while (offset + 4 <= lineage.text_end) : (offset += 4) {
        const word = std.mem.readInt(u32, output.text[offset..][0..4], .little);
        const op = word & 0xfc00_0000;
        if (op != 0x9400_0000 and op != 0x1400_0000) continue;
        const shifted: i32 = @bitCast((word & 0x03ff_ffff) << 6);
        const destination = @as(i64, offset) + @as(i64, shifted >> 6) * 4;
        try std.testing.expectEqual(@as(i64, target_offset orelse return error.TestExpectedEqual), destination);
        call_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), call_count);
}

fn stageCompactGpApplication(
    alloc: std.mem.Allocator,
    compact: dnir.Module,
    application: semantic_graph.id,
) !dnir.Module {
    const functions = try alloc.dupe(dnir.Function, compact.functions);
    var found = false;
    for (functions) |*function| {
        var flat_index: u32 = 0;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.op == .br) return error.TestUnexpectedResult;
            }
        }

        const blocks = try alloc.dupe(dnir.Block, function.blocks);
        function.blocks = blocks;
        for (blocks) |*block| {
            for (block.instrs, 0..) |instruction, instruction_index| {
                if (instruction.application == null or
                    !std.meta.eql(instruction.application.?, application))
                {
                    flat_index += 1;
                    continue;
                }
                if (found or instruction.op != .call_direct or
                    instruction.realization_start == null or
                    instruction.realization_start.? != flat_index)
                {
                    return error.TestUnexpectedResult;
                }
                switch (instruction.lhs) {
                    .void, .f64 => return error.TestUnexpectedResult,
                    else => {},
                }

                const staged = try alloc.alloc(dnir.Instr, block.instrs.len + 1);
                @memcpy(staged[0..instruction_index], block.instrs[0..instruction_index]);
                staged[instruction_index] = .{
                    .op = .mov_arg,
                    .result = 0,
                    .lhs = instruction.lhs,
                    .ty = .i64,
                };
                staged[instruction_index + 1] = instruction;
                staged[instruction_index + 1].lhs = .void;
                staged[instruction_index + 1].realization_start = flat_index;
                @memcpy(
                    staged[instruction_index + 2 ..],
                    block.instrs[instruction_index + 1 ..],
                );
                block.instrs = staged;
                found = true;
                flat_index += 2;
            }
        }
    }
    if (!found) return error.TestExpectedEqual;
    var staged = compact;
    staged.functions = functions;
    return staged;
}

/// Graph lift has a PRECONDITION: the module has been canonicalized by
/// `table_apply`, so that every lawful spelling of a world projection is the one
/// node the recognizers look for. `os.args(1)` and `os.env("PATH")` parse as
/// `.call`; the projection recognizers in `dnir_lower` only fire on `.index`.
///
/// This was driver-only (`main.zig`), so tests that build their own
/// parse -> check -> lift pipeline skipped it and asserted against an AST no
/// user ever compiles. Demagix (`a[i]` canonicalizes to `a(i)`) then rewrote
/// two fixtures into the spelling only the driver could resolve, and the tests
/// failed for a reason that had nothing to do with what they were testing.
/// Normalizing here keeps the precondition attached to the stage that needs it.
fn liftCheckedTestGraph(
    module: *ast.Module,
    checked: *const Sema,
    graph: *semantic_graph.SemanticGraph,
) !void {
    table_apply.normalizeModule(checked.alloc, module, &checked.type_map);
    _ = try graph.liftModuleWithCheckedCalls(module, checked, module.file);
}

fn emitCheckedTestAssembly(
    alloc: std.mem.Allocator,
    module: *const ast.Module,
    graph: *semantic_graph.SemanticGraph,
    entry: ?[]const u8,
) !AssemblyWithLineage {
    var diagnostic: Diagnostic = .{};
    if (entry) |name| {
        return emitAssemblyForExecutableWithGraphLineageObserved(
            alloc,
            module,
            name,
            graph,
            &diagnostic,
        );
    }
    return emitAssemblyWithGraphLineageObserved(
        alloc,
        module,
        "native-asm",
        graph,
        &diagnostic,
    );
}

fn emitCheckedTestObject(
    alloc: std.mem.Allocator,
    module: *const ast.Module,
    graph: *semantic_graph.SemanticGraph,
) !ObjectWithLineage {
    var diagnostic: Diagnostic = .{};
    return emitObjectWithGraphLineageObserved(
        alloc,
        module,
        "native-object",
        graph,
        &diagnostic,
    );
}

fn expectCheckedTestSemanticFailure(
    alloc: std.mem.Allocator,
    module: *ast.Module,
    checked: *const Sema,
    expected: []const u8,
    expected_lowering: ?[]const u8,
) !void {
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(module, checked, &graph);
    var diagnostic: Diagnostic = .{};
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        emitAssemblyWithGraphLineageObserved(
            alloc,
            module,
            "native-asm",
            &graph,
            &diagnostic,
        ),
    );
    const primary = expected_lowering orelse expected;
    try std.testing.expectEqualStrings(primary, diagnostic.note().?);
    if (std.mem.eql(u8, expected, "unresolved-application-facts") or
        std.mem.eql(u8, primary, "unresolved-application-facts"))
    {
        try std.testing.expect(diagnostic.application != null);
    }
    if (expected_lowering) |note| {
        try std.testing.expectEqualStrings(note, diagnostic.lowering.note().?);
    } else {
        try std.testing.expect(diagnostic.lowering.note() == null);
    }
}

fn expectCheckedTestPhysicalRefusal(
    alloc: std.mem.Allocator,
    module: *ast.Module,
    checked: *const Sema,
    expected: []const u8,
) !void {
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(module, checked, &graph);
    var diagnostic: Diagnostic = .{};
    try std.testing.expectError(
        error.UnsupportedProgram,
        emitAssemblyWithGraphLineageObserved(
            alloc,
            module,
            "native-asm",
            &graph,
            &diagnostic,
        ),
    );
    if (diagnostic.lowering.note()) |note| {
        try std.testing.expectEqualStrings(note, diagnostic.note().?);
    } else {
        try std.testing.expectEqualStrings(expected, diagnostic.note().?);
    }
}

test "native backend: folded module provenance does not select constant realization" {
    var diagnostic: Diagnostic = .{};
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const plain_instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 14 }, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 0 }, .ty = .i64 },
    };
    const qualified_instructions = [_]dnir.Instr{
        .{
            .op = .@"const",
            .result = 0,
            .lhs = .{ .i64 = 14 },
            .req_alias = "token",
            .field = "kindfun",
            .ty = .i64,
        },
        .{ .op = .ret, .lhs = .{ .temp = 0 }, .ty = .i64 },
    };
    const plain_blocks = [_]dnir.Block{.{ .instrs = &plain_instructions }};
    const qualified_blocks = [_]dnir.Block{.{ .instrs = &qualified_instructions }};
    const plain_functions = [_]dnir.Function{.{
        .name = "main",
        .ret = .i64,
        .blocks = &plain_blocks,
    }};
    const qualified_functions = [_]dnir.Function{.{
        .name = "main",
        .ret = .i64,
        .blocks = &qualified_blocks,
    }};
    const plain = dnir.Module{ .functions = &plain_functions };
    const qualified = dnir.Module{ .functions = &qualified_functions };

    var plain_output = try emitArm64FromDnir(alloc, plain, null, &diagnostic);
    defer plain_output.deinit(alloc);
    var qualified_output = try emitArm64FromDnir(alloc, qualified, null, &diagnostic);
    defer qualified_output.deinit(alloc);
    try std.testing.expect(plain_output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), plain_output.lineage.len);
    try std.testing.expect(qualified_output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), qualified_output.lineage.len);
    try std.testing.expectEqualSlices(u8, plain_output.text, qualified_output.text);
    try std.testing.expectEqualStrings(plain_output.asm_text, qualified_output.asm_text);

    const plain_object = try emitMachOArm64Object(
        alloc,
        plain_output.text,
        plain_output.cstring,
        plain_output.symbols,
        plain_output.relocations,
        plain_output.bss_size,
    );
    defer alloc.free(plain_object);
    const qualified_object = try emitMachOArm64Object(
        alloc,
        qualified_output.text,
        qualified_output.cstring,
        qualified_output.symbols,
        qualified_output.relocations,
        qualified_output.bss_size,
    );
    defer alloc.free(qualified_object);
    try std.testing.expectEqualSlices(u8, plain_object, qualified_object);
}

test "native backend: compact checked call preserves staged machine realization" {
    var diagnostic: Diagnostic = .{};
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\observe: i64 = (value: i64)
        \\    value
        \\main: i64 = (seed: i64)
        \\    observe(40 + 2)
    ;
    var lexer = Lexer.init(source, "gp-inline.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var ast_module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&ast_module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&ast_module, &checked, "gp-inline.id");
    const applications = try checkedApplications(&graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 1), applications.len);

    const compact = try dnir_lower.lowerModuleWithGraph(alloc, &ast_module, &graph);
    try validateDnirApplications(alloc, compact, &graph, &diagnostic);
    var compact_call_count: usize = 0;
    var compact_mov_count: usize = 0;
    for (compact.functions) |function| {
        var instruction_index: u32 = 0;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.op == .mov_arg) compact_mov_count += 1;
                if (instruction.application != null) {
                    compact_call_count += 1;
                    try std.testing.expectEqual(dnir.Op.call_direct, instruction.op);
                    try std.testing.expectEqual(instruction_index, instruction.realization_start.?);
                    switch (instruction.lhs) {
                        .void, .f64 => return error.TestUnexpectedResult,
                        else => {},
                    }
                }
                instruction_index += 1;
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 1), compact_call_count);
    try std.testing.expectEqual(@as(usize, 0), compact_mov_count);

    const staged = try stageCompactGpApplication(alloc, compact, applications[0].application);
    try validateDnirApplications(alloc, staged, &graph, &diagnostic);
    var compact_output = try emitArm64FromDnir(alloc, compact, null, &diagnostic);
    defer compact_output.deinit(alloc);
    var staged_output = try emitArm64FromDnir(alloc, staged, null, &diagnostic);
    defer staged_output.deinit(alloc);
    try validateMachineLineage(alloc, compact_output, &graph, &diagnostic);
    try validateMachineLineage(alloc, staged_output, &graph, &diagnostic);
    try std.testing.expectEqualSlices(u8, staged_output.text, compact_output.text);
    try std.testing.expectEqualStrings(staged_output.asm_text, compact_output.asm_text);
    try std.testing.expectEqual(@as(usize, 1), compact_output.lineage.len);
    try std.testing.expectEqual(
        compact_output.lineage[0].instruction_start + 1,
        compact_output.lineage[0].instruction_end,
    );
    try std.testing.expectEqual(
        staged_output.lineage[0].instruction_start + 2,
        staged_output.lineage[0].instruction_end,
    );
    try std.testing.expectEqual(staged_output.lineage[0].text_start, compact_output.lineage[0].text_start);
    try std.testing.expectEqual(staged_output.lineage[0].text_end, compact_output.lineage[0].text_end);
    try expectLineageCallTarget(alloc, compact_output, compact, compact_output.lineage[0]);

    const compact_object = try emitMachOArm64Object(
        alloc,
        compact_output.text,
        compact_output.cstring,
        compact_output.symbols,
        compact_output.relocations,
        compact_output.bss_size,
    );
    defer alloc.free(compact_object);
    const staged_object = try emitMachOArm64Object(
        alloc,
        staged_output.text,
        staged_output.cstring,
        staged_output.symbols,
        staged_output.relocations,
        staged_output.bss_size,
    );
    defer alloc.free(staged_object);
    try std.testing.expectEqualSlices(u8, staged_object, compact_object);
}

test "native backend: nested compact checked calls retain direct region use and distinct lineage" {
    var diagnostic: Diagnostic = .{};
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\inner: i64 = (value: i64)
        \\    value
        \\outer: i64 = (value: i64)
        \\    value
        \\main: i64 = (seed: i64)
        \\    outer(inner(42))
    ;
    var lexer = Lexer.init(source, "nested-gp-inline.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var ast_module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&ast_module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&ast_module, &checked, "nested-gp-inline.id");
    const applications = try checkedApplications(&graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 2), applications.len);
    try std.testing.expect(!std.meta.eql(applications[0].application, applications[1].application));
    try std.testing.expect(!std.meta.eql(
        try applicationResult(&graph, applications[0], &diagnostic),
        try applicationResult(&graph, applications[1], &diagnostic),
    ));

    const module = try dnir_lower.lowerModuleWithGraph(alloc, &ast_module, &graph);
    try validateDnirApplications(alloc, module, &graph, &diagnostic);
    var call_applications: [2]semantic_graph.id = undefined;
    var call_count: usize = 0;
    for (module.functions) |function| {
        var instruction_index: u32 = 0;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                try std.testing.expect(instruction.op != .mov_arg);
                if (instruction.application != null) {
                    if (call_count >= call_applications.len) return error.TestUnexpectedResult;
                    call_applications[call_count] = instruction.application.?;
                    call_count += 1;
                    try std.testing.expectEqual(instruction_index, instruction.realization_start.?);
                    switch (instruction.lhs) {
                        .void, .f64 => return error.TestUnexpectedResult,
                        else => {},
                    }
                }
                instruction_index += 1;
            }
        }
    }
    try std.testing.expectEqual(call_applications.len, call_count);

    const regions = try region_graph.buildModuleRegions(alloc, module);
    defer region_graph.freeModuleRegions(alloc, regions);
    try region_graph.validateModuleRegions(alloc, regions, &graph, module);
    var inner_coordinate: ?u32 = null;
    var outer_coordinate: ?u32 = null;
    var direct_use = false;
    for (module.functions, regions.regions) |function, region| {
        var coordinate: u32 = 1;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.application) |application| {
                    if (std.meta.eql(application, call_applications[0])) inner_coordinate = coordinate;
                    if (std.meta.eql(application, call_applications[1])) outer_coordinate = coordinate;
                }
                coordinate += 1;
            }
        }
        if (inner_coordinate != null and outer_coordinate != null) {
            for (region.dependencies) |dependency| {
                if (dependency.producer == inner_coordinate.? and
                    dependency.consumer == outer_coordinate.?)
                {
                    direct_use = true;
                }
            }
        }
    }
    try std.testing.expect(direct_use);

    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try validateMachineLineage(alloc, output, &graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 2), output.lineage.len);
    var inner_lineage: ?MachineLineage = null;
    var outer_lineage: ?MachineLineage = null;
    for (output.lineage) |lineage| {
        try std.testing.expectEqual(lineage.instruction_start + 1, lineage.instruction_end);
        try expectLineageCallTarget(alloc, output, module, lineage);
        if (std.meta.eql(lineage.application, call_applications[0])) inner_lineage = lineage;
        if (std.meta.eql(lineage.application, call_applications[1])) outer_lineage = lineage;
    }
    const inner = inner_lineage orelse return error.TestExpectedEqual;
    const outer = outer_lineage orelse return error.TestExpectedEqual;
    try std.testing.expect(inner.instruction_end <= outer.instruction_start);
    try std.testing.expect(inner.text_end <= outer.text_start);
}

test "native backend: a call in tail position is a jump, not a frame (§12 TAIL)" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // `_tail` is the textbook fixture: one arm returns, the other calls itself
    // in tail position. `_grow` is the CONTROL — the same self-call with its
    // result used as an operand, which is not in tail position and must keep
    // its frame.
    const source =
        \\_tail: i64 = (n: i64, acc: i64)
        \\    if n <= 0
        \\        return acc
        \\    return _tail(n - 1, acc + 1)
        \\_grow: i64 = (n: i64)
        \\    if n <= 0
        \\        return 0
        \\    return n + _grow(n - 1)
    ;
    var lexer = Lexer.init(source, "tailform.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&module, &checked, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &module, &graph, null);
    defer assembly.deinit(alloc);
    const text = assembly.assembly;

    const tail_symbol = "_idol_tailform___tail";
    const grow_symbol = "_idol_tailform___grow";

    // THE FORM, IN THREE PARTS.
    //
    // (1) A JUMP TO THE TARGET, and (2) NO CALL TO IT. Both halves are the
    // assertion: `b` present while `bl` also survived somewhere would mean the
    // frame is still being pushed on some path.
    const jump = "\tb " ++ tail_symbol ++ "\n";
    const jump_at = std.mem.indexOf(u8, text, jump) orelse return error.TestExpectedEqual;
    try std.testing.expect(std.mem.indexOf(u8, text, "\tbl " ++ tail_symbol ++ "\n") == null);
    // The jump REPLACES the return; nothing may follow it on that path.
    try std.testing.expect(std.mem.indexOf(u8, text, jump) == std.mem.lastIndexOf(u8, text, jump));

    // (3) THE FRAME IS GIVEN BACK BEFORE THE BRANCH, not after it and not by
    // the callee. The instruction immediately preceding the jump must be the
    // `add sp, sp, #N` that undoes this function's own `sub sp, sp, #N` — the
    // same tear-down its ordinary `ret` performs. A jump emitted with the
    // frame still standing is the defect this pins: it would run, answer
    // correctly at depth 100, and grow the stack forever.
    const before_jump = text[0..jump_at];
    const restore_at = std.mem.lastIndexOf(u8, before_jump, "\tadd sp, sp, #") orelse
        return error.TestExpectedEqual;
    const after_restore = before_jump[restore_at..];
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, after_restore, "\n"));
    // …and it gives back exactly what the prologue took.
    const claim_at = std.mem.indexOf(u8, text, "\tsub sp, sp, #") orelse return error.TestExpectedEqual;
    const claimed = text[claim_at + "\tsub sp, sp, #".len ..];
    const released = after_restore["\tadd sp, sp, #".len..];
    const claimed_end = std.mem.indexOfScalar(u8, claimed, '\n') orelse return error.TestExpectedEqual;
    const released_end = std.mem.indexOfScalar(u8, released, '\n') orelse return error.TestExpectedEqual;
    try std.testing.expectEqualStrings(claimed[0..claimed_end], released[0..released_end]);

    // THE ARGUMENTS ARE ALREADY STAGED when the frame goes back. Both of them
    // are written into the argument registers before the tear-down, which is
    // the whole reason the tear-down cannot destroy them.
    const tail_start = std.mem.indexOf(u8, text, tail_symbol ++ ":\n") orelse
        return error.TestExpectedEqual;
    const staging = text[tail_start..restore_at];
    try std.testing.expect(std.mem.lastIndexOf(u8, staging, "\tmov x0, x") != null);
    try std.testing.expect(std.mem.lastIndexOf(u8, staging, "\tmov x1, x") != null);

    // THE CONTROL. `_grow`'s self-call is an operand of `+`, so it is NOT in
    // tail position: it keeps its `bl` and never becomes a jump. Without this
    // half the test above passes just as well for a compiler that turned every
    // call into a branch.
    try std.testing.expect(std.mem.indexOf(u8, text, "\tbl " ++ grow_symbol ++ "\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "\tb " ++ grow_symbol ++ "\n") == null);
}

test "native backend: a tail jump relocates as B and not as BL" {
    var diagnostic: Diagnostic = .{};
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE ASSEMBLY TEXT IS NOT THE ARTIFACT. `patchCalls` resolves every call
    // patch by writing an opcode over the branch site, and it used to write a
    // literal BL there — which would have turned this jump back into a call in
    // the BYTES while the `.s` file went on saying `b`. Only a byte-level
    // oracle can tell those two apart, so this is that oracle.
    const source =
        \\_tail: i64 = (n: i64, acc: i64)
        \\    if n <= 0
        \\        return acc
        \\    return _tail(n - 1, acc + 1)
        \\main: i64 = (seed: i64)
        \\    _tail(seed, 0)
    ;
    var lexer = Lexer.init(source, "tailbytes.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "tailbytes.id");

    var output = try emitArm64ModuleWithGraph(alloc, &module, null, &graph, &diagnostic);
    defer output.deinit(alloc);

    var target_offset: ?u32 = null;
    for (output.symbols) |symbol| {
        if (!symbol.defined or symbol.section != 1) continue;
        if (!std.mem.eql(u8, symbol.name, "idol_tailbytes___tail")) continue;
        target_offset = symbol.offset;
    }
    const target = target_offset orelse return error.TestExpectedEqual;

    var jumps: usize = 0;
    var calls: usize = 0;
    var offset: u32 = 0;
    while (offset + 4 <= output.text.len) : (offset += 4) {
        const word = std.mem.readInt(u32, output.text[offset..][0..4], .little);
        const op = word & 0xfc00_0000;
        if (op != 0x1400_0000 and op != 0x9400_0000) continue;
        const shifted: i32 = @bitCast((word & 0x03ff_ffff) << 6);
        const destination = @as(i64, offset) + @as(i64, shifted >> 6) * 4;
        if (destination != @as(i64, target)) continue;
        if (op == 0x1400_0000) jumps += 1 else calls += 1;
    }
    // `_tail`'s own recursion is a jump; `main`'s application of it is NOT in
    // tail position (its result is bound and returned through main's own
    // frame convention) or is, and either way exactly one of each reaches the
    // target here: the self-recursion never as BL, and never zero jumps.
    try std.testing.expect(jumps >= 1);
    try std.testing.expectEqual(@as(usize, 0), calls);
}

test "native backend: checked subject fact reaches object bytes" {
    var diagnostic: Diagnostic = .{};
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\observe: i64 = (subject: i64, left: i64, right: i64)
        \\    subject + left + right
        \\main: i64 = (seed: i64)
        \\    40:observe(1, 1)
    ;
    var lexer = Lexer.init(source, "machine-lineage.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "machine-lineage.id");
    const applications = try checkedApplications(&graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 1), applications.len);
    try std.testing.expect(graph.applicationSubject(applications[0].application) != null);

    const projected = try dnir_lower.lowerModuleWithGraph(alloc, &module, &graph);
    var instruction_index: u32 = 0;
    var spans_abi_staging = false;
    var dnir_caller: ?semantic_graph.id = null;
    var dnir_subject: ?semantic_graph.id = null;
    for (projected.functions) |function| {
        instruction_index = 0;
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.application != null) {
                    spans_abi_staging = instruction.realization_start.? < instruction_index;
                    dnir_caller = function.id;
                    dnir_subject = instruction.subject;
                }
                instruction_index += 1;
            }
        }
    }
    try std.testing.expect(spans_abi_staging);
    try std.testing.expectEqual(graph.applicationCaller(applications[0].application).?, dnir_caller.?);
    try std.testing.expect(std.meta.eql(graph.applicationSubject(applications[0].application).?, dnir_subject.?));

    var output = try emitArm64ModuleWithGraph(alloc, &module, null, &graph, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), output.lineage.len);
    const text_lineage = output.lineage[0];
    try std.testing.expectEqual(graph.applicationRelation(applications[0].application).?, text_lineage.relation);
    try std.testing.expectEqual(graph.applicationTarget(applications[0].application).?, text_lineage.target);
    try std.testing.expectEqual(applications[0].application, text_lineage.application);
    try std.testing.expectEqual(try applicationResult(&graph, applications[0], &diagnostic), text_lineage.value);
    try std.testing.expect(std.meta.eql(graph.applicationSubject(applications[0].application).?, text_lineage.subject.?));
    try std.testing.expect(graph.applicationDescriptor(applications[0].application).?.eql(text_lineage.descriptor));
    try std.testing.expectEqual(graph.applicationCaller(applications[0].application).?, text_lineage.caller);
    try std.testing.expect(text_lineage.instruction_start + 1 < text_lineage.instruction_end);
    try expectLineageCallTarget(alloc, output, projected, text_lineage);
    const main_start = std.mem.indexOf(u8, output.asm_text, "_main:\n") orelse
        return error.TestExpectedEqual;
    // `machine-lineage.id` is home `machine-lineage`; the hyphen folds.
    // The application is in tail position, so §12 TAIL realizes it as `b`; the
    // three staged argument registers are the point here and they are unmoved.
    const call_offset = std.mem.indexOf(u8, output.asm_text[main_start..], "b _idol_machine_lineage__observe") orelse
        return error.TestExpectedEqual;
    const call_staging = output.asm_text[main_start .. main_start + call_offset];
    try std.testing.expect(std.mem.indexOf(u8, call_staging, "mov x0") != null);
    try std.testing.expect(std.mem.indexOf(u8, call_staging, "mov x1") != null);
    try std.testing.expect(std.mem.indexOf(u8, call_staging, "mov x2") != null);

    output.lineage[0].caller +%= 1;
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateMachineLineage(alloc, output, &graph, &diagnostic),
    );
    output.lineage[0].caller -%= 1;
    output.lineage[0].subject.? +%= 1;
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateMachineLineage(alloc, output, &graph, &diagnostic),
    );
    output.lineage[0].subject.? -%= 1;
    output.lineage[0].descriptor = .i32;
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateMachineLineage(alloc, output, &graph, &diagnostic),
    );
    output.lineage[0].descriptor = graph.applicationDescriptor(applications[0].application).?;
    output.lineage[0].target +%= 1;
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateMachineLineage(alloc, output, &graph, &diagnostic),
    );
    output.lineage[0].target -%= 1;

    var artifact = try emitObjectWithGraphLineage(alloc, &module, "native-object", &graph);
    defer artifact.deinit(alloc);
    try std.testing.expect(artifact.graph == &graph);
    try std.testing.expectEqual(@as(usize, 1), artifact.lineage.len);
    const object_lineage = artifact.lineage[0];
    try std.testing.expectEqual(text_lineage.relation, object_lineage.relation);
    try std.testing.expectEqual(text_lineage.target, object_lineage.target);
    try std.testing.expectEqual(text_lineage.application, object_lineage.application);
    try std.testing.expectEqual(text_lineage.value, object_lineage.value);
    try std.testing.expect(std.meta.eql(text_lineage.subject.?, object_lineage.subject.?));
    try std.testing.expect(text_lineage.descriptor.eql(object_lineage.descriptor));
    try std.testing.expectEqual(text_lineage.caller, object_lineage.caller);
    try std.testing.expectEqualSlices(
        u8,
        output.text[text_lineage.text_start..text_lineage.text_end],
        artifact.bytes[object_lineage.object_start..object_lineage.object_end],
    );

    var assembly = try emitAssemblyWithGraphLineage(alloc, &module, "native-asm", &graph);
    defer assembly.deinit(alloc);
    try std.testing.expect(assembly.graph == &graph);
    try std.testing.expectEqual(@as(usize, 1), assembly.lineage.len);
    try std.testing.expectEqual(object_lineage.application, assembly.lineage[0].application);
    try std.testing.expect(@as(usize, assembly.lineage[0].text_end) <= assembly.machine.len);
    try std.testing.expectEqualSlices(
        u8,
        output.text[text_lineage.text_start..text_lineage.text_end],
        assembly.machine[assembly.lineage[0].text_start..assembly.lineage[0].text_end],
    );
    try std.testing.expect(std.mem.indexOf(u8, assembly.assembly, "bl _idol_machine_lineage__observe") != null);

    const application = applications[0].application;
    const row = graph.application_rows.items[application];
    const saved = graph.application_facts.items[row];
    const alternate = graph.applicationCaller(application) orelse return error.TestExpectedEqual;
    try std.testing.expect(alternate != text_lineage.relation);
    graph.application_facts.items[row].applied = .{ .one = alternate };
    graph.application_facts.items[row].target = .{ .one = alternate };
    defer graph.application_facts.items[row] = saved;

    var split_output = try emitArm64ModuleWithGraph(alloc, &module, null, &graph, &diagnostic);
    defer split_output.deinit(alloc);
    try validateMachineLineage(alloc, split_output, &graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 1), split_output.lineage.len);
    try std.testing.expectEqual(text_lineage.relation, split_output.lineage[0].relation);
    try std.testing.expectEqual(alternate, split_output.lineage[0].target);

    var split_artifact = try emitObjectWithGraphLineage(alloc, &module, "native-object", &graph);
    defer split_artifact.deinit(alloc);
    try std.testing.expectEqual(text_lineage.relation, split_artifact.lineage[0].relation);
    try std.testing.expectEqual(alternate, split_artifact.lineage[0].target);
}

test "native backend: removing checked facts refuses before machine emission" {
    var diagnostic: Diagnostic = .{};
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\observe: i64 = (subject: i64)
        \\    subject
        \\main: i64 = (seed: i64)
        \\    42:observe()
    ;
    var lexer = Lexer.init(source, "missing-lineage.id");
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var ast_module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&ast_module);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&ast_module, &checked, "missing-lineage.id");
    const applications = try checkedApplications(&graph, &diagnostic);
    try std.testing.expectEqual(@as(usize, 1), applications.len);

    const module = try dnir_lower.lowerModuleWithGraph(alloc, &ast_module, &graph);
    var removed = false;
    for (module.functions) |function| {
        for (function.blocks) |block| {
            const instructions: []dnir.Instr = @constCast(block.instrs);
            for (instructions) |*instruction| {
                if (instruction.application == null) continue;
                instruction.relation = null;
                instruction.application = null;
                instruction.value = null;
                instruction.subject = null;
                instruction.realization_start = null;
                removed = true;
            }
        }
    }
    try std.testing.expect(removed);
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateDnirApplications(alloc, module, &graph, &diagnostic),
    );
}

