    try std.testing.expect(diagnostic.application != null);
    try std.testing.expect(diagnostic.lowering.note() == null);
}

test "native backend physical oracle retains qualified link symbol and two-register call ABI" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    const parameters = [_]dnir.Param{
        .{ .name = "a", .ty = .i64 },
        .{ .name = "b", .ty = .i64 },
    };
    const add_instructions = [_]dnir.Instr{
        .{
            .op = .binop,
            .result = 2,
            .lhs = .{ .temp = 0 },
            .rhs = .{ .temp = 1 },
            .binop = .add,
            .ty = .i64,
        },
        .{ .op = .ret, .lhs = .{ .temp = 2 }, .ty = .i64 },
    };
    const main_instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 10 }, .ty = .i64 },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 20 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = 1 }, .ty = .i64 },
        .{ .op = .call_direct, .result = 2, .callee = "math.add", .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 2 }, .ty = .i64 },
    };
    const add_blocks = [_]dnir.Block{.{ .instrs = &add_instructions }};
    const main_blocks = [_]dnir.Block{.{ .instrs = &main_instructions }};
    const functions = [_]dnir.Function{
        .{ .name = "math.add", .ret = .i64, .params = &parameters, .blocks = &add_blocks },
        .{ .name = "main", .ret = .i64, .blocks = &main_blocks },
    };
    const module = dnir.Module{ .functions = &functions };

    // This schedule is an authority-false physical oracle: it proves only the
    // linker spelling and ABI moves after meaning has already been selected.
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "_math_add") != null);
    const main_start = std.mem.indexOf(u8, output.asm_text, "_main:\n") orelse
        return error.TestExpectedEqual;
    // `main` returns `math.add(a, b)` directly — a tail position, so the
    // transfer is `b` and the two argument moves still have to be right.
    const call_offset = std.mem.indexOf(u8, output.asm_text[main_start..], "b _math_add") orelse
        return error.TestExpectedEqual;
    const staging = output.asm_text[main_start .. main_start + call_offset];
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x0") != null);
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x1") != null);

    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expect(std.mem.indexOf(u8, object, "_math_add") != null);
}

test "native backend unroll copy shape has four machine operations and zero semantic lineage" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    const once_instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 20 }, .ty = .i64 },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 22 }, .ty = .i64 },
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 2 }, .ty = .i64 },
    };
    const four_instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 20 }, .ty = .i64 },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 22 }, .ty = .i64 },
        // The research unroller copies these exact physical ids verbatim.
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 2 }, .ty = .i64 },
    };
    const once_blocks = [_]dnir.Block{.{ .instrs = &once_instructions }};
    const four_blocks = [_]dnir.Block{.{ .instrs = &four_instructions }};
    const once_functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &once_blocks }};
    const four_functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &four_blocks }};
    const once_module = dnir.Module{ .functions = &once_functions };
    const four_module = dnir.Module{ .functions = &four_functions };

    var diagnostic: Diagnostic = .{};
    var once = try emitArm64FromDnir(alloc, once_module, null, &diagnostic);
    defer once.deinit(alloc);
    var four = try emitArm64FromDnir(alloc, four_module, null, &diagnostic);
    defer four.deinit(alloc);

    // Three extra DNIR copies become three distinct four-byte AArch64
    // instructions. They still produce ZERO machine-lineage rows because the
    // graph has supplied no original or derived application/value occurrence.
    try std.testing.expectEqual(once.text.len + 3 * @sizeOf(u32), four.text.len);
    try std.testing.expectEqual(@as(usize, 0), once.lineage.len);
    try std.testing.expectEqual(@as(usize, 0), four.lineage.len);

    // This is a damage control, not an alternate lineage registry. Delete it
    // when the graph-owned unroll transform makes four distinct derived
    // occurrences queryable through the existing MachineLineage projection.
}

// Regression: a two-argument call whose BOTH operands are prior call results
// must stage the two arguments from DISTINCT source registers. The mov_arg
// ownership recorder once read `result` (a PHYSICAL ABI slot 0/1 for mov_arg) as
// a value id; slot 1 aliased temp id 1, so staging the second argument rebound
// and then freed the first result's live register, and both `mov x0`/`mov x1`
// read the same clobbered register — `add2(id(a), id(b))` collapsed to
// `add2(v, v)`. Two callees keep the results out of x0 so the collision, if it
// returns, shows up as one shared source register here.
test "native backend stages two call-result arguments from distinct registers" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    const id_params = [_]dnir.Param{.{ .name = "x", .ty = .i64 }};
    const g_params = [_]dnir.Param{
        .{ .name = "a", .ty = .i64 },
        .{ .name = "b", .ty = .i64 },
    };
    const id_instructions = [_]dnir.Instr{
        .{ .op = .ret, .lhs = .{ .temp = 0 }, .ty = .i64 },
    };
    const g_instructions = [_]dnir.Instr{
        .{ .op = .binop, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .binop = .add, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 2 }, .ty = .i64 },
    };
    const main_instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 5 }, .ty = .i64 },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 7 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .call_direct, .result = 2, .callee = "id", .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 1 }, .ty = .i64 },
        .{ .op = .call_direct, .result = 3, .callee = "id", .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 2 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = 3 }, .ty = .i64 },
        .{ .op = .call_direct, .result = 4, .callee = "g", .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 4 }, .ty = .i64 },
    };
    const id_blocks = [_]dnir.Block{.{ .instrs = &id_instructions }};
    const g_blocks = [_]dnir.Block{.{ .instrs = &g_instructions }};
    const main_blocks = [_]dnir.Block{.{ .instrs = &main_instructions }};
    const functions = [_]dnir.Function{
        .{ .name = "id", .ret = .i64, .params = &id_params, .blocks = &id_blocks },
        .{ .name = "g", .ret = .i64, .params = &g_params, .blocks = &g_blocks },
        .{ .name = "main", .ret = .i64, .blocks = &main_blocks },
    };
    const module = dnir.Module{ .functions = &functions };

    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);

    const main_start = std.mem.indexOf(u8, output.asm_text, "_main:\n") orelse
        return error.TestExpectedEqual;
    const tail = output.asm_text[main_start..];
    const call_g = std.mem.indexOf(u8, tail, "b _g") orelse return error.TestExpectedEqual;
    const staging = tail[0..call_g];
    // The final argument staged into x1 must read a register that is not the
    // same one x0's argument was moved from. Find the last `mov x0, xN` and
    // `mov x1, xM` in the staging window and require N != M.
    const x0_at = std.mem.lastIndexOf(u8, staging, "mov x0, x") orelse return error.TestExpectedEqual;
    const x1_at = std.mem.lastIndexOf(u8, staging, "mov x1, x") orelse return error.TestExpectedEqual;
    const x0_src = staging[x0_at + "mov x0, x".len ..];
    const x1_src = staging[x1_at + "mov x1, x".len ..];
    const x0_end = std.mem.indexOfAny(u8, x0_src, "\n ,") orelse x0_src.len;
    const x1_end = std.mem.indexOfAny(u8, x1_src, "\n ,") orelse x1_src.len;
    try std.testing.expect(!std.mem.eql(u8, x0_src[0..x0_end], x1_src[0..x1_end]));
}

test "native backend refuses source conversion absent application facts and retains variadic ABI oracle" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\main(): i64
        \\    s = to(str)(42)
        \\    return s:len()
        \\end
    , "to_str_vararg.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    // SLOT-ROLE-ONE (8534db8d) made the curried conversion RESOLVE: the first
    // operand occupies the subject slot, the application facts publish, and
    // `to(str)(42)` emits instead of refusing. This test had pinned the OLD
    // refusal ("unresolved-application-facts"); the reland's idol-native
    // suite (80/80) and the differential battery (0 answer diffs) are the
    // authority for the capability change. Pinned now: resolution succeeds
    // and assembly emits with graph lineage observed.
    {
        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        try liftCheckedTestGraph(&mod, &sem, &graph);
        var resolved: Diagnostic = .{};
        var emitted = try emitAssemblyWithGraphLineageObserved(
            alloc,
            &mod,
            "native-asm",
            &graph,
            &resolved,
        );
        defer emitted.deinit(alloc);
        try std.testing.expect(emitted.assembly.len > 0);
    }

    const instructions = [_]dnir.Instr{
        .{ .op = .alloc_slots, .result = 0, .lhs = .{ .i64 = 3 } },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 24 }, .ty = .i64 },
        .{ .op = .@"const", .result = 2, .lhs = .{ .str = "%lld" }, .ty = .str },
        .{ .op = .@"const", .result = 3, .lhs = .{ .i64 = 42 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = 1 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 2, .lhs = .{ .temp = 2 }, .ty = .str },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 3 }, .field = "vararg", .ty = .i64 },
        .{ .op = .call_extern, .callee = "snprintf", .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    const listing = output.asm_text;

    const main_pos = std.mem.indexOf(u8, listing, "_main:") orelse return error.TestExpectedEqual;
    const bl_off = std.mem.indexOf(u8, listing[main_pos..], "bl _snprintf") orelse return error.TestExpectedEqual;
    const staging = listing[main_pos .. main_pos + bl_off];

    // The three NAMED parameters travel in registers, as AAPCS64 says.
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x0,") != null);
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x1,") != null);
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x2,") != null);

    // The tail argument does NOT. Apple's ARM64 ABI reads it from memory at
    // sp, so a fourth register argument is silently ignored: `snprintf(buf,
    // 24, "%lld", n)` staged into x3 assembles correctly and prints a POINTER.
    try std.testing.expect(std.mem.indexOf(u8, staging, "mov x3,") == null);

    // Immediately before the branch: reserve the memory-argument area and
    // write the tail into its first slot.
    const tail = staging[staging.len - 40 ..];
    try std.testing.expect(std.mem.indexOf(u8, tail, "sub sp, sp, #16") != null);
    try std.testing.expect(std.mem.indexOf(u8, tail, ", [sp, #0]") != null);
}

/// The register number in the first `prefix` occurrence at or after `from`, or
/// null. `prefix` ends immediately before the digits, e.g. `"mov x"`.
fn asmRegAfter(text: []const u8, from: usize, prefix: []const u8) ?struct { reg: u8, at: usize } {
    const rel = std.mem.indexOf(u8, text[from..], prefix) orelse return null;
    const at = from + rel;
    const digits = text[at + prefix.len ..];
    var n: usize = 0;
    while (n < digits.len and std.ascii.isDigit(digits[n])) n += 1;
    if (n == 0) return null;
    const reg = std.fmt.parseInt(u8, digits[0..n], 10) catch return null;
    return .{ .reg = reg, .at = at };
}

// A VARIADIC-TAIL `mov_arg` DOES NOT READ ITS OPERAND — it records it, and the
// register is not read until `materializePendingVarargs` runs INSIDE the call.
// `computeValueLastUse` ended the operand's range at the staging instruction, so
// `sweepGpLive` returned the register one instruction early and the call's own
// format string was allocated straight into it.
//
// This is the DNIR of `stdout:write("A=" .. idr(idr("V")) .. "\n")`, the shape
// that printed `A=A=%s\n\n\n\n` — THE FORMAT STRING PASSED AS ITS OWN ARGUMENT.
// One `..` hole that is a NESTED call is the whole trigger: the inner call puts
// x0 in the outer call's save set, so the outer result is homed above x8 instead
// of staying in x0, and that home is exactly what `allocReg` hands out next.
//
// The assertion is on the REGISTER IDENTITY, not on the text around it: the
// value written to the memory-argument area must be the register the outer call
// left its result in, and the format string must have gone somewhere else.
test "native backend keeps a staged vararg live through the call that reads it" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const idr_params = [_]dnir.Param{.{ .name = "x", .ty = .str }};
    const idr_instructions = [_]dnir.Instr{
        .{ .op = .ret, .lhs = .{ .temp = 0 }, .ty = .str },
    };
    const main_instructions = [_]dnir.Instr{
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .str = "V" }, .ty = .str },
        .{ .op = .call_direct, .result = 1, .callee = "idr", .ty = .str },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 1 }, .ty = .str },
        .{ .op = .call_direct, .result = 2, .callee = "idr", .ty = .str },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 2 }, .field = "vararg", .ty = .str },
        .{ .op = .call_extern, .callee = "printf", .lhs = .{ .str = "A=%s\n" } },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const idr_blocks = [_]dnir.Block{.{ .instrs = &idr_instructions }};
    const main_blocks = [_]dnir.Block{.{ .instrs = &main_instructions }};
    const functions = [_]dnir.Function{
        .{ .name = "idr", .ret = .str, .params = &idr_params, .blocks = &idr_blocks },
        .{ .name = "main", .ret = .i64, .blocks = &main_blocks },
    };
    const module = dnir.Module{ .functions = &functions };

    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    const listing = output.asm_text;

    const main_at = std.mem.indexOf(u8, listing, "_main:") orelse return error.TestExpectedEqual;
    const call_at = main_at + (std.mem.indexOf(u8, listing[main_at..], "bl _printf") orelse
        return error.TestExpectedEqual);
    const window = listing[main_at..call_at];

    // The OUTER `bl _idr` — the second one — and the register its result was
    // moved into. `mov x{d}, x0` is emitted only because x0 is in the save set,
    // which is the pressure this shape exists to create.
    const first_idr = std.mem.indexOf(u8, window, "bl _idr") orelse return error.TestExpectedEqual;
    const outer_idr = first_idr + 1 +
        (std.mem.indexOf(u8, window[first_idr + 1 ..], "bl _idr") orelse return error.TestExpectedEqual);
    const home = asmRegAfter(window, outer_idr, "mov x") orelse return error.TestExpectedEqual;
    try std.testing.expect(home.reg >= 9);

    // The format string is materialized somewhere ELSE. Reading it into `home`
    // is the defect, and it is invisible in the bytes until the program runs.
    const fmt_reg = asmRegAfter(window, home.at, "adrp x") orelse return error.TestExpectedEqual;
    try std.testing.expect(fmt_reg.reg != home.reg);

    // …and what lands in the memory-argument area is the CALL RESULT.
    var buf: [32]u8 = undefined;
    const store = try std.fmt.bufPrint(&buf, "str x{d}, [sp, #0]", .{home.reg});
    try std.testing.expect(std.mem.indexOf(u8, window[fmt_reg.at..], store) != null);
}

// `stdout:write` is `print` MINUS THE LINE ENDING. They shared one lowering, and
// the shared one appended: `.str` reached `print_value`, `print_value` called
// `puts`, and `puts` writes a newline the program did not. `print` keeps `puts`;
// write takes `printf("%s", v)`, which writes exactly what it was given.
test "native backend write egress does not append a line ending" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const write_instructions = [_]dnir.Instr{
        .{ .op = .print_value, .lhs = .{ .str = "XY" }, .ty = .str, .field = "nonl" },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const print_instructions = [_]dnir.Instr{
        .{ .op = .print_value, .lhs = .{ .str = "XY" }, .ty = .str },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    inline for (.{
        .{ &write_instructions, false },
        .{ &print_instructions, true },
    }) |case| {
        const blocks = [_]dnir.Block{.{ .instrs = case[0] }};
        const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
        const module = dnir.Module{ .functions = &functions };
        var diagnostic: Diagnostic = .{};
        var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
        defer output.deinit(alloc);
        const appends = case[1];
        // Both directions on both spellings: a write that reaches `puts` has
        // grown a newline, and a `print` that stops reaching it has lost one.
        try std.testing.expectEqual(appends, std.mem.indexOf(u8, output.asm_text, "bl _puts") != null);
        try std.testing.expectEqual(!appends, std.mem.indexOf(u8, output.asm_text, "bl _printf") != null);
        // The line ending is not smuggled in through the format either.
        if (!appends) {
            try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "\"%s\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "\"%s\\n\"") == null);
        }
    }
}

// A NULL string still writes nothing rather than libc's `(null)`, and the guard
// has to read the register the STRING is in — never the format, which is never
// null and would pass every null straight through to `%s`.
//
// This used to be spelled as two literal register names (`cmp x2, #0` for the
// write path, `cmp x0, #0` for `puts`), which pinned the ABI HOME rather than
// the law. The homes are no longer written until after `emitSaveCallerRegs`
// (see `print_value`: staging them earlier made the save preserve printf's own
// arguments and the restore write them back over the caller's live values), so
// the guard now names whatever register EVALUATION left the string in. The law
// it was always testing survives that move and is what is asserted here:
//
//   * a null guard exists ahead of the egress call, and
//   * the format string is not materialized into any register until AFTER the
//     guard — so "the guard tested the format" is not merely false, it is
//     unrepresentable, and
//   * the register the guard names is the one that then travels to the ABI
//     home, so it is not merely SOME live register either.
test "native backend write egress guards the value register not the format" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const write_instructions = [_]dnir.Instr{
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .str = "PATH" }, .ty = .str },
        .{ .op = .call_extern, .result = 0, .callee = "getenv", .ty = .str },
        .{ .op = .print_value, .lhs = .{ .temp = 0 }, .ty = .str, .field = "nonl" },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const print_instructions = [_]dnir.Instr{
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .str = "PATH" }, .ty = .str },
        .{ .op = .call_extern, .result = 0, .callee = "getenv", .ty = .str },
        .{ .op = .print_value, .lhs = .{ .temp = 0 }, .ty = .str },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    inline for (.{
        // callee, ABI home the value must reach, format label (null on `puts`,
        // which takes the string itself in x0 and has no format at all).
        .{ &write_instructions, "\tbl _printf\n", "x2", @as(?[]const u8, "adrp x0, Lduo_str_1") },
        .{ &print_instructions, "\tbl _puts\n", "x0", @as(?[]const u8, null) },
    }) |case| {
        const blocks = [_]dnir.Block{.{ .instrs = case[0] }};
        const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
        const module = dnir.Module{ .functions = &functions };
        var diagnostic: Diagnostic = .{};
        var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
        defer output.deinit(alloc);
        const text = output.asm_text;

        const call_at = std.mem.indexOf(u8, text, case[1]) orelse return error.NoEgressCall;
        const guard_at = std.mem.lastIndexOf(u8, text[0..call_at], ", #0\n\tb.eq ") orelse
            return error.NoNullGuard;
        const cmp_at = std.mem.lastIndexOf(u8, text[0..guard_at], "\tcmp ") orelse
            return error.NoNullGuard;
        const guard_reg = text[cmp_at + "\tcmp ".len .. guard_at];
        // A register name and nothing else — this is what fails loudly if the
        // guard ever grows an operand the parse above does not model.
        try std.testing.expect(guard_reg.len >= 2 and guard_reg[0] == 'x');

        // THE FORMAT IS NOT IN A REGISTER YET when the guard runs.
        if (case[3]) |fmt_adrp| {
            const fmt_at = std.mem.indexOf(u8, text, fmt_adrp) orelse return error.NoFormat;
            try std.testing.expect(fmt_at > guard_at);
        }

        // …and the register the guard names is the one that reaches the home.
        const home: []const u8 = case[2];
        if (!std.mem.eql(u8, guard_reg, home)) {
            const window = text[guard_at..call_at];
            const move = try std.fmt.allocPrint(alloc, "\tmov {s}, {s}\n", .{ home, guard_reg });
            try std.testing.expect(std.mem.indexOf(u8, window, move) != null);
        }
    }
}

// THE FIRST INTERNED STRING HAS SYMBOL INDEX 0, AND 0 IS NOT "NO FORMAT".
//
// `print_value` used 0 as the "no format string" sentinel for `fmt_sym`, but
// `internString` returns 0 for the first interned string. A program whose
// first print is numeric (`print(7)` with no earlier string literal) interned
// "%lld\n" at index 0, the emitter skipped the `adrp x0`, and the binary
// called printf with a garbage format pointer — a SEGV with empty output,
// which the conversion gate's arm 8 read as `''` against oracle `'7'`.
test "native backend numeric print interns its format at symbol zero" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const instructions = [_]dnir.Instr{
        .{ .op = .print_value, .lhs = .{ .i64 = 7 }, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    const text = output.asm_text;

    const call_at = std.mem.indexOf(u8, text, "\tbl _printf\n") orelse return error.NoEgressCall;
    // The format is the first interned string: symbol zero is a real symbol,
    // so its address is materialized into x0 ahead of the call.
    _ = std.mem.indexOf(u8, text[0..call_at], "adrp x0, Lduo_str_0") orelse
        return error.NoFormatAtSymbolZero;
}

// A WRITTEN MODULE-SCOPE BINDING IS ONE STORAGE LOCATION.
//
// It had none: the native-scalar profile gave a file-scope binding no storage,
// so each function treated the name as its own register-resident local, the
// write landed nowhere the next read could see, and the read folded to the
// initializer. Measured against `--backend=c` on the two fixtures that record
// it, `examples/native_differential/unsupported/`:
//
//     g066  total = total + i in a loop     direct 0 5 exit 0   c 6 5 exit 6
//     g108  main writes 8, show() reads     direct 8 5          c 8 8
//
// Two functions must therefore reach THE SAME WORD, and that is what this
// asserts — not that a global "works", but that the store's symbol and the
// load's symbol are one symbol, which is the only thing the old shape got wrong.
test "native backend gives a written module global one shared word" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const bump_instructions = [_]dnir.Instr{
        .{ .op = .load_global, .result = 0, .field = "total", .ty = .i64 },
        .{ .op = .binop, .result = 1, .binop = .add, .lhs = .{ .temp = 0 }, .rhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .store_global, .field = "total", .lhs = .{ .temp = 1 }, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const main_instructions = [_]dnir.Instr{
        .{ .op = .store_global, .field = "total", .lhs = .{ .i64 = 5 }, .ty = .i64 },
        .{ .op = .call_direct, .result = 2, .callee = "bump", .ty = .i64 },
        .{ .op = .load_global, .result = 3, .field = "total", .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 3 }, .ty = .i64 },
    };
    const bump_blocks = [_]dnir.Block{.{ .instrs = &bump_instructions }};
    const main_blocks = [_]dnir.Block{.{ .instrs = &main_instructions }};
    const functions = [_]dnir.Function{
        .{ .name = "bump", .ret = .i64, .blocks = &bump_blocks },
        .{ .name = "main", .ret = .i64, .blocks = &main_blocks },
    };
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);

    // ONE word of `__DATA,__bss`, however many times the name is mentioned. Four
    // mentions across two functions is the point: `internGlobal` must answer with
    // the same symbol every time, or each function gets a private location and
    // the defect is back with storage attached.
    try std.testing.expectEqual(@as(u64, 8), output.bss_size);
    var globals: usize = 0;
    var section: u8 = 0;
    for (output.symbols) |sym| {
        if (!std.mem.startsWith(u8, sym.name, "Lduo_g_")) continue;
        globals += 1;
        section = sym.section;
        try std.testing.expectEqualStrings("Lduo_g_total", sym.name);
        try std.testing.expect(!sym.external);
    }
    try std.testing.expectEqual(@as(usize, 1), globals);
    // Sections are __text, then __cstring / __const when non-empty, then __bss.
    // This module has neither string nor promoted table, so __bss is section 2 —
    // and a wrong index here is a relocation resolved into the wrong section.
    try std.testing.expectEqual(@as(u8, 2), section);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, ".section __DATA,__bss") != null);
}

// The address a global's word is stamped at must be the address the object
// writer lays the section down at. Two derivations of one number is how a
// relocation resolves to the wrong word, so there is one — `bssBaseAddr` — and
// this pins the property that made it necessary: 8-byte alignment on EVERY
// path, including the one with no `__const` section, which the original
// expression left to luck.
test "native backend bss base address is 8-aligned on every section layout" {
    for ([_]usize{ 0, 1, 7, 8, 9, 4096, 4097 }) |text_len| {
        for ([_]usize{ 0, 1, 5, 8, 13 }) |cstring_len| {
            for ([_]usize{ 0, 8, 16 }) |const_len| {
                const at = bssBaseAddr(text_len, cstring_len, const_len);
                try std.testing.expectEqual(@as(usize, 0), at % 8);
                try std.testing.expect(at >= text_len + cstring_len + const_len);
            }
        }
    }
}

test "native backend lowers if elseif else branches" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\pick: i64 = (n: i64)
        \\    out = 0
        \\    if n < 0
        \\        out = 11
        \\    elseif n == 0
        \\        out = 13
        \\    elseif n > 10
        \\        out = 17
        \\    else
        \\        out = 19
        \\    out
        \\
        \\main: i64 = ()
        \\    pick(11)
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    const asm_text = assembly.assembly;
    try std.testing.expect(std.mem.indexOf(u8, asm_text, "\tcmp x") != null);
    var cmp_count: usize = 0;
    var branch_count: usize = 0;
    var select_count: usize = 0;
    var lines = std.mem.splitScalar(u8, asm_text, '\n');
    while (lines.next()) |line| {
        if (std.mem.startsWith(u8, line, "\tcmp x")) cmp_count += 1;
        if (std.mem.startsWith(u8, line, "\tb.") and std.mem.indexOf(u8, line, ".Lduo_") != null) branch_count += 1;
        if (std.mem.startsWith(u8, line, "\tcsel x")) select_count += 1;
    }
    try std.testing.expect(cmp_count >= 3);
    // THREE CONDITIONS, THREE REALIZATIONS — as a branch OR as a select.
    //
    // This read `branch_count >= 3` and was pinning the LOWERING rather than
    // the fact. The chain's last rung (`elseif n > 10 \n out = 17 \n else \n
    // out = 19`) is a two-sided `if` over one binding, so W8 realizes it as a
    // `csel` and that rung stops being a branch. Counting both is what the
    // test meant: every condition is still decided, and none is dropped.
    try std.testing.expect(branch_count + select_count >= 3);

    var object = try emitCheckedTestObject(alloc, &mod, &graph);
    defer object.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, object.bytes, "_pick") != null);
}

