test "native backend authority-false physical loop oracle retains continue break and backedge" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    const instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 0 }, .ty = .i64 },
        .{ .op = .store_local, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 0 }, .ty = .i64 },
        .{ .op = .store_local, .result = 1, .lhs = .{ .temp = 1 }, .ty = .i64 },
        .{ .op = .@"const", .result = 2, .lhs = .{ .i64 = 5 }, .ty = .i64 },
        .{ .op = .binop, .result = 3, .lhs = .{ .local = 0 }, .rhs = .{ .temp = 2 }, .binop = .lt, .ty = .i64 },
        .{ .op = .br, .lhs = .{ .temp = 3 }, .branch_target = 19, .branch_condition = .when_false },
        .{ .op = .@"const", .result = 4, .lhs = .{ .i64 = 2 }, .ty = .i64 },
        .{ .op = .binop, .result = 5, .lhs = .{ .local = 0 }, .rhs = .{ .temp = 4 }, .binop = .eq, .ty = .i64 },
        .{ .op = .br, .lhs = .{ .temp = 5 }, .branch_target = 15, .branch_condition = .when_true },
        .{ .op = .@"const", .result = 6, .lhs = .{ .i64 = 4 }, .ty = .i64 },
        .{ .op = .binop, .result = 7, .lhs = .{ .local = 0 }, .rhs = .{ .temp = 6 }, .binop = .eq, .ty = .i64 },
        .{ .op = .br, .lhs = .{ .temp = 7 }, .branch_target = 19, .branch_condition = .when_true },
        .{ .op = .binop, .result = 8, .lhs = .{ .local = 1 }, .rhs = .{ .local = 0 }, .binop = .add, .ty = .i64 },
        .{ .op = .store_local, .result = 1, .lhs = .{ .temp = 8 }, .ty = .i64 },
        .{ .op = .@"const", .result = 9, .lhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .binop, .result = 10, .lhs = .{ .local = 0 }, .rhs = .{ .temp = 9 }, .binop = .add, .ty = .i64 },
        .{ .op = .store_local, .result = 0, .lhs = .{ .temp = 10 }, .ty = .i64 },
        .{ .op = .br, .branch_target = 4, .branch_condition = .unconditional },
        .{ .op = .ret, .lhs = .{ .local = 1 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "b.eq") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "\tb .Lduo_") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "add x") != null);
    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expectEqual(@as(u32, 0xfeedfacf), std.mem.readInt(u32, object[0..4], .little));
}

test "native backend: graph linkage owns source C import and relocation" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\@ffi("llabs")
        \\llabs: i64 = (n: i64)
        \\    0
        \\
        \\x = llabs(-37)
        \\x + 5
        \\
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    const external = graph.relationForDeclaration(&mod.body.stmts[0].func_decl).?;
    const linkage = graph.callableLinkage(external).?;
    try std.testing.expectEqual(semantic_graph.CallableOrigin.c, linkage.origin);
    try std.testing.expectEqual(semantic_graph.CallableExposure.c_import, linkage.exposure);
    try std.testing.expectEqualStrings("llabs", linkage.symbol);

    var checked_diagnostic: Diagnostic = .{};
    var lowered = try dnir_lower.lowerModuleWithGraphObserved(alloc, &mod, &graph, &checked_diagnostic.lowering);
    defer dnir.deinitModule(alloc, lowered);
    try validateDnirApplications(alloc, lowered, &graph, &checked_diagnostic);
    try std.testing.expectEqual(@as(usize, 1), lowered.externs.len);
    try std.testing.expectEqualStrings("llabs", lowered.externs[0].symbol);

    // A c_import identity is never a definition, even when no application
    // would otherwise force the validator to inspect its target.
    const lowered_functions: []dnir.Function = @constCast(lowered.functions);
    var root_function: ?*dnir.Function = null;
    for (lowered_functions) |*function| {
        if (function.id) |id| {
            if (graph.isModuleRoot(id)) root_function = function;
        }
    }
    const damaged_definition = root_function orelse return error.TestExpectedEqual;
    const root_id = damaged_definition.id;
    const root_name = damaged_definition.name;
    damaged_definition.id = external;
    damaged_definition.name = linkage.symbol;
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateDnirApplications(alloc, lowered, &graph, &checked_diagnostic),
    );
    try std.testing.expectEqualStrings("callable-import-definition", checked_diagnostic.note().?);
    damaged_definition.id = root_id;
    damaged_definition.name = root_name;

    var c_call: ?*dnir.Instr = null;
    for (lowered.functions) |function| {
        for (function.blocks) |block| {
            const instructions: []dnir.Instr = @constCast(block.instrs);
            for (instructions) |*instruction| {
                if (instruction.target != null and instruction.target.? == external) c_call = instruction;
            }
        }
    }
    const call = c_call orelse return error.TestExpectedEqual;
    const callee = call.callee;
    call.callee = "labs";
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateDnirApplications(alloc, lowered, &graph, &checked_diagnostic),
    );
    try std.testing.expectEqualStrings("application-link-symbol", checked_diagnostic.note().?);
    call.callee = callee;

    // Removing only the physical projection cannot be repaired from the known
    // libc spelling. The exact graph-required extern row is mandatory.
    const externs = lowered.externs;
    lowered.externs = &.{};
    try std.testing.expectError(
        error.SemanticFactsInvalid,
        validateDnirApplications(alloc, lowered, &graph, &checked_diagnostic),
    );
    try std.testing.expectEqualStrings("missing-callable-extern", checked_diagnostic.note().?);
    lowered.externs = externs;

    var checked_output = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer checked_output.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, checked_output.assembly, "bl _llabs") != null);

    const instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = -37 }, .ty = .i64 },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .call_extern, .result = 1, .callee = "llabs", .ty = .i64 },
        .{ .op = .@"const", .result = 2, .lhs = .{ .i64 = 5 }, .ty = .i64 },
        .{ .op = .binop, .result = 3, .lhs = .{ .temp = 1 }, .rhs = .{ .temp = 2 }, .binop = .add, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .temp = 3 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    try std.testing.expectEqual(@as(usize, 1), output.relocations.len);
    try std.testing.expectEqualStrings("llabs", output.symbols[output.relocations[0].symbol_index].name);
    try std.testing.expect(!output.symbols[output.relocations[0].symbol_index].defined);
    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expect(std.mem.indexOf(u8, object, "_llabs") != null);
}

test "native backend: graph linkage owns source C string import" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\@ffi("puts")
        \\puts: i64 = (s: str)
        \\    0
        \\
        \\puts("Hello")
        \\0
        \\
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    const external = graph.relationForDeclaration(&mod.body.stmts[0].func_decl).?;
    const linkage = graph.callableLinkage(external).?;
    try std.testing.expectEqual(semantic_graph.CallableExposure.c_import, linkage.exposure);
    try std.testing.expectEqualStrings("puts", linkage.symbol);
    var checked_output = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer checked_output.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, checked_output.assembly, "bl _puts") != null);

    const instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .str = "Hello" }, .ty = .str },
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .str },
        .{ .op = .call_extern, .result = 1, .callee = "puts", .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    // Interned literal materializes in the cstring section.
    try std.testing.expect(output.cstring.len > 0);
    try std.testing.expect(std.mem.indexOf(u8, output.cstring, "Hello") != null);

    // Three relocations: one branch26 to puts, plus a page21/pageoff12 pair to the string label.
    try std.testing.expectEqual(@as(usize, 3), output.relocations.len);
    var saw_branch_puts = false;
    var saw_page21 = false;
    var saw_pageoff12 = false;
    for (output.relocations) |reloc| {
        const sym = output.symbols[reloc.symbol_index];
        switch (reloc.kind) {
            .branch26 => {
                try std.testing.expectEqualStrings("puts", sym.name);
                try std.testing.expect(!sym.defined);
                saw_branch_puts = true;
            },
            .page21 => {
                try std.testing.expect(sym.defined and !sym.external and sym.section == 2);
                saw_page21 = true;
            },
            .pageoff12 => {
                try std.testing.expect(sym.defined and !sym.external and sym.section == 2);
                saw_pageoff12 = true;
            },
            .abs64 => unreachable, // data-section only; lives in output.data_relocations
        }
    }
    try std.testing.expect(saw_branch_puts);
    try std.testing.expect(saw_page21);
    try std.testing.expect(saw_pageoff12);

    // The string section symbol's n_value is the absolute VM address (text.len + cstring offset),
    // never a bare cstring-relative offset — clang's linker rejects the latter.
    const text_len: u32 = @intCast(output.text.len);
    for (output.symbols) |sym| {
        if (sym.defined and !sym.external and sym.section == 2) {
            try std.testing.expect(sym.offset >= text_len);
        }
    }

    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expect(std.mem.indexOf(u8, object, "__cstring") != null);
    try std.testing.expect(std.mem.indexOf(u8, object, "_puts") != null);
}

test "interned string label is not aliased between symbol and string tables" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };

    _ = try compiler.internString("Hello");
    // The strings table must own its OWN copy of the label. `finish` moves
    // the symbol table into the output while the strings table stays with
    // the compiler, so a shared allocation is a use-after-free of the
    // output's symbol name the moment `deinit` frees the strings table —
    // it surfaced as garbage local-symbol names in emitted objects.
    try std.testing.expect(compiler.strings.items[0].name.ptr != compiler.symbols.items[0].name.ptr);
    try std.testing.expectEqualStrings("Lduo_str_0", compiler.strings.items[0].name);

    var output = try compiler.finish();
    compiler.deinit();

    try std.testing.expectEqual(@as(usize, 1), output.symbols.len);
    try std.testing.expectEqualStrings("Lduo_str_0", output.symbols[0].name);
    output.deinit(alloc);
}

