    instruction.* = saved;
}

test "native backend assembly lists helper call labels" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\add(a: i64, b: i64): i64
        \\    a + b
        \\end
        \\
        \\main(seed: i64): i64
        \\    add(1, 2)
        \\end
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    const asm_text = assembly.assembly;
    // `native.id` is home `native`. `main(seed: i64)` TAKES AN OPERAND, so it
    // is not eligible to be the process at all and is an ordinary relation of
    // this home — one parameter away from the `.globl _main` the two tests
    // above and below pin. That is the whole content of the narrowed
    // process-entry exemption: the spelling `main` is not the fact.
    try std.testing.expect(std.mem.indexOf(u8, asm_text, ".globl _idol_native__add") != null);
    try std.testing.expect(std.mem.indexOf(u8, asm_text, ".globl _idol_native__main") != null);
    try std.testing.expect(std.mem.indexOf(u8, asm_text, ".globl _main\n") == null);
    // `main`'s whole body IS `add(1, 2)`, so the application is in tail
    // position and §12 TAIL realizes it as a jump: the frame goes back first
    // and x30 still names main's caller, so `add` returns straight past it.
    try std.testing.expect(std.mem.indexOf(u8, asm_text, "\tb _idol_native__add\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, asm_text, "\tbl _idol_native__add\n") == null);
}

// Source `print` reaches machine code, and it reaches the SAME machine code as
// `stdout:write`.
//
// This test used to assert the opposite — that `print(1)` in an ordinary module
// refused with `unresolved-application-facts` — and that refusal was the single
// largest hole in the direct backend: measured over the 1005 tracked `.id`
// files, 110 programs that `idol check` accepts and the C bootstrap compiles
// were refused by direct naming exactly this one relation. `print(v)` and
// `stdout:write(v)` are one host-egress node (`dnir_lower.lowerPrint`), and the
// only thing separating them was WHERE the file lived. The physical
// `print_value` oracle below is unchanged: it is the DNIR-level control that
// the egress op still lowers to a real libc call.
test "native backend lowers source print to host egress and retains physical print oracle" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\main(): i64
        \\    print(1)
        \\    0
        \\end
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);

    // `emitAssemblyModeWithGraphLineage` refuses unless the HOST is
    // aarch64-macos, so everything below the graph lift is unavailable
    // elsewhere. Every other physical test in this file carries this guard;
    // this one did not, so it was the single red test in the suite on any other
    // host — reported as a backend defect when it was a missing guard.
    //
    // The off-host arm ASSERTS THE REFUSAL rather than skipping. `DNB004` is a
    // published outcome, a skip measures nothing, and a refusal that quietly
    // became a wrong answer is exactly what this suite exists to catch.
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) {
        try std.testing.expectError(
            error.UnsupportedTarget,
            emitCheckedTestAssembly(alloc, &mod, &graph, null),
        );
        return;
    }

    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, assembly.assembly, ".globl _main") != null);
    try std.testing.expect(std.mem.indexOf(u8, assembly.assembly, "bl _printf") != null);

    // The subject-first spelling of the same egress, in a module with the same
    // name, must produce the same call — one node, not two. It used to produce
    // `puts` against `print`'s `printf`, which is TWO nodes wearing one name and
    // is why `stdout:write` carried a newline `print` is entitled to and write
    // is not.
    var stream_lex = Lexer.init(
        \\main: i64 = ()
        \\    stdout:write("1")
        \\    0
    , "native.id");
    var stream_parser = Parser.init(&stream_lex, alloc);
    stream_parser.idol_mode = true;
    var stream_mod = try stream_parser.parse_module();
    var stream_sem = Sema.init(alloc);
    defer stream_sem.deinit();
    stream_sem.idol_mode = true;
    try stream_sem.check_module(&stream_mod);
    var stream_graph = semantic_graph.SemanticGraph.init(alloc);
    defer stream_graph.deinit();
    try liftCheckedTestGraph(&stream_mod, &stream_sem, &stream_graph);
    var stream_assembly = try emitCheckedTestAssembly(alloc, &stream_mod, &stream_graph, null);
    defer stream_assembly.deinit(alloc);
    try expectWriteEgress(stream_assembly.assembly);

    const instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .print_value, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "bl _printf") != null);
    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expect(std.mem.indexOf(u8, object, "_printf") != null);
}

// HOST EGRESS IS A CALL, AND A CALL DOES NOT GET TO EAT ITS CALLER'S VALUES.
//
// The defect this pins answered WRONG and said nothing. In
//
//     _r4: { a: i64, b: i64, c: i64, d: i64 }
//     _show: i64 = (p: _r4)   print(99)   return p.<field>
//
// `p.a` came back 208, `p.b` 2, `p.c` 99, `p.d` 4 — the low byte of the format
// string's address, then the right answer, then PRINT'S OWN ARGUMENT, then the
// right answer. Exit 0, no diagnostic. Alternating fields, because x0 and x2
// are the two registers printf's call shape writes and they are the first and
// third argument slots of the exploded record.
//
// TWO INDEPENDENT MECHANISMS PRODUCED IT, and this test pins both, because
// either one alone still miscompiles:
//
//   * `print_value` staged `adrp x0, <fmt>` and `mov x2, <value>` ABOVE
//     `emitSaveCallerRegs`, so the save preserved printf's arguments and the
//     restore wrote them back over the caller's live values. The physical
//     signature is ordering: `str x30, [sp,` closes the caller-save block, and
//     it must precede every argument write. Asserted below.
//
//   * `dnirFunctionHasCall` did not count `print_value`, so a printing body was
//     planned as a LEAF and kept its parameters in the incoming ABI registers
//     across the `bl`. The physical signature is residency: after the egress
//     call, nothing may be READ out of x0..x7. Asserted below.
//
// A compile-only assertion is exactly what a silent wrong answer defeats, so
// the ANSWER is asserted too, by
// `examples/native_differential/native_only/record_param_across_egress.id`
// (every field of a 3/4/5/8/12/16-field record read after an egress call, plus
// scalar mixes, local mutation, and f64 parameters — exit 97 or a distinct code
// naming the field that came back wrong).
test "native backend keeps record parameter fields alive across host egress" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\_r4: { a: i64, b: i64, c: i64, d: i64 }
        \\
        \\_show: i64 = (p: _r4)
        \\  print(99)
        \\  return p.a + p.b + p.c + p.d
        \\
        \\main: i64 = ()
        \\  v: _r4 = { a = 1, b = 2, c = 3, d = 4 }
        \\  return _show(v)
    , "native.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    const asm_text = assembly.assembly;

    const label = "_idol_native___show:\n";
    const body_at = (std.mem.indexOf(u8, asm_text, label) orelse
        return error.NoShowRelation) + label.len;
    const body_end = std.mem.indexOfPos(u8, asm_text, body_at, "\n\n") orelse asm_text.len;
    const body = asm_text[body_at..body_end];

    const call_at = std.mem.indexOf(u8, body, "\tbl _printf\n") orelse return error.NoEgressCall;
    const before_call = body[0..call_at];
    const after_call = body[call_at + "\tbl _printf\n".len ..];

    // ORDERING. `emitSaveCallerRegs` always stores x30, and always last in its
    // GP run, so its position IS the end of the save block. Every register the
    // call shape writes must be written after it.
    const save_at = std.mem.indexOf(u8, before_call, "\tstr x30, [sp,") orelse
        return error.NoCallerSave;
    if (std.mem.indexOf(u8, before_call, "\tadrp x0,")) |fmt_at| {
        try std.testing.expect(save_at < fmt_at);
    }
    if (std.mem.indexOf(u8, before_call, "\tmov x2,")) |arg_at| {
        try std.testing.expect(save_at < arg_at);
    }

    // RESIDENCY. The four fields arrive in x0..x3 and the body reads all four
    // AFTER the egress call, so if any read still names an argument register
    // the value it reads is whatever printf left there. The only x0 the tail is
    // allowed is the WRITE that returns the sum.
    inline for (.{ ", x0\n", ", x1\n", ", x2\n", ", x3\n", ", x0,", ", x1,", ", x2,", ", x3," }) |read| {
        try std.testing.expect(std.mem.indexOf(u8, after_call, read) == null);
    }
}

test "native backend refuses source sealed record application absent graph identity facts" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\Point: { x: f64, y: f64 }
        \\length2(p: Point): f64
        \\    p.x * p.x + p.y * p.y
        \\end
        \\main(): i64
        \\    if length2({ x = 3.0, y = 4.0 }) == 25.0
        \\        return 0
        \\    else
        \\        return 1
        \\    end
        \\end
    , "pass11_record_proof.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    // A record literal (`{ x = 3.0, y = 4.0 }`) passed as an operand cannot cross
    // the scalar application ABI, so the checked-operand law rejects it at the
    // precise site — `application-operand-abi` — before any generic missing-id
    // refusal. Surfacing the operand-shape reason first is strictly more
    // informative than the earlier catch-all `missing-application-id`.
    try expectCheckedTestSemanticFailure(
        alloc,
        &mod,
        &sem,
        "graph-dnir-facts",
        "application-operand-abi",
    );
}

