test "WP-04: a sixteen-field record parameter stacks its overflow fields" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // SIXTEEN FIELDS: eight in x0..x7 and eight in the caller's outgoing
    // argument area. `functionEligibleReason` refused this outright — "record
    // parameter fields overflow the 8 argument registers" — on the ground that
    // a record's fields are never stacked. They are; a field is a
    // general-purpose word and the slot index is the only thing either end
    // reads.
    //
    // THE ASSERTION IS ON THE EMITTED FORM, not on "it compiled". A budget
    // raised without the two ends agreeing about WHERE the ninth word lives
    // still links, still exits, and answers with caller garbage — which is the
    // failure mode this whole area keeps producing. So: the caller must open a
    // 64-byte outgoing block (eight overflow words) and write the sixteenth to
    // its last slot, and the callee must read that same slot back.
    //
    // `forward` EXISTS TO KEEP A CALL SITE. `main` takes no operands and its
    // body folds to a constant (lawful nonexecution), so a module whose only
    // application lives in `main` emits a callee and no caller at all — the
    // half of the seam this test is about would simply not be in the listing.
    // A relation that takes an operand does not fold.
    const source =
        \\big: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, i: i64, j: i64, k: i64, l: i64, m: i64, n: i64, o: i64, p: i64 }
        \\last(v: big): i64
        \\    return v.p
        \\end
        \\forward(v: big): i64
        \\    return last(v)
        \\end
        \\main(): i64
        \\    w: big = { a = 1, b = 2, c = 3, d = 4, e = 5, f = 6, g = 7, h = 8, i = 9, j = 10, k = 11, l = 12, m = 13, n = 14, o = 15, p = 116 }
        \\    forward(w)
        \\end
    ;
    var lex = Lexer.init(source, "wide_record_param.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);

    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);

    // The outgoing block is exactly eight words: sixteen slots less the eight
    // that ride registers.
    try std.testing.expect(std.mem.indexOf(u8, assembly.assembly, "sub sp, sp, #64") != null);

    // Slot 15 — the sixteenth field — is written by the caller and read by the
    // callee at the same displacement, (15 - 8) * 8.
    var wrote_last_slot = false;
    var read_last_slot = false;
    var lines = std.mem.splitScalar(u8, assembly.assembly, '\n');
    while (lines.next()) |raw| {
        const line = std.mem.trim(u8, raw, " \t\r");
        if (!std.mem.endsWith(u8, line, ", [sp, #56]")) continue;
        if (std.mem.startsWith(u8, line, "str x")) wrote_last_slot = true;
        if (std.mem.startsWith(u8, line, "ldr x")) read_last_slot = true;
    }
    try std.testing.expect(wrote_last_slot);
    try std.testing.expect(read_last_slot);

    var object = try emitCheckedTestObject(alloc, &mod, &graph);
    defer object.deinit(alloc);
    try std.testing.expect(object.bytes.len > 0);
}

test "native backend refuses unresolved byte call and retains branch-field physical oracle" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const source =
        \\wasm_header = { 0x00, 0x61, 0x73, 0x6D }
        \\read_u8_at(base: i64, off: i64): i64
        \\    __native_load_u8(base, off)
        \\end
        \\main(): i64
        \\    c = { data = wasm_header, pos = 0, len = 8 }
        \\    b0 = read_u8_at(c.data, 0)
        \\    if b0 != 0 return 1001 end
        \\    c.pos = c.pos + 1
        \\    if c.pos != 1 return 1006 end
        \\    0
        \\end
    ;
    var lex = Lexer.init(source, "pass11_wasm_blob_direct.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    try expectCheckedTestSemanticFailure(
        alloc,
        &mod,
        &sem,
        "unresolved-application-facts",
        null,
    );

    const instructions = [_]dnir.Instr{
        .{ .op = .@"const", .result = 0, .lhs = .{ .str = "\x00asm" }, .ty = .str },
        .{ .op = .@"const", .result = 1, .lhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .load_index, .result = 2, .lhs = .{ .temp = 0 }, .rhs = .{ .temp = 1 }, .ty = .u8 },
        .{ .op = .@"const", .result = 3, .lhs = .{ .i64 = 0 }, .ty = .i64 },
        .{ .op = .binop, .result = 4, .lhs = .{ .temp = 2 }, .rhs = .{ .temp = 3 }, .binop = .neq, .ty = .i64 },
        .{ .op = .br, .lhs = .{ .temp = 4 }, .branch_target = 7, .branch_condition = .when_false },
        .{ .op = .ret, .lhs = .{ .i64 = 1001 }, .ty = .i64 },
        .{ .op = .@"const", .result = 5, .lhs = .{ .i64 = 0 }, .ty = .i64 },
        .{ .op = .store_local, .result = 10, .lhs = .{ .temp = 5 }, .record = "Cursor", .field = "pos", .ty = .i64 },
        .{ .op = .@"const", .result = 6, .lhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .binop, .result = 7, .lhs = .{ .local = 10 }, .rhs = .{ .temp = 6 }, .binop = .add, .ty = .i64 },
        .{ .op = .store_local, .result = 10, .lhs = .{ .temp = 7 }, .record = "Cursor", .field = "pos", .ty = .i64 },
        .{ .op = .@"const", .result = 8, .lhs = .{ .i64 = 1 }, .ty = .i64 },
        .{ .op = .binop, .result = 9, .lhs = .{ .local = 10 }, .rhs = .{ .temp = 8 }, .binop = .neq, .ty = .i64 },
        .{ .op = .br, .lhs = .{ .temp = 9 }, .branch_target = 16, .branch_condition = .when_false },
        .{ .op = .ret, .lhs = .{ .i64 = 1006 }, .ty = .i64 },
        .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const functions = [_]dnir.Function{.{ .name = "main", .ret = .i64, .blocks = &blocks }};
    const module = dnir.Module{ .functions = &functions };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.graph == null);
    try std.testing.expectEqual(@as(usize, 0), output.lineage.len);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "ldrb") != null);
    try std.testing.expect(std.mem.count(u8, output.asm_text, "add x") >= 2);
    try std.testing.expect(std.mem.count(u8, output.asm_text, "b.eq") >= 2);
    const object = try emitMachOArm64Object(
        alloc,
        output.text,
        output.cstring,
        output.symbols,
        output.relocations,
        output.bss_size,
    );
    defer alloc.free(object);
    try std.testing.expectEqual(@as(u32, 0xfeedfacf), std.mem.readInt(u32, object[0..4], .little));
}

test "unused immediate bindings do not demand register or stack places" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const source =
        \\main: i64 = ()
        \\    v0 = 1
        \\    v1 = 1
        \\    v2 = 1
        \\    v3 = 1
        \\    v4 = 1
        \\    v5 = 1
        \\    v6 = 1
        \\    v7 = 1
        \\    v8 = 1
        \\    v9 = 1
        \\    v10 = 1
        \\    v11 = 1
        \\    v12 = 1
        \\    v13 = 1
        \\    v14 = 1
        \\    v15 = 1
        \\    v16 = 1
        \\    v17 = 1
        \\    v18 = 1
        \\    v19 = 1
        \\    v20 = 1
        \\    v21 = 1
        \\    v0 + v21
    ;
    var lex = Lexer.init(source, "pass11_spill_proof.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    const listing = assembly.assembly;
    try std.testing.expect(std.mem.indexOf(u8, listing, "\tstr x") == null);
    try std.testing.expect(std.mem.indexOf(u8, listing, "\tldr x") == null);
    try std.testing.expect(std.mem.indexOf(u8, listing, "\tsub sp") == null);
    try std.testing.expect(std.mem.indexOf(u8, listing, "lua_") == null);

    var object = try emitCheckedTestObject(alloc, &mod, &graph);
    defer object.deinit(alloc);
    try std.testing.expect(object.bytes.len > 0);

    const minimal_source =
        \\main: i64 = ()
        \\    v0 = 1
        \\    v21 = 1
        \\    v0 + v21
    ;
    var minimal_lex = Lexer.init(minimal_source, "pass11-spill-proof.id");
    var minimal_parser = Parser.init(&minimal_lex, alloc);
    minimal_parser.idol_mode = true;
    var minimal_mod = try minimal_parser.parse_module();
    var minimal_sem = Sema.init(alloc);
    defer minimal_sem.deinit();
    minimal_sem.idol_mode = true;
    try minimal_sem.check_module(&minimal_mod);

    var minimal_graph = semantic_graph.SemanticGraph.init(alloc);
    defer minimal_graph.deinit();
    try liftCheckedTestGraph(&minimal_mod, &minimal_sem, &minimal_graph);
    var minimal_assembly = try emitCheckedTestAssembly(alloc, &minimal_mod, &minimal_graph, null);
    defer minimal_assembly.deinit(alloc);
    try std.testing.expectEqualStrings(minimal_assembly.assembly, listing);
    var minimal_object = try emitCheckedTestObject(alloc, &minimal_mod, &minimal_graph);
    defer minimal_object.deinit(alloc);
    try std.testing.expectEqualSlices(u8, minimal_object.bytes, object.bytes);
}

test "native backend spills GP locals past home budget without aliasing owners" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE VALUES ARE PARAMETER-DERIVED ON PURPOSE. Every binding used to be
    // `= 1`, and that stopped probing anything the day constant folding reached
    // USED bindings: the whole body collapses to a single immediate, there is
    // nothing left to spill, and `saw_stack_local` is false. The test would then
    // report a failure for a pass WORKING.
    //
    // The neighbouring test at "unused immediate bindings do not demand register
    // or stack places" asserts exactly the opposite for the same 21-binding
    // shape — no `str`, no `ldr`, no `sub sp` — so the two are only telling
    // different stories while one of them is opaque to the folder. Deriving
    // every value from `n` makes this one opaque by construction: the folder
    // cannot know `n`, all 21 stay live to the sum, and register pressure is
    // real rather than notional.
    //
    // This matters more than it looks. The GP home budget was measured at 20
    // against a pool of 19 allocatable registers (x9-x17, x19-x28; x18 is
    // Apple's reserved platform register), and that mismatch stayed invisible
    // for as long as every table-indexing function looked like a caller and
    // spilled everything anyway. A test whose body folds cannot see a
    // register-pressure bug at all.
    const source =
        \\pressure: i64 = (n: i64)
        \\    v0 = n + 1
        \\    v1 = n + 2
        \\    v2 = n + 3
        \\    v3 = n + 4
        \\    v4 = n + 5
        \\    v5 = n + 6
        \\    v6 = n + 7
        \\    v7 = n + 8
        \\    v8 = n + 9
        \\    v9 = n + 10
        \\    v10 = n + 11
        \\    v11 = n + 12
        \\    v12 = n + 13
        \\    v13 = n + 14
        \\    v14 = n + 15
        \\    v15 = n + 16
        \\    v16 = n + 17
        \\    v17 = n + 18
        \\    v18 = n + 19
        \\    v19 = n + 20
        \\    v20 = n + 21
        \\    v0 + v1 + v2 + v3 + v4 + v5 + v6 + v7 + v8 + v9 + v10 + v11 + v12 + v13 + v14 + v15 + v16 + v17 + v18 + v19 + v20
        \\
        \\main: i64 = ()
        \\    pressure(1)
    ;
    var lex = Lexer.init(source, "live-register-pressure.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64ModuleWithGraph(
        alloc,
        &mod,
        null,
        &graph,
        &diagnostic,
    );
    defer output.deinit(alloc);
    var saw_stack_local = false;
    for (output.cost) |entry| {
        if (entry.kind == .stack_local) saw_stack_local = true;
    }
    try std.testing.expect(saw_stack_local);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "_main") != null);
    // The body must NOT have folded — if it did, `saw_stack_local` above is
    // measuring nothing and this test has quietly stopped being a test. 21 live
    // parameter-derived values cannot collapse to one immediate, so the relation
    // has to still be emitted.
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "pressure") != null);
}

test "record return wider than x0..x7 uses the AAPCS64 x8 indirect result" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // Nine i64 fields: one more than the argument register file, so the record
    // cannot be exploded and the caller must hand over a buffer address.
    // Verified by VALUE, not only by shape: the same program built with
    // `--emit exe` reads all nine fields back (11,22,…,99) and agrees with
    // `--backend=c` field for field.
    const source =
        \\big: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, i: i64 }
        \\mk(): big
        \\    return { a = 11, b = 22, c = 33, d = 44, e = 55, f = 66, g = 77, h = 88, i = 99 }
        \\end
        \\main(seed: i64): i64
        \\    v = mk()
        \\    return v.a + v.i
        \\end
    ;
    var lex = Lexer.init(source, "indirect_ret.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&mod, &sem, "indirect_ret.id");
    try std.testing.expectEqual(@as(usize, 1), graph.applications().len);

    var assembly = try emitAssemblyWithGraphLineage(alloc, &mod, "native-asm", &graph);
    defer assembly.deinit(alloc);
    const listing = assembly.assembly;

    // Caller: reserve the buffer and point x8 at it BEFORE the branch.
    const x8_setup = std.mem.indexOf(u8, listing, "add x8, sp,") orelse
        return error.MissingIndirectResultPointer;
    const call_site = std.mem.indexOf(u8, listing, "\tbl _idol_indirect_ret__mk\n") orelse
        return error.MissingCall;
    try std.testing.expect(x8_setup < call_site);

    // Callee: park x8 while it is still live, then write through the parked
    // copy. `mov x9, x8` is the parking move; the last field lands at +64.
    try std.testing.expect(std.mem.indexOf(u8, listing, ", x8\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, listing, ", #64]\n") != null);

    // And it is genuinely indirect: nothing is returned in the argument file.
    const mk_start = std.mem.indexOf(u8, listing, "_mk:\n") orelse return error.MissingCallee;
    const mk_body = listing[mk_start..call_site];
    try std.testing.expect(std.mem.indexOf(u8, mk_body, "mov x0,") == null);

    var object = try emitObjectWithGraphLineage(alloc, &mod, "native-object", &graph);
    defer object.deinit(alloc);
    try std.testing.expect(object.bytes.len > 0);
}

test "an eight-field record return still explodes into x0..x7" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // The no-regression control for the register path, and the case that was
    // silently WRONG: `ret_record` carried three values in lhs/rhs/third and
    // stopped, while the caller copied x0..x7 out regardless — so field five
    // onward was whatever the frame left behind. Exercised by value: this
    // program exits 18 (1*10 + 8) under both backends; it exited 10 before.
    const source =
        \\eight: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64 }
        \\mk(): eight
        \\    return { a = 1, b = 2, c = 3, d = 4, e = 5, f = 6, g = 7, h = 8 }
        \\end
        \\main(seed: i64): i64
        \\    v = mk()
        \\    return v.a * 10 + v.h
        \\end
    ;
    var lex = Lexer.init(source, "explode8.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    var assembly = try emitCheckedTestAssembly(alloc, &mod, &graph, null);
    defer assembly.deinit(alloc);
    const listing = assembly.assembly;

    // Every one of the eight ABI registers is written, including the eighth.
    try std.testing.expect(std.mem.indexOf(u8, listing, "mov x7,") != null);
    // And no indirect buffer is set up — this path stays in registers.
    try std.testing.expect(std.mem.indexOf(u8, listing, "add x8, sp,") == null);
    // x18 is Apple's reserved platform register; eight staged fields is the
    // pressure that used to reach it.
    try std.testing.expect(std.mem.indexOf(u8, listing, "x18") == null);

    var object = try emitCheckedTestObject(alloc, &mod, &graph);
    defer object.deinit(alloc);
    try std.testing.expect(object.bytes.len > 0);
}

/// Compile one `idol_mode` source through the direct backend and hand back the
/// module output, so the three tests below can read `cost` and `asm_text`
/// without repeating twenty lines of front-end setup each.
fn carriedLocalTestModule(
    alloc: std.mem.Allocator,
    source: []const u8,
    diagnostic: *Diagnostic,
) !Arm64Output {
    var lex = Lexer.init(source, "carried-local.id");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var sem = Sema.init(alloc);
    defer sem.deinit();
    sem.idol_mode = true;
    try sem.check_module(&mod);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    try liftCheckedTestGraph(&mod, &sem, &graph);
    return try emitArm64ModuleWithGraph(alloc, &mod, null, &graph, diagnostic);
}

fn countStackLocals(cost: []const CostEntry, needle: []const u8) usize {
    var n: usize = 0;
    for (cost) |entry| {
        if (entry.kind != .stack_local) continue;
        if (needle.len == 0 or std.mem.indexOf(u8, entry.reason, needle) != null) n += 1;
    }
    return n;
}

test "CFG liveness reaches its fixpoint beyond sixteen widening steps" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);

    try last.put(alloc, 7, 1);
    try defined.put(alloc, 7, 0);

    // Reverse order forces exactly one newly reachable back edge per pass.
    // The retired sixteen-round ceiling pinned this value to maxInt instead of
    // deriving the last CFG tail that actually contains it.
    var back: [17][2]u32 = undefined;
    for (0..back.len) |i| {
        const head: u32 = @intCast(back.len - i);
        back[i] = .{ head, head + 1 };
    }

    const reads = [_][2]u32{.{ 7, 1 }};
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 18), last.get(7));
}

test "CFG liveness carries a parameter through a loop at function entry" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);

    // Parameters have no defining instruction. Treating that absence as an
    // instruction-zero definition makes a loop whose header is zero exclude
    // them from widening, even though they entered the function before it.
    try last.put(alloc, 7, 2);
    const back = [_][2]u32{.{ 0, 4 }};
    const reads = [_][2]u32{.{ 7, 2 }, .{ 8, 2 }};

    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 4), last.get(7));

    // A value genuinely defined at the header is new on every iteration and
    // must remain distinct from the carried-in parameter case above.
    try last.put(alloc, 8, 2);
    try defined.put(alloc, 8, 0);
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 2), last.get(8));
}

test "CFG liveness carries a value read before its loop redefinition" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);
    const back = [_][2]u32{.{ 2, 6 }};

    // The value entering at the back edge is read at the header before this
    // iteration replaces it. Its first definition is inside the loop, but that
    // definition does not dominate the header read.
    try last.put(alloc, 7, 2);
    try defined.put(alloc, 7, 4);
    const reads = [_][2]u32{ .{ 7, 0 }, .{ 7, 2 }, .{ 8, 4 } };
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 6), last.get(7));

    // A definition before the first read dominates every iteration's read and
    // therefore does not carry the previous iteration's realization.
    try last.put(alloc, 8, 4);
    try defined.put(alloc, 8, 3);
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 4), last.get(8));
}

test "CFG liveness carries a value read by its loop redefinition" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);
    const back = [_][2]u32{.{ 2, 6 }};

    // A same-place update reads the entering value before publishing its
    // replacement. Instruction indexes alone coincide, but semantic order does
    // not: the read must retain the realization through the back edge.
    try last.put(alloc, 7, 4);
    try defined.put(alloc, 7, 4);
    const reads = [_][2]u32{ .{ 7, 4 }, .{ 8, 5 } };
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 6), last.get(7));

    // A later read consumes the value produced inside this iteration; it does
    // not make the prior iteration's realization loop-carried.
    try last.put(alloc, 8, 5);
    try defined.put(alloc, 8, 3);
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &.{});
    try std.testing.expectEqual(@as(?u32, 5), last.get(8));
}

test "CFG liveness carries a value when control skips its loop definition" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);
    const back = [_][2]u32{.{ 2, 8 }};
    const reads = [_][2]u32{.{ 7, 6 }};

    // The branch at the loop header can land after the definition. Its later
    // read therefore consumes the value entering the loop on that path even
    // though the definition is textually first.
    try last.put(alloc, 7, 6);
    try defined.put(alloc, 7, 4);
    const bypass = [_][2]u32{.{ 2, 6 }};
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &bypass);
    try std.testing.expectEqual(@as(?u32, 8), last.get(7));

    try last.put(alloc, 7, 6);
    const late = [_][2]u32{.{ 2, 7 }};
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &late);
    try std.testing.expectEqual(@as(?u32, 6), last.get(7));

    try last.put(alloc, 7, 6);
    const nested = [_][2]u32{ .{ 2, 8 }, .{ 5, 7 } };
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &nested, &late);
    try std.testing.expectEqual(@as(?u32, 8), last.get(7));

    try last.put(alloc, 7, 6);
    const crossed = [_][2]u32{ .{ 2, 8 }, .{ 3, 7 } };
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &crossed, &late);
    try std.testing.expectEqual(@as(?u32, 6), last.get(7));

    // Edges wholly before or after the definition do not bypass it.
    try last.put(alloc, 7, 6);
    const separate = [_][2]u32{ .{ 2, 3 }, .{ 5, 6 } };
    Arm64Compiler.widenValueLastUses(&last, &reads, &defined, &back, &separate);
    try std.testing.expectEqual(@as(?u32, 6), last.get(7));
}

test "CFG liveness retains nested and deferred consumption" {
    const alloc = std.testing.allocator;
    var last: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer last.deinit(alloc);
    var defined: std.AutoHashMapUnmanaged(u32, u32) = .empty;
    defer defined.deinit(alloc);
    try defined.put(alloc, 7, 4);
    const forward = [_][2]u32{.{ 2, 7 }};
    const nested = [_][2]u32{ .{ 2, 8 }, .{ 1, 7 } };
    const reversed = [_][2]u32{ .{ 1, 7 }, .{ 2, 8 } };
    const prior = [_][2]u32{.{ 7, 1 }};
    for ([_][]const [2]u32{ &nested, &reversed }) |back| {
        try last.put(alloc, 7, 1);
        Arm64Compiler.widenValueLastUses(&last, &prior, &defined, back, &forward);
        try std.testing.expectEqual(@as(?u32, 8), last.get(7));
    }
    const back = [_][2]u32{.{ 2, 8 }};
    const staged = [_][2]u32{.{ 7, 6 }};
    try last.put(alloc, 7, 7);
    Arm64Compiler.widenValueLastUses(&last, &staged, &defined, &back, &forward);
    try std.testing.expectEqual(@as(?u32, 8), last.get(7));
}

test "CFG liveness releases values when a branch skips their definition and read" {
    const alloc = std.testing.allocator;
    const parameter = [_]dnir.Param{.{ .name = "n", .ty = .i64 }};
    var instruction: [83]dnir.Instr = undefined;
    instruction[0] = .{ .op = .br, .lhs = .{ .local = 0 }, .branch_target = 81, .branch_condition = .when_true };
    for (0..40) |index| {
        const value: u32 = @intCast(index + 1);
        instruction[index * 2 + 1] = .{ .op = .@"const", .result = value, .lhs = .{ .i64 = @intCast(index + 3) }, .ty = .i64 };
        instruction[index * 2 + 2] = .{ .op = .binop, .result = value + 40, .lhs = .{ .temp = value }, .rhs = .{ .local = 0 }, .binop = .add, .ty = .i64 };
    }
    instruction[81] = .{ .op = .br, .lhs = .{ .local = 0 }, .branch_target = 0, .branch_condition = .when_true };
    instruction[82] = .{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .i64 };
    const block = [_]dnir.Block{.{ .instrs = &instruction }};
    const function = [_]dnir.Function{.{ .name = "scan", .ret = .i64, .params = &parameter, .blocks = &block }};
    const module = dnir.Module{ .functions = &function };
    var diagnostic: Diagnostic = .{};
    var output = try emitArm64FromDnir(alloc, module, null, &diagnostic);
    defer output.deinit(alloc);
    try std.testing.expect(output.text.len > 0);
    for (output.cost) |entry| try std.testing.expect(entry.kind != .spill);
}

test "CFG liveness does not read ABI staging slots as value definitions" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // `result` on both staging instructions is an ABI register slot, not the
    // definition of the parameter with the same numeric id. Both parameters
    // enter before the entry-header loop and are read again on every trip.
    const instructions = [_]dnir.Instr{
        .{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = 0 }, .ty = .i64 },
        .{ .op = .fp_mov_arg, .result = 1, .lhs = .{ .temp = 1 }, .ty = .f64 },
        .{ .op = .br, .lhs = .{ .temp = 2 }, .branch_target = 0, .branch_condition = .when_true },
    };
    const blocks = [_]dnir.Block{.{ .instrs = &instructions }};
    const function = dnir.Function{
        .name = "stage",
        .ret = .void,
        .blocks = &blocks,
    };

    try compiler.computeValueLastUse(function);
    try std.testing.expectEqual(@as(?u32, 2), compiler.value_free_at.get(0));
    try std.testing.expectEqual(@as(?u32, 2), compiler.value_free_at.get(1));
}

test "a carried local in a calling function keeps its register across the back edge" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE DEFECT THIS PINS, and it was the largest measured one in the compiler:
    // `planGpStackLocals` read `gate_spill_all_locals = body_has_call`, so ONE
    // call anywhere in a function put EVERY local in the frame for the whole
    // body — a `str` per assignment and an `ldr` per read, on every iteration of
    // every loop. `benchmarks/cyc/w/ilp4.id` carries four values through such a
    // loop and paid it eight times an iteration; the row sat at 2.34x its
    // answer-checked floor while clang sat at 0.98x.
    //
    // The call is deliberately OUTSIDE the loop. That is the point: the old rule
    // never asked where the call was, only whether one existed.
    //
    // EVERY VALUE IS PARAMETER-DERIVED, for the reason the neighbouring
    // "spills GP locals past home budget" test spells out at length — with
    // literal seeds the folder evaluates the entire loop and `_main` becomes
    // `mov x0, #0x2d7; ret`, at which point there are no locals and this test
    // reports success for a pass that never ran. The `kernel` guard at the
    // bottom is what makes that failure visible instead of silent.
    const source =
        \\step: i64 = (n: i64)
        \\    n + 1
        \\
        \\kernel: i64 = (n: i64)
        \\    a = step(n)
        \\    b = n + 2
        \\    c = n + 3
        \\    d = n + 4
        \\    i = 1
        \\    while i <= n
        \\        a = ((a ~ i) * 7) & 255
        \\        b = ((b ~ i) * 7) & 255
        \\        c = ((c ~ i) * 7) & 255
        \\        d = ((d ~ i) * 7) & 255
        \\        i += 1
        \\    a + b + c + d
        \\
        \\main: i64 = ()
        \\    kernel(5)
    ;
    var diagnostic: Diagnostic = .{};
    var output = try carriedLocalTestModule(alloc, source, &diagnostic);
    defer output.deinit(alloc);

    // The body must not have folded, or nothing below is measuring anything.
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "kernel") != null);

    // Five carried locals in a function that calls: not one of them may be
    // given a frame slot, and neither reason for taking one may fire.
    try std.testing.expectEqual(
        @as(usize, 0),
        countStackLocals(output.cost, "not carried across a loop"),
    );
    try std.testing.expectEqual(
        @as(usize, 0),
        countStackLocals(output.cost, "GP home budget exhausted"),
    );
    // The PARAMETER still takes a frame slot, and that is deliberate rather
    // than incidental — see the note at its `planSlot` call. Asserting it here
    // keeps the two halves of the rule from drifting apart silently: if
    // parameters are ever promoted, this line is where it gets noticed.
    try std.testing.expect(countStackLocals(output.cost, "parameter is not loop-carried") > 0);
    // THE ASSERTION THAT FAILS ON THE OLD BACKEND, and the reason this test is
    // a test rather than a description. `gate_spill_all_locals = body_has_call`
    // sent every local through the gate-transport branch, so a program with no
    // gate transport anywhere in it recorded six "gate transport local spilled
    // to stack frame" entries — five locals and the parameter. Verified against
    // a compiler built from this same tree with the change reverted: six here,
    // zero after.
    try std.testing.expectEqual(
        @as(usize, 0),
        countStackLocals(output.cost, "gate transport"),
    );

    // And the home has to be one a `bl` cannot reach. x19 is the first register
    // of the callee-saved bank, so the prologue saving it is the observable
    // consequence of a home being taken there; a home in x9..x17 would leave the
    // prologue empty, and a home in x0..x7 is the `bare` miscompile.
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "str x19, [sp") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "ldr x19, [sp") != null);
}

test "a local that is not carried keeps its frame slot rather than a saved register" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE OTHER DIRECTION, and it is not symmetry for its own sake. A home in
    // the callee-saved bank costs a `str` in the prologue and an `ldr` in the
    // epilogue, because the register belongs to the caller. A local assigned
    // inside a loop repays that every iteration; a local assigned once on a
    // straight line repays it never.
    //
    // MEASURED when every local was eligible: three of `gate/edge.sh`'s static
    // ledger entries regressed on instruction count and nothing else moved —
    // `LAW len/str-world` 28 -> 31, `LAW to/str` 47 -> 52, `CONTROL
    // glue/len-world` 28 -> 31, all of it prologue. Restricting homes to
    // loop-stored slots put all three back and cost nothing on any cycle row.
    const source =
        \\step: i64 = (n: i64)
        \\    n + 1
        \\
        \\kernel: i64 = (n: i64)
        \\    a = step(n)
        \\    b = a + 2
        \\    c = b + 3
        \\    a + b + c
        \\
        \\main: i64 = ()
        \\    kernel(5)
    ;
    var diagnostic: Diagnostic = .{};
    var output = try carriedLocalTestModule(alloc, source, &diagnostic);
    defer output.deinit(alloc);

    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "kernel") != null);
    // No loop, so no local earns a home, and the REASON is recorded rather than
    // inferred: an entry saying "budget exhausted" here would mean the
    // earned-home rule had stopped applying and the budget was doing the work.
    try std.testing.expect(countStackLocals(output.cost, "not carried across a loop") > 0);
    try std.testing.expectEqual(
        @as(usize, 0),
        countStackLocals(output.cost, "GP home budget exhausted"),
    );
}

test "carried locals past the home budget still go to the frame" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return error.SkipZigTest;

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // The bank is ten registers wide (x19-x28) and that is the whole budget, so
    // a loop carrying more than ten values cannot have them all in it. The
    // surplus takes the frame slot it always had — which is what makes this a
    // strict improvement rather than a trade: nothing loses a place it used to
    // have, some things gain a better one.
    const source =
        \\step: i64 = (n: i64)
        \\    n + 1
        \\
        \\kernel: i64 = (n: i64)
        \\    s = step(n)
        \\    v0 = n + 1
        \\    v1 = n + 2
        \\    v2 = n + 3
        \\    v3 = n + 4
        \\    v4 = n + 5
        \\    v5 = n + 6
        \\    v6 = n + 7
        \\    v7 = n + 8
        \\    v8 = n + 9
        \\    v9 = n + 10
        \\    v10 = n + 11
        \\    i = 1
        \\    while i <= n
        \\        v0 = (v0 + i) & 255
        \\        v1 = (v1 + i) & 255
        \\        v2 = (v2 + i) & 255
        \\        v3 = (v3 + i) & 255
        \\        v4 = (v4 + i) & 255
        \\        v5 = (v5 + i) & 255
        \\        v6 = (v6 + i) & 255
        \\        v7 = (v7 + i) & 255
        \\        v8 = (v8 + i) & 255
        \\        v9 = (v9 + i) & 255
        \\        v10 = (v10 + i) & 255
        \\        s = (s + v0) & 255
        \\        i += 1
        \\    s + v0 + v1 + v2 + v3 + v4 + v5 + v6 + v7 + v8 + v9 + v10
        \\
        \\main: i64 = ()
        \\    kernel(5)
    ;
    var diagnostic: Diagnostic = .{};
    var output = try carriedLocalTestModule(alloc, source, &diagnostic);
    defer output.deinit(alloc);

    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "kernel") != null);
    // Twelve carried values against a ten-register bank. The surplus is on the
    // frame and it is there for the BUDGET reason; if this ever reads zero,
    // either the bank grew or the plan stopped counting.
    try std.testing.expect(countStackLocals(output.cost, "GP home budget exhausted") > 0);
    // …and the bank is still fully used, so the frame is the overflow rather
    // than the default.
    try std.testing.expect(std.mem.indexOf(u8, output.asm_text, "str x28, [sp") != null);
}

/// THE CORRECTNESS OBLIGATION OF THE CONSTANT-DIVISOR SEQUENCE, DISCHARGED
/// AGAINST THE LAW ITSELF.
///
/// `@divFloor` and `@mod` are Zig's names for what
/// `//` and `%` mean, so they are the ORACLE here — not a table of expected
/// numbers a reader would have to trust, and not the emitter's own opinion.
/// `flooredMagicAnswer` models the emitted instruction sequence in the same
/// wrapping i64 the machine uses, so a disagreement here is a wrong answer
/// this backend would have shipped.
///
/// THE DIVIDEND SET IS CHOSEN, not sampled. The relation the sequence rests on
/// — `S(n) = floor(n/k) - [n < 0 AND k | n]` — has its extremes exactly at the
/// ends of the quotient range and at the ends of the remainder range, so the
/// set walks `n = q*k + r` for `q` at both extremes and `r` at both ends of
/// `[0, k)`, plus INT_MIN, INT_MAX, zero and both signs of one, plus a
/// pseudorandom spread that would catch anything the reasoning missed.
fn expectMagicAgreesWithLaw(k: i64) !void {
    const mg = Arm64Compiler.magicFlooredDivisor(k) orelse return error.NoMagic;
    const nmin: i64 = std.math.minInt(i64);
    const nmax: i64 = std.math.maxInt(i64);

    const check = struct {
        fn one(kk: i64, m: Arm64Compiler.FlooredMagic, n: i64) !void {
            try std.testing.expectEqual(@divFloor(n, kk), Arm64Compiler.flooredMagicAnswer(kk, m, n, false));
            try std.testing.expectEqual(@mod(n, kk), Arm64Compiler.flooredMagicAnswer(kk, m, n, true));
        }
    }.one;

    for ([_]i64{ nmin, nmin + 1, nmin + 2, -2, -1, 0, 1, 2, nmax - 2, nmax - 1, nmax }) |n| try check(k, mg, n);

    const qmin: i64 = @divFloor(nmin, k);
    const qmax: i64 = @divFloor(nmax, k);
    const qs = [_]i64{ qmin, qmin + 1, qmin + 2, -2, -1, 0, 1, 2, qmax - 2, qmax - 1, qmax };
    for (qs) |q| {
        if (q < qmin or q > qmax) continue;
        const base: i128 = @as(i128, q) * @as(i128, k);
        var r: i64 = 0;
        while (r < k and r < 4) : (r += 1) {
            const n: i128 = base + r;
            if (n >= nmin and n <= nmax) try check(k, mg, @intCast(n));
            const n2: i128 = base + k - 1 - r;
            if (n2 >= nmin and n2 <= nmax) try check(k, mg, @intCast(n2));
        }
    }

    var s: u64 = 0x243f6a8885a308d3 ^ @as(u64, @bitCast(k));
    var i: u32 = 0;
    while (i < 4000) : (i += 1) {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        try check(k, mg, @bitCast(s));
    }
}

test "constant divisor magic answers the floored law on every boundary dividend" {
    var k: i64 = 3;
    while (k <= 600) : (k += 1) {
        if (Arm64Compiler.powerOfTwoShift(k) != null) continue;
        try expectMagicAgreesWithLaw(k);
    }
    // The ends of the admitted range and the shapes that have historically
    // broken magic-number searches: one below and one above a power of two,
    // a divisor larger than half the dividend range, and the largest i64.
    for ([_]i64{
        3,
        7,
        9,
        10,
        100,
        1000,
        65535,
        65537,
        1000000007,
        (@as(i64, 1) << 31) - 1,
        (@as(i64, 1) << 32) + 1,
        (@as(i64, 1) << 62) - 1,
        (@as(i64, 1) << 62) + 1,
        (@as(i64, 1) << 62) + (@as(i64, 1) << 61),
        std.math.maxInt(i64) - 1,
        std.math.maxInt(i64),
    }) |k2| {
        if (Arm64Compiler.powerOfTwoShift(k2) != null) continue;
        try expectMagicAgreesWithLaw(k2);
    }
}

test "constant divisor magic is exhaustive over a dense dividend window" {
    var k: i64 = 3;
    while (k <= 40) : (k += 1) {
        if (Arm64Compiler.powerOfTwoShift(k) != null) continue;
        const mg = Arm64Compiler.magicFlooredDivisor(k).?;
        var n: i64 = -300000;
        while (n <= 300000) : (n += 1) {
            try std.testing.expectEqual(@divFloor(n, k), Arm64Compiler.flooredMagicAnswer(k, mg, n, false));
            try std.testing.expectEqual(@mod(n, k), Arm64Compiler.flooredMagicAnswer(k, mg, n, true));
        }
    }
}

test "the divisors this realization refuses keep the sdiv path" {
    // A power of two has a ONE-instruction realization and must not reach the
    // multiply; 1 and 0 and every negative divisor are outside the derivation.
    for ([_]i64{ -9223372036854775807 - 1, -1000000, -7, -2, -1, 0, 1, 2, 4, 8, 1024, (@as(i64, 1) << 62) }) |k| {
        try std.testing.expectEqual(@as(?Arm64Compiler.FlooredMagic, null), Arm64Compiler.magicFlooredDivisor(k));
    }
}

// GAP-148. THE ONLY INSTRUCTION THAT MAKES A SPILLED VALUE READABLE AGAIN.
//
// `ensureRegLiveRemap` is what `evalDnirValue` calls for a `.local` or `.temp`
// whose register has been spilled, and its result is handed back as THE register
// holding that value. Under gate transport its exhaustion path has to supply
// that register itself, and this measures that what the caller receives is the
// register the reload actually landed in. The arm reached its destination
// through `reclaimSpilledReg` when this test was written and now uses `reg`
// itself, which is why one spilled register is the whole state this needs.
//
// The compiler is built directly rather than through a source program because
// the path needs an exhausted pool AND an exhausted spill area at the same
// instant — a condition a fixture reaches only incidentally, and then stops
// reaching the next time allocation changes.
test "a gate-transport reclaim reloads the value it hands a register for" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // GATE TRANSPORT WITH NO PRE-RESERVED SPILL AREA. `spillReg` then falls to
    // its last-resort branch, which refuses outright under gate transport
    // (moving `sp` mid-body invalidates every offset the prologue handed out),
    // so every rung of the `allocRegExcluding` cascade raises
    // `RegisterExhausted` and the reclaim is the only way this call returns.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    const spilled: u5 = 10;
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, spilled, off);
    // Busy everywhere else, and the spilled register NOT `used_regs` — exactly
    // the state `spillReg` leaves behind.
    compiler.used_regs = @splat(true);
    compiler.used_regs[spilled] = false;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    const owner: u32 = 7;
    try temps.put(alloc, owner, spilled);

    const before = compiler.code.items.len;
    const live = try compiler.ensureRegLiveRemap(&temps, spilled);

    // ONE `ldr`, from this value's slot, into the register that was returned.
    // Without it the caller reads whatever the reclaimed register last held.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // …and the ownership facts that load pays for: no reload still owed, the
    // owner naming the loaded register, that register claimed, and the frame
    // slot returned to the pool now that nothing has to be read out of it.
    try std.testing.expect(!compiler.spilled_regs.contains(spilled));
    try std.testing.expectEqual(@as(?u5, live), temps.get(owner));
    try std.testing.expect(compiler.used_regs[live]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);
}

// GAP-148. A RECLAIM MAY TAKE DEAD STORAGE, NEVER A VALUE LOCATION.
//
// Built directly rather than through a source program for the same reason as
// the reload test above: the reclaim needs an exhausted pool and an exhausted
// spill area at one instant, which a fixture reaches only incidentally.
test "a gate-transport reclaim refuses an owned value and takes stale storage" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // The state `spillReg` leaves behind: the victim is out of `used_regs`, its
    // value is in a frame slot, and `gp_reg_owner` still names the value that
    // will read it back.
    const spilled: u5 = 10;
    const off: u16 = 8;
    const owner: u32 = 3;
    try compiler.spilled_regs.put(alloc, spilled, off);
    compiler.used_regs = @splat(true);
    compiler.used_regs[spilled] = false;
    compiler.gp_reg_owner[spilled] = owner;

    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(spilled));
    try std.testing.expectEqual(@as(?u32, owner), compiler.gp_reg_owner[spilled]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    compiler.gp_reg_owner[spilled] = null;
    const reg = try compiler.reclaimSpilledReg(null);
    try std.testing.expectEqual(spilled, reg);
    try std.testing.expect(compiler.used_regs[reg]);
    try std.testing.expect(!compiler.spilled_regs.contains(reg));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);
}

// GAP-148. A RELOAD PUTS THE VALUE BACK IN THE REGISTER, AND MUST PUT THE
// REGISTER BACK IN THE POOL'S BUSY SET.
//
// `spillReg` clears `used_regs[victim]` because after the store the register no
// longer holds the value. `ensureRegLive` is the exact inverse — it loads the
// value back into THAT SAME register — but it restored only the half of the
// state that stops a reload being owed. The register was left unclaimed while
// holding a live value, and it was no longer in `spilled_regs` either, so the
// one guard that had been standing in for the claim was gone too: both free
// scans in `allocRegExcluding` skip a spilled register, and neither skips this
// one. The next allocation therefore hands out a register whose value is live
// and whose owner still names it, and the two writes race with no diagnostic.
//
// Bounded to gate transport with the rest of this gap: `spillReg` is reached
// only from `allocRegExcluding`, which refuses above its spill loops unless
// `gate_transport`, so `spilled_regs` is empty everywhere else and
// `ensureRegLive` is a no-op there.
//
// Built directly rather than through a source program for the same reason as
// the two reclaim tests above: the state under test is one the allocator passes
// through, not one a fixture names.
test "a reload reclaims the register it loaded the value into" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.stack_frame_bytes = 64;

    // Exactly the state `spillReg` leaves behind: the value is in a frame slot,
    // the register is out of `used_regs`, and `gp_reg_owner` still names the
    // value that will read it back.
    const spilled: u5 = 10;
    const off: u16 = 8;
    const owner: u32 = 3;
    try compiler.spilled_regs.put(alloc, spilled, off);
    compiler.used_regs = @splat(true);
    compiler.used_regs[spilled] = false;
    compiler.gp_reg_owner[spilled] = owner;

    const before = compiler.code.items.len;
    try compiler.ensureRegLive(spilled);

    // One `ldr`, from this value's slot, into the register it was spilled from.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, spilled);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );
    try std.testing.expect(!compiler.spilled_regs.contains(spilled));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // THE REGISTER IS BUSY AGAIN. Every other register here is claimed, so an
    // allocation that reads this one as free returns exactly it, and the value
    // the `ldr` above just loaded is overwritten by its second owner. With the
    // claim restored the pool has nothing to give and says so, which is the
    // answer: refusing is a bail, allocating is a wrong result.
    try std.testing.expect(compiler.used_regs[spilled]);
    try std.testing.expectError(error.RegisterExhausted, compiler.allocRegExcluding(null));

    // …and it is not busy forever. The claim is released by the same sweep that
    // would have released it had the register never spilled, off the owner
    // record `spillReg` preserved across the store.
    compiler.sweepGpLive(1);
    try std.testing.expect(!compiler.used_regs[spilled]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[spilled]);
}

// GAP-148. A VALUE THAT CHANGES REGISTERS TAKES ITS OWNER RECORD WITH IT.
//
// `ensureRegLiveRemap` moves a spilled value into a DIFFERENT register and
// rewrites every temp that named the old one — the same relocation
// `preserveArgReg` performs, which finishes by writing `gp_reg_owner[fresh]`
// for exactly this reason. This one wrote neither end, and each end is a defect
// in the opposite direction:
//
//   - `gp_reg_owner[reg]` still named the value, which no longer lives there.
//     `spillReg` left the register out of `used_regs` and the reload removed its
//     `spilled_regs` entry, so both free scans in `allocRegExcluding` now hand
//     it out — and then `sweepGpLive`, reading the stale owner, frees it again
//     under the value it was just given. Two owners, one register, no
//     diagnostic: the shape this gap is open on.
//   - `gp_reg_owner[fresh]` stayed null for a register a live value now
//     occupies. `sweepGpLive` skips an unowned register, so nothing ever
//     reclaims it, and the pool shrinks by one on the one path whose whole job
//     is to relieve register pressure. `preserveArgReg` names the same failure
//     from the other side — owner null there ran `tree.id` out of registers.
//
// Built directly rather than through a source program for the same reason as
// the reclaim and reload tests above: the state under test is one the allocator
// passes through, not one a fixture names.
test "a remapped reload moves the owner to the register it loaded into" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.stack_frame_bytes = 64;

    // Exactly the state `spillReg` leaves behind, plus one free register for the
    // reload to land in, so the remap arm runs rather than the reclaim arm.
    const spilled: u5 = 10;
    const free: u5 = 11;
    const off: u16 = 8;
    const owner: u32 = 3;
    try compiler.spilled_regs.put(alloc, spilled, off);
    compiler.used_regs = @splat(true);
    compiler.used_regs[spilled] = false;
    compiler.used_regs[free] = false;
    compiler.gp_reg_owner[spilled] = owner;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    try temps.put(alloc, owner, spilled);

    const fresh = try compiler.ensureRegLiveRemap(&temps, spilled);
    try std.testing.expectEqual(free, fresh);
    try std.testing.expectEqual(free, temps.get(owner).?);
    try std.testing.expect(!compiler.spilled_regs.contains(spilled));

    // THE OWNER IS WHERE THE VALUE IS, AND NOWHERE ELSE.
    try std.testing.expectEqual(@as(?u32, owner), compiler.gp_reg_owner[fresh]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[spilled]);

    // The vacated register is allocatable again, and it is the next one the pool
    // reaches. `owner` is absent from `value_free_at`, which the sweep reads as
    // dead at every index — the ordinary state of an owner whose reads are
    // behind emission — so a stale record on this register frees it under the
    // value the allocation just handed it to.
    const reused = try compiler.allocRegExcluding(null);
    try std.testing.expectEqual(spilled, reused);
    compiler.sweepGpLive(1);
    try std.testing.expect(compiler.used_regs[reused]);

    // …and the register the value MOVED to is reclaimed by that same sweep, off
    // the owner record that travelled with it. Without the record it is claimed
    // for the rest of the function and the pool is one register smaller.
    try std.testing.expect(!compiler.used_regs[fresh]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[fresh]);
}

// GAP-148. A RELOAD DOES NOT HAVE TO SPEND ANOTHER VALUE TO GET A REGISTER.
//
// The exhaustion arm of `ensureRegLiveRemap` needs one register to load a
// spilled value into. It used to take one from `reclaimSpilledReg`, which frees
// a register by dropping the `spilled_regs` entry that would have reloaded it —
// the only thing that could still read that value out of the frame. So a read
// of one spilled value destroyed another, chosen by hash order.
//
// It never had to. `reg` is itself spilled, and its entry is the one this
// function drops anyway, because its value is the value being loaded out. Both
// choices free exactly one register; only one of them abandons a value.
//
// Built directly rather than through a source program for the same reason as
// the reclaim, reload, and remap tests above: the arm needs an exhausted pool
// AND an exhausted spill area at one instant, which a fixture reaches only
// incidentally and stops reaching the next time allocation changes.
test "a reload under exhaustion abandons no other spilled value" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // GATE TRANSPORT WITH NO PRE-RESERVED SPILL AREA, so `spillReg` refuses at
    // its last-resort branch and every rung of the `allocRegExcluding` cascade
    // raises `RegisterExhausted` — the exhaustion arm is the only way this call
    // returns.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // TWO spilled values, exactly the state `spillReg` leaves behind for each:
    // an entry, `used_regs` cleared, and the owner record deliberately kept.
    const a: u5 = 10;
    const b: u5 = 11;
    const off_a: u16 = 8;
    const off_b: u16 = 16;
    const owner_a: u32 = 3;
    const owner_b: u32 = 4;
    try compiler.spilled_regs.put(alloc, a, off_a);
    try compiler.spilled_regs.put(alloc, b, off_b);
    compiler.used_regs = @splat(true);
    compiler.used_regs[a] = false;
    compiler.used_regs[b] = false;
    compiler.gp_reg_owner[a] = owner_a;
    compiler.gp_reg_owner[b] = owner_b;

    // READ THE VALUE THE RECLAIM WOULD NOT HAVE TAKEN. `reclaimSpilledReg`
    // returns the first entry this same iteration order reaches, so making the
    // read target the OTHER one is what forces the old arm to abandon somebody
    // rather than to pick the register it was already emptying.
    var it = compiler.spilled_regs.iterator();
    const bystander = it.next().?.key_ptr.*;
    const target: u5 = if (bystander == a) b else a;
    const target_off: u16 = if (target == a) off_a else off_b;
    const target_owner: u32 = if (target == a) owner_a else owner_b;
    const bystander_off: u16 = if (bystander == a) off_a else off_b;
    const bystander_owner: u32 = if (bystander == a) owner_a else owner_b;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, target_owner, target);

    const before = compiler.code.items.len;
    const live = try compiler.ensureRegLiveRemap(&temps, target);

    // THE OTHER VALUE IS UNTOUCHED, WHICH IS THE WHOLE FACT. Its entry is the
    // only thing that can move it out of the frame again, its owner still names
    // the register that entry reloads, and its slot is not in the free pool
    // where a later spill would store a second live value over it.
    try std.testing.expectEqual(@as(?u16, bystander_off), compiler.spilled_regs.get(bystander));
    try std.testing.expectEqual(@as(?u32, bystander_owner), compiler.gp_reg_owner[bystander]);

    // …and the read itself is complete: one `ldr` from this value's slot into
    // the register that was returned, which is this value's own register.
    try std.testing.expectEqual(target, live);
    const reload_off: u16 = compiler.stack_frame_bytes - target_off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );
    try std.testing.expect(!compiler.spilled_regs.contains(target));
    try std.testing.expectEqual(@as(?u5, target), temps.get(target_owner));

    // THE LOADED REGISTER IS CLAIMED AND STILL OWNED. The reclaim nulled the
    // owner of whatever it returned, so reaching this register through it left
    // a live value under a null owner and `sweepGpLive` skips one of those
    // forever. Here the record `spillReg` preserved across the store is the
    // record the sweep releases, at the same index it always would have.
    try std.testing.expect(compiler.used_regs[live]);
    try std.testing.expectEqual(@as(?u32, target_owner), compiler.gp_reg_owner[live]);

    // ONE slot released, this value's, by the one removal that took its entry.
    // The bystander's slot is still reserved to the bystander.
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(target_off, compiler.free_spill_slots.items[0]);

    // The sweep releases the loaded register off that preserved owner record,
    // so the pool does not shrink by one on the path whose whole job is to
    // relieve register pressure.
    compiler.sweepGpLive(1);
    try std.testing.expect(!compiler.used_regs[live]);
}

// GAP-148. THE ONE REGISTER THE ALLOCATION SAID NOT TO TOUCH.
//
// `allocRegExcluding(exclude)` makes exactly one promise, and every path in it
// keeps that promise but the last. Both free scans skip `exclude`; all three
// spill passes skip `exclude`, which is also why this call can never be what
// puts `exclude` into `spilled_regs`. Then the bottom hands the whole decision
// to `reclaimSpilledReg`, which took no `exclude` at all and iterated the map
// in hash order — so when `exclude` was already spilled when the call arrived,
// the caller could be handed back the register it had just named as holding a
// value it was still using.
//
// The exclusion is not a preference. `emitBinopFlooredConstDivisor` states the
// reason at its own call: `dst` is claimed by the caller and a plain `allocReg`
// could spill it, leaving `dst` mapped to a slot holding the value it had
// BEFORE the sequence. The reclaim is worse than that spill, because it drops
// the `spilled_regs` entry as well: the caller's value is abandoned in the
// frame with nothing able to read it back, the caller writes its second value
// into the same register, and both reads are wrong with no diagnostic.
//
// The excluded register has to have been spilled BEFORE the call, and those
// windows are ordinary. `emitIfConverted` reads the binding into `old`, then
// evaluates both operands — each of which allocates, and can therefore spill
// `old` — before asking for `allocRegExcluding(old)`. `emitIfConvertedTwoSided`
// holds the then-arm's `rt` across the whole else arm and then asks for
// `allocRegExcluding(rt)`.
//
// Built directly rather than through a source program for the same reason as
// the reclaim, reload, and remap tests above: this needs the exact state the
// spill cascade leaves at the bottom of `allocRegExcluding` — nothing claimed,
// because everything allocatable is already spilled — which a fixture reaches
// only incidentally.
test "a gate-transport reclaim refuses the register the allocation excluded" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 256;

    // The state the recursion arrives in: every allocatable register spilled,
    // so both free scans skip every register, and all three spill passes fall
    // through on `!used_regs[victim]` — `spillReg` cleared each one as it went.
    // Only the reclaim at the bottom is left.
    var reg: u5 = 0;
    while (reg < 29) : (reg += 1) {
        if (reg == Arm64Compiler.platform_reserved_reg) continue;
        try compiler.spilled_regs.put(alloc, reg, @as(u16, reg) * 8);
        compiler.gp_reg_owner[reg] = @as(u32, reg) + 100;
    }

    // EXCLUDE THE ONE THE RECLAIM WOULD OTHERWISE TAKE. Its choice is the map's
    // iteration order, so reading that order here is what makes this the
    // excluded register rather than one of twenty-seven others.
    var it = compiler.spilled_regs.iterator();
    const held: u5 = it.next().?.key_ptr.*;
    const held_off = compiler.spilled_regs.get(held).?;
    const held_owner = compiler.gp_reg_owner[held].?;
    var stale: u5 = 0;
    var stale_it = compiler.spilled_regs.keyIterator();
    while (stale_it.next()) |candidate| {
        if (candidate.* != held) {
            stale = candidate.*;
            break;
        }
    }
    compiler.gp_reg_owner[stale] = null;

    const got = try compiler.allocRegExcluding(held);

    // THE PROMISE. Whatever came back, it is not the register the caller named
    // as still holding a value, and it is a register the caller may write.
    try std.testing.expect(got != held);
    try std.testing.expectEqual(stale, got);
    try std.testing.expect(compiler.used_regs[got]);
    try std.testing.expect(!compiler.spilled_regs.contains(got));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[got]);

    // …and the excluded register keeps all three of the records a reclaim
    // clears: its value is still in the frame, its entry is still the only
    // thing that can read it back, and its owner still names it. The slot it
    // occupies is not in the free pool for a later spill to store over.
    try std.testing.expectEqual(@as(?u16, held_off), compiler.spilled_regs.get(held));
    try std.testing.expectEqual(@as(?u32, held_owner), compiler.gp_reg_owner[held]);
    try std.testing.expect(!compiler.used_regs[held]);
    for (compiler.free_spill_slots.items) |slot| try std.testing.expect(slot != held_off);
}

// GAP-148. THE RELEASE DROPPED THE ENTRY AND KEPT THE SLOT.
//
// Four paths take a register out of `spilled_regs`, and taking the entry out is
// what makes the frame slot behind it unreadable: `ensureRegLive` and
// `ensureRegLiveRemap` are its only readers and both key on the entry. Three of
// the four hand the slot back to `free_spill_slots` on exactly that removal —
// the two reloads, and `sweepGpLive`. `releaseReg` was the fourth and kept it,
// so a slot nothing could ever read again stayed reserved for the rest of the
// function, `spillReg` stepped `gate_spill_cursor` past it toward
// `gate_spill_end`, and the refusal that follows is a spill the pre-reserved
// area still had room for.
//
// Built directly rather than through a source program for the same reason as
// the reclaim, reload, and remap tests above: this is a state the allocator
// passes through between a spill and the release of the scratch that was
// spilled, not a state a fixture names.
test "a released scratch register returns the frame slot it kept" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill loops otherwise, so `spilled_regs` is empty everywhere else and
    // this whole body is the `used_regs` clear alone.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // The state `spillReg` leaves behind for a SCRATCH register — the value is
    // in a frame slot, the register is out of `used_regs`, and no owner record
    // names it, which is the ordinary state of a register `allocReg` handed out
    // for one instruction's operand.
    const scratch: u5 = 10;
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, scratch, off);
    compiler.used_regs[scratch] = false;

    // An OWNED spilled register beside it. `releaseReg` returns above every
    // record it holds, so the fix must not reach this one: its value is still
    // owed a reload.
    const owned: u5 = 11;
    const owned_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, owned, owned_off);
    compiler.gp_reg_owner[owned] = 7;

    const before = compiler.code.items.len;
    compiler.releaseReg(scratch);

    // A release emits nothing; it moves records only.
    try std.testing.expectEqual(before, compiler.code.items.len);

    // The entry is gone — that part was already true, and it is what makes the
    // slot dead — and the slot is back in the pool for the next spill.
    try std.testing.expect(!compiler.spilled_regs.contains(scratch));
    try std.testing.expect(!compiler.used_regs[scratch]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // ONCE, NOT ONCE PER CALL. The emit paths release the same register more
    // than once — `releaseReg(addr)` beside `releaseReg(base)` where the two
    // resolved to one register — and a slot in `free_spill_slots` twice is two
    // later spills storing two live values at one offset. The removal is
    // idempotent; the release is not, so the release belongs to the removal
    // that actually took the entry.
    compiler.releaseReg(scratch);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);

    // The owned neighbour is untouched: entry, owner, and unreleased slot.
    compiler.releaseReg(owned);
    try std.testing.expectEqual(@as(?u16, owned_off), compiler.spilled_regs.get(owned));
    try std.testing.expectEqual(@as(?u32, 7), compiler.gp_reg_owner[owned]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
}

// GAP-148. A SPILLED HOME MOVED, AND THE PIN THAT NAMES IT DID NOT.
//
// `evalDnirValue` reads a local through `pinned` FIRST and `temps` second.
// `ensureRegLiveRemap` rewrites `temps` and cannot reach `pinned` — it is not
// handed the map — nor `imm_hoist`, which names a hoisted immediate's register
// the same way. So relocating a home's value to a fresh register left both of
// those naming the register the value LEFT, and that register is free after the
// move: the pool hands it to the next allocation and the next read of the local
// answers with whatever landed there.
//
// `gp_call_home_regs` documents this failure and its measurement — `sha.id`
// answered 0 instead of 16, `native.id` fell from 210 agreements to 128 — and
// buys the CALLING function out of it by refusing to spill a callee-bank home,
// which costs nothing because `probeFunctionPlan` steps its ladder down. It says
// in the same breath that a LEAF's home is still a spill victim and carries the
// hazard unrepaired, because a leaf has no ladder and taking its victims away
// would refuse programs that compile today. The second spill pass in
// `allocRegExcluding` skips only `gp_call_home_regs`, and a leaf sets no bit
// there, so a leaf home is reached whenever pressure walks x28 down past the
// unhomed registers.
//
// The repair takes no victim away: the home still spills, and it comes back to
// the register every map already names. Built directly rather than through a
// source program for the same reason as the reclaim, reload, remap, and release
// tests above — this is a state the allocator passes through between a spill and
// the next read of the local, not a state a fixture names.
test "a spilled local home reloads into the register its pin still names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its three spill passes otherwise, so `spilled_regs` is empty everywhere
    // else and no home is ever a victim.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // A LEAF's home, in the callee bank but with no `gp_call_home_regs` bit,
    // which is exactly what `allocHomeReg` leaves behind when the function does
    // not call. `markGpHome` is the producer of the rest of that state.
    const home: u5 = 20;
    compiler.markGpHome(home);
    try std.testing.expect(compiler.gp_home_regs[home]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[home]);
    try std.testing.expectEqual(@as(u32, 0), compiler.gp_call_home_regs & (@as(u32, 1) << home));

    // The state `spillReg` leaves behind: the value is in a frame slot, the
    // entry reserves the register to it, and `used_regs` is clear.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, home, off);
    compiler.used_regs[home] = false;

    // The three maps that name this home. `pinned` is the one `evalDnirValue`
    // consults first and the one this function cannot rewrite.
    const slot: u32 = 3;
    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, slot, home);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    try pinned.put(alloc, slot, home);
    compiler.eval_pinned = &pinned;

    const before = compiler.code.items.len;
    const live = try compiler.ensureRegLiveRemap(&temps, home);

    // THE READ ANSWERS THE REGISTER THE PIN NAMES. This is the whole fact: a
    // fresh register here and the pin is stale for every later read of `slot`.
    try std.testing.expectEqual(home, live);
    try std.testing.expectEqual(@as(?u5, live), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, live), temps.get(slot));

    // One `ldr` from this value's slot into that same register.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // The home survives the round trip intact: still a home, claimed again by
    // the reload, entry gone, and its slot back in the pool exactly once.
    try std.testing.expect(compiler.gp_home_regs[live]);
    try std.testing.expect(compiler.used_regs[live]);
    try std.testing.expect(!compiler.spilled_regs.contains(home));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // NOTHING ELSE WAS TAKEN. Reloading into the home costs the pool no
    // register, so the scratch the relocation would have consumed is still
    // free — `allocRegExcluding` scans x9 upward and x9 is where it would have
    // gone.
    try std.testing.expect(!compiler.used_regs[9]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[9]);

    // AND THE READ IS REPEATABLE. The second read finds no entry and answers
    // the same register without emitting or releasing anything, which is what a
    // home read looks like when the home was never spilled at all.
    const again = try compiler.ensureRegLiveRemap(&temps, home);
    try std.testing.expectEqual(home, again);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
}

// GAP-148. THE ONE PINNED REGISTER THAT WAS NEVER A HOME.
//
// The test above repaired the pin/remap face for a HOME, and `gp_home_regs` is
// what it asked. That flag is the same set as "pinned" at five of the six
// `pinned.put` sites, each of which calls `markGpHome` first. The sixth is a
// LEAF's parameter: `compileDnirFunction` keeps an incoming argument in its own
// x0..x7 register, claims it, writes `temps` and `pinned`, and marks no home
// because there is none to mark. The bit stays clear until a store to that slot
// sets it, so a parameter that is only ever READ is pinned and is not a home
// for its whole life.
//
// It is a spill victim there: the third pass in `allocRegExcluding` walks x7..x0
// and takes any `used_regs` register that is neither `exclude` nor a staged
// argument, and a parameter at rest is neither. The remap then relocated it,
// rewrote `temps`, and left `pinned` — the map `evalDnirValue` reads FIRST —
// naming a register the move vacated: `spillReg` had cleared `used_regs` and the
// remap removed the `spilled_regs` entry, so both free scans hand it out and the
// next read of the parameter answers whatever landed there. The same wrong
// answer `gp_call_home_regs` measured for a home, reached through the one pinned
// register its flag does not cover.
//
// Built directly rather than through a source program for the same reason as the
// reclaim, reload, remap, release, home, unwind, hoist, store, spill-band,
// call-result, argument-preserve and pack-result tests around it — this is a
// state the allocator passes through between a spill of a parameter register and
// the next read of that parameter, not a state a fixture names.
test "a spilled parameter that is pinned and not a home reloads into its own register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its three spill passes otherwise, so `spilled_regs` is empty everywhere
    // else and this read is the map lookup it always was.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // What the leaf-parameter arm of `compileDnirFunction` leaves behind: the
    // incoming register claimed, both maps naming it, AND NO HOME FLAG. That
    // last fact is the whole difference from the home test above.
    const arg_reg: u5 = 0;
    const slot: u32 = 0;
    compiler.claimReg(arg_reg);
    try std.testing.expect(!compiler.gp_home_regs[arg_reg]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[arg_reg]);

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, slot, arg_reg);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    try pinned.put(alloc, slot, arg_reg);
    compiler.eval_pinned = &pinned;

    // And what the third spill pass leaves behind: the value in a frame slot,
    // the entry reserving the register to it, `used_regs` clear.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, arg_reg, off);
    compiler.used_regs[arg_reg] = false;

    // The read that reaches the remap, through the map it cannot rewrite.
    const before = compiler.code.items.len;
    const live = try compiler.evalDnirValue(&temps, .{ .local = slot });

    // THE READ ANSWERS THE REGISTER THE PIN NAMES. A fresh register here and
    // the pin is stale for every later read of this parameter.
    try std.testing.expectEqual(arg_reg, live);
    try std.testing.expectEqual(@as(?u5, live), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, live), temps.get(slot));

    // One `ldr` from this parameter's slot back into that same register.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // The claim is back — the half of `spillReg` the store did not perform —
    // the entry is gone, and its slot went back exactly once, on the removal
    // that took it.
    try std.testing.expect(compiler.used_regs[live]);
    try std.testing.expect(!compiler.spilled_regs.contains(arg_reg));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // AND IT IS STILL NOT A HOME. The reload does not mint one; the pin alone
    // is what made the register the destination.
    try std.testing.expect(!compiler.gp_home_regs[live]);

    // NOTHING ELSE WAS TAKEN. Reloading into the pinned register costs the pool
    // no register, so the scratch the relocation would have consumed is still
    // free — `allocRegExcluding` scans x9 upward and x9 is where it would have
    // gone.
    try std.testing.expect(!compiler.used_regs[9]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[9]);

    // AND THE READ IS REPEATABLE. The second read finds no entry, emits
    // nothing, and releases nothing, which is what reading a parameter that was
    // never spilled has always looked like.
    const again = try compiler.evalDnirValue(&temps, .{ .local = slot });
    try std.testing.expectEqual(arg_reg, again);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);

    // AN UNPINNED TEMP IS UNTOUCHED BY THIS TERM AND STILL RELOCATES. The pin
    // is the fact, not the spill: no map this function cannot reach names x10,
    // so the remap is free to move its value and rewrite the one map that does.
    const other: u5 = 10;
    const other_slot: u32 = 7;
    const other_off: u16 = 24;
    compiler.claimReg(other);
    try temps.put(alloc, other_slot, other);
    try compiler.spilled_regs.put(alloc, other, other_off);
    compiler.used_regs[other] = false;

    const moved = try compiler.ensureRegLiveRemap(&temps, other);
    try std.testing.expect(moved != other);
    try std.testing.expectEqual(@as(?u5, moved), temps.get(other_slot));
    try std.testing.expect(!compiler.spilled_regs.contains(other));
}

// GAP-148. THE RECLAIM TOOK A HOME, AND NOTHING CAN GIVE A HOME BACK.
//
// `reclaimSpilledReg` frees a register by dropping the `spilled_regs` entry
// that would have reloaded it. For a temp that abandons the temp's value, which
// is this gap's documented and still-open hazard. For a HOME it is worse in a
// second, independent direction, and that direction is what this test names.
//
// `markGpHome` sets `gp_home_regs[reg]` and that bit is never cleared for the
// rest of the function — `sweepGpLive` skips a home, `releaseReg` returns above
// one, and only the hoist unwind or the per-function reset clears the array. So
// the register the reclaim hands out arrives already flagged as somebody's home:
// no release path will ever take it back, the pool shrinks by one for the rest
// of the function, and `ensureRegLiveRemap` refuses to write `gp_reg_owner` for
// a home destination, so a value later relocated into it lives under a null
// owner that `sweepGpLive` also skips. All of that on the one path whose entire
// job is to relieve register pressure.
//
// Reached in a LEAF. The second spill pass in `allocRegExcluding` skips only
// `gp_call_home_regs`, and a leaf sets no bit there, so pressure walking x28
// down spills leaf homes into `spilled_regs` — and the reclaim below the passes
// then iterates that map in hash order with no home check at all.
//
// Skipping a home costs the reclaim one candidate, which is the argument the
// `exclude` skip in the same function already makes; when a home is genuinely
// the only entry, the refusal is the bail this function already ends with, and a
// refusal is a bail while the alternative is a wrong answer. Not the closure —
// closure is authoritative `register`/`frame` assignment before emission, per
// this gap's record, under which a home's location is carried by the assignment
// and is not a register the reclaim can bid for.
test "the spilled-register reclaim passes over a home and takes a temp" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport, and so does this reclaim:
    // `allocRegExcluding` refuses above its three spill passes otherwise.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // A LEAF's home — in the callee bank, with no `gp_call_home_regs` bit, which
    // is what the second spill pass needs to reach it as a victim.
    const home: u5 = 20;
    compiler.markGpHome(home);
    try std.testing.expectEqual(@as(u32, 0), compiler.gp_call_home_regs & (@as(u32, 1) << home));

    // The state `spillReg` leaves behind for that home.
    const home_off: u16 = 8;
    try compiler.spilled_regs.put(alloc, home, home_off);
    compiler.used_regs[home] = false;

    // A HOME ALONE IS NOT A CANDIDATE. The map is non-empty and every entry in
    // it is a home, so the answer is the refusal, not the home.
    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));

    // And the home is exactly as it was: the entry that reloads it still there,
    // still a home, still unclaimed, and its slot NOT in the free pool — a
    // released slot is a second value stored over this one.
    try std.testing.expectEqual(@as(?u16, home_off), compiler.spilled_regs.get(home));
    try std.testing.expect(compiler.gp_home_regs[home]);
    try std.testing.expect(!compiler.used_regs[home]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // Now an ownerless stale spill beside it. It is dead storage rather than a
    // value location, so it is the entry the reclaim may reach.
    const temp: u5 = 21;
    const temp_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, temp, temp_off);
    compiler.used_regs[temp] = false;

    const got = try compiler.reclaimSpilledReg(null);
    try std.testing.expectEqual(temp, got);

    // The stale entry is dropped, its slot returned, and its register claimed.
    try std.testing.expect(!compiler.spilled_regs.contains(temp));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[temp]);
    try std.testing.expect(compiler.used_regs[temp]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(temp_off, compiler.free_spill_slots.items[0]);

    // THE HOME IS STILL WHOLE, which is the whole point: its reload survives a
    // reclaim that happened beside it.
    try std.testing.expectEqual(@as(?u16, home_off), compiler.spilled_regs.get(home));
    try std.testing.expect(compiler.gp_home_regs[home]);
    try std.testing.expect(!compiler.used_regs[home]);

    // A reclaim emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. THE RECLAIM BID FOR A REGISTER THE CALL HAD ALREADY BEEN GIVEN.
//
// `pending_arg_regs` is the marshaling's statement that x_k holds an argument
// for the `bl` it is building. `allocRegExcluding` asks it twice — in the
// x0..x7 free scan and in the x7..x0 spill pass, where the comment reads "a
// staged argument register is not a spill candidate: its live value belongs to
// the call being marshaled, not to a temp we can park" — and then falls into
// `reclaimSpilledReg` without asking a third time.
//
// The entry that puts a staged register in reach is one the marshaling left
// stale. `mov_arg` writes the argument into `slot` with `emitMovImm`,
// `emitAdrpAdd` or `emitMovReg`, and none of them touches `spilled_regs`;
// `preserveArgReg` is what empties `slot` first, and it moves only for an id
// that is still LIVE, so a `slot` named nothing but stale ids keeps an entry
// describing a frame copy the register no longer holds. The reclaim then took
// it: entry dropped, register claimed and handed back as scratch, the caller's
// first write over the staged argument, and the call made with it. A wrong
// argument with no diagnostic, on the one register the marshaling had already
// declared spoken for.
//
// Built directly, like every test this gap has recorded: the state is one the
// allocator passes through between a stale spill and the next operand
// evaluation under pressure, not one a fixture names.
test "the spilled-register reclaim passes over a staged argument register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport, and so does this reclaim:
    // `allocRegExcluding` refuses above its three spill passes otherwise.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // The state the cascade leaves for a spilled x2, from before the staging.
    const staged: u5 = 2;
    const staged_off: u16 = 8;
    try compiler.spilled_regs.put(alloc, staged, staged_off);
    compiler.used_regs[staged] = false;

    // And the marshaling's statement, which `mov_arg` makes right after writing
    // the argument into x2 and which nothing removes until `emitBl`.
    compiler.markStagedArgReg(staged);
    try std.testing.expect(compiler.pending_arg_regs & (@as(u8, 1) << 2) != 0);

    // A STAGED REGISTER ALONE IS NOT A CANDIDATE. The map is non-empty and its
    // only entry names a register this call has already been given, so the
    // answer is the refusal, not the argument.
    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));

    // And x2 is exactly as it was: still staged, still unclaimed, its entry
    // still there — dropping it is what hands the register out — and its slot
    // NOT in the free pool, since a released slot is a second value stored over
    // this one.
    try std.testing.expectEqual(@as(?u16, staged_off), compiler.spilled_regs.get(staged));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[staged]);
    try std.testing.expect(!compiler.used_regs[staged]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // An ownerless stale spill beside it remains reclaimable whichever entry
    // the map's iteration order offers first.
    const temp: u5 = 21;
    const temp_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, temp, temp_off);
    compiler.used_regs[temp] = false;

    try std.testing.expectEqual(temp, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(temp));
    try std.testing.expect(compiler.used_regs[temp]);

    // THE STAGED ARGUMENT IS STILL WHOLE, which is the whole point: it survives
    // a reclaim that happened beside it.
    try std.testing.expectEqual(@as(?u16, staged_off), compiler.spilled_regs.get(staged));
    try std.testing.expect(!compiler.used_regs[staged]);

    // THE SKIP IS THE STAGING FACT AND NOTHING ELSE. `emitBl` clears
    // `pending_arg_regs`, and after it the same entry in the same state is the
    // ownerless stale entry the reclaim may take — so this is one term, not a
    // register the reclaim can no longer reach.
    compiler.pending_arg_regs = 0;
    try std.testing.expectEqual(staged, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(staged));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[staged]);
    try std.testing.expect(compiler.used_regs[staged]);

    // A reclaim emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. THE RECLAIM BID FOR A REGISTER THE VARIADIC TAIL HAD ALREADY BEEN
// GIVEN.
//
// Apple's ARM64 ABI passes a variadic tail in MEMORY, so those arguments never
// reach x0..x7 and `pending_arg_regs` — eight bits describing exactly those
// eight registers — cannot state the reservation for them.
// `materializePendingVarargs` evaluates each one into an ordinary allocatable
// register, records it in `pending_varargs[i].reg`, and `emitPushVarargs`
// stores the lot to [sp, #i*8] after the save. Between the two the register
// holds an argument for the `bl` being built.
//
// The window is that loop's own: slot 0's register is staged while slot 1's
// operand is evaluated, and evaluation allocates. Both free scans in
// `allocRegExcluding` pass over the register, but only because `used_regs`
// names it — and `used_regs` is precisely what the cascade's spill passes take.
// After `spillReg` the claim is gone and the entry is in `spilled_regs`, where
// the reclaim took it: entry dropped, owner nulled, `claimReg`, handed back as
// scratch. The caller's first write lands on the staged argument and
// `emitPushVarargs` stores that write into the callee's memory-argument slot.
//
// A spill ALONE does not clobber it — both free scans skip anything
// `spilled_regs` contains, so the bytes survive and the push happens to store
// the right ones. The reclaim is the one arm that makes it wrong, and it is the
// arm no reservation had ever been stated to.
//
// Built directly, like every test this gap has recorded: this is a state the
// allocator passes through between a stale spill and the next tail operand
// under pressure, not one a fixture names.
test "the spilled-register reclaim passes over a staged variadic tail register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport, and so does this reclaim:
    // `allocRegExcluding` refuses above its three spill passes otherwise.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // Tail slot 0 materialized into x21, and the allocation for a later slot
    // spilled it — the claim dropped, the value in the frame, the entry here.
    const staged: u5 = 21;
    const staged_off: u16 = 8;
    compiler.pending_varargs[0] = .{ .reg = staged, .staged = true, .scratch = true };
    compiler.pending_vararg_count = 1;
    try compiler.spilled_regs.put(alloc, staged, staged_off);
    compiler.used_regs[staged] = false;

    // A STAGED TAIL REGISTER ALONE IS NOT A CANDIDATE. The map is non-empty and
    // its only entry names a register this call has already been given, so the
    // answer is the refusal, not the argument.
    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));

    // And x21 is exactly as it was: entry, owner, claim and frame slot all
    // untouched — dropping the entry is what hands the register out, and
    // releasing the slot is what stores a second value over this one.
    try std.testing.expectEqual(@as(?u16, staged_off), compiler.spilled_regs.get(staged));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[staged]);
    try std.testing.expect(!compiler.used_regs[staged]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // An ownerless stale spill beside it remains reclaimable whichever entry
    // the map's iteration order offers first.
    const temp: u5 = 22;
    try compiler.spilled_regs.put(alloc, temp, 24);
    compiler.used_regs[temp] = false;

    try std.testing.expectEqual(temp, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(temp));
    try std.testing.expect(compiler.used_regs[temp]);

    // THE STAGED TAIL ARGUMENT IS STILL WHOLE, which is the whole point: it
    // survives a reclaim that happened beside it.
    try std.testing.expectEqual(@as(?u16, staged_off), compiler.spilled_regs.get(staged));
    try std.testing.expect(!compiler.used_regs[staged]);

    // A HOLE IS NOT A RESERVATION. A slot inside `pending_vararg_count` that no
    // `mov_arg` wrote is `.{}` — operand null, `reg` 0 — so reading the cleared
    // operand as "materialized" would reserve x0 for nothing. `staged` is the
    // fact, and an ownerless stale x0 beside a hole is still reclaimable.
    compiler.pending_varargs[1] = .{};
    compiler.pending_vararg_count = 2;
    try compiler.spilled_regs.put(alloc, 0, 40);
    compiler.used_regs[0] = false;
    try std.testing.expectEqual(@as(u5, 0), try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(0));

    // THE SKIP IS THE STAGING FACT AND NOTHING ELSE. `emitPopVarargs` clears
    // the tail, and after it the same entry in the same state is ownerless stale
    // storage the reclaim may take — so this is one term, not a register
    // the reclaim can no longer reach.
    compiler.pending_varargs[0] = .{};
    compiler.pending_vararg_count = 0;
    try std.testing.expectEqual(staged, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(staged));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[staged]);
    try std.testing.expect(compiler.used_regs[staged]);

    // A reclaim emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. THE RELOCATION MOVED A VALUE OUT OF A REGISTER THE VARIADIC TAIL
// HAD ALREADY BEEN GIVEN.
//
// `pending_varargs[i].reg` is the fourth map that names a register, beside
// `pinned`, `temps` and `imm_hoist`, and it names one for the same reason
// `pending_arg_regs` names x_k: between `materializePendingVarargs` and
// `emitPushVarargs` the register holds an argument for the `bl` being built.
// The section above taught `reclaimSpilledReg` that reservation.
// `ensureRegLiveRemap` is the OTHER path that takes a register away from the
// map naming it, and it had never been asked.
//
// The window is the materialization's own loop. Slot i is staged while slot j's
// operand is evaluated; that evaluation allocates, the cascade spills slot i's
// register — the spill passes read `used_regs`, which is all a staged tail
// register has — and if slot j's operand is a value that LIVES in that
// register, `evalDnirValue` arrives here for it. The relocation rewrites
// `temps`, which names it, and leaves `pending_varargs[i].reg`, which names it
// too and which nothing in that function reaches. `emitPushVarargs` then reads
// that field and stores the vacated register into the callee's memory-argument
// slot — vacated because `spillReg` cleared `used_regs` and the remap drops the
// entry both free scans were skipping, so the pool hands it out. A wrong
// variadic argument with no diagnostic.
//
// The repair costs the pool nothing, which is weaker than the trade the home
// and pin branches make: a relocation is net zero in registers, so reloading
// into the register the staging names gives up no register the move would have
// produced.
//
// Built directly, like every test this gap has recorded: this is a state the
// allocator passes through between a stale spill and the next read of a staged
// tail operand, not one a fixture names.
test "a spilled variadic tail register reloads into the register its staging names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its three spill passes otherwise, so `spilled_regs` is empty everywhere
    // else and this function returns above the branch under test.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // Tail slot 0 materialized a `.temp` into x21 — `owned`, so the slot is not
    // `scratch` and `temps` names the same register the staging does. Then the
    // allocation for a later slot spilled it: value in the frame, entry in the
    // map, claim gone, owner preserved across the store.
    const staged: u5 = 21;
    const staged_off: u16 = 8;
    const staged_temp: u32 = 5;
    compiler.pending_varargs[0] = .{ .reg = staged, .staged = true };
    compiler.pending_vararg_count = 1;
    try compiler.spilled_regs.put(alloc, staged, staged_off);
    compiler.gp_reg_owner[staged] = staged_temp;
    compiler.used_regs[staged] = false;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, staged_temp, staged);

    const before = compiler.code.items.len;
    const live = try compiler.ensureRegLiveRemap(&temps, staged);

    // THE READ ANSWERS THE REGISTER THE STAGING NAMES. This is the whole fact:
    // a fresh register here and `pending_varargs[0].reg` is stale for the
    // `emitPushVarargs` that reads it a few instructions later.
    try std.testing.expectEqual(staged, live);
    try std.testing.expectEqual(staged, compiler.pending_varargs[0].reg);
    try std.testing.expectEqual(@as(?u5, live), temps.get(staged_temp));

    // One `ldr` out of this value's own slot, into that same register.
    const reload_off: u16 = compiler.stack_frame_bytes - staged_off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // The register comes back exactly as it went in: claimed again by the
    // reload, entry gone, its slot back in the pool once, and the owner
    // `spillReg` preserved across the store still at its index — the sweep
    // releases this claim on the same record it would have had no spill
    // happened at all.
    try std.testing.expect(compiler.used_regs[staged]);
    try std.testing.expect(!compiler.spilled_regs.contains(staged));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(staged_off, compiler.free_spill_slots.items[0]);
    try std.testing.expectEqual(@as(?u32, staged_temp), compiler.gp_reg_owner[staged]);

    // NOTHING ELSE WAS TAKEN. A relocation is net zero in registers, so
    // reloading into the staged register gives the pool up nothing: x9 is where
    // the relocation would have gone and it is still free.
    try std.testing.expect(!compiler.used_regs[9]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[9]);

    // A HOLE IS NOT A RESERVATION. A slot inside `pending_vararg_count` that no
    // `mov_arg` wrote is `.{}` — operand null, `staged` clear, `reg` 0 — so
    // reading the cleared operand as "materialized" would pin x0 for nothing.
    // A spilled x0 beside a hole is still the relocation's.
    compiler.pending_varargs[1] = .{};
    compiler.pending_vararg_count = 2;
    const hole_temp: u32 = 13;
    const hole_off: u16 = 40;
    try compiler.spilled_regs.put(alloc, 0, hole_off);
    compiler.gp_reg_owner[0] = hole_temp;
    compiler.used_regs[0] = false;
    try temps.put(alloc, hole_temp, 0);

    const moved = try compiler.ensureRegLiveRemap(&temps, 0);
    try std.testing.expect(moved != 0);
    try std.testing.expectEqual(@as(?u5, moved), temps.get(hole_temp));
    try std.testing.expectEqual(@as(?u32, hole_temp), compiler.gp_reg_owner[moved]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[0]);
    try std.testing.expect(!compiler.spilled_regs.contains(0));

    // THE SKIP IS THE STAGING FACT AND NOTHING ELSE. `emitPopVarargs` clears
    // the tail, and after it the identical entry in the identical state is the
    // ordinary temp the relocation has always moved — so this is one term, not
    // a value the remap can no longer relocate.
    compiler.pending_varargs[0] = .{};
    compiler.pending_vararg_count = 0;
    try compiler.spilled_regs.put(alloc, staged, staged_off);
    compiler.used_regs[staged] = false;

    const relocated = try compiler.ensureRegLiveRemap(&temps, staged);
    try std.testing.expect(relocated != staged);
    try std.testing.expectEqual(@as(?u5, relocated), temps.get(staged_temp));
    try std.testing.expectEqual(@as(?u32, staged_temp), compiler.gp_reg_owner[relocated]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[staged]);
}

// GAP-148. THE RECLAIM BID FOR A REGISTER A PIN STILL NAMED.
//
// `reclaimSpilledReg` passes over four reservations — `exclude`, a home,
// `pending_arg_regs`, and a staged variadic tail — and reads the HOME FLAG
// where `ensureRegLiveRemap` reads the PIN MAP. Those are the same set at five
// of the six `pinned.put` sites, each of which calls `markGpHome` first. The
// sixth is a LEAF's parameter: `compileDnirFunction` keeps an incoming argument
// in its own x0..x7 register, claims it, writes `temps` and `pinned`, and marks
// no home because there is none to mark. The bit stays clear until a store to
// that slot sets it, so a parameter that is only ever READ — every leaf
// parameter this backend compiles today — is pinned and is not a home for its
// whole life.
//
// It is a spill victim there: the third pass in `allocRegExcluding` walks
// x7..x0 and takes any `used_regs` register that is neither `exclude` nor a
// staged argument, and a parameter at rest is neither. The reclaim below the
// passes then found that entry and took it — entry dropped, `gp_reg_owner`
// nulled, slot released, `claimReg`, handed back as scratch — while `pinned`
// still named the register and `evalDnirValue` consults `pinned` FIRST for a
// local. The next read of the parameter answers a register the caller was just
// given and is about to write, and the frame copy is gone in both directions at
// once: `ensureRegLive` and `ensureRegLiveRemap` both key on the dropped entry,
// and the slot is back in `free_spill_slots` for the next spill to store a
// second value over. The same wrong answer `gp_call_home_regs` measured for a
// home, reached through the one pinned register the home flag does not cover —
// and through the reclaim rather than the reload, which answered it by
// returning the parameter to the register both maps name.
//
// Built directly, like every test this gap has recorded: this is a state the
// allocator passes through between a spill of a parameter register and the next
// allocation under pressure, not one a fixture names.
test "the spilled-register reclaim passes over a pinned parameter and takes a temp" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport, and so does this reclaim:
    // `allocRegExcluding` refuses above its three spill passes otherwise.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // What the leaf-parameter arm of `compileDnirFunction` leaves behind: the
    // incoming register claimed, both maps naming it, AND NO HOME FLAG. That
    // last fact is the whole difference from the home test above.
    const arg_reg: u5 = 0;
    const slot: u32 = 0;
    compiler.claimReg(arg_reg);

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, slot, arg_reg);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    try pinned.put(alloc, slot, arg_reg);
    compiler.eval_pinned = &pinned;
    try std.testing.expect(!compiler.gp_home_regs[arg_reg]);

    // And what the third spill pass leaves behind: the value in a frame slot,
    // the entry reserving the register to it, `used_regs` clear. A leaf sets no
    // `pending_arg_regs` bit — it makes no call — so no reservation this
    // function already asks about covers this entry.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, arg_reg, off);
    compiler.used_regs[arg_reg] = false;
    try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);

    // A PINNED PARAMETER ALONE IS NOT A CANDIDATE. The map is non-empty and its
    // only entry is pinned, so the answer is the refusal, not the parameter.
    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));

    // And the parameter is exactly as it was: the entry that reloads it still
    // there, both maps still naming the register, still unclaimed, and its slot
    // NOT in the free pool — a released slot is a second value stored over this
    // one.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(arg_reg));
    try std.testing.expectEqual(@as(?u5, arg_reg), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, arg_reg), temps.get(slot));
    try std.testing.expect(!compiler.used_regs[arg_reg]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // Now an ownerless stale spill beside it. It is dead storage rather than a
    // value location, so it is the entry the reclaim may reach.
    const temp: u5 = 21;
    const temp_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, temp, temp_off);
    compiler.used_regs[temp] = false;

    const got = try compiler.reclaimSpilledReg(null);
    try std.testing.expectEqual(temp, got);

    // The stale entry is dropped, its slot returned, and its register claimed.
    try std.testing.expect(!compiler.spilled_regs.contains(temp));
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[temp]);
    try std.testing.expect(compiler.used_regs[temp]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(temp_off, compiler.free_spill_slots.items[0]);

    // THE PARAMETER IS STILL WHOLE, which is the whole point: its reload
    // survives a reclaim that happened beside it.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(arg_reg));
    try std.testing.expectEqual(@as(?u5, arg_reg), pinned.get(slot));
    try std.testing.expect(!compiler.used_regs[arg_reg]);

    // A PIN THAT NAMES ANOTHER REGISTER IS NOT THIS ONE. `regIsPinned` walks the
    // map's values, so the question is the register and not the presence of a
    // pin map: an unpinned ownerless stale spill beside a pinned one is still
    // reclaimable, and it is reached before the entry the skip protects.
    const other: u5 = 22;
    const other_off: u16 = 32;
    try compiler.spilled_regs.put(alloc, other, other_off);
    compiler.used_regs[other] = false;

    try std.testing.expectEqual(other, try compiler.reclaimSpilledReg(null));
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(arg_reg));

    // AND WITH NO PIN MAP THERE IS NO PIN — which `eval_pinned` is outside a
    // function body. The identical entry in the identical state is then the
    // ownerless stale register the reclaim may take, so the skip is one term
    // and not an entry the reclaim can no longer reach.
    compiler.eval_pinned = null;
    try std.testing.expectEqual(arg_reg, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(arg_reg));
    try std.testing.expect(compiler.used_regs[arg_reg]);
    try std.testing.expectEqual(@as(usize, 3), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[2]);

    // A reclaim emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. AN ABI-BANK RESULT IS A VALUE LOCATION AND `gp_reg_owner` NEVER SAYS SO.
//
// The reclaim reads "ownerless" as "dead storage". Every write to
// `gp_reg_owner` skips `r < 9`, so a call or pack result the ABI left in
// x0..x7 is ownerless for its whole life while `temps` names its register --
// and `temps` is the map `evalDnirValue` reads for it. The third spill pass
// walks x7..x0 and takes it; the reclaim then dropped the entry and released
// the slot, so the value's last location was deleted and the next read
// answered the register the caller had just been handed as scratch.
test "the spilled-register reclaim passes over a register the temp map names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // What the pack-result arm of a call leaves behind: the ABI register
    // claimed and `temps` naming it, and NOTHING else -- no owner, because the
    // `gp_reg_owner` writes skip x0..x7; no home; no pin; no staging, the call
    // it came from having already returned.
    const result_reg: u5 = 0;
    const result: u32 = 7;
    compiler.claimReg(result_reg);

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, result, result_reg);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    compiler.eval_pinned = &pinned;
    compiler.eval_temps = &temps;
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[result_reg]);
    try std.testing.expect(!compiler.gp_home_regs[result_reg]);
    try std.testing.expect(!compiler.evalPinNames(result_reg));
    try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);

    // And what the third spill pass leaves behind: the value in a frame slot,
    // the entry reserving the register to it, `used_regs` clear.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, result_reg, off);
    compiler.used_regs[result_reg] = false;

    // A NAMED RESULT ALONE IS NOT A CANDIDATE. Every entry in the map is one, so
    // the answer is the refusal.
    try std.testing.expectError(error.RegisterExhausted, compiler.reclaimSpilledReg(null));

    // The entry that reloads it is still there, `temps` still names the
    // register, and the slot is NOT in the free pool -- a released slot is a
    // second value stored over this one.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(result_reg));
    try std.testing.expectEqual(@as(?u5, result_reg), temps.get(result));
    try std.testing.expect(!compiler.used_regs[result_reg]);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // A TEMP THAT NAMES ANOTHER REGISTER IS NOT THIS ONE. The skip is one term
    // and not a blanket refusal: an ownerless stale entry no map names is still
    // the dead storage this function may retire.
    const stale: u5 = 21;
    const stale_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, stale, stale_off);
    compiler.used_regs[stale] = false;

    try std.testing.expectEqual(stale, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(stale));
    try std.testing.expect(compiler.used_regs[stale]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(stale_off, compiler.free_spill_slots.items[0]);

    // The result is still whole beside it.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(result_reg));
    try std.testing.expect(!compiler.used_regs[result_reg]);

    // AND WITH NO TEMP MAP THERE IS NO READER -- which `eval_temps` is outside a
    // function body. The identical entry in the identical state is then the
    // ownerless stale register the reclaim may take, so the refusal above is
    // this skip and not one of the five beside it.
    compiler.eval_temps = null;
    try std.testing.expectEqual(result_reg, try compiler.reclaimSpilledReg(null));
    try std.testing.expect(!compiler.spilled_regs.contains(result_reg));
    try std.testing.expect(compiler.used_regs[result_reg]);
    try std.testing.expectEqual(@as(usize, 2), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[1]);

    // A reclaim emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. A RELEASE GIVES BACK A CLAIM; IT DOES NOT RETIRE A VALUE'S LAST
// LOCATION.
//
// `releaseReg` reads the same register-keyed test the reclaim read --
// `gp_reg_owner[reg] == null` -- and every write to `gp_reg_owner` skips
// `r < 9`. So a call or pack result the ABI left in x0..x7 is ownerless for
// its whole life while `temps` names its register, the third spill pass walks
// x7..x0 and puts that register in `spilled_regs`, and the emitter then
// releases the operand register it is done with. The entry that reloads the
// value went with it, and the slot went into the free pool for the next spill
// to store over.
test "a release keeps the spill entry of a register the temp map names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // The state an operand read leaves: `temps` names the ABI register for the
    // value, and nothing else does -- no owner, the `gp_reg_owner` writes
    // skipping x0..x7; no home; no pin.
    const result_reg: u5 = 0;
    const result: u32 = 7;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    try temps.put(alloc, result, result_reg);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    compiler.eval_pinned = &pinned;
    compiler.eval_temps = &temps;
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[result_reg]);
    try std.testing.expect(!compiler.evalPinNames(result_reg));

    // Then the third spill pass takes it while the other operand is evaluated.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, result_reg, off);
    compiler.used_regs[result_reg] = false;

    compiler.releaseReg(result_reg);

    // THE CLAIM IS GIVEN BACK AND THE STORAGE IS KEPT. The entry is the only
    // thing `ensureRegLive`/`ensureRegLiveRemap` key on, and the slot is not in
    // the free pool, where the next spill would store a second value over this
    // one.
    try std.testing.expect(!compiler.used_regs[result_reg]);
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(result_reg));
    try std.testing.expectEqual(@as(?u5, result_reg), temps.get(result));
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // UNNAMED SCRATCH IS STILL THE DEAD STORAGE THIS FUNCTION RETIRES, on the
    // removal that took the entry, and releasing it twice still puts one
    // offset in the pool once.
    const scratch: u5 = 21;
    const scratch_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, scratch, scratch_off);
    compiler.used_regs[scratch] = true;

    compiler.releaseReg(scratch);
    try std.testing.expect(!compiler.used_regs[scratch]);
    try std.testing.expect(!compiler.spilled_regs.contains(scratch));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(scratch_off, compiler.free_spill_slots.items[0]);

    compiler.releaseReg(scratch);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);

    // AND THE TERM IS THE BAND, NOT THE MAP. At x9 and above the owner record
    // is rebound after every value instruction, so ownerless there is scratch
    // whatever `temps` still says -- and `evalDnirValue` refuses that name
    // itself. A named register in that band is released exactly as before.
    const banded: u5 = 22;
    const banded_off: u16 = 32;
    try temps.put(alloc, result + 1, banded);
    try compiler.spilled_regs.put(alloc, banded, banded_off);
    compiler.used_regs[banded] = true;
    try std.testing.expect(compiler.evalTempNames(banded));

    compiler.releaseReg(banded);
    try std.testing.expect(!compiler.spilled_regs.contains(banded));
    try std.testing.expectEqual(@as(usize, 2), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(banded_off, compiler.free_spill_slots.items[1]);

    // AND WITH NO TEMP MAP THERE IS NO READER, which `eval_temps` is outside a
    // function body. The identical entry in the identical state is then
    // ordinary dead scratch again, so the retention above is this term and not
    // one of the guards beside it.
    compiler.eval_temps = null;
    compiler.releaseReg(result_reg);
    try std.testing.expect(!compiler.spilled_regs.contains(result_reg));
    try std.testing.expectEqual(@as(usize, 3), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[2]);

    // A release emits nothing; it moves records only.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
}

// GAP-148. THE HOIST UNWIND GAVE BACK A REGISTER THE POOL COULD NOT TAKE.
//
// `immHoistExit` exists to release a loop's reserved constant registers "so the
// loop-exit code and any sibling loop can reuse them", and it released the three
// records `markGpHome` wrote — `gp_home_regs`, `gp_reg_owner`, `used_regs`. None
// of those is what keeps a SPILLED register out of the pool. `spilled_regs` is:
// both free scans in `allocRegExcluding` skip anything that map contains, which
// is the fail-closed guard standing in for the claim `spillReg` dropped. So a
// hoist home that had been spilled left the unwind unallocatable for the rest of
// the function, and its frame slot — whose only readers, `ensureRegLive` and
// `ensureRegLiveRemap`, both key on that entry — stayed reserved with nothing
// able to read it, pushing `spillReg` toward the `gate_spill_end` refusal.
//
// Only a LEAF's hoist home reaches the map: the first spill pass in
// `allocRegExcluding` skips every home and the second skips `gp_call_home_regs`,
// which a leaf never sets. Built directly rather than through a source program
// for the same reason as the reclaim, reload, remap, release, and home tests
// above — this is a state the allocator passes through between a spill and a
// latch, not a state a fixture names.
test "the hoist unwind returns the frame slot with the register it releases" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill loops otherwise, so `spilled_regs` is empty everywhere else.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // One loop holding one hoisted constant in a reserved home, exactly as
    // `immHoistEnter` leaves it.
    const home: u5 = 20;
    const hoisted: i64 = 4096;
    compiler.markGpHome(home);
    try compiler.imm_hoist.put(alloc, hoisted, home);
    var active: Arm64Compiler.HoistActive = .{ .latch = 4 };
    active.values[0] = hoisted;
    active.regs[0] = home;
    active.count = 1;
    compiler.hoist_active[0] = active;
    compiler.hoist_depth = 1;

    // The state `spillReg` leaves behind: the value is at a frame slot, and the
    // register is out of `used_regs` with the `spilled_regs` entry standing in
    // for the claim.
    const off: u16 = 16;
    try compiler.spilled_regs.put(alloc, home, off);
    compiler.used_regs[home] = false;

    // A spilled register belonging to somebody else, to prove the unwind takes
    // only the entries of the registers it is releasing.
    const other: u5 = 11;
    const other_off: u16 = 32;
    try compiler.spilled_regs.put(alloc, other, other_off);
    compiler.gp_reg_owner[other] = 7;

    const before = compiler.code.items.len;
    compiler.immHoistExit(5);

    // An unwind emits nothing; it moves records only.
    try std.testing.expectEqual(before, compiler.code.items.len);

    // The records the unwind already cleared.
    try std.testing.expectEqual(@as(u8, 0), compiler.hoist_depth);
    try std.testing.expect(!compiler.gp_home_regs[home]);
    try std.testing.expect(compiler.imm_hoist.get(hoisted) == null);

    // And the one that decides whether the release is a release at all.
    try std.testing.expectEqual(@as(?u16, null), compiler.spilled_regs.get(home));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // The neighbour keeps its entry, its owner, and its unreleased slot.
    try std.testing.expectEqual(@as(?u16, other_off), compiler.spilled_regs.get(other));
    try std.testing.expectEqual(@as(?u32, 7), compiler.gp_reg_owner[other]);

    // The register is back in the pool, which is the whole point of the unwind:
    // with every other allocatable register busy, the free scan reaches it. With
    // the entry left behind, both scans pass over it and the allocation falls
    // into the spill cascade instead.
    var reg: u5 = 0;
    while (reg < 29) : (reg += 1) {
        if (reg != home) compiler.used_regs[reg] = true;
    }
    try std.testing.expectEqual(home, try compiler.allocReg());
}

// GAP-148. THE HOISTED CONSTANT WAS READ OUT OF A MAP, NOT OUT OF THE FRAME.
//
// `ensureRegLiveRemap` states the rule and names the gap in its own coverage:
// the maps that name a value's register cannot rewrite themselves, so a read
// through one of them has to consult `spilled_regs` before it answers. It does
// that for `pinned` and for `temps`, the two maps a `.local` is read through.
// `imm_hoist` is the third, and the three constant arms of `evalDnirValue` are
// its only readers that hand back a register — they answered from the map alone.
//
// A hoisted constant's register is a spill victim in a CALLING function, not
// only a leaf: `immHoistEnter` takes it from `allocReg` rather than
// `allocHomeReg`, so `markGpHome` flags it as a home while `gp_call_home_regs`
// stays clear for it, and the second spill pass in `allocRegExcluding` skips
// only that mask. After the spill the value is in the frame and `used_regs` is
// clear — and `used_regs` is the entire save set `emitSaveCallerRegs` builds, so
// the constant leaves the save set while `imm_hoist` still names its register
// and the next `bl` clobbers x9..x17 out from under every later read.
//
// Built directly rather than through a source program for the same reason as the
// reclaim, reload, remap, release, home, and unwind tests above — this is a state
// the allocator passes through between a spill and the next read of a hoisted
// constant, not a state a fixture names.
test "a hoisted constant reloads before the read that names its register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` is empty everywhere else and
    // this whole read is the map lookup it always was.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    // What `immHoistEnter` leaves behind for one hoisted constant: a register
    // from the ordinary pool, flagged a home, with no `gp_call_home_regs` bit —
    // which is what makes it reachable by the second spill pass.
    const home: u5 = 20;
    const hoisted: i64 = 4096;
    compiler.markGpHome(home);
    try compiler.imm_hoist.put(alloc, hoisted, home);
    try std.testing.expectEqual(@as(u32, 0), compiler.gp_call_home_regs & (@as(u32, 1) << home));

    // And what `spillReg` leaves behind: the value at a frame slot, the entry
    // standing in for the claim it dropped, and `used_regs` clear — which is the
    // save set `emitSaveCallerRegs` builds, so the constant is no longer in it.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, home, off);
    compiler.used_regs[home] = false;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    const before = compiler.code.items.len;
    const live = try compiler.evalDnirValue(&temps, .{ .i64 = hoisted });

    // THE READ ANSWERS THE REGISTER `imm_hoist` NAMES — it always did, and that
    // is not the fact. The fact is what has to be true of that register first.
    try std.testing.expectEqual(home, live);

    // One `ldr` from this constant's slot back into that same register.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const want: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, live);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // The claim is back, which is the save-set membership the spill took away,
    // and the home records `markGpHome` wrote are untouched by the round trip.
    try std.testing.expect(compiler.used_regs[live]);
    try std.testing.expect(compiler.gp_home_regs[live]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[live]);

    // The entry is gone and its slot went back exactly once, on the removal that
    // took it — the rule `sweepGpLive`, `releaseReg`, and both reloads share.
    try std.testing.expect(!compiler.spilled_regs.contains(home));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // NOTHING ELSE WAS TAKEN. Reloading into the register every map already
    // names costs the pool nothing, so the scratch a relocation would have
    // consumed is still free — `allocRegExcluding` scans x9 upward.
    try std.testing.expect(!compiler.used_regs[9]);

    // AND THE READ IS REPEATABLE. A second read finds no entry, emits nothing,
    // and releases nothing: a hoisted constant that was never spilled reads
    // exactly as it did before this repair.
    const again = try compiler.evalDnirValue(&temps, .{ .i64 = hoisted });
    try std.testing.expectEqual(home, again);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);

    // THE OTHER TWO ARMS READ THE SAME MAP AND OWE THE SAME RELOAD. `.f64` and
    // `.f32` hoist their bit patterns into a GP register the identical way, so
    // the repair is the class and not the `.i64` specimen.
    const fhome: u5 = 21;
    const fval: f64 = 2.5;
    const fbits: i64 = @bitCast(fval);
    compiler.markGpHome(fhome);
    try compiler.imm_hoist.put(alloc, fbits, fhome);
    const foff: u16 = 24;
    try compiler.spilled_regs.put(alloc, fhome, foff);
    compiler.used_regs[fhome] = false;

    const fbefore = compiler.code.items.len;
    const flive = try compiler.evalDnirValue(&temps, .{ .f64 = fval });
    try std.testing.expectEqual(fhome, flive);
    const freload_off: u16 = compiler.stack_frame_bytes - foff - 8;
    const fwant: u32 = 0xf94003e0 | ((@as(u32, freload_off) / 8) << 10) | @as(u32, flive);
    try std.testing.expectEqual(fbefore + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        fwant,
        std.mem.readInt(u32, compiler.code.items[fbefore..][0..4], .little),
    );
    try std.testing.expect(compiler.used_regs[flive]);
    try std.testing.expect(!compiler.spilled_regs.contains(fhome));
}

// A STORE INTO A SPILLED HOME KILLS THE FRAME COPY, AND THE ENTRY HAS TO DIE
// WITH IT (GAP-148).
//
// Every fact this gap has recorded so far lives on a READ path — which entry a
// reclaim may take, where a reloaded value lands, what the reclaim, the remap,
// the release and the unwind leave behind. This one is the WRITE path.
// `store_local`'s register-homed arm writes the local's new value straight into
// the register `pinned`/`temps` names, with `emitMovRegFit`, and left
// `spilled_regs` naming that register. The entry then says the value is in the
// frame while the register holds the value just stored, and `ensureRegLive` —
// reached by the very next read, through `ensureRegLiveRemap`'s home branch —
// emits the `ldr` that puts the OLD value back over the new one. A silent wrong
// answer for every read of that local after the store.
//
// Built directly rather than through a source program for the same reason as the
// reclaim, reload, remap, release, home, unwind and hoist tests above: this is a
// state the allocator passes through between a spill of a home and the next
// store into it, not a state a fixture names.
test "a store into a spilled home retires the entry that would reload it" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` is empty everywhere else and
    // this store is the move it always was.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // What a homed local looks like: one register for the whole function, named
    // by both maps `evalDnirValue` consults.
    const slot: u32 = 3;
    const home: u5 = 20;
    compiler.markGpHome(home);
    try pinned.put(alloc, slot, home);
    try temps.put(alloc, slot, home);

    // And what `spillReg` leaves behind. A LEAF's home is a spill victim: the
    // first pass in `allocRegExcluding` skips every home and the second skips
    // only `gp_call_home_regs`, which a leaf never sets.
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, home, off);
    compiler.used_regs[home] = false;
    try std.testing.expectEqual(@as(u32, 0), compiler.gp_call_home_regs & (@as(u32, 1) << home));

    // The value being stored, in an ordinary scratch register.
    const src_temp: u32 = 7;
    const src_reg: u5 = 9;
    compiler.claimReg(src_reg);
    try temps.put(alloc, src_temp, src_reg);

    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = slot,
        .lhs = .{ .temp = src_temp },
        .ty = .i64,
    }, &branch_patches, null, 0);

    // THE STORE IS ONE MOVE INTO THE HOME, unchanged by this repair.
    const want_mov: u32 = 0xaa0003e0 | (@as(u32, src_reg) << 16) | @as(u32, home);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        want_mov,
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );

    // THE ENTRY IS GONE. It named a frame copy the store just superseded, and
    // it is the only thing that can still write to this register behind the
    // program's back.
    try std.testing.expectEqual(@as(?u16, null), compiler.spilled_regs.get(home));

    // Its slot went back exactly once, on the removal that took it — the rule
    // `sweepGpLive`, `releaseReg`, the unwind and both reloads already share.
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);

    // The claim is back and the home records are untouched: the register stands
    // for this local again, exactly as it did before the spill.
    try std.testing.expect(compiler.used_regs[home]);
    try std.testing.expect(compiler.gp_home_regs[home]);
    try std.testing.expectEqual(@as(?u5, home), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, home), temps.get(slot));

    // AND THE NEXT READ EMITS NOTHING. This is the failure itself: with the
    // entry alive, `ensureRegLiveRemap`'s home branch reloads the pre-store
    // value over the value just stored, and answers with it.
    const after_store = compiler.code.items.len;
    const read = try compiler.evalDnirValue(&temps, .{ .local = slot });
    try std.testing.expectEqual(home, read);
    try std.testing.expectEqual(after_store, compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);

    // A NEIGHBOUR THE STORE DID NOT NAME KEEPS EVERYTHING. Only the register
    // written to has a dead frame copy.
    const other: u5 = 21;
    const other_off: u16 = 24;
    compiler.markGpHome(other);
    try compiler.spilled_regs.put(alloc, other, other_off);
    compiler.used_regs[other] = false;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = slot,
        .lhs = .{ .temp = src_temp },
        .ty = .i64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(@as(?u16, other_off), compiler.spilled_regs.get(other));
    try std.testing.expect(!compiler.used_regs[other]);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
}

// GAP-148: THE SPILL AREA WAS RESERVED AT ONE END OF THE FRAME AND HANDED OUT
// FROM THE OTHER.
//
// Every fact this gap has recorded so far is about a MAP — which entry a reclaim
// may take, where a reloaded value lands, what the reclaim, the remap, the
// release, the unwind and the store leave behind. This one is about the FRAME.
// `spillReg` and `ensureRegLive` address a slot as `stack_frame_bytes - off - 8`,
// so `off` counts down from the top of the frame; the prologue named the band
// `[gp_stack_bytes, gp_stack_bytes + spill_reserve)`, which is the reserved
// area's address measured UP from `sp`. The two coordinates overlap rather than
// shift: the cursor starts at the top of the reservation and walks downward out
// of it, across the GP stack locals at `[sp, 0 .. gp_stack_bytes)`.
//
// Built directly rather than through a source program for the same reason as
// every test above it: the collision needs the reserved area actually exhausted,
// which a fixture reaches only incidentally.
test "the gate spill band stays inside the area the prologue reserved" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE BAND, over the layouts the prologue builds. `prior` is whatever the
    // frame already held — table regions and records, rebased above the new
    // reservation; `gp_stack_bytes` is the locals band at `[sp,#0]`; the
    // reservation is the `spill_reserve` bytes directly above them.
    const priors = [_]u16{ 0, 64, 512 };
    const locals = [_]u16{ 0, 16, 80, 512 };
    const reserves = [_]u16{ 64, 256, 1024 };
    for (priors) |prior| {
        for (locals) |gp_stack_bytes| {
            for (reserves) |spill_reserve| {
                const frame_bytes: u16 = prior + gp_stack_bytes + spill_reserve;
                const band = Arm64Compiler.gateSpillBand(frame_bytes, gp_stack_bytes, spill_reserve);
                // The area is not made smaller by being put in the right place.
                try std.testing.expectEqual(spill_reserve, band.end - band.base);
                var cursor = band.base;
                var slots: u16 = 0;
                while (cursor + 16 <= band.end) : (cursor += 16) {
                    // The address `spillReg` stores at and `ensureRegLive`
                    // reloads from, for this `off`.
                    const addr: u16 = frame_bytes - cursor - 8;
                    // ABOVE THE LOCALS. Below this line the store writes over a
                    // local's home and the local's next store writes over the
                    // spilled value.
                    try std.testing.expect(addr >= gp_stack_bytes);
                    // AND INSIDE THE RESERVATION. Above this line it writes into
                    // the table and record regions the prologue rebased.
                    try std.testing.expect(addr + 8 <= gp_stack_bytes + spill_reserve);
                    slots += 1;
                }
                try std.testing.expectEqual(spill_reserve / 16, slots);
            }
        }
    }

    // AND THE OFFSETS `spillReg` ACTUALLY EMITS, on the measured layout: ten
    // locals at `slot * 8`, a 256-byte reservation above them, nothing else in
    // the frame.
    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so this whole area is untouched elsewhere.
    compiler.gate_transport = true;

    const gp_stack_bytes: u16 = 80;
    const spill_reserve: u16 = 256;
    compiler.stack_frame_bytes = gp_stack_bytes + spill_reserve;
    var slot: u32 = 0;
    while (slot < 10) : (slot += 1) {
        try compiler.gp_stack_locals.put(alloc, slot, @intCast(slot * 8));
    }
    const band = Arm64Compiler.gateSpillBand(compiler.stack_frame_bytes, gp_stack_bytes, spill_reserve);
    compiler.gate_spill_base = band.base;
    compiler.gate_spill_end = band.end;
    compiler.gate_spill_cursor = band.base;

    // One spill per slot the reservation holds, on distinct registers so no
    // reload path can return a slot to the free list mid-walk.
    const victims = [_]u5{ 9, 10, 11, 12, 13, 14, 15, 16, 17, 19, 20, 21, 22, 23, 24, 25 };
    try std.testing.expectEqual(@as(usize, spill_reserve / 16), victims.len);
    var seen: [victims.len]u16 = @splat(0);
    for (victims, 0..) |victim, i| {
        const before = compiler.code.items.len;
        try compiler.spillReg(victim);
        // `spillReg` emits exactly one `str` for a slot the area already holds.
        try std.testing.expectEqual(before + 4, compiler.code.items.len);
        const word = std.mem.readInt(u32, compiler.code.items[before..][0..4], .little);
        try std.testing.expectEqual(@as(u32, victim), word & 0x1f);
        const addr: u16 = @intCast(((word >> 10) & 0xfff) * 8);
        seen[i] = addr;
        // NOT OVER A LOCAL, and inside the reservation.
        try std.testing.expect(addr >= gp_stack_bytes);
        try std.testing.expect(addr + 8 <= gp_stack_bytes + spill_reserve);
        var prev: usize = 0;
        while (prev < i) : (prev += 1) {
            try std.testing.expect(seen[prev] != addr);
        }
    }

    // The area is full, and the refusal at the end of it is the one the reserve's
    // own sizing relies on: a bound that is too tight costs a named refusal.
    try std.testing.expectError(error.RegisterExhausted, compiler.spillReg(26));
}

fn spDisp(word: [4]u8) u16 {
    return @intCast(((std.mem.readInt(u32, &word, .little) >> 10) & 0xfff) * 8);
}

test "a spill and its reload name one byte across a temporary sp window" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    const gp_stack_bytes: u16 = 80;
    const spill_reserve: u16 = 256;
    compiler.stack_frame_bytes = gp_stack_bytes + spill_reserve;
    const band = Arm64Compiler.gateSpillBand(compiler.stack_frame_bytes, gp_stack_bytes, spill_reserve);
    compiler.gate_spill_base = band.base;
    compiler.gate_spill_end = band.end;
    compiler.gate_spill_cursor = band.base;
    try compiler.gp_stack_locals.put(alloc, 3, 24);

    // CONTROL, `sp` at the frame: the displacement is the expression every
    // consumer wrote before the correction, so no program that stays out of a
    // window changes a byte.
    const control_at = compiler.code.items.len;
    try compiler.spillReg(9);
    try std.testing.expectEqual(control_at + 4, compiler.code.items.len);
    const control_addr = spDisp(compiler.code.items[control_at..][0..4].*);
    const control_off = compiler.spilled_regs.get(9).?;
    try std.testing.expectEqual(compiler.stack_frame_bytes - control_off - 8, control_addr);

    const local_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(24, 11);
    const local_addr = spDisp(compiler.code.items[local_at..][0..4].*);
    try std.testing.expectEqual(@as(u16, 24), local_addr);

    // The window: `emitSaveCallerRegs`, `emitPushVarargs`, the pack park,
    // `snprintf`'s x0 save and `printf`'s stack argument all move `sp` and leave
    // `stack_frame_bytes` alone, because each is undone before the frame ends.
    const window: u16 = 32;
    try compiler.emitSubSpTemp(window);

    const store_at = compiler.code.items.len;
    try compiler.spillReg(10);
    try std.testing.expectEqual(store_at + 4, compiler.code.items.len);
    const store_word = std.mem.readInt(u32, compiler.code.items[store_at..][0..4], .little);
    try std.testing.expectEqual(@as(u32, 10), store_word & 0x1f);
    const store_addr = spDisp(compiler.code.items[store_at..][0..4].*);
    const slot_off = compiler.spilled_regs.get(10).?;

    // The same frame byte, named from the window's `sp`: a GP stack local and a
    // spill slot are one coordinate family and move together.
    const local_in_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(24, 11);
    try std.testing.expectEqual(local_addr + window, spDisp(compiler.code.items[local_in_at..][0..4].*));

    try compiler.emitAddSpTemp(window);

    const reload_at = compiler.code.items.len;
    try compiler.ensureRegLive(10);
    try std.testing.expectEqual(reload_at + 4, compiler.code.items.len);
    const reload_word = std.mem.readInt(u32, compiler.code.items[reload_at..][0..4], .little);
    try std.testing.expectEqual(@as(u32, 10), reload_word & 0x1f);
    const reload_addr = spDisp(compiler.code.items[reload_at..][0..4].*);

    // ONE BYTE, NAMED FROM TWO STACK POINTERS. `sp` was `window` lower at the
    // store, so the byte is `window` further from it there; a displacement that
    // ignores the window makes these two differ by exactly `window` and the
    // reload answers with the slot's previous contents.
    try std.testing.expectEqual(reload_addr, store_addr - window);
    try std.testing.expectEqual(compiler.stack_frame_bytes - slot_off - 8, reload_addr);
    try std.testing.expect(reload_addr >= gp_stack_bytes);
    try std.testing.expect(reload_addr + 8 <= gp_stack_bytes + spill_reserve);
    try std.testing.expect(reload_addr != control_addr);

    // FAIL CLOSED, four ways. A displacement past the scaled `[sp,#imm]` field
    // wraps into a different slot, so it refuses instead.
    compiler.sp_temp_bytes = 32760;
    try std.testing.expectError(error.RegisterExhausted, compiler.frameScaledDisp(reload_addr));
    // `add` chains past its imm12 and carries no such limit.
    _ = try compiler.frameDisp(reload_addr);
    compiler.sp_temp_bytes = 0;
    _ = try compiler.frameScaledDisp(reload_addr);

    // A close wider than the open would leave `sp` above the frame base with a
    // wrapped residual describing it.
    try compiler.emitSubSpTemp(16);
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitAddSpTemp(32));
    try std.testing.expectEqual(@as(u16, 16), compiler.sp_temp_bytes);

    // Permanent growth inside a window: the window's `add sp` restores the OLD
    // base, so the reservation `stack_frame_bytes` then claims does not exist.
    try std.testing.expectError(error.UnsupportedProgram, compiler.frameGrow(16));

    // And the frame may not be torn down from inside one.
    try std.testing.expectError(error.UnsupportedProgram, compiler.restoreStackFrame());
    try compiler.emitAddSpTemp(16);
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);
}

// GROWTH RENAMES A BOTTOM-ANCHORED RESIDENT, AND ONLY THE PROLOGUE REBASES ONE
// (GAP-148).
//
// `frameSlotOff` counts DOWN FROM THE TOP, so a spill slot's displacement grows
// with the frame and names one byte across any growth. GP stack locals, table
// slot bases and record field slots count UP FROM `sp`: growth leaves their
// displacement alone, so the same `[sp,#imm]` reaches a byte `bytes` further
// from the top than the one it means, and the growth's own reservation reaches
// it too. One address, two owners — this gap's shape at the frame.
//
// The prologue rebases what its own growth displaces (the record region under
// the table region, both under the locals/spill region). Three sites grow during
// BODY emission, where no rebasing owner exists: `spillReg`'s last resort, which
// stated the rule by hand for itself, and `assignRecordFromAbiRegs` /
// `assignF64RecordFromFpAbiRegs`, which stated nothing. `frame_sealed` is the
// boundary between the two, and `frameResidents` is the one fact both refusals
// read.
//
// Not the closure. Closure remains authoritative `register`/`frame` assignment
// before emission, per this gap's record, under which the frame is laid out once
// from the assignment and no emission-time growth exists to rename anything.
test "a sealed frame refuses growth that would rename a bottom-anchored resident" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.stack_frame_bytes = 64;
    const local_off: u16 = 24;
    try compiler.gp_stack_locals.put(alloc, 3, local_off);

    const spill_off: u16 = 16;
    const store_at = compiler.code.items.len;
    try compiler.emitStrFrame(9, try compiler.frameSlotOff(spill_off));
    const store_addr = spDisp(compiler.code.items[store_at..][0..4].*);

    const local_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(local_off, 11);
    const local_addr = spDisp(compiler.code.items[local_at..][0..4].*);
    try std.testing.expectEqual(local_off, local_addr);
    const local_from_top: u16 = compiler.stack_frame_bytes - local_addr - 8;

    // Prologue staging: growth is admitted, and the caller owes the rebase.
    const grow: u16 = 16;
    try compiler.frameGrow(grow);

    // Top-anchored: `sp` is `grow` lower and the displacement is `grow` larger,
    // so the reload names the byte the store wrote.
    const reload_at = compiler.code.items.len;
    try compiler.emitLdrFrame(9, try compiler.frameSlotOff(spill_off));
    try std.testing.expectEqual(store_addr + grow, spDisp(compiler.code.items[reload_at..][0..4].*));

    // Bottom-anchored: the same displacement, `grow` further from the top.
    const after_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(local_off, 11);
    try std.testing.expectEqual(local_addr, spDisp(compiler.code.items[after_at..][0..4].*));
    try std.testing.expectEqual(local_from_top + grow, compiler.stack_frame_bytes - local_addr - 8);

    // FAIL CLOSED once the frame is the body's: no rebasing owner, so growth
    // over a resident refuses and emits nothing.
    compiler.frame_sealed = true;
    try std.testing.expectEqual(@as(usize, 1), compiler.frameResidents());
    const sealed_len = compiler.code.items.len;
    const sealed_frame = compiler.stack_frame_bytes;
    try std.testing.expectError(error.UnsupportedProgram, compiler.frameGrow(grow));
    try std.testing.expectEqual(sealed_len, compiler.code.items.len);
    try std.testing.expectEqual(sealed_frame, compiler.stack_frame_bytes);

    // `spillReg`'s last resort reads the same fact under its own refusal, which
    // is the capacity answer its callers already handle.
    try std.testing.expectError(error.RegisterExhausted, compiler.spillReg(9));

    // An empty frame has nothing to rename, so that last resort survives the
    // seal.
    compiler.gp_stack_locals.clearRetainingCapacity();
    try std.testing.expectEqual(@as(usize, 0), compiler.frameResidents());
    try compiler.frameGrow(grow);
    try std.testing.expectEqual(sealed_frame + grow, compiler.stack_frame_bytes);

    // A window is still the other refusal, and it holds after the seal.
    try compiler.emitSubSpTemp(16);
    try std.testing.expectError(error.UnsupportedProgram, compiler.frameGrow(grow));
    try compiler.emitAddSpTemp(16);
}

test "a displacement the scaled field cannot carry exactly refuses before it encodes" {
    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // ALIGNMENT: 12 encodes as 8 and prints as 12 — object and assembly
    // disagree and both report success.
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitStrSp(9, 12));
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitLdrSp(9, 12));
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitStrSpFp(1, 12));
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitLdrSpFp(1, 12));
    // BOUND: 32768 scales to 4096, which leaves the imm12 for the base field.
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitStrSp(9, 32768));
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitLdrSpFp(1, 32768));
    // A refusal that had already encoded would have sent the wrong bytes.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 0), compiler.asm_text.items.len);

    // BOUND-IS-NOT-ALIGNMENT: the last addressable slot encodes.
    try compiler.emitStrSp(9, 32760);
    // ALIGNMENT-IS-NOT-THE-BOUND: an aligned displacement inside it encodes.
    try compiler.emitLdrSp(9, 8);
    try std.testing.expectEqual(@as(usize, 8), compiler.code.items.len);
    const top = std.mem.readInt(u32, compiler.code.items[0..4], .little);
    try std.testing.expectEqual(@as(u32, 4095), (top >> 10) & 0xfff);
    const near = std.mem.readInt(u32, compiler.code.items[4..8], .little);
    try std.testing.expectEqual(@as(u32, 1), (near >> 10) & 0xfff);
}

test "an sp move off the sixteen-byte grid refuses before it moves the frame base" {
    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = std.testing.allocator,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    try std.testing.expectError(error.UnsupportedProgram, compiler.emitSubSp(24));
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitAddSp(8));
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);

    // The window and the frame reach the same predicate through their own
    // producers, and neither leaves the displacement they carry behind.
    try std.testing.expectError(error.UnsupportedProgram, compiler.emitSubSpTemp(8));
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);
    try std.testing.expectError(error.UnsupportedProgram, compiler.frameGrow(8));
    try std.testing.expectEqual(@as(u16, 0), compiler.stack_frame_bytes);

    // GRID-IS-NOT-THE-CHUNK: a move past `sp_imm_max` splits, and every chunk
    // is on the grid.
    try compiler.emitSubSp(4096);
    try std.testing.expectEqual(@as(usize, 8), compiler.code.items.len);
    const first = std.mem.readInt(u32, compiler.code.items[0..4], .little);
    try std.testing.expectEqual(@as(u32, 4080), (first >> 10) & 0xfff);
    const rest = std.mem.readInt(u32, compiler.code.items[4..8], .little);
    try std.testing.expectEqual(@as(u32, 16), (rest >> 10) & 0xfff);
}

// THE PARK WROTE A FRAME BYTE IT NEVER RESERVED (GAP-148).
//
// `[sp, #save.stack_bytes]` is the byte `sp` stood on before the save window
// opened. That is a FRAME coordinate — reached outside `frameDisp`, which the
// frame/window transfer made the sole reader of every one of them — and it is
// owned: the GP stack local at frame offset 0, or with an empty frame the
// callee-save slot for x19, or with neither the caller's own outgoing word.
// The store reported success and the byte's owner reported nothing.
//
// The sibling pack arm reserved its window BEFORE the save, so its store never
// named a frame byte; the scalar arm took the same addressing without the
// reservation. Both now measure from an assigned coordinate rather than from a
// literal — the pack's own residual is the test below this one.
test "a parked call result names the slot it reserved and not the frame's" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // A frame with a resident on the byte the unreserved store named.
    compiler.stack_frame_bytes = 96;
    try compiler.gp_stack_locals.put(alloc, 0, 0);

    // The state the arm is reached in: every candidate live, nothing left for
    // the answer.
    var reg: u5 = 0;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;
    const park = try compiler.parkOpen(true);
    const park_bytes = park.bytes;
    try std.testing.expectEqual(@as(u16, 16), park_bytes);
    try std.testing.expectEqual(compiler.sp_temp_bytes, park.base);

    const save = try compiler.emitSaveCallerRegs();
    // The reservation answered before the save window existed what the
    // allocation answers after it.
    try std.testing.expectError(error.RegisterExhausted, compiler.allocRegOutsideSaveSet(save));

    // AN UNRESERVED PARK REFUSES, and a refusal that had already encoded would
    // have shipped the store.
    const at = compiler.code.items.len;
    const asm_at = compiler.asm_text.items.len;
    try std.testing.expectError(error.RegisterExhausted, compiler.parkCallResult(.{}));
    try std.testing.expectEqual(at, compiler.code.items.len);
    try std.testing.expectEqual(asm_at, compiler.asm_text.items.len);

    // A RESERVED PARK stores once, at the location it was assigned.
    try compiler.parkCallResult(park);
    try std.testing.expectEqual(at + 4, compiler.code.items.len);
    const park_addr = spDisp(compiler.code.items[at..][0..4].*);
    try std.testing.expectEqual(save.stack_bytes, park_addr);

    // AND IT IS NOT THE FRAME'S. The resident at frame offset 0, addressed from
    // the same `sp` through `frameDisp`, is the byte the unreserved store named
    // and it is a different byte — exactly `park_bytes` above this one.
    const local_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(0, 9);
    const local_addr = spDisp(compiler.code.items[local_at..][0..4].*);
    try std.testing.expectEqual(park_addr + park_bytes, local_addr);

    // THE READ IS THE SAME BYTE FROM A DIFFERENT `sp`. Once the save window
    // closes the slot stands at [sp, #0], and the reservation is the only thing
    // that still makes it this function's.
    const store_sp_temp = compiler.sp_temp_bytes;
    try compiler.emitRestoreCallerRegs(save);
    const reload_sp_temp = compiler.sp_temp_bytes;
    try std.testing.expectEqual(park_bytes, reload_sp_temp);
    try std.testing.expectEqual(
        @as(i32, park_addr) - @as(i32, store_sp_temp),
        @as(i32, 0) - @as(i32, reload_sp_temp),
    );
    // The resident moved with `sp` and the parked byte did not.
    const after_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(0, 9);
    try std.testing.expectEqual(park_bytes, spDisp(compiler.code.items[after_at..][0..4].*));

    // The close returns the frame to itself.
    try compiler.parkClose(park);
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);
    try std.testing.expectEqual(@as(u16, 0), try compiler.frameDisp(0));
}

// THE PARKED ANSWER'S DISPLACEMENT WAS TWO LITERALS, NOT A LOCATION (GAP-148).
//
// The store carried `save.stack_bytes` and the reload carried `0`. Neither
// reads `sp_temp_bytes`, so both are correct only while the save window is the
// ONLY thing between the assignment and the read — an assumption the block
// already breaks twice, at `preserve_x0` and at the pack park, and one no
// predicate stated. `parkDisp` is the park's `frameDisp`: the slot keeps the
// coordinate it was assigned and every consumer measures from the `sp` it
// actually stands on.
test "a parked call result keeps its location under a window it did not open" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // A resident that measures the park from OUTSIDE it, so the slot's true
    // displacement is available without asking `parkDisp` for it.
    compiler.stack_frame_bytes = 96;
    try compiler.gp_stack_locals.put(alloc, 0, 0);

    var reg: u5 = 0;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;

    const park = try compiler.parkOpen(true);
    try std.testing.expectEqual(@as(u16, 16), park.bytes);
    const save = try compiler.emitSaveCallerRegs();

    // CO-LOCATED CONTROL: with the save window alone between the assignment and
    // the store, the location answers exactly the literal the store carried, so
    // no program that opens no further window changes a byte.
    try std.testing.expectEqual(save.stack_bytes, try compiler.parkDisp(park));

    // A WINDOW IS NOT THE SAVE SET. One more open — the shape `emitPushVarargs`
    // and `preserve_x0` already have — and the literal names a byte 32 below
    // the slot while the location follows it.
    try compiler.emitSubSpTemp(32);
    try std.testing.expectEqual(save.stack_bytes + 32, try compiler.parkDisp(park));

    // THE FAILING CONTROL FOR THE ENCODER-CLOSED PATH. The slot's displacement
    // is measured here from the resident at frame offset 0 less the park's own
    // width — `frameDisp`'s answer, not the park's — so the two spellings are
    // compared against a third party. `save.stack_bytes` is the literal the
    // store carried while the park was two literals; under this window it names
    // a byte 32 inside the window rather than the slot, and the store that
    // ships it writes the caller's byte and reads back the callee's saved
    // register. This assertion is the one that fails on that spelling.
    const probe_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(0, 9);
    const slot_disp = spDisp(compiler.code.items[probe_at..][0..4].*) - park.bytes;
    try std.testing.expectEqual(save.stack_bytes + 32, slot_disp);
    try std.testing.expect(slot_disp != save.stack_bytes);

    const store_at = compiler.code.items.len;
    try compiler.parkCallResult(park);
    try std.testing.expectEqual(slot_disp, spDisp(compiler.code.items[store_at..][0..4].*));

    // AND THE CLOSE IS ORDERED, NOT ONLY SIZED. `emitAddSpTemp` admits this
    // close on width alone; taking it here would leave `sp` 32 bytes inside the
    // still-open window and every later `frameDisp` wrong by exactly that.
    const at = compiler.code.items.len;
    const asm_at = compiler.asm_text.items.len;
    try std.testing.expectError(error.UnsupportedProgram, compiler.parkClose(park));
    try std.testing.expectEqual(at, compiler.code.items.len);
    try std.testing.expectEqual(asm_at, compiler.asm_text.items.len);
    try std.testing.expectEqual(park.base + save.stack_bytes + 32, compiler.sp_temp_bytes);

    try compiler.emitAddSpTemp(32);
    try compiler.emitRestoreCallerRegs(save);
    try std.testing.expectEqual(@as(u16, 0), try compiler.parkDisp(park));
    try compiler.parkClose(park);
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);

    // A CLOSED PARK IS NOT AN OPEN ONE. The slot is the caller's again, and
    // `sp_temp_bytes - park.base` under a `u16` would wrap into a displacement
    // that encodes.
    try std.testing.expectError(error.UnsupportedProgram, compiler.parkDisp(park));

    // AN UNASSIGNED PARK HAS NO BYTE AT ALL, and answers with the capacity
    // error `probeFunctionPlan` steps its ladder down on rather than a refusal.
    try std.testing.expectError(error.RegisterExhausted, compiler.parkDisp(.{}));
    // The close of one is the no-op that lets the arm publish nothing.
    try compiler.parkClose(.{});
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);
}

// THE PACK ANSWER'S SLOTS WERE TWO REWRITTEN LITERALS AND A BYTE BELOW `sp`
// (GAP-148).
//
// The pack arm reserved its window before the save, so its store never named a
// frame byte — but neither end of it named the RESERVATION either. The store
// carried `save.stack_bytes + i * 8`, which is the assigned coordinate only
// while the save window is the sole thing standing between the reservation and
// the store; and the reload carried `i * 8 - pack_bytes` through `ldur`, taken
// AFTER `emitAddSpTemp` had already raised `sp` past the window, so the answers
// were read from bytes below `sp` that the close had returned to the caller and
// nothing kept. Neither spelling reads `sp_temp_bytes`, so no predicate stated
// what either assumed.
//
// `parkOpenSlots` assigns the locations before emission and `parkSlotDisp` is
// the sole producer of each member's displacement, so every consumer measures
// from the `sp` it actually stands on and the read precedes the close.
// `emitLdurSp` had this one caller and is gone with it: no backend addressing
// reaches below `sp`.
test "a parked pack answer names the slots it reserved and reads them before the close" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // A resident that measures the park from OUTSIDE it, so each slot's true
    // displacement is available without asking the park for it.
    compiler.stack_frame_bytes = 96;
    try compiler.gp_stack_locals.put(alloc, 0, 0);

    // Three returned members on the sixteen-byte grid `emitSubSp` encodes.
    compiler.used_regs[9] = true;
    const park = try compiler.parkOpenSlots(3);
    try std.testing.expectEqual(@as(u16, 32), park.bytes);
    try std.testing.expectEqual(compiler.sp_temp_bytes, park.base);

    const save = try compiler.emitSaveCallerRegs();

    // CO-LOCATED CONTROL: with the save window alone between the reservation and
    // the store, the location answers exactly the literal the store carried, so
    // no program that opens no further window changes a byte.
    try std.testing.expectEqual(save.stack_bytes, try compiler.parkSlotDisp(park, 0));
    try std.testing.expectEqual(save.stack_bytes + 8, try compiler.parkSlotDisp(park, 1));
    try std.testing.expectEqual(save.stack_bytes + 16, try compiler.parkSlotDisp(park, 2));

    // CONTROL 1 — ASSIGNED THEN EMITTED FROM THE WRONG `sp` LITERAL.
    // One more open — the shape `emitPushVarargs` and `preserve_x0` already
    // have — and `save.stack_bytes + i * 8` names a byte 32 below slot `i`.
    // Rejected by `parkSlotDisp`, which measures `sp_temp_bytes - park.base`.
    try compiler.emitSubSpTemp(32);
    try std.testing.expectEqual(save.stack_bytes + 32, try compiler.parkSlotDisp(park, 0));
    try std.testing.expect(save.stack_bytes != try compiler.parkSlotDisp(park, 0));

    // CONTROL 3 — THE SLOT MEASURED BY A THIRD PARTY, AND A BASE THAT IS NOT
    // `parkOpen`'s. The resident at frame offset 0, addressed from this same
    // `sp` through `frameDisp`, stands exactly `park.bytes` above slot 0, so
    // the park's answer is checked against a coordinate family it does not
    // produce. A base `sp` is not standing below was never reserved by this
    // function; `parkDisp`'s `sp_temp_bytes < park.base` rejects it rather than
    // measuring a negative distance into a `u16`.
    const probe_at = compiler.code.items.len;
    try compiler.storeGpStackLocal(0, 9);
    const slot0 = spDisp(compiler.code.items[probe_at..][0..4].*) - park.bytes;
    try std.testing.expectEqual(slot0, try compiler.parkSlotDisp(park, 0));
    try std.testing.expectEqual(slot0 + 16, try compiler.parkSlotDisp(park, 2));
    try std.testing.expectError(
        error.UnsupportedProgram,
        compiler.parkSlotDisp(.{ .bytes = park.bytes, .base = compiler.sp_temp_bytes + 16 }, 0),
    );

    // A SLOT PAST THE RESERVATION IS NOT THIS PARK'S BYTE, and answers with the
    // capacity error rather than an encodable displacement into the neighbour.
    try std.testing.expectError(error.RegisterExhausted, compiler.parkSlotDisp(park, 4));
    try std.testing.expectError(error.RegisterExhausted, compiler.parkSlotDisp(.{}, 0));

    // CONTROL 2 — THE CLOSE IS ORDERED, NOT ONLY SIZED. `emitAddSpTemp` admits
    // a close of exactly this width here; taking it would leave `sp` 32 bytes
    // inside the still-open window and every later `frameDisp` wrong by that.
    // `parkClose`'s `sp_temp_bytes != park.base` is the predicate that rejects,
    // and a refusal that had already encoded would have shipped the `add`.
    try std.testing.expect(park.bytes <= compiler.sp_temp_bytes);
    const at = compiler.code.items.len;
    const asm_at = compiler.asm_text.items.len;
    try std.testing.expectError(error.UnsupportedProgram, compiler.parkClose(park));
    try std.testing.expectEqual(at, compiler.code.items.len);
    try std.testing.expectEqual(asm_at, compiler.asm_text.items.len);

    // THE STORES AND THE READS ARE ONE COORDINATE FAMILY across every `sp` the
    // block stands on: the store side under the save window, the read side once
    // it has closed, both from the reservation.
    try compiler.emitAddSpTemp(32);
    const store_at = compiler.code.items.len;
    try compiler.emitStrSp(2, try compiler.parkSlotDisp(park, 2));
    try std.testing.expectEqual(
        save.stack_bytes + 16,
        spDisp(compiler.code.items[store_at..][0..4].*),
    );
    try compiler.emitRestoreCallerRegs(save);
    const read_at = compiler.code.items.len;
    try compiler.emitLdrSp(2, try compiler.parkSlotDisp(park, 2));
    try std.testing.expectEqual(@as(u16, 16), spDisp(compiler.code.items[read_at..][0..4].*));

    // AND THE READ PRECEDED THE CLOSE. Afterwards the bytes are the caller's
    // again and the retired reload's `i * 8 - pack_bytes` is below `sp`; the
    // location refuses instead of encoding it.
    try compiler.parkClose(park);
    try std.testing.expectEqual(@as(u16, 0), compiler.sp_temp_bytes);
    try std.testing.expectError(error.UnsupportedProgram, compiler.parkSlotDisp(park, 2));
    try std.testing.expectEqual(@as(u16, 0), try compiler.frameDisp(0));
}

test "the park reservation is the answer the save set will give" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var reg: u5 = 0;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;

    // NO RESULT DEMANDED: nothing to park whatever the pool holds.
    try std.testing.expectEqual(@as(u16, 0), compiler.parkReserve(false));

    // x8 IS NOT A CANDIDATE and neither is x18: leaving either clear must not
    // withdraw the reservation, because the allocation will not hand it out.
    compiler.used_regs[8] = false;
    compiler.used_regs[Arm64Compiler.platform_reserved_reg] = false;
    try std.testing.expectEqual(@as(u16, 16), compiler.parkReserve(true));
    compiler.used_regs[8] = true;
    compiler.used_regs[Arm64Compiler.platform_reserved_reg] = true;

    // A SPILLED REGISTER IS NOT FREE: `spillReg` clears `used_regs`, and both
    // readers skip the map that still describes it.
    compiler.used_regs[11] = false;
    try compiler.spilled_regs.put(alloc, 11, 0);
    try std.testing.expectEqual(@as(u16, 16), compiler.parkReserve(true));

    // ONE FREE CANDIDATE withdraws the reservation, and the allocation takes
    // exactly that register once the save set exists.
    _ = compiler.spilled_regs.remove(11);
    try std.testing.expectEqual(@as(u16, 0), compiler.parkReserve(true));
    const save = try compiler.emitSaveCallerRegs();
    try std.testing.expectEqual(@as(u5, 11), try compiler.allocRegOutsideSaveSet(save));

    // AND `save` IS NOT `used_regs`, WHICH IS WHY THE RESERVATION IS READ
    // BEFORE THE WINDOW OPENS. A register released after the save is free in
    // the pool and still reloaded by restore, so the two readers diverge from
    // that moment on: x12 was live at save, so restore will overwrite it, and
    // only the set remembers that.
    compiler.used_regs[12] = false;
    try std.testing.expectEqual(@as(u16, 0), compiler.parkReserve(true));
    try std.testing.expectError(error.RegisterExhausted, compiler.allocRegOutsideSaveSet(save));
}

// THE CALL'S ANSWER TOOK THE ONE REGISTER THE SPILL MAP WAS STILL DESCRIBING
// (GAP-148).
//
// `emitSaveCallerRegs` builds its save set from `used_regs`, and `spillReg`
// CLEARS `used_regs[victim]`. So "x0 is not in the save set" — the question the
// call-result arm asked — is true in two states, not one: x0 is idle, or x0 was
// spilled and the frame holds its value for an owner whose reads are still
// ahead. The arm read them as one and gave the callee's answer to x0 in both.
//
// In the second state that is one register with two owners, this gap's shape,
// and it fails in both directions at once. `temps[result] = 0` while the spilled
// owner's own id also names 0, so the next read of EITHER reaches
// `ensureRegLiveRemap`, which reloads the frame copy and rewrites every `temps`
// entry naming 0 to the register it loaded into — the call's answer silently
// becomes the pre-call value of an unrelated binding. And `gp_reg_owner[0]`,
// which `spillReg` deliberately preserved, still names the spilled owner, so
// `sweepGpLive` reads it dead at this index and clears `used_regs[0]` for the
// register the answer was just given.
//
// The entry cannot be retired to make room: its value is not the call's, and
// dropping the only thing that reloads it is the abandonment
// `reclaimSpilledReg` documents. So the answer takes a register the map does not
// name — the question `allocRegOutsideSaveSet` already asks of every candidate
// it considers, for this reason — and is copied out of x0 by a move that does
// not consult the map, because after `bl` no entry describes x0's contents.
//
// Built directly rather than through a source program for the same reason as the
// reclaim, reload, remap, release, home, unwind, hoist, store and spill-band
// tests above:
// this is a state the allocator passes through between a spill of an ABI
// register and the next call, not a state a fixture names.
test "a call result refuses the ABI register the spill map still names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` is empty everywhere else,
    // the guard this test names is false, and the arm is the one it always was.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // The state `spillReg` leaves behind on x0: value in a frame slot, entry
    // reserving the register to it, `used_regs` clear, and the owner record
    // preserved across the store so the sweep can still release it. Only the
    // third spill pass in `allocRegExcluding` reaches x0..x7, which is why this
    // is gate transport's state and nobody else's.
    const spilled: u5 = 0;
    const off: u16 = 8;
    const owner_id: u32 = 41;
    try compiler.spilled_regs.put(alloc, spilled, off);
    compiler.used_regs[spilled] = false;
    compiler.gp_reg_owner[spilled] = owner_id;
    try temps.put(alloc, owner_id, spilled);

    // A SECOND spilled register the call does not name, to show the repair
    // takes nothing from anyone else.
    const bystander: u5 = 11;
    const bystander_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, bystander, bystander_off);
    compiler.used_regs[bystander] = false;

    // A call with no operand: nothing touches x0 before the save, so the entry
    // is still standing when the result arm runs. `preserveArgReg` would have
    // reloaded it on an operand path; `.void` is the shape that reaches here.
    const result_id: u32 = 7;
    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .call_direct,
        .result = result_id,
        .lhs = .void,
        .callee = "f",
        .ty = .i64,
    }, &branch_patches, null, 0);

    // THE ANSWER IS NOT IN x0. This is the whole fact: x0 is spoken for, and the
    // register that carries the result is one `allocRegOutsideSaveSet` proved
    // free — x9, the first it scans.
    const dst: u5 = 9;
    try std.testing.expectEqual(@as(?u5, dst), temps.get(result_id));
    try std.testing.expect(compiler.used_regs[dst]);

    // Nothing was taken from the spilled owner: the entry stands, its slot is
    // not in the free pool, `used_regs` is still clear, and the owner record
    // `sweepGpLive` will release it by is untouched.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(spilled));
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[spilled]);
    try std.testing.expectEqual(@as(?u32, owner_id), compiler.gp_reg_owner[spilled]);
    try std.testing.expectEqual(@as(?u16, bystander_off), compiler.spilled_regs.get(bystander));

    // SIX INSTRUCTIONS, AND NONE OF THEM RELOADS x0. `sub sp` / `str x30` /
    // `bl` / `mov x9, x0` / `ldr x30` / `add sp` — the save area, the call, the
    // copy out, and the restore. An `ldr x0, [sp, #…]` anywhere in this window
    // would be the frame copy landing over the callee's answer, at an offset
    // measured from a stack pointer the save area has already moved.
    try std.testing.expectEqual(before + 24, compiler.code.items.len);
    const want_mov: u32 = 0xaa0003e0 | (@as(u32, spilled) << 16) | @as(u32, dst);
    try std.testing.expectEqual(
        want_mov,
        std.mem.readInt(u32, compiler.code.items[before + 12 ..][0..4], .little),
    );
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const reload_word: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, spilled);
    var i: usize = before;
    while (i < compiler.code.items.len) : (i += 4) {
        try std.testing.expect(
            std.mem.readInt(u32, compiler.code.items[i..][0..4], .little) != reload_word,
        );
    }

    // AND THE FAILURE ITSELF. Reading the spilled owner reloads its frame copy
    // and remaps every `temps` entry that named x0. With the answer parked in
    // x0 the remap takes the answer with it and the two ids come back as one
    // register; here the owner moves alone and the answer stays where the call
    // put it.
    const owner_reg = try compiler.evalDnirValue(&temps, .{ .temp = owner_id });
    try std.testing.expectEqual(@as(?u5, owner_reg), temps.get(owner_id));
    try std.testing.expectEqual(@as(?u5, dst), temps.get(result_id));
    try std.testing.expect(owner_reg != dst);
    try std.testing.expectEqual(@as(?u32, owner_id), compiler.gp_reg_owner[owner_reg]);
    try std.testing.expect(!compiler.spilled_regs.contains(spilled));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);
}

// THE ARGUMENT REGISTER WAS PRESERVED INTO ITSELF (GAP-148).
//
// `preserveArgReg` exists to move a live value OUT of an x0..x7 slot before the
// caller stages an argument into it. It asked `allocReg` for the destination,
// and `allocReg` is `allocRegExcluding(null)`: when x9..x28 are all busy its
// x0..x7 fallback scans from x0 up and returns the slot itself, because
// `used_regs[slot]` is false — the released-but-still-named state that is what
// makes a victim findable here in the first place. The old arm read `fresh ==
// slot` as "nothing to do", released it, and returned, so the argument the
// caller wrote one instruction later landed on top of the value, and every id
// that named the slot read the argument instead. One register, two owners: this
// gap's shape, reached through the allocator rather than through the
// marshaling.
//
// Not gate transport. The free scan reaches this with `spilled_regs` empty, so
// unlike the spill, reclaim, reload, remap, release, home, unwind, hoist, store,
// band and call-result faces above, the bound this one carries is register
// pressure alone — nineteen busy registers and an ABI slot that a
// `releaseDnirTemp` freed without unnaming.
//
// Built directly rather than through a source program for the same reason as
// those: it is a state the allocator passes through, not one a fixture names.
test "an argument register is not preserved into itself" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    // The pressure that sends the allocator to its x0..x7 fallback: every
    // register the first scan walks is busy. x18 is the platform register and
    // is not in the pool either way.
    var reg: u5 = 9;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;

    // The slot being marshaled into, in the state `preserveArgReg` is called
    // for: unclaimed, so the fallback scan will offer it, and named by two ids
    // at once — the binding and the value that produced it, which is the pair
    // the function's own comment says must both travel.
    const slot: u5 = 0;
    const binding_id: u32 = 12;
    const value_id: u32 = 13;
    compiler.used_regs[slot] = false;
    try temps.put(alloc, binding_id, slot);
    try temps.put(alloc, value_id, slot);

    // One register left for the value to go to, and it is not x0. x1 and x2 are
    // busy so the destination is x3 whichever way the scan is entered, which is
    // what makes the emitted move exact below.
    compiler.used_regs[1] = true;
    compiler.used_regs[2] = true;
    compiler.used_regs[3] = false;
    reg = 4;
    while (reg < 8) : (reg += 1) compiler.used_regs[reg] = true;

    try compiler.preserveArgReg(&temps, &pinned, slot, 0);

    // THE VALUE LEFT x0. Both ids name the destination, it is claimed, and the
    // slot is free for the argument the caller stages next.
    const fresh: u5 = 3;
    try std.testing.expectEqual(@as(?u5, fresh), temps.get(binding_id));
    try std.testing.expectEqual(@as(?u5, fresh), temps.get(value_id));
    try std.testing.expect(compiler.used_regs[fresh]);
    try std.testing.expect(!compiler.used_regs[slot]);

    // And the move is really there. The old arm emitted nothing at all, which
    // is the whole of the failure: the value stayed in x0 and the argument was
    // written over it.
    try std.testing.expectEqual(@as(usize, 4), compiler.code.items.len);
    const mov_word: u32 = 0xaa0003e0 | (@as(u32, slot) << 16) | @as(u32, fresh);
    try std.testing.expectEqual(
        mov_word,
        std.mem.readInt(u32, compiler.code.items[0..4], .little),
    );
}

// AND THE COST OF THE EXCLUSION, STATED (GAP-148).
//
// With the slot excluded, a pool that has nothing else to give refuses rather
// than relocating. That is the trade this file makes everywhere else — a
// refusal is a bail while the alternative is a wrong answer — and it is worth a
// test of its own because it is what the previous arm bought its silence with:
// the old code answered this state by returning the slot, doing nothing, and
// letting the argument overwrite the value.
test "preserving an argument register refuses when the pool has only that register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    var reg: u5 = 9;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;
    reg = 1;
    while (reg < 8) : (reg += 1) compiler.used_regs[reg] = true;

    const slot: u5 = 0;
    const owner_id: u32 = 12;
    compiler.used_regs[slot] = false;
    try temps.put(alloc, owner_id, slot);

    // Outside gate transport `allocRegExcluding` refuses above its spill passes,
    // so this is the whole answer the allocator has.
    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.preserveArgReg(&temps, &pinned, slot, 0),
    );

    // Nothing was emitted and nothing was moved: the refusal is a bail, and the
    // caller's `try` carries it out of the function before an argument is
    // staged over anything.
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, slot), temps.get(owner_id));
}

// A DEAD NAME IN AN ARGUMENT REGISTER BOUGHT A RELOCATION AND A BAIL (GAP-148).
//
// The exclusion above is the repair that stopped `preserveArgReg` handing the
// argument's own slot back as the destination, and it left a cost this gap
// recorded and did not pay: nothing removes a `temps` entry when its value
// dies — `sweepGpLive` clears `gp_reg_owner` and `used_regs` and leaves `temps`
// alone — so an id whose last read is already behind emission goes on naming an
// ABI register for the rest of the function. The victim scan found that name,
// could not tell it from a live one, and asked for somewhere to put a value
// nobody would read again: a move and a register when the pool had one, and
// `error.RegisterExhausted` — a refused program — when it did not.
//
// `value_free_at` is the fact that separates them and it is not a new one; it
// is what `sweepGpLive` reads one line later in the same driver iteration. What
// was missing was the index to read it against, which is why `compileDnirInstr`,
// the two if-conversion emitters and the tail-call emitter now carry `at` down
// to this function.
//
// The boundary is `last < at` and not the sweep's `last <= idx`: the sweep runs
// AFTER the instruction at `idx` and may retire an id that instruction read,
// while this runs BEFORE the marshaling it guards completes, so an id whose
// last read IS the call being marshaled is still owed its value. Both sides of
// that boundary are asserted below.
//
// Not gate transport, like the two faces above it: `spilled_regs` is empty and
// the bound is register pressure alone. Not the closure either — closure is
// authoritative `register`/`frame` assignment before emission, per this gap's
// record, under which a value's liveness is carried by the assignment rather
// than recovered from a map that outlives it.
test "a dead name in an argument register does not buy it a relocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    // The state the marshaling arms call this function in: the slot unclaimed —
    // released by `releaseDnirTemp` without being unnamed, which is what makes
    // a victim findable here at all — and still named by an id whose last read
    // the function-wide liveness pass put at instruction 3.
    const slot: u5 = 0;
    const id: u32 = 12;
    const died_at: u32 = 3;
    try compiler.value_free_at.put(alloc, id, died_at);
    try temps.put(alloc, id, slot);

    // The same pressure the two tests above build: every register the first
    // scan walks is busy and so is every ABI register but the slot itself, so
    // the exclusion has nothing at all to give.
    var reg: u5 = 1;
    while (reg < 29) : (reg += 1) compiler.used_regs[reg] = true;
    compiler.used_regs[slot] = false;

    // (A) THE NAME IS BEHIND EMISSION. This is instruction 4 and the id was
    //     last read at 3, so nothing reads x0 again and the argument may land
    //     on it. No move, no register — and the differential this test turns
    //     on, no bail: the old scan asked the empty pool for a destination and
    //     the `try` carried `error.RegisterExhausted` out of a program that had
    //     no live value in the slot.
    try compiler.preserveArgReg(&temps, &pinned, slot, died_at + 1);
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, slot), temps.get(id));
    try std.testing.expect(!compiler.used_regs[slot]);

    // (B) AND IT DOES NOT SPEND A REGISTER EITHER. Hand the pool exactly one
    //     and it is still free afterwards: the skip is the refusal's cost
    //     removed, not the refusal itself in another spelling.
    const fresh: u5 = 3;
    compiler.used_regs[fresh] = false;
    try compiler.preserveArgReg(&temps, &pinned, slot, died_at + 1);
    try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, slot), temps.get(id));
    try std.testing.expect(!compiler.used_regs[fresh]);

    // (C) THE BOUNDARY IS ON THE LIVE SIDE. At the instruction that IS the id's
    //     last read the value is still owed one, so the identical state
    //     relocates — into the one register the pool now has — and every id
    //     that named the slot travels, exactly as before this change.
    try compiler.preserveArgReg(&temps, &pinned, slot, died_at);
    try std.testing.expectEqual(@as(?u5, fresh), temps.get(id));
    try std.testing.expect(compiler.used_regs[fresh]);
    try std.testing.expect(!compiler.used_regs[slot]);
    try std.testing.expectEqual(@as(usize, 4), compiler.code.items.len);
    const mov_word: u32 = 0xaa0003e0 | (@as(u32, slot) << 16) | @as(u32, fresh);
    try std.testing.expectEqual(
        mov_word,
        std.mem.readInt(u32, compiler.code.items[0..4], .little),
    );

    // (D) AND THE TRADE THE EXCLUSION MAKES FOR A LIVE VALUE IS UNTOUCHED. The
    //     relocation above claimed the last register, so a live id in the slot
    //     meets the empty pool again and the answer is still the bail — which
    //     is what the test above measures and what this one must not have
    //     quietly removed.
    try temps.put(alloc, id, slot);
    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.preserveArgReg(&temps, &pinned, slot, died_at),
    );
    try std.testing.expectEqual(@as(usize, 4), compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, slot), temps.get(id));
}

// A PACK RESULT TOOK THE ABI REGISTER THE SPILL MAP WAS STILL DESCRIBING
// (GAP-148).
//
// The call-result face above asked "is x0 in the save set" and read a spilled
// register as an idle one. The pack asks the same question in its own words —
// `used_regs[i]` — and read it the same wrong way, because `spillReg` CLEARS
// `used_regs[victim]`: the store that moved the value to the frame is what
// makes the register look free here, while `spilled_regs` still reserves it to
// its owner and `gp_reg_owner[i]` still names that owner.
//
// With no conflict declared the pack arm claims x_i for the callee's answer and
// publishes `temps[temp] = i`. One register, two owners. The next read of the
// spilled owner reloads its frame copy into x_i, over the answer, or remaps it
// out and takes the answer's id along; and `sweepGpLive`, reading the preserved
// owner record dead at this index, clears `used_regs[i]` for the register the
// answer was just given.
//
// The callee wrote x_i and no other register can answer for it, so the repair
// is not a different destination but the park the conflict path already has:
// the pack is stored to the frame at the call and reloaded into registers
// `allocReg` proves free — both of its free scans skip anything `spilled_regs`
// contains.
//
// Built directly rather than through a source program for the same reason as
// the reclaim, reload, remap, release, home, unwind, hoist, store, band and
// call-result tests above: this is a state the allocator passes through between
// a spill of an ABI register and the next call, not a state a fixture names.
test "a pack result refuses the ABI register the spill map still names" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` is empty everywhere else,
    // the term this test names is false, and the conflict is the one it always
    // was.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 64;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // The state `spillReg` leaves behind on x1 — the SECOND pack slot, so the
    // first is an ordinary idle register and the differential is the spill
    // alone: value in a frame slot, entry reserving the register to it,
    // `used_regs` clear, and the owner record preserved across the store so the
    // sweep can still release it.
    const spilled: u5 = 1;
    const off: u16 = 8;
    const owner_id: u32 = 41;
    try compiler.spilled_regs.put(alloc, spilled, off);
    compiler.used_regs[spilled] = false;
    compiler.gp_reg_owner[spilled] = owner_id;
    try temps.put(alloc, owner_id, spilled);

    // A two-value pack with no operand: nothing touches x0 or x1 before the
    // save, so the entry is still standing when the pack arm runs.
    const first: u32 = 7;
    const second: u32 = 8;
    const pack = [_]dnir.PackResult{
        .{ .value = 100, .temp = first, .ty = .i64 },
        .{ .value = 101, .temp = second, .ty = .i64 },
    };
    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .call_direct,
        .lhs = .void,
        .callee = "f",
        .ty = .i64,
        .pack_results = &pack,
    }, &branch_patches, null, 0);

    // NEITHER ANSWER IS IN AN ABI REGISTER. The park took both to the frame and
    // brought them back in the two registers `allocReg` scans first, which is
    // the whole fact: x1 is spoken for, and the pack cannot keep a register the
    // map is still describing merely because the callee wrote it.
    try std.testing.expectEqual(@as(?u5, 10), temps.get(second));
    try std.testing.expectEqual(@as(?u5, 9), temps.get(first));
    try std.testing.expect(compiler.used_regs[9] and compiler.used_regs[10]);

    // Nothing was taken from the spilled owner: the entry stands, its slot is
    // not in the free pool, `used_regs` is still clear, and the owner record
    // `sweepGpLive` will release it by is untouched.
    try std.testing.expectEqual(@as(?u16, off), compiler.spilled_regs.get(spilled));
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[spilled]);
    try std.testing.expectEqual(@as(?u32, owner_id), compiler.gp_reg_owner[spilled]);

    // AND NO RELOAD OF x1 ANYWHERE IN THE WINDOW. The park moves `sp` twice,
    // and a spill-slot offset is measured from the frame base; an `ldr x1,
    // [sp, #…]` emitted between those two moves would read the wrong slot and
    // land over the callee's answer besides.
    const reload_off: u16 = compiler.stack_frame_bytes - off - 8;
    const reload_word: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, spilled);
    var i: usize = before;
    while (i < compiler.code.items.len) : (i += 4) {
        try std.testing.expect(
            std.mem.readInt(u32, compiler.code.items[i..][0..4], .little) != reload_word,
        );
    }

    // AND THE FAILURE ITSELF. Reading the spilled owner reloads its frame copy
    // and remaps every `temps` entry that named x1. With the second answer
    // parked in x1 the remap takes that answer with it and the two ids come
    // back as one register; here the owner moves alone and both answers stay
    // where the park put them.
    const owner_reg = try compiler.evalDnirValue(&temps, .{ .temp = owner_id });
    try std.testing.expectEqual(@as(?u5, owner_reg), temps.get(owner_id));
    try std.testing.expect(owner_reg != 9 and owner_reg != 10);
    try std.testing.expectEqual(@as(?u5, 9), temps.get(first));
    try std.testing.expectEqual(@as(?u5, 10), temps.get(second));
    try std.testing.expectEqual(@as(?u32, owner_id), compiler.gp_reg_owner[owner_reg]);
    try std.testing.expect(!compiler.spilled_regs.contains(spilled));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);
}

// AN IF-CONVERTED ARM'S ANSWER IS A LIVE VALUE, AND THE RECLAIM MAY NOT BID FOR
// IT (GAP-148).
//
// `emitIfConverted` computes the arm unconditionally into `dst`, then evaluates
// the condition, then selects. The ownership record that says `dst` holds a live
// value used to be written AFTER the select, so across the whole condition the
// arm's answer sat in a register `gp_reg_owner` called empty.
//
// That is the one entry `reclaimSpilledReg` bids for. Its skip list is
// `exclude`, a home, a pin, a staged argument, a staged tail — and an OWNED
// entry, which is the rule that a spilled register's frame slot is the only
// remaining location of a live value and may not be retired. An UNOWNED entry is
// by that same rule a stale name left by register staging, and free to take.
//
// The condition allocates: an immediate operand is `allocReg`. Under gate
// transport an allocation that fails runs the entire cascade — every free scan
// skips `spilled_regs`, so a spill frees nothing and the passes walk x28..x9 and
// x7..x0 spilling everything, `dst` among them — and ends at the reclaim, which
// finds `dst` unowned, drops the entry, releases the slot, claims the register
// and hands it back as the condition's own scratch. `evalDnirValue`'s
// `emitMovImm` then writes the condition's immediate over the arm's computed
// value, and the `csel` selects between that immediate and the binding's old
// value. A wrong answer with no diagnostic, on the register the transform exists
// to produce.
//
// Built directly rather than through a source program for the same reason as the
// reclaim, reload, remap, release, home, unwind, hoist, store, band, call-result
// and pack tests above: this needs an exhausted register pool at the exact
// instant a folded `if` evaluates its condition, which is a state the allocator
// passes through and not one a fixture names.
test "an if-converted arm's answer is not reclaimable while the condition allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` stays empty everywhere else
    // and this whole path is unreachable.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // THE POOL, arranged so the cascade has exactly one victim and the reclaim
    // exactly one candidate — otherwise the victim is hash order's to choose and
    // the differential is not the change's.
    //
    // x9 and x10 are the two bindings' homes, and x12..x28 stand for a body that
    // already used the bank. All of them are `gp_call_home_regs` as well, so both
    // spill passes pass over them: the first skips every home, the second skips
    // that mask. x0..x7 are staged arguments, which both the free scan and the
    // third spill pass skip. x11 is the only register left, and it is the one
    // `allocRegExcluding` hands the arm.
    const binding: u32 = 1;
    const other: u32 = 2;
    const home_lhs: u5 = 9;
    const home_rhs: u5 = 10;
    for ([_]u5{ home_lhs, home_rhs }) |r| {
        compiler.gp_home_regs[r] = true;
        compiler.used_regs[r] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << r;
    }
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, binding, home_lhs);
    try temps.put(alloc, other, home_rhs);

    // `binding = binding + other` under a condition that is an immediate — the
    // immediate is what makes the condition allocate.
    const arm_temp: u32 = 50;
    const plan = Arm64Compiler.IfConvPlan{
        .cmp = null,
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .i64 = 7 },
            .ty = .i64,
        },
        .op = .{
            .op = .binop,
            .binop = .add,
            .ty = .i64,
            .lhs = .{ .local = binding },
            .rhs = .{ .local = other },
            .result = arm_temp,
        },
        .store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .temp = arm_temp },
            .result = binding,
        },
        .extra = 3,
    };

    // THE POOL IS GENUINELY EMPTY AT THE CONDITION, so the answer is a refusal —
    // the bail this allocator already answers with — and not a register taken
    // from the value the fold just computed.
    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConverted(&temps, &pinned, plan, &branch_patches, 0),
    );

    // AND THE ARM'S VALUE IS STILL WHERE THE SPILL PUT IT. The entry stands, its
    // slot is not in the free pool, and the owner record that made it
    // unreclaimable names the arm's temp. Without that record the reclaim
    // retires all three and returns x11 as the condition's scratch.
    const arm_reg: u5 = 11;
    try std.testing.expectEqual(@as(?u16, 0), compiler.spilled_regs.get(arm_reg));
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(@as(?u32, arm_temp), compiler.gp_reg_owner[arm_reg]);
    try std.testing.expect(!compiler.used_regs[arm_reg]);

    // AND THE ARM WAS COMPUTED INTO x11 BEFORE ANY OF IT — the `add` is present
    // and the condition's `movz x11, #7`, which is what the reclaim's register
    // would have carried, is not.
    const add_word: u32 = 0x8b000000 | (@as(u32, home_rhs) << 16) | (@as(u32, home_lhs) << 5) | arm_reg;
    const movz_word: u32 = 0xd2800000 | (@as(u32, 7) << 5) | arm_reg;
    var saw_add = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == add_word) saw_add = true;
        try std.testing.expect(word != movz_word);
    }
    try std.testing.expect(saw_add);
}

// A ZERO-OP ARM'S ANSWER IS HELD IN NO MAP AT ALL (GAP-148).
//
// `emitIfConvArm` answers an arm with no ops by evaluating the store's operand
// directly, and for an immediate that is `allocReg` plus `emitMovImm` — a fresh
// register carrying the arm's whole value with nothing recording that it does.
// `used_regs` keeps the free scans off it and is the exact bit the spill passes
// require, so under gate transport the NEXT exhausted allocation spills it and
// reaches `reclaimSpilledReg`, whose skip list is `exclude`, a home, a pin, a
// staged argument, a staged tail and an OWNED entry. An unowned entry is by that
// same rule a stale name register staging left behind, and free to take.
//
// Here the next allocation is the other arm's, and after it the destination's
// and the condition's. The reclaim drops the entry, releases the slot, claims
// the register and hands it back, and `emitMovImm` writes the new operand over
// the arm's value; the `csel` then selects that operand as the arm's answer.
//
// The pool below is arranged so the then arm gets x11 and the destination x16,
// and so the CONDITION is the allocation that runs out — the cascade spills both
// and the reclaim finds x16 owned (the select's carrier, recorded by the repair
// this file's previous section landed) and x11 not. With x11 held the cascade
// refuses instead, which is the bail this allocator already answers with when
// the pool is genuinely empty; without it the emitter runs to completion and
// emits `movz x11, #7` over the arm's `movz x11, #5` and a `csel` that selects
// the condition's own operand.
//
// Built directly rather than through a source program for the same reason as
// every reclaim test above: this needs an exhausted register pool at the exact
// instant a folded two-sided `if` evaluates its condition, which is a state the
// allocator passes through and not one a fixture names.
test "a zero-op if-conversion arm's answer is not reclaimable while the condition allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` stays empty everywhere else
    // and this whole path is unreachable.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // THE POOL. x10 is the else arm's binding home; x9 and x12..x28 except x16
    // stand for a body that already used the bank. All of them are
    // `gp_call_home_regs` as well, so both spill passes pass over them: the
    // first skips every home, the second skips that mask. x0..x7 are staged
    // arguments, which both the free scan and the third spill pass skip. That
    // leaves exactly x11 and x16, in that order — the arm's and the select's.
    const binding: u32 = 1;
    const other: u32 = 2;
    const arm_reg: u5 = 11;
    const sel_reg: u5 = 16;
    const home_other: u5 = 10;
    compiler.gp_home_regs[9] = true;
    compiler.used_regs[9] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << 9;
    compiler.gp_home_regs[home_other] = true;
    compiler.used_regs[home_other] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_other;
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        if (busy == sel_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, other, home_other);

    // The binding lives in the frame, so the store at the end of the emitter is
    // an `str` and allocates nothing — the control arm has to be able to RUN to
    // completion for its wrong answer to be the differential.
    try compiler.gp_stack_locals.put(alloc, binding, 64);

    // `if <imm> then binding = 5 else binding = other` — the then arm has NO
    // ops, so its answer is `movz x11, #5` and nothing else, and the condition
    // is an immediate, which is what makes the condition allocate.
    const arm_imm: i64 = 5;
    const cond_imm: i64 = 7;
    const plan = Arm64Compiler.TwoSidedPlan{
        .cmp = null,
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .i64 = cond_imm },
            .ty = .i64,
        },
        .then_ops = &.{},
        .then_store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .i64 = arm_imm },
            .result = binding,
        },
        .else_ops = &.{},
        .else_store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .local = other },
            .result = binding,
        },
        .extra = 5,
    };

    // THE POOL IS GENUINELY EMPTY AT THE CONDITION, so the answer is a refusal
    // and not a register taken from the arm the fold just computed.
    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConvertedTwoSided(&temps, &pinned, plan, &branch_patches, 0),
    );

    // AND THE ARM'S VALUE IS STILL WHERE THE SPILL PUT IT. The entry stands, its
    // slot is not back in the free pool, and the record that made it
    // unreclaimable is present. Without the hold the reclaim retires this entry,
    // returns x11 as the condition's scratch, and the emitter runs on.
    try std.testing.expect(compiler.spilled_regs.get(arm_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[arm_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[arm_reg]);

    // AND THE ARM WAS COMPUTED INTO x11 BEFORE ANY OF IT — the arm's own
    // `movz x11, #5` is present and the condition's `movz x11, #7`, which is
    // what the reclaim's register would have carried, is not.
    const arm_word: u32 = 0xd2800000 | (@as(u32, @intCast(arm_imm)) << 5) | arm_reg;
    const cond_word: u32 = 0xd2800000 | (@as(u32, @intCast(cond_imm)) << 5) | arm_reg;
    var saw_arm = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == arm_word) saw_arm = true;
        try std.testing.expect(word != cond_word);
    }
    try std.testing.expect(saw_arm);
}

// AND THE ONE-SIDED SELECT'S OTHER OPERAND IS THE SAME BID (GAP-148).
//
// `emitIfConverted`'s step (1) loads the binding's current value — the arm's
// "else" — and for a FRAME-homed binding that is `loadGpStackLocal`: `allocReg`
// plus an `ldr`, recording no owner. `allocRegExcluding(old)` covers it for the
// arm's own allocation at step (2), and the condition at step (3) excludes
// nothing. So `old` reaches the reclaim as an unowned entry exactly as `dst`
// used to, and the register handed back is written by `emitMovImm` before the
// `csel` reads it as the binding's previous value.
//
// Same pool shape as the test above: x11 is `old`, x16 is `dst`, and the
// condition is the allocation that runs out.
test "the if-converted select's fallback operand is not reclaimable either" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const binding: u32 = 1;
    const other: u32 = 2;
    const old_reg: u5 = 11;
    const sel_reg: u5 = 16;
    const home_other: u5 = 10;
    compiler.gp_home_regs[9] = true;
    compiler.used_regs[9] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << 9;
    compiler.gp_home_regs[home_other] = true;
    compiler.used_regs[home_other] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_other;
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        if (busy == sel_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, other, home_other);
    // FRAME-HOMED, which is what makes step (1) a fresh unowned register rather
    // than a home the reclaim already passes over.
    try compiler.gp_stack_locals.put(alloc, binding, 64);

    const cond_imm: i64 = 7;
    const arm_temp: u32 = 50;
    const plan = Arm64Compiler.IfConvPlan{
        .cmp = null,
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .i64 = cond_imm },
            .ty = .i64,
        },
        .op = .{
            .op = .binop,
            .binop = .add,
            .ty = .i64,
            .lhs = .{ .local = binding },
            .rhs = .{ .local = other },
            .result = arm_temp,
        },
        .store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .temp = arm_temp },
            .result = binding,
        },
        .extra = 3,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConverted(&temps, &pinned, plan, &branch_patches, 0),
    );

    // The binding's previous value is still in the frame slot the spill gave it.
    try std.testing.expect(compiler.spilled_regs.get(old_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[old_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[old_reg]);

    // The `ldr` that established it is present and the condition's
    // `movz x11, #7` is not.
    const cond_word: u32 = 0xd2800000 | (@as(u32, @intCast(cond_imm)) << 5) | old_reg;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        try std.testing.expect(word != cond_word);
    }
    const add_word: u32 = 0x8b000000 | (@as(u32, home_other) << 16) | (@as(u32, old_reg) << 5) | sel_reg;
    var saw_add = false;
    i = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == add_word) saw_add = true;
    }
    try std.testing.expect(saw_add);
}

// AND THE LEFT OPERAND OF THE ARM'S OWN BINOP IS THE SAME BID (GAP-148).
//
// The two sections above hold the registers the two if-conversion emitters
// carry ACROSS a step: the binding's previous value, and a zero-op arm's
// answer. The register left over is the one carried across a single LINE — the
// left operand of a two-operand evaluation. `emitIfConverted` establishes `a`
// and immediately evaluates `plan.op.rhs`, which excludes nothing: an immediate
// is `allocReg` plus `emitMovImm`, and under gate transport an exhausted
// `allocReg` runs the whole cascade, spills `a` among everything else, and ends
// at `reclaimSpilledReg`, whose skip list treats an entry with a NULL owner as
// a stale name register staging left behind and free to take.
//
// The reclaim hands `a`'s register back as the RIGHT operand's own scratch,
// `emitMovImm` writes the right operand over the left, and
// `emitCompareOrBinop` computes the right operand against itself.
//
// The pool below leaves exactly x11 and x16 free, in that order, so `old` takes
// x11 and the left operand x16, and the RIGHT operand's evaluation is the
// allocation that runs out. The condition reads a homed local and allocates
// nothing, so the control arm — this repair reverted — runs the emitter to
// COMPLETION and emits `movz x16, #7` over the left operand's `movz x16, #5`.
// With the hold the cascade refuses instead, which is the bail this allocator
// already answers with when the pool is genuinely empty.
//
// Built directly rather than through a source program for the reason every
// reclaim test in this file states: this needs an exhausted register pool at
// the exact instant a folded `if` evaluates its arm's second operand, which is
// a state the allocator passes through and not one a fixture names.
test "the if-converted arm's left operand is not reclaimable while its right operand allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // Spills exist only under gate transport: `allocRegExcluding` refuses above
    // its spill passes otherwise, so `spilled_regs` stays empty everywhere else
    // and this whole path is unreachable.
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const binding: u32 = 1;
    const other: u32 = 2;
    const old_reg: u5 = 11;
    const lhs_reg: u5 = 16;
    const home_other: u5 = 10;
    compiler.gp_home_regs[9] = true;
    compiler.used_regs[9] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << 9;
    compiler.gp_home_regs[home_other] = true;
    compiler.used_regs[home_other] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_other;
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        if (busy == lhs_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, other, home_other);
    // Frame-homed, so step (1) is `loadGpStackLocal` into x11 and the closing
    // store is an `str` that allocates nothing — the control arm has to be able
    // to RUN to completion for its wrong answer to be the differential.
    try compiler.gp_stack_locals.put(alloc, binding, 64);

    const lhs_imm: i64 = 5;
    const rhs_imm: i64 = 7;
    const arm_temp: u32 = 50;
    const plan = Arm64Compiler.IfConvPlan{
        .cmp = null,
        // The condition reads the homed local, so it allocates nothing and the
        // ONLY allocation that can run out is the right operand's.
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .local = other },
            .ty = .i64,
        },
        .op = .{
            .op = .binop,
            .binop = .add,
            .ty = .i64,
            .lhs = .{ .i64 = lhs_imm },
            .rhs = .{ .i64 = rhs_imm },
            .result = arm_temp,
        },
        .store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .temp = arm_temp },
            .result = binding,
        },
        .extra = 3,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConverted(&temps, &pinned, plan, &branch_patches, 0),
    );

    // The left operand is still where the spill put it: the entry stands, its
    // slot is not back in the free pool, and the record that made it
    // unreclaimable is present.
    try std.testing.expect(compiler.spilled_regs.get(lhs_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[lhs_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[lhs_reg]);

    // AND IT WAS COMPUTED INTO x16 BEFORE ANY OF IT — the left operand's own
    // `movz x16, #5` is present and the right operand's `movz x16, #7`, which
    // is what the reclaim's register would have carried, is not.
    const lhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(lhs_imm)) << 5) | lhs_reg;
    const rhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(rhs_imm)) << 5) | lhs_reg;
    var saw_lhs = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == lhs_word) saw_lhs = true;
        try std.testing.expect(word != rhs_word);
    }
    try std.testing.expect(saw_lhs);
    // The binding's previous value is untouched by this repair and still held
    // by the one the section above landed — which is why the reclaim passed
    // over x11 and reached the left operand at all.
    try std.testing.expect(compiler.gp_reg_owner[old_reg] != null);
}

// AND SO IS THE COMPARE'S LEFT OPERAND, IN THE ONE-SIDED EMITTER (GAP-148).
//
// Step (3) fuses a comparison into the condition's `cmp`, and it evaluates two
// operands on two consecutive lines with nothing excluded between them. `clhs`
// is therefore the same unowned live register as the arm's left operand above,
// and the reclaim handing it to `crhs` makes `emitCmpReg` compare the right
// operand against itself — the select then runs on a condition that is
// unconditionally equal. `ensureRegLive` inside `emitCmpReg` cannot help: the
// reclaim removed the entry it keys on.
//
// Three registers are free here rather than two, because this emitter
// establishes `old` and `dst` before the condition and both must land before
// `clhs` does: x11 is `old`, x16 is `dst`, x17 is `clhs`, and `crhs` is the
// allocation that runs out. The reclaim passes over x11 and x16 — the holds the
// two sections above landed — and finds x17.
test "the if-converted condition's left operand is not reclaimable while its right operand allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const binding: u32 = 1;
    const other: u32 = 2;
    const another: u32 = 3;
    const old_reg: u5 = 11;
    const sel_reg: u5 = 16;
    const clhs_reg: u5 = 17;
    const home_other: u5 = 10;
    const home_another: u5 = 9;
    compiler.gp_home_regs[home_another] = true;
    compiler.used_regs[home_another] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_another;
    compiler.gp_home_regs[home_other] = true;
    compiler.used_regs[home_other] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_other;
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        if (busy == sel_reg or busy == clhs_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, other, home_other);
    try temps.put(alloc, another, home_another);
    try compiler.gp_stack_locals.put(alloc, binding, 64);

    // BOTH ARM OPERANDS ARE HOMED LOCALS, so step (2) allocates only its
    // destination and the condition is the first thing that can exhaust.
    const clhs_imm: i64 = 5;
    const crhs_imm: i64 = 7;
    const arm_temp: u32 = 50;
    const plan = Arm64Compiler.IfConvPlan{
        .cmp = .{
            .op = .binop,
            .binop = .lt,
            .ty = .i64,
            .lhs = .{ .i64 = clhs_imm },
            .rhs = .{ .i64 = crhs_imm },
            .result = 60,
        },
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .temp = 60 },
            .ty = .i64,
        },
        .op = .{
            .op = .binop,
            .binop = .add,
            .ty = .i64,
            .lhs = .{ .local = other },
            .rhs = .{ .local = another },
            .result = arm_temp,
        },
        .store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .temp = arm_temp },
            .result = binding,
        },
        .extra = 4,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConverted(&temps, &pinned, plan, &branch_patches, 0),
    );

    try std.testing.expect(compiler.spilled_regs.get(clhs_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[clhs_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[clhs_reg]);

    // The arm's `add x16, x10, x9` and the compare's own `movz x17, #5` are
    // present; `movz x17, #7`, which is what the reclaim's register would have
    // carried, is not.
    const clhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(clhs_imm)) << 5) | clhs_reg;
    const crhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(crhs_imm)) << 5) | clhs_reg;
    const add_word: u32 = 0x8b000000 | (@as(u32, home_another) << 16) | (@as(u32, home_other) << 5) | sel_reg;
    var saw_clhs = false;
    var saw_add = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == clhs_word) saw_clhs = true;
        if (word == add_word) saw_add = true;
        try std.testing.expect(word != crhs_word);
    }
    try std.testing.expect(saw_clhs);
    try std.testing.expect(saw_add);
    // `old` is untouched by this repair and still held by the previous one.
    try std.testing.expect(compiler.gp_reg_owner[old_reg] != null);
}

// AND IN THE TWO-SIDED EMITTER, WHICH IS THE SAME THREE LINES (GAP-148).
//
// `emitIfConvertedTwoSided` computes both arms, then the destination, then the
// condition — so by the time the condition runs, `rt`, `re` and `dst` are all
// held or owned and `clhs` is the ONLY entry the reclaim can still take. Taking
// it makes the `cmp` read its right operand twice and the `csel` select on a
// condition that is unconditionally equal.
//
// Both arms answer with a homed local and allocate nothing, so x11 is `dst`,
// x16 is `clhs`, and `crhs` is the allocation that runs out.
test "the two-sided condition's left operand is not reclaimable while its right operand allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const binding: u32 = 1;
    const other: u32 = 2;
    const another: u32 = 3;
    const sel_reg: u5 = 11;
    const clhs_reg: u5 = 16;
    const home_other: u5 = 10;
    const home_another: u5 = 9;
    compiler.gp_home_regs[home_another] = true;
    compiler.used_regs[home_another] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_another;
    compiler.gp_home_regs[home_other] = true;
    compiler.used_regs[home_other] = true;
    compiler.gp_call_home_regs |= @as(u32, 1) << home_other;
    var busy: u5 = 12;
    while (busy <= 28) : (busy += 1) {
        if (busy == clhs_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
    try temps.put(alloc, other, home_other);
    try temps.put(alloc, another, home_another);
    try compiler.gp_stack_locals.put(alloc, binding, 64);

    const clhs_imm: i64 = 5;
    const crhs_imm: i64 = 7;
    const plan = Arm64Compiler.TwoSidedPlan{
        .cmp = .{
            .op = .binop,
            .binop = .lt,
            .ty = .i64,
            .lhs = .{ .i64 = clhs_imm },
            .rhs = .{ .i64 = crhs_imm },
            .result = 60,
        },
        .br = .{
            .op = .br,
            .branch_condition = .when_false,
            .branch_target = 4,
            .lhs = .{ .temp = 60 },
            .ty = .i64,
        },
        .then_ops = &.{},
        .then_store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .local = other },
            .result = binding,
        },
        .else_ops = &.{},
        .else_store = .{
            .op = .store_local,
            .ty = .i64,
            .lhs = .{ .local = another },
            .result = binding,
        },
        .extra = 6,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.emitIfConvertedTwoSided(&temps, &pinned, plan, &branch_patches, 0),
    );

    try std.testing.expect(compiler.spilled_regs.get(clhs_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[clhs_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[clhs_reg]);
    // The select's own destination carries the record the previous section
    // landed, so the reclaim passed over it and reached `clhs` alone.
    try std.testing.expect(compiler.gp_reg_owner[sel_reg] != null);

    const clhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(clhs_imm)) << 5) | clhs_reg;
    const crhs_word: u32 = 0xd2800000 | (@as(u32, @intCast(crhs_imm)) << 5) | clhs_reg;
    var saw_clhs = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == clhs_word) saw_clhs = true;
        try std.testing.expect(word != crhs_word);
    }
    try std.testing.expect(saw_clhs);
}

// AN ORDINARY BINOP'S OPERANDS ARE HELD IN LOCAL VARIABLES, AND NO MAP NAMES
// THEM (GAP-148).
//
// The three integer binop arms of `compileDnirInstr` evaluate an operand and
// then keep its register in a Zig local across the next operand's evaluation,
// across the destination's `allocReg`, and — for `idiv`/`mod` — across
// `emitFlooredDivRem`'s three `allocRegExcluding(dst)`. None of those excludes
// an operand. `evalDnirValue`'s constant, string and stack-local arms answer
// with a register `allocReg` recorded only in `used_regs`, so its
// `gp_reg_owner` is null, which is precisely the entry `reclaimSpilledReg`
// retires. `ensureRegLive` inside every register-form emitter reloads a merely
// SPILLED operand and cannot reload a reclaimed one: the reclaim removed the
// entry it keys on.
//
// Each test builds an `Arm64Compiler` directly, for the reason every reclaim
// test in this file states: the state under test needs an exhausted register
// pool at the exact instant a binop reaches its second allocation. The bank
// below leaves exactly ONE allocatable register free, so the cascade has a
// known victim list and the reclaim exactly one candidate — otherwise the
// victim is hash order's to choose and the differential is not this change's.
fn gap148BinopBank(compiler: *Arm64Compiler, free: u5) void {
    compiler.gate_transport = true;
    compiler.stack_frame_bytes = 336;
    compiler.gate_spill_base = 0;
    compiler.gate_spill_end = 256;
    compiler.gate_spill_cursor = 0;
    var busy: u5 = 9;
    while (busy <= 28) : (busy += 1) {
        if (busy == free) continue;
        if (busy == Arm64Compiler.platform_reserved_reg) continue;
        compiler.gp_home_regs[busy] = true;
        compiler.used_regs[busy] = true;
        compiler.gp_call_home_regs |= @as(u32, 1) << busy;
    }
    compiler.pending_arg_regs = 0xff;
}

fn gap148MovzWord(reg: u5, imm: u32) u32 {
    return 0xd2800000 | (imm << 5) | @as(u32, reg);
}

test "the binop's left operand is not reclaimable while its right operand allocates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    const lhs_reg: u5 = 16;
    gap148BinopBank(&compiler, lhs_reg);

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // A COMPARISON, so `constBinopRealization` refuses on its first line and
    // the general two-operand arm is the one reached.
    const ins = dnir.Instr{
        .op = .binop,
        .binop = .lt,
        .ty = .i64,
        .lhs = .{ .i64 = 5 },
        .rhs = .{ .i64 = 7 },
        .result = 40,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.compileDnirInstr(&temps, &pinned, ins, &branch_patches, null, 0),
    );

    // The left operand is still where the spill put it: the entry stands, its
    // slot is not back in the free pool, and the record that made it
    // unreclaimable is present.
    try std.testing.expect(compiler.spilled_regs.get(lhs_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[lhs_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[lhs_reg]);

    // AND IT WAS COMPUTED INTO x16 BEFORE ANY OF IT — the left operand's own
    // `movz x16, #5` is present and the right operand's `movz x16, #7`, which
    // is what the reclaim's register would have carried, is not.
    var saw_lhs = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == gap148MovzWord(lhs_reg, 5)) saw_lhs = true;
        try std.testing.expect(word != gap148MovzWord(lhs_reg, 7));
    }
    try std.testing.expect(saw_lhs);
}

// THE SAME OPERAND, IN THE INTEGER ARM OF A FLOAT KERNEL (GAP-148).
//
// `cur_func_float` selects a second copy of the two-operand sequence, reached
// whenever both operands of an instruction inside a float-returning function
// are integers. It holds `ilhs` across `irhs`'s evaluation on the same two
// consecutive lines.
test "the float kernel's integer binop left operand is not reclaimable either" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
