    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const ins = dnir.Instr{
        .op = .binop,
        .binop = .add,
        .ty = .i64,
        .lhs = .{ .i64 = 5 },
        .rhs = .{ .i64 = 3 },
        .result = 42,
    };

    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.compileDnirInstr(&temps, &pinned, ins, &branch_patches, null, 0),
    );

    try std.testing.expect(compiler.spilled_regs.get(lhs_reg) != null);
    try std.testing.expect(compiler.gp_reg_owner[lhs_reg] != null);
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);

    // `add x16, x16, #3` is the instruction the reclaimed destination would
    // have produced, and it is not here.
    const add_word: u32 = 0x91000000 | (@as(u32, 3) << 10) | (@as(u32, lhs_reg) << 5) | @as(u32, lhs_reg);
    var saw_lhs = false;
    var i: usize = 0;
    while (i + 4 <= compiler.code.items.len) : (i += 4) {
        const word = std.mem.readInt(u32, compiler.code.items[i..][0..4], .little);
        if (word == gap148MovzWord(lhs_reg, 5)) saw_lhs = true;
        try std.testing.expect(word != add_word);
    }
    try std.testing.expect(saw_lhs);
}

// THE GP->FP TRANSFER READ THE REGISTER, NOT THE VALUE (GAP-148).
//
// `spilled_regs` naming a register is this backend's statement that the value
// is in the frame and the register is not the answer, and every emitter that
// reads a general register as a SOURCE honours it by calling `ensureRegLive`
// first -- `emitAddImmSized`, `emitCmpReg`, `emitBitReg`, `emitStrIdx`,
// `emitVecLdrQPost16`, `emitMovReg`, `emitNarrowFit`, all of them. The two
// instructions that read a general register into the FLOAT file never asked.
//
// The widening caller compounds it from above: `evalDnirValueFp`'s `crossFile`
// arm reads `temps.get(id)` DIRECTLY rather than through `evalDnirValue`, so
// `ensureRegLiveRemap` does not run for it either and this emitter is the only
// place left where the question could be asked at all.
//
// The clobber does not need the pool to hand the register out. `spillReg`
// clears `used_regs`, and `used_regs` is the entire save set
// `emitSaveCallerRegs` builds, so the spill takes the integer out of the set
// while `temps` still names its register, the next `bl` clobbers x0..x17, and
// the conversion turns the call's leavings into a float. No diagnostic, and the
// asm reads exactly like the conversion it was written to be.
//
// Built directly rather than through a source program for the same reason as
// every test this gap has recorded: the state is one the allocator passes
// through between a spill and a read, not one a fixture names.
test "a general register read into the float file is reloaded first" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // The state `spillReg` leaves behind: the value is at `off`, the claim is
    // gone, and `gp_reg_owner` is preserved across the store so the sweep can
    // release it at the index it always would have.
    compiler.stack_frame_bytes = 32;
    const xreg: u5 = 11;
    const off: u16 = 8;
    const owner: u32 = 7;
    try compiler.spilled_regs.put(alloc, xreg, off);
    compiler.used_regs[xreg] = false;
    compiler.gp_reg_owner[xreg] = owner;

    const dreg: u5 = 3;
    try compiler.emitScvtfFromGpr(dreg, xreg);

    // The reload is there, and it is the `ldr` into the register every map
    // already names -- the same reload the home branch of `ensureRegLiveRemap`
    // performs, at the offset `spillReg` stored to.
    try std.testing.expectEqual(@as(usize, 8), compiler.code.items.len);
    const reload_off: u16 = 32 - off - 8;
    const ldr_word: u32 = 0xf94003e0 | ((@as(u32, reload_off) / 8) << 10) | @as(u32, xreg);
    try std.testing.expectEqual(
        ldr_word,
        std.mem.readInt(u32, compiler.code.items[0..4], .little),
    );
    const scvtf_word: u32 = 0x9e620000 | (@as(u32, xreg) << 5) | @as(u32, dreg);
    try std.testing.expectEqual(
        scvtf_word,
        std.mem.readInt(u32, compiler.code.items[4..8], .little),
    );

    // And the rest of the reload: the entry is retired by the removal that took
    // it, the slot is released exactly once, the claim the loaded value is owed
    // is paid, and the owner record is untouched.
    try std.testing.expect(!compiler.spilled_regs.contains(xreg));
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expectEqual(off, compiler.free_spill_slots.items[0]);
    try std.testing.expect(compiler.used_regs[xreg]);
    try std.testing.expectEqual(@as(?u32, owner), compiler.gp_reg_owner[xreg]);

    // FALSE ACCEPT: AN UNSPILLED SOURCE IS NOT RELOADED. The term is
    // `spilled_regs` and not a blanket `ldr` before every transfer, so a source
    // the map does not name emits the conversion alone and the pool is
    // untouched.
    const plain: u5 = 12;
    const before = compiler.code.items.len;
    try compiler.emitScvtfFromGpr(dreg, plain);
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(@as(usize, 1), compiler.free_spill_slots.items.len);
    try std.testing.expect(!compiler.used_regs[plain]);

    // The second transfer carries the same term.
    const other: u5 = 13;
    const other_off: u16 = 16;
    try compiler.spilled_regs.put(alloc, other, other_off);
    compiler.used_regs[other] = false;
    const at_fmov = compiler.code.items.len;
    try compiler.emitFmovFromGpr(dreg, other);
    try std.testing.expectEqual(at_fmov + 8, compiler.code.items.len);
    const other_reload: u16 = 32 - other_off - 8;
    const other_ldr: u32 = 0xf94003e0 | ((@as(u32, other_reload) / 8) << 10) | @as(u32, other);
    try std.testing.expectEqual(
        other_ldr,
        std.mem.readInt(u32, compiler.code.items[at_fmov..][0..4], .little),
    );
    const fmov_word: u32 = 0x9e670000 | (@as(u32, other) << 5) | @as(u32, dreg);
    try std.testing.expectEqual(
        fmov_word,
        std.mem.readInt(u32, compiler.code.items[at_fmov + 4 ..][0..4], .little),
    );
    try std.testing.expect(!compiler.spilled_regs.contains(other));

    // WRONG ERROR: THE DESTINATION SIDE IS NOT THE SOURCE SIDE. `emitFmovToGpr`
    // WRITES its `xreg`, and `spilled_regs` is keyed by GP index, so a reload
    // there would `ldr` a GP slot at an index taken from the FP operand. An
    // entry naming the destination survives untouched and nothing is emitted
    // but the transfer.
    const dst_gp: u5 = 14;
    const dst_off: u16 = 24;
    try compiler.spilled_regs.put(alloc, dst_gp, dst_off);
    const at_to_gpr = compiler.code.items.len;
    try compiler.emitFmovToGpr(dst_gp, dreg);
    try std.testing.expectEqual(at_to_gpr + 4, compiler.code.items.len);
    const to_gpr_word: u32 = 0x9e660000 | (@as(u32, dreg) << 5) | @as(u32, dst_gp);
    try std.testing.expectEqual(
        to_gpr_word,
        std.mem.readInt(u32, compiler.code.items[at_to_gpr..][0..4], .little),
    );
    try std.testing.expectEqual(@as(?u16, dst_off), compiler.spilled_regs.get(dst_gp));
    try std.testing.expectEqual(@as(usize, 2), compiler.free_spill_slots.items.len);
}

// THE WIDENING READ THE NAME AND NOT THE VALUE (GAP-148).
//
// `evalDnirValueFp`'s `crossFile` arm converts an INTEGER-classed value sitting
// in a float position, and to do that it needs a general register. It read one
// out of `temps` directly. `temps` is a name, and this backend already says so
// in the function that turns a name into a location: `evalDnirValue` consults
// `eval_pinned` above the map, refuses a name in x9..x28 whose `gp_reg_owner`
// does not match, and falls through to the frame home — the one place a local's
// value stays authoritative. A released register keeps its name (`emitPopVarargs`
// releases scratch the map still names; `sweepGpLive` frees by owner record and
// leaves the name alone), so the arm converted whatever the pool had since put
// there, and `scvtf` reads like the conversion it was written to be.
//
// Built directly rather than through a source program for the same reason as
// every test this gap has recorded: the state is one the allocator passes
// through between a release and a read, not one a fixture names.
test "the widening conversion reads the value's home, not a stale name" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // `fp_temps` does not hold the slot, so the value is integer-classed and a
    // float position makes `crossFile` true: this is the widening arm.
    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    const slot: u32 = 3;
    const stale: u5 = 11;
    const off: u16 = 16;
    try temps.put(alloc, slot, stale);
    try compiler.gp_stack_locals.put(alloc, slot, off);

    // The stale state: the register is claimed and owned by a DIFFERENT id, so
    // the name this local holds stands for a claim that is gone.
    compiler.used_regs[stale] = true;
    compiler.gp_reg_owner[stale] = 7;

    const d = try compiler.evalDnirValueFp(&temps, .{ .local = slot });
    try std.testing.expectEqual(@as(u5, Arm64Compiler.fp_value_reg_base), d);

    // Two instructions: the load from the frame home, then the conversion out
    // of the register that load filled. The stale register is not the source.
    try std.testing.expectEqual(@as(usize, 8), compiler.code.items.len);
    const fresh: u5 = 9;
    const ldr_word: u32 = 0xf94003e0 | ((@as(u32, off) / 8) << 10) | @as(u32, fresh);
    try std.testing.expectEqual(
        ldr_word,
        std.mem.readInt(u32, compiler.code.items[0..4], .little),
    );
    const scvtf_word: u32 = 0x9e620000 | (@as(u32, fresh) << 5) | @as(u32, d);
    try std.testing.expectEqual(
        scvtf_word,
        std.mem.readInt(u32, compiler.code.items[4..8], .little),
    );

    // WRONG ERROR: A LIVE NAME IS STILL THE ANSWER, AND NO STORAGE IS INVENTED
    // FOR IT. The term is the owner record, not the presence of a frame home:
    // an owned name converts out of its own register with the conversion alone,
    // and the home is not read.
    const live_slot: u32 = 4;
    const live_reg: u5 = 12;
    try temps.put(alloc, live_slot, live_reg);
    try compiler.gp_stack_locals.put(alloc, live_slot, 24);
    compiler.used_regs[live_reg] = true;
    compiler.gp_reg_owner[live_reg] = live_slot;

    const at_live = compiler.code.items.len;
    const live_d = try compiler.evalDnirValueFp(&temps, .{ .local = live_slot });
    try std.testing.expectEqual(at_live + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        0x9e620000 | (@as(u32, live_reg) << 5) | @as(u32, live_d),
        std.mem.readInt(u32, compiler.code.items[at_live..][0..4], .little),
    );
    try std.testing.expectEqual(@as(?u5, live_reg), temps.get(live_slot));

    // FALSE ACCEPT: WITH NO REGISTER TO LOAD INTO, THE WIDENING REFUSES. The
    // frame home is where the value is, so reaching it costs a register; when
    // the pool cannot pay, the answer is the same `RegisterExhausted` bail
    // `allocRegExcluding` gives outside gate transport, never the stale
    // register as a fallback.
    var full: u5 = 0;
    while (full < 29) : (full += 1) compiler.used_regs[full] = true;
    const at_full = compiler.code.items.len;
    try std.testing.expectError(
        error.RegisterExhausted,
        compiler.evalDnirValueFp(&temps, .{ .local = slot }),
    );
    try std.testing.expectEqual(at_full, compiler.code.items.len);
}

// A STALE NAME IS NOT A PLACE TO STORE INTO (GAP-148).
//
// `evalDnirValue` refuses a `temps` name in x9..x28 that is neither a home nor
// its own id's owner: that is a claim `sweepGpLive` or `emitPopVarargs` gave
// back under a name nobody rewrote, and the pool has since handed the register
// to somebody else. The read side falls through to the frame home for it. The
// `store_local` arm read the same map raw, so it moved this local's new value
// into the stranger's register and then `markGpHome` claimed that register as
// this local's home for the rest of the function — which also sets the very
// flag that stops the read side refusing, so the stranger's own name starts
// answering with the local's value.
//
// Built directly rather than through a source program for the same reason as
// every test this gap has recorded: the state is one the allocator passes
// through between a release and a store, not one a fixture names.
test "a store does not home a local in a register another value owns" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // The value being stored, in ordinary scratch.
    const src_temp: u32 = 7;
    const src_reg: u5 = 9;
    compiler.claimReg(src_reg);
    try temps.put(alloc, src_temp, src_reg);

    // The stale state: this local's name survives in `temps`, but the register
    // is claimed and owned by a DIFFERENT id, so the claim the name stood for
    // is gone and the register belongs to that id now.
    const slot: u32 = 3;
    const stranger_reg: u5 = 11;
    const stranger_id: u32 = 41;
    try temps.put(alloc, slot, stranger_reg);
    compiler.claimReg(stranger_reg);
    compiler.gp_reg_owner[stranger_reg] = stranger_id;

    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = slot,
        .lhs = .{ .temp = src_temp },
        .ty = .i64,
    }, &branch_patches, null, 0);

    // THE STORE GOES TO A HOME OF ITS OWN. A leaf's `allocHomeReg` falls
    // through to the ordinary pool, whose first free register is x10 — x9 holds
    // the value and x11 is the stranger's.
    const home: u5 = 10;
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        0xaa0003e0 | (@as(u32, src_reg) << 16) | @as(u32, home),
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );
    try std.testing.expect(compiler.gp_home_regs[home]);
    try std.testing.expectEqual(@as(?u5, home), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, home), temps.get(slot));

    // AND THE STRANGER KEEPS EVERYTHING. Its value was not written over, its
    // claim stands, and it did not become this local's home — the flag that
    // would have made `staleGpName` serve its name to this local's readers.
    try std.testing.expectEqual(@as(?u32, stranger_id), compiler.gp_reg_owner[stranger_reg]);
    try std.testing.expect(compiler.used_regs[stranger_reg]);
    try std.testing.expect(!compiler.gp_home_regs[stranger_reg]);

    // WRONG ERROR: A LIVE NAME IS STILL THE PLACE, AND NO SECOND HOME IS TAKEN
    // FOR IT. The term is the owner record and not the absence of a home flag:
    // a name its own id owns is stored into where it stands, with one move and
    // no allocation.
    const own_slot: u32 = 4;
    const own_reg: u5 = 12;
    const src2_temp: u32 = 8;
    const src2_reg: u5 = 14;
    try temps.put(alloc, own_slot, own_reg);
    compiler.claimReg(own_reg);
    compiler.gp_reg_owner[own_reg] = own_slot;
    compiler.claimReg(src2_reg);
    try temps.put(alloc, src2_temp, src2_reg);

    const at_own = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = own_slot,
        .lhs = .{ .temp = src2_temp },
        .ty = .i64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(at_own + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        0xaa0003e0 | (@as(u32, src2_reg) << 16) | @as(u32, own_reg),
        std.mem.readInt(u32, compiler.code.items[at_own..][0..4], .little),
    );
    try std.testing.expectEqual(@as(?u5, own_reg), temps.get(own_slot));
    try std.testing.expectEqual(@as(?u5, own_reg), pinned.get(own_slot));
    // x9 was released by the first store and is what `allocHomeReg` would have
    // answered; it is still free, so this store took no register at all.
    try std.testing.expect(!compiler.used_regs[src_reg]);

    // FALSE ACCEPT: WITH NO REGISTER TO HOME IN, THE STORE REFUSES. Reaching a
    // location of its own costs a register, and when the pool cannot pay the
    // answer is the `RegisterExhausted` bail `allocRegExcluding` already gives
    // outside gate transport — never the stranger's register as a fallback.
    const starved_slot: u32 = 5;
    try temps.put(alloc, starved_slot, stranger_reg);
    var full: u5 = 0;
    while (full < 29) : (full += 1) compiler.claimReg(full);
    const at_full = compiler.code.items.len;
    try std.testing.expectError(error.RegisterExhausted, compiler.compileDnirInstr(
        &temps,
        &pinned,
        .{ .op = .store_local, .result = starved_slot, .lhs = .{ .temp = src2_temp }, .ty = .i64 },
        &branch_patches,
        null,
        0,
    ));
    try std.testing.expectEqual(at_full, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u32, stranger_id), compiler.gp_reg_owner[stranger_reg]);
    try std.testing.expectEqual(@as(?u5, null), pinned.get(starved_slot));
}

// A LOCAL'S FIRST HOME IS NOT ANOTHER LOCAL'S HOME (GAP-148).
//
// The f64 `store_local` arm took `pinned.get(slot) orelse temps.get(slot)
// orelse d`, and `d` is whatever register `evalDnirValueFp` answered with. For
// a temp that is right: the temp dies into the local and the store pays no
// move. For a `.local` it is another local's HOME, and the integer path next
// to it adopts `val_reg` never — its fresh-home arms take `allocHomeReg` and
// move. So `b: f64 = a` homed `b` in `a`'s register and emitted nothing, and
// the two locals were one register for the rest of the function: the next
// store to either wrote both.
//
// Built directly rather than through a source program for the same reason as
// every test this gap has recorded: the state is one the allocator passes
// through, not one a fixture names.
test "a first store does not home a local in another local's home" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // `a`, exactly as a parameter or an earlier store leaves it: FP-classed,
    // named in both maps, and flagged as a home.
    const a: u32 = 3;
    const a_home: u5 = Arm64Compiler.fp_value_reg_base;
    try compiler.markFpTemp(a);
    try temps.put(alloc, a, a_home);
    try pinned.put(alloc, a, a_home);
    compiler.markFpHome(a_home);

    // `b: f64 = a` — `b` has no location yet, so this is the `orelse` arm.
    const b: u32 = 4;
    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = b,
        .lhs = .{ .local = a },
        .ty = .f64,
    }, &branch_patches, null, 0);

    // `b` GETS A HOME OF ITS OWN AND THE VALUE IS MOVED INTO IT. d17 is the
    // first free register in the value band; d16 is `a`'s.
    const b_home: u5 = Arm64Compiler.fp_value_reg_base + 1;
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        0x1e604000 | (@as(u32, a_home) << 5) | @as(u32, b_home),
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );
    try std.testing.expectEqual(@as(?u5, b_home), temps.get(b));
    try std.testing.expectEqual(@as(?u5, b_home), pinned.get(b));
    try std.testing.expect(compiler.fp_home_regs[b_home]);
    try std.testing.expect(compiler.fp_temps.contains(b));

    // AND `a` KEEPS ITS OWN. Its name, its pin and its home flag all stand, so
    // a later store to `b` cannot reach it.
    try std.testing.expectEqual(@as(?u5, a_home), temps.get(a));
    try std.testing.expectEqual(@as(?u5, a_home), pinned.get(a));
    try std.testing.expect(compiler.fp_home_regs[a_home]);

    // WRONG ERROR: A TEMP'S REGISTER IS STILL ADOPTED, WITH NO MOVE AND NO
    // SECOND REGISTER. The term is `fp_home_regs`, not "the source belongs to
    // somebody": a temp dying into a local is the case this arm is written for
    // and `x2 = x * y` must keep paying nothing for it.
    const t: u32 = 7;
    const t_reg: u5 = Arm64Compiler.fp_value_reg_base + 2;
    const c: u32 = 5;
    try compiler.markFpTemp(t);
    try temps.put(alloc, t, t_reg);
    compiler.used_fp_regs[t_reg] = true;
    compiler.fp_reg_owner[t_reg] = t;

    const at_temp = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = c,
        .lhs = .{ .temp = t },
        .ty = .f64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(at_temp, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, t_reg), temps.get(c));
    try std.testing.expect(compiler.fp_home_regs[t_reg]);
    try std.testing.expectEqual(@as(?u32, null), compiler.fp_reg_owner[t_reg]);

    // FALSE ACCEPT: WITH NO REGISTER TO HOME IN, THE STORE REFUSES. Taking a
    // home of its own costs a register, and when the value band cannot pay the
    // answer is the `RegisterExhausted` bail `allocFpReg` already gives — never
    // the source local's home as a fallback.
    const starved: u32 = 6;
    var full: u5 = Arm64Compiler.fp_value_reg_base;
    while (full < Arm64Compiler.fp_value_reg_base + Arm64Compiler.fp_value_reg_count) : (full += 1) {
        compiler.used_fp_regs[full] = true;
    }
    const at_full = compiler.code.items.len;
    try std.testing.expectError(error.RegisterExhausted, compiler.compileDnirInstr(
        &temps,
        &pinned,
        .{ .op = .store_local, .result = starved, .lhs = .{ .local = a }, .ty = .f64 },
        &branch_patches,
        null,
        0,
    ));
    try std.testing.expectEqual(at_full, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, null), temps.get(starved));
    try std.testing.expectEqual(@as(?u5, null), pinned.get(starved));
    try std.testing.expectEqual(@as(?u5, a_home), temps.get(a));
    try std.testing.expect(compiler.fp_home_regs[a_home]);
}

test "a stale destination name is not a home" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const base = Arm64Compiler.fp_value_reg_base;
    const h: u5 = base;
    const h2: u5 = base + 1;
    const t2: u32 = 5;
    const u: u32 = 6;
    const s: u32 = 7;
    try compiler.markFpTemp(t2);
    try temps.put(alloc, t2, h);
    compiler.fp_reg_owner[h] = t2;
    compiler.used_fp_regs[h] = true;
    try compiler.markFpTemp(u);
    try temps.put(alloc, u, h2);
    compiler.fp_reg_owner[h2] = u;
    compiler.used_fp_regs[h2] = true;
    try compiler.markFpTemp(s);
    try temps.put(alloc, s, h);

    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = s,
        .lhs = .{ .temp = u },
        .ty = .f64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(before, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, h2), temps.get(s));
    try std.testing.expectEqual(@as(?u5, h2), pinned.get(s));
    try std.testing.expect(compiler.fp_home_regs[h2]);
    try std.testing.expectEqual(@as(?u32, null), compiler.fp_reg_owner[h2]);
    try std.testing.expectEqual(@as(?u5, h), temps.get(t2));
    try std.testing.expectEqual(@as(?u32, t2), compiler.fp_reg_owner[h]);
    try std.testing.expect(compiler.used_fp_regs[h]);
    try std.testing.expect(!compiler.fp_home_regs[h]);

    const h3: u5 = base + 2;
    const d3: u5 = base + 3;
    const a3: u32 = 11;
    const v3: u32 = 12;
    const s3: u32 = 13;
    try compiler.markFpTemp(a3);
    try temps.put(alloc, a3, h3);
    try pinned.put(alloc, a3, h3);
    compiler.markFpHome(h3);
    try compiler.markFpTemp(v3);
    try temps.put(alloc, v3, d3);
    compiler.fp_reg_owner[d3] = v3;
    compiler.used_fp_regs[d3] = true;
    try compiler.markFpTemp(s3);
    try temps.put(alloc, s3, h3);

    const before3 = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = s3,
        .lhs = .{ .temp = v3 },
        .ty = .f64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(before3, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, d3), temps.get(s3));
    try std.testing.expectEqual(@as(?u5, d3), pinned.get(s3));
    try std.testing.expect(compiler.fp_home_regs[d3]);
    try std.testing.expectEqual(@as(?u32, null), compiler.fp_reg_owner[d3]);
    try std.testing.expectEqual(@as(?u5, h3), temps.get(a3));
    try std.testing.expectEqual(@as(?u5, h3), pinned.get(a3));
    try std.testing.expect(compiler.fp_home_regs[h3]);

    const a: u32 = 10;
    const w: u32 = 9;
    const t2b: u32 = 14;
    const ha: u5 = base + 4;
    const ht: u5 = base + 5;
    try compiler.markFpTemp(a);
    try temps.put(alloc, a, ha);
    try pinned.put(alloc, a, ha);
    compiler.markFpHome(ha);
    try compiler.markFpTemp(t2b);
    try temps.put(alloc, t2b, ht);
    compiler.fp_reg_owner[ht] = t2b;
    compiler.used_fp_regs[ht] = true;
    try compiler.markFpTemp(w);
    try temps.put(alloc, w, ht);
    var full: u5 = base;
    while (full < base + Arm64Compiler.fp_value_reg_count) : (full += 1) {
        compiler.used_fp_regs[full] = true;
    }
    const at_full = compiler.code.items.len;
    try std.testing.expectError(error.RegisterExhausted, compiler.compileDnirInstr(
        &temps,
        &pinned,
        .{ .op = .store_local, .result = w, .lhs = .{ .local = a }, .ty = .f64 },
        &branch_patches,
        null,
        0,
    ));
    try std.testing.expectEqual(at_full, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, ht), temps.get(w));
    try std.testing.expect(!compiler.fp_home_regs[ht]);
    try std.testing.expectEqual(@as(?u32, t2b), compiler.fp_reg_owner[ht]);
}

// A LOCAL'S HOME IS A REGISTER THE FUNCTION PRESERVES (GAP-148).
//
// `emitSaveCallerRegs` walks the FP file from `fp_value_reg_base`, so d0..d7
// are preserved by nothing. A call result is parked in d0 by both call arms —
// unconditionally when `ins.application` is absent — and `orelse d` then homed
// the local THERE: no move, no home flag, and the next `bl` overwrote it.
//
// Built directly rather than through a source program for the same reason as
// every test this gap has recorded: the state is one the allocator passes
// through, not one a fixture names.
test "a first store does not home a local in an ABI register no call preserves" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    // A call result exactly as the two call arms leave one: FP-classed, named
    // at d0, that register claimed, and no home flag anywhere.
    const parked: u32 = 3;
    try compiler.markFpTemp(parked);
    try temps.put(alloc, parked, 0);
    compiler.used_fp_regs[0] = true;

    const b: u32 = 4;
    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = b,
        .lhs = .{ .temp = parked },
        .ty = .f64,
    }, &branch_patches, null, 0);

    // `b` GETS A VALUE-BAND HOME AND THE RESULT IS MOVED INTO IT.
    const b_home: u5 = Arm64Compiler.fp_value_reg_base;
    try std.testing.expectEqual(before + 4, compiler.code.items.len);
    try std.testing.expectEqual(
        0x1e604000 | @as(u32, b_home),
        std.mem.readInt(u32, compiler.code.items[before..][0..4], .little),
    );
    try std.testing.expectEqual(@as(?u5, b_home), temps.get(b));
    try std.testing.expectEqual(@as(?u5, b_home), pinned.get(b));
    try std.testing.expect(compiler.fp_home_regs[b_home]);
    try std.testing.expect(compiler.fp_temps.contains(b));

    // d0 IS NOT A HOME. `markFpHome` has no band guard, so a flag set here
    // would make d0 answer as stable storage for the rest of the function.
    try std.testing.expect(!compiler.fp_home_regs[0]);

    // WRONG ERROR: A TEMP ALREADY IN THE VALUE BAND IS STILL ADOPTED, WITH NO
    // MOVE AND NO SECOND REGISTER. The term is the band, not "a store always
    // takes a home of its own": a temp dying into a local is the case this arm
    // is written for and `x2 = x * y` must keep paying nothing for it.
    const t: u32 = 7;
    const t_reg: u5 = Arm64Compiler.fp_value_reg_base + 1;
    const c: u32 = 5;
    try compiler.markFpTemp(t);
    try temps.put(alloc, t, t_reg);
    compiler.used_fp_regs[t_reg] = true;
    compiler.fp_reg_owner[t_reg] = t;

    const at_temp = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .store_local,
        .result = c,
        .lhs = .{ .temp = t },
        .ty = .f64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(at_temp, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, t_reg), temps.get(c));
    try std.testing.expect(compiler.fp_home_regs[t_reg]);
    try std.testing.expectEqual(@as(?u32, null), compiler.fp_reg_owner[t_reg]);

    // FALSE ACCEPT: WITH NO REGISTER TO HOME IN, THE STORE REFUSES. A home of
    // its own costs a register, and when the value band cannot pay the answer
    // is the `RegisterExhausted` bail `allocFpReg` already gives — never the
    // unpreserved ABI register as a fallback.
    const starved: u32 = 6;
    var full: u5 = Arm64Compiler.fp_value_reg_base;
    while (full < Arm64Compiler.fp_value_reg_base + Arm64Compiler.fp_value_reg_count) : (full += 1) {
        compiler.used_fp_regs[full] = true;
    }
    const at_full = compiler.code.items.len;
    try std.testing.expectError(error.RegisterExhausted, compiler.compileDnirInstr(
        &temps,
        &pinned,
        .{ .op = .store_local, .result = starved, .lhs = .{ .temp = parked }, .ty = .f64 },
        &branch_patches,
        null,
        0,
    ));
    try std.testing.expectEqual(at_full, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u5, null), temps.get(starved));
    try std.testing.expectEqual(@as(?u5, null), pinned.get(starved));
    try std.testing.expect(!compiler.fp_home_regs[0]);
}

// A CALL RESULT LEFT IN d0 IS DESTROYED BY THE NEXT CALL (GAP-148).
//
// The `.f64` call arm copied its result out of d0 only when
// `ins.application != null`. The calls lowered without an application id are
// exactly `native_ir.isBootstrapForeignCall` — `sqrt`, `sin`, `cos`, `fabs`,
// `floor`, `ceil` — so `a:sqrt() + b:sqrt()` named the first result at d0, the
// second call's own `fmov d0, <arg>` wrote over it, and the `fadd` read d0
// twice. `fp_abi_passthrough` is the record that says when d0 may be kept.
test "a bootstrap f64 call result leaves d0 before the next call overwrites it" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch_patches: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch_patches.deinit(alloc);

    const first: u32 = 3;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .call_extern,
        .result = first,
        .callee = "sqrt",
        .lhs = .{ .f64 = 2.0 },
        .ty = .f64,
    }, &branch_patches, null, 0);

    // THE RESULT IS IN THE VALUE BAND, AND THE LAST INSTRUCTION IS THE MOVE
    // THAT PUT IT THERE.
    const home: u5 = Arm64Compiler.fp_value_reg_base;
    try std.testing.expectEqual(@as(?u5, home), temps.get(first));
    try std.testing.expect(!compiler.used_fp_regs[0]);
    const tail = compiler.code.items.len - 4;
    try std.testing.expectEqual(
        0x1e604000 | @as(u32, home),
        std.mem.readInt(u32, compiler.code.items[tail..][0..4], .little),
    );

    const second: u32 = 4;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .call_extern,
        .result = second,
        .callee = "sqrt",
        .lhs = .{ .f64 = 3.0 },
        .ty = .f64,
    }, &branch_patches, null, 0);

    // TWO LIVE RESULTS, TWO REGISTERS. The defect names both at d0.
    try std.testing.expect(temps.get(first).? != temps.get(second).?);
    try std.testing.expectEqual(@as(?u5, home), temps.get(first));

    // WRONG ERROR: A GENUINE ABI PASSTHROUGH STILL KEEPS d0 AND TAKES NO
    // REGISTER. The term is `fp_abi_passthrough`, not "a call always copies".
    const through: u32 = 5;
    try compiler.fp_abi_passthrough.put(alloc, through, {});
    const before_through = compiler.code.items.len;
    try compiler.compileDnirInstr(&temps, &pinned, .{
        .op = .call_extern,
        .result = through,
        .callee = "sqrt",
        .lhs = .{ .f64 = 4.0 },
        .ty = .f64,
    }, &branch_patches, null, 0);
    try std.testing.expectEqual(@as(?u5, 0), temps.get(through));
    try std.testing.expect(compiler.used_fp_regs[0]);
    try std.testing.expect(!compiler.used_fp_regs[Arm64Compiler.fp_value_reg_base + 2]);
    try std.testing.expect(compiler.code.items.len > before_through);

    // FALSE ACCEPT: A HOME OF ITS OWN COSTS A REGISTER, AND THE ANSWER WHEN THE
    // BAND CANNOT PAY IS THE REFUSAL `allocFpReg` ALREADY GIVES — NEVER d0 AS A
    // FALLBACK.
    const starved: u32 = 6;
    var full: u5 = Arm64Compiler.fp_value_reg_base;
    while (full < Arm64Compiler.fp_value_reg_base + Arm64Compiler.fp_value_reg_count) : (full += 1) {
        compiler.used_fp_regs[full] = true;
    }
    try std.testing.expectError(error.RegisterExhausted, compiler.compileDnirInstr(
        &temps,
        &pinned,
        .{ .op = .call_extern, .result = starved, .callee = "sqrt", .ty = .f64 },
        &branch_patches,
        null,
        0,
    ));
    try std.testing.expectEqual(@as(?u5, null), temps.get(starved));
}

// A STALE NAME IS NOT A VALUE — THE TEMP SIDE (GAP-148).
test "a stale temp name is not a register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    // A name `sweepGpLive` left behind and `allocReg` has since re-let: the
    // register carries `stranger`, and `temps` still calls it `stale_id`.
    const stale_id: u32 = 4;
    const stranger: u32 = 5;
    const named: u5 = 9;
    try temps.put(alloc, stale_id, named);
    compiler.gp_reg_owner[named] = stranger;
    compiler.used_regs[named] = true;

    const before = compiler.code.items.len;
    try std.testing.expectError(
        error.UndefinedName,
        compiler.evalDnirValue(&temps, .{ .temp = stale_id }),
    );
    try std.testing.expectEqualStrings(
        "temp 4 has no register",
        diagnostic.note_buffer[0..diagnostic.note_len],
    );
    try std.testing.expectEqual(before, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u32, stranger), compiler.gp_reg_owner[named]);
    try std.testing.expect(compiler.used_regs[named]);
    try std.testing.expectEqual(@as(?u5, named), temps.get(stale_id));

    // WRONG-ERROR CONTROL: the term is `gp_reg_owner` identity, not "a temp
    // read refuses".
    const own_id: u32 = 6;
    const own_reg: u5 = 10;
    try temps.put(alloc, own_id, own_reg);
    compiler.gp_reg_owner[own_reg] = own_id;
    compiler.used_regs[own_reg] = true;
    try std.testing.expectEqual(
        own_reg,
        try compiler.evalDnirValue(&temps, .{ .temp = own_id }),
    );

    // FALSE-ACCEPT CONTROL: an ABSENT owner is ordinary scratch for a temp, not
    // a stale name. `staleGpName` reads it as stale for the `.local` arm, which
    // answers with the frame home a temp does not have; refusing it here would
    // refuse every scratch value the emitters hold through `claimReg` alone.
    const scratch_id: u32 = 9;
    const scratch_reg: u5 = 12;
    try temps.put(alloc, scratch_id, scratch_reg);
    compiler.claimReg(scratch_reg);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[scratch_reg]);
    try std.testing.expectEqual(
        scratch_reg,
        try compiler.evalDnirValue(&temps, .{ .temp = scratch_id }),
    );

    // FALSE-ACCEPT CONTROL: the BAND is the other half of the term, and the ABI
    // bank carries owner records too — `spillReg` preserves `gp_reg_owner[0]`
    // across a spill of x0. A foreign owner there is `preserveArgReg`'s to
    // answer, not this read's, so the same two-id state that refuses in the
    // band is served below x9.
    const abi_id: u32 = 7;
    const abi_reg: u5 = 0;
    try temps.put(alloc, abi_id, abi_reg);
    compiler.gp_reg_owner[abi_reg] = stranger;
    try std.testing.expectEqual(
        abi_reg,
        try compiler.evalDnirValue(&temps, .{ .temp = abi_id }),
    );
}

// A STALE NAME IS NOT A VALUE — THE FLOAT FILE (GAP-148).
test "a float name another value owns is not a register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    // A name `sweepFpLive` left behind and `allocFpReg` has since re-let: the
    // register carries `stranger`, and `temps` still calls it `stale_id`.
    const stale_id: u32 = 4;
    const stranger: u32 = 5;
    const named: u5 = Arm64Compiler.fp_value_reg_base;
    try temps.put(alloc, stale_id, named);
    try compiler.markFpTemp(stale_id);
    compiler.fp_reg_owner[named] = stranger;
    compiler.used_fp_regs[named] = true;

    const before = compiler.code.items.len;
    try std.testing.expectError(
        error.UndefinedName,
        compiler.evalDnirValueFp(&temps, .{ .temp = stale_id }),
    );
    try std.testing.expectEqualStrings(
        "temp 4 has no register",
        diagnostic.note_buffer[0..diagnostic.note_len],
    );
    try std.testing.expectEqual(before, compiler.code.items.len);
    try std.testing.expectEqual(@as(?u32, stranger), compiler.fp_reg_owner[named]);
    try std.testing.expect(compiler.used_fp_regs[named]);
    try std.testing.expectEqual(@as(?u5, named), temps.get(stale_id));

    // The `.local` arm reads the same map and has the same absent fallback.
    const stale_slot: u32 = 8;
    const slot_reg: u5 = Arm64Compiler.fp_value_reg_base + 1;
    try temps.put(alloc, stale_slot, slot_reg);
    try compiler.markFpTemp(stale_slot);
    compiler.fp_reg_owner[slot_reg] = stranger;
    compiler.used_fp_regs[slot_reg] = true;
    try std.testing.expectError(
        error.UndefinedName,
        compiler.evalDnirValueFp(&temps, .{ .local = stale_slot }),
    );
    try std.testing.expectEqualStrings(
        "local 8 has no register",
        diagnostic.note_buffer[0..diagnostic.note_len],
    );

    // WRONG-ERROR CONTROL: the term is `fp_reg_owner` identity, not "a float
    // read refuses".
    const own_id: u32 = 6;
    const own_reg: u5 = Arm64Compiler.fp_value_reg_base + 2;
    try temps.put(alloc, own_id, own_reg);
    try compiler.markFpTemp(own_id);
    compiler.fp_reg_owner[own_reg] = own_id;
    compiler.used_fp_regs[own_reg] = true;
    try std.testing.expectEqual(
        own_reg,
        try compiler.evalDnirValueFp(&temps, .{ .temp = own_id }),
    );

    // FALSE-ACCEPT CONTROL: an ABSENT owner is ordinary scratch. `releaseFpReg`
    // returns above any owned register, and a leaf parameter's home is d0..d7,
    // which no owner record ever names.
    const scratch_id: u32 = 9;
    const scratch_reg: u5 = Arm64Compiler.fp_value_reg_base + 3;
    try temps.put(alloc, scratch_id, scratch_reg);
    try compiler.markFpTemp(scratch_id);
    compiler.used_fp_regs[scratch_reg] = true;
    try std.testing.expectEqual(@as(?u32, null), compiler.fp_reg_owner[scratch_reg]);
    try std.testing.expectEqual(
        scratch_reg,
        try compiler.evalDnirValueFp(&temps, .{ .temp = scratch_id }),
    );
}

