// GAP-148. THE THIRD PATH THAT TAKES A REGISTER AWAY FROM THE MAP NAMING IT.
//
// `ensureRegLiveRemap` and `reclaimSpilledReg` were each taught `evalPinNames`
// for the same register this test builds: the LEAF parameter
// `compileDnirFunction` keeps in its incoming x0..x7 register, pinned and never
// a home. `releaseReg` is the third, and it was never asked — instead about
// thirty of its call sites ask `regIsPinned` themselves and the rest do not,
// so `.br`'s `releaseReg(cond)` on `if c then ... else ...` gave back the very
// claim `claimReg(arg_reg)` exists to hold.
//
// What that claim buys is stated at the `pinned.put` site: `allocRegExcluding`
// does not read `pinned`, so with x9..x28 busy it falls to x0..x7 and asks only
// `used_regs`. The measurement there is a loop that ran to signed overflow and
// answered independently of its argument. This test is that allocator scan,
// run against a parameter a release has just been called on.
//
// Built directly rather than through a source program, like the reclaim,
// reload, remap, release, home, store and argument-preserve tests around it:
// the state is one the allocator passes through between a release and the next
// allocation, not one a fixture names.
test "a release does not give back the claim a pin holds" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    // The leaf-parameter arm's state: the incoming register claimed, both maps
    // naming it, no home flag, no owner record. `gp_home_regs` is empty below
    // x9 and `gp_reg_owner` is never written there, so neither term this
    // function already asks can see this register.
    const arg_reg: u5 = 0;
    const slot: u32 = 0;
    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    try temps.put(alloc, slot, arg_reg);
    try pinned.put(alloc, slot, arg_reg);
    compiler.eval_pinned = &pinned;
    compiler.eval_temps = &temps;
    compiler.claimReg(arg_reg);
    try std.testing.expect(!compiler.gp_home_regs[arg_reg]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[arg_reg]);

    // `.br` reads the condition out of the parameter and releases what it read.
    const before = compiler.code.items.len;
    compiler.releaseReg(try compiler.evalDnirValue(&temps, .{ .local = slot }));
    try std.testing.expectEqual(before, compiler.code.items.len);
    try std.testing.expect(compiler.used_regs[arg_reg]);

    // THE ALLOCATOR IS THE OBSERVER. Fill x9..x28 so the second free scan
    // reaches the ABI file, then ask for a register: it must not be the one the
    // pin names, and the pin and the name must still agree with the read.
    var busy: u5 = 9;
    while (busy < 29) : (busy += 1) {
        if (busy == Arm64Compiler.platform_reserved_reg) continue;
        compiler.claimReg(busy);
    }
    const scratch = try compiler.allocReg();
    try std.testing.expect(scratch != arg_reg);
    try std.testing.expectEqual(@as(?u5, arg_reg), pinned.get(slot));
    try std.testing.expectEqual(@as(?u5, arg_reg), temps.get(slot));
    try std.testing.expectEqual(
        arg_reg,
        try compiler.evalDnirValue(&temps, .{ .local = slot }),
    );

    // THE TERM IS THE MAP, NOT THE BAND. An ordinary scratch register in the
    // same file, named by nothing, is still released — releasing it is what
    // keeps the pool from draining, and a term spelled `reg < 9` would hold it.
    const plain: u5 = 6;
    compiler.claimReg(plain);
    compiler.releaseReg(plain);
    try std.testing.expect(!compiler.used_regs[plain]);

    // AND THE TERM IS READ, NOT ASSUMED. With no pin map there is no pin —
    // `evalPinNames` is false outside a function body — so the same register
    // releases, which is what every direct-construction caller sees.
    compiler.claimReg(arg_reg);
    compiler.eval_pinned = null;
    compiler.releaseReg(arg_reg);
    try std.testing.expect(!compiler.used_regs[arg_reg]);

    // A PINNED REGISTER'S SPILL ENTRY IS ITS VALUE'S LAST LOCATION. The return
    // stands above the removal, so the entry `ensureRegLiveRemap` reloads from
    // survives a release and its slot is not handed to the next spill.
    compiler.eval_pinned = &pinned;
    compiler.stack_frame_bytes = 64;
    const off: u16 = 8;
    try compiler.spilled_regs.put(alloc, arg_reg, off);
    compiler.used_regs[arg_reg] = false;
    compiler.releaseReg(arg_reg);
    try std.testing.expect(compiler.spilled_regs.contains(arg_reg));
    try std.testing.expectEqual(@as(usize, 0), compiler.free_spill_slots.items.len);
}

/// The machine text one program emits, and the `.mod` instruction's divisor
/// fact — both read off ONE compile so the two cannot describe different runs.
fn flooredDivisorProbe(
    alloc: std.mem.Allocator,
    source: []const u8,
    file: []const u8,
    strip_derivations: bool,
) !struct { text: usize, divisor: dnir.DivisorSign } {
    var diagnostic: Diagnostic = .{};
    var lexer = Lexer.init(source, file);
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    const module = try alloc.create(ast.Module);
    module.* = try parser.parse_module();
    var checked = Sema.init(alloc);
    checked.idol_mode = true;
    try checked.check_module(module);

    const graph = try alloc.create(semantic_graph.SemanticGraph);
    graph.* = semantic_graph.SemanticGraph.init(alloc);
    try liftCheckedTestGraph(module, &checked, graph);
    // THE CORRUPTION ARM. Nothing else about the program changes: same source,
    // same graph, same call site, same arguments — only the retained
    // derivations are gone.
    if (strip_derivations) graph.results.clearRetainingCapacity();

    var divisor: dnir.DivisorSign = .unknown;
    const lowered = try dnir_lower.lowerModuleWithGraph(alloc, module, graph);
    for (lowered.functions) |function| {
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.op != .binop) continue;
                if (instruction.binop != .mod) continue;
                divisor = instruction.divisor;
            }
        }
    }

    var output = try emitArm64ModuleWithGraph(alloc, module, null, graph, &diagnostic);
    defer output.deinit(alloc);
    return .{ .text = output.text.len, .divisor = divisor };
}

test "native backend: the floored correction spends the retained derivation of its divisor" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // `n % sum(d, 1)`. The divisor is an APPLICATION, so before a result
    // relation retained anything about its own result this took the general
    // eight-instruction floored correction that `n % (d + 1)` does not.
    const proved =
        \\sum: i64 = (a: i64, b: i64)
        \\    a + b
        \\main: i64 = (seed: i64)
        \\    d = seed % 10
        \\    n = seed % 1000
        \\    n % sum(d, 1)
    ;
    // The SAME PROGRAM with the same word over a difference. A difference can
    // be negative, so no width is proved and the general correction stays —
    // which is the discrimination `sum` would otherwise have bought by spelling.
    const spelled =
        \\sum: i64 = (a: i64, b: i64)
        \\    a - b
        \\main: i64 = (seed: i64)
        \\    d = seed % 10
        \\    n = seed % 1000
        \\    n % sum(d, 1)
    ;

    const with = try flooredDivisorProbe(alloc, proved, "proved.id", false);
    const without = try flooredDivisorProbe(alloc, proved, "stripped.id", true);
    const wrong = try flooredDivisorProbe(alloc, spelled, "spelled.id", false);

    // THE FACT REACHES THE INSTRUCTION, as the width it was derived at.
    try std.testing.expectEqual(dnir.DivisorSign{ .derived = 5 }, with.divisor);
    try std.testing.expect(with.divisor.proved());
    // REMOVING IT PREVENTS THE UNJUSTIFIED USE, and the WORD does not restore it.
    try std.testing.expectEqual(dnir.DivisorSign.unknown, without.divisor);
    try std.testing.expectEqual(dnir.DivisorSign.unknown, wrong.divisor);

    // AND THE REALIZATION IS DIFFERENT, which is what makes the fact worth
    // retaining rather than worth asserting. The cheap correction is three
    // AArch64 instructions shorter, and the two refusals emit the same text as
    // each other because they are the same program with the same proof missing.
    try std.testing.expect(with.text < without.text);
    try std.testing.expectEqual(without.text, wrong.text);
    try std.testing.expectEqual(@as(usize, 3 * 4), without.text - with.text);
}

test "native backend: the subject-first face of an application spends the same derivation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const subject_first =
        \\sum: i64 = (a: i64, b: i64)
        \\    a + b
        \\main: i64 = (seed: i64)
        \\    d = seed % 10
        \\    n = seed % 1000
        \\    n % d:sum(1)
    ;
    const operand_first =
        \\sum: i64 = (a: i64, b: i64)
        \\    a + b
        \\main: i64 = (seed: i64)
        \\    d = seed % 10
        \\    n = seed % 1000
        \\    n % sum(d, 1)
    ;

    const subject = try flooredDivisorProbe(alloc, subject_first, "subject.id", false);
    const operand = try flooredDivisorProbe(alloc, operand_first, "operand.id", false);
    const stripped = try flooredDivisorProbe(alloc, subject_first, "stripped.id", true);

    try std.testing.expectEqual(dnir.DivisorSign{ .derived = 5 }, subject.divisor);
    try std.testing.expectEqual(operand.divisor, subject.divisor);
    try std.testing.expectEqual(operand.text, subject.text);

    try std.testing.expectEqual(dnir.DivisorSign.unknown, stripped.divisor);
    try std.testing.expectEqual(@as(usize, 3 * 4), stripped.text - subject.text);
}

test "native record cells preserve word storage and independent source values" {
    const alloc = std.testing.allocator;
    var scalar: ScalRecordMap = .empty;
    var floating: F64RecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &floating,
        .scal_records = &scalar,
        .record = &.{.{ .name = "record", .fields = &.{"code"}, .kinds = &.{.i64}, .widths = &.{.u16} }},
    };
    defer compiler.deinit();
    var value: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer value.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch.deinit(alloc);
    try value.put(alloc, 0, 9);
    try value.put(alloc, 1, 10);
    try pinned.put(alloc, 0, 9);
    try pinned.put(alloc, 1, 10);
    compiler.eval_pinned = &pinned;
    compiler.eval_temps = &value;
    compiler.markGpHome(9);
    compiler.markGpHome(10);
    var instruction = dnir.Instr{ .op = .store_index, .record = "record", .field = "code", .ty = .u16, .lhs = .{ .local = 0 }, .rhs = .{ .i64 = 1 }, .third = .{ .local = 1 } };
    try compiler.compileDnirInstr(&value, &pinned, instruction, &branch, null, 0);
    try std.testing.expectEqual(@as(usize, 8), compiler.code.items.len);
    const fit = std.mem.readInt(u32, compiler.code.items[0..4], .little);
    const store = std.mem.readInt(u32, compiler.code.items[4..8], .little);
    try std.testing.expectEqual(@as(u32, 10), (fit >> 5) & 31);
    try std.testing.expect((fit & 31) != 10);
    try std.testing.expectEqual(fit & 31, store & 31);
    try std.testing.expectEqual(@as(u32, 0xf9000000), store & 0xffc00000);
    try std.testing.expectEqual(@as(u32, 9), (store >> 5) & 31);
    try std.testing.expectEqual(@as(?u5, 10), value.get(1));
    try std.testing.expect(compiler.used_regs[10]);
    instruction.op = .load_index;
    instruction.result = 2;
    const before = compiler.code.items.len;
    try compiler.compileDnirInstr(&value, &pinned, instruction, &branch, null, 0);
    try std.testing.expectEqual(before + 8, compiler.code.items.len);
    const load = std.mem.readInt(u32, compiler.code.items[before..][0..4], .little);
    try std.testing.expectEqual(@as(u32, 0xf9400000), load & 0xffc00000);
    try std.testing.expectEqual(@as(u32, 9), (load >> 5) & 31);
    instruction.op = .store_index;
    instruction.record = "";
    instruction.ty = .u8;
    instruction.result = null;
    try compiler.compileDnirInstr(&value, &pinned, instruction, &branch, null, 0);
    const byte = std.mem.readInt(u32, compiler.code.items[compiler.code.items.len - 4 ..][0..4], .little);
    try std.testing.expectEqual(@as(u32, 0x39000000), byte & 0xffc00000);
}

test "native record cells refuse damaged descriptors before emission" {
    const alloc = std.testing.allocator;
    var scalar: ScalRecordMap = .empty;
    var floating: F64RecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &floating,
        .scal_records = &scalar,
        .record = &.{.{ .name = "record", .fields = &.{"code"}, .kinds = &.{.i64}, .widths = &.{.u16} }},
    };
    defer compiler.deinit();
    var value: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer value.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);
    var branch: std.ArrayList(Arm64Compiler.DnirBranchPatch) = .empty;
    defer branch.deinit(alloc);
    const original = dnir.Instr{ .op = .store_index, .record = "record", .field = "code", .ty = .u16, .lhs = .{ .local = 0 }, .rhs = .{ .i64 = 1 }, .third = .{ .local = 1 } };
    for (0..7) |damage| {
        var instruction = original;
        const record = compiler.record;
        defer compiler.record = record;
        switch (damage) {
            0 => instruction.record = "absent",
            1 => instruction.field = "absent",
            2 => instruction.rhs = .{ .i64 = 2 },
            3 => instruction.ty = .i64,
            4 => compiler.record = &.{ record[0], record[0] },
            5 => compiler.record = &.{.{ .name = "record", .fields = &.{ "code", "code" }, .kinds = &.{ .i64, .i64 }, .widths = &.{ .u16, .u16 } }},
            6 => compiler.record = &.{.{ .name = "record", .fields = &.{"code"}, .kinds = &.{} }},
            else => unreachable,
        }
        try std.testing.expectError(error.UnsupportedProgram, compiler.compileDnirInstr(&value, &pinned, instruction, &branch, null, 0));
        try std.testing.expectEqual(@as(usize, 0), compiler.code.items.len);
    }
}

test "staged argument registers return to the pool after the call" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    compiler.used_regs[2] = true;
    compiler.used_regs[3] = true;
    compiler.used_regs[5] = true;
    compiler.markStagedArgReg(2);
    compiler.markStagedArgReg(3);
    compiler.markStagedArgReg(5);

    compiler.releaseStagedArgRegs(compiler.pending_arg_regs, null, &temps, 0);
    try std.testing.expect(!compiler.used_regs[2]);
    try std.testing.expect(!compiler.used_regs[3]);
    try std.testing.expect(!compiler.used_regs[5]);
    try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);

    compiler.used_regs[2] = true;
    compiler.used_regs[3] = true;
    compiler.markStagedArgReg(2);
    compiler.markStagedArgReg(3);
    compiler.releaseStagedArgRegs(compiler.pending_arg_regs, 2, &temps, 0);
    try std.testing.expect(compiler.used_regs[2]);
    try std.testing.expect(!compiler.used_regs[3]);
    try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);
}

test "releaseStagedArgRegs keeps a register a live temps value still claims" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    // x0 holds a value live past the call at index 7 (last use at 9); x1
    // holds a value whose last use was the call itself (dead after it).
    // The save around the call preserved both and the restore put them
    // back, so x0's claim survives the release and x1's does not.
    compiler.used_regs[0] = true;
    compiler.used_regs[1] = true;
    compiler.markStagedArgReg(0);
    compiler.markStagedArgReg(1);
    try temps.put(alloc, 100, 0);
    try temps.put(alloc, 101, 1);
    try compiler.value_free_at.put(alloc, 100, 9);
    try compiler.value_free_at.put(alloc, 101, 7);

    compiler.releaseStagedArgRegs(compiler.pending_arg_regs, null, &temps, 7);

    try std.testing.expect(compiler.used_regs[0]);
    try std.testing.expect(!compiler.used_regs[1]);
    try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);
}

test "preserveArgReg names an owner when the relocation lands below x9" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    try temps.put(alloc, 100, 3);
    try compiler.value_free_at.put(alloc, 100, std.math.maxInt(u32));
    compiler.used_regs[3] = true;

    var r: u5 = 9;
    while (r < 29) : (r += 1) compiler.used_regs[r] = true;
    compiler.used_regs[0] = true;
    compiler.used_regs[1] = true;
    compiler.used_regs[2] = true;
    compiler.used_regs[5] = true;
    compiler.used_regs[6] = true;
    compiler.used_regs[7] = true;

    try compiler.preserveArgReg(&temps, &pinned, 3, 0);
    try std.testing.expectEqual(@as(u5, 4), temps.get(100).?);
    try std.testing.expectEqual(@as(?u32, 100), compiler.gp_reg_owner[4]);
    try std.testing.expect(compiler.used_regs[4]);
}

test "the call result refuses x0..x7 when the owned pool is exhausted" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var r: u5 = 9;
    while (r < 29) : (r += 1) compiler.used_regs[r] = true;

    try std.testing.expectEqual(@as(?u5, null), compiler.resultReg(null));
    try std.testing.expectEqual(@as(u16, 16), compiler.parkReserve(true));
    const save = try compiler.emitSaveCallerRegs();
    try std.testing.expectError(error.RegisterExhausted, compiler.allocRegOutsideSaveSet(save));
}

test "the preserved x0 restore names an owner for its register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);

    try temps.put(alloc, 77, 0);
    compiler.used_regs[0] = true;
    try compiler.value_free_at.put(alloc, 77, std.math.maxInt(u32));

    try compiler.restorePreservedX0(&temps, 77);
    const reg = temps.get(77).?;
    try std.testing.expect(reg >= 9);
    try std.testing.expect(compiler.used_regs[reg]);
    try std.testing.expectEqual(@as(?u32, 77), compiler.gp_reg_owner[reg]);

    try compiler.value_free_at.put(alloc, 77, 0);
    compiler.sweepGpLive(1);
    try std.testing.expect(!compiler.used_regs[reg]);
    try std.testing.expectEqual(@as(?u32, null), compiler.gp_reg_owner[reg]);
}

test "the allocator drains after representative call sequences" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    var iter: u32 = 0;
    while (iter < 25) : (iter += 1) {
        const base: u32 = 1000 + iter * 4;
        var i: u5 = 0;
        while (i < 3) : (i += 1) {
            const r = try compiler.allocReg();
            compiler.gp_reg_owner[r] = base + i;
            try temps.put(alloc, base + i, r);
            try compiler.value_free_at.put(alloc, base + i, std.math.maxInt(u32));
        }
        try compiler.value_free_at.put(alloc, base + 3, std.math.maxInt(u32));

        compiler.used_regs[0] = true;
        compiler.used_regs[1] = true;
        compiler.markStagedArgReg(0);
        compiler.markStagedArgReg(1);

        try temps.put(alloc, base + 3, 0);
        try compiler.restorePreservedX0(&temps, base + 3);

        compiler.releaseStagedArgRegs(compiler.pending_arg_regs, null, &temps, iter);

        var k: u32 = 0;
        while (k < 4) : (k += 1) {
            try compiler.value_free_at.put(alloc, base + k, 0);
        }
        compiler.sweepGpLive(iter + 1);

        var r: u5 = 9;
        while (r < 29) : (r += 1) {
            if (r == Arm64Compiler.platform_reserved_reg) continue;
            try std.testing.expect(!compiler.used_regs[r]);
        }
        var a: u5 = 0;
        while (a < 8) : (a += 1) {
            try std.testing.expect(!compiler.used_regs[a]);
        }
        try std.testing.expectEqual(@as(u8, 0), compiler.pending_arg_regs);
    }
}

test "a vararg relocated out of the ABI range returns its register" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var f64_records: F64RecordMap = .empty;
    var scal_records: ScalRecordMap = .empty;
    var diagnostic: Diagnostic = .{};
    var compiler = Arm64Compiler{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .f64_records = &f64_records,
        .scal_records = &scal_records,
        .entry = null,
    };
    defer compiler.deinit();

    var temps: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer temps.deinit(alloc);
    var pinned: std.AutoHashMapUnmanaged(u32, u5) = .empty;
    defer pinned.deinit(alloc);

    try temps.put(alloc, 1, 0);
    compiler.used_regs[0] = true;
    try compiler.value_free_at.put(alloc, 1, std.math.maxInt(u32));

    compiler.pending_varargs[0] = .{ .operand = .{ .temp = 1 } };
    compiler.pending_vararg_count = 1;
    try compiler.materializePendingVarargs(&temps, &pinned);
    const vbytes = try compiler.emitPushVarargs();
    try compiler.emitPopVarargs(vbytes);

    var r: u5 = 9;
    while (r <= 28) : (r += 1) {
        if (r == 18) continue;
        if (compiler.gp_home_regs[r]) continue;
        try std.testing.expect(!compiler.used_regs[r]);
    }
    try std.testing.expect(compiler.used_regs[0]);
    try std.testing.expectEqual(@as(u5, 0), temps.get(1).?);
}
